INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a1-8x','Audi','A1','8X',2010,2018,'["3-Türer", "5-Türer (Sportback)"]','Kleinwagen',NULL,'Die erste Generation des Audi A1 (8X) zeichnet sich durch eine sportlich-kompakte Karosserie mit scharfen Linien aus. Typisch sind der große Singleframe-Kühlergrill und die markanten, oft optional in Kontrastfarbe lackierten Dachbögen, die dem Fahrzeug eine individuelle Optik verleihen. Die Scheinwerfer sind schmal und ziehen sich weit in die Kotflügel.','Ende 2014 (Modelljahr 2015) erfolgte ein Facelift. Dabei wurden die Front- und Heckschürzen leicht überarbeitet, die Scheinwerfer und Rückleuchten erhielten ein neues Design (optional mit Xenon Plus und LED-Tagfahrlicht vorne, LED-Technik hinten). Zudem wurden neue Außenfarben und Felgendesigns eingeführt.',NULL,NULL,NULL,5,2010,NULL,'2 Jahre (nach Erstzulassung 3 Jahre)',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a1-gb','Audi','A1','GB',2018,NULL,'["Schrägheck"]','Kleinwagen','audi-a1-8x','Der Audi A1 GB ist die zweite Generation des A1 und unterscheidet sich deutlich vom Vorgänger 8X durch eine schärfere, sportlichere Designsprache. Er besitzt einen breiteren, flacheren Singleframe-Grill und drei schmale Lufteinlässe unter der Motorhaubenkante, die an den Ur-Quattro erinnern. Die C-Säule ist markant und stark nach hinten geneigt, oft in Kontrastfarbe zum restlichen Dach. Im Gegensatz zum Vorgänger ist der A1 GB ausschließlich als Fünftürer (Sportback) erhältlich.',NULL,NULL,NULL,NULL,5,2019,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a3-typ-8l','Audi','A3','Typ 8L',1996,2003,'["3-Türer Schrägheck", "5-Türer Schrägheck"]','Kompaktklasse',NULL,'Der Audi A3 Typ 8L ist die erste Generation des A3. Er zeichnet sich durch ein vergleichsweise rundes und kompaktes Design aus, das noch nicht die später typische Singleframe-Kühlergrill-Optik aufweist. Die Frontpartie ist durch separate, eher schmale Scheinwerfer und einen kleineren Kühlergrill oberhalb des Stoßfängers geprägt. Im Vergleich zum Nachfolger (Typ 8P) wirkt der 8L insgesamt weicher in den Linien und hat eine weniger aggressive Frontgestaltung. Die Heckleuchten sind ebenfalls runder und weniger kantig als bei späteren Generationen.','Im Jahr 2000 erfolgte ein Facelift. Erkennbar ist dies an Klarglas-Scheinwerfern (statt geriffelter Gläser), leicht modifizierten Stoßfängern vorne und hinten, sowie neuen Heckleuchten mit klaren Blinkern. Im Innenraum wurden das Lenkrad, das Kombiinstrument und die Mittelkonsole überarbeitet.',NULL,NULL,NULL,4,1998,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a3-typ-8p','Audi','A3','Typ 8P',2003,2012,'["Limousine", "Sportback", "Cabriolet"]','Kompaktklasse','audi-a3-typ-8l','Der Audi A3 Typ 8P zeichnet sich durch eine deutlich schärfere und modernere Linienführung im Vergleich zum Vorgänger (Typ 8L) aus. Die Frontpartie erhielt im Laufe der Bauzeit den markanten Singleframe-Kühlergrill, der anfangs noch geteilt war und später zu einem großen, trapezförmigen Element zusammengeführt wurde. Die Scheinwerfer sind kantiger und dynamischer gestaltet, und die Karosserie wirkt insgesamt sportlicher und gestreckter. Der 8P war zudem der erste A3, der als fünftüriger Sportback mit eigenständiger Heckpartie angeboten wurde.','Das erste größere Facelift erfolgte 2005 mit der Einführung des Singleframe-Kühlergrills für alle Modelle. Ein weiteres, umfassenderes Facelift im Jahr 2008 brachte überarbeitete Scheinwerfer (optional mit LED-Tagfahrlicht), einen modifizierten Singleframe-Kühlergrill mit geänderten Streben, neue Stoßfänger vorne und hinten, sowie geänderte Heckleuchten (teilweise mit LED-Technik). Auch der Innenraum wurde dezent überarbeitet, unter anderem mit neuen Lenkrädern und Bedienelementen.',NULL,NULL,NULL,5,2003,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a3-typ-8v','Audi','A3','Typ 8V',2012,2020,'["3-Türer", "Sportback", "Limousine", "Cabriolet"]','Kompaktklasse','audi-a3-typ-8p','Der Audi A3 Typ 8V zeichnet sich durch ein schärferes, kantigeres Design im Vergleich zum Vorgänger 8P aus. Die Frontpartie wird von einem breiteren und flacheren Singleframe-Kühlergrill dominiert. Die Scheinwerfer sind ebenfalls kantiger gestaltet und verfügen oft über eine markante LED-Tagfahrlichtsignatur. Im Innenraum fällt das auf Wunsch ausfahrbare MMI-Display auf, das eine aufgeräumtere Armaturentafel ermöglicht.','Das Facelift im Jahr 2016 brachte eine überarbeitete Front mit neu gestalteten Scheinwerfern (optional mit Matrix-LED-Technologie), einem modifizierten Kühlergrill und geänderten Stoßfängern. Am Heck wurden die Rückleuchten leicht angepasst und erhielten eine neue Lichtsignatur. Im Innenraum wurde das optionale Virtual Cockpit eingeführt und das MMI-Infotainmentsystem aktualisiert.',NULL,NULL,NULL,5,2012,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a3-typ-8y','Audi','A3','Typ 8Y',2020,NULL,'["Sportback", "Limousine"]','Kompaktklasse','audi-a3-typ-8v','Der Audi A3 Typ 8Y zeichnet sich durch eine deutlich schärfere und sportlichere Linienführung im Vergleich zum Vorgänger (8V) aus. Auffällig sind der breitere und flachere Singleframe-Kühlergrill mit Wabenstruktur, die markanten, pfeilförmigen LED-Tagfahrlichtsignaturen in den Scheinwerfern (oft mit Pixel-Matrix-Design) und die ausgeprägten Lufteinlässe an der Front. Die Schulterlinie ist stärker konturiert, und das Heck wirkt breiter und muskulöser. Im Innenraum dominiert ein volldigitales Cockpit und ein zentraler, leicht zum Fahrer geneigter Touchscreen für das Infotainment-System.','Ein Facelift wurde im März 2024 vorgestellt. Die Änderungen umfassen eine überarbeitete Frontschürze mit neuem Singleframe-Kühlergrill und größeren Lufteinlässen, neue Lichtsignaturen für die LED-Scheinwerfer und Heckleuchten (vier wählbare digitale Tagfahrlichtsignaturen), sowie einen neu gestalteten Heckdiffusor. Im Innenraum wurden neue Dekoreinlagen, ein überarbeiteter Gangwahlhebel und zusätzliche Ambientebeleuchtung eingeführt.',NULL,NULL,NULL,5,2020,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a4-b5','Audi','A4','B5',1994,2001,'["Limousine", "Avant"]','Mittelklasse','audi-80-b4','Der Audi A4 B5 löste den Audi 80 ab und präsentierte sich mit einer deutlich runderen, aerodynamischeren Formgebung im Vergleich zum kantigeren Vorgänger. Charakteristisch sind die schmalen, langgezogenen Scheinwerfer, die in die Kotflügel übergehen, sowie der trapezförmige Kühlergrill, der noch nicht die später typische Singleframe-Form hatte. Die Seitenlinie ist fließender, und das Heck der Limousine wirkt kompakter. Der Avant (Kombi) wurde erst 1996 eingeführt und zeichnet sich durch ein harmonisch integriertes Kombiheck aus.','Ein umfassendes Facelift erfolgte im Modelljahr 1999 (Produktionsstart Ende 1998). Die Front erhielt neue, leicht modifizierte Scheinwerfer mit klaren Gläsern und integrierten Blinkern (vorher orange), einen leicht überarbeiteten Kühlergrill und neue Stoßfänger mit runderen Nebelscheinwerfern. Am Heck wurden die Rückleuchten leicht überarbeitet, und die Stoßfänger erhielten ebenfalls eine modernere Form. Im Innenraum gab es kleinere Änderungen an Materialien und Schaltern, sowie ein überarbeitetes Kombiinstrument.',NULL,NULL,NULL,3,1997,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a4-b6','Audi','A4','B6',2000,2004,'["Limousine", "Avant"]','Mittelklasse','audi-a4-b5','Der Audi A4 B6 unterscheidet sich vom Vorgänger B5 durch eine deutlich rundlichere und fließendere Karosserieform. Die Scheinwerfer sind nicht mehr eckig, sondern haben eine geschwungene, leicht mandelförmige Kontur. Die Frontschürze ist integrierter und weniger kantig, und die Heckleuchten sind breiter und reichen weiter in die Kofferraumklappe hinein, mit einer charakteristischen C-Form im Design.',NULL,NULL,NULL,NULL,4,2001,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a4-b7','Audi','A4','B7',2004,2008,'["Limousine", "Avant", "Cabriolet"]','Mittelklasse','audi-a4-b6','Der Audi A4 B7 ist sofort am markanten Singleframe-Kühlergrill zu erkennen, der sich über die gesamte Höhe der Front erstreckt und ihn deutlich vom Vorgänger B6 abgrenzt. Die Scheinwerfer sind neu gestaltet, wirken eckiger und haben eine leichte Welle am unteren Rand. Auch die Heckleuchten sind breiter und flacher als beim B6, was dem Fahrzeug ein sportlicheres und moderneres Erscheinungsbild verleiht.',NULL,NULL,NULL,NULL,5,2005,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a4-b8','Audi','A4','B8',2007,2015,'["Limousine", "Avant", "Allroad quattro"]','Mittelklasse','audi-a4-b7','Der Audi A4 B8 zeichnet sich durch einen markanten, breiteren Singleframe-Kühlergrill aus, der im Vergleich zum Vorgänger B7 stärker in die Front integriert ist. Die Scheinwerfer sind schmaler und haben oft ein charakteristisches LED-Tagfahrlichtband am unteren Rand. Die Karosserielinien sind schärfer und fließender, mit einer ausgeprägten Schulterlinie, die sich von den Scheinwerfern bis zu den Rückleuchten zieht. Die Rückleuchten sind breiter und flacher als beim B7 und reichen weiter in die Heckklappe hinein.','Das Facelift im Jahr 2011 (Modelljahr 2012) brachte überarbeitete Scheinwerfer mit einer wellenförmigen Unterkante und neuen LED-Tagfahrlichtgrafiken. Der Singleframe-Kühlergrill erhielt abgeschrägte obere Ecken und eine neue Gitterstruktur. Die Stoßfänger wurden vorne und hinten neu gestaltet, mit größeren Lufteinlässen vorne und einem Diffusor-Einsatz hinten. Auch die Rückleuchten erhielten eine neue, durchgehende LED-Lichtleiste. Im Innenraum wurden Lenkräder, Bedienelemente und Zierleisten leicht modifiziert.',NULL,NULL,NULL,5,2008,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a4-b9','Audi','A4','B9',2015,2023,'["Limousine", "Avant", "Allroad"]','Mittelklasse','audi-a4-b8','Der Audi A4 B9 zeichnet sich durch eine schärfere, horizontal betonte Linienführung aus. Die Scheinwerfer sind flacher und breiter als beim Vorgänger B8, oft mit einer markanten LED-Tagfahrlichtsignatur. Der Singleframe-Kühlergrill ist breiter und flacher gestaltet, was dem Fahrzeug eine sportlichere und modernere Optik verleiht. Die Karosserie wirkt insgesamt gestreckter und dynamischer.','Das Facelift (Modelljahr 2020, vorgestellt 2019) brachte eine überarbeitete Frontpartie mit einem noch breiteren und flacheren Singleframe-Kühlergrill, der nun eine Wabenstruktur aufweisen kann. Die Scheinwerfer wurden neu gestaltet und sind serienmäßig mit LED-Technik ausgestattet, optional mit Matrix-LED. Auch die Heckleuchten erhielten eine neue Lichtsignatur. Im Innenraum wurde das MMI-Bediensystem durch einen größeren Touchscreen ersetzt, der die bisherige Dreh-Drück-Steuerung ablöste.',NULL,NULL,NULL,5,2015,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a5-i','Audi','A5','I',2007,2016,'["Coupé", "Cabriolet", "Sportback"]','Obere Mittelklasse',NULL,'Die erste Generation des Audi A5 (Typ 8T/8F) zeichnet sich durch eine flache, sportliche Silhouette aus. Die Front ist geprägt von einem großen Singleframe-Kühlergrill mit abgeschrägten oberen Ecken und markanten, oft mit LED-Tagfahrlichtbändern versehenen Scheinwerfern, die eine leicht geschwungene Unterkante aufweisen. Die Seitenlinie ist von einer markanten Schulterlinie geprägt, die sich von den Scheinwerfern bis zu den Rückleuchten zieht. Im Vergleich zum Nachfolger (A5 II) wirken die Scheinwerfer und Rückleuchten weniger kantig und die Karosserie insgesamt runder.','Das Facelift im Jahr 2011 brachte eine überarbeitete Frontpartie mit abgeflachten oberen Ecken des Singleframe-Kühlergrills und neu gestalteten Scheinwerfern mit einer durchgehenden LED-Lichtleiste. Die Nebelscheinwerfer erhielten eine eckigere Form. Am Heck wurden die Rückleuchten leicht modifiziert und erhielten eine neue Lichtsignatur. Auch das Interieur wurde mit neuen Lenkrädern und überarbeiteten Bedienelementen aufgewertet.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a5-ii','Audi','A5','II',2016,NULL,'["Coupé", "Sportback", "Cabriolet"]','Obere Mittelklasse','audi-a5-i','Die zweite Generation des Audi A5 (B9) zeichnet sich durch eine schärfere, kantigere Designsprache aus. Die Scheinwerfer sind flacher und laufen spitzer zu, oft mit einer markanten LED-Tagfahrlichtsignatur. Der Singleframe-Kühlergrill ist breiter und flacher als beim Vorgänger und hat eine sechseckige Form. Die Motorhaube weist markante Powerdomes auf, und die Seitenlinie ist stärker konturiert mit einer ausgeprägteren Schulterlinie.','Das Facelift im Jahr 2019 (Modelljahr 2020) brachte eine überarbeitete Frontpartie mit einem breiteren, flacheren Singleframe-Kühlergrill, der nun eine Wabenstruktur aufweist. Die Lufteinlässe an der Front wurden neu gestaltet und sind markanter. Die Scheinwerfer erhielten eine neue Lichtsignatur und sind optional mit Matrix-LED-Technologie erhältlich. Am Heck wurden die Stoßfänger und die Endrohrblenden modifiziert, und die Rückleuchten erhielten ebenfalls eine neue LED-Grafik. Im Innenraum wurde das MMI-Bediensystem durch einen größeren Touchscreen ersetzt, der die bisherige Dreh-Drück-Steuerung ablöste.',NULL,NULL,NULL,5,2016,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a6-c4','Audi','A6','C4',1994,1997,'["Limousine", "Avant"]','Obere Mittelklasse','audi-100-c4','Der Audi A6 C4 ist im Wesentlichen ein umbenannter und leicht überarbeiteter Audi 100 C4. Die markantesten Unterschiede zum Audi 100 C4 sind die geänderten Scheinwerfer (oft mit Klarglasoptik), die neu gestalteten Stoßfänger vorne und hinten, die geänderte Heckklappe mit integriertem Kennzeichenausschnitt (Limousine) und die durchgehende rote Leiste zwischen den Rückleuchten (Avant). Die Frontpartie wirkt insgesamt runder und moderner als beim Vorgänger.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a6-c5','Audi','A6','C5',1997,2004,'["Limousine", "Avant"]','Obere Mittelklasse','audi-a6-c4','Der Audi A6 C5 zeichnet sich durch seine deutlich runderen und fließenderen Karosserielinien im Vergleich zum kantigeren Vorgänger C4 aus. Die Front wird von großen, mandelförmigen Scheinwerfern dominiert, die sich weit in die Kotflügel ziehen. Die Dachlinie der Limousine fällt sanft nach hinten ab, und der Kühlergrill ist breiter und stärker in die Front integriert.','Das Facelift erfolgte im Modelljahr 2002 (produziert ab Mitte 2001). Optische Änderungen umfassten neu gestaltete Scheinwerfer mit Klarglasoptik und integrierten Blinkern, einen leicht modifizierten Kühlergrill, neue Stoßfänger vorne und hinten sowie geänderte Rückleuchten mit runden Elementen. Im Innenraum gab es kleinere Anpassungen an Materialien und Bedienelementen.',NULL,NULL,NULL,3,1998,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a6-c6','Audi','A6','C6',2004,2011,'["Limousine", "Avant", "Allroad"]','Obere Mittelklasse','audi-a6-c5','Der Audi A6 C6 ist sofort am markanten, großen Singleframe-Kühlergrill zu erkennen, der sich von der Motorhaube bis zur Unterkante der Stoßstange zieht. Im Vergleich zum Vorgänger C5 wirkt er deutlich runder und fließender, mit einer ausgeprägteren Schulterlinie. Die Heckleuchten sind breiter und ziehen sich weit in den Kofferraumdeckel hinein.','Das Facelift im Herbst 2008 (Modelljahr 2009) brachte eine überarbeitete Frontschürze und neue Scheinwerfer mit integriertem LED-Tagfahrlicht (eine Reihe von LEDs am unteren Rand). Am Heck wurden die Leuchten ebenfalls neu gestaltet und erhielten eine markante LED-Lichtsignatur. Zudem gab es leichte Änderungen am Singleframe-Kühlergrill und der Heckschürze.',NULL,NULL,NULL,5,2004,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a6-c7','Audi','A6','C7',2011,2018,'["Limousine", "Avant"]','Obere Mittelklasse','audi-a6-c6','Der Audi A6 C7 zeichnet sich durch eine deutlich schärfere und sportlichere Linienführung im Vergleich zum Vorgänger C6 aus. Charakteristisch sind die flacheren, breiteren Scheinwerfer, die optional mit einem markanten LED-Tagfahrlichtband ausgestattet sind. Der Singleframe-Kühlergrill ist breiter und flacher gestaltet, mit abgeschrägten oberen Ecken. Eine ausgeprägte Schulterlinie zieht sich über die gesamte Fahrzeugseite. Die Heckleuchten sind ebenfalls flacher und breiter, betonen die Fahrzeugbreite und verfügen über eine horizontale Gliederung.','Das Facelift erfolgte im Herbst 2014 (Modelljahr 2015). Optische Änderungen umfassen neu gestaltete Scheinwerfer (optional mit Matrix-LED-Technologie), einen überarbeiteten Singleframe-Kühlergrill, modifizierte Stoßfänger vorne und hinten sowie neu gezeichnete Rückleuchten, die optional mit dynamischen Blinkern erhältlich waren. Auch die Endrohrblenden wurden angepasst.',NULL,NULL,NULL,5,2011,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a6-c8','Audi','A6','C8',2018,NULL,'["Limousine", "Avant", "Allroad"]','Obere Mittelklasse','audi-a6-c7','Der Audi A6 C8 zeichnet sich durch einen breiteren und flacheren Singleframe-Kühlergrill aus, der von scharf gezeichneten Scheinwerfern mit markanter Tagfahrlichtsignatur flankiert wird. Am Heck verbindet ein durchgehendes Chromband die Rückleuchten (bei Limousine und Avant). Im Innenraum dominieren zwei große Touchscreens in der Mittelkonsole (oben für Infotainment, unten für Klima/Komfortfunktionen), die das Bedienkonzept des Vorgängers mit Dreh-Drück-Steller und ausfahrbarem Bildschirm ablösen.',NULL,NULL,NULL,NULL,5,2018,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a7-typ-4g','Audi','A7','Typ 4G',2010,2018,'["Sportback"]','Obere Mittelklasse',NULL,'Der Audi A7 Typ 4G zeichnet sich durch seine coupéhafte Fließheck-Karosserie mit fünf Türen aus, die eine sportlich-elegante Silhouette bildet. Er besitzt einen breiten, flachen Singleframe-Kühlergrill und markante, oft pfeilförmige LED-Tagfahrlichter. Im Vergleich zum Audi A6 C7, mit dem er sich die Plattform teilt, ist der A7 deutlich flacher, breiter und verfügt über rahmenlose Seitenscheiben.','Im Jahr 2014 erhielt der A7 Typ 4G ein Facelift. Die Änderungen umfassten neu gestaltete Scheinwerfer (optional mit Matrix LED-Technologie), einen überarbeiteten Singleframe-Kühlergrill und modifizierte Stoßfänger vorne und hinten. Die Heckleuchten wurden ebenfalls aktualisiert und verfügten nun über dynamische Blinker. Im Innenraum gab es neue Materialien und Updates für das Infotainmentsystem.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a7-typ-4k','Audi','A7','Typ 4K',2018,NULL,'["Sportback"]','Obere Mittelklasse','audi-a7-typ-4g','Der Audi A7 Typ 4K zeichnet sich durch eine deutlich schärfere und sportlichere Linienführung im Vergleich zum Vorgänger (Typ 4G) aus. Auffällig sind der breitere, flachere Singleframe-Kühlergrill und das durchgehende Leuchtenband am Heck, das eine markante digitale Lichtsignatur aufweist. Im Innenraum dominieren zwei große Touchscreens (MMI touch response) die Mittelkonsole, die den klassischen Dreh-Drück-Steller ersetzen.','Im Mai 2023 erfolgte eine Modellpflege. Die Änderungen umfassen neu gestaltete Frontschürzen mit Wabenstruktur, überarbeitete Heckdiffusoren und neue Felgendesigns. Im Innenraum wurden neue Dekoreinlagen und Sitzbezüge eingeführt. Die Ausstattungslinien wurden neu strukturiert und umbenannt (Basis, advanced, S line).',NULL,NULL,NULL,NULL,NULL,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a8-d2','Audi','A8','D2',1994,2002,'["Limousine", "Langversion"]','Oberklasse','audi-v8-d11','Der Audi A8 D2 ist erkennbar an seiner fließenden, aber noch kantigeren Karosserielinie im Vergleich zum Nachfolger D3. Charakteristisch sind die relativ schmalen, rechteckigen Scheinwerfer mit integrierten Blinkern und die breite, aber noch nicht als Singleframe ausgeführte Kühlergrill-Einheit, die von einer Chromleiste umrahmt wird. Die Heckleuchten sind durchgehend rot und relativ schmal, oft mit einer Chromleiste zwischen den Leuchten. Die Karosserie besteht vollständig aus Aluminium (Audi Space Frame).','Das Facelift im Jahr 1999 (Modelljahr 2000) brachte dezente Änderungen mit sich. Die Scheinwerfer erhielten eine leicht überarbeitete Optik, oft mit Klarglas-Blinkern. Die Nebelscheinwerfer wurden in die Stoßstange integriert. Am Heck wurden die Rückleuchten leicht modifiziert, und die Chromleiste zwischen den Rückleuchten entfiel zugunsten einer durchgehenden roten Optik. Im Innenraum gab es kleinere Anpassungen an Materialien und Bedienelementen.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a8-d3','Audi','A8','D3',2002,2010,'["Limousine"]','Oberklasse','audi-a8-d2','Der Audi A8 D3 ist erkennbar an seiner fließenden, eleganten Karosserielinie, die im Vergleich zum Vorgänger D2 deutlich runder und weniger kantig ist. Charakteristisch sind die breiteren, mandelförmigen Scheinwerfer und die Einführung des markanten Singleframe-Kühlergrills, der ab dem Facelift 2005 die gesamte Front dominiert. Die Heckleuchten sind breiter und flacher als beim D2.','Das große Facelift im Jahr 2005 führte den markanten Singleframe-Kühlergrill ein, der sich von der Motorhaube bis zur Unterkante der Stoßstange erstreckt. Die Frontstoßstange wurde neu gestaltet, und die Nebelscheinwerfer wurden in die unteren Lufteinlässe integriert. Auch die Heckleuchten erhielten eine leicht modifizierte Grafik. Ein kleineres Update 2007 brachte dezente Änderungen an den Außenspiegeln mit integrierten LED-Blinkern und eine leicht überarbeitete Heckschürze.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a8-d4','Audi','A8','D4',2010,2017,'["Limousine"]','Oberklasse','audi-a8-d3','Der Audi A8 D4 zeichnet sich durch einen breiteren, aber noch nicht so dominanten Singleframe-Kühlergrill wie der Nachfolger D5 aus. Die Scheinwerfer sind markanter und integrieren oft ein durchgehendes LED-Tagfahrlichtband. Im Vergleich zum Vorgänger D3 wirkt die Karosserie fließender und muskulöser, mit einer stärker ausgeprägten Schulterlinie. Am Heck sind die Leuchten breiter und flacher, oft durch eine Chromleiste verbunden. Das Interieur ist deutlich moderner, mit einem ausfahrbaren MMI-Bildschirm und einem Touchpad für die Bedienung.','Das Facelift erfolgte im Herbst 2013 (Modelljahr 2014). Wesentliche Merkmale sind die optionalen Matrix-LED-Scheinwerfer mit adaptiver Lichtverteilung, leicht modifizierte Stoßfänger vorne und hinten, eine überarbeitete Motorpalette mit optimiertem Verbrauch und Leistung sowie neue Chromapplikationen am Heck. Im Innenraum gab es kleinere Detailänderungen und neue Assistenzsysteme.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-a8-d5','Audi','A8','D5',2017,NULL,'["Limousine"]','Oberklasse','audi-a8-d4','Die D5-Generation des Audi A8 zeichnet sich durch einen breiteren und flacheren Singleframe-Kühlergrill aus. Am Heck ist ein markantes, durchgehendes Leuchtenband charakteristisch, das die Breite des Fahrzeugs betont. Die Karosserie wirkt im Vergleich zum Vorgänger D4 schärfer gezeichnet und moderner, mit einer stärkeren Betonung der Radhäuser.','Das Facelift erfolgte Ende 2021 (Modelljahr 2022). Der Singleframe-Grill wurde noch breiter und erhielt eine neue Gitterstruktur. Die seitlichen Lufteinlässe wurden neu gestaltet und wirken markanter. Neue digitale Matrix-LED-Scheinwerfer und OLED-Heckleuchten mit anpassbaren Lichtsignaturen wurden eingeführt. Die Heckschürze erhielt ebenfalls ein überarbeitetes Design.',NULL,NULL,NULL,NULL,NULL,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-e-tron-2019','Audi','e-tron','1. Generation (GE)',2018,2022,'["SUV", "SUV Coupé"]','Obere Mittelklasse',NULL,'Die erste Generation des Audi e-tron zeichnet sich durch den markanten, geschlossenen Singleframe-Grill in Platin-Grau mit vertikalen Streben aus. Die Scheinwerfer verfügen über vier horizontale Segmente für das Tagfahrlicht. Ein weiteres Erkennungsmerkmal sind die optionalen virtuellen Außenspiegel (Kameras statt Spiegel) und die Ladeklappen, die sich beidseitig vorne an den Kotflügeln befinden.',NULL,NULL,NULL,NULL,5,2019,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-e-tron-gt-typ-4j','Audi','e-tron GT','Typ 4J',2021,NULL,'["Sportlimousine", "Coupé"]','Oberklasse',NULL,'Der Audi e-tron GT Typ 4J zeichnet sich durch seine extrem flache und breite Karosserie mit einer stark abfallenden Dachlinie aus, die ihm eine coupéartige Silhouette verleiht. Die Front dominiert ein geschlossener Singleframe-Grill in Wagenfarbe mit einer Wabenstruktur, flankiert von markanten LED-Scheinwerfern (optional Matrix-LED oder Laserlicht). Am Heck ist ein durchgehendes Leuchtenband charakteristisch, das die Breite des Fahrzeugs betont und die Rückleuchten miteinander verbindet. Die breiten Radhäuser und die muskulösen Schultern unterstreichen den sportlichen Anspruch.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q2-ga','Audi','Q2','GA',2016,NULL,'["SUV"]','Kompakt-SUV',NULL,'Der Audi Q2 GA zeichnet sich durch seine markante, farblich abgesetzte C-Säule (Blade), das polygonale Design mit vielen Ecken und Kanten sowie den breiten, flachen Singleframe-Kühlergrill aus. Die Scheinwerfer sind kantig und die Heckleuchten relativ klein und hoch positioniert. Er ist deutlich kompakter und sportlicher gezeichnet als der größere Q3.','Im Jahr 2020 erhielt der Audi Q2 ein Facelift. Die auffälligsten Änderungen umfassen eine neu gestaltete Frontschürze mit größeren Lufteinlässen und einem leicht modifizierten Singleframe-Grill. Die LED-Scheinwerfer erhielten eine neue Lichtsignatur, und optional waren Matrix-LED-Scheinwerfer erhältlich. Am Heck wurden die Stoßfänger überarbeitet und die Diffusor-Optik verstärkt. Neue Außenfarben und Felgendesigns wurden ebenfalls eingeführt.',NULL,NULL,NULL,5,2016,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q3-i','Audi','Q3','I',2011,2018,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Audi Q3 (Typ 8U) zeichnet sich durch eine rundlichere, weniger kantige Form im Vergleich zum Nachfolger aus. Die Scheinwerfer sind eher tropfenförmig und laufen spitz zur Fahrzeugmitte hin. Der Singleframe-Kühlergrill ist trapezförmig und hat abgerundete Ecken, während die Nebelscheinwerfer in runden Aussparungen in der Frontschürze sitzen. Die Heckleuchten sind relativ kompakt und reichen nicht weit in die Heckklappe hinein.','Das Facelift im Jahr 2014 (Modelljahr 2015) brachte eine überarbeitete Frontpartie mit einem markanteren Singleframe-Kühlergrill, der nun stärker dreidimensional ausgeprägt war und eine neue Lamellenstruktur erhielt. Die Scheinwerfer wurden neu gestaltet und waren optional mit LED-Technik erhältlich. Auch die Heckleuchten erhielten eine leicht modifizierte Grafik. Die Stoßfänger wurden ebenfalls dezent angepasst.',NULL,NULL,NULL,5,2011,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q3-ii','Audi','Q3','II',2018,NULL,'["SUV", "Crossover"]','Kompakt-SUV','audi-q3-i','Der Audi Q3 II (seit 2018) unterscheidet sich deutlich vom Vorgänger. Auffällig sind die schärfer gezeichneten Linien, die breitere und flachere Singleframe-Grill-Optik mit vertikalen Streben, die nun schmaleren Scheinwerfer mit neuer LED-Signatur und die insgesamt kantigere Karosserieform. Das Heck wirkt gestreckter und moderner, mit durchgehenden Rückleuchten-Elementen, die durch eine Chromleiste verbunden sind.','Im Herbst 2024 wurde der Q3 II überarbeitet. Äußerlich erkennbar an einem leicht modifizierten Singleframe-Grill, neuen Scheinwerfer- und Rückleuchten-Designs mit angepasster Lichtsignatur sowie dezenten Änderungen an Stoßfängern und Rad-Designs. Innen gab es ein überarbeitetes Infotainmentsystem und neue Materialien.',NULL,NULL,NULL,5,2018,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q4-e-tron-2021','Audi','Q4 e-tron','1. Generation (Typ F4)',2021,NULL,'["SUV", "SUV-Coupé"]','Kompakt-SUV',NULL,'Die erste Generation des Audi Q4 e-tron zeichnet sich durch eine geschlossene, markante Singleframe-Front aus, die typisch für Audis Elektrofahrzeuge ist. Die Scheinwerfer sind schmal und scharf gezeichnet, oft mit digitalen Tagfahrlichtsignaturen. Die Karosserie weist muskulöse Radhäuser und eine fließende Dachlinie auf, insbesondere beim Sportback-Modell. Im Vergleich zu Audis Verbrenner-SUVs wie dem Q3 oder Q5 wirkt der Q4 e-tron futuristischer und aerodynamischer, mit einem kürzeren vorderen Überhang und einem längeren Radstand, bedingt durch die MEB-Plattform.',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q5-i','Audi','Q5','I',2008,2017,'["SUV"]','Kompakt-SUV',NULL,'Der Audi Q5 der ersten Generation (Typ 8R) wurde 2008 eingeführt. Er zeichnet sich durch die typische Audi-Singleframe-Kühlergrill-Architektur aus, die sich von den Vorgängermodellen unterscheidet. Die Scheinwerfer sind scharf geschnitten und integrieren optional LED-Tagfahrlichter. Die Seitenlinie ist durch eine markante Schulterlinie und eine abfallende Dachlinie geprägt, die dem Fahrzeug eine coupéhafte Anmutung verleiht. Im Vergleich zu früheren SUV-Modellen von Audi wirkt der Q5 sportlicher und dynamischer.','Im Jahr 2012 erhielt der Audi Q5 ein Facelift. Äußerlich erkennbar an einem neu gestalteten Singleframe-Kühlergrill, überarbeiteten Scheinwerfern und Rückleuchten mit optionalen LED-Lichtbändern. Die Stoßfänger wurden ebenfalls modifiziert. Im Innenraum gab es kleinere Detailverbesserungen und neue Ausstattungsoptionen.',NULL,NULL,NULL,5,2017,NULL,'24 Monate','Der Audi Q5 I ist ein solider Kompakt-SUV mit guter Verarbeitung und angenehmem Fahrkomfort. Achten Sie beim Kauf auf die Wartungshistorie, insbesondere bei den Dieselmotoren, bei denen Probleme mit dem Partikelfilter auftreten können. Rost ist bei gut gepflegten Fahrzeugen eher selten ein Thema. Die Getriebeautomatik (S tronic) sollte auf Ruckeln geprüft werden. Beliebte Motorisierungen sind die TDI-Varianten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q5-ii','Audi','Q5','II',2017,2023,'["SUV", "SUV Coupé"]','Mittelklasse-SUV','audi-q5-i','Die zweite Generation des Audi Q5 (Typ FY) ist an einem breiteren, flacheren Singleframe-Kühlergrill und schärfer gezeichneten Scheinwerfern mit einer markanten LED-Tagfahrlichtsignatur zu erkennen. Die Karosserielinien sind insgesamt kantiger und sportlicher als beim Vorgänger. Am Heck fallen die flacheren, breiteren Rückleuchten auf, die optional mit OLED-Technologie erhältlich waren. Im Innenraum dominieren ein freistehendes MMI-Display und ein digitales Kombiinstrument (Audi virtual cockpit).','Das Facelift im Jahr 2020 brachte einen noch breiteren und flacheren Singleframe-Kühlergrill mit neuen Wabeneinsätzen. Die Scheinwerfer erhielten eine neue Lichtsignatur, und die Lufteinlässe an der Front wurden überarbeitet. Am Heck wurden die Rückleuchten neu gestaltet und waren optional mit digitaler OLED-Technologie erhältlich, die verschiedene Lichtsignaturen ermöglichte. Die Stoßfänger vorne und hinten wurden ebenfalls modifiziert. Im Innenraum gab es ein neues MMI-Touch-Display mit größerer Diagonale und verbesserter Konnektivität.',NULL,NULL,NULL,5,2017,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q7-typ-4l','Audi','Q7','Typ 4L',2006,2015,'["SUV"]','Oberklasse-SUV',NULL,'Der Audi Q7 Typ 4L ist an seiner massiven, aber runden Karosserieform erkennbar. Charakteristisch sind der große Singleframe-Kühlergrill mit vertikalen Chromstreben, die relativ großen, rechteckigen Scheinwerfer und die breiten, horizontal ausgerichteten Rückleuchten. Im Vergleich zum Nachfolger (Typ 4M) wirkt der 4L weniger kantig und hat eine stärker abfallende Dachlinie zum Heck hin.','Das Facelift im Jahr 2009 brachte dezente Änderungen mit sich. Die Scheinwerfer erhielten ein neues Design mit integriertem LED-Tagfahrlichtband am unteren Rand. Der Kühlergrill wurde leicht überarbeitet, und die Stoßfänger vorne und hinten wurden modifiziert. Die Rückleuchten erhielten ebenfalls eine neue Grafik mit LED-Technik. Im Innenraum gab es kleinere Anpassungen an den Bedienelementen und neue Dekorleisten.',NULL,NULL,NULL,5,2006,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q7-typ-4m','Audi','Q7','Typ 4M',2015,NULL,'["SUV"]','Obere Mittelklasse','audi-q7-typ-4l','Der Audi Q7 Typ 4M unterscheidet sich vom Vorgänger Typ 4L durch ein deutlich kantigeres und athletischeres Design. Er besitzt einen breiteren, markanten Singleframe-Kühlergrill mit horizontalen Lamellen und schmalere, schärfer gezeichnete Scheinwerfer, die oft mit Matrix-LED-Technologie ausgestattet sind. Die Karosserielinien sind weniger rundlich und wirken insgesamt moderner und präziser.','Das Facelift im Jahr 2019 brachte eine umfassende optische und technische Überarbeitung. Äußerlich wurde der Singleframe-Kühlergrill noch markanter und erhielt eine neue Lamellenstruktur. Die Scheinwerfer und Heckleuchten wurden neu gestaltet und erhielten eine neue Lichtsignatur. Im Innenraum wurde das MMI-Bediensystem durch zwei große Touchscreens (MMI touch response) ersetzt, ähnlich dem Audi A8, und das virtuelle Cockpit wurde weiterentwickelt.',NULL,NULL,NULL,5,2015,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q8-e-tron-2023','Audi','Q8 e-tron','2023',2022,NULL,'["SUV", "Sportback"]','Obere Mittelklasse','audi-e-tron-2018','Der Audi Q8 e-tron ist das umfassende Facelift und die Umbenennung des ursprünglichen Audi e-tron (Typ GE). Er unterscheidet sich durch ein neu gestaltetes Frontdesign mit einem überarbeiteten Singleframe-Grill, der nun teilweise in Wagenfarbe lackiert ist und ein neues, flaches Audi-Logo trägt. Die Scheinwerfer wurden leicht modifiziert und die Stoßfänger vorne und hinten neu gestaltet. Am Heck ist der Modellschriftzug nun in die durchgehende Lichtleiste integriert. Ein weiteres Merkmal ist die Projektion des Audi-Logos auf den Boden beim Öffnen der Türen.','Das Facelift vom Audi e-tron (2018-2022) zum Audi Q8 e-tron (ab 2022) umfasst eine Vielzahl von Änderungen. Optisch fallen sofort der neu gestaltete Singleframe-Grill auf, der nun teilweise in Wagenfarbe lackiert ist und ein neues, zweidimensionales Audi-Logo trägt. Die Frontschürze wurde aerodynamisch optimiert und die Lufteinlässe vergrößert. Am Heck wurde der Diffusor überarbeitet und der Modellschriftzug ist nun in die durchgehende Lichtleiste integriert. Technisch wurden die Batteriekapazitäten erhöht, die Ladeleistung verbessert und die Effizienz der Elektromotoren gesteigert. Auch das Fahrwerk und die Lenkung wurden überarbeitet, um ein präziseres Fahrgefühl zu ermöglichen.',NULL,NULL,NULL,5,2019,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-q8-i','Audi','Q8','I',2018,NULL,'["SUV Coupé"]','Obere Mittelklasse',NULL,'Der Audi Q8 der ersten Generation zeichnet sich durch seinen markanten, achteckigen Singleframe-Grill aus, der breiter und flacher ist als bei anderen Audi SUV-Modellen. Charakteristisch ist die coupéhafte Dachlinie, die sanft nach hinten abfällt und in einer stark geneigten Heckscheibe mündet. Am Heck verbindet ein durchgehendes Leuchtenband die Rückleuchten, was ihm eine breite und sportliche Optik verleiht. Die rahmenlosen Türen sind ein weiteres Alleinstellungsmerkmal.','Im Jahr 2023 erhielt der Audi Q8 ein Facelift. Die Änderungen umfassen neu gestaltete Front- und Heckschürzen, die dem Fahrzeug eine noch sportlichere Optik verleihen. Die Lichtsignaturen wurden überarbeitet, insbesondere die digitalen Tagfahrlichtsignaturen vorne und die OLED-Rückleuchten mit wählbaren Designs. Neue Felgendesigns und zusätzliche Lackfarben wurden eingeführt. Im Innenraum gab es neue Zierelemente und Sitzbezüge.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-r8-typ-42','Audi','R8','Typ 42',2006,2015,'["Coupé", "Spyder"]','Sportwagen',NULL,'Der Audi R8 Typ 42 ist die erste Generation des R8. Er zeichnet sich durch seine charakteristischen Sideblades (große, vertikale Lufteinlässe hinter den Türen, die farblich abgesetzt sein können) aus, die ein prägnantes Designmerkmal sind. Die Frontpartie besitzt einen Singleframe-Kühlergrill mit horizontalen Lamellen und markante, eher eckige Scheinwerfer mit integrierten LED-Tagfahrlichtern (ab 2008). Die Heckleuchten sind ebenfalls eher eckig und verfügen über eine klare Lichtsignatur. Im Vergleich zum Nachfolger (Typ 4S) wirkt der Typ 42 insgesamt kantiger und weniger aggressiv.','Das Facelift im Jahr 2012 brachte subtile Änderungen mit sich. Die auffälligsten Merkmale sind die Voll-LED-Scheinwerfer und -Rückleuchten, die nun serienmäßig waren. Die Frontschürze wurde leicht überarbeitet, und der Kühlergrill erhielt eine neue Optik. Am Heck wurden die Endrohre der Abgasanlage runder und die Heckschürze leicht modifiziert. Zudem wurde das sequentielle R tronic Getriebe durch das schnellere 7-Gang S tronic Doppelkupplungsgetriebe ersetzt.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-2-avant-b4','Audi','RS 2 Avant','B4',1994,1995,'["Kombi"]','Obere Mittelklasse',NULL,'Der Audi RS 2 Avant basiert auf dem Audi 80 B4 Avant, unterscheidet sich jedoch durch zahlreiche spezifische Merkmale, die in Zusammenarbeit mit Porsche entwickelt wurden. Auffällig sind die vom Porsche 911 (964) Carrera entliehenen Außenspiegel, die Porsche-Bremsanlage mit rot lackierten Sätteln und Porsche-Schriftzug, die 17-Zoll-Leichtmetallräder im Porsche-Design sowie die modifizierten Front- und Heckstoßfänger mit größeren Lufteinlässen vorne und einem durchgehenden roten Leuchtenband am Heck. Die Frontscheinwerfer sind ebenfalls spezifisch und unterscheiden sich von den Standard-Audi-80-Scheinwerfern.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-3-8y','Audi','RS 3','8Y',2021,NULL,'["Sportback", "Limousine"]','Kompaktklasse','audi-rs-3-8v','Der Audi RS 3 8Y zeichnet sich durch eine deutlich aggressivere Frontpartie mit einem breiteren, rahmenlosen Singleframe-Kühlergrill und RS-spezifischem Wabengitter aus. Die Matrix-LED-Scheinwerfer verfügen über eine markante digitale Tagfahrlichtsignatur, die bei den RS-Modellen oft ein Zielflaggen-Design zeigt. Im Vergleich zum Vorgänger 8V sind die Karosserielinien schärfer und kantiger, die Radhäuser sind deutlich verbreitert und die Frontschürze besitzt große, markante Lufteinlässe. Am Heck fallen die zwei großen, ovalen Endrohre und der RS-spezifische Diffusor auf.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-3-sportback-8p','Audi','RS 3 Sportback','8P',2011,2012,'["Kompaktwagen"]','Kompaktklasse',NULL,'Der Audi RS 3 Sportback der Generation 8P zeichnet sich durch seine deutlich verbreiterten Kotflügel vorne und hinten aus, die ihn vom regulären A3 8P und S3 8P abheben. Die Frontpartie ist geprägt von einem spezifischen RS-Stoßfänger mit großen Lufteinlässen und einem Kühlergrill in Wabenstruktur mit ''quattro''-Schriftzug. Am Heck fallen der markante Diffusor und die zwei großen ovalen Endrohre der Abgasanlage auf. Ein Dachkantenspoiler und spezifische RS-Leichtmetallräder runden das sportliche Erscheinungsbild ab.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-3-sportback-8v','Audi','RS 3 Sportback','8V',2015,2020,'["Kompaktwagen", "Sportback"]','Kompaktklasse','audi-rs-3-sportback-8p','Der Audi RS 3 Sportback der Generation 8V zeichnet sich durch eine schärfere, kantigere Designsprache im Vergleich zum Vorgänger aus. Auffällig sind die breiteren Radhäuser, die großen Lufteinlässe in der Frontschürze und der markante Singleframe-Kühlergrill mit Wabenstruktur und quattro-Schriftzug am unteren Rand. Die Scheinwerfer sind schmaler und aggressiver gezeichnet, oft mit LED-Tagfahrlicht. Am Heck fallen der Dachkantenspoiler und die großen ovalen Endrohre der Abgasanlage auf.','Das Facelift (Modelljahr 2017, ab Frühjahr 2017 erhältlich) brachte eine überarbeitete Frontpartie mit neu gestalteten LED-Scheinwerfern (optional Matrix-LED), einem markanteren Singleframe-Kühlergrill mit dreidimensionaler Wabenstruktur und einem schärfer gezeichneten Stoßfänger mit größeren Lufteinlässen. Am Heck wurden die LED-Rückleuchten mit dynamischem Blinklicht und der Diffusoreinsatz modifiziert. Im Innenraum gab es ein optionales Virtual Cockpit und eine aktualisierte Infotainment-Generation.',NULL,NULL,NULL,5,2012,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-4-avant-b5','Audi','RS 4 Avant','B5',1999,2001,'["Kombi"]','Mittelklasse','audi-rs-2-avant','Der Audi RS 4 Avant der Generation B5 basiert auf dem A4 B5, unterscheidet sich jedoch durch deutlich verbreiterte Kotflügel, eine eigenständige Frontschürze mit großen Lufteinlässen und einem spezifischen Wabengrill. Auch die Heckschürze ist modifiziert und integriert die ovalen Endrohre. Die Karosserie ist im Vergleich zum A4 B5 deutlich muskulöser und sportlicher gestaltet.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-4-avant-b8','Audi','RS 4 Avant','B8',2012,2015,'["Kombi"]','Obere Mittelklasse','audi-rs-4-avant-b7','Der Audi RS 4 Avant B8 basiert auf dem Facelift des A4 B8. Er zeichnet sich durch einen markanten Singleframe-Kühlergrill mit Wabenstruktur und RS-spezifischen Designelementen aus. Die Scheinwerfer sind keilförmiger als beim Vor-Facelift A4 B8 und verfügen über eine durchgehende LED-Tagfahrlichtleiste. Die Kotflügel sind deutlich verbreitert, um die breitere Spur und die größeren Räder aufzunehmen. Am Heck fallen der große Dachkantenspoiler und die ovalen Endrohre der Abgasanlage auf.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-4-avant-b9','Audi','RS 4 Avant','B9',2017,NULL,'["Kombi"]','Mittelklasse','audi-rs-4-avant-b8','Der Audi RS 4 Avant B9 zeichnet sich durch eine deutlich aggressivere Frontpartie im Vergleich zum Vorgänger B8 aus, mit einem breiteren und flacheren Singleframe-Kühlergrill, der eine Wabenstruktur aufweist. Die Scheinwerfer sind schärfer gezeichnet und verfügen über eine neue LED-Lichtsignatur. Die Karosserie ist durch markant ausgestellte Radhäuser (ca. 30 mm breiter pro Seite) und RS-spezifische Stoßfänger mit großen Lufteinlässen gekennzeichnet. Am Heck fallen der RS-spezifische Diffusor und die zwei großen ovalen Endrohre auf.','Das Facelift erfolgte Ende 2019 (Modelljahr 2020). Die Front erhielt einen noch breiteren und flacheren Singleframe-Kühlergrill mit einer überarbeiteten Wabenstruktur, der nun ohne Rahmen in die Stoßfänger integriert ist. Die LED-Scheinwerfer wurden neu gestaltet und zeigen eine geänderte Tagfahrlichtsignatur. Die Stoßfänger vorne und hinten wurden ebenfalls überarbeitet, mit größeren seitlichen Lufteinlässen vorne und einem markanteren Diffusor hinten. Im Innenraum wurde das Infotainmentsystem auf das MMI touch-Display umgestellt, das nun größer ist und keine Dreh-Drück-Regler mehr besitzt.',NULL,NULL,NULL,5,2015,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-4-b7','Audi','RS 4','B7',2006,2008,'["Limousine", "Avant", "Cabriolet"]','Obere Mittelklasse','audi-rs-4-b5','Der Audi RS 4 B7 unterscheidet sich vom regulären A4 B7 durch seine deutlich breiteren Radhäuser, die großen Lufteinlässe in der Frontschürze und den markanten Singleframe-Kühlergrill mit Wabenstruktur. Im Vergleich zum Vorgänger RS 4 B5 ist die Karosserieform moderner, die Front aggressiver gestaltet und die Außenspiegel sind in Aluminium-Optik gehalten.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-5-8t','Audi','RS 5','8T',2010,2015,'["Coupé", "Cabriolet"]','Sportwagen','null','Der Audi RS 5 (8T) unterscheidet sich vom Vorgänger durch seine breiteren Kotflügel, die markante Front mit großen Lufteinlässen und dem Singleframe-Kühlergrill, die charakteristischen RS-Ovalrohre am Heck und die schärfer gezeichneten Scheinwerfer und Rückleuchten.','Das Facelift im Jahr 2012 brachte eine überarbeitete Front mit neuen Scheinwerfern (optional mit LED-Tagfahrlicht), einen modifizierten Kühlergrill, neue Stoßfänger und überarbeitete Rückleuchten. Im Innenraum gab es kleinere Änderungen an Lenkrad und Infotainmentsystem.',NULL,NULL,NULL,NULL,NULL,NULL,'2','Der RS 5 (8T) ist ein leistungsstarker Sportwagen, der jedoch auch höhere Unterhaltskosten mit sich bringt. Achten Sie auf eine lückenlose Wartungshistorie, insbesondere im Hinblick auf das Getriebe und den Motor. Rost an den Radläufen und der Heckklappe kann ein Problem darstellen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-5-b9','Audi','RS 5','B9',2017,2024,'["Coupé", "Sportback"]','Sportwagen','audi-rs-5-b8','Der Audi RS 5 B9 unterscheidet sich vom Vorgänger B8 durch eine breitere und flachere Singleframe-Kühlergrill-Architektur, markantere Lufteinlässe, eine schärfere Linienführung der Karosserie mit ausgeprägten Radläufen und eine neu gestaltete Heckpartie mit durchgehender Lichtleiste und ovalen Endrohren. Die Scheinwerfer sind flacher und aggressiver gezeichnet.','Das Facelift (Modelljahr 2020) brachte eine überarbeitete Front mit breiterem Kühlergrill, neuen Scheinwerfern mit optionalem Laserlicht, modifizierten Lufteinlässen und einem neuen Frontspoiler. Am Heck wurden die Stoßfänger und die Lichtsignatur der Rückleuchten angepasst. Im Innenraum gab es ein neues Infotainmentsystem mit Touchscreen und ein digitales Kombiinstrument.',NULL,NULL,NULL,NULL,NULL,NULL,'24 Monate','Der RS 5 B9 bietet eine exzellente Kombination aus Sportlichkeit und Alltagstauglichkeit. Achten Sie auf die Wartungshistorie, insbesondere im Hinblick auf das Getriebe und den Motor. Modelle mit Keramikbremsen sind teurer in der Wartung, bieten aber eine bessere Performance. Die Ausstattungsvarianten können stark variieren, prüfen Sie die vorhandenen Optionen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-6-avant-c7','Audi','RS 6 Avant','C7',2013,2018,'["Kombi"]','Obere Mittelklasse','audi-rs-6-avant-c6','Der Audi RS 6 Avant C7 basiert auf dem A6 C7, unterscheidet sich aber durch eine deutlich aggressivere Frontschürze mit großen Lufteinlässen, einen spezifischen Singleframe-Kühlergrill mit Wabenstruktur und RS-Emblem, sowie verbreiterte Radhäuser, die dem Fahrzeug eine breitere Spur verleihen. Am Heck sind ein markanter Diffusor und zwei große ovale Endrohre charakteristisch. Die Scheinwerfer sind schmaler und schärfer gezeichnet als beim Vorgänger C6.','Im Jahr 2014 erhielt der RS 6 Avant C7 ein Facelift (oft als C7.5 bezeichnet). Die auffälligsten Änderungen umfassten neu gestaltete LED-Scheinwerfer (optional Matrix-LED), überarbeitete LED-Rückleuchten mit dynamischem Blinklicht, eine leicht modifizierte Frontschürze und einen aktualisierten Singleframe-Kühlergrill. Im Innenraum gab es ein verbessertes MMI-Infotainmentsystem mit schnellerem Prozessor und neuen Dekoreinlagen.',NULL,NULL,NULL,5,2011,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-6-avant-c8','Audi','RS 6 Avant','C8',2019,NULL,'["Kombi"]','Obere Mittelklasse','audi-rs-6-avant-c7','Der Audi RS 6 Avant C8 zeichnet sich durch eine deutlich aggressivere und breitere Karosserie im Vergleich zum zivilen A6 Avant aus. Charakteristisch sind die stark ausgestellten Radhäuser, die dem Fahrzeug eine Breite von 1,95 Metern verleihen. Die Front dominiert ein breiter, rahmenloser Singleframe-Grill mit Wabenstruktur und RS-spezifischem Design. Die Scheinwerfer sind flacher und schärfer gezeichnet als beim Vorgänger C7 und stammen vom A7, nicht vom A6. Am Heck fallen die ovalen RS-Abgasendrohre und ein markanter Dachkantenspoiler auf. Die gesamte Karosserie, mit Ausnahme der vorderen Türen, des Daches und der Heckklappe, ist RS-spezifisch.',NULL,NULL,NULL,NULL,5,2018,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-6-c5','Audi','RS 6','C5',2002,2004,'["Avant", "Limousine"]','Obere Mittelklasse','audi-rs-4-b5','Der Audi RS 6 C5 basiert auf dem Audi A6 C5, unterscheidet sich jedoch durch deutlich verbreiterte Kotflügel, eine aggressivere Frontschürze mit größeren Lufteinlässen, eine Heckschürze mit integrierten ovalen Doppelendrohren und RS-spezifische Leichtmetallräder. Die Außenspiegelgehäuse sind in Aluminiumoptik gehalten.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-6-c6','Audi','RS 6','C6',2008,2010,'["Kombi", "Limousine"]','Obere Mittelklasse','audi-rs-6-c5','Der Audi RS 6 C6 zeichnet sich durch seine deutlich verbreiterten Radhäuser aus, die eine breitere Spur und größere Räder aufnehmen. Die Front dominiert ein großer, einteiliger Singleframe-Kühlergrill mit Wabenstruktur. Charakteristisch sind zudem die in die Hauptscheinwerfer integrierten LED-Tagfahrlichter und die großen Lufteinlässe in der Frontschürze. Am Heck sind die RS-typischen ovalen Endrohre und ein dezenter Diffusor zu finden. Im Vergleich zum Vorgänger C5 wirkt der C6 massiver und moderner, mit einer fließenderen Linienführung und einer stärker integrierten Lichtsignatur.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-7-sportback-c7','Audi','RS 7 Sportback','C7',2013,2018,'["Sportback"]','Obere Mittelklasse',NULL,'Der Audi RS 7 Sportback C7 basiert auf dem A7 C7 und ist durch seine spezifischen RS-Merkmale klar erkennbar. Dazu gehören eine aggressivere Frontschürze mit großen, markanten Lufteinlässen und einem Wabenkühlergrill, breitere Radhäuser, die dem Fahrzeug eine muskulösere Statur verleihen, sowie eine RS-spezifische Heckschürze mit integriertem Diffusor und zwei großen ovalen Endrohren. Die Scheinwerfer sind im Vergleich zum Vorgänger (der nicht existiert, aber im Vergleich zu anderen Audi-Modellen der Zeit) schärfer gezeichnet und oft mit LED-Technik ausgestattet.','Das Facelift (Modelljahr 2015, vorgestellt Ende 2014) brachte überarbeitete Scheinwerfer mit serienmäßiger LED-Technik oder optionalen Matrix-LED-Scheinwerfern, eine leicht modifizierte Frontschürze und einen neu gestalteten Singleframe-Kühlergrill. Am Heck wurden die Rückleuchten mit neuen LED-Grafiken versehen und die Heckschürze leicht angepasst. Im Innenraum gab es kleinere Updates bei den Materialien und dem Infotainmentsystem (MMI).',NULL,NULL,NULL,NULL,NULL,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-7-sportback-c8','Audi','RS 7 Sportback','C8',2019,NULL,'["Sportback"]','Obere Mittelklasse','audi-rs-7-sportback-c7','Der Audi RS 7 Sportback C8 zeichnet sich durch eine deutlich aggressivere und breitere Karosserie im Vergleich zum zivilen A7 C8 aus, mit verbreiterten Radhäusern (ca. 40 mm pro Seite). Die Frontpartie ist geprägt von einem RS-spezifischen Singleframe-Kühlergrill ohne Chromrahmen und großen, markanten Lufteinlässen mit Wabenstruktur. Am Heck fallen die RS-typischen ovalen Doppelendrohre und ein ausfahrbarer Heckspoiler auf.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-e-tron-gt-typ-ge','Audi','RS e-tron GT','Typ GE',2021,NULL,'["Limousine"]','Oberklasse',NULL,'Der Audi RS e-tron GT Typ GE zeichnet sich durch seine extrem flache, breite und sportliche Karosserie im Gran Turismo-Stil aus. Er besitzt eine markante, invertierte Singleframe-Maske, die je nach Ausstattung in Wagenfarbe oder Schwarz gehalten ist. Die scharf gezeichneten, flachen LED-Scheinwerfer (optional Matrix LED oder Laserlicht) und das durchgehende Leuchtenband am Heck mit dynamischen Blinkern sind charakteristisch. Die muskulösen Radhäuser und die coupéartige Dachlinie unterstreichen seinen sportlichen Anspruch. Er unterscheidet sich deutlich von den SUV-Modellen der e-tron Familie durch seine niedrige Bauhöhe und die klassische Sportwagen-Proportion.','Im Mai 2024 erfolgte ein umfassendes Update. Die RS e-tron GT Modelle erhielten eine überarbeitete Frontschürze mit neu gestalteten Lufteinlässen und einem modifizierten Singleframe-Grill. Am Heck wurden der Diffusor und die Heckschürze angepasst. Neue Felgendesigns und Lackfarben wurden eingeführt. Im Innenraum gab es neue Lenkräder, Sitzbezüge und digitale Inhalte im MMI. Technisch wurden die Leistung der Elektromotoren, die Batteriekapazität und die Ladeleistung erhöht sowie das Fahrwerk überarbeitet.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-q3-8u','Audi','RS Q3','8U',2013,2018,'["SUV"]','Kompakt-SUV',NULL,'Der Audi RS Q3 der Generation 8U basiert auf dem ersten Audi Q3. Er zeichnet sich durch eine kompakte, eher rundliche Karosserieform aus. Die Front ist geprägt von einem großen, trapezförmigen Singleframe-Kühlergrill mit Wabenstruktur und RS-Schriftzug. Die Scheinwerfer sind relativ schmal und laufen spitz zu den Kotflügeln hin aus. Im Vergleich zum Standard-Q3 8U besitzt der RS Q3 größere Lufteinlässe in der Frontschürze, verbreiterte Radläufe und einen markanten Heckdiffusor mit einem großen, ovalen Endrohr.','Das Facelift (Modelljahr 2015, vorgestellt Ende 2014) brachte eine überarbeitete Frontpartie mit einem neu gestalteten Singleframe-Kühlergrill, der nun stärker in die Scheinwerfer integriert ist (''3D-Effekt''). Die Scheinwerfer erhielten eine neue Innenstruktur mit serienmäßigen Xenon plus-Einheiten und optionalen LED-Scheinwerfern. Die Heckleuchten wurden ebenfalls leicht modifiziert und erhielten eine neue Lichtsignatur. Zudem wurden die Stoßfänger vorne und hinten dezent angepasst.',NULL,NULL,NULL,5,2011,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-q3-f3','Audi','RS Q3','F3',2019,NULL,'["SUV", "Sportback"]','Kompakt-SUV','audi-rs-q3-8u','Die zweite Generation des Audi RS Q3 (F3) ist deutlich aggressiver und kantiger gestaltet als ihr Vorgänger. Sie zeichnet sich durch einen breiteren, rahmenlosen Singleframe-Grill mit Wabenstruktur, große Lufteinlässe und schmale, keilförmige LED-Scheinwerfer aus. Am Heck fallen die breiten Radhäuser, der markante Dachkantenspoiler und die großen ovalen RS-Abgasendrohre auf. Die Sportback-Variante besitzt eine coupéartige Dachlinie.',NULL,NULL,NULL,NULL,5,2018,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-rs-q8-4m','Audi','RS Q8','4M',2020,NULL,'["SUV"]','Oberklasse-SUV',NULL,'Der Audi RS Q8 4M ist die Hochleistungsversion des Audi Q8. Er zeichnet sich durch eine deutlich aggressivere Frontpartie mit einem RS-spezifischen Singleframe-Kühlergrill in Wabenstruktur und großen seitlichen Lufteinlässen aus. Die Radhäuser sind im Vergleich zum Standard-Q8 deutlich verbreitert, und am Heck fallen der RS-spezifische Diffusor sowie die zwei großen ovalen RS-Endrohre auf. Die Matrix-LED-Scheinwerfer und LED-Heckleuchten sind serienmäßig.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-tt-rs-8j','Audi','TT RS','8J',2009,2014,'["Coupé", "Roadster"]','Kompaktsportwagen',NULL,'Der Audi TT RS der Generation 8J basiert auf der zweiten Generation des Audi TT. Er unterscheidet sich von den zivileren TT-Modellen durch eine aggressivere Frontschürze mit größeren Lufteinlässen und einem Wabengrill, der das ''TT RS''-Logo trägt. Am Heck sind zwei ovale Endrohre und ein feststehender Heckspoiler (optional, aber häufig) oder ein automatisch ausfahrender Spoiler charakteristisch. Die Karosserielinien sind im Vergleich zum Vorgänger (8N) schärfer und weniger rundlich.','Im Jahr 2012 wurde der TT RS als ''plus''-Modell eingeführt. Dieses bot eine Leistungssteigerung und optische Details wie schwarze Außenspiegelgehäuse, einen schwarzen Kühlergrillrahmen und spezielle 19-Zoll-Räder. Es handelte sich jedoch nicht um ein umfassendes Facelift mit signifikanten Änderungen an Scheinwerfern oder Karosserieblechen.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-tt-rs-fv/8s','Audi','TT RS','FV/8S',2016,2023,'["Coupé", "Roadster"]','Sportwagen','audi-tt-rs-8j','Der Audi TT RS FV/8S zeichnet sich durch schärfere, kantigere Linien im Vergleich zum Vorgänger aus. Auffällig sind die serienmäßigen Matrix-LED-Scheinwerfer (optional OLED-Rückleuchten), der breitere Singleframe-Kühlergrill mit Wabenstruktur und der feststehende Heckflügel (optional). Die Frontschürze ist aggressiver gestaltet mit größeren Lufteinlässen.','Das Facelift im Jahr 2019 brachte eine nochmals geschärfte Optik mit sich. Die Frontschürze wurde neu gestaltet, mit vertikalen Stegen in den seitlichen Lufteinlässen und einem durchgehenden Blade unterhalb des Kühlergrills. Am Heck wurden die Diffusoreinsätze markanter und die Endrohre der Abgasanlage leicht angepasst. Die OLED-Rückleuchten waren nun serienmäßig.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-tt-typ-8j','Audi','TT','Typ 8J',2006,2014,'["Coupé", "Roadster"]','Sportwagen','audi-tt-typ-8n','Der Audi TT Typ 8J unterscheidet sich vom Vorgänger (Typ 8N) durch eine deutlich schärfere Linienführung, größere Abmessungen und eine breitere Spur. Auffällig sind die neu gestalteten Scheinwerfer mit optionalen LED-Tagfahrlichtern, der größere Singleframe-Kühlergrill und die markanteren Seitenlinien. Das Heck wirkt moderner mit neuen Rückleuchten und einem integrierten Diffusor.','Das Facelift im Jahr 2010 brachte eine überarbeitete Front mit neuem Kühlergrill und Scheinwerfern, geänderte Stoßfänger, neue Außenspiegel mit integrierten Blinkern und ein überarbeitetes Heck. Im Innenraum gab es kleinere Änderungen an Materialien und Bedienelementen.',NULL,NULL,NULL,5,2006,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-tt-typ-8n','Audi','TT','Typ 8N',1998,2006,'["Coupé", "Roadster"]','Sportwagen',NULL,'Der Audi TT Typ 8N ist die erste Generation des Audi TT. Charakteristisch sind die abgerundeten Formen, die kugelförmige Heckpartie und die markante Tankklappe im Stil eines Rennwagens. Die Scheinwerfer sind rundlich und die Heckleuchten ebenfalls abgerundet. Im Vergleich zu späteren Generationen wirkt das Design deutlich "knubbeliger" und weniger scharfkantig.','Im Jahr 2003 erhielt der TT Typ 8N ein Facelift. Äußerlich erkennbar an leicht überarbeiteten Scheinwerfern und Rückleuchten, einer geänderten Frontschürze und neuen Felgendesigns. Technisch gab es unter anderem eine Leistungssteigerung bei einigen Motoren und ein strafferes Fahrwerk.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der Audi TT Typ 8N ist ein ikonischer Sportwagen, der heute als Youngtimer interessant ist. Achten Sie auf Rost, insbesondere an den Radläufen und Schwellern. Bei den frühen Modellen mit dem 1.8T Motor kann der Zahnriemenwechsel kritisch sein. Getriebe und Kupplung können bei sportlicher Fahrweise verschleißen. Die Quattro-Modelle sind generell robuster, aber auch teurer in der Wartung. Die Fahrwerkskomponenten sind anfällig für Verschleiß.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('audi-tt-typ-fv','Audi','TT','Typ FV',2014,2023,'["Coupé", "Roadster"]','Kompaktsportwagen','audi-tt-typ-8j','Der Audi TT Typ FV (3. Generation) zeichnet sich durch ein deutlich kantigeres und schärferes Design im Vergleich zum runderen Vorgänger Typ 8J aus. Die Front ist geprägt von einem flacheren, breiteren Singleframe-Kühlergrill und serienmäßigen Xenon-Scheinwerfern (optional LED oder Matrix-LED). Die Seitenlinie ist straffer, und das Heck wirkt durch die horizontalen Linien und die schmaleren Rückleuchten breiter. Im Innenraum ist das Audi Virtual Cockpit (voll digitales Kombiinstrument) ein zentrales und sofort erkennbares Merkmal, da es das zentrale MMI-Display auf der Mittelkonsole ersetzt.','Im Jahr 2018 erhielt der Audi TT Typ FV ein Facelift. Äußerlich erkennbar an einem modifizierten Singleframe-Kühlergrill mit dreidimensionaler Gitterstruktur, größeren seitlichen Lufteinlässen und einem überarbeiteten Heckdiffusor. Die Endrohre wurden je nach Motorisierung angepasst (zwei runde Endrohre für die 40 TFSI und 45 TFSI Modelle, ovale Endrohre für den TTS). Neue Lackfarben und Felgendesigns wurden ebenfalls eingeführt.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-1er-e87','BMW','1er','E87',2004,2011,'["Schrägheck 5-Türer"]','Kompaktklasse','BMW 3er Compact (E46/5)','Der BMW E87 ist die erste Generation des 1er und zeichnet sich durch seine typischen BMW-Proportionen aus: lange Motorhaube, kurzer vorderer Überhang und ein nach hinten versetztes Greenhouse. Charakteristisch sind die markanten Frontscheinwerfer, die oft als ''Tränenaugen'' oder ''Böser Blick'' bezeichnet werden, die Doppelniere und die L-förmigen Heckleuchten. Die Seitenlinie ist sportlich-keilförmig mit dem typischen Hofmeister-Knick an der C-Säule.','Das Facelift (LCI) im Jahr 2007 brachte dezente, aber sichtbare Änderungen mit sich. Die Frontschürze wurde neu gestaltet, die Niere erhielt eine leicht modifizierte Form und die Scheinwerfer-Inlays wurden überarbeitet. Am Heck wurden die Stoßfänger und die Heckleuchten neu gestaltet, wobei die Rückleuchten nun LED-Technik für die Bremslichter nutzten. Im Innenraum gab es neue Materialien und leichte Anpassungen am Armaturenbrett und den Bedienelementen.','Durchschnittlich bis gut, mit einigen Auffälligkeiten bei bestimmten Baujahren und Motoren (z.B. Steuerkette N47).','Über dem Durchschnitt in den ersten Jahren, später leicht erhöhte Mängelquoten bei Fahrwerk, Beleuchtung und Bremsen.','Gute Langzeitqualität, aber mit bekannten Schwachstellen bei Fahrwerk und Elektrik. Motoren (insbesondere N47 Diesel) erfordern Aufmerksamkeit.',5,2004,25000,'Alle 2 Jahre','Der BMW 1er E87 bietet ein sportliches Fahrerlebnis mit Heckantrieb in der Kompaktklasse. Beim Kauf sollte man besonders auf die Servicehistorie achten, da einige Motoren (insbesondere der N47 Diesel) für Steuerkettenprobleme bekannt sind. Auch Fahrwerkskomponenten (Querlenker, Stoßdämpfer) und die Elektrik können im Alter Probleme bereiten. Rost ist selten ein Thema. Modelle nach dem Facelift (ab 2007) sind oft ausgereifter und sparsamer.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-1er-f20-f21','BMW','1er','F20/F21',2011,2019,'["5-Türer Schrägheck", "3-Türer Schrägheck"]','Kompaktklasse','BMW 1er E87/E81','Charakteristisch sind die flachen, breiten Scheinwerfer, die vor dem Facelift bis an die Niere reichen und eine leicht ''traurige'' Optik aufweisen. Die Niere ist breiter und flacher als beim Vorgänger E8x. Am Heck fallen die L-förmigen Heckleuchten auf, die sich in die Heckklappe ziehen. Die Silhouette ist deutlich dynamischer und keilförmiger als beim E8x, mit einer längeren Motorhaube und kurzen Überhängen.','Das Facelift (LCI) im Jahr 2015 brachte eine umfassende Überarbeitung der Front- und Heckpartie. Vorne wurden die Scheinwerfer komplett neu gestaltet, sie sind nun schmaler, schärfer gezeichnet und serienmäßig mit LED-Tagfahrlicht ausgestattet (optional Voll-LED). Die Frontschürze erhielt größere Lufteinlässe. Am Heck wurden die Heckleuchten ebenfalls komplett neu gestaltet, sie sind nun breiter und zweigeteilt, mit einer markanten L-Form im LED-Design. Die Heckschürze wurde ebenfalls modifiziert.','mittel','Durchschnittlich bis leicht überdurchschnittlich, insbesondere bei älteren Modellen und höheren Laufleistungen. Achsaufhängung und Beleuchtung sind häufiger Mängelpunkte.','Durchschnittlich, mit Stärken bei Fahrwerk und Bremsen, aber Schwächen bei der Elektronik und dem Ölverlust bei älteren Dieseln.',5,2012,30000,'Alle 2 Jahre','Der BMW 1er F20/F21 bietet ein sportliches Fahrerlebnis mit Hinterradantrieb in der Kompaktklasse. Besonders die Sechszylinder-Modelle (M135i/M140i) sind begehrt. Beim Kauf sollte auf die Servicehistorie geachtet werden, insbesondere bei den N47-Dieselmotoren (Steuerkette) und den frühen N20-Benzinern (ebenfalls Steuerkette). Ölverlust und Probleme mit der Wasserpumpe sind weitere bekannte Schwachstellen. Das Facelift (LCI) ab 2015 brachte nicht nur optische Verbesserungen, sondern auch überarbeitete Motoren (B-Serie), die als zuverlässiger gelten. Eine Probefahrt ist unerlässlich, um auf ungewöhnliche Geräusche oder Ruckeln zu achten.','2026-06','{"F20": "5-Türer Schrägheck", "F21": "3-Türer Schrägheck"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-1er-f40','BMW','1er','F40',2019,NULL,'["Schrägheck"]','Kompaktklasse','BMW 1er F20/F21','Der F40 ist die erste 1er Generation mit Frontantrieb und quer eingebautem Motor. Optisch zeichnet er sich durch eine breitere, einteilige Niere aus, die nicht mehr mit den Scheinwerfern verbunden ist. Die Scheinwerfer sind flacher und breiter als beim Vorgänger F20, oft mit einer markanten LED-Tagfahrlichtsignatur. Die Proportionen wirken kompakter und weniger langgestreckt als beim Heckantriebs-Vorgänger, mit einer kürzeren Motorhaube und einem geräumigeren Innenraum. Die Heckleuchten sind breiter und zweigeteilt, reichen in die Heckklappe hinein.','Das Facelift (LCI) des F40, eingeführt im Jahr 2024, bringt eine umfassende Überarbeitung des Designs mit sich. Die Frontpartie erhält eine neu gestaltete Niere mit vertikalen und diagonalen Streben sowie eine deutlich modifizierte Frontschürze mit größeren Lufteinlässen. Die Scheinwerfer sind schlanker und verfügen über eine neue LED-Grafik. Am Heck wurden die Leuchten ebenfalls neu gestaltet, mit einer markanteren L-Form und einer überarbeiteten Heckschürze, die je nach Ausstattungslinie unterschiedliche Diffusor-Elemente aufweist. Im Innenraum wurde das Curved Display mit iDrive 8.5 eingeführt, das die bisherigen separaten Displays ersetzt.',NULL,NULL,NULL,5,2019,30000,'Alle 2 Jahre','Der BMW 1er F40 bietet eine gute Mischung aus Sportlichkeit und Alltagstauglichkeit. Als Gebrauchtwagen ist er aufgrund seines jungen Alters und der BMW-typischen Qualität meist eine sichere Wahl. Achten Sie auf die Ausstattungslinie, da diese den Charakter des Fahrzeugs stark prägt. Der Frontantrieb macht ihn im Alltag handlicher, auch wenn Puristen den Heckantrieb vermissen. Die Motoren sind effizient und leistungsstark. Prüfen Sie die Servicehistorie und eventuelle Software-Updates, insbesondere bei frühen Baujahren. Die M135i- und 128ti-Modelle bieten viel Fahrspaß, sind aber auch teurer im Unterhalt.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-2er-active-tourer-f45','BMW','2er Active Tourer','F45',2014,2021,'["Kompaktvan"]','Kompaktvan',NULL,'Erste Generation des 2er Active Tourer. Erkennbar an der BMW-typischen Niere, aber mit Frontantrieb und höherer Karosserieform im Vergleich zu anderen BMW-Modellen.','Im März 2018 gab es ein Facelift (LCI) mit modifizierten Front- und Heckschürzen, neuen LED-Scheinwerfern und -Rückleuchten, sowie überarbeiteten Motoren und Infotainmentsystemen.','Gut','Durchschnittlich bis gut, Bremsen und Fahrwerk sind oft unauffällig, Beleuchtung und Ölverlust können Mängel verursachen.','Überwiegend positiv, geringe Mängelquote bei Fahrwerk und Lenkung. Bremsen und Beleuchtung sind die häufigsten Beanstandungen.',5,2014,25000,'Alle 2 Jahre','Der BMW 2er Active Tourer (F45) ist ein praktischer Kompaktvan mit BMW-typischer Fahrqualität, aber Frontantrieb. Er bietet viel Platz und eine gute Ausstattung. Achten sollte man auf die Wartungshistorie, insbesondere bei den Dieselmotoren (Steuerkette) und den Automatikgetrieben. Das Facelift-Modell ab 2018 ist technisch ausgereifter. Ein gutes Familienauto für diejenigen, die Wert auf Komfort und ein hochwertiges Interieur legen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-2er-active-tourer-u06','BMW','2er Active Tourer','U06',2021,NULL,'["Kompaktvan"]','Kompaktklasse','BMW 2er Active Tourer F45','Deutlich größere BMW Niere, flachere LED-Scheinwerfer, bündige Türgriffe, schlankere LED-Rückleuchten.',NULL,NULL,NULL,NULL,5,2022,30000,'Alle 2 Jahre','Der BMW 2er Active Tourer (U06) ist ein kompakter Van, der auf der UKL2-Plattform basiert und somit Front- oder Allradantrieb bietet. Er zeichnet sich durch ein modernes Interieur mit Curved Display und iDrive 8 (später iDrive 8.5) aus. Die Motorenpalette umfasst Benzin-, Diesel- und Plug-in-Hybrid-Varianten. Er bietet ein gutes Raumangebot und hohen Fahrkomfort, ist aber nicht so sportlich wie andere BMW-Modelle. Die Plug-in-Hybrid-Modelle bieten eine gute elektrische Reichweite.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-2er-coupe-f22','BMW','2er Coupé','F22',2013,2021,'["Coupé"]','Kompaktklasse','BMW 1er Coupé E82','Das F22 Coupé ist die erste Generation des BMW 2er Coupés. Es basiert auf der Plattform des F20/F21 1er und unterscheidet sich durch eine eigenständige Karosserie mit zwei Türen und einem sportlicheren Design.','Im Juli 2017 (LCI) gab es ein leichtes Facelift mit neuen LED-Scheinwerfern und -Rückleuchten, überarbeiteten Interieur-Details und neuen Lackfarben/Felgenoptionen.',NULL,NULL,NULL,5,2014,30000,'Alle 2 Jahre','Der BMW 2er Coupé F22 ist ein beliebtes Fahrzeug für Fahrer, die ein kompaktes, sportliches Coupé mit Heckantrieb suchen. Die Motorenpalette reicht von sparsamen Vierzylindern bis zu leistungsstarken Sechszylindern. Achten Sie beim Kauf auf die Wartungshistorie, insbesondere bei den stärkeren Motoren. Typische Schwachstellen sind die Steuerkette bei frühen N20-Motoren und gelegentliche Probleme mit der Elektrik.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-2er-coupe-g42','BMW','2er Coupé','G42',2021,NULL,'["Coupé"]','Kompaktklasse','BMW 2er Coupé F22','Deutlich aggressiveres Design als der Vorgänger, breitere Niere, neue Scheinwerferform, keine durchgehende Lichtleiste am Heck.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre','Der BMW 2er Coupé G42 ist ein sportliches Kompaktcoupé mit klassischem Hinterradantrieb (oder Allrad) und längs eingebauten Motoren. Er bietet eine gute Fahrdynamik und hochwertige Materialien im Innenraum. Die Motorenpalette reicht von effizienten Vierzylindern bis zum leistungsstarken M240i mit Reihensechszylinder. Der Kofferraum ist für ein Coupé ausreichend, die Rücksitze eher für kurze Strecken geeignet. Achten Sie auf die Ausstattung, da viele Features optional sind.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-2er-gran-coupe-f44','BMW','2er Gran Coupé','F44',2019,NULL,'["Limousine"]','Kompaktklasse',NULL,'Viertüriges Coupé auf Basis der UKL2-Plattform (Frontantrieb), erkennbar an rahmenlosen Scheiben und flacherer Dachlinie im Vergleich zum 1er F40.',NULL,NULL,NULL,NULL,5,2019,30000,'Alle 2 Jahre','Das BMW 2er Gran Coupé (F44) ist eine stilvolle Alternative zum klassischen Kompaktwagen, die auf der Frontantriebsplattform des 1er F40 basiert. Es bietet ein sportliches Design mit rahmenlosen Türen und einer coupéartigen Dachlinie. Der Innenraum ist modern und hochwertig, jedoch ist der Platz auf den Rücksitzen und im Kofferraum aufgrund der Karosserieform eingeschränkter als beim 1er. Die Motorenpalette reicht von effizienten Dreizylindern bis zum sportlichen M235i xDrive. Beim Kauf sollte auf die Ausstattung geachtet werden, da viele Features optional waren. Die Zuverlässigkeit ist generell gut, jedoch können frühe Modelle von Softwareproblemen betroffen sein. Eine Probefahrt ist empfehlenswert, um das Fahrverhalten und den Komfort zu beurteilen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-e21','BMW','3er','E21',1975,1983,'["Limousine"]','Kompaktklasse','bmw-02er-e10','Der BMW E21 ist die erste Generation des 3er. Er zeichnet sich durch seine keilförmige Karosserie, die charakteristischen runden Doppelscheinwerfer (bei den stärkeren Modellen, Basismodelle hatten Einzelscheinwerfer) und die nach vorne geneigte BMW-Niere aus. Im Vergleich zum Vorgänger, dem 02er, wirkt der E21 moderner und aerodynamischer, mit einer stärker ausgeprägten C-Säule und einem integrierteren Kofferraum. Die Heckleuchten sind rechteckig und horizontal ausgerichtet.','Ein leichtes Facelift erfolgte 1979. Die auffälligste Änderung war die Überarbeitung des Innenraums, insbesondere des Armaturenbretts, das nun eine modernere Optik erhielt. Äußerlich gab es nur minimale Anpassungen, wie zum Beispiel leicht modifizierte Stoßfänger und eine verbesserte Aerodynamik durch kleine Spoilerlippen an der Frontschürze bei einigen Modellen.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-e30','BMW','3er','E30',1982,1994,'["Limousine", "Coupé", "Cabriolet", "Touring"]','Kompaktklasse','bmw-3er-e21','Der E30 unterscheidet sich vom Vorgänger E21 durch die kantigere Linienführung, die nun rechteckigen Scheinwerfer (bei vielen Modellen), die breiteren Stoßstangen und die Einführung der Touring-Karosserie. Die Heckleuchten sind beim E30 meist größer und haben ein charakteristisches Wabenmuster.','Das erste Facelift (oft als ''Mopf 1'' bezeichnet) fand 1987 statt und brachte überarbeitete Stoßstangen (breitere Kunststoffstoßstangen, die sogenannten ''breiten Lippen''), neue Scheinwerferdesigns und modifizierte Heckleuchten. Ein weiteres, kleineres Facelift (oft ''Mopf 2'' genannt) folgte 1989 mit weiteren Detailänderungen an Front und Heck.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der BMW E30 gilt als Klassiker und ist bei Liebhabern sehr beliebt. Achten Sie auf Rost, insbesondere an den Radläufen, Schwellern und der Heckklappe. Die Motoren sind generell robust, aber regelmäßige Wartung ist entscheidend. Die Fahrwerkskomponenten können Verschleißerscheinungen zeigen. Modelle mit M-Technik oder die M3-Variante sind besonders gesucht.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-e36','BMW','3er','E36',1990,2000,'["Limousine", "Coupe", "Cabrio", "Touring", "Compact"]','Mittelklasse','E30','Runde, aerodynamische Karosserie mit fließenden Linien. Klappscheinwerfer entfallen, stattdessen feste Einfach-Scheinwerfer. Breitere Spur als E30.','1996: Neue Scheinwerfer, überarbeitete Stoßfänger',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2025-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-e46','BMW','3er','E46',1998,2007,'["Limousine", "Coupé", "Cabrio", "Touring", "Compact"]','Mittelklasse','BMW 3er E36','Der E46 zeichnet sich durch eine rundlichere, fließendere Formgebung im Vergleich zum kantigeren E36 aus. Die Scheinwerfer sind nicht mehr durch eine gemeinsame Glasabdeckung verbunden, sondern einzeln in die Karosserie integriert und haben eine leicht geschwungene Unterkante. Die BMW-Niere ist breiter und stärker in die Motorhaube integriert. Die Seitenlinie wirkt eleganter und weniger keilförmig.','Limousine und Touring (ab Herbst 2001): Neu gestaltete Scheinwerfer mit leicht nach oben gezogener Unterkante (sogenannte ''Tränen''), geänderte Nieren, neue Frontschürze mit runderen Nebelscheinwerfern, modifizierte Heckleuchten mit LED-Technik (teilweise), neue Heckschürze. Coupé und Cabrio (ab Frühjahr 2003): Neu gestaltete Scheinwerfer mit leicht veränderter Form und integrierten Blinkern, geänderte Nieren, neue Frontschürze, modifizierte Heckleuchten mit LED-Technik, neue Heckschürze.',NULL,NULL,NULL,4,2001,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-e90','BMW','3er','E90',2005,2011,'["Limousine"]','Mittelklasse','bmw-3er-e46','Der E90 unterscheidet sich vom Vorgänger E46 durch eine deutlich schärfere und kantigere Linienführung. Die Scheinwerfer sind größer und aggressiver gezeichnet, oft mit den charakteristischen ''Angel Eyes'' als Tagfahrlicht. Die Niere ist breiter und flacher. Am Heck fallen die L-förmigen Rückleuchten auf, die sich in die Kofferraumklappe ziehen.','Das Facelift (LCI) im September 2008 brachte eine neu gestaltete Frontschürze mit größeren Lufteinlässen, eine breitere Niere und neu geformte Scheinwerfer, die bei Xenon-Ausstattung LED-Tagfahrlichtringe integrierten. Die Motorhaube erhielt markantere Sicken. Am Heck wurden die Rückleuchten überarbeitet und erhielten eine LED-Lichttechnik. Auch die Heckschürze wurde leicht modifiziert.',NULL,NULL,NULL,5,2005,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-f30','BMW','3er','F30',2011,2018,'["Limousine"]','Mittelklasse','bmw-3er-e90','Die F30-Generation zeichnet sich durch ihre breitere und flachere Niere aus, die direkt mit den Scheinwerfern verbunden ist. Die Scheinwerfer selbst sind schmaler und ziehen sich bis zur Niere. Im Vergleich zum Vorgänger E90 wirkt die Front dynamischer und die Seitenlinie ist durch eine markante Doppelsicke geprägt, die von den vorderen Radläufen bis zu den Rückleuchten verläuft. Die Heckleuchten sind L-förmig und breiter als beim E90.','Das Facelift (LCI) im Juli 2015 brachte leichte optische Änderungen mit sich: Die Frontschürze wurde überarbeitet, die LED-Tagfahrlichter sind nun serienmäßig und die optionalen Voll-LED-Scheinwerfer erhielten eine neue Grafik. Am Heck wurden die LED-Rückleuchten ebenfalls neu gestaltet und die Heckschürze leicht modifiziert. Im Innenraum gab es kleinere Detailänderungen und neue Zierleisten.',NULL,NULL,NULL,5,2012,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-3er-g20-g21','BMW','3er','G20/G21',2019,NULL,'["Limousine", "Touring"]','Mittelklasse','bmw-3er-f30','Die siebte Generation des BMW 3er (G20 Limousine, G21 Touring) zeichnet sich durch eine deutlich größere, einteilige Doppelniere, schärfere Linienführung und serienmäßige LED-Scheinwerfer aus. Im Vergleich zum Vorgänger F30/F31 ist er länger, breiter und flacher, mit einem sportlicheren Auftritt und einer moderneren Innenraumgestaltung.','Das Facelift (LCI - Life Cycle Impulse) im Jahr 2022 brachte eine neu gestaltete Frontschürze, schlankere LED-Scheinwerfer mit umgedrehtem Tagfahrlicht-Design, eine überarbeitete Heckschürze und vor allem das Curved Display im Innenraum, das das digitale Kombiinstrument und den Infotainment-Bildschirm zu einer Einheit verbindet (iDrive 8).',NULL,NULL,NULL,5,2019,25000,'Alle 2 Jahre','Der BMW 3er G20/G21 bietet eine exzellente Kombination aus sportlicher Fahrdynamik, hohem Fahrkomfort und hochwertiger Verarbeitung. Die Motorenpalette ist breit gefächert und umfasst effiziente Mild-Hybrid-Aggregate (ab 2020/2021) sowie leistungsstarke M Performance Modelle und Plug-in-Hybride. Frühe Modelle können von Software-Updates profitieren. Bei Plug-in-Hybriden (330e) sollte die Historie der Hochvoltbatterie geprüft werden. Generell gilt der G20/G21 als zuverlässig, jedoch können bei sportlicher Fahrweise Bremsen und Reifen stärker verschleißen. Achten Sie auf eine lückenlose Wartungshistorie.','2026-06','{"G20": "Limousine", "G21": "Touring"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-4er-f32-f33-f36','BMW','4er','F32/F33/F36',2013,2020,'["Coupé", "Cabrio", "Gran Coupé"]','Mittelklasse','BMW 3er E92/E93','Die 4er-Reihe wurde als eigenständige Baureihe vom 3er abgeleitet, um die Coupé-, Cabrio- und Gran Coupé-Varianten sportlicher zu positionieren. Interne Codes F32 (Coupé), F33 (Cabrio), F36 (Gran Coupé).','Im Frühjahr 2017 (LCI - Life Cycle Impulse) gab es ein Facelift mit leicht modifizierten LED-Scheinwerfern und -Rückleuchten, überarbeiteten Stoßfängern, neuen Felgendesigns und kleineren Änderungen im Innenraum (z.B. neue Zierleisten, iDrive-Controller).','Gut bis sehr gut, wenige Ausfälle. Typische Probleme sind eher alters- und laufleistungsbedingt.','Unterdurchschnittlich gut, oft besser als der Durchschnitt der jeweiligen Altersklasse. Bremsen und Fahrwerk sind die häufigsten Mängelpunkte, aber auf niedrigem Niveau.','Gut, überdurchschnittlich wenige Mängel. Fahrwerk und Bremsen sind die häufigsten Beanstandungen, aber meist geringfügig.',5,2012,25000,'Alle 2 Jahre','Der BMW 4er F3x bietet eine sportliche Alternative zum 3er mit eigenständigem Design. Die Motorenpalette ist breit und reicht von sparsamen Vierzylindern bis zu kräftigen Sechszylindern. Das Fahrwerk ist straff, aber komfortabel genug für den Alltag. Beim Gebrauchtwagenkauf auf die Historie achten, besonders bei leistungsstarken Modellen. Die Verarbeitungsqualität ist hoch. Das Gran Coupé bietet eine gute Mischung aus Sportlichkeit und Alltagstauglichkeit mit vier Türen und großer Heckklappe.','2026-06','{"F32": "Coupé", "F33": "Cabrio", "F36": "Gran Coupé"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-4er-g22-g23-g26','BMW','4er','G22/G23/G26',2020,NULL,'["Coupé", "Cabrio", "Gran Coupé"]','Obere Mittelklasse','F32/F33/F36','Die G2x-Generation des 4er BMW ist sofort an der markanten, großen und vertikal ausgerichteten Doppelniere zu erkennen, die sich über die gesamte Höhe der Front erstreckt. Im Vergleich zum Vorgänger F3x sind die Scheinwerfer schmaler und schärfer gezeichnet. Die G26 Gran Coupé-Variante verfügt über rahmenlose Türen und eine Fließheck-Karosserie.','Ein Facelift (LCI) für G22/G23 erfolgte im Jahr 2024. Merkmale sind neu gestaltete Scheinwerfer (optional mit Laserlicht), leicht modifizierte Heckleuchten, neue Felgendesigns und im Innenraum das Curved Display mit iDrive 8.5.',NULL,NULL,NULL,5,2019,25000,'Alle 2 Jahre','Der BMW 4er der G2x-Generation bietet eine sportliche Fahrdynamik und eine hochwertige Verarbeitung. Die Motorenpalette ist breit gefächert und reicht von effizienten Vierzylindern bis zu leistungsstarken Sechszylindern und den M-Modellen. Beim Kauf sollte auf die Ausstattung geachtet werden, da viele Komfort- und Assistenzsysteme optional waren. Die große Niere ist Geschmackssache, aber das Fahrwerk und die Lenkung sind typisch BMW sportlich-präzise. Bei Gebrauchtwagen auf Scheckheftpflege und eventuelle Rückrufe achten. Die iDrive-Systeme sind intuitiv bedienbar und bieten moderne Konnektivität.','2026-06','{"G22": "Coupé", "G23": "Cabrio", "G26": "Gran Coupé"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-e12','BMW','5er','E12',1972,1981,'["Limousine"]','Obere Mittelklasse','bmw-neue-klasse','Der BMW E12 ist die erste Generation des 5er. Er zeichnet sich durch seine klassische, kantige Limousinenform mit dem charakteristischen Hofmeister-Knick an der C-Säule aus. Die Front wird von den typischen Doppelrundscheinwerfern und einer schmalen BMW-Niere dominiert. Im Vergleich zum Vorgänger (Neue Klasse) wirkt er moderner und fließender, aber noch nicht so aerodynamisch wie spätere Generationen.','Das Facelift im Jahr 1976 brachte dezente Änderungen mit sich. Die auffälligsten Merkmale sind die neu gestalteten Rückleuchten, die nun breiter und flacher waren. Die Front erhielt eine leicht modifizierte Niere und eine geänderte Motorhaube, die sich bis zur Frontschürze zog. Im Innenraum wurden das Armaturenbrett und die Mittelkonsole überarbeitet, um ergonomischer zu sein.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-e28','BMW','5er','E28',1981,1987,'["Limousine"]','Obere Mittelklasse','bmw-5er-e12','Der BMW E28 ist der Nachfolger des E12 und zeichnet sich durch eine kantigere, aber aerodynamischere Karosserie aus. Die Frontpartie behält die BMW-typischen Doppelrundscheinwerfer, die jedoch flacher und stärker in die Karosserie integriert sind als beim Vorgänger. Die Niere ist breiter und flacher. Am Heck sind die Leuchten ebenfalls breiter und weniger hoch als beim E12. Im Innenraum ist das Cockpit stärker zum Fahrer hin ausgerichtet.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-e34','BMW','5er','E34',1988,1996,'["Limousine", "Touring"]','Obere Mittelklasse','bmw-5er-e28','Der E34 zeichnet sich durch eine kantigere, aber aerodynamischere Form als sein Vorgänger E28 aus. Typisch sind die vier runden Scheinwerfer, die von einer breiten Niere flankiert werden, sowie die flache, breite Motorhaube. Im Vergleich zum Nachfolger E39 fehlen die ''Angel Eyes'' und die Niere ist schmaler und höher.','Ein größeres Facelift fand nicht statt, aber es gab kontinuierliche Modellpflegemaßnahmen. Ab 1992 wurden die Nieren breiter (sogenannte ''breite Niere''), die Außenspiegel aerodynamischer und die Motorenpalette wurde überarbeitet (Einführung der M50-Motoren mit VANOS).',NULL,NULL,NULL,NULL,NULL,10000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-e39','BMW','5er','E39',1995,2003,'["Limousine", "Touring"]','Obere Mittelklasse','bmw-5er-e34','Der BMW E39 zeichnet sich durch seine runden, klaren Doppelscheinwerfer aus, die unter einer gemeinsamen Glasabdeckung liegen und nicht mehr wie beim Vorgänger E34 einzeln eingefasst sind. Die Niere ist breiter und flacher. Die Karosserie wirkt insgesamt fließender und weniger kantig als beim E34, mit einer stärker ausgeprägten Keilform und einer sanfter abfallenden Dachlinie. Die Seitenlinie ist durch eine markante Sicke unterhalb der Fenster und eine integrierte Stoßfängergestaltung geprägt.','Das Facelift (LCI) im September 2000 brachte geänderte Scheinwerfer mit Corona-Ringen (Angel Eyes) und weißen Blinkergläsern vorne, neue Rückleuchten mit LED-Technik (Lichtleiter) und weißen Blinkergläsern hinten. Die Frontschürze wurde leicht modifiziert, und die Nebelscheinwerfer erhielten eine runde Form anstelle der bisherigen rechteckigen. Auch die Niere wurde dezent überarbeitet.',NULL,NULL,NULL,4,1998,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-e60','BMW','5er','E60',2003,2010,'["Limousine", "Touring"]','Obere Mittelklasse','bmw-5er-e39','Die E60/E61-Generation ist bekannt für ihr kontroverses "Bangle-Design", insbesondere das Heck der Limousine mit der markanten, stufenförmigen Kofferraumklappe. Die Front zeichnet sich durch leicht nach oben gezogene Doppelscheinwerfer mit den typischen BMW "Angel Eyes" (Coronaringen) aus. Im Vergleich zum Vorgänger E39 wirkt der E60 deutlich kantiger und moderner, mit einer stärker ausgeprägten Keilform und einem iDrive-Controller in der Mittelkonsole.','Das Facelift (LCI - Life Cycle Impulse) im März 2007 brachte dezente Änderungen mit sich. Dazu gehören leicht modifizierte Front- und Heckschürzen, überarbeitete Scheinwerfer mit LED-Tagfahrlicht und LED-Rückleuchten mit neuem Leuchtendesign. Im Innenraum wurden die Türverkleidungen, das iDrive-System (nun mit Favoritentasten) und die Materialauswahl überarbeitet. Auch die Motorenpalette wurde aktualisiert, unter anderem mit der Einführung von EfficientDynamics-Technologien.',NULL,NULL,NULL,4,2004,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-f10','BMW','5er','F10',2010,2016,'["Limousine"]','Obere Mittelklasse','bmw-5er-e60','Der BMW 5er F10 zeichnet sich durch eine flachere und breitere Niere im Vergleich zum Vorgänger E60 aus. Die Scheinwerfer sind ebenfalls flacher und breiter gestaltet, oft mit den charakteristischen Corona-Ringen (Angel Eyes). Die Karosserie wirkt klassischer und weniger polarisierend als der E60, mit einer markanten Sicke, die sich von den vorderen Radläufen bis zu den Rückleuchten zieht. Das Heck ist weniger kantig als beim E60 und integriert die Rückleuchten harmonischer in die Gesamtform.','Das Facelift (LCI) im Jahr 2013 brachte leicht überarbeitete Scheinwerfer (optional mit Voll-LED-Technik) und Blinker, die nun in die Außenspiegel integriert wurden. Die Frontschürze wurde mit neu gestalteten Lufteinlässen modifiziert. Am Heck gab es eine leicht angepasste Heckschürze und Rückleuchten mit einer neuen LED-Grafik. Im Innenraum wurden kleinere Detailänderungen vorgenommen, wie zum Beispiel Chromapplikationen und neue Polsteroptionen.',NULL,NULL,NULL,5,2010,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-5er-g30','BMW','5er','G30',2017,2023,'["Limousine"]','Obere Mittelklasse','bmw-5er-f10','Der BMW 5er G30 ist an seiner schärfer gezeichneten Front mit den direkt an die Niere anschließenden Scheinwerfern zu erkennen, die im Vergleich zum Vorgänger F10 flacher und breiter wirken. Die Niere selbst ist größer und dreidimensionaler gestaltet. Die Seitenlinie ist eleganter und gestreckter, mit einer markanten Sicke, die von den vorderen Radhäusern bis zu den Rückleuchten verläuft. Die Heckleuchten sind breiter und reichen weiter in die Kofferraumklappe hinein, mit einer L-förmigen LED-Grafik.','Das Facelift (LCI) im Jahr 2020 brachte eine überarbeitete Front mit flacheren, neu gestalteten Scheinwerfern, die serienmäßig LED-Technik und optional Laserlicht erhielten. Die BMW Niere wurde breiter und höher. Die vorderen Stoßfänger wurden neu geformt, mit größeren Lufteinlässen. Am Heck wurden die Rückleuchten mit einer neuen, dreidimensionalen Lichtsignatur und dunkleren Abdeckungen versehen. Die Heckschürze wurde ebenfalls modifiziert, und die Endrohrblenden erhielten eine trapezförmige Form.',NULL,NULL,NULL,5,2017,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-6er-e24','BMW','6er','E24',1976,1989,'["Coupé"]','Oberklasse','BMW E9','Die erste Generation des BMW 6er Coupés, oft liebevoll als ''Haifischmaul'' bezeichnet, aufgrund der markanten, nach vorne geneigten Frontpartie. Charakteristisch sind die Doppelrundscheinwerfer und die lange Motorhaube.','Ein umfassendes Facelift erfolgte 1982 (oft als ''zweite Serie'' oder ''Highline'' bezeichnet), welches technische Änderungen an Fahrwerk, Bremsen und Elektrik umfasste. Optisch gab es modifizierte Stoßstangen, eine leicht überarbeitete Frontschürze und beim M635CSi einen Heckspoiler. Ab 1987 wurden die Stoßstangen erneut überarbeitet und Nebelscheinwerfer integriert.',NULL,NULL,NULL,NULL,NULL,10000,'2 Jahre','Der BMW E24 ist ein begehrter Klassiker und Youngtimer. Hauptaugenmerk beim Kauf sollte auf Rost gelegt werden, insbesondere an Schwellern, Radläufen, Wagenheberaufnahmen, im Bereich der Front- und Heckscheibe sowie am Tankdeckel. Die Elektrik kann altersbedingt Mängel aufweisen (Fensterheber, Zentralverriegelung, Kombiinstrument). Motoren sind bei guter Wartung robust, aber Dichtungen und Nebenaggregate (Wasserpumpe, Lichtmaschine) können altersbedingt Probleme bereiten. Achten Sie auf den Zustand des Fahrwerks (Buchsen, Lager). Ersatzteile sind teilweise teuer oder schwer zu finden, besonders für spezifische Ausstattungsmerkmale. Eine lückenlose Wartungshistorie ist von Vorteil.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-6er-e63-e64','BMW','6er','E63/E64',2003,2010,'["Coupé", "Cabrio"]','Oberklasse','BMW E24','Charakteristisches ''Bangle-Design'' mit langer Motorhaube, kurzen Überhängen und markantem Heck. Die E63-Reihe (Coupé) wurde 2003 eingeführt, die E64-Reihe (Cabrio) 2004.','Im September 2007 (Modelljahr 2008) erfolgte ein ''Life Cycle Impulse'' (LCI). Änderungen umfassten eine modifizierte Front- und Heckschürze, neue LED-Rückleuchten, überarbeitete Scheinwerfer, neue Motoren (z.B. 630i mit N53, 635d) und leichte Anpassungen im Interieur.',NULL,NULL,NULL,NULL,NULL,25000,'2 Jahre','Der BMW 6er E63/E64 ist ein stilvolles und leistungsstarkes Coupé oder Cabrio. Beim Kauf sollte man besonders auf den Zustand der Elektronik (iDrive, Komfortfunktionen), mögliche Rostansätze (insbesondere an Heckklappe und Radläufen bei frühen Modellen) und den Zustand des Fahrwerks achten. V8-Motoren (N62) können Probleme mit Ventilschaftdichtungen und Kühlmittelleitungen aufweisen. Das Verdeck des Cabrios (E64) sollte auf Dichtigkeit und Funktion geprüft werden. Eine vollständige Servicehistorie ist entscheidend.','2026-06','{"E63": "Coupé", "E64": "Cabrio"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-6er-f12-f13-f06','BMW','6er','F12/F13/F06',2011,2018,'["Cabrio", "Coupé", "Gran Coupé"]','Oberklasse','E63/E64','Die dritte Generation des BMW 6er wurde als F12 (Cabrio), F13 (Coupé) und F06 (Gran Coupé) angeboten. Sie zeichnet sich durch eine flache, breite Front mit markanten Nieren und langgezogenen Scheinwerfern aus. Das Design ist eleganter und weniger polarisierend als beim Vorgänger E63/E64.','Im Frühjahr 2015 erfolgte ein Facelift (LCI). Optische Änderungen umfassten neu gestaltete Front- und Heckschürzen, serienmäßige LED-Scheinwerfer und -Nebelscheinwerfer sowie leicht modifizierte Rückleuchten. Im Innenraum gab es neue Materialien und Farben. Die Motoren wurden leicht überarbeitet, um die Effizienz zu steigern.',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre','Der BMW 6er der F-Generation ist ein luxuriöser und komfortabler Reisewagen mit sportlichen Ambitionen. Er bietet eine hochwertige Verarbeitung und eine umfangreiche Ausstattung. Als Gebrauchtwagen sind die Preise attraktiv, jedoch sollte man die hohen Wartungs- und Ersatzteilkosten der Oberklasse berücksichtigen. Besonders die V8-Motoren (650i) können teuer im Unterhalt sein. Die Diesel- und Reihensechszylinder-Benziner gelten als robustere Wahl. Auf regelmäßige Wartung und den Zustand des Fahrwerks achten.','2026-06','{"F12": "Cabrio", "F13": "Coupé", "F06": "Gran Coupé"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-6er-gran-turismo-g32','BMW','6er Gran Turismo','G32',2017,NULL,'["Fließheck"]','Obere Mittelklasse','BMW 5er Gran Turismo (F07)','Großer Fließheck-Kofferraum, rahmenlose Scheiben, basiert auf der Technik des 5er G30/G31. Deutlich eleganter und weniger klobig als der Vorgänger F07.','Facelift (LCI) im Jahr 2020: Neu gestaltete Frontschürze, schlankere LED-Scheinwerfer (optional Laserlicht), größere Niere, neue Heckschürze, neue Rückleuchten. Im Innenraum iDrive 7.0 mit größeren Displays. Einführung von 48V-Mild-Hybrid-Technologie für alle Motoren.',NULL,NULL,NULL,5,2017,30000,'Alle 2 Jahre','Der BMW 6er Gran Turismo (G32) ist eine komfortable und geräumige Reiselimousine mit Fließheck, die die Praktikabilität eines Kombis mit dem Komfort einer Limousine verbindet. Er bietet eine hohe Langstreckentauglichkeit und eine umfangreiche Serienausstattung. Die Motoren sind durchweg kräftig und effizient. Nach dem Facelift 2020 profitieren alle Motoren von der 48V-Mild-Hybrid-Technologie. Achten Sie auf die üblichen Verschleißteile und die Historie bei Gebrauchtwagen. Die Luftfederung an der Hinterachse ist serienmäßig, eine Voll-Luftfederung optional – hier auf Funktion prüfen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-e23','BMW','7er','E23',1977,1986,'["Limousine"]','Oberklasse',NULL,'Der E23 war die erste Generation der 7er-Reihe. Charakteristisch sind die kantige Karosserieform, die Doppelscheinwerfer (bei vielen Modellen) und die typische BMW-Niere. Im Vergleich zu seinen Vorgängern (wie der E3) war der E23 deutlich größer und moderner gestaltet.','1982 gab es ein Facelift, das unter anderem überarbeitete Stoßstangen, neue Scheinwerfer- und Rückleuchten-Designs sowie eine verbesserte Innenausstattung brachte.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-e32','BMW','7er','E32',1986,1994,'["Limousine", "Langversion"]','Oberklasse','bmw-7er-e23','Der BMW E32 zeichnet sich durch seine elegante, fließende Linienführung aus, die im Vergleich zum Vorgänger E23 deutlich moderner und aerodynamischer wirkt. Charakteristisch sind die schmalen, rechteckigen Doppelscheinwerfer, die von einer breiten Niere flankiert werden. Die Motorhaube ist flacher und die Seitenlinie weniger kantig als beim E23. Im Vergleich zum Nachfolger E38 fehlen dem E32 die runden, in die Scheinwerfer integrierten Standlichtringe (''Angel Eyes'') und die Karosserie wirkt insgesamt noch etwas kantiger und weniger abgerundet als beim E38.',NULL,NULL,NULL,NULL,NULL,NULL,10000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-e38','BMW','7er','E38',1994,2001,'["Limousine"]','Oberklasse','bmw-7er-e32','Der E38 unterscheidet sich vom Vorgänger E32 durch eine deutlich modernere, fließendere Karosserielinie. Die Doppelrundscheinwerfer sind unter einer gemeinsamen Glasabdeckung zusammengefasst, im Gegensatz zu den getrennten Einheiten des E32. Die BMW-Niere ist breiter und flacher gestaltet, und die gesamte Silhouette wirkt gestreckter und dynamischer.','Das Facelift erfolgte im Herbst 1998 (Modelljahr 1999). Die Scheinwerfer erhielten eine leicht abgerundete Unterkante und bei Xenon-Ausstattung die charakteristischen ''Angel Eyes''. Die Rückleuchten wurden mit weißen Blinkergläsern statt der vorherigen orangen ausgestattet. Die Nieren wurden leicht breiter und stärker gewölbt, und die Frontschürze wurde mit runderen Nebelscheinwerfern modifiziert. Zudem wurden neue Motoren eingeführt.',NULL,NULL,NULL,NULL,NULL,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-e65/e66','BMW','7er','E65/E66',2001,2008,'["Limousine", "Langversion Limousine"]','Oberklasse','bmw-7er-e38','Der BMW 7er E65/E66 ist bekannt für sein polarisierendes Design, oft als ''Bangle Butt'' bezeichnet, mit einem markanten, nach hinten abfallenden Kofferraumdeckel. Die Front zeichnet sich durch große, geschwungene Scheinwerfer aus, die sich weit in die Kotflügel ziehen, und eine breite BMW-Niere. Im Innenraum war er der erste BMW mit dem iDrive-Bediensystem, das die meisten Funktionen über einen Dreh-Drück-Steller in der Mittelkonsole steuerte und die Anzahl der physischen Knöpfe drastisch reduzierte.','Das Facelift (LCI) im Jahr 2005 brachte eine Überarbeitung der Front- und Heckpartie. Die Scheinwerfer erhielten eine leicht geänderte Form mit einer stärker ausgeprägten ''Augenbraue'' und die Niere wurde dezenter gestaltet. Am Heck wurden die Rückleuchten neu gezeichnet, sie wirken nun schlanker und moderner, und der Kofferraumdeckel wurde optisch weniger wuchtig. Auch die Stoßfänger wurden vorne und hinten modifiziert. Im Innenraum gab es kleinere Anpassungen am iDrive-System und den Materialien.',NULL,NULL,NULL,NULL,NULL,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-f01/f02','BMW','7er','F01/F02',2008,2015,'["Limousine"]','Oberklasse','bmw-7er-e65/e66','Der F01/F02 unterscheidet sich vom Vorgänger E65/E66 durch eine deutlich konservativere Linienführung. Die charakteristischen "Hofmeister-Knick"-Elemente sind subtiler integriert. Die Scheinwerfer sind weniger spitz zulaufend und die BMW-Niere wirkt breiter und weniger dominant. Die Karosserie ist insgesamt kantiger und weniger geschwungen.','Das Facelift (LCI) im Jahr 2012 brachte dezente optische Änderungen. Die Scheinwerfer erhielten eine neue LED-Signatur, die BMW-Niere wurde leicht modifiziert und die Frontschürze neu gestaltet. Im Innenraum gab es Anpassungen am Infotainmentsystem und neue Dekorleisten.',NULL,NULL,NULL,5,2009,NULL,'2 Jahre','Der BMW 7er F01/F02 bietet Luxus und Komfort auf hohem Niveau. Achten Sie bei Gebrauchtfahrzeugen auf den Wartungszustand, insbesondere bei den Dieselmotoren und der komplexen Elektronik. Regelmäßige Inspektionen sind entscheidend. Die Langversion F02 bietet deutlich mehr Platz im Fond.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-g11/g12','BMW','7er','G11/G12',2015,2022,'["Limousine"]','Oberklasse','bmw-7er-f01/f02','Der G11/G12 unterscheidet sich vom Vorgänger F01/F02 durch eine deutlich flachere und breitere Niere, neu gestaltete Scheinwerfer mit optionaler Laserlicht-Technologie und eine markantere Linienführung der Karosserie. Die Heckleuchten sind durch ein durchgehendes Chromband verbunden.','Das Facelift (LCI) im Jahr 2019 brachte eine vergrößerte Niere, überarbeitete Scheinwerfer und Rückleuchten, eine neue Motorhaube und Stoßfänger. Im Innenraum wurde das Infotainmentsystem aktualisiert und neue Assistenzsysteme eingeführt.',NULL,NULL,NULL,5,2015,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-7er-g70','BMW','7er','G70',2022,NULL,'["Limousine"]','Luxusklasse','bmw-7er-g11-g12','Die G70-Generation zeichnet sich durch eine radikal neue Frontpartie mit zweigeteilten Scheinwerfern aus, bei denen die Tagfahrlichter und Blinker oben und die Hauptscheinwerfer tiefer in der Stoßstange integriert sind. Die BMW Niere ist deutlich größer und kann optional beleuchtet werden. Das Heck ist breiter und flacher gestaltet, mit schlanken, horizontalen Rückleuchten, die weit in die Seiten reichen. Im Innenraum dominiert das Curved Display, das das digitale Kombiinstrument und den Infotainment-Bildschirm in einer Einheit vereint.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'3 Jahre (Erst-HU), danach alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-8er-e31','BMW','8er','E31',1990,1999,'["Coupé"]','Oberklasse','BMW 6er E24','Charakteristische Klappscheinwerfer, säulenloses Design, breite Niere, flache Silhouette.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre','Der BMW E31 ist ein komplexes und technisch anspruchsvolles Fahrzeug. Besonders die V12-Modelle sind wartungsintensiv und können hohe Betriebskosten verursachen. Achten Sie auf den Zustand der Elektronik (Kabelbaum, Steuergeräte), des Fahrwerks und der Klimaanlage. Rost ist selten, aber an neuralgischen Punkten wie Wagenheberaufnahmen oder Radläufen möglich. Eine lückenlose Wartungshistorie ist entscheidend. Ersatzteile können teuer und schwer zu finden sein. Der 840Ci mit dem M62-Motor gilt als etwas robuster und wartungsfreundlicher als die V12-Modelle.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-8er-g15-g14-g16','BMW','8er','G15/G14/G16',2018,NULL,'["Coupé", "Cabrio", "Gran Coupé"]','Oberklasse','BMW 6er (F06/F12/F13)','G15 (Coupé), G14 (Cabrio), G16 (Gran Coupé)','LCI (Life Cycle Impulse) im Jahr 2022: Leichte optische Änderungen an Front (Niere, Stoßfänger), neue Ausstattungspakete, größere Displays im Innenraum (12,3 Zoll).',NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre','Der BMW 8er der G-Generation ist ein luxuriöses und sportliches Fahrzeug der Oberklasse. Er bietet eine breite Motorenpalette von effizienten Reihensechszylindern bis hin zu leistungsstarken V8-Motoren. Die Verarbeitungsqualität ist hoch, und die Ausstattung ist umfangreich. Als Gebrauchtwagen sind die Preise aufgrund des hohen Neupreises und des Wertverlusts attraktiv. Auf die Wartungshistorie und den Zustand der Bremsen und Reifen sollte geachtet werden, insbesondere bei den leistungsstärkeren Modellen. Elektronikprobleme sind selten, aber möglich. Der 8er ist kein Volumenmodell, daher sind spezifische Langzeitdaten zu Mängeln noch begrenzt.','2026-06','{"G15": "Coupé", "G14": "Cabrio", "G16": "Gran Coupé"}',NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-i3-i01','BMW','i3','I01',2013,2022,'["Kompaktwagen", "5-Türer", "Elektroauto"]','Premium-Kompaktwagen',NULL,'Der BMW i3 (I01) zeichnet sich durch sein futuristisches Design mit einer hohen, schmalen Karosserie, gegenläufig öffnenden Türen (Coach Doors) ohne B-Säule und einer markanten schwarzen Gürtellinie aus, die sich um das gesamte Fahrzeug zieht. Die großen Fensterflächen und die schmalen Reifen auf großen Felgen sind ebenfalls charakteristisch. Die Front ist geprägt von der geschlossenen BMW-Niere und U-förmigen LED-Tagfahrleuchten.','Das Facelift (Life Cycle Impulse, LCI) im Jahr 2017 brachte eine leicht überarbeitete Front- und Heckschürze mit neuen Chromakzenten, serienmäßige Voll-LED-Scheinwerfer und neue Außenfarben. Zudem wurde die Sportvariante i3s eingeführt, die sich durch spezifische Stoßfänger, breitere Spur und größere Räder optisch abgrenzt.','Sehr gut','Gering (oft unter dem Durchschnitt)','Gut (wenig Mängel, vor allem bei Fahrwerk und Bremsen)',4,2013,NULL,'Alle 2 Jahre','Der BMW i3 ist ein innovatives Elektrofahrzeug mit einer leichten Karbon-Fahrgastzelle. Achten Sie beim Kauf auf den Zustand der Hochvoltbatterie (SOH - State of Health), auch wenn diese als sehr langlebig gilt. Bei Modellen mit Range Extender (REX) sollte der Zweizylinder-Motor regelmäßig gewartet und auf Funktion geprüft werden, da er oft nur selten genutzt wird. Fahrwerk und Bremsen sind robust, aber die Reifen können aufgrund der schmalen Dimensionen teuer sein. Die Ladeinfrastruktur und die persönlichen Reichweitenanforderungen sollten vor dem Kauf geklärt werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-i4-g26','BMW','i4','G26',2021,NULL,'["Gran Coupé"]','Mittelklasse',NULL,'Der BMW i4 G26 ist als rein elektrisches Gran Coupé eng mit dem BMW 4er Gran Coupé (G26) verwandt, unterscheidet sich aber durch spezifische Designelemente. Auffällig sind die geschlossene BMW Niere mit integrierten Sensoren und blauen Akzenten, die aerodynamisch optimierten Felgen, die fehlenden Auspuffendrohre und die blauen Designelemente an Front, Seite und Heck (z.B. im Diffusor). Die Ladeklappe befindet sich an der Stelle des Tankdeckels.',NULL,NULL,NULL,NULL,4,2022,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-i5-g60','BMW','i5','G60',2023,NULL,'["Limousine"]','Oberklasse','bmw-5er-g30','Der BMW i5 G60 unterscheidet sich von seinem Vorgänger G30 durch eine deutlich flachere und breitere Niere, die nun optional beleuchtet ist. Die Scheinwerfer sind schmaler und schärfer gezeichnet, und die Karosserielinien wirken insgesamt moderner und aerodynamischer. Die Heckleuchten sind durchgehend und verbinden die beiden Leuchteneinheiten.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-i7-g70','BMW','i7','G70',2022,NULL,'["Limousine"]','Luxusklasse',NULL,'Der BMW i7 G70 ist die vollelektrische Variante der 7er-Reihe G70 und zeichnet sich durch eine markante Frontpartie mit geteilten Scheinwerfern aus, bei der die oberen, schmalen Leuchten die Tagfahrlichter und Blinker beherbergen, während die Hauptscheinwerfer tiefer und dunkler integriert sind. Die BMW Niere ist groß, aufrecht stehend und kann optional beleuchtet werden. Die Karosserie ist sehr präsent und monolithisch, mit bündig integrierten Türgriffen. Am Heck fallen die schlanken, L-förmigen Rückleuchten auf, die weit in die Seitenflanken reichen und durch eine Chromleiste verbunden sind. Im Vergleich zum Vorgänger (7er G11/G12) wirkt der G70 deutlich massiver und moderner, insbesondere durch die neue Frontlichtsignatur und die glatteren Flächen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-ix-i20','BMW','iX','I20',2021,NULL,'["SUV"]','Oberklasse-SUV',NULL,'Der BMW iX (I20) ist sofort an seiner markanten, vertikal ausgerichteten Doppelniere zu erkennen, die als ''Intelligenzfläche'' dient und Sensoren beherbergt. Charakteristisch sind die schmalen, weit in die Kotflügel gezogenen Scheinwerfer, die rahmenlosen Türen und die flache, coupéartige Dachlinie. Die Heckleuchten sind ebenfalls sehr schmal und L-förmig. Das Design ist futuristisch und unterscheidet sich stark von anderen BMW-Modellen.',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre','Der BMW iX ist ein vollelektrisches Oberklasse-SUV, das mit modernster Technik, hohem Komfort und einer luxuriösen Ausstattung punktet. Als reines Elektrofahrzeug entfallen klassische Wartungsarbeiten wie Ölwechsel. Potenzielle Käufer sollten auf den Zustand der Hochvoltbatterie und der Ladeinfrastruktur achten. Software-Updates sind wichtig für die Funktionalität. Die Reichweite ist für die meisten Anwendungsfälle ausreichend, kann aber bei hohen Geschwindigkeiten oder kalten Temperaturen variieren. Die Verfügbarkeit von Lademöglichkeiten sollte berücksichtigt werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-ix1-u11','BMW','iX1','U11',2022,NULL,'["SUV"]','Kompakt-SUV',NULL,'Der BMW iX1 U11 basiert auf der dritten Generation des X1 (U11) und ist äußerlich eng mit diesem verwandt. Er unterscheidet sich durch spezifische Designelemente, die seine elektrische Natur betonen: Blaue Akzente an der Frontschürze, den Seitenschwellern und dem Heckdiffusor (optional, entfällt bei M Sport), ein geschlossener Kühlergrill mit BMW i-Logo und das Fehlen sichtbarer Auspuffendrohre. Die Frontscheinwerfer sind schmaler und schärfer gezeichnet als beim Vorgänger (F48), und die Niere ist größer und fast quadratisch.',NULL,NULL,NULL,NULL,5,2022,NULL,'alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-ix3-g08','BMW','iX3','G08',2020,NULL,'["SUV"]','Mittelklasse-SUV',NULL,'Der BMW iX3 G08 basiert auf dem X3 G01, unterscheidet sich aber durch spezifische Designelemente für Elektrofahrzeuge. Dazu gehören eine geschlossene BMW Niere mit blauen Akzenten, blaue Zierelemente an den Seiten und am Heck, aerodynamisch optimierte Leichtmetallräder und ein modifiziertes Heck mit einem Diffusor anstelle von Auspuffendrohren. Die Frontschürze ist ebenfalls spezifisch gestaltet.','Im September 2021 erhielt der iX3 G08 ein Facelift (LCI). Die markantesten Änderungen umfassen flachere LED-Scheinwerfer, eine vergrößerte und neu gestaltete BMW Niere, eine überarbeitete Frontschürze mit vertikalen Lufteinlässen und eine neu geformte Heckschürze. Die Heckleuchten erhielten eine neue Grafik mit dreidimensionaler Kontur. Im Innenraum wurde das Infotainment-Display auf 12,3 Zoll vergrößert und die Mittelkonsole leicht überarbeitet.',NULL,NULL,NULL,5,2017,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-m4-f82','BMW','M4','F82',2014,2020,'["Coup\u00e9", "Cabrio (F83)"]','Sportwagen-Coupé','M3 Coupé (E92)','Basiert auf 4er F32. Powerdome-Haube, breite Kotflügel, vier Endrohre (zwei Doppelrohre), CFK-Dach. KLEINE Niere — klarer Unterschied zum G82.','LCI 2017: LED-Scheinwerfer serienmäßig, OLED-Rückleuchten.',NULL,NULL,NULL,NULL,NULL,25000,'alle 2 Jahre',NULL,'2026-05',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-m4-g82','BMW','M4','G82',2021,NULL,'["Coup\u00e9", "Cabrio (G83)"]','Sportwagen-Coupé','M4 F82','Basiert auf 4er G22. GROSSE, hochkant stehende Doppelniere (auffälligstes Merkmal!), schmale Scheinwerfer.','LCI 2024: neue Matrix-LED-Scheinwerfer, Curved Display im Innenraum.',NULL,NULL,NULL,NULL,NULL,NULL,'alle 2 Jahre (Neuwagen: erste HU nach 3 Jahren)',NULL,'2026-05',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x1-e84','BMW','X1','E84',2009,2015,'["SUV", "Crossover"]','Kompakt-SUV',NULL,'Erste Generation des X1, basierend auf der Plattform des 3er E90.','2012 (LCI): Überarbeitete Front- und Heckschürzen, modifizierte Scheinwerfer und Rückleuchten, neue Außenspiegel, leicht angepasster Innenraum (Materialien, Zierleisten), überarbeitete Motorenpalette.','Durchschnittlich, mit einigen Auffälligkeiten bei Elektronik und Motorperipherie.','Durchschnittlich bis leicht überdurchschnittlich für das Alter. Häufige Mängel: Fahrwerk (Achsen, Lenkung), Bremsanlage, Beleuchtung.','Gute Langzeitqualität, aber mit altersbedingten Schwächen an Fahrwerk und Bremsen. Dieselmotoren tendenziell robuster als frühe Benziner.',5,2009,25000,'Alle 2 Jahre','Der BMW X1 E84 bietet eine gute Mischung aus SUV-Praktikabilität und BMW-Fahrdynamik. Besonders die Dieselmotoren gelten als robust und sparsam. Beim Kauf sollte auf den Zustand des Fahrwerks, die Bremsen und eventuelle Undichtigkeiten (Motor, Panoramadach) geachtet werden. Modelle nach dem Facelift (ab 2012) profitieren von überarbeiteten Motoren und Detailverbesserungen. Allrad (xDrive) ist empfehlenswert für bessere Traktion, erhöht aber den Verbrauch leicht.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x1-f48','BMW','X1','F48',2015,2022,'["SUV"]','Kompakt-SUV','BMW X1 E84','Zweite Generation des X1, basierend auf der UKL2-Plattform (Frontantriebsarchitektur). Deutlich geräumiger als der Vorgänger E84.','LCI (Life Cycle Impulse) im Jahr 2019. Neue Frontschürze, größere BMW-Niere, neue LED-Scheinwerfer und -Rückleuchten, überarbeitete Innenraumdetails (z.B. Infotainment-Display, neue Schaltkulisse).','Gut','Unterdurchschnittlich gut (weniger Mängel als der Durchschnitt)','Gut',5,2015,25000,'2 Jahre','Der BMW X1 F48 ist ein geräumiges und praktisches Kompakt-SUV mit hochwertiger Verarbeitung. Er bietet eine gute Mischung aus Komfort und Fahrdynamik. Die Motoren sind in der Regel zuverlässig und sparsam. Besonders die Dieselmotoren sind für ihre Effizienz bekannt. Beim Kauf sollte auf die Historie geachtet werden, insbesondere bei Fahrzeugen mit hoher Laufleistung. Die Plug-in-Hybrid-Variante 25e bietet eine gute Kombination aus elektrischer Reichweite und Verbrennerleistung.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x1-u11','BMW','X1','U11',2022,NULL,'["SUV"]','Kompakt-SUV','F48','Deutlich gewachsene Abmessungen, markanterer Nierengrill, flachere LED-Scheinwerfer, bündige Türgriffe, neu gestaltetes Interieur mit Curved Display.',NULL,NULL,NULL,NULL,5,2022,20000,'Alle 2 Jahre','Als relativ neues Modell sind Langzeiterfahrungen und typische Gebrauchtwagenmängel noch nicht umfassend dokumentiert. Der U11 bietet eine moderne Ausstattung, effiziente Antriebe (auch elektrisch und Plug-in-Hybrid) und ein geräumiges Interieur. Auf Software-Updates und die Funktion des Infotainmentsystems achten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x2-f39','BMW','X2','F39',2017,2023,'["SUV-Coupé"]','Kompakt-SUV',NULL,'Kompaktes SUV-Coupé auf UKL2-Plattform, sportlichere Interpretation des X1 (F48). Flachere Dachlinie, markante C-Säule mit BMW-Logo.',NULL,'Gut','Gering','Überdurchschnittlich',5,2017,25000,'Alle 2 Jahre','Der BMW X2 F39 ist eine sportlichere und Lifestyle-orientierte Alternative zum X1. Er bietet agiles Fahrverhalten und eine hochwertige Verarbeitung. Achten sollte man auf die Ausstattung, da viele Extras aufpreispflichtig waren. Die Motorenpalette ist breit und bietet sowohl effiziente Dreizylinder als auch kräftige Vierzylinder, inklusive Plug-in-Hybrid. Gebrauchtwagenpreise sind stabil. Typische Schwachstellen sind überschaubar, aber die Bremsen können bei sportlicher Fahrweise stärker verschleißen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x2-u10','BMW','X2','U10',2023,NULL,'["SUV-Coupé"]','Kompakt-SUV','BMW X2 F39','Deutlich gewachsene Dimensionen, coupéhaftere Dachlinie, markante Front mit optional beleuchteter Niere, flachere Scheinwerfer, bündige Türgriffe, eigenständiges Heckdesign.',NULL,NULL,NULL,NULL,5,2023,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x3-e83','BMW','X3','E83',2003,2010,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des BMW X3, intern E83 genannt. Charakteristisch sind die runden Nebelscheinwerfer, die eher kantige Form im Vergleich zu späteren Generationen und die typischen BMW-Nieren der frühen 2000er Jahre.','Umfassendes Facelift im Jahr 2006 (LCI - Life Cycle Impulse): Geänderte Front- und Heckschürzen, neue Scheinwerfer- und Rückleuchtengrafik, überarbeiteter Innenraum mit hochwertigeren Materialien und neuen Lenkrädern. Die Motorenpalette wurde ebenfalls aktualisiert.',NULL,NULL,NULL,4,2003,25000,'Alle 2 Jahre','Der BMW X3 E83 war der erste Kompakt-SUV von BMW und bot eine sportliche Fahrdynamik. Besonders die Reihensechszylinder-Dieselmotoren (3.0d, 3.0sd) sind aufgrund ihrer Leistung und Effizienz beliebt, aber auch die Reihensechszylinder-Benziner überzeugen. Beim Kauf sollte auf Rost an der Heckklappe (oft im Bereich der Kennzeichenbeleuchtung), Probleme mit dem Verteilergetriebe (xDrive-Modelle, besonders bei unregelmäßigem Ölwechsel), defekte Turbolader bei Dieseln und ausgeschlagene Fahrwerkskomponenten (Querlenker, Stoßdämpfer) geachtet werden. Das Facelift-Modell (ab 2006) gilt als ausgereifter und bietet einen hochwertigeren Innenraum. Panoramadächer können undicht werden oder Probleme mit der Mechanik haben.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x3-f25','BMW','X3','F25',2010,2017,'["SUV"]','Mittelklasse-SUV','E83','Zweite Generation des BMW X3. Erkennbar an der größeren, muskulöseren Karosserie im Vergleich zum E83, mit markanten Doppelscheinwerfern und der BMW-Niere. Die F25-Generation ist deutlich gewachsen und bietet mehr Innenraum.','Facelift (LCI) 2014: Geänderte Frontschürze, neue Scheinwerfer (optional Voll-LED), überarbeitete Nieren, neue Außenspiegel mit integrierten Blinkern, leichte Änderungen am Heck, neue Interieur-Materialien und Farben.',NULL,NULL,NULL,5,2011,25000,'2 Jahre','Der BMW X3 F25 gilt als robustes und zuverlässiges Fahrzeug. Besondere Aufmerksamkeit sollte dem Zustand des Panoramadachs, dem Verteilergetriebe (bei xDrive-Modellen) und der Steuerkette bei den N47-Dieselmotoren gewidmet werden. Regelmäßige Wartung ist entscheidend. Die Benziner gelten als unauffälliger.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x3-g01','BMW','X3','G01',2017,2024,'["SUV"]','Mittelklasse-SUV','F25','Deutlich gewachsene Dimensionen gegenüber dem Vorgänger, markantere, größere Niere, schärfere Linienführung, serienmäßige LED-Scheinwerfer, L-förmige LED-Rückleuchten.','LCI (Life Cycle Impulse) im Jahr 2021: Neu gestaltete Frontschürze mit größeren Lufteinlässen, flachere LED-Scheinwerfer, neu geformte Niere, überarbeitete Heckschürze, neue LED-Rückleuchten mit dreidimensionaler Optik, digitales Cockpit und größere Infotainment-Displays im Innenraum.','Gut','Gering','Überdurchschnittlich',5,2017,30000,'2 Jahre','Der BMW X3 G01 ist ein ausgereiftes und beliebtes Mittelklasse-SUV, das Komfort, gute Fahrdynamik und eine hochwertige Verarbeitung bietet. Die Motorenpalette ist breit und reicht von effizienten Vierzylindern bis zu leistungsstarken Sechszylindern und Plug-in-Hybriden. Achten Sie auf die Ausstattungslinien, da diese den Charakter des Fahrzeugs stark prägen. Gebrauchte Modelle sind aufgrund der hohen Nachfrage preisstabil. Typische Schwachstellen sind selten, aber eine lückenlose Wartungshistorie ist empfehlenswert. Das Facelift (LCI) ab 2021 bringt modernere Optik und verbesserte Infotainment-Technik.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x3-g45','BMW','X3','G45',2024,NULL,'["SUV"]','Mittelklasse-SUV','BMW X3 G01','Deutlich vergrößerte BMW Niere, neue Lichtsignatur vorne und hinten, flachere Dachlinie, markantere Seitenlinie.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'Alle 2 Jahre (nach 3 Jahren Erst-HU)',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x4-f26','BMW','X4','F26',2014,2018,'["SUV-Coupé"]','Mittelklasse-SUV',NULL,'Die erste Generation des BMW X4, basierend auf der Plattform des BMW X3 (F25). Charakteristisch ist die coupéartige Dachlinie, die ihn vom konventionellen SUV X3 abgrenzt.',NULL,NULL,NULL,NULL,NULL,NULL,30000,'2 Jahre','Der BMW X4 F26 ist technisch eng mit dem X3 F25 verwandt. Achten Sie auf den Zustand des Verteilergetriebes bei Allradmodellen, insbesondere bei hohen Laufleistungen. Bremsen und Fahrwerkskomponenten können je nach Fahrweise und Nutzung überdurchschnittlichen Verschleiß zeigen. Die Motoren gelten als robust, regelmäßige Wartung ist jedoch entscheidend. Dieselmotoren mit N47-Motorcode können von Steuerkettenproblemen betroffen sein, neuere B47-Motoren sind hier unauffälliger. Prüfen Sie die Funktion der Elektronik und des Infotainmentsystems.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x4-g02','BMW','X4','G02',2018,NULL,'["SUV-Coupé"]','Mittelklasse-SUV','F26','Die zweite Generation des BMW X4 (G02) basiert auf dem G01 X3. Sie ist erkennbar an ihrer markanten, coupéartigen Dachlinie, den schmalen, langgezogenen LED-Rückleuchten und der sportlicheren Front im Vergleich zum Vorgänger. Die Frontscheinwerfer sind serienmäßig LED und reichen bis an die BMW Niere heran.','Im Jahr 2021 erfolgte ein Life Cycle Impulse (LCI). Merkmale des Facelifts sind eine neu gestaltete Frontschürze mit vertikalen Lufteinlässen, flachere LED-Scheinwerfer, eine überarbeitete BMW Niere (größer und mit neuem Gitterdesign), eine neu gestaltete Heckschürze mit integrierten Endrohren und ein modernisiertes Interieur mit dem BMW Curved Display (optional) und dem iDrive 7 Infotainment-System.',NULL,NULL,NULL,5,2017,25000,'3 Jahre nach Erstzulassung, danach alle 2 Jahre','Der BMW X4 G02 gilt als technisch ausgereift und zuverlässig, da er auf der bewährten G01 X3 Plattform basiert. Er bietet eine sportliche Fahrweise und hochwertige Materialien im Innenraum. Beim Kauf sollte auf eine lückenlose Wartungshistorie geachtet werden. Modelle mit M Sportpaket oder M Performance sind oft straffer abgestimmt. Die Motorenpalette ist breit und bietet für jeden Anspruch etwas, wobei die Dieselmotoren für Langstreckenfahrer besonders effizient sind. Auf mögliche Software-Updates und den Zustand der Bremsen achten, insbesondere bei leistungsstärkeren Varianten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x5-e53','BMW','X5','E53',1999,2006,'["SUV"]','Oberklasse-SUV',NULL,'Der erste BMW X5, charakterisiert durch die typische BMW-Niere, runde Scheinwerfer (vor Facelift), und eine robuste, sportliche SUV-Silhouette. Markteinführung in Europa 2000.','Im Jahr 2003 erfolgte ein Facelift: Neue Scheinwerfer mit Corona-Ringen, überarbeitete Niere, neue Heckleuchten, neue Frontschürze, neue Motoren (z.B. 4.4i N62, 3.0d M57TÜ).',NULL,NULL,NULL,4,2000,20000,'2 Jahre','Der BMW X5 E53 ist ein robuster SUV, der jedoch altersbedingt einige Schwachstellen aufweisen kann. Besonders zu beachten sind Rost an Heckklappe und Türen, Verschleiß am Fahrwerk (Querlenker, Spurstangen, Luftfederung hinten), Probleme mit der Elektrik (Fensterheber, PDC, Pixelfehler im Kombiinstrument) und Undichtigkeiten am Panoramadach. Die Automatikgetriebe sind bei mangelnder Wartung anfällig. Dieselmotoren sind langlebig, aber Injektoren und Turbolader können Probleme bereiten. V8-Motoren sind durstig und können zu Ölverlust neigen. Eine vollständige Historie und regelmäßige Wartung sind entscheidend für den Kauf.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x5-e70','BMW','X5','E70',2006,2013,'["SUV"]','Oberklasse-SUV','BMW X5 E53','Deutlich gewachsen gegenüber dem Vorgänger E53, markante Doppelniere, Doppelrundscheinwerfer, L-förmige Rückleuchten, iDrive-Controller in der Mittelkonsole.','Das Facelift (LCI) erfolgte 2010. Es umfasste neue Motoren (z.B. N55 statt N54, N57 statt M57, N63 statt N62), eine modifizierte Frontschürze mit größeren Lufteinlässen, geänderte Scheinwerfer mit LED-Tagfahrlichtringen und neu gestaltete Heckleuchten mit LED-Technik.',NULL,NULL,NULL,5,2007,25000,'Alle 2 Jahre','Der BMW X5 E70 bietet viel Platz, hohen Fahrkomfort und eine gute Langstreckentauglichkeit. Die Motoren sind kräftig, aber der Verbrauch ist entsprechend hoch. Besonders die Dieselmotoren sind beliebt. Beim Kauf sollte auf den Zustand der Luftfederung (falls vorhanden), das Panoramadach und die Elektronik geachtet werden. Modelle nach dem Facelift (ab 2010) profitieren von effizienteren Motoren und kleineren Design-Updates. Eine vollständige Wartungshistorie ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x5-f15','BMW','X5','F15',2013,2018,'["SUV"]','Oberklasse-SUV','BMW X5 E70','Dritte Generation des X5. Charakteristisch sind die mit den Nieren verbundenen Scheinwerfer, eine fließendere Linienführung und eine insgesamt sportlichere, aber dennoch bullige Optik im Vergleich zum Vorgänger E70.',NULL,'Gut bis sehr gut (wenige Pannen, meist Kleinigkeiten wie Batterie oder Reifen)','Durchschnittlich bis leicht überdurchschnittlich (oftmals Bremsen, Fahrwerk, Beleuchtung)','Gute Langzeitqualität, aber auf Bremsen und Fahrwerk achten.',5,2013,30000,'2 Jahre','Der BMW X5 F15 ist ein komfortables und leistungsstarkes SUV mit hohem Reisekomfort. Beim Gebrauchtwagenkauf sollte auf den Zustand der Luftfederung (falls vorhanden), die Bremsanlage und eventuelle Elektronikfehler geachtet werden. Dieselmotoren sind robust, aber auf die Einhaltung der Wartungsintervalle achten. Panoramadach auf Funktion und Dichtigkeit prüfen. Fahrzeuge mit umfangreicher Ausstattung sind anfälliger für Elektronikprobleme.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x5-g05','BMW','X5','G05',2018,NULL,'["SUV"]','Oberklasse-SUV','F15','Große, markante Doppelniere, schmalere, langgezogene Scheinwerfer, L-förmige LED-Rückleuchten, deutlich gewachsene Dimensionen im Vergleich zum Vorgänger.','Facelift (LCI) 2023: Neu gestaltete, noch schmalere Scheinwerfer mit pfeilförmigem Tagfahrlicht, optional beleuchtete Niere (''Iconic Glow''), neue Heckleuchten mit X-Grafik, Curved Display im Innenraum (12,3 Zoll Instrumentendisplay, 14,9 Zoll Control Display), Einführung von 48-Volt-Mild-Hybrid-Technologie für alle Verbrennungsmotoren.',NULL,NULL,NULL,5,2018,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x6-e71','BMW','X6','E71',2008,2014,'["SUV-Coupé"]','Oberklasse-SUV',NULL,'Erste Generation des X6. Charakteristisch ist die coupéartige Dachlinie, die den sportlichen Charakter betont. Große Nieren, markante Scheinwerfer und eine breite Spur.','Ein Facelift (LCI - Life Cycle Impulse) erfolgte im Jahr 2012. Änderungen umfassten leicht modifizierte Scheinwerfer (optional mit adaptiven LED-Scheinwerfern), überarbeitete Heckleuchten mit LED-Technik, neue Lackfarben und Felgendesigns sowie kleinere Anpassungen im Innenraum und bei den Motoren.',NULL,NULL,NULL,5,2007,25000,'Alle 2 Jahre','Der BMW X6 E71 basiert technisch auf dem X5 E70 und teilt viele seiner Stärken und Schwächen. Achten sollte man auf den Zustand der Luftfederung an der Hinterachse (falls vorhanden), die Funktion des Panoramadachs, den Zustand der Bremsen und des Fahrwerks (Querlenker, Spurstangen). Bei Dieselmotoren sind der Zustand des Partikelfilters und der Injektoren zu prüfen. Elektronikprobleme können auftreten, insbesondere beim iDrive-System. Ein lückenloses Scheckheft ist bei diesen komplexen Fahrzeugen essenziell.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x6-f16','BMW','X6','F16',2014,2019,'["SUV-Coupé"]','Oberklasse-SUV','E71','Zweite Generation des X6. Basierend auf dem F15 X5, aber mit der charakteristischen Coupé-Dachlinie. Größere, breitere BMW-Nieren, schärfere Linienführung und LED-Scheinwerfer (optional) im Vergleich zum Vorgänger E71.',NULL,NULL,NULL,NULL,5,2014,30000,'Alle 2 Jahre','Der BMW X6 F16 bietet eine sportliche Optik und Fahrdynamik gepaart mit hohem Komfort und einer luxuriösen Ausstattung. Die Motoren sind durchweg kräftig und effizient für ihre Leistungsklasse. Besonders die Dieselmotoren sind beliebt wegen ihres Drehmoments und akzeptablen Verbrauchs. Beim Kauf sollte auf die Historie geachtet werden, da viele Fahrzeuge als Leasingrückläufer oder Firmenwagen hohe Laufleistungen aufweisen können. Typische Schwachstellen sind im Bereich der Elektronik und des Fahrwerks zu finden, insbesondere bei Fahrzeugen mit adaptiven Fahrwerken oder Luftfederung. Regelmäßige Wartung ist entscheidend für die Langlebigkeit. Der Wiederverkaufswert ist stabil, aber die Unterhaltskosten sind hoch.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x6-g06','BMW','X6','G06',2019,NULL,'["SUV-Coupé"]','Oberklasse-SUV','F16','Markante Coupé-Linie, große BMW-Niere (optional beleuchtet), schmale LED-Scheinwerfer, L-förmige LED-Rückleuchten, breite Schulterlinie.','Facelift (LCI) 2023: Neu gestaltete Frontschürze, schlankere Scheinwerfer, serienmäßig beleuchtete Niere (Iconic Glow), neue Rückleuchten-Grafik, Curved Display im Innenraum mit iDrive 8 (später iDrive 8.5), neue Motorisierungen mit 48V-Mild-Hybrid-Technologie.',NULL,NULL,NULL,NULL,NULL,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-x7-g07','BMW','X7','G07',2019,NULL,'["SUV"]','Oberklasse-SUV',NULL,'Der BMW X7 G07 ist die erste Generation des X7. Er ist erkennbar an seiner imposanten Größe, der großen Doppelniere und den zweigeteilten Scheinwerfern (ab LCI 2022).','Das Facelift (LCI) im Jahr 2022 brachte eine umfassende Überarbeitung der Front mit neu gestalteten, zweigeteilten Scheinwerfern (Split-Headlights), einer beleuchteten Niere (Iconic Glow optional) und einer modifizierten Frontschürze. Im Innenraum wurde das Curved Display (12,3 Zoll Instrumentendisplay und 14,9 Zoll Control Display) mit iDrive 8 eingeführt, sowie neue Zierleisten und ein neu gestalteter Gangwahlschalter.',NULL,NULL,NULL,NULL,NULL,25000,'Alle 2 Jahre','Der BMW X7 G07 ist ein luxuriöses Oberklasse-SUV, das viel Platz, Komfort und modernste Technik bietet. Er ist als Neu- und Gebrauchtwagen hochpreisig. Achten Sie auf die Luftfederung, die bei älteren Modellen oder hoher Laufleistung anfällig sein kann. Elektronikprobleme sind selten, aber teuer in der Reparatur. Die Motoren gelten als robust, insbesondere die Reihensechszylinder. Der Verbrauch ist der Fahrzeugklasse entsprechend hoch. Eine vollständige Servicehistorie ist essenziell.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-z4-e85','BMW','Z4','E85',2002,2008,'["Roadster"]','Sportwagen','BMW Z3','Erste Generation des Z4, Roadster mit klassischem Stoffverdeck. Markante lange Motorhaube und kurzes Heck.','LCI (Life Cycle Impulse) ab 2006: Neue Motoren (N52 statt M54), leicht überarbeitete Front- und Heckschürzen, neue Scheinwerfer- und Rückleuchtengrafiken, Blinkergläser weiß statt orange.','Im Mittelfeld, oft gute Werte für Motor und Elektrik, Schwächen bei Batterie und Zündanlage.','Überdurchschnittlich gut, besonders bei Fahrwerk und Bremsen. Rost ist selten ein Thema.','Gute Langzeitqualität, wenige Mängel bei Fahrwerk und Lenkung. Bremsen und Beleuchtung altersbedingt anfällig.',NULL,NULL,25000,'2 Jahre','Achten Sie auf den Zustand des Verdeckmechanismus (Motor, Gestänge), die Funktion der elektrischen Helfer (Fensterheber, PDC) und den Zustand des Fahrwerks (Querlenkerlager, Stoßdämpfer). Bei M54-Motoren auf Ölverbrauch und VANOS-Geräusche achten. N52-Motoren können Probleme mit der elektrischen Wasserpumpe und Injektoren haben. Rost ist selten, aber an den Radläufen und Schwellern prüfen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-z4-e86','BMW','Z4','E86',2006,2008,'["Coupé"]','Sportwagen','BMW Z3 Coupé (E36/8)','Die interne Bezeichnung E86 steht für die Coupé-Variante des Z4 der ersten Generation. Der Roadster trägt die Bezeichnung E85. Lange Motorhaube
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-z4-e89','BMW','Z4','E89',2009,2016,'["Roadster"]','Sportwagen','BMW Z4 E85/E86','Der E89 ist die zweite Generation des Z4 und zeichnet sich durch sein versenkbares Hardtop aus, im Gegensatz zum Stoffverdeck des Vorgängers E85. Das Design ist flacher und breiter.','Das Facelift (LCI) im Jahr 2013 brachte leichte Änderungen an den Scheinwerfern (LED-Tagfahrlicht), den Seitenblinkern und der Heckschürze. Neue Außenfarben und Interieur-Optionen wurden eingeführt. Der sDrive18i wurde als neue Einstiegsvariante hinzugefügt.',NULL,NULL,NULL,NULL,NULL,25000,'Alle 2 Jahre','Der BMW Z4 E89 ist ein stilvoller Roadster mit einem praktischen Hardtop, das ihn ganzjahrestauglich macht. Die Motorenpalette reicht von sparsamen Vierzylindern bis zu kräftigen Sechszylindern. Beim Kauf sollte besonders auf die Funktion des Hardtops, mögliche Wassereintritte und den Zustand der Fahrwerkskomponenten geachtet werden. Die N54-Motoren (sDrive35i/is) sind leistungsstark, können aber anfälliger für Probleme mit der Hochdruckpumpe und den Injektoren sein. Die N20-Motoren (sDrive18i/20i/28i) sind effizienter, aber auch hier gab es Berichte über Steuerkettenprobleme bei frühen Baujahren. Ein lückenloses Scheckheft ist empfehlenswert.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('bmw-z4-g29','BMW','Z4','G29',2018,NULL,'["Roadster"]','Sportwagen','Z4 E89','Dritte Generation des Z4. Erkennbar an der neuen Designsprache mit breiteren Nieren, vertikal angeordneten LED-Scheinwerfern und dem Stoffverdeck.','Leichtes Facelift im Herbst 2022 (Modelljahr 2023) mit dezent überarbeiteten Nieren, neuen Felgendesigns und erweiterten Lackfarben. Keine wesentlichen technischen Änderungen.',NULL,NULL,NULL,5,2019,30000,'Alle 2 Jahre','Der BMW Z4 G29 ist ein moderner Roadster, der in Kooperation mit Toyota (Supra) entwickelt wurde. Er bietet eine gute Mischung aus Sportlichkeit und Komfort. Die Motoren sind durchweg kräftig und zuverlässig. Das Fahrwerk ist straff, aber nicht unkomfortabel. Das Stoffverdeck öffnet und schließt schnell. Als Gebrauchtwagen sind die Preise stabil. Auf die Bremsen und den Zustand der Reifen sollte geachtet werden, da das Fahrzeug oft sportlich bewegt wird. Elektronikprobleme sind selten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('cupra-born-erste-generation','Cupra','Born','Erste Generation',2021,NULL,'["Schrägheck"]','Kompaktklasse',NULL,'Die erste Generation des Cupra Born zeichnet sich durch ein sportliches Design mit scharfen Linien, kupferfarbenen Akzenten und einer dynamischen Frontpartie aus. Charakteristisch sind die Voll-LED-Scheinwerfer mit einer markanten Lichtsignatur und das durchgehende Leuchtenband am Heck. Im Vergleich zum Schwestermodell VW ID.3 wirkt der Born aggressiver und tiefergelegt.',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('cupra-formentor-erste-generation','Cupra','Formentor','Erste Generation',2020,NULL,'["SUV-Coupé"]','Kompakt-SUV',NULL,'Der Cupra Formentor ist das erste eigenständige Modell der Marke Cupra und nicht als Seat erhältlich. Er zeichnet sich durch seine markante, coupéartige Dachlinie aus, die zum Heck hin stark abfällt. Die Frontpartie wird von schmalen LED-Scheinwerfern mit dreieckiger Tagfahrlichtsignatur und einem großen Kühlergrill mit Wabenstruktur dominiert. Am Heck verbindet ein durchgehendes LED-Leuchtenband die Rückleuchten, unter denen das Cupra-Logo platziert ist.','Im April 2024 wurde ein Facelift vorgestellt. Die überarbeitete Version verfügt über eine neu gestaltete Frontpartie mit dem Cupra-Logo nun auf der Motorhaube, neue Matrix-LED-Scheinwerfer mit einer weiterentwickelten dreieckigen Lichtsignatur und einem überarbeiteten Kühlergrill. Am Heck wurden die Leuchten neu gestaltet und das Cupra-Logo ist nun beleuchtet. Im Innenraum gibt es neue Materialien und ein größeres Infotainment-Display (optional 12,9 Zoll oder 15 Zoll).',NULL,NULL,NULL,5,2020,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('cupra-leon-erste-generation','Cupra','Leon','Erste Generation',2020,NULL,'["Schräghecklimousine", "Kombi"]','Kompaktklasse','seat-leon-dritte-generation','Die erste Generation des Cupra Leon ist eine Abspaltung vom Seat Leon. Erkennbar ist sie an der eigenständigen Front mit markanterer Schürze, den Cupra-spezifischen Felgen und dem Cupra-Logo. Im Innenraum unterscheidet sie sich durch sportlichere Sitze und Cupra-Akzente.',NULL,NULL,NULL,NULL,5,2020,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-ecosport-first-generation','Ford','EcoSport','First generation',2012,2022,'["SUV"]','Mini-SUV',NULL,'Die erste Generation des Ford EcoSport (interner Code B515) zeichnet sich durch eine kompakte SUV-Form mit einer relativ hohen Dachlinie und einer markanten Frontpartie aus. Die Scheinwerfer sind schmal und langgezogen, oft mit einem leicht nach oben geschwungenen Design. Der Kühlergrill ist trapezförmig und sitzt relativ hoch. Ein charakteristisches Merkmal vieler früher Modelle, insbesondere außerhalb Europas, war das außen an der Heckklappe montierte Reserverad, das später für den europäischen Markt optional oder entfiel. Im Vergleich zum späteren Facelift und der zweiten Generation ist die Front weniger aggressiv und die Scheinwerfer sind weniger kantig.','Das erste große Facelift erfolgte 2017 (Modelljahr 2018). Die Front wurde komplett überarbeitet mit einem größeren, sechseckigen Kühlergrill im Stil des Kuga und Focus, neuen, schärfer gezeichneten Scheinwerfern mit integriertem LED-Tagfahrlicht und einer neu gestalteten Motorhaube. Die Nebelscheinwerfer wurden in die unteren Lufteinlässe integriert. Am Heck wurden die Stoßfänger und die Rückleuchten leicht modifiziert. Im Innenraum gab es ein deutlich aufgewertetes Armaturenbrett mit einem freistehenden Touchscreen-Infotainmentsystem und hochwertigeren Materialien. Das außenliegende Reserverad entfiel für die meisten Märkte, war aber in einigen Regionen weiterhin optional.',NULL,NULL,NULL,4,2013,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-ecosport-second-generation','Ford','EcoSport','Second generation',2013,2023,'["SUV"]','Mini-SUV',NULL,'Die zweite Generation des Ford EcoSport zeichnet sich durch eine kompakte SUV-Form mit einer erhöhten Bodenfreiheit aus. Charakteristisch sind die relativ schmalen, hoch positionierten Scheinwerfer, der trapezförmige Kühlergrill (anfangs mit horizontalen Lamellen, später mit Wabenmuster) und die seitlich öffnende Heckklappe, die bei den frühen Modellen oft ein außenliegendes Reserverad trug. Die Dachlinie fällt leicht nach hinten ab.','Das erste größere Facelift erfolgte 2017 (Modelljahr 2018). Dabei wurde die Frontpartie deutlich überarbeitet: Der Kühlergrill erhielt ein neues Design (oft Wabenmuster), die Scheinwerfer wurden schlanker und moderner, und die Nebelscheinwerfer wurden neu positioniert. Im Innenraum gab es ein neues Armaturenbrett mit einem freistehenden Touchscreen. Das außenliegende Reserverad wurde optional oder entfiel ganz. Ein weiteres, kleineres Update gab es 2021 mit leichten Anpassungen an der Ausstattung und den Motoren.',NULL,NULL,NULL,4,2013,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk1','Ford','Fiesta','Mk1',1976,1983,'["3-Türer Schrägheck", "Kastenwagen"]','Kleinwagen',NULL,'Der Fiesta Mk1 zeichnet sich durch seine kompakte, kantige Form mit runden Scheinwerfern und einer schmalen, horizontalen Kühlergrillspange aus. Die Heckleuchten sind klein und quadratisch. Im Vergleich zu späteren Generationen wirkt er sehr schlicht und funktional, ohne die aerodynamischen oder runderen Formen der Nachfolger.','Im Jahr 1981 erhielt der Fiesta Mk1 ein leichtes Facelift. Die auffälligsten Änderungen waren eine überarbeitete Front mit einem neuen Kühlergrill, der nun breiter war und das Ford-Logo in der Mitte trug, sowie größere Stoßfänger aus Kunststoff. Die Heckleuchten wurden ebenfalls leicht modifiziert und die Innenausstattung erhielt neue Stoffe und ein überarbeitetes Armaturenbrett.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk2','Ford','Fiesta','Mk2',1983,1989,'["Schrägheck"]','Kleinwagen','ford-fiesta-mk1','Der Mk2 unterscheidet sich vom Mk1 durch eine überarbeitete Front mit größeren Scheinwerfern und einem breiteren Kühlergrill. Die Heckleuchten wurden ebenfalls modifiziert und die Karosserieformen leicht angepasst, insbesondere die C-Säule.','1986 wurde ein Facelift durchgeführt, das eine neue Frontschürze, modifizierte Scheinwerfer und Rückleuchten sowie eine überarbeitete Innenausstattung brachte. Die Motorenpalette wurde ebenfalls aktualisiert.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der Ford Fiesta Mk2 war ein beliebtes Stadtauto, das für seine Zuverlässigkeit und sein gutes Fahrverhalten bekannt war. Achten Sie beim Kauf auf Rost, insbesondere an den Radläufen, Schwellern und der Heckklappe. Die Motoren sind generell robust, aber regelmäßige Wartung ist wichtig. Die Elektrik kann bei älteren Modellen anfällig sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk3','Ford','Fiesta','Mk3',1989,1996,'["3-Türer", "5-Türer", "Kastenwagen"]','Kleinwagen','ford-fiesta-mk2','Der Fiesta Mk3 unterscheidet sich deutlich vom kantigeren Vorgänger durch ein runderes, aerodynamischeres Design. Er besitzt größere, abgerundete Scheinwerfer, die fließender in die Karosserie übergehen, sowie integrierte Stoßfänger. Die Heckleuchten sind ebenfalls größer und runder gestaltet. Das Interieur wurde komplett überarbeitet und wirkt moderner.','Im Jahr 1994 (oft als ''Fiesta ''94'' oder Mk3.5 bezeichnet) erhielt der Fiesta Mk3 ein Facelift. Die Änderungen umfassten eine leicht überarbeitete Frontschürze, geringfügig modifizierte Scheinwerfer und Heckleuchten. Wichtiger waren die technischen Neuerungen wie der serienmäßige Fahrerairbag und verbesserter Seitenaufprallschutz.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk4','Ford','Fiesta','Mk4',1995,2002,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kleinwagen','ford-fiesta-mk3','Die vierte Generation des Ford Fiesta zeichnet sich durch ein deutlich runderes und weicheres Design im Vergleich zum kantigeren Vorgänger aus. Prägnant sind die großen, ovalen Scheinwerfer und der ebenfalls ovale Kühlergrill, der in die Frontschürze integriert ist. Die Karosserie wirkt insgesamt stromlinienförmiger und weniger eckig.','Im Jahr 1999 erfolgte ein Facelift (oft als Mk4.5 oder MkIVb bezeichnet). Die Front erhielt einen neu gestalteten Stoßfänger mit größerem Lufteinlass und einen markanteren, oft verchromten ovalen Kühlergrill. Die Scheinwerfer wurden leicht überarbeitet und erhielten klarere Gläser. Auch die Heckleuchten wurden dezent modifiziert. Im Innenraum gab es kleinere Änderungen an Materialien und Lenkrad.',NULL,NULL,NULL,2,1997,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk5','Ford','Fiesta','Mk5',2002,2008,'["Schrägheck 3-Türer", "Schrägheck 5-Türer", "Kastenwagen"]','Kleinwagen','ford-fiesta-mk4','Der Fiesta Mk5 (intern B256/B299) zeichnet sich durch ein deutlich runderes und moderneres Design im Vergleich zum kantigeren Vorgänger aus. Auffällig sind die großen, mandelförmigen Scheinwerfer, die weit in die Kotflügel reichen, sowie die abgerundete Frontschürze mit einem breiten, ovalen Lufteinlass. Die Seitenlinie ist fließender, und die Heckleuchten sind vertikal angeordnet und reichen bis in die C-Säule.','Im November 2005 erfolgte ein Facelift. Die Front erhielt einen größeren, trapezförmigen Kühlergrill im Stil des Ford Focus Mk2, neue Stoßfänger und leicht überarbeitete Scheinwerfer mit integrierten Blinkern. Die Heckleuchten wurden leicht modifiziert und die Innenraummaterialien sowie die Instrumententafel aufgewertet.',NULL,NULL,NULL,4,2002,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk6','Ford','Fiesta','Mk6',2001,2008,'["Schrägheck 3-türig", "Schrägheck 5-türig"]','Kleinwagen','ford-fiesta-mk5','Der Ford Fiesta Mk6 (auch als Fiesta VI bekannt) zeichnet sich durch sein rundlicheres, fließendes Design im Vergleich zum kantigeren Vorgänger Mk5 aus. Auffällig sind die großen, mandelförmigen Scheinwerfer, die weit in die Kotflügel reichen, sowie die vertikal angeordneten Rückleuchten. Die Frontpartie wirkt insgesamt weicher und weniger aggressiv als beim Nachfolger Mk7.','Im Jahr 2005 erhielt der Fiesta Mk6 ein Facelift. Die markantesten Änderungen umfassten eine neu gestaltete Frontschürze mit einem größeren, trapezförmigen Kühlergrill, Klarglas-Scheinwerfer und überarbeitete Rückleuchten mit einer neuen Innenaufteilung. Auch im Innenraum gab es kleinere Anpassungen, wie neue Materialien und Farben.',NULL,NULL,NULL,4,2002,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-fiesta-mk7','Ford','Fiesta','Mk7',2008,2017,'["Schrägheck", "Dreitürer", "Fünftürer"]','Kleinwagen','ford-fiesta-mk6','Der Fiesta Mk7 zeichnet sich durch Fords ''Kinetic Design''-Sprache aus. Er besitzt markante, nach hinten gezogene Scheinwerfer, eine dynamisch geformte Karosserie mit einer aufsteigenden Seitenlinie und einen trapezförmigen Kühlergrill, der nach dem Facelift deutlich größer und prägnanter wurde. Im Vergleich zum Vorgänger (Mk6) wirkt er runder, sportlicher und weniger kantig.','Das Facelift erfolgte Ende 2012 (Modelljahr 2013). Das auffälligste Merkmal ist der große, trapezförmige Kühlergrill im ''Aston Martin''-Stil. Die Scheinwerfer wurden neu gestaltet und konnten optional mit LED-Tagfahrlicht ausgestattet werden. Die Frontschürze erhielt ein neues Design, und die Heckleuchten wurden leicht überarbeitet. Im Innenraum gab es neue Materialien, eine überarbeitete Mittelkonsole und das SYNC-Infotainmentsystem.',NULL,NULL,NULL,5,2008,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-focus-mk1','Ford','Focus','Mk1',1998,2004,'["Schräghecklimousine", "Kombi"]','Kompaktklasse','Escort','Der Ford Focus Mk1 löste den Escort ab. Er zeichnet sich durch ein deutlich moderneres Design aus, insbesondere durch die ''New Edge''-Designsprache mit scharfen Linien und dreieckigen Elementen an Front und Heck. Die Scheinwerfer sind größer und trapezförmig, die Heckleuchten sind vertikal angeordnet und ragen in die Seitenwand.','Das Facelift im Jahr 2001 brachte eine überarbeitete Frontschürze, neue Scheinwerfer mit Klarglasoptik, geänderte Rückleuchten und eine verbesserte Innenausstattung mit höherwertigen Materialien. Die Motorenpalette wurde ebenfalls aktualisiert.',NULL,NULL,NULL,4,2000,NULL,'24 Monate','Der Focus Mk1 gilt als solides und fahrdynamisches Fahrzeug. Achten Sie auf Rost an Radläufen, Schwellern und Türen. Probleme können bei älteren Modellen mit der Elektrik, dem Auspuff und der Kupplung auftreten. Die Motoren sind generell robust, aber regelmäßige Wartung ist wichtig.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-focus-mk2','Ford','Focus','Mk2',2004,2011,'["Schrägheck 3-Türer", "Schrägheck 5-Türer", "Limousine", "Kombi", "Coupé-Cabriolet"]','Kompaktklasse','ford-focus-mk1','Der Focus Mk2 ist deutlich größer und erwachsener als sein Vorgänger. Er zeichnet sich durch größere, mandelförmige Scheinwerfer aus, die weiter in die Kotflügel reichen, eine markantere, trapezförmige Kühlergrillöffnung und eine insgesamt rundlichere, aber straffere Karosserielinie. Die Heckleuchten sind ebenfalls größer und ragen stärker in die Seitenflanken hinein.','Das Facelift (oft als Mk2.5 bezeichnet) wurde Ende 2007 vorgestellt und ab Anfang 2008 verkauft. Es brachte eine umfassende Überarbeitung im Stil des ''Kinetic Design'' von Ford. Die Front erhielt einen deutlich größeren, umgedrehten Trapezgrill, neue, spitzer zulaufende Scheinwerfer, die bis in die Kotflügel reichen, und eine neu gestaltete Motorhaube mit stärker ausgeprägten Sicken. Am Heck wurden die Rückleuchten leicht modifiziert und die Stoßfänger neu gestaltet. Im Innenraum gab es neue Materialien und ein überarbeitetes Armaturenbrett mit neuen Bedienelementen.',NULL,NULL,NULL,5,2004,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-focus-mk3','Ford','Focus','Mk3',2011,2018,'["Schrägheck", "Limousine", "Kombi"]','Kompaktklasse','ford-focus-mk2','Der Focus Mk3 zeichnet sich durch das ''Kinetic Design 2.0'' aus, das sich durch eine sehr dynamische und fließende Linienführung kennzeichnet. Auffällig sind die schlanken, weit nach hinten gezogenen Scheinwerfer, die bis in die Kotflügel reichen, sowie der markante, trapezförmige Kühlergrill (vor Facelift eher schmal, nach Facelift breiter und tiefer). Die Seitenlinie ist stark ansteigend, und das Heck wirkt im Vergleich zum Vorgänger deutlich sportlicher und weniger kantig.','Das Facelift (ab 2014/2015) brachte eine umfassende Überarbeitung der Frontpartie mit sich. Der Kühlergrill wurde deutlich vergrößert und erhielt die markante ''Aston Martin''-Optik, die zu dieser Zeit typisch für Ford war. Die Scheinwerfer wurden schmaler und erhielten eine neue Lichtsignatur (optional mit Bi-Xenon). Auch die Nebelscheinwerfer und die Stoßfänger wurden neu gestaltet. Am Heck gab es kleinere Änderungen an den Rückleuchten und der Heckschürze. Im Innenraum wurde das Armaturenbrett vereinfacht, die Anzahl der Knöpfe reduziert und das Infotainmentsystem auf SYNC 2 (später SYNC 3) aktualisiert.',NULL,NULL,NULL,5,2012,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-focus-mk4','Ford','Focus','Mk4',2018,NULL,'["Limousine", "Kombi"]','Kompaktklasse','ford-focus-mk3','Der Focus Mk4 zeichnet sich durch eine deutlich dynamischere und fließendere Designsprache aus als sein Vorgänger. Auffällig sind die schmaleren, weiter nach hinten gezogenen Scheinwerfer, der breitere, tiefer sitzende Kühlergrill mit Wabenstruktur (je nach Ausstattung) und die stärker ausgeprägten Seitenlinien. Am Heck fallen die zweigeteilten, horizontal ausgerichteten Rückleuchten auf, die sich bis in die Heckklappe ziehen und das Fahrzeug breiter wirken lassen. Die Motorhaube ist länger und flacher gestaltet.','Im Oktober 2021 wurde ein Facelift vorgestellt. Die Front wurde überarbeitet mit einem größeren, höher positionierten Kühlergrill, der nun das Ford-Logo trägt. Die Scheinwerfer sind schlanker und verfügen über eine neue Lichtsignatur mit integrierten Nebelscheinwerfern. Am Heck wurden die Rückleuchten leicht modifiziert und erhielten eine dunklere Tönung. Im Innenraum wurde ein neues, größeres 13,2-Zoll-Infotainment-Display mit SYNC 4 eingeführt.',NULL,NULL,NULL,5,2018,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-galaxy-first-generation','Ford','Galaxy','First generation',1995,2006,'["Van", "Großraumlimousine"]','Van',NULL,'Die erste Generation des Ford Galaxy ist an ihrer geräumigen, kastenartigen Karosserieform erkennbar, die typisch für Großraumlimousinen der 90er Jahre ist. Die Front zeichnet sich durch große, rechteckige Scheinwerfer und einen schmalen Kühlergrill mit dem ovalen Ford-Logo aus. Die Heckleuchten sind vertikal angeordnet und flankieren die Heckklappe. Er teilt sich die Plattform und viele Karosserieteile mit dem VW Sharan I und dem Seat Alhambra I.','Im Jahr 2000 erfolgte ein umfassendes Facelift. Die Front wurde komplett überarbeitet mit größeren, mandelförmigen Scheinwerfern, einem markanteren Kühlergrill und einer neuen Stoßstange. Auch die Heckleuchten erhielten ein neues Design, das nun stärker in die Heckklappe hineinragte. Die Seitenlinie wurde durch neue Zierleisten und geänderte Außenspiegel modernisiert. Im Innenraum wurden Armaturenbrett und Mittelkonsole neu gestaltet.',NULL,NULL,NULL,3,1999,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-galaxy-second-generation','Ford','Galaxy','Second generation',2006,2015,'["Großraumlimousine"]','Großraum-Van','ford-galaxy-first-generation','Die zweite Generation des Ford Galaxy (intern WA6) unterscheidet sich deutlich vom Vorgänger durch eine modernere, fließendere Karosserieform. Charakteristisch sind die schräg nach hinten gezogenen, größeren Scheinwerfer, der trapezförmige Kühlergrill und die stärker geneigte Windschutzscheibe, die eine Einheit mit der Motorhaube bildet. Im Vergleich zum Vorgänger wirkt er weniger kastenförmig und dynamischer, mit einer ausgeprägteren Seitenlinie und größeren Heckleuchten, die sich in die Heckklappe erstrecken.','Im Jahr 2010 erfolgte ein Facelift. Dabei wurden die Frontpartie mit einem größeren, trapezförmigen unteren Kühlergrill und einem schmaleren oberen Kühlergrill überarbeitet. Die Scheinwerfer erhielten eine neue Innenstruktur mit LED-Tagfahrlicht. Am Heck wurden die Rückleuchten leicht modifiziert und die Heckklappe erhielt eine Chromleiste. Im Innenraum gab es neue Materialien und eine überarbeitete Mittelkonsole.',NULL,NULL,NULL,5,2006,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-kuga-mk1','Ford','Kuga','Mk1',2008,2012,'["SUV"]','Kompakt-SUV',NULL,'Der Kuga Mk1 zeichnet sich durch ein rundlicheres, weniger kantiges Design im Vergleich zum Nachfolger aus. Auffällig sind die großen, weit in die Kotflügel gezogenen Scheinwerfer, der trapezförmige untere Kühlergrill und die runden Nebelscheinwerfer. Die Heckleuchten sind relativ hoch positioniert und haben eine markante C-Form, die sich um die Seite zieht. Die Fensterlinie steigt nach hinten leicht an.',NULL,NULL,NULL,NULL,5,2008,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-kuga-mk2','Ford','Kuga','Mk2 (C520)',2012,2019,'["SUV"]','Kompakt-SUV','ford-kuga-mk1','Der Kuga Mk2 unterscheidet sich vom Vorgänger durch ein deutlich runderes und fließenderes Design. Er besitzt einen größeren, trapezförmigen Kühlergrill und schlankere, nach hinten gezogene Scheinwerfer. Die Heckleuchten sind ebenfalls schmaler und ziehen sich stärker in die Heckklappe hinein, was ihm ein dynamischeres Erscheinungsbild verleiht.','Das Facelift (ab 2016) brachte einen markanteren, sechseckigen Kühlergrill (oft als ''Aston Martin''-Grill bezeichnet), neu gestaltete, schmalere Scheinwerfer mit optionalem LED-Tagfahrlicht und überarbeitete Nebelscheinwerfer. Am Heck wurden die Leuchten leicht modifiziert und die Stoßfänger neu geformt. Im Innenraum gab es ein neues Lenkrad und das SYNC 3 Infotainmentsystem.',NULL,NULL,NULL,5,2012,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-kuga-mk3','Ford','Kuga','Mk3',2019,NULL,'["SUV"]','Kompakt-SUV','ford-kuga-mk2','Die dritte Generation des Ford Kuga ist deutlich dynamischer und flacher gezeichnet als der Vorgänger. Sie zeichnet sich durch eine coupéhaftere Dachlinie, eine größere und höher positionierte Frontpartie mit markanterem Kühlergrill und schlankere, höher angesetzte LED-Scheinwerfer aus. Die Heckleuchten sind ebenfalls schmaler und horizontaler ausgerichtet. Im Innenraum dominiert ein größerer, freistehender Touchscreen und ein digitales Kombiinstrument.','Ein Facelift wurde Ende 2023 vorgestellt und ist seit 2024 erhältlich. Es umfasst eine neu gestaltete Frontpartie mit einem größeren Kühlergrill, der das Ford-Logo integriert, sowie neu gezeichnete LED-Scheinwerfer mit einer durchgehenden Lichtleiste. Am Heck gibt es überarbeitete Rückleuchten. Im Innenraum wurde ein größerer 13,2-Zoll-Infotainment-Bildschirm eingeführt und die Ausstattungslinien neu strukturiert (z.B. Active, ST-Line).',NULL,NULL,NULL,5,2019,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mondeo-mk1','Ford','Mondeo','Mk1',1993,1996,'["Limousine", "Kombi"]','Mittelklasse','Ford Sierra','Der Mondeo Mk1 löste den Sierra ab und brachte ein deutlich moderneres Design mit abgerundeten Formen, integrierten Stoßfängern und einer markanten, nach unten gezogenen Kühlerniere. Die Scheinwerfer waren größer und integrierten Blinker. Die Karosserie wirkte insgesamt breiter und flacher als beim Vorgänger.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mondeo-mk2','Ford','Mondeo','Mk2',1996,2000,'["Limousine", "Kombi", "Schrägheck"]','Mittelklasse','ford-mondeo-mk1','Der Mondeo Mk2 (intern ''96er Mondeo) ist eine umfassende Überarbeitung des Mk1. Er zeichnet sich durch eine deutlich rundlichere Frontpartie mit größeren, ovaleren Scheinwerfern und einem breiteren, ovalen Kühlergrill aus. Die Motorhaube ist stärker gewölbt. Am Heck wurden die Rückleuchten neu gestaltet und sind nun breiter und runder. Die Seitenlinie blieb weitgehend erhalten, aber die Stoßfänger wurden integrierter und runder.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mondeo-mk3','Ford','Mondeo','Mk3',2000,2007,'["Limousine", "Kombi", "Fließheck"]','Mittelklasse','ford-mondeo-mk2','Der Mk3 Mondeo unterscheidet sich deutlich vom Mk2. Er hat eine rundere, modernere Karosserieform mit größeren Scheinwerfern und einem breiteren Kühlergrill. Die Seitenlinie ist fließender und die Heckleuchten sind horizontaler und breiter gestaltet. Im Innenraum wurde das Design komplett überarbeitet und wirkt deutlich hochwertiger.','Das Facelift im Jahr 2003 brachte eine überarbeitete Frontpartie mit einem größeren, trapezförmigen Kühlergrill, neuen Scheinwerfern und Stoßfängern. Auch das Heck wurde leicht modifiziert, insbesondere die Rückleuchten. Im Innenraum gab es Verbesserungen bei Materialien und Ergonomie.',NULL,NULL,NULL,4,2002,NULL,'24 Monate','Der Mondeo Mk3 bot ein gutes Preis-Leistungs-Verhältnis und war in verschiedenen Karosserievarianten erhältlich. Achten Sie auf Rost an Radläufen und Schwellern, insbesondere bei älteren Modellen. Probleme mit der Elektrik, wie z.B. defekte Fensterheber oder Zentralverriegelung, können auftreten. Die Dieselmotoren sind generell robust, aber auf die Wartungshistorie sollte geachtet werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mondeo-mk4','Ford','Mondeo','Mk4',2007,2014,'["Limousine", "Kombi", "Fließheck"]','Mittelklasse','ford-mondeo-mk3','Der Mondeo Mk4 zeichnet sich durch Fords ''Kinetic Design'' aus, erkennbar an der großen, trapezförmigen Kühlergrillöffnung, den markant nach hinten gezogenen Scheinwerfern und der dynamischen, fließenden Linienführung. Im Vergleich zum Vorgänger wirkt er deutlich größer, breiter und sportlicher, mit einer ausgeprägten Schulterlinie und einer stärker geneigten Windschutzscheibe.','Ende 2010 (Modelljahr 2011) erfolgte ein Facelift. Die Front erhielt eine neue Stoßstange mit integrierten LED-Tagfahrleuchten, eine modifizierte Motorhaube und leicht überarbeitete Scheinwerfer. Am Heck wurden die Rückleuchten neu gestaltet und die Heckklappe angepasst. Im Innenraum gab es neue Materialien, eine überarbeitete Mittelkonsole und ein verbessertes Infotainmentsystem.',NULL,NULL,NULL,5,2007,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-fifth-generation','Ford','Mustang','Fifth generation (S197)',2004,2014,'["Coupé", "Cabriolet"]','Pony Car','ford-mustang-fourth-generation','Die fünfte Generation des Ford Mustang (S197) zeichnet sich durch ein stark retro-inspiriertes Design aus, das Elemente der ersten Mustang-Generation aufgreift. Charakteristisch sind die runden Hauptscheinwerfer, die von rechteckigen Blinkern flankiert werden, eine lange Motorhaube mit Powerdome und eine steil abfallende Heckscheibe. Im Vergleich zum Vorgänger (SN95) wirkt er deutlich muskulöser und weniger abgerundet, mit schärferen Linien und einer prominenteren Frontpartie. Die Rückleuchten sind vertikal angeordnet und dreigeteilt.','Ein umfassendes Facelift erfolgte für das Modelljahr 2010 (Produktion ab Ende 2009). Die Front wurde aerodynamischer gestaltet mit einer neuen, stärker geneigten Frontschürze, schmaleren Scheinwerfern und einer modifizierten Motorhaube. Die Rückleuchten wurden ebenfalls neu gestaltet, behielten die dreigeteilte Optik bei, waren aber flacher und mit LED-Technik ausgestattet. Das Interieur erhielt hochwertigere Materialien und ein überarbeitetes Armaturenbrett. Für das Modelljahr 2011 wurden neue Motoren eingeführt (3.7L V6 und 5.0L Coyote V8).',NULL,NULL,NULL,NULL,NULL,16000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-first-generation','Ford','Mustang','First generation',1964,1973,'["Coupé", "Cabriolet", "Fastback"]','Sportwagen',NULL,'Der Ford Mustang der ersten Generation zeichnet sich durch sein ikonisches ''Pony Car''-Design aus. Charakteristisch sind die langen Motorhauben, die kurzen Heckpartien, die vertikalen Rückleuchten und die seitlichen Lufteinlässe hinter den Türen. Die Frontpartie wird von einem Kühlergrill mit dem Mustang-Logo dominiert. Im Vergleich zu späteren Generationen ist das Design kantiger und weniger stromlinienförmig.','1967 gab es ein Facelift, das die Karosserie leicht vergrößerte und die Frontpartie überarbeitete, mit einem tieferen Kühlergrill und größeren Scheinwerfern. Die Rückleuchten wurden ebenfalls modifiziert. Ein weiteres Facelift folgte 1969 mit einer aggressiveren Front, neuen Seitenlinien und einer überarbeiteten Heckpartie.',NULL,NULL,NULL,NULL,NULL,NULL,'','Die erste Generation des Ford Mustang ist ein Klassiker mit Kultstatus. Bei der Suche nach einem Exemplar sollte auf Rost an typischen Stellen wie Radläufen, Schweller und Unterboden geachtet werden. Die Motoren (oft V8) sind in der Regel robust, aber eine Überprüfung des Zustands ist unerlässlich. Ersatzteile sind für die gängigsten Modelle gut verfügbar, können aber bei selteneren Varianten teuer werden. Die Fahrwerkskomponenten und Bremsen sollten auf Verschleiß geprüft werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-fourth-generation','Ford','Mustang','Fourth generation (SN95)',1994,2004,'["Coupé", "Cabriolet"]','Sportwagen','ford-mustang-third-generation','Die vierte Generation des Mustang (SN95) zeichnet sich durch ein deutlich runderes und aerodynamischeres Design im Vergleich zum kantigen Vorgänger (Fox Body) aus. Charakteristisch sind die integrierten, horizontalen Scheinwerfer, die markanten seitlichen Lufteinlässe hinter den Türen und die dreigeteilten Rückleuchten, die in die Karosserie integriert sind. Die Front wirkt weniger aggressiv als bei späteren Generationen.','Im Jahr 1999 erfolgte ein umfassendes Facelift, bekannt als ''New Edge''-Design. Dieses brachte schärfere Linien und eine aggressivere Optik mit sich. Die Scheinwerfer wurden größer und eckiger, die Kotflügel erhielten ausgeprägtere Kanten und die Front- und Heckschürzen wurden neu gestaltet, um dem Fahrzeug ein muskulöseres Erscheinungsbild zu verleihen. Die seitlichen Lufteinlässe wurden ebenfalls überarbeitet.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-mach-e-first-generation','Ford','Mustang Mach-E','First generation',2020,NULL,'["SUV", "Crossover"]','Mittelklasse-SUV',NULL,'Der Mustang Mach-E ist ein rein elektrisches SUV mit einer coupéartigen Dachlinie. Er zeichnet sich durch Mustang-typische Designelemente aus, wie die dreigeteilten Rückleuchten, die lange Motorhaube (obwohl elektrisch) und die muskulösen Radhäuser. Die Front ist durch einen geschlossenen Kühlergrill mit dem Mustang-Pony-Logo und schmalen LED-Scheinwerfern geprägt. Im Vergleich zu anderen Ford-SUVs ist seine Silhouette deutlich sportlicher und dynamischer.',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-second-generation','Ford','Mustang','Second generation',1974,1978,'["Coupe", "Hatchback"]','Pony Car','ford-mustang-first-generation','Die zweite Generation des Ford Mustang, oft als Mustang II bezeichnet, ist deutlich kompakter und kleiner als ihr Vorgänger. Sie zeichnet sich durch eine kantigere Karosserieform aus, oft mit einzelnen, rechteckigen Scheinwerfern (spätere Modelle oder bestimmte Ausstattungslinien konnten auch Doppelrundscheinwerfer haben). Die Frontpartie ist weniger aggressiv als die des ersten Mustang, mit einem markanten Kühlergrill, der das Mustang-Pferd trägt. Das Heck ist entweder als klassisches Notchback-Coupe oder als dreitüriges Fließheck (Hatchback) ausgeführt, das eine stärkere Neigung als die Fastback-Varianten des Vorgängers aufweist.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-sixth-generation','Ford','Mustang','Sixth generation (S550)',2014,2023,'["Coupé", "Cabriolet"]','Sportwagen','ford-mustang-fifth-generation','Die sechste Generation des Mustang (S550) unterscheidet sich deutlich vom Vorgänger durch ein moderneres, weniger retro-inspiriertes Design. Charakteristisch sind die schärfer gezeichneten, schmaleren Scheinwerfer mit drei vertikalen LED-Tagfahrlichtern (Tri-Bar-DRLs) und ein trapezförmiger Kühlergrill. Die Karosserie wirkt flacher und breiter, und am Heck finden sich neu interpretierte dreigeteilte LED-Rückleuchten. Technisch ist die Einführung einer Einzelradaufhängung an der Hinterachse ein wesentliches Merkmal.','Ein Facelift erfolgte 2017 (Modelljahr 2018). Die Frontpartie wurde überarbeitet mit einer tieferen Motorhaube, einem neu gestalteten Kühlergrill und schlankeren, aggressiver wirkenden LED-Scheinwerfern. Die Stoßfänger wurden ebenfalls modifiziert. Am Heck gab es kleinere Anpassungen an den Rückleuchten und dem Diffusor. Im Innenraum wurden hochwertigere Materialien und ein optionales digitales Kombiinstrument eingeführt.',NULL,NULL,NULL,3,2017,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-mustang-third-generation','Ford','Mustang','Third generation',1979,1993,'["Coupé", "Hatchback", "Cabriolet"]','Sportwagen','ford-mustang-second-generation','Die dritte Generation des Ford Mustang, bekannt als ''Fox Body'', zeichnet sich durch ihre kantige und aerodynamische Form aus, die einen deutlichen Bruch mit dem runderen Design des Vorgängers darstellt. Anfangs waren rechteckige Scheinwerfer prägend, die ab dem Facelift 1987 durch bündig integrierte, schräge ''Aero''-Scheinwerfer ersetzt wurden. Typisch sind die lange Motorhaube und das kurze Heck, sowie die Verfügbarkeit als Notchback (Stufenheck-Coupé), Hatchback (Schrägheck) und Cabriolet.','Ein signifikantes Facelift erfolgte 1987. Die auffälligsten Änderungen waren die Einführung von bündig integrierten, schrägen ''Aero''-Scheinwerfern und eine überarbeitete Frontschürze, die dem Fahrzeug ein moderneres und aerodynamischeres Aussehen verlieh. Auch die Heckleuchten und Stoßfänger wurden angepasst, um das Design zu harmonisieren.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-puma-mk1','Ford','Puma','Mk1',1997,2002,'["Coupé"]','Sportcoupé',NULL,'Der Ford Puma Mk1 ist ein kompaktes 2+2-sitziges Coupé, das auf der Plattform des Fiesta Mk4 basiert. Charakteristisch sind die großen, mandelförmigen Scheinwerfer, die sich weit in die Kotflügel ziehen, sowie die fließende Dachlinie, die in einem kurzen Heck endet. Die Frontpartie wird von einem ovalen Kühlergrill dominiert, der typisch für das New Edge Design von Ford aus dieser Ära ist. Im Vergleich zu anderen Ford-Modellen der Zeit (z.B. Fiesta, Focus) wirkt der Puma deutlich sportlicher und dynamischer.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('ford-puma-mk2','Ford','Puma','Mk2',2019,NULL,'["SUV", "Crossover"]','Kleinwagen-SUV','ford-puma-mk1','Der Ford Puma Mk2 unterscheidet sich grundlegend vom Vorgänger durch seine SUV-Karosserieform im B-Segment, während der Mk1 ein Sportcoupé war. Er ist erkennbar an seinen hoch positionierten, mandelförmigen LED-Scheinwerfern, dem großen, trapezförmigen Kühlergrill und der coupéhaften Dachlinie. Die Karosserie ist deutlich höher und bulliger als die des Fiesta, auf dessen Plattform er basiert.','Im Jahr 2024 erhielt der Puma ein Facelift. Die Änderungen umfassen eine neu gestaltete Frontschürze, überarbeitete Scheinwerfer mit einer neuen LED-Lichtsignatur, ein aktualisiertes Interieur mit einem größeren zentralen Touchscreen (12 Zoll) und einem neuen digitalen Kombiinstrument (12,8 Zoll) sowie eine leicht modifizierte Heckpartie.',NULL,NULL,NULL,5,2019,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i10-dritte-generation','Hyundai','i10','Dritte Generation',2020,NULL,'["Kleinwagen"]','A','hyundai-i10-zweite-generation','Die dritte Generation des Hyundai i10 (ab 2020) unterscheidet sich deutlich von seinem Vorgänger. Auffällig sind die breitere und flachere Karosserie, die schärfer gezeichneten Scheinwerfer mit integrierten Tagfahrlichtern und die markante, trapezförmige Kühlermaske. Die Heckleuchten sind nun horizontal angeordnet und in die Heckklappe integriert, was dem Fahrzeug einen moderneren und sportlicheren Look verleiht. Die Fensterlinie ist ebenfalls neu gestaltet und verleiht dem i10 ein dynamischeres Profil.',NULL,NULL,NULL,NULL,3,2020,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i10-erste-generation','Hyundai','i10','Erste Generation',2007,2013,'["Steilheck"]','Kleinstwagen','hyundai-atos','Die erste Generation des Hyundai i10 zeichnet sich durch eine kompakte, abgerundete Karosserie mit einer relativ hohen Dachlinie aus. Die Front ist geprägt von großen, mandelförmigen Scheinwerfern, die weit in die Kotflügel reichen, und einem kleinen, trapezförmigen Kühlergrill. Die Heckleuchten sind vertikal angeordnet und reichen bis in die C-Säule. Im Vergleich zum Nachfolger (zweite Generation) wirkt er runder und weniger dynamisch, mit einer deutlich höheren Fensterlinie.','Im Jahr 2011 erfolgte ein Facelift. Die markantesten Änderungen waren neu gestaltete Scheinwerfer mit integriertem Tagfahrlicht (oft LED), ein größerer, sechseckiger Kühlergrill im Stil der damaligen Hyundai-Designsprache (''Fluidic Sculpture'') und überarbeitete Stoßfänger vorne und hinten. Am Heck wurden die Rückleuchten leicht modifiziert und die Nebelschlussleuchte in den Stoßfänger integriert. Auch im Innenraum gab es kleinere Anpassungen an Materialien und Farben.',NULL,NULL,NULL,4,2008,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i10-zweite-generation','Hyundai','i10','Zweite Generation',2013,2020,'["Kleinwagen"]','A','hyundai-i10-erste-generation','Die zweite Generation des Hyundai i10 (2013-2020) unterscheidet sich von seinem Vorgänger durch eine breitere und flachere Silhouette, eine markantere Frontpartie mit größeren Scheinwerfern und einem trapezförmigen Kühlergrill sowie eine insgesamt modernere und dynamischere Linienführung. Die Heckleuchten sind horizontaler und integrieren sich stärker in die Heckklappe.','Im Jahr 2016 erhielt der i10 ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill (jetzt mit aktiven Luftklappen bei einigen Modellen), neuen Stoßfängern vorne und hinten, sowie modifizierten Scheinwerfern und Rückleuchten. Im Innenraum gab es neue Ausstattungsoptionen und ein überarbeitetes Infotainmentsystem.',NULL,NULL,NULL,4,2014,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i20-dritte-generation','Hyundai','i20','Dritte Generation',2020,NULL,'["Fünftürige Steilhecklimousine"]','Kleinwagen','hyundai-i20-zweite-generation','Die dritte Generation des Hyundai i20 zeichnet sich durch ein deutlich dynamischeres Design aus. Auffällig sind der breitere, tiefer positionierte Kühlergrill, die scharf gezeichneten LED-Scheinwerfer mit integriertem Tagfahrlicht und die markante Z-förmige Seitenlinie, die in die Rückleuchten übergeht. Am Heck sind die Rückleuchten durch eine Chromleiste oder ein durchgehendes Leuchtenband (je nach Ausstattung und Facelift) verbunden, was ihn klar vom Vorgänger abgrenzt.','Im Jahr 2023 (Modelljahr 2024) erhielt der i20 ein Facelift. Die Änderungen umfassen eine neu gestaltete Frontschürze mit einem überarbeiteten Kühlergrillmuster und neuen Lufteinlässen. Die LED-Scheinwerfer und Rückleuchten wurden leicht modifiziert, wobei das durchgehende Leuchtenband am Heck nun stärker betont wird. Neue Leichtmetallfelgen-Designs und zusätzliche Außenfarben wurden eingeführt. Im Innenraum gab es kleinere Anpassungen, wie neue digitale Instrumente und USB-C-Anschlüsse.',NULL,NULL,NULL,4,2020,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i20-erste-generation','Hyundai','i20','Erste Generation',2008,2014,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kleinwagen','Hyundai Getz','Die erste Generation des Hyundai i20 zeichnet sich durch eine eher rundliche, kompakte Karosserie aus. Die Front wird von großen, mandelförmigen Scheinwerfern dominiert, die weit in die Kotflügel gezogen sind. Der Kühlergrill ist schmal und meist in Wagenfarbe oder Schwarz gehalten, mit horizontalen Lamellen. Im Vergleich zum Nachfolger (zweite Generation) wirkt er weniger kantig und besitzt nicht den markanten, großen Hexagonalgrill.','Im Jahr 2012 erhielt der i20 ein Facelift. Die auffälligsten Änderungen waren die Einführung des neuen, hexagonalen Hyundai-Familiengrills, neu gestaltete Stoßfänger vorne und hinten sowie überarbeitete Scheinwerfer, die optional mit LED-Tagfahrlicht erhältlich waren. Auch die Nebelscheinwerfer wurden neu geformt.',NULL,NULL,NULL,5,2009,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i20-zweite-generation','Hyundai','i20','Zweite Generation',2014,2020,'["Schräghecklimousine", "Kombilimousine"]','Kleinwagen','hyundai-i20-erste-generation','Die zweite Generation des Hyundai i20 (intern GB/IB) unterscheidet sich deutlich vom Vorgänger. Auffällig sind die nun größeren und schärfer gezeichneten Scheinwerfer, die bis weit in die Kotflügel reichen. Der Kühlergrill ist trapezförmig und tiefer positioniert. Die C-Säule ist nun schwarz abgesetzt und erzeugt einen schwebenden Dach-Effekt, was dem Fahrzeug ein moderneres Aussehen verleiht. Die Rückleuchten sind horizontaler und breiter geworden.','Im Jahr 2018 erhielt der i20 ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill mit Wabendesign, neuen Front- und Heckstoßfängern sowie geänderten Scheinwerfern und Rückleuchten. Im Innenraum gab es ein neues Infotainmentsystem und überarbeitete Materialien.',NULL,NULL,NULL,4,2014,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i30-dritte-generation','Hyundai','i30','Dritte Generation',2017,NULL,'["Schrägheck", "Kombi", "Fastback"]','Kompaktklasse','hyundai-i30-zweite-generation','Die dritte Generation des Hyundai i30 (Baureihe PD) ist erkennbar am markanten, breiten Kaskaden-Kühlergrill, der von schlanken, horizontal ausgerichteten Scheinwerfern flankiert wird. Im Vergleich zum Vorgänger wirkt das Design erwachsener und sportlicher, mit schärferen Linien und einer breiteren, tieferen Statur. Die Fastback-Variante mit ihrer coupéartigen Dachlinie ist exklusiv für diese Generation.','Das erste Facelift (2020) brachte eine überarbeitete Front mit einem neuen Kühlergrillmuster, V-förmigen LED-Tagfahrlichtern und neu gestalteten Stoßfängern. Auch die Heckleuchten erhielten eine neue Lichtsignatur. Im Innenraum gab es ein größeres Infotainment-Display (bis zu 10,25 Zoll) und ein digitales Kombiinstrument. Das zweite Facelift (2024) führte ein nochmals modifiziertes Frontdesign mit einem neuen Kühlergrill und integrierten LED-Tagfahrlichtern in den Scheinwerfern ein, sowie weitere Detailänderungen an Stoßfängern und Felgen.',NULL,NULL,NULL,5,2017,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i30-erste-generation','Hyundai','i30','erste Generation',2007,2011,'["Schräghecklimousine", "Kombi"]','Kompaktklasse',NULL,'Die erste Generation des Hyundai i30 (Baureihe FD) löste den Hyundai Getz ab und war das erste Modell der Marke, das speziell für den europäischen Markt entwickelt wurde. Charakteristisch sind die relativ hohe Gürtellinie, die leicht nach hinten abfallende Dachlinie bei der Schräghecklimousine und die markante, leicht nach vorne geneigte Frontpartie mit den trapezförmigen Scheinwerfern und dem Kühlergrill. Der Kombi (CW) unterscheidet sich durch den längeren Radstand und das eigenständige Heckdesign mit den weit nach oben reichenden Rückleuchten.','Im Jahr 2010 erhielt der i30 ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill mit einer Chromspange, neuen Scheinwerfer- und Rückleuchtengrafiken sowie modifizierten Stoßfängern. Im Innenraum wurden die Materialien aufgewertet und die Instrumentenbeleuchtung geändert.',NULL,NULL,NULL,5,2008,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-i30-zweite-generation','Hyundai','i30','Zweite Generation',2012,2016,'["Schrägheck (5-Türer)", "Kombi", "Schrägheck (3-Türer)"]','Kompaktklasse','hyundai-i30-erste-generation','Die zweite Generation (GD) zeichnet sich durch das ''Fluidic Sculpture''-Design von Hyundai aus, mit einer deutlich fließenderen Linienführung als der Vorgänger. Auffällig sind die größeren, sechseckigen Kühlergrills, die stärker nach hinten gezogenen Scheinwerfer, die oft LED-Tagfahrlicht integrieren, und die ausgeprägteren Charakterlinien entlang der Fahrzeugseiten. Die Heckleuchten sind breiter und reichen weiter in die Seitenflanken hinein.','Das Facelift (GD2) im Jahr 2015 brachte dezente Änderungen mit sich. Dazu gehörten ein leicht modifizierter, nun stärker betonter sechseckiger Kühlergrill, neue Felgendesigns und eine überarbeitete Frontschürze. Im Innenraum gab es neue Materialien und verbesserte Infotainmentsysteme. Technisch wurden neue Motoren (z.B. 1.6 CRDi mit 136 PS) und ein 7-Gang-Doppelkupplungsgetriebe eingeführt.',NULL,NULL,NULL,5,2012,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-ioniq-5-erste-generation','Hyundai','Ioniq 5','Erste Generation',2021,NULL,'["SUV", "Crossover"]','Kompaktklasse',NULL,'Der Ioniq 5 unterscheidet sich deutlich von früheren Hyundai-Modellen. Charakteristisch sind die pixelartigen Scheinwerfer und Rückleuchten, die eine retro-futuristische Ästhetik aufweisen. Die Karosserie ist kantig und aufrecht, mit einem langen Radstand und kurzen Überhängen, was ihm ein einzigartiges, geräumiges Erscheinungsbild verleiht. Die C-Säule ist markant gestaltet und integriert Lüftungsschlitze.',NULL,NULL,NULL,NULL,5,2021,NULL,'','Der Hyundai Ioniq 5 ist ein rein elektrisches Kompakt-SUV, das auf der E-GMP-Plattform basiert. Er zeichnet sich durch sein futuristisches Design, ein geräumiges Interieur und schnelle Ladezeiten aus. Achten Sie bei der Auswahl auf die verschiedenen Batteriegrößen und Antriebsvarianten (Heckantrieb oder Allradantrieb). Die Verfügbarkeit von Sonderausstattungen wie dem Vision Roof (ein Glasdach ohne Trennstege) oder der Vehicle-to-Load (V2L)-Funktion kann den Komfort und die Funktionalität weiter erhöhen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-ioniq-6-erste-generation','Hyundai','Ioniq 6','Erste Generation',2022,NULL,'["Limousine"]','Obere Mittelklasse',NULL,'Die erste Generation des Hyundai Ioniq 6 zeichnet sich durch ihre stark stromlinienförmige, coupéartige Limousinen-Silhouette aus. Auffällig sind die ''Parametric Pixel''-Designelemente, die sich sowohl in den schmalen Frontscheinwerfern als auch in den durchgehenden Rückleuchten wiederfinden. Ein charakteristisches Merkmal ist der integrierte Heckspoiler im ''Entenbürzel''-Stil, der die aerodynamische Form unterstreicht. Die Karosserie ist sehr glatt und fließend gestaltet, mit versenkbaren Türgriffen und einer niedrigen Dachlinie.',NULL,NULL,NULL,NULL,5,2022,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-kona-erste-generation','Hyundai','Kona','Erste Generation',2017,2023,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Hyundai Kona zeichnet sich durch ein markantes, zweigeteiltes Scheinwerferdesign aus, bei dem die schmalen LED-Tagfahrlichter oben und die Hauptscheinwerfer darunter in separaten Einheiten angeordnet sind. Die Front dominiert der Hyundai-typische ''Cascading Grille''. Auffällig sind zudem die robust wirkenden Kunststoffverkleidungen um die Radhäuser und den unteren Karosseriebereich, die dem Fahrzeug einen Offroad-Charakter verleihen. Im Vergleich zum Nachfolger (zweite Generation) ist die erste Generation kompakter und hat eine weniger futuristische, aber eigenständige Formensprache.','Im Jahr 2020 erhielt der Kona ein Facelift. Die Front wurde überarbeitet mit einer breiteren, neu gestalteten Frontschürze und einem modifizierten Kühlergrill, der nun eine horizontalere Struktur aufweist. Die Tagfahrlichter wurden schmaler und die Hauptscheinwerfer erhielten eine neue Grafik. Am Heck wurden die Stoßfänger und die Leuchtengrafik leicht angepasst. Die Gesamtlänge des Fahrzeugs wuchs geringfügig. Im Innenraum gab es ein neues digitales Kombiinstrument und ein größeres Infotainment-Display.',NULL,NULL,NULL,5,2017,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-kona-zweite-generation','Hyundai','Kona','Zweite Generation',2023,NULL,'["SUV", "Crossover"]','Kleinwagen','hyundai-kona-erste-generation','Die zweite Generation des Hyundai Kona unterscheidet sich deutlich vom Vorgänger. Auffällig sind die durchgehenden LED-Lichtbänder an Front und Heck, die dem Fahrzeug eine futuristische Optik verleihen. Die Karosserie ist kantiger und insgesamt größer geworden, was sich auch im Innenraum bemerkbar macht. Die Radhäuser sind stärker ausgeprägt und die Seitenlinie wirkt dynamischer.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-santa-fe-dritte-generation','Hyundai','Santa Fe','DM',2012,2018,'["SUV"]','D-Segment','hyundai-santa-fe-zweite-generation','Die dritte Generation (DM) des Hyundai Santa Fe unterscheidet sich deutlich von seinem Vorgänger. Auffällig sind die schärfer gezeichneten Linien, die nun horizontal ausgerichtete Front mit dem sechseckigen Kühlergrill und die markanten Scheinwerfer, die sich weiter in die Kotflügel ziehen. Die Seitenlinie wirkt dynamischer mit einer ausgeprägten Charakterlinie. Das Heck ist ebenfalls neu gestaltet mit größeren Rückleuchten.','Das Facelift im Jahr 2015 brachte eine überarbeitete Front mit einem modifizierten Kühlergrill, neuen Scheinwerfer- und Nebelscheinwerferdesigns. Am Heck wurden die Rückleuchten angepasst und die Stoßfänger neu gestaltet. Im Innenraum gab es Verbesserungen bei Materialien und Infotainmentsystemen.',NULL,NULL,NULL,5,2012,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-santa-fe-erste-generation','Hyundai','Santa Fe','Erste Generation',2000,2006,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Hyundai Santa Fe (SM) wurde 2000 eingeführt. Charakteristisch sind die runden Scheinwerfer, die markante, leicht nach unten abfallende Motorhaube und die relativ kantige Karosserieform im Vergleich zu späteren Generationen. Die Heckleuchten sind vertikal angeordnet und reichen weit in die Seitenwand hinein.','Ein Facelift erfolgte im Jahr 2004. Äußerlich erkennbar an überarbeiteten Scheinwerfern und Rückleuchten, einem neuen Kühlergrill und modifizierten Stoßfängern. Im Innenraum gab es Anpassungen am Armaturenbrett und der Mittelkonsole.',NULL,NULL,NULL,4,2005,NULL,'24 Monate','Die erste Generation des Santa Fe ist ein robustes und geräumiges SUV, das sich gut für Familien eignet. Achten Sie beim Kauf auf Rost an Radläufen, Schwellern und dem Unterboden. Bei Fahrzeugen mit Automatikgetriebe sollte die Funktion geprüft werden. Die Dieselmotoren können anfällig für Probleme mit der Einspritzanlage sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-santa-fe-vierte-generation','Hyundai','Santa Fe','Vierte Generation',2018,2023,'["SUV"]','Mittelklasse-SUV','hyundai-santa-fe-dritte-generation','Die vierte Generation des Hyundai Santa Fe ist sofort an ihrem markanten Split-Light-Design zu erkennen, bei dem die schmalen LED-Tagfahrlichter hoch oben an der Motorhaubenkante platziert sind und die eigentlichen Hauptscheinwerfer darunter in separaten Einheiten sitzen. Der große, kaskadenförmige Kühlergrill dominiert die Front und ist breiter sowie präsenter als beim Vorgänger. Die Karosserie wirkt insgesamt muskulöser und kantiger, mit ausgeprägten Radhäusern und einer stärker konturierten Seitenlinie.','Im Jahr 2020 erhielt die vierte Generation ein umfassendes Facelift, das oft als ''zweite Phase'' oder ''Facelift-Generation'' bezeichnet wird. Die Front wurde stark überarbeitet: Der Kühlergrill wurde noch größer und breiter, reichte bis zu den Hauptscheinwerfern und erhielt ein neues, markanteres Gittermuster. Die T-förmigen LED-Tagfahrlichter wurden neu gestaltet und integrierten sich nun in die Scheinwerfereinheit. Auch die Stoßfänger vorne und hinten wurden neu geformt, und die Rückleuchten erhielten eine durchgehende Lichtleiste. Im Innenraum gab es ein neues Infotainmentsystem mit größerem Bildschirm und eine neu gestaltete Mittelkonsole mit Shift-by-Wire-Tasten statt eines klassischen Wählhebels.',NULL,NULL,NULL,5,2018,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-santa-fe-zweite-generation','Hyundai','Santa Fe','Zweite Generation',2006,2012,'["SUV"]','Mittelklasse-SUV','hyundai-santa-fe-erste-generation','Die zweite Generation des Santa Fe (Typ CM) ist deutlich runder und weniger kantig als ihr Vorgänger. Sie zeichnet sich durch eine größere, oft verchromte Kühlergrillpartie aus, die von geschwungenen, nach hinten gezogenen Scheinwerfern flankiert wird. Die Seitenlinie wirkt fließender, und die Heckleuchten sind größer und stärker in die Karosserie integriert, oft mit klaren Elementen für Blinker und Rückfahrlicht. Im Vergleich zur ersten Generation wirkt sie insgesamt moderner und erwachsener.','Im Jahr 2009 (Modelljahr 2010) erhielt die zweite Generation ein Facelift. Die Front wurde überarbeitet mit einem neuen Kühlergrill (oft mit horizontalen Lamellen), einem neu gestalteten Stoßfänger und geänderten Nebelscheinwerfern. Die Scheinwerfer erhielten teilweise dunklere Einfassungen. Am Heck gab es neue Rückleuchtengrafiken, teilweise mit LED-Technik. Im Innenraum wurden Materialien und Infotainmentsysteme aktualisiert.',NULL,NULL,NULL,4,2006,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-tucson-dritte-generation','Hyundai','Tucson','Dritte Generation',2015,2020,'["SUV"]','Kompakt-SUV','hyundai-tucson-zweite-generation','Die dritte Generation des Hyundai Tucson (TL) unterscheidet sich deutlich von seinem Vorgänger. Auffällig sind der neue, sechseckige Kühlergrill mit horizontalen Chromstreben, die integrierten LED-Tagfahrlichter in den Scheinwerfern und die markante, kantigere Linienführung der Karosserie mit stärker ausgeprägten Radhäusern. Die Heckleuchten sind schmaler und horizontaler gestaltet.','Das Facelift im Jahr 2018 brachte eine überarbeitete Front mit einem modifizierten Kühlergrill (oft mit "Cascading Grill"-Elementen), neuen Scheinwerfer- und Nebelscheinwerferdesigns sowie eine angepasste Heckschürze und neue Rückleuchten. Im Innenraum wurden Materialien und Infotainmentsysteme aufgewertet.',NULL,NULL,NULL,5,2015,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-tucson-erste-generation','Hyundai','Tucson','Erste Generation',2004,2010,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Hyundai Tucson zeichnet sich durch eine eher rundliche, aber robuste Karosserieform aus. Auffällig sind die großen, mandelförmigen Scheinwerfer, die weit in die Kotflügel reichen, sowie der relativ schmale Kühlergrill mit horizontalen Lamellen und dem zentral platzierten Hyundai-Logo. Die Heckleuchten sind vertikal angeordnet und reichen bis in die Heckklappe. Die Dachlinie fällt leicht nach hinten ab, und die Radhäuser sind deutlich ausgeformt.','Im Jahr 2007 erhielt der Tucson ein leichtes Facelift. Die Änderungen waren subtil und umfassten primär einen überarbeiteten Kühlergrill mit feineren Lamellen, leicht modifizierte Stoßfänger vorne und hinten sowie neue Designs für die Leichtmetallräder. Die Scheinwerfer und Heckleuchten blieben in ihrer Grundform erhalten, erhielten aber teilweise eine leicht geänderte Innenstruktur oder Klarglasoptik.',NULL,NULL,NULL,4,2006,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-tucson-vierte-generation','Hyundai','Tucson','Vierte Generation',2020,NULL,'["SUV"]','Kompakt-SUV','hyundai-tucson-dritte-generation','Die vierte Generation des Hyundai Tucson (NX4) unterscheidet sich deutlich von seinem Vorgänger. Auffälligstes Merkmal ist die ''Parametric Dynamics'' Designsprache mit integrierten Tagfahrlichtern in den Kühlergrill-Elementen, die bei Dunkelheit sichtbar werden. Die Karosserie wirkt kantiger und skulpturaler, mit markanten Linien und Radhäusern. Das Heck ist durchgängig mit einem Leuchtenband verbunden.','Ein Facelift wurde im Jahr 2024 angekündigt, das unter anderem eine überarbeitete Frontpartie mit neuem Kühlergrill und modifizierten Scheinwerfern sowie ein aktualisiertes Interieur mit größeren Displays und neuen Materialien mit sich bringt.',NULL,NULL,NULL,5,2021,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('hyundai-tucson-zweite-generation','Hyundai','Tucson','Zweite Generation',2009,2015,'["SUV"]','Kompakt-SUV','hyundai-tucson-erste-generation','Die zweite Generation des Hyundai Tucson (in Europa als ix35 bekannt) zeichnet sich durch ein deutlich dynamischeres und fließenderes Design im Vergleich zum kantigeren Vorgänger aus. Auffällig sind die geschwungenen, nach hinten gezogenen Scheinwerfer, die eine Verbindung zur Seitenlinie herstellen, sowie der trapezförmige Kühlergrill mit horizontalen Lamellen. Die Karosserie wirkt insgesamt runder und aerodynamischer, mit einer stärker ausgeprägten Schulterlinie und einer abfallenden Dachlinie zum Heck hin.','Im Jahr 2013 erfolgte ein Facelift, das hauptsächlich dezente Änderungen mit sich brachte. Dazu gehörten neue Bi-Xenon-Scheinwerfer mit LED-Tagfahrlicht, leicht überarbeitete Rückleuchten mit LED-Technik und neue Leichtmetallfelgen-Designs. Im Innenraum wurden hochwertigere Materialien und ein überarbeitetes Infotainmentsystem eingeführt.',NULL,NULL,NULL,5,2010,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-ceed-cd','Kia','Ceed','CD',2018,NULL,'["Kombi", "Schrägheck"]','Kompaktklasse','kia-ceed-jd','Die dritte Generation (CD) des Kia Ceed unterscheidet sich deutlich vom Vorgänger (JD). Auffällige Merkmale sind die schärfer gezeichneten Scheinwerfer mit integriertem Tagfahrlicht, die breitere und flachere "Tigernase"-Kühlergrill-Einrahmung und die insgesamt dynamischere Linienführung der Karosserie. Die Heckleuchten sind nun horizontaler und schmaler gestaltet.','Das Facelift im Jahr 2021 brachte eine überarbeitete Front mit neu gestaltetem Kühlergrill und Stoßfänger, angepasste Scheinwerfer- und Rückleuchtengrafiken sowie neue Felgendesigns. Im Innenraum wurde das Infotainmentsystem aktualisiert und die Materialanmutung verbessert.',NULL,NULL,NULL,5,2019,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-ceed-ed','Kia','Ceed','ED',2006,2012,'["Kombi", "Schräghecklimousine"]','Kompaktklasse',NULL,'Der Kia Ceed ED ist die erste Generation des Ceed. Erkennbar an den runden Scheinwerfern, der eher konventionellen Kühlerniere und der insgesamt etwas konservativeren Linienführung im Vergleich zum Nachfolger. Die Heckleuchten sind oft zweiteilig und reichen bis in die Heckklappe.','Im Jahr 2010 erhielt der Ceed ED ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontschürze, neuen Scheinwerfern mit leicht geänderter Form und einer modifizierten Kühlerniere. Auch die Rückleuchten wurden leicht angepasst. Im Innenraum gab es Verbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,5,2007,NULL,'24 Monate','Der Kia Ceed ED war bei seiner Einführung ein wichtiger Schritt für Kia und bot ein gutes Preis-Leistungs-Verhältnis. Achten Sie beim Gebrauchtkauf auf Rost an Radläufen und Schwellern, insbesondere bei älteren Modellen. Die Zuverlässigkeit ist im Allgemeinen gut, aber regelmäßige Wartung ist entscheidend. Die Motoren sind robust, aber die Kupplung kann bei Vielfahrern Verschleißerscheinungen zeigen. Die Elektronik ist meist unauffällig.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-ceed-jd','Kia','Ceed','JD',2012,2018,'["Schrägheck", "Kombi", "Coupé"]','Kompaktklasse','kia-ceed-ed','Der Kia Ceed JD zeichnet sich durch ein deutlich dynamischeres und sportlicheres Design im Vergleich zum Vorgänger ED aus. Auffällig sind die scharf gezeichneten, nach hinten gezogenen Scheinwerfer, die oft mit LED-Tagfahrlicht ausgestattet sind. Die Frontpartie wird von Kias ''Tigernase''-Kühlergrill dominiert, der breiter und flacher als beim Vorgänger ist. Die Seitenlinie ist fließender und die Heckleuchten sind horizontaler und breiter gestaltet, was dem Fahrzeug eine breitere und stabilere Optik verleiht.','Im Jahr 2015 erhielt der Kia Ceed JD ein Facelift. Die Änderungen umfassten eine leicht überarbeitete Frontschürze mit neuen Nebelscheinwerfer-Einfassungen und einem modifizierten Kühlergrill. Die Heckleuchten erhielten eine neue LED-Grafik. Im Innenraum wurden neue Materialien und Zierelemente verwendet, und das Infotainmentsystem wurde aktualisiert. Zudem wurden neue Motoren eingeführt, darunter ein 1.0 T-GDI Dreizylinder und ein überarbeiteter 1.6 CRDi Diesel.',NULL,NULL,NULL,5,2012,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-ev6-cv','Kia','EV6','CV',2021,NULL,'["Kombilimousine"]','Kompaktklasse',NULL,'Der Kia EV6 CV unterscheidet sich von seinen Vorgängern durch sein futuristisches Design mit einer durchgehenden Lichtleiste am Heck, einer coupéartigen Dachlinie und einer markanten Frontpartie mit schmalen Scheinwerfern. Die Karosserie ist als Crossover-Kombilimousine ausgelegt.',NULL,NULL,NULL,NULL,5,2022,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-niro-de','Kia','Niro','DE',2022,NULL,'["Kombi"]','Kompakt-SUV','Kia Niro (2016)','Die zweite Generation des Kia Niro (DE) unterscheidet sich deutlich vom Vorgänger. Auffällig sind die vertikalen Rückleuchten, die stark an den Polestar 2 erinnern, und die markante C-Säule mit optionaler Kontrastlackierung. Die Frontpartie zeigt einen breiteren Kühlergrill und schmalere Scheinwerfer.',NULL,NULL,NULL,NULL,5,2022,NULL,'24 Monate','Der Kia Niro DE ist in drei Antriebsvarianten erhältlich: als Vollhybrid (HEV), als Plug-in-Hybrid (PHEV) und als reines Elektroauto (EV). Die Wahl hängt stark vom individuellen Fahrprofil ab. Der HEV ist eine gute Wahl für Fahrer, die hauptsächlich Kurzstrecken fahren und gelegentlich längere Strecken zurücklegen. Der PHEV bietet eine größere elektrische Reichweite für Pendler, die zu Hause oder am Arbeitsplatz laden können. Der EV ist ideal für Fahrer, die eine rein elektrische Mobilität wünschen und Zugang zu Lademöglichkeiten haben.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-niro-sg2','Kia','Niro','SG2',2022,NULL,'["SUV"]','Kompakt-SUV','kia-niro-de','Der Kia Niro SG2 unterscheidet sich deutlich vom Vorgänger (DE) durch sein futuristisches und kantigeres Design. Auffällig sind die ''Herzschlag''-Tagfahrlichter, die in die obere Kante der Frontschürze integriert sind und eine markante, schmale Lichtsignatur bilden. Die C-Säule ist farblich abgesetzt und kann optional in einer Kontrastfarbe lackiert werden, was ein einzigartiges Designmerkmal darstellt. Die Heckleuchten sind vertikal angeordnet und reichen bis zur C-Säule, während die Heckscheibe eine stärkere Neigung aufweist. Im Innenraum dominieren zwei große, miteinander verbundene Displays für Instrumente und Infotainment.',NULL,NULL,NULL,NULL,4,2022,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-picanto-ba','Kia','Picanto','BA',2004,2011,'["Kleinwagen", "Schräghecklimousine"]','A',NULL,'Der Kia Picanto BA ist die erste Generation des Picanto. Er zeichnet sich durch ein rundliches Design mit großen, ovalen Scheinwerfern und einer eher kastenförmigen Karosserie aus. Die Heckleuchten sind vertikal angeordnet und reichen bis in die C-Säule. Im Vergleich zu späteren Generationen wirkt das Design deutlich einfacher und weniger dynamisch.','2007 erhielt der Picanto ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontschürze mit integrierten Nebelscheinwerfern, einem leicht modifizierten Kühlergrill und neuen Rückleuchten mit Klarglasoptik. Im Innenraum gab es Anpassungen am Armaturenbrett und der Mittelkonsole.',NULL,NULL,NULL,4,2004,NULL,'24 Monate','Der Kia Picanto BA ist ein günstiges Stadtauto, das vor allem durch seine Wendigkeit und niedrigen Unterhaltskosten punktet. Achten Sie beim Kauf auf Rost an Radläufen und Schwellern, defekte Lambdasonden und ausgeschlagene Spurstangenköpfe. Die Klimaanlage kann ebenfalls anfällig sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-picanto-ja','Kia','Picanto','JA',2017,NULL,'["Kleinwagen"]','A','kia-picanto-ba','Der Kia Picanto JA unterscheidet sich vom Vorgänger BA durch eine deutlich kantigere Front mit schmaleren Scheinwerfern und einer größeren, trapezförmigen Kühlermaske. Die Heckleuchten sind nun horizontal geteilt und reichen weiter in die Heckklappe hinein. Die Seitenlinie wirkt insgesamt dynamischer mit stärker ausgeprägten Sicken.','Das Facelift im Jahr 2020 brachte eine überarbeitete Front mit neu gestalteten Scheinwerfern und Tagfahrlichtern, eine modifizierte Kühlermaske und Stoßfänger. Am Heck wurden die Rückleuchten angepasst und die Stoßfänger neu gestaltet. Im Innenraum gab es ein neues Infotainmentsystem und überarbeitete Materialien.',NULL,NULL,NULL,3,2017,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-picanto-ta','Kia','Picanto','TA',2011,2017,'["3-Türer Schrägheck", "5-Türer Schrägheck"]','Kleinstwagen','kia-picanto-ba','Der Kia Picanto TA unterscheidet sich vom Vorgänger BA durch ein deutlich moderneres und dynamischeres Design. Auffällig sind die größeren, mandelförmigen Scheinwerfer, die sich weit in die Kotflügel ziehen, sowie der markante ''Tigernasen''-Kühlergrill. Die Seitenlinie ist von einer aufsteigenden Fensterlinie und einer markanten Sicke über den Türgriffen geprägt. Am Heck fallen die vertikalen Rückleuchten auf, die sich um die Ecke der Karosserie ziehen.','Im Jahr 2015 erhielt der Picanto TA ein Facelift. Die Änderungen umfassten eine leicht überarbeitete Frontschürze mit neuen Nebelscheinwerfern und einem modifizierten Kühlergrill. Am Heck gab es eine neue Grafik für die Rückleuchten, teilweise mit LED-Technik. Im Innenraum wurden neue Chromakzente und Stoffe eingeführt.',NULL,NULL,NULL,4,2011,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-rio-dc','Kia','Rio','DC',2000,2005,'["Limousine", "Kombi"]','Kleinwagen',NULL,'Die erste Generation des Kia Rio (DC) ist an ihrer eher rundlichen, aber schlichten Formgebung erkennbar. Die Front zeichnet sich durch große, leicht abgerundete Scheinwerfer aus, die in die Kotflügel übergehen, und einen schmalen Kühlergrill mit dem Kia-Logo in der Mitte. Die Limousine hat ein klassisches Stufenheck, während der Kombi (oft als Rio Wagon bezeichnet) ein deutlich verlängertes Dach und eine steilere Heckklappe aufweist. Im Vergleich zum Nachfolger (JB) wirkt der DC weniger dynamisch und kantig.','Im Jahr 2002 erhielt der Rio DC ein leichtes Facelift. Die auffälligsten Änderungen waren ein neu gestalteter Kühlergrill, der nun eine größere, ovale Öffnung aufwies, sowie leicht modifizierte Stoßfänger vorne und hinten. Die Scheinwerfer und Rückleuchten blieben weitgehend unverändert, aber es gab neue Radkappen und Felgendesigns. Im Innenraum wurden kleinere Anpassungen an Materialien und Farben vorgenommen.',NULL,NULL,NULL,NULL,NULL,15000,'alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-rio-jb','Kia','Rio','JB',2005,2011,'["Schräghecklimousine", "Stufenhecklimousine"]','Kleinwagen','kia-rio-dc','Der Kia Rio JB unterscheidet sich vom Vorgänger DC durch eine deutlich modernere und rundere Karosserieform. Die Scheinwerfer sind größer und integrieren sich stärker in die Frontpartie, die Kühlerniere ist schmaler und horizontaler. Die Heckleuchten sind beim Schrägheck vertikal angeordnet und reichen weit in die Seiten.','Im Jahr 2009 erhielt der Rio JB ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontpartie mit einer modifizierten Kühlermaske und neuen Scheinwerfern. Auch die Rückleuchten wurden leicht angepasst. Im Innenraum gab es Verbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,4,2005,NULL,'24 Monate','Der Kia Rio JB ist ein solider Kleinwagen, der besonders durch sein gutes Preis-Leistungs-Verhältnis und die für seine Klasse oft gute Ausstattung auffällt. Achten Sie beim Gebrauchtkauf auf Rost an Radläufen und Schwellern, sowie auf den Zustand der Bremsen und des Fahrwerks. Die Motoren sind in der Regel robust, aber regelmäßige Wartung ist wichtig.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-rio-ub','Kia','Rio','UB',2011,2017,'["Schrägheck", "Limousine"]','Kleinwagen','kia-rio-de','Die vierte Generation des Kia Rio (UB) zeichnet sich durch ein deutlich dynamischeres Design aus. Auffällig sind die schmalen, nach hinten gezogenen Scheinwerfer, die in die breitere ''Tigernase''-Kühlergrill-Interpretation übergehen. Die Seitenlinie ist fließender und sportlicher als beim Vorgänger, mit einer aufsteigenden Fensterlinie. Am Heck sind die Rückleuchten horizontal angelegt und reichen bis in die Seitenflanken, was dem Fahrzeug eine breitere Optik verleiht.','Im Jahr 2014 erhielt der Kia Rio UB ein leichtes Facelift. Die Änderungen umfassten eine überarbeitete Frontschürze mit neuen Nebelscheinwerfer-Einfassungen, einen leicht modifizierten Kühlergrill und neue Leichtmetallfelgen. Im Innenraum wurden neue Materialien und Farben sowie ein überarbeitetes Infotainmentsystem eingeführt.',NULL,NULL,NULL,5,2011,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-rio-yb','Kia','Rio','YB',2016,2023,'["Schrägheck"]','Kleinwagen','kia-rio-ub','Die vierte Generation (YB) des Kia Rio zeichnet sich durch eine sportlichere und gestrecktere Silhouette aus. Auffällig sind die schmaleren, nach hinten gezogenen Scheinwerfer mit U-förmigem LED-Tagfahrlicht (je nach Ausstattung), der breitere und flachere ''Tigernasen''-Kühlergrill sowie die horizontal ausgerichteten Rückleuchten, die das Fahrzeug breiter wirken lassen. Im Vergleich zum Vorgänger (UB) wirkt die Front aggressiver und die Seitenlinie dynamischer.','Im Jahr 2020 erhielt der Kia Rio YB ein Facelift. Die Änderungen umfassten eine leicht überarbeitete Frontschürze mit neuen Nebelscheinwerfergehäusen, einen modifizierten Kühlergrill mit Wabenmuster und neue Voll-LED-Scheinwerfer (optional). Im Innenraum wurde ein größeres 8-Zoll-Infotainment-Display eingeführt und das digitale Kombiinstrument ''Supervision Cluster'' mit 4,2-Zoll-Display war nun verfügbar. Zudem wurden neue Assistenzsysteme und Mild-Hybrid-Antriebe eingeführt.',NULL,NULL,NULL,5,2017,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sorento-jc','Kia','Sorento','JC',2002,2009,'["SUV"]','Oberklasse',NULL,'Der Kia Sorento JC unterscheidet sich von seinem Vorgänger durch eine deutlich rundere und modernere Karosserieform. Auffällig sind die größeren, integrierten Scheinwerfer, die sich weiter in die Kotflügel ziehen, sowie der breitere und markantere Kühlergrill. Die Heckleuchten sind ebenfalls neu gestaltet und horizontaler ausgerichtet.','2006 erhielt der Sorento JC ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill mit Chromspangen, neuen Front- und Heckstoßfängern sowie modifizierten Scheinwerfern und Rückleuchten. Im Innenraum gab es Verbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,4,2003,NULL,'24 Monate','Der Sorento JC ist ein robuster SUV, der sich gut für den Anhängerbetrieb und leichte Geländefahrten eignet. Achten Sie beim Kauf auf Rost an tragenden Teilen, insbesondere am Leiterrahmen und den Radläufen. Die Dieselmotoren können Probleme mit der Einspritzanlage und dem Turbolader aufweisen. Regelmäßige Wartung ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sorento-mq4','Kia','Sorento','MQ4',2020,NULL,'["SUV"]','D-Segment','kia-sorento-um','Der MQ4 unterscheidet sich deutlich vom Vorgänger UM. Auffällig sind die vertikal angeordneten Scheinwerfer, die markante, breitere und kantigere Frontpartie mit dem weiterentwickelten Tiger-Nose-Kühlergrill und die C-förmigen Rückleuchten, die über eine Leiste verbunden sind. Die Karosserie wirkt insgesamt muskulöser und moderner.',NULL,NULL,NULL,NULL,5,2020,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sorento-um','Kia','Sorento','UM',2014,2020,'["SUV"]','Mittelklasse-SUV','sorento-xm','Die UM-Generation zeichnet sich durch einen markanteren, breiteren ''Tigernasen''-Kühlergrill aus, der direkt in die schlankeren, nach hinten gezogenen Scheinwerfer übergeht. Die Karosserie wirkt muskulöser und weniger rundlich als beim Vorgänger XM. Die Front ist aufrechter, und die C-Säule weist oft ein ''Haifischflossen''-Design auf.','Das Facelift im Jahr 2017 (Modelljahr 2018) brachte überarbeitete Stoßfänger vorne und hinten, einen neu gestalteten ''Tigernasen''-Kühlergrill, neue LED-Scheinwerfer und Rückleuchten sowie neue Leichtmetallräder. Im Innenraum wurden das Lenkrad, das Infotainmentsystem und die Klimabedienung aktualisiert.',NULL,NULL,NULL,5,2014,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sorento-xm','Kia','Sorento','XM',2009,2015,'["SUV"]','Kompakt-SUV','kia-sorento-ex','Der Kia Sorento XM unterscheidet sich deutlich von seinem Vorgänger (EX). Er hat eine deutlich modernere und rundere Karosserieform, eine markantere Front mit größeren Scheinwerfern und einem breiteren Kühlergrill. Die Seitenlinie ist dynamischer gestaltet, und das Heck wirkt kompakter und aufgeräumter.','Im Jahr 2012 erhielt der Sorento XM ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontpartie mit neu gestalteten Scheinwerfern und Stoßfängern, sowie modifizierten Rückleuchten. Im Innenraum gab es Verbesserungen bei Materialien und Infotainmentsystem.',NULL,NULL,NULL,5,2010,NULL,'24 Monate','Der Kia Sorento XM ist ein geräumiges und robustes SUV, das sich gut für Familien eignet. Achten Sie beim Kauf auf Rost an Auspuffanlage und Achsteilen, sowie auf die Funktion des Allradantriebs. Regelmäßige Wartung ist wichtig, insbesondere bei Fahrzeugen mit höherer Laufleistung.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sportage-ja','Kia','Sportage','JA',1993,2004,'["SUV", "Geländewagen"]','Kompakt-SUV',NULL,'Der Kia Sportage JA ist an seiner kantigen, boxy Karosserieform erkennbar, die typisch für Geländewagen der 90er Jahre ist. Er besitzt runde oder leicht ovale Scheinwerfer (je nach Facelift) und eine auf der Heckklappe montierte Reserveradabdeckung. Im Vergleich zum Nachfolger (JE/KM) wirkt der JA deutlich weniger abgerundet und moderner, sondern eher robust und funktional.','Ein Facelift erfolgte 1998. Dabei wurden die Frontscheinwerfer leicht überarbeitet (größer und weniger rund), der Kühlergrill erhielt ein neues Design (oft in Wagenfarbe statt Chrom), und die Stoßfänger wurden modifiziert. Auch im Innenraum gab es kleinere Anpassungen an Materialien und Design.',NULL,NULL,NULL,NULL,NULL,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sportage-je','Kia','Sportage','JE',2004,2010,'["SUV"]','Kompakt-SUV','Kia Sportage (JA)','Die zweite Generation (JE) des Kia Sportage unterscheidet sich deutlich vom Vorgänger (JA). Sie ist größer, moderner gestaltet und hat eine selbsttragende Karosserie (Monocoque) statt eines Leiterrahmens. Die Front wird von größeren, trapezförmigen Scheinwerfern und einem breiteren Kühlergrill dominiert. Die Seitenlinie ist fließender und die Heckleuchten sind horizontal angeordnet und reichen weit in die Heckklappe hinein.','Im Jahr 2008 erhielt der Sportage ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill, neuen Scheinwerfern und Rückleuchten sowie geänderten Stoßfängern. Im Innenraum gab es Verbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,4,2005,NULL,'24 Monate','Der Kia Sportage JE war als robustes und preislich attraktives Kompakt-SUV konzipiert. Achten Sie beim Gebrauchtkauf auf Rost an Fahrwerksteilen und Radläufen, insbesondere bei Fahrzeugen, die viel im Winterbetrieb eingesetzt wurden. Die Motoren sind generell zuverlässig, aber regelmäßige Wartung ist wichtig. Die Dieselmotoren können Probleme mit dem Turbolader oder der Einspritzanlage aufweisen, besonders bei hoher Laufleistung.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sportage-nq5','Kia','Sportage','NQ5',2021,NULL,'["SUV"]','Kompakt-SUV','kia-sportage-ql','Der NQ5 unterscheidet sich deutlich vom Vorgänger QL. Auffällig sind die stark nach hinten gezogenen, bumerangförmigen Tagfahrlichter, die in die Hauptscheinwerfer integriert sind. Die Frontpartie wirkt kantiger und breiter, mit einem markanten Kühlergrill. Die Seitenlinie ist durch eine charakteristische Sicke geprägt, die sich von den vorderen Kotflügeln bis zu den Rückleuchten zieht. Das Heck ist ebenfalls neu gestaltet mit schmalen, horizontalen Rückleuchten, die durch ein schmales Band verbunden sind.',NULL,NULL,NULL,NULL,5,2022,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sportage-ql','Kia','Sportage','QL',2015,2021,'["SUV"]','Kompakt-SUV','kia-sportage-sl','Der Kia Sportage QL unterscheidet sich von seinem Vorgänger (SL) durch eine deutlich überarbeitete Frontpartie mit neu gestalteten Scheinwerfern, die sich weiter in die Kotflügel ziehen, und einer markanteren, nach unten gerückten Kühlermaske (''Tiger Nose''). Die Rückleuchten sind ebenfalls neu gezeichnet und oft durch eine Chromleiste verbunden. Die Karosserie wirkt insgesamt kantiger und moderner.','Das Facelift im Jahr 2018 brachte eine überarbeitete Front mit neuen LED-Tagfahrlichtern (oft vier ''Eiswürfel''-LEDs pro Seite), einem modifizierten Kühlergrill und Stoßfängern. Am Heck wurden die Rückleuchten leicht angepasst und die Auspuffendrohre neu gestaltet. Im Innenraum gab es Verbesserungen bei Materialien und Infotainmentsystem.',NULL,NULL,NULL,5,2015,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-sportage-sl','Kia','Sportage','SL',2010,2015,'["SUV"]','Kompakt-SUV','kia-sportage-je','Die dritte Generation des Kia Sportage (SL) zeichnet sich durch ein deutlich dynamischeres Design aus als ihr Vorgänger. Auffällig sind die schmalen, weit in die Kotflügel gezogenen Scheinwerfer, die eine optische Einheit mit dem markanten Tigernasen-Kühlergrill bilden. Die Seitenlinie ist coupéartiger mit einer ansteigenden Fensterlinie und einer abfallenden Dachlinie. Am Heck dominieren horizontal ausgerichtete Rückleuchten, die sich um die Fahrzeugecken ziehen und eine breitere Optik verleihen.','Im Jahr 2014 erhielt der Sportage SL ein leichtes Facelift. Die Änderungen waren subtil und umfassten einen überarbeiteten Kühlergrill mit neuen Lamellen, neue Nebelscheinwerfer und LED-Tagfahrlicht. Im Innenraum wurden hochwertigere Materialien verwendet, und es gab neue Ausstattungsoptionen wie ein beheizbares Lenkrad und ein überarbeitetes Infotainmentsystem.',NULL,NULL,NULL,5,2010,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('kia-stonic-yb','Kia','Stonic','YB',2017,NULL,'["SUV"]','Kleinwagen-SUV',NULL,'Der Kia Stonic (YB) ist ein kompakter Crossover mit einer markanten, sportlichen Optik. Er zeichnet sich durch die typische Kia-Tigernase aus, die hier jedoch breiter und flacher gestaltet ist als bei größeren Modellen. Die Scheinwerfer sind schmal und ziehen sich weit in die Kotflügel. Ein auffälliges Merkmal ist die oft zweifarbige Lackierung mit einem kontrastierenden Dach, das durch eine breite C-Säule optisch abgesetzt wird. Die Karosserie wirkt robust mit angedeuteten Unterfahrschutz-Elementen an Front und Heck.','Das Facelift im Jahr 2020 brachte leichte optische Retuschen, darunter neue LED-Scheinwerfer und -Rückleuchten sowie überarbeitete Stoßfänger. Im Innenraum wurden das Infotainmentsystem und die Konnektivitätsfunktionen aktualisiert. Technisch wurden neue Mild-Hybrid-Antriebe (48V) eingeführt und die Assistenzsysteme erweitert.',NULL,NULL,NULL,3,2017,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-amg-gt-c190','Mercedes-AMG','GT','C190',2014,2021,'["Coupé", "Roadster"]','Sportwagen','mercedes-benz-sls-amg-c197','Der Mercedes-AMG GT C190 zeichnet sich durch seine lange Motorhaube, das weit nach hinten versetzte Cockpit und das kurze, knackige Heck aus. Die Front ist geprägt von einem breiten Kühlergrill mit zentralem Stern und markanten, schmalen Scheinwerfern. Im Vergleich zum Vorgänger SLS AMG fehlen die Flügeltüren, und die Karosserie wirkt kompakter und aggressiver.','Ein erstes Facelift erfolgte 2017 (Modelljahr 2018), bei dem der Panamericana-Kühlergrill mit vertikalen Streben (zuvor nur beim GT R) für alle Varianten eingeführt wurde. Zudem wurden die Frontschürze leicht überarbeitet, neue Endrohrblenden eingeführt und das Interieur erhielt ein digitales Kombiinstrument sowie ein neues Lenkrad. Ein weiteres Update erfolgte 2018/2019 mit neuen Scheinwerfern und Rückleuchten, die eine markantere Lichtsignatur aufwiesen, sowie weiteren Interieur-Anpassungen.',NULL,NULL,NULL,NULL,NULL,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-a-klasse-w168','Mercedes-Benz','A-Klasse','W168',1997,2004,'["Schrägheck"]','Kompaktklasse',NULL,'Die erste Generation der A-Klasse zeichnet sich durch ihre ungewöhnlich hohe, kompakte Karosserie und das markante, leicht abfallende Frontdesign aus. Die Scheinwerfer sind rundlich und relativ groß, die Motorhaube kurz und steil. Im Vergleich zum Nachfolger (W169) wirkt der W168 insgesamt runder und weniger kantig, mit einer deutlich ausgeprägteren ''One-Box''-Silhouette. Das Sandwichboden-Konzept ist ein Alleinstellungsmerkmal.','Im Jahr 2001 (Mopf) erhielt der W168 ein Facelift. Die Frontschürze wurde neu gestaltet und integrierte nun die Nebelscheinwerfer, die zuvor separat angebracht waren. Die Scheinwerfer erhielten eine leicht überarbeitete Optik. Am Heck wurden die Stoßfänger und die Rückleuchten dezent modifiziert. Die Außenspiegel wurden mit integrierten Blinkern versehen. Im Innenraum gab es verbesserte Materialien und neue Lenkräder.',NULL,NULL,NULL,4,1999,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-a-klasse-w169','Mercedes-Benz','A-Klasse','W169',2004,2012,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kompaktklasse','mercedes-benz-a-klasse-w168','Die zweite Generation der A-Klasse (W169) unterscheidet sich vom Vorgänger (W168) durch ein deutlich runderes und dynamischeres Design. Die Scheinwerfer sind größer, mandelförmiger und reichen weiter in die Kotflügel. Die Kühlermaske ist breiter und der Mercedes-Stern prominenter. Die Karosserie wirkt insgesamt bulliger und die Gürtellinie ist höher. Zudem wurde erstmals eine dreitürige Variante (C169) angeboten.','Das Facelift im Jahr 2008 brachte dezente Änderungen mit sich. Dazu gehören neu gestaltete Stoßfänger vorne und hinten, ein leicht modifizierter Kühlergrill mit einer neuen Lamellenstruktur und überarbeitete Scheinwerfer und Rückleuchten, die nun eine klarere Optik aufweisen. Im Innenraum wurden neue Stoffe und Zierelemente verwendet.',NULL,NULL,NULL,5,2005,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-a-klasse-w176','Mercedes-Benz','A-Klasse','W176',2012,2018,'["Schrägheck"]','Kompaktklasse','mercedes-benz-a-klasse-w169','Die A-Klasse W176 markiert einen radikalen Bruch mit dem Van-artigen Vorgänger W169 und präsentiert sich als sportlicher Kompaktwagen. Sie ist deutlich flacher und breiter als der W169. Charakteristisch sind die scharf gezeichneten Scheinwerfer, die oft mit einer LED-Tagfahrlicht-Spange (als „Fackel“ oder „Augenbraue“) versehen sind und in die Kotflügel hineinragen. Der Kühlergrill ist breit und aufrecht, meist mit einem großen, zentralen Mercedes-Stern und zwei Lamellen. Die Seitenlinie ist dynamisch mit einer ansteigenden Fensterlinie. Im Vergleich zum Nachfolger W177 wirkt der W176 kantiger und weniger fließend, insbesondere die Scheinwerfer und Rückleuchten sind weniger schmal und langgezogen.','Im Juli 2015 erfolgte ein Facelift. Die Änderungen umfassten leicht modifizierte Stoßfänger vorne und hinten, eine neue Lichtsignatur der Scheinwerfer (optional LED High Performance Scheinwerfer) und Rückleuchten sowie eine überarbeitete Gestaltung des Kühlergrills. Im Innenraum gab es neue Zierteile, ein größeres freistehendes Display (optional 8 Zoll) und neue Farben für die Ambientebeleuchtung. Technisch wurden die Motoren optimiert und das Fahrwerk überarbeitet.',NULL,NULL,NULL,5,2012,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-a-klasse-w177','Mercedes-Benz','A-Klasse','W177',2018,NULL,'["Schrägheck", "Limousine"]','Kompaktklasse','mercedes-benz-a-klasse-w176','Die vierte Generation der A-Klasse (W177) zeichnet sich durch eine deutlich dynamischere und flachere Frontpartie aus, mit schmaleren, spitzer zulaufenden Scheinwerfern, die oft mit LED-Tagfahrlicht in einer L-Form versehen sind. Der Kühlergrill ist breiter und trapezförmig, meist mit einer einzelnen Lamelle und dem zentralen Mercedes-Stern. Am Heck sind die Rückleuchten zweigeteilt und erstrecken sich in die Heckklappe, was sie vom Vorgänger (W176) unterscheidet, dessen Rückleuchten komplett in den Kotflügeln saßen. Die Karosserie wirkt insgesamt gestreckter und eleganter.','Das Facelift im Jahr 2022 brachte dezente Änderungen mit sich: Die Scheinwerfer erhielten eine leicht überarbeitete Grafik mit zwei LED-Punkten als Tagfahrlicht. Der Kühlergrill wurde mit einem neuen Sternenmuster versehen und die Frontschürze leicht modifiziert. Am Heck wurden die Diffusor-Optik und die LED-Grafik der Rückleuchten angepasst. Im Innenraum wurde das Lenkrad neu gestaltet und das MBUX-Infotainmentsystem erhielt ein Update mit Fingerabdrucksensor.',NULL,NULL,NULL,5,2018,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-b-klasse-w245','Mercedes-Benz','B-Klasse','W245',2005,2011,'["Kompaktvan"]','Kompaktklasse',NULL,'Der W245 ist die erste Generation der B-Klasse. Er zeichnet sich durch seine hohe Sitzposition, das Van-ähnliche Karosseriedesign mit einer relativ steilen Front und einem Heck mit vertikal angeordneten Rückleuchten aus. Im Vergleich zu konventionellen Kompaktwagen bietet er ein deutlich größeres Raumgefühl und Variabilität.','Im Jahr 2008 erhielt die B-Klasse (W245) ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontschürze, neuen Scheinwerfern, geänderten Außenspiegeln und Heckleuchten. Im Innenraum wurden die Materialien aufgewertet und die Mittelkonsole überarbeitet.',NULL,NULL,NULL,5,2005,NULL,'24 Monate','Die B-Klasse W245 bietet viel Platz und Variabilität für ihre Klasse. Achten Sie beim Gebrauchtkauf auf Rost an den Radläufen und Schwellern, defekte Klimaanlagen und Probleme mit der Steuerkette bei älteren Benzinmotoren. Die Automatikgetriebe können ebenfalls anfällig sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-b-klasse-w246','Mercedes-Benz','B-Klasse','W246',2011,2018,'["Kompaktvan"]','Kompaktklasse','mercedes-benz-b-klasse-t245','Die zweite Generation der B-Klasse (W246) ist im Vergleich zum Vorgänger (T245) deutlich dynamischer gestaltet. Sie zeichnet sich durch eine flachere Dachlinie, eine markantere Front mit breiterem Kühlergrill und größeren, schräg nach hinten gezogenen Scheinwerfern aus. Die Seitenlinie wirkt gestreckter und weniger hochbauend als beim T245, und die Heckleuchten sind breiter und horizontaler ausgerichtet.','Im September 2014 erfolgte ein Facelift. Die Front wurde überarbeitet mit einem neuen Stoßfänger, einem modifizierten Kühlergrill und optionalen LED High Performance-Scheinwerfern. Am Heck wurden die Stoßfänger und die LED-Heckleuchten neu gestaltet. Im Innenraum gab es ein größeres, freistehendes Display (bis zu 8 Zoll) und neue Zierteile.',NULL,'6.8','Durchschnittlich',5,2011,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-b-klasse-w247','Mercedes-Benz','B-Klasse','W247',2019,NULL,'["Kompaktvan"]','Kompaktklasse','mercedes-benz-b-klasse-w246','Die dritte Generation der B-Klasse (W247) zeichnet sich durch ein deutlich dynamischeres Design aus als ihr Vorgänger. Auffällig sind die flacheren, optionalen LED-Scheinwerfer, die sich nahtlos in die Front integrieren, sowie die sportlichere Frontschürze mit größeren Lufteinlässen. Am Heck sind die zweiteiligen Heckleuchten charakteristisch, die sich bis in die Heckklappe ziehen. Im Innenraum ist das MBUX-Infotainmentsystem mit zwei freistehenden Displays und die Lüftungsdüsen in Turbinen-Optik ein klares Erkennungsmerkmal.','Im Jahr 2022 erhielt der W247 ein Facelift. Die Änderungen umfassen eine neu gestaltete Frontschürze, eine überarbeitete Kühlerverkleidung mit Sternenmuster (je nach Ausstattung), neue LED-Scheinwerfergrafiken und am Heck einen neuen Diffusor sowie neue LED-Rückleuchten. Im Innenraum wurde das Lenkrad aktualisiert und das MBUX-System um einen Fingerabdruck-Sensor erweitert. Die Auswahl an Ausstattungslinien wurde vereinfacht.',NULL,NULL,NULL,5,2019,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-c-klasse-w202','Mercedes-Benz','C-Klasse','W202',1993,2000,'["Limousine", "Kombi"]','Kompaktklasse','Mercedes-Benz 190 (W201)','Der W202 war die erste C-Klasse und löste den legendären ''Baby-Benz'' W201 ab. Er zeichnet sich durch eine deutlich rundere und modernere Formgebung aus als sein kantiger Vorgänger. Die Scheinwerfer sind größer und integrierter in die Karosserie, die Mercedes-typische Kühlermaske ist präsenter. Die Seitenlinie ist glatter und weniger stark gegliedert.','1997 erhielt der W202 ein Facelift. Äußerlich erkennbar an den nun in Wagenfarbe lackierten Stoßfängern und Zierleisten (statt schwarz), sowie an neuen Felgendesigns. Im Innenraum wurden die Materialien aufgewertet und die Ergonomie verbessert.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der W202 gilt als solider und langlebiger Mercedes, der jedoch wie jedes ältere Fahrzeug regelmäßige Wartung benötigt. Rost kann ein Thema sein, besonders an Radläufen und Schwellern. Bei den Benzinern sind die Reihensechszylinder (M104, M112) oft robuster als die Vierzylinder. Bei den Dieseln sind die Motoren der Baureihe OM60x und OM611 bekannt für ihre Langlebigkeit, aber auch anfällig für defekte Einspritzpumpen. Die Automatikgetriebe sind meist zuverlässig, sollten aber auf Ölverlust geprüft werden. Die Elektrik kann bei älteren Modellen anfällig sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-c-klasse-w203','Mercedes-Benz','C-Klasse','W203',2000,2007,'["Limousine", "T-Modell", "Sportcoupé"]','Mittelklasse','mercedes-benz-c-klasse-w202','Die W203-Generation zeichnet sich durch ihre deutlich rundlicheren und fließenderen Formen im Vergleich zum kantigen Vorgänger W202 aus. Prägnant sind die sogenannten ''Erdnuss''-Doppelscheinwerfer, bei denen pro Seite zwei ovale Leuchteinheiten unter einer gemeinsamen Abdeckung sitzen. Die Seitenlinie ist geschwungener, und das Heck wirkt weniger eckig. Das Sportcoupé (CL203) hat eine eigenständige Heckpartie mit einer großen Glasheckklappe.','Im Frühjahr 2004 erfolgte ein umfassendes Facelift. Äußerlich erkennbar an einer leicht modifizierten Frontschürze, einem neu gestalteten Kühlergrill mit drei Lamellen (zuvor vier) und Klarglas-Scheinwerfern mit dunklerem Hintergrund. Die Heckleuchten erhielten eine neue Optik. Im Innenraum wurden das Kombiinstrument, das Lenkrad und die Mittelkonsole überarbeitet, und es kamen hochwertigere Materialien zum Einsatz. Die Technik wurde ebenfalls aktualisiert, unter anderem mit einer direkteren Lenkung und überarbeiteten Fahrwerken.',NULL,NULL,NULL,5,2002,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-c-klasse-w204','Mercedes-Benz','C-Klasse','W204',2007,2014,'["Limousine", "Kombi", "Coupé"]','Kompaktklasse','mercedes-benz-c-klasse-w203','Der W204 unterscheidet sich deutlich vom Vorgänger W203. Markante Merkmale sind die schärfer gezeichneten Scheinwerfer, die nun bis in die vorderen Kotflügel reichen, die breitere und flachere Kühlermaske sowie die insgesamt kantigere und muskulösere Linienführung der Karosserie. Die charakteristische "Schulterlinie" des W203 ist beim W204 weniger ausgeprägt.','Das Facelift im Jahr 2011 brachte eine überarbeitete Frontschürze mit größeren Lufteinlässen, neue Scheinwerfer mit integriertem LED-Tagfahrlicht (optional), eine neu gestaltete Motorhaube und einen modifizierten Kühlergrill. Am Heck gab es angepasste Rückleuchten und eine neue Heckschürze. Im Innenraum wurden das Lenkrad, die Mittelkonsole und die Materialien aufgewertet.',NULL,NULL,NULL,5,2007,NULL,'24 Monate','Der W204 gilt als solider und zuverlässiger Mittelklassewagen. Achten Sie beim Kauf auf Rost an den Radläufen und Schwellern, insbesondere bei älteren Modellen. Die Automatikgetriebe können bei hoher Laufleistung anfällig sein. Die Motoren sind generell robust, aber die Dieselmotoren (insbesondere die OM651) können Probleme mit dem Turbolader oder den Injektoren haben. Regelmäßige Wartung ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-c-klasse-w205','Mercedes-Benz','C-Klasse','W205',2014,2021,'["Limousine", "Kombi", "Coupé", "Cabriolet"]','Mittelklasse','mercedes-benz-c-klasse-w204','Der W205 unterscheidet sich deutlich vom Vorgänger W204 durch eine flachere, coupéartigere Dachlinie bei der Limousine und dem Kombi, eine markantere Front mit größeren Scheinwerfern und einer breiteren, tiefer gezogenen Kühlermaske. Die Heckleuchten sind schmaler und horizontaler gestaltet. Im Innenraum dominiert ein freistehendes Infotainment-Display, das es beim W204 nicht gab.','Das Facelift (ab 2018) brachte eine überarbeitete Frontschürze, neue Scheinwerfer mit geänderten Tagfahrlichtsignaturen, modifizierte Rückleuchten und im Innenraum ein größeres, optional digitales Kombiinstrument sowie ein überarbeitetes Lenkrad mit Touch-Bedienfeldern.',NULL,NULL,NULL,5,2014,NULL,'24 Monate','Der W205 bietet eine breite Palette an Motorisierungen und Karosserievarianten. Achten Sie bei älteren Modellen auf die Wartungshistorie, insbesondere bei den Automatikgetrieben. Rost ist bei diesem Modell weniger ein Problem als bei früheren Mercedes-Generationen. Die Elektronik kann bei manchen Modellen anfällig sein, insbesondere das Infotainmentsystem.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-c-klasse-w206','Mercedes-Benz','C-Klasse','W206',2021,NULL,'["Limousine", "Kombi"]','Mittelklasse','mercedes-benz-c-klasse-w205','Der W206 unterscheidet sich deutlich vom Vorgänger W205. Auffällig sind die schmaleren Scheinwerfer mit integriertem Tagfahrlicht, die markantere und größere Kühlermaske sowie die aerodynamisch optimierte Karosserie mit stärker abfallender Dachlinie bei der Limousine. Die Rückleuchten sind horizontal geteilt und reichen weit in den Kofferraumdeckel hinein.',NULL,NULL,NULL,NULL,5,2022,NULL,'24 Monate','Der W206 ist die erste C-Klasse, die ausschließlich als Mild-Hybrid oder Plug-in-Hybrid angeboten wird. Die Motorenpalette ist breit gefächert, wobei die Plug-in-Hybride eine hohe elektrische Reichweite bieten. Achten Sie bei Gebrauchtfahrzeugen auf den Wartungszustand, insbesondere bei den Hybridkomponenten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cla-c117','Mercedes-Benz','CLA','C117',2013,2019,'["Coupé", "Shooting Brake"]','Kompaktklasse',NULL,'Der CLA C117 ist ein viertüriges Coupé auf Basis der A-Klasse (W176), erkennbar an seiner stark abfallenden Dachlinie, den rahmenlosen Seitenscheiben und der markanten, coupéartigen Heckpartie mit schmalen Rückleuchten. Die Front ähnelt der A-Klasse W176, unterscheidet sich aber durch eine eigenständige Gestaltung der Stoßfänger und des Kühlergrills, oft mit Diamantgrill-Optik.','Das Facelift (Mopf) im Jahr 2016 brachte dezente Änderungen mit sich: Modifizierte Stoßfänger vorne und hinten, ein serienmäßiger Diamantgrill, neue LED High Performance-Scheinwerfer (optional) mit markanterer Lichtsignatur und überarbeitete Rückleuchten mit LED-Technik. Im Innenraum wurden neue Sitzbezüge, Zierteile und ein größeres, freistehendes 8-Zoll-Display eingeführt.',NULL,NULL,NULL,5,2013,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cla-c118','Mercedes-Benz','CLA','C118',2019,NULL,'["Coupé", "Shooting Brake"]','Kompaktklasse','mercedes-benz-cla-c117','Der CLA C118 zeichnet sich durch eine flachere, sportlichere Silhouette aus als sein Vorgänger C117. Die Scheinwerfer sind schmaler und aggressiver gezeichnet, oft mit einer markanten LED-Tagfahrlichtsignatur. Die Frontschürze ist dynamischer gestaltet, und die Heckleuchten sind zweiteilig, schmaler und horizontaler ausgerichtet, was das Fahrzeug breiter wirken lässt. Die Seitenlinie ist stärker coupéartig abfallend.','Im Januar 2023 wurde ein Facelift vorgestellt. Dieses umfasst eine überarbeitete Frontschürze, einen neuen Kühlergrill mit Sternenmuster, leicht modifizierte LED-Scheinwerfer und Heckleuchten. Im Innenraum wurden neue Polsteroptionen und das aktualisierte MBUX-Infotainmentsystem mit zwei 10,25-Zoll-Displays (serienmäßig) eingeführt. Zudem wurden die Mild-Hybrid-Antriebe überarbeitet.',NULL,NULL,NULL,5,2019,25000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cla-shooting-brake-x117','Mercedes-Benz','CLA Shooting Brake','X117',2015,2019,'["Kombi"]','Kompaktklasse',NULL,'Der CLA Shooting Brake X117 ist die erste Generation des Modells. Er basiert auf der A-Klasse W176 und dem CLA Coupé C117. Charakteristisch sind die rahmenlosen Türen, die coupéhafte Dachlinie, die nach hinten abfallende Fensterlinie und das sportlich-elegante Heck mit der großen Heckklappe. Die Front ähnelt dem CLA Coupé C117 mit markanten Scheinwerfern und der Diamantgrill-Option.','Im Jahr 2016 erhielt der CLA Shooting Brake X117 ein Facelift. Die Änderungen umfassten eine modifizierte Frontschürze, einen neu gestalteten Kühlergrill, optional LED High Performance-Scheinwerfer mit neuem Innenleben und eine überarbeitete Heckschürze mit integrierten Endrohrblenden. Im Innenraum wurden neue Sitzbezüge, Zierteile und ein größeres, freistehendes 8-Zoll-Display eingeführt.',NULL,NULL,NULL,5,2013,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cla-shooting-brake-x118','Mercedes-Benz','CLA Shooting Brake','X118',2019,NULL,'["Kombi"]','Kompaktklasse','CLA Shooting Brake X117','Der X118 unterscheidet sich vom Vorgänger X117 durch eine flachere Dachlinie, eine breitere Spur und eine insgesamt sportlichere Anmutung. Die Scheinwerfer sind schmaler und aggressiver gezeichnet, die Heckleuchten sind horizontaler und ziehen sich weiter in die Heckklappe. Die C-Säule ist schlanker und die Fensterlinie steigt im hinteren Bereich stärker an.','Das Facelift (voraussichtlich 2023/2024) brachte überarbeitete Stoßfänger, neue Felgendesigns und möglicherweise Anpassungen an der Lichtsignatur. Im Innenraum wurden das Infotainmentsystem MBUX aktualisiert und neue Materialien eingeführt.',NULL,NULL,NULL,5,2019,NULL,'24 Monate','Der CLA Shooting Brake X118 bietet eine sportliche Alternative zu traditionellen Kombis. Achten Sie auf die Motorisierung, da die Einstiegsmodelle etwas untermotorisiert wirken können. Die Verarbeitung ist auf hohem Niveau, aber die Aufpreisliste ist lang. Beliebte Ausstattungsoptionen sind das MBUX-Infotainmentsystem, Assistenzsysteme und das AMG Line-Paket.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cls-c218','Mercedes-Benz','CLS','C218',2011,2018,'["Coupé", "Shooting Brake"]','Oberklasse','mercedes-benz-cls-c219','Der C218 unterscheidet sich vom Vorgänger C219 durch eine deutlich flachere und dynamischere Dachlinie, eine markantere Front mit größeren Scheinwerfern und einer breiteren Kühlermaske sowie ein insgesamt moderneres und aggressiveres Design. Die Heckleuchten sind schmaler und ziehen sich weiter in die Seite.','Das Facelift im Jahr 2014 brachte eine überarbeitete Front mit neuem Kühlergrill, adaptiven LED-Scheinwerfern (optional), einem modifizierten Stoßfänger und neuen Leichtmetallrädern. Im Innenraum wurde das Infotainmentsystem aktualisiert und das Lenkrad überarbeitet.',NULL,NULL,NULL,5,2011,NULL,'24 Monate','Der C218 ist bekannt für seinen Komfort und seine sportliche Eleganz. Achten Sie bei Gebrauchtwagen auf die Wartungshistorie, insbesondere bei den Dieselmotoren und den Automatikgetrieben. Rost kann an den Radläufen und Schwellern ein Thema sein, besonders bei älteren Modellen. Die Elektronik kann anfällig sein, prüfen Sie alle Funktionen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cls-c219','Mercedes-Benz','CLS','C219',2004,2010,'["4-türiges Coupé"]','Obere Mittelklasse',NULL,'Die erste Generation des Mercedes-Benz CLS (C219) zeichnet sich durch ihre einzigartige, fließende Dachlinie aus, die einem Coupé ähnelt, aber vier Türen besitzt. Typisch sind die markanten, tropfenförmigen Scheinwerfer, die sich weit in die Kotflügel ziehen, sowie die breite, lamellenartige Kühlergrillgestaltung. Die Heckpartie ist ebenfalls sehr eigenständig mit breiten, horizontal ausgerichteten Rückleuchten, die in die Seitenflanken übergehen und eine sanft abfallende Kofferraumlinie bilden. Im Vergleich zu anderen Mercedes-Modellen der Zeit (z.B. E-Klasse W211) wirkt der CLS deutlich dynamischer und eleganter, mit einer stärker ausgeprägten Seitenlinie und einem sportlicheren Auftritt.','Ein Facelift erfolgte im Jahr 2008. Die Änderungen umfassten einen neu gestalteten Kühlergrill mit zwei Lamellen statt vier, neue Außenspiegel mit integrierten LED-Blinkleuchten in Pfeilform, leicht modifizierte Frontschürzen und Heckschürzen sowie neue LED-Rückleuchten mit einem markanteren Design. Im Innenraum gab es ein neues Dreispeichenlenkrad und überarbeitete Kombiinstrumente.',NULL,NULL,NULL,NULL,NULL,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-cls-c257','Mercedes-Benz','CLS','C257',2018,NULL,'["Coupé-Limousine"]','Oberklasse','mercedes-benz-cls-x218','Der C257 unterscheidet sich vom Vorgänger X218 durch eine deutlich flachere und breitere Front mit schmaleren Scheinwerfern, einer markanteren Kühlermaske und einer dynamischeren Linienführung. Die Heckleuchten sind nun horizontal geteilt und integrieren sich stärker in die Kofferraumklappe.','Das Facelift (oft als Modelljahr 2022 bezeichnet) brachte dezente Änderungen an Front- und Heckschürze, neue Felgendesigns und eine überarbeitete Innenraumgestaltung mit einem größeren Infotainment-Display und neuen Lenkradgenerationen. Die Motorenpalette wurde ebenfalls aktualisiert, insbesondere im Hinblick auf Mild-Hybrid-Technologie.',NULL,NULL,NULL,5,2017,NULL,'24 Monate','Der C257 bietet ein luxuriöses Interieur und hohen Fahrkomfort. Achten Sie bei Gebrauchtwagen auf die Wartungshistorie, insbesondere bei den komplexen Motoren und Getrieben. Die Luftfederung (optional) kann ein Schwachpunkt sein. Die frühen Modelle hatten teilweise Probleme mit der Software des Infotainmentsystems.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-e-klasse-w210','Mercedes-Benz','E-Klasse','W210',1995,2002,'["Limousine", "Kombi"]','Obere Mittelklasse','mercedes-benz-e-klasse-w124','Der W210 unterscheidet sich deutlich vom kantigen W124. Charakteristisch sind die vier runden Scheinwerfer, die in die vorderen Kotflügel integriert sind, sowie die abgerundeten Linien der Karosserie. Die Heckleuchten sind breiter und flacher gestaltet.','Das Facelift im Jahr 2000 brachte überarbeitete Scheinwerfer mit Klarglasoptik, modifizierte Stoßfänger, neue Außenspiegel mit integrierten Blinkern und eine überarbeitete Innenausstattung mit neuem Lenkrad und verbesserter Materialanmutung.',NULL,NULL,NULL,NULL,NULL,NULL,'24 Monate','Der W210 gilt als solider Wagen, jedoch sind Rostprobleme, insbesondere an Radläufen, Schwellern und Türkanten, häufig. Bei den Benzinmotoren sind die Reihensechszylinder (M104, M112) und V8 (M119, M113) zu bevorzugen. Bei den Dieseln sind die Reihenvier- und Sechszylinder (OM604, OM605, OM606) robust, aber anfällig für Probleme mit der Einspritzpumpe. Die Automatikgetriebe sind generell haltbar. Auf Rost und die Wartungshistorie achten.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-e-klasse-w211','Mercedes-Benz','E-Klasse','W211',2002,2009,'["Limousine", "Kombi"]','Obere Mittelklasse','mercedes-benz-e-klasse-w210','Der W211 unterscheidet sich vom Vorgänger W210 durch eine deutlich rundere und geschwungenere Linienführung. Charakteristisch sind die vier einzelnen, ovalen Scheinwerfer, die nun ineinander übergehen, sowie die stärker konturierte Motorhaube und die neu gestaltete Frontschürze. Die Seitenlinie wirkt dynamischer mit einer stärker ansteigenden Schulterlinie.','Das Facelift im Jahr 2006 brachte eine überarbeitete Front mit neuen Scheinwerfern (Bi-Xenon serienmäßig), einem modifizierten Kühlergrill und Stoßfängern. Am Heck wurden die Rückleuchten angepasst. Im Innenraum gab es Änderungen am Lenkrad, der Mittelkonsole und der Materialanmutung. Die Motorenpalette wurde ebenfalls überarbeitet.',NULL,NULL,NULL,5,2004,NULL,'24 Monate','Der W211 bietet viel Komfort und eine hohe Verarbeitungsqualität. Achten Sie auf Rost an Radläufen und Türen, insbesondere bei Fahrzeugen vor dem Facelift. Die Elektronik kann anfällig sein, insbesondere das SBC-Bremssystem (bei Modellen vor dem Facelift). Regelmäßige Wartung ist entscheidend. Die Kombi-Version (T-Modell) ist praktisch, aber die Luftfederung kann teuer im Unterhalt sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-e-klasse-w212','Mercedes-Benz','E-Klasse','W212',2009,2016,'["Limousine", "Kombi"]','Obere Mittelklasse','mercedes-benz-e-klasse-w211','Die W212-Generation zeichnet sich durch ihre markanten, geteilten Doppelscheinwerfer aus, die eine rautenförmige oder leicht rechteckige Form haben. Die Karosserie ist kantiger und muskulöser als beim Vorgänger W211, mit einer ausgeprägten Sicke über den hinteren Radläufen, die an den Ponton-Mercedes erinnert. Die Heckleuchten sind breiter und zweigeteilt, reichen bis in die Kofferraumklappe.','Das Facelift (Mopf) im Jahr 2013 brachte eine umfassende optische Überarbeitung. Die zuvor geteilten Doppelscheinwerfer wurden zu einem einzigen, durchgehenden Scheinwerfergehäuse zusammengefasst, das jedoch weiterhin die vier Lichtelemente durch LED-Tagfahrlicht-Spangen andeutet. Die Frontschürze und der Kühlergrill wurden neu gestaltet, wobei der Kühlergrill je nach Ausstattungslinie (klassisch mit Stern auf der Haube oder sportlich mit großem Stern im Grill) variierte. Am Heck wurden die Rückleuchten und die Heckschürze modifiziert, um einen moderneren und breiteren Eindruck zu vermitteln.',NULL,NULL,NULL,5,2009,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-e-klasse-w213','Mercedes-Benz','E-Klasse','W213',2016,2023,'["Limousine", "T-Modell", "Coupé", "Cabriolet"]','Obere Mittelklasse','mercedes-benz-e-klasse-w212','Die W213-Generation zeichnet sich durch eine fließende, elegante Linienführung aus, die sich deutlich vom kantigeren Vorgänger W212 abhebt. Charakteristisch sind die schmalen, horizontal ausgerichteten LED-Scheinwerfer (oft mit zwei LED-Streifen als Tagfahrlicht) und die breitere, tiefer positionierte Kühlergrill-Variante. Im Innenraum dominieren zwei große, nebeneinander angeordnete Displays (optional) und hochwertige Materialien. Die Heckleuchten sind horizontal und schmal, oft mit einem ''Stardust''-Effekt.','Das Facelift (Mopf) im Jahr 2020 brachte eine umfassende Überarbeitung mit sich. Die Front wurde mit neuen, flacheren LED-Scheinwerfern (ein LED-Streifen als Tagfahrlicht) und einem neu gestalteten Kühlergrill modernisiert. Die Heckleuchten erhielten ebenfalls ein neues Design, das nun breiter und horizontaler wirkt. Im Innenraum wurde das MBUX-Infotainmentsystem eingeführt, und das Lenkraddesign wurde überarbeitet.',NULL,NULL,NULL,5,2016,25000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-e-klasse-w214','Mercedes-Benz','E-Klasse','W214',2023,NULL,'["Limousine", "Kombi"]','Obere Mittelklasse','mercedes-benz-e-klasse-w213','Die W214-Generation zeichnet sich durch eine neue Frontpartie aus, bei der die Scheinwerfer mit der Kühlerverkleidung optisch verbunden sind und eine geschwungene Form aufweisen. Die Rückleuchten sind neu gestaltet und zeigen ein markantes Stern-Design (Mercedes-Stern-Muster) im Inneren. Im Vergleich zum Vorgänger W213 wirkt die Karosserie fließender und aerodynamischer. Im Innenraum dominiert das optionale MBUX Superscreen, das drei Displays unter einer durchgehenden Glasfläche vereint.',NULL,NULL,NULL,NULL,5,2023,25000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-eqa-h243','Mercedes-Benz','EQA','H243',2021,NULL,'["SUV"]','Kompakt-SUV',NULL,'Der EQA H243 ist als rein elektrisches Kompakt-SUV an seiner geschlossenen ''Black Panel''-Front mit integriertem Mercedes-Stern und einer durchgehenden Lichtleiste, die die Scheinwerfer verbindet, erkennbar. Auch am Heck zieht sich eine durchgehende Lichtleiste über die gesamte Breite des Fahrzeugs. Die Karosserie basiert auf dem GLA (H247), unterscheidet sich aber durch die spezifischen Elektro-Designelemente.','Im Jahr 2023 erhielt der EQA ein Facelift. Die auffälligsten Änderungen umfassen ein neues Frontdesign mit einem Sternenmuster in der ''Black Panel''-Front, neu gestaltete Heckleuchten und ein überarbeitetes Lenkrad im Innenraum. Zudem wurde die Reichweite einiger Modelle durch Optimierungen am Antriebsstrang und der Batterie erhöht.',NULL,NULL,NULL,5,2021,NULL,'2 Jahre (Erstuntersuchung nach 3 Jahren)',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-eqb-x243','Mercedes-Benz','EQB','X243',2021,NULL,'["SUV"]','Kompaktklasse',NULL,'Der EQB X243 ist äußerlich eng mit dem GLB X247 verwandt, unterscheidet sich aber durch die markentypische Black-Panel-Front mit durchgehendem Leuchtenband und integriertem Stern. Die Heckleuchten sind ebenfalls durch ein Leuchtenband verbunden. Die Karosserieform ist kastenförmig und bietet optional eine dritte Sitzreihe.','Im September 2023 wurde ein Facelift vorgestellt. Die Front erhielt ein neues Black-Panel-Design mit Sternenmuster und eine überarbeitete Stoßstange. Die Heckleuchten wurden leicht modifiziert und das Interieur erhielt ein neues Lenkrad sowie aktualisierte MBUX-Software.',NULL,NULL,NULL,5,2021,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-eqe-v295','Mercedes-Benz','EQE','V295',2022,NULL,'["Limousine"]','Obere Mittelklasse',NULL,'Der Mercedes-Benz EQE (V295) ist eine rein elektrische Limousine, die sich durch eine fließende, coupéartige Silhouette mit einer ''One-Bow''-Linie auszeichnet. Charakteristisch sind die bündig integrierten Türgriffe, das durchgehende Leuchtenband am Heck und die Black-Panel-Front, die den Kühlergrill ersetzt und die Scheinwerfer optisch verbindet. Die Scheinwerfer sind schmal und ziehen sich weit in die Kotflügel. Im Vergleich zu seinem Verbrenner-Pendant, der E-Klasse, wirkt der EQE futuristischer und aerodynamischer, mit einer glatteren Karosserie ohne ausgeprägte Sicken.',NULL,NULL,NULL,NULL,5,2022,NULL,'3 Jahre, danach alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-eqs-v297','Mercedes-Benz','EQS','V297',2021,NULL,'["Limousine"]','Oberklasse',NULL,'Der Mercedes-Benz EQS (V297) ist die erste rein elektrische Luxuslimousine von Mercedes-Benz. Er zeichnet sich durch eine sehr fließende, coupéartige Silhouette mit einer ''One-Bow''-Linie aus. Die Front ist geprägt von einem großen, geschlossenen Black-Panel-Kühlergrill, der die Scheinwerfer optisch verbindet, und schmalen, digitalen LED-Scheinwerfern. Die Heckleuchten sind durch ein durchgehendes Leuchtenband miteinander verbunden. Im Innenraum dominiert das optionale MBUX Hyperscreen, das sich über die gesamte Breite des Armaturenbretts erstreckt.','Ein Facelift wurde im April 2024 vorgestellt. Wesentliche optische Änderungen umfassen einen neuen Kühlergrill mit verchromten Lamellen und einem aufrechten Mercedes-Stern auf der Motorhaube, der an klassische S-Klasse-Modelle erinnert. Die AMG Line erhält weiterhin den Black-Panel-Grill. Im Innenraum gibt es neue Zierelemente und Komfortverbesserungen, wie z.B. eine verbesserte Geräuschdämmung und eine optimierte Rekuperation.',NULL,NULL,NULL,5,2021,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-g-klasse-w-460','Mercedes-Benz','G-Klasse','W 460',1979,1992,'["Geländewagen", "Cabriolet", "Kastenwagen"]','Geländewagen',NULL,'Die W 460 Generation ist erkennbar an ihrer kantigen, funktionalen Karosserie ohne die breiteren Kotflügel oder die luxuriöseren Anbauteile späterer Generationen. Sie besitzt runde Hauptscheinwerfer, eine schmale, vertikale Kühlergrillmaske und oft außenliegende Türscharniere. Die Blinker sind typischerweise klein und seitlich an den vorderen Kotflügeln angebracht. Im Vergleich zum Nachfolger W 463 fehlen ihr die integrierten Stoßfänger und die breiteren Radläufe.','Es gab keine klassischen Facelifts im Sinne großer optischer Überarbeitungen. Über die Bauzeit hinweg gab es kleinere technische Anpassungen und Detailverbesserungen, wie z.B. die Einführung neuer Motoren oder geringfügige Änderungen im Innenraum (z.B. Armaturenbrett-Layout, Sitze).',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-g-klasse-w-461','Mercedes-Benz','G-Klasse','W 461',1992,NULL,'["Geländewagen 3-Türer", "Geländewagen 5-Türer", "Kastenwagen", "Pick-up"]','Geländewagen','mercedes-benz-g-klasse-w-460','Der W 461 ist primär als Nutzfahrzeug- und Militärvariante der G-Klasse konzipiert. Optisch ähnelt er stark dem W 460, unterscheidet sich aber durch eine robustere, weniger luxuriöse Ausstattung und oft durch spezifische Anbauteile für den professionellen Einsatz. Im Vergleich zum W 463 fehlen ihm die breiteren Kotflügel, die moderneren Scheinwerfer und die luxuriösere Innenausstattung. Die Front ist meist schlichter gehalten, oft mit einfachen Halogen-Scheinwerfern und einem funktionalen Kühlergrill.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-g-klasse-w-463','Mercedes-Benz','G-Klasse','W 463',1990,2018,'["SUV", "Geländewagen", "Cabrio"]','Luxus-Geländewagen','mercedes-benz-g-klasse-w-460','Die erste Generation des W 463 unterscheidet sich vom Vorgänger W 460 durch eine deutlich luxuriösere Innenausstattung mit Holz- und Lederelementen, permanenten Allradantrieb statt zuschaltbarem, sowie serienmäßigen ABS und drei Differentialsperren. Äußerlich sind die integrierten Blinker in den Kotflügeln (nicht mehr aufgesetzt) und die moderneren Scheinwerferrahmen Merkmale. Die Türgriffe sind ebenfalls moderner und bündiger in die Türen integriert.','Die G-Klasse W 463 erfuhr im Laufe ihrer langen Bauzeit zahlreiche kleinere und größere Facelifts. Wichtige Änderungen umfassen: 1997 Einführung des G 500 mit V8-Motor und neuen Scheinwerfern mit Klarglasoptik. 2001 Einführung des G 400 CDI und des G 270 CDI, sowie ein überarbeitetes Interieur mit neuem Kombiinstrument und Multifunktionslenkrad. 2006 ein weiteres Interieur-Update mit neuem COMAND-System. 2007 Einführung des G 55 AMG Kompressor. 2008 leichte optische Retuschen an Front und Heck, neue Außenspiegel. 2012 ein umfassendes Facelift mit neuem Kühlergrill, LED-Tagfahrlicht unter den Hauptscheinwerfern, neu gestalteter Stoßfänger und einem komplett überarbeiteten Interieur mit großem Zentraldisplay und modernerer Mittelkonsole.',NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-g-klasse-w-463-(ab-2018)','Mercedes-Benz','G-Klasse','W 463 (ab 2018)',2018,NULL,'["SUV"]','Luxus-Geländewagen','mercedes-benz-g-klasse-w-463-(1990-2018)','Die zweite Generation des W 463 behält die ikonische, kantige Form bei, ist aber in allen Dimensionen gewachsen (breiter, länger). Auffällig sind die runden LED-Scheinwerfer (oft Multibeam LED), die modernisierte Frontschürze und der Kühlergrill. Die Türgriffe sind weiterhin charakteristisch, aber die Karosserie wirkt insgesamt etwas glatter und integrierter. Im Innenraum dominieren zwei große, nebeneinanderliegende Displays für Instrumente und Infotainment, was einen deutlichen Unterschied zum Vorgänger darstellt.',NULL,NULL,NULL,NULL,NULL,NULL,25000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gl-klasse-x164','Mercedes-Benz','GL-Klasse','X164',2006,2012,'["SUV"]','Oberklasse-SUV',NULL,'Die GL-Klasse X164 ist ein großes, siebensitziges SUV mit einer imposanten Erscheinung. Sie zeichnet sich durch eine relativ flache Dachlinie, eine breite Front mit einem großen Kühlergrill und dem Mercedes-Stern in der Mitte sowie rechteckige, leicht abgerundete Scheinwerfer aus. Im Vergleich zum Nachfolger X166 wirkt die X164-Generation insgesamt runder und weniger kantig, insbesondere an den Scheinwerfern und Rückleuchten, die beim X166 schmaler und stärker in die Karosserie integriert sind.','Das Facelift im Jahr 2009 brachte dezente Änderungen mit sich. Dazu gehörten neu gestaltete Stoßfänger vorne und hinten, ein überarbeiteter Kühlergrill mit horizontalen Chromlamellen, LED-Tagfahrlicht in den vorderen Stoßfängern und neue Rückleuchten mit LED-Technik. Auch die Endrohre der Abgasanlage wurden modifiziert und die Leichtmetallräder erhielten neue Designs.',NULL,NULL,NULL,NULL,NULL,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gla-h247','Mercedes-Benz','GLA','H247',2020,NULL,'["SUV"]','Kompakt-SUV','mercedes-benz-gla-x156','Der H247 ist im Vergleich zum Vorgänger X156 deutlich höher und kürzer, was ihm eine SUV-typischere Silhouette verleiht. Er verfügt über eine modernere Front mit flacheren LED-Scheinwerfern und einer markanteren Kühlergrillgestaltung. Im Innenraum ist das MBUX-Infotainmentsystem mit zwei nebeneinanderliegenden Bildschirmen (Widescreen-Cockpit) ein klares Erkennungsmerkmal.','Im Jahr 2023 erfolgte ein Facelift. Dieses umfasste eine überarbeitete Frontschürze, neue LED-Lichtsignaturen an Front und Heck, einen modifizierten Kühlergrill mit vertikalen Lamellen und eine neue Auswahl an Lackfarben und Felgendesigns. Im Innenraum wurde das MBUX-System aktualisiert, unter anderem mit drahtloser Apple CarPlay- und Android Auto-Integration.',NULL,NULL,NULL,5,2020,25000,'Alle 2 Jahre nach Erstzulassung',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gla-x156','Mercedes-Benz','GLA','X156',2013,2019,'["SUV"]','Kompakt-SUV',NULL,'Der GLA X156 basiert auf der Kompaktwagenplattform von Mercedes-Benz (A-Klasse W176). Er zeichnet sich durch eine coupéartige Dachlinie, erhöhte Bodenfreiheit und eine sportliche, aber kompakte SUV-Optik aus. Die Front ist geprägt von einem großen Kühlergrill mit zentralem Stern und markanten, leicht nach hinten gezogenen Scheinwerfern. Im Vergleich zu größeren SUVs von Mercedes-Benz wirkt er agiler und weniger wuchtig.','Im Januar 2017 erhielt der GLA X156 ein Facelift. Die Änderungen umfassten neu gestaltete Stoßfänger vorne und hinten, serienmäßige LED High Performance-Scheinwerfer (ersetzen Bi-Xenon), überarbeitete Rückleuchten mit Multilevel-Funktion, neue Leichtmetallräder und eine neue Lackfarbe (Canyonbeige). Im Innenraum gab es neue Sitzbezüge, Zierteile und ein aufgewertetes Infotainmentsystem mit 8-Zoll-Display.',NULL,NULL,NULL,5,2013,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-glb-x247','Mercedes-Benz','GLB','X247',2019,NULL,'["SUV"]','Kompakt-SUV',NULL,'Der GLB X247 zeichnet sich durch seine kantige, robuste SUV-Form aus, die ihn vom runderen GLA abgrenzt. Er besitzt eine aufrechte Front mit einem markanten Kühlergrill, der meist zwei horizontale Lamellen und einen großen Mercedes-Stern trägt. Die Scheinwerfer sind im Vergleich zu anderen Mercedes-SUVs der Zeit eher flach und rechteckig. Ein weiteres Erkennungsmerkmal ist die optional erhältliche dritte Sitzreihe, die ihn in seinem Segment besonders macht.','Das Facelift im Jahr 2023 brachte eine überarbeitete Frontschürze mit neuen Lufteinlässen und ein aktualisiertes Kühlergrilldesign, das je nach Ausstattungslinie variiert (z.B. mit vertikalen Lamellen oder einem Sternenmuster). Die LED-Lichtsignatur der Scheinwerfer und Rückleuchten wurde modernisiert. Im Innenraum gab es ein neues Lenkrad und die neueste Generation des MBUX-Infotainmentsystems. Technisch wurden die Benzinmotoren um Mild-Hybrid-Technologie erweitert.',NULL,NULL,NULL,5,2019,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-glc-x253','Mercedes-Benz','GLC','X253',2015,2022,'["SUV", "SUV Coupé"]','Mittelklasse-SUV','mercedes-benz-glk-x204','Der GLC X253 zeichnet sich durch eine deutlich rundlichere und fließendere Formgebung im Vergleich zum kantigen Vorgänger GLK aus. Die Front ist geprägt von einer großen, aufrechten Kühlergrill-Einheit mit zentralem Mercedes-Stern und langgezogenen, leicht nach hinten geschwungenen Scheinwerfern. Die Seitenlinie ist coupéhafter, besonders beim GLC Coupé (C253), das eine stark abfallende Dachlinie zum Heck aufweist. Die Heckleuchten sind horizontal ausgerichtet und zweigeteilt, wobei ein Teil in der Heckklappe sitzt.','Das Facelift (Mopf) im Jahr 2019 brachte überarbeitete LED-Scheinwerfer mit neuer Lichtsignatur (Tagfahrlicht in L-Form), einen modifizierten Kühlergrill mit doppelten Lamellen und Chrom-Elementen sowie neu gestaltete Stoßfänger vorne und hinten. Am Heck wurden die LED-Rückleuchten ebenfalls leicht modifiziert und erhielten eine neue Innenstruktur. Im Innenraum wurde das Infotainmentsystem MBUX mit Touchscreen und Sprachsteuerung eingeführt, das Lenkrad neu gestaltet und ein digitales Kombiinstrument optional angeboten.',NULL,NULL,NULL,5,2015,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gle-coupé-c167','Mercedes-Benz','GLE Coupé','C167',2019,NULL,'["SUV-Coupé"]','Oberklasse','mercedes-benz-gle-coupé-c292','Das C167 Coupé unterscheidet sich vom Vorgänger C292 durch eine deutlich flachere Dachlinie, die stärker an ein Coupé erinnert. Die Scheinwerfer sind schmaler und aggressiver gezeichnet, die Heckleuchten sind horizontal geteilt und verbinden sich optisch mit dem Mercedes-Stern. Die charakteristische Mercedes-typische Kühlermaske mit dem großen Stern in der Mitte ist weiterhin präsent.','Das Facelift (voraussichtlich 2023/2024) brachte eine überarbeitete Frontschürze, neue Scheinwerfer- und Rückleuchtengrafiken sowie möglicherweise eine Leistungssteigerung bei einigen Motorvarianten. Die Innenraumgestaltung wurde mit dem MBUX-Infotainmentsystem der neuesten Generation aktualisiert.',NULL,NULL,NULL,5,2020,NULL,'24 Monate','Das GLE Coupé C167 bietet eine luxuriöse und sportliche Alternative zu traditionellen SUVs. Achten Sie bei Gebrauchtwagen auf die Wartungshistorie, insbesondere bei den leistungsstärkeren AMG-Modellen. Die hohe Sitzposition und die coupéhafte Dachlinie sind charakteristisch. Die Bedienung über das MBUX-System ist intuitiv, erfordert aber etwas Eingewöhnung.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gle-coupé-c292','Mercedes-Benz','GLE Coupé','C292',2015,2019,'["Coupé"]','Oberklasse','mercedes-benz-ml-w166','Das C292 Coupé unterscheidet sich vom Vorgänger (ML W166) durch seine stark abfallende Dachlinie, die ihm den Coupé-Charakter verleiht. Die Frontpartie mit der markanten Kühlermaske und den schmalen Scheinwerfern ist typisch für die Mercedes-Designsprache dieser Zeit. Das Heck ist durch die breiten, flachen Rückleuchten und die integrierten Endrohre geprägt.',NULL,NULL,NULL,NULL,5,2015,NULL,'24 Monate','Beim Kauf eines gebrauchten C292 sollte auf die regelmäßige Wartung geachtet werden, insbesondere bei den Dieselmotoren (OM651, OM642). Probleme mit der Abgasrückführung und dem Partikelfilter können auftreten. Bei den Benzinern sind die Zündspulen und die Steuerketten (bei älteren Modellen) zu prüfen. Die Luftfederung (AIRMATIC) ist ein Komfortmerkmal, kann aber auch kostenintensiv in der Reparatur sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gle-w166-facelift','Mercedes-Benz','GLE','W166 (Facelift)',2015,2019,'["SUV"]','Oberklasse','mercedes-benz-ml-w166','Der W166 (Facelift) unterscheidet sich vom Vorgänger durch eine neu gestaltete Frontschürze, modifizierte Scheinwerfer mit geänderter LED-Signatur, eine breitere und stärker konturierte Kühlermaske sowie überarbeitete Rückleuchten. Die Modellbezeichnung wurde von ML auf GLE geändert.','Das Facelift des W166 brachte eine überarbeitete Front mit neuer Stoßstange, modifizierten Scheinwerfern und einer angepassten Kühlermaske. Auch die Rückleuchten wurden überarbeitet. Im Innenraum gab es Detailverbesserungen am Infotainmentsystem und den Materialien. Die Modellbezeichnung wurde von ML auf GLE geändert.',NULL,NULL,NULL,5,2015,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gle-w167','Mercedes-Benz','GLE','W167',2019,NULL,'["SUV"]','Oberklasse','mercedes-benz-gle-w166','Der W167 unterscheidet sich vom Vorgänger W166 durch eine deutlich flachere und gestrecktere Silhouette, eine neu gestaltete Front mit schmaleren Scheinwerfern und einer markanteren Kühlermaske sowie ein moderneres Heck mit horizontalen Rückleuchten. Die Innenraumgestaltung wurde komplett überarbeitet und integriert das MBUX-Infotainmentsystem mit zwei großen Displays.','Das Facelift (oft als Modelljahr 2024 bezeichnet) brachte eine überarbeitete Frontschürze, neue Scheinwerfer- und Rückleuchtengrafiken, eine modifizierte Kühlermaske und neue Felgendesigns. Im Innenraum wurde das Lenkrad überarbeitet und die Bedienung des Infotainmentsystems weiterentwickelt.',NULL,NULL,NULL,5,2019,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gls-x166','Mercedes-Benz','GLS','X166',2015,2019,'["SUV"]','Oberklasse','mercedes-benz-gl-klasse-x164','Der GLS (X166) ist eine Modellpflege des GL (X164). Erkennbar ist er an der überarbeiteten Front mit neu gestalteten Scheinwerfern, einer breiteren Kühlermaske mit zwei Lamellen und einem modifizierten Stoßfänger. Am Heck gibt es ebenfalls angepasste Rückleuchten und einen neuen Stoßfänger.','Das Facelift erfolgte 2015 und brachte die Umbenennung von GL in GLS mit sich. Äußerlich wurden die Frontpartie mit neuen Scheinwerfern, Kühlergrill und Stoßfänger überarbeitet. Am Heck gab es angepasste Rückleuchten und einen neuen Stoßfänger. Im Innenraum wurden das Infotainmentsystem und die Materialien aufgewertet.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-gls-x167','Mercedes-Benz','GLS','X167',2019,NULL,'["SUV"]','Oberklasse-SUV','mercedes-benz-gls-x166','Der GLS X167 ist deutlich größer und wirkt fließender als sein Vorgänger X166. Er zeichnet sich durch eine markantere Front mit einem größeren Kühlergrill und schlankeren, oft serienmäßigen Multibeam-LED-Scheinwerfern aus. Die Heckleuchten sind zweiteilig und horizontal ausgerichtet, während das Interieur das MBUX-Infotainmentsystem mit zwei großen Bildschirmen und ein moderneres Lenkrad aufweist.','Das Facelift im Jahr 2023 brachte einen neu gestalteten Frontstoßfänger, einen Kühlergrill mit vier horizontalen Lamellen und eine modifizierte Lichtsignatur der LED-Heckleuchten. Im Innenraum wurden das Lenkrad aktualisiert, die MBUX-Software verbessert und neue Zierelemente sowie Polsterfarben eingeführt. Die Offroad-Funktionen wurden erweitert und die Motorisierungen leicht überarbeitet.',NULL,NULL,NULL,NULL,NULL,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-ml-klasse-w163','Mercedes-Benz','ML-Klasse','W163',1997,2005,'["SUV"]','Oberklasse',NULL,'Der W163 war die erste Generation der ML-Klasse. Charakteristisch sind die abgerundeten Formen im Vergleich zu kantigeren SUVs der Zeit, die integrierten Scheinwerfer und Rückleuchten sowie die markante, breite Kühlermaske mit dem großen Mercedes-Stern. Die seitlichen Fensterlinien sind relativ hoch und die C-Säule ist breit.','Das Facelift im Jahr 2001 brachte eine überarbeitete Frontschürze, neue Scheinwerfer mit Klarglasoptik, geänderte Blinkergläser, modifizierte Rückleuchten und Außenspiegel. Im Innenraum gab es ein neues Lenkrad und eine überarbeitete Mittelkonsole.',NULL,NULL,NULL,4,2002,NULL,'24 Monate','Der W163 war das erste SUV von Mercedes-Benz und bot viel Platz und Komfort. Bekannte Schwachstellen sind Rost an den Radläufen und Schwellern, Probleme mit der Elektronik (insbesondere Fensterheber und Zentralverriegelung) sowie Verschleiß an Fahrwerksteilen. Die Motoren sind generell robust, aber die Automatikgetriebe können anfällig sein. Auf Rost und die Wartungshistorie sollte geachtet werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-ml-klasse-w164','Mercedes-Benz','ML-Klasse','W164',2005,2011,'["SUV"]','Obere Mittelklasse','mercedes-benz-ml-klasse-w163','Der W164 unterscheidet sich vom Vorgänger W163 durch eine deutlich rundere und dynamischere Karosserieform. Die Scheinwerfer sind größer und ziehen sich weiter in die Kotflügel zurück. Die Front wirkt insgesamt fließender, die Heckleuchten sind breiter und horizontaler ausgerichtet als beim W163. Die C-Säule ist markanter und stärker geneigt.','Im Jahr 2008 erfolgte ein Facelift. Erkennbar ist dieses an einem neu gestalteten Frontstoßfänger mit größeren Lufteinlässen und einer geänderten Kühlermaske (drei statt vier Lamellen). Die Scheinwerfer erhielten eine leicht modifizierte Innenstruktur. Am Heck wurden der Stoßfänger und die Rückleuchten (teilweise mit LED-Technik) überarbeitet. Im Innenraum gab es neue Materialien und ein neues Lenkrad.',NULL,NULL,NULL,5,2008,20000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-ml-klasse-w166','Mercedes-Benz','ML-Klasse','W166',2011,2015,'["SUV"]','Obere Mittelklasse SUV','mercedes-benz-ml-klasse-w164','Die dritte Generation der ML-Klasse (W166) unterscheidet sich vom Vorgänger W164 durch eine deutlich modernere und fließendere Designsprache. An der Front fallen der größere, aufrechter stehende Kühlergrill mit zwei Lamellen und zentralem Stern sowie die markanteren, rechteckigen Scheinwerfer mit integriertem LED-Tagfahrlichtstreifen auf. Das Heck ist geprägt von breiteren, horizontal ausgerichteten Rückleuchten, die in die Heckklappe hineinreichen. Eine charakteristische Sicke über den hinteren Radläufen ist ebenfalls ein Erkennungsmerkmal.',NULL,NULL,NULL,NULL,5,2011,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w116','Mercedes-Benz','S-Klasse','W116',1972,1980,'["Limousine"]','Oberklasse','W108','Klassische Stufenheck-Limousine mit langer Motorhaube, verchromten Stoßfängern und markanten Rechteck-Scheinwerfern. Erkennbar an der hohen Gürtellinie und dem breiten C-Säulen-Dreiecksfenster.',NULL,NULL,NULL,NULL,NULL,NULL,10000,'2 Jahre',NULL,'2025-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w126','Mercedes-Benz','S-Klasse','W126',1979,1991,'["Limousine", "Coupé"]','Oberklasse','mercedes-benz-s-klasse-w116','Der W126 unterscheidet sich deutlich vom Vorgänger W116 durch seine deutlich flachere und aerodynamischere Linienführung. Markant sind die breiteren, horizontalen Scheinwerfer und die nunmehr stoßfängerintegrierten Blinker. Die Seitenlinie ist glatter und weniger kantig, die Fensterflächen sind größer. Das Coupé (C126) teilt sich die Plattform mit der Limousine, hat aber eine eigenständige Dachlinie und C-Säulen.','Das erste Facelift (1985) brachte eine Überarbeitung der Stoßfänger, die nun umlaufend und breiter waren (oft als ''breite Bänder'' bezeichnet). Die Zierleisten wurden ebenfalls angepasst. Technisch gab es Detailverbesserungen an den Motoren und Fahrwerk. Ein zweites, kleineres Facelift (1987) brachte unter anderem neue Felgendesigns und eine leicht modifizierte Frontschürze.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der W126 gilt als sehr robust und langlebig, besonders die Sechszylinder-Benziner (M103) und die Dieselmotoren (OM603) sind bekannt für ihre Zuverlässigkeit. Rost ist bei älteren Fahrzeugen ein Thema, besonders an Radläufen, Schwellerenden und Wagenheberaufnahmen. Die Automatikgetriebe können bei hoher Laufleistung anfällig sein. Die elektrische Anlage, insbesondere die Fensterheber und die Zentralverriegelung, kann Probleme bereiten. Eine gute Wartungshistorie ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w140','Mercedes-Benz','S-Klasse','W140',1991,1998,'["Limousine", "Coupé"]','Oberklasse','mercedes-benz-s-klasse-w126','Die W140-Generation zeichnet sich durch ein sehr massives und imposantes Erscheinungsbild aus, deutlich größer und breiter als der Vorgänger W126. Typisch sind die breite C-Säule, die großen, rechteckigen Scheinwerfer und Rückleuchten sowie die Doppelverglasung für verbesserte Geräuschdämmung. Bis zum Facelift waren zudem elektrisch ausfahrbare Peilstäbe an den hinteren Kotflügeln zur Einparkhilfe sichtbar.','Das Facelift (Modellpflege ''94) im Jahr 1994 brachte leicht modifizierte Front- und Heckstoßfänger, weiße Blinkergläser vorne (statt orange), geänderte Rückleuchten mit dunkleren Segmenten und einen leicht überarbeiteten Kühlergrill. Die zuvor sichtbaren Peilstäbe zur Einparkhilfe wurden durch Ultraschallsensoren (Parktronic) ersetzt.',NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w220','Mercedes-Benz','S-Klasse','W220',1998,2005,'["Limousine"]','Oberklasse','mercedes-benz-s-klasse-w140','Der W220 zeichnet sich durch ein deutlich runderes und fließenderes Design im Vergleich zum kantigen Vorgänger W140 aus. Die Front wird von charakteristischen, mandelförmigen Doppelscheinwerfern dominiert, die sich klar von den rechteckigen Einheiten des W140 abgrenzen. Die Silhouette ist insgesamt flacher und eleganter.','Das Facelift erfolgte im Herbst 2002. Optisch erkennbar an klareren Scheinwerfergläsern (nicht mehr so milchig/matt), einer leicht modifizierten Frontschürze und neuen Rückleuchten mit klareren Segmenten. Im Innenraum gab es ein neues Lenkrad und ein überarbeitetes COMAND-System. Technisch wurden das Active Body Control (ABC)-Fahrwerk und die Elektronik verbessert.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w221','Mercedes-Benz','S-Klasse','W221',2005,2013,'["Limousine"]','Oberklasse','mercedes-benz-s-klasse-w220','Die S-Klasse W221 zeichnet sich durch ein deutlich runderes und fließenderes Design im Vergleich zum Vorgänger W220 aus. Sie besitzt markante, größere, mandelförmige Scheinwerfer, die sich weit in die Kotflügel ziehen. Der Kühlergrill ist breiter und verfügt über drei Lamellen, wobei der Mercedes-Stern auf der Motorhaube platziert ist. Die Radläufe sind stärker ausgeprägt, und die Rückleuchten sind breiter und flacher als beim W220, mit einer klaren horizontalen Gliederung.','Das Facelift (MOPF) im Jahr 2009 brachte dezente Änderungen mit sich. Dazu gehören neu gestaltete Stoßfänger vorne und hinten, die nun integrierte LED-Tagfahrlichter im vorderen Stoßfänger aufweisen. Die Scheinwerfer erhielten eine leicht modifizierte Innenstruktur und LED-Blinker. Die Rückleuchten wurden ebenfalls leicht überarbeitet und erhielten eine durchgehende Chromleiste. Im Innenraum gab es neue Lenkräder und eine überarbeitete COMAND-Bedienung.',NULL,NULL,NULL,NULL,NULL,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w222','Mercedes-Benz','S-Klasse','W222',2013,2020,'["Limousine", "Langversion", "Coupé", "Cabriolet", "Maybach"]','Oberklasse','mercedes-benz-s-klasse-w221','Die W222-Generation zeichnet sich durch eine fließendere, elegantere Linienführung im Vergleich zum Vorgänger W221 aus. Auffällig sind die markanten, vollständig mit LED-Technik ausgestatteten Scheinwerfer und Rückleuchten, die eine charakteristische Lichtsignatur bilden. Im Innenraum dominieren zwei große, nebeneinander angeordnete Displays für Instrumente und Infotainment, die eine durchgehende Glasfläche bilden und das Cockpit modernisieren. Die Frontpartie wirkt breiter und präsenter, mit einem größeren Kühlergrill und stärker konturierten Stoßfängern.','Das Facelift im Jahr 2017 brachte primär optische Neuerungen an der Front: Neue Multibeam-LED-Scheinwerfer mit drei markanten LED-Fackeln als Tagfahrlicht, ein überarbeiteter Kühlergrill (je nach Ausstattung mit drei Doppellamellen oder feineren vertikalen Streben) und neu gestaltete Stoßfänger. Am Heck wurden die LED-Rückleuchten mit einem ''Stardust''-Effekt versehen. Im Innenraum gab es ein neues Lenkrad mit Touch-Control-Buttons und eine Aktualisierung des Infotainmentsystems COMAND Online.',NULL,NULL,NULL,NULL,NULL,25000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-s-klasse-w223','Mercedes-Benz','S-Klasse','W223',2020,NULL,'["Limousine"]','Oberklasse','mercedes-benz-s-klasse-w222','Die W223-Generation zeichnet sich durch flachere, breitere Scheinwerfer aus, die weit in die Kotflügel reichen, sowie einen größeren, aufrechter stehenden Kühlergrill. Am Heck fallen die zweiteiligen, horizontalen Rückleuchten auf, die sich bis in die Heckklappe erstrecken. Ein weiteres markantes Merkmal sind die bündig in die Karosserie integrierten Türgriffe, die elektrisch ausfahren. Im Innenraum dominiert ein großes, hochkant stehendes Zentraldisplay und ein volldigitales Kombiinstrument.',NULL,NULL,NULL,NULL,5,2021,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-sl-r230','Mercedes-Benz','SL','R230',2001,2011,'["Cabriolet"]','Oberklasse','mercedes-benz-sl-r129','Der R230 löste den R129 ab. Charakteristisch sind die markanten Doppelscheinwerfer, die im Vergleich zum Vorgänger deutlich runderen Formen und die integrierten Blinker in den Außenspiegeln. Die charakteristische SL-Linie mit dem langen Radstand und der kurzen Fahrgastzelle bleibt erhalten.','Das erste Facelift (2006) brachte eine überarbeitete Front mit neu gestalteten Scheinwerfern und Kühlergrill, geänderte Frontschürze, neue Außenspiegel mit integrierten Blinkern und ein überarbeitetes Heck mit neuen Rückleuchten. Das Interieur wurde ebenfalls aufgewertet. Ein zweites Facelift (2008) brachte weitere Detailänderungen, unter anderem eine neue Lenkradgeneration und überarbeitete Infotainmentsysteme.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre','Der R230 ist ein komfortables und sportliches Cabriolet. Achten Sie auf Rost an den Radläufen und Schwellern, Probleme mit dem ABC-Fahrwerk (Active Body Control) und der Elektronik. Die Motoren sind generell robust, aber die Wartungskosten können hoch sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-sl-r231','Mercedes-Benz','SL','R231',2012,2020,'["Roadster"]','Luxus-Roadster','mercedes-benz-sl-r230','Der R231 unterscheidet sich vom Vorgänger R230 durch eine deutlich kantigere und modernere Designsprache. Auffällig sind die aufrechter stehende Front mit einem großen, zentralen Stern im Kühlergrill, die markanten LED-Tagfahrlichter in den Stoßfängern und die breiteren, horizontal ausgerichteten Heckleuchten. Die Seitenlinie wirkt gestreckter und weniger rundlich als beim R230.','Das Facelift (Modellpflege) erfolgte Ende 2015 für das Modelljahr 2016. Die Front wurde umfassend überarbeitet mit neuen, schmaleren und schräger gestellten LED-Scheinwerfern, einem neu gestalteten Kühlergrill im ''Diamond''-Design (je nach Ausstattung) und einer sportlicheren Frontschürze. Am Heck gab es leicht modifizierte Heckleuchten mit neuer LED-Grafik und eine überarbeitete Heckschürze mit integrierten Endrohren. Im Innenraum wurden das Infotainmentsystem und das Lenkrad aktualisiert.',NULL,NULL,NULL,NULL,NULL,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-sl-r232','Mercedes-Benz','SL','R232',2021,NULL,'["Roadster"]','Luxus-Sportwagen','mercedes-benz-sl-r231','Der R232 ist sofort an seiner sportlich-eleganten, flachen Silhouette mit langem Radstand und kurzen Überhängen erkennbar. Charakteristisch sind die schmalen, scharf gezeichneten LED-Scheinwerfer, der AMG-spezifische Panamericana-Kühlergrill mit vertikalen Streben und die schlanken, horizontal ausgerichteten LED-Rückleuchten. Im Gegensatz zum Vorgänger R231 verfügt der R232 über ein klassisches Stoffverdeck und eine 2+2-Sitzkonfiguration.',NULL,NULL,NULL,NULL,NULL,NULL,20000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-v-klasse-w447','Mercedes-Benz','V-Klasse','W447',2014,NULL,'["Van"]','Mittelklasse','mercedes-benz-viano-w639','Der W447 unterscheidet sich deutlich vom Vorgänger W639. Die Frontpartie ist moderner gestaltet mit schmaleren Scheinwerfern, einer markanteren Motorhaube und einer neuen Stoßstange. Die Seitenlinie ist glatter und die Heckleuchten sind horizontaler angeordnet und reichen weiter in die Heckklappe hinein. Das Interieur wurde ebenfalls komplett überarbeitet und wirkt hochwertiger.','Im Jahr 2019 erhielt die V-Klasse (W447) ein Facelift. Äußerlich erkennbar an einer neu gestalteten Frontschürze, einem modifizierten Kühlergrill mit optional zwei Lamellen, neuen Scheinwerfer- und Rückleuchtengrafiken sowie neuen Felgendesigns. Im Innenraum wurden das Armaturenbrett überarbeitet, ein neues Lenkrad mit Touch-Control-Buttons eingeführt und das Infotainmentsystem aktualisiert. Die Lüftungsdüsen wurden ebenfalls neu gestaltet.',NULL,NULL,NULL,5,2014,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-v-klasse-w638','Mercedes-Benz','V-Klasse','W638',1996,2003,'["Großraumlimousine"]','Großraumlimousine',NULL,'Die erste Generation der V-Klasse (W638) zeichnet sich durch eine relativ kantige, aber dennoch abgerundete Van-Karosserie aus. Die Frontpartie wird von großen, rechteckigen Scheinwerfern dominiert, die bündig in die Karosserie integriert sind. Der Kühlergrill ist schmal und horizontal ausgerichtet, mit dem Mercedes-Stern in der Mitte. Im Vergleich zum Nachfolger (W639) wirkt der W638 weniger dynamisch und stärker auf Funktionalität ausgerichtet, mit einer flacheren Windschutzscheibe und einer insgesamt weniger Pkw-ähnlichen Anmutung.','Im Jahr 1999 erfolgte ein Facelift. Äußerlich erkennbar war dies an leicht modifizierten Scheinwerfern mit Klarglasoptik und einer geänderten Frontschürze. Im Innenraum wurden die Materialien aufgewertet und die Instrumententafel überarbeitet. Technisch gab es Verbesserungen an Fahrwerk und Bremsen sowie neue Motoren.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('mercedes-benz-viano-w639','Mercedes-Benz','Viano','W639',2003,2014,'["Van"]','Mittelklasse','Vito/V-Klasse (W638)','Der W639 unterscheidet sich deutlich vom Vorgänger W638. Er hat eine kantigere, modernere Form. Die Scheinwerfer sind größer und trapezförmiger, die Frontpartie wirkt bulliger. Die Seitenlinie ist geradliniger und die Fensterflächen sind anders proportioniert. Die Heckleuchten sind vertikal angeordnet und reichen weiter in die Heckklappe hinein.','Das Facelift im Jahr 2010 brachte eine überarbeitete Frontpartie mit neuen Scheinwerfern, einem geänderten Kühlergrill und Stoßfängern. Auch die Rückleuchten wurden modifiziert. Im Innenraum gab es neue Materialien und ein überarbeitetes Bedienkonzept.',NULL,NULL,NULL,NULL,NULL,NULL,'24 Monate','Der Viano W639 ist ein geräumiger und vielseitiger Van, der sich gut für Familien und als Transporter eignet. Achten Sie beim Kauf auf Rost, insbesondere an den Radläufen und Schwellern. Die Automatikgetriebe können anfällig sein. Regelmäßige Wartung ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-adam-a','Opel','Adam','A',2012,2019,'["Kleinwagen", "Cabrio"]','Kleinstwagen',NULL,'Der Opel Adam A ist ein dreitüriger Kleinstwagen mit einer markanten, runden Formgebung. Typisch sind die schwebend wirkende Dachlinie, die durch eine farblich abgesetzte A-Säule und ein optionales Kontrastdach betont wird. Die Front zeichnet sich durch große, mandelförmige Scheinwerfer und einen breiten Kühlergrill mit Chromspange und Opel-Blitz aus. Am Heck fallen die runden Rückleuchten und die relativ hohe Ladekante auf. Im Vergleich zu anderen Opel-Modellen seiner Zeit wirkt der Adam verspielter und individueller.',NULL,NULL,NULL,NULL,5,2013,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-f','Opel','Astra','F',1991,1998,'["Schrägheck", "Limousine", "Caravan", "Cabriolet", "Kastenwagen"]','Kompaktklasse','opel-kadett-e','Der Astra F zeichnet sich durch sein geradliniges, funktionales Design aus. Die Frontpartie wird von schmalen, rechteckigen Scheinwerfern und einem schmalen Kühlergrill mit dem Opel-Blitz dominiert. Die Heckleuchten sind ebenfalls rechteckig und oft durch eine Leiste oder den Opel-Schriftzug verbunden. Im Vergleich zum Vorgänger Kadett E wirkt er moderner und aerodynamischer, aber noch deutlich kantiger als der Nachfolger Astra G.','Das Facelift im Herbst 1994 (Modelljahr 1995) brachte eine Reihe von Änderungen mit sich. Äußerlich fielen vor allem die leicht modifizierten Stoßfänger, der geänderte Kühlergrill (oft mit Chromleiste) und die nun klaren Blinkergläser vorne auf. Im Innenraum wurden die Materialien verbessert, neue Polsterstoffe eingeführt und das Lenkrad-Design überarbeitet. Technisch gab es Verbesserungen bei der Rostvorsorge und der Motorenpalette.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-g','Opel','Astra','G',1998,2005,'["Limousine", "Caravan", "Coupé", "Cabrio", "Lieferwagen"]','Kompaktklasse','opel-astra-f','Der Astra G zeichnet sich durch eine deutlich rundlichere und aerodynamischere Karosserie im Vergleich zum kantigeren Vorgänger Astra F aus. Die Scheinwerfer sind groß und bogenförmig, fließen in die Kotflügel über. Die Frontpartie wirkt insgesamt weicher, mit einem integrierten Kühlergrill, der das Opel-Logo trägt. Die Heckleuchten sind ebenfalls runder und breiter als beim Vorgänger.',NULL,NULL,NULL,NULL,4,1999,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-h','Opel','Astra','H',2004,2010,'["Schrägheck", "Kombi", "Limousine", "Coupé-Cabriolet", "GTC"]','Kompaktklasse','opel-astra-g','Der Opel Astra H zeichnet sich durch eine deutlich modernere und dynamischere Formgebung im Vergleich zum Vorgänger Astra G aus. Auffällig sind die größeren, mandelförmigen Scheinwerfer, die bis in die Kotflügel reichen, sowie die markante, V-förmige Front mit einem breiteren Kühlergrill, der das Opel-Logo prominent trägt. Die Seitenlinie ist fließender, und die Heckleuchten sind breiter und horizontaler ausgerichtet als beim Astra G. Die GTC-Variante (dreitürig) besitzt eine eigenständige, coupéartige Dachlinie und eine sportlichere Frontschürze.','Im Jahr 2007 erfolgte ein leichtes Facelift. Die Änderungen waren subtil und umfassten primär eine leicht modifizierte Frontschürze mit einem größeren Lufteinlass und Chromapplikationen (je nach Ausstattung), neue Rückleuchten mit einer leicht geänderten Grafik (teilweise in LED-Optik) und neue Felgendesigns. Im Innenraum gab es kleinere Anpassungen bei den Materialien und Dekorleisten.',NULL,NULL,NULL,5,2004,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-j','Opel','Astra','J',2009,2015,'["Schrägheck", "Kombi", "Limousine", "Coupé"]','Kompaktklasse','opel-astra-h','Der Opel Astra J zeichnet sich durch eine markante, coupé-ähnliche Dachlinie und eine breite, muskulöse Karosserie aus. Auffällig sind die bumerangförmigen Scheinwerfer, die sich weit in die Kotflügel ziehen, sowie die sichelförmige Sicke in den hinteren Türen, die zur C-Säule ansteigt. Im Vergleich zum Vorgänger Astra H wirkt er deutlich dynamischer und runder, mit einer stärker ausgeprägten Schulterlinie. Die Limousine und das Coupé (GTC) wurden bis 2018 produziert.','Im Jahr 2012 erhielt der Astra J ein Facelift. Die Front wurde überarbeitet mit einem neuen Kühlergrill, der eine breitere Chromspange und eine geänderte Wabenstruktur aufweist. Die Nebelscheinwerfer erhielten eine neue Einfassung mit Chromakzenten. Am Heck wurden die Rückleuchten leicht modifiziert und die Chromleiste über dem Kennzeichen bei den Schrägheck- und Kombimodellen neu gestaltet. Zudem gab es neue Felgendesigns und eine erweiterte Motorenpalette.',NULL,NULL,NULL,5,2009,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-k','Opel','Astra','K',2015,2021,'["Schrägheck", "Kombi"]','Kompaktklasse','opel-astra-j','Der Astra K zeichnet sich durch eine deutlich schlankere und dynamischere Karosserie im Vergleich zum Vorgänger Astra J aus. Ein markantes Merkmal ist das ''schwebende Dach'', das durch eine schwarze Blende an der C-Säule erzeugt wird. Die Scheinwerfer sind schmaler und schärfer gezeichnet, oft mit der optionalen IntelliLux LED Matrix-Lichttechnologie. Der Kühlergrill ist breiter und flacher, mit einer Chromspange, die optisch in die Scheinwerfer übergeht.','Das Facelift im Jahr 2019 brachte äußerlich nur geringfügige Änderungen mit sich, darunter eine leicht modifizierte Frontschürze mit neuen Lufteinlässen und dezent angepasste Kühlergrill-Einsätze. Die wesentlichen Neuerungen betrafen die Motorenpalette mit neuen Dreizylinder-Benzin- und Dieselmotoren sowie aerodynamische Verbesserungen. Im Innenraum gab es ein aktualisiertes Infotainmentsystem und optional ein digitales Kombiinstrument.',NULL,NULL,NULL,5,2015,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-astra-l','Opel','Astra','L',2021,NULL,'["Schrägheck", "Kombi"]','Kompaktklasse','opel-astra-k','Der Opel Astra L ist sofort an der markanten ''Opel Vizor''-Front zu erkennen, einem durchgehenden schwarzen Band, das die schlanken LED-Scheinwerfer und das Opel-Logo integriert. Die Karosserie zeichnet sich durch scharfe, kantige Linien und eine sportlichere Silhouette aus. Am Heck fallen die schmalen, horizontal ausgerichteten LED-Rückleuchten auf. Im Innenraum unterscheidet er sich deutlich vom Vorgänger durch das volldigitale ''Pure Panel''-Cockpit mit zwei großen Bildschirmen.',NULL,NULL,NULL,NULL,5,2022,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-a','Opel','Corsa','A',1982,1993,'["Schrägheck", "Stufenheck"]','Kleinwagen',NULL,'Der Opel Corsa A zeichnet sich durch seine kantige, kompakte Karosserie aus. Die frühen Modelle (bis 1990) haben markante rechteckige Scheinwerfer und einen schmalen Kühlergrill. Im Vergleich zum Nachfolger Corsa B ist der Corsa A deutlich weniger abgerundet und wirkt insgesamt eckiger.','Ein umfassendes Facelift erfolgte 1990. Dabei wurden die Frontscheinwerfer runder und größer, der Kühlergrill wurde neu gestaltet und oft in den Stoßfänger integriert. Die Stoßfänger selbst wurden ebenfalls überarbeitet und wirkten massiver. Auch die Heckleuchten erhielten ein leicht modifiziertes Design.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-b','Opel','Corsa','B',1993,2000,'["3-Türer Schrägheck", "5-Türer Schrägheck", "Kombi", "Stufenheck", "Lieferwagen"]','Kleinwagen','opel-corsa-a','Der Corsa B zeichnet sich durch seine deutlich runderen und weicheren Formen im Vergleich zum kantigen Vorgänger Corsa A aus. Die Frontpartie ist geprägt von ovalen, leicht schräg gestellten Scheinwerfern und einem kleinen, ovalen Kühlergrill. Die Heckleuchten sind vertikal angeordnet und reichen bis in die Seitenflanken.','Ein Facelift erfolgte 1997 (Modelljahr 1998). Die Änderungen waren subtil und umfassten eine leicht modifizierte Frontschürze mit integrierten Nebelscheinwerfern (je nach Ausstattung), einen leicht überarbeiteten Kühlergrill mit einer breiteren Chromleiste und neue Radkappen/Leichtmetallfelgen. Im Innenraum gab es neue Stoffmuster und geringfügige Anpassungen an den Bedienelementen.',NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-c','Opel','Corsa','C',2000,2006,'["3-Türer", "5-Türer", "Kastenwagen"]','Kleinwagen','opel-corsa-b','Der Corsa C unterscheidet sich vom Vorgänger B durch eine deutlich rundlichere und modernere Formgebung. Die Scheinwerfer sind größer und mandelförmiger, die Heckleuchten sind vertikal angeordnet und reichen bis in die C-Säule. Die Gürtellinie ist höher und die Karosserie wirkt insgesamt bulliger und weniger kantig als beim Corsa B.','Im Herbst 2003 erfolgte ein Facelift. Die Frontschürze wurde neu gestaltet, der Kühlergrill erhielt eine breitere Chromspange und die Scheinwerfer bekamen ein leicht geändertes Innenleben. Am Heck wurden die Rückleuchten leicht modifiziert, insbesondere die Anordnung der Leuchtelemente. Im Innenraum wurden die Materialien aufgewertet und neue Polsterstoffe eingeführt.',NULL,NULL,NULL,4,2002,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-d','Opel','Corsa','D',2006,2014,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kleinwagen','opel-corsa-c','Der Corsa D unterscheidet sich vom Vorgänger Corsa C durch ein deutlich runderes und moderneres Design. Er besitzt große, mandelförmige Scheinwerfer, die weit in die Kotflügel reichen, sowie einen breiteren Kühlergrill mit einer markanten Chromspange und einem großen Opel-Logo. Die Karosserie wirkt insgesamt erwachsener und weniger kantig als beim Corsa C.','Das Facelift erfolgte Ende 2010/Anfang 2011. Die Front wurde überarbeitet mit einer neuen Frontschürze, einem breiteren Lufteinlass und neu integrierten Nebelscheinwerfern. Der Kühlergrill erhielt eine breitere Chromspange. Die Scheinwerfer wurden leicht modifiziert und waren optional mit LED-Tagfahrlicht erhältlich. Im Innenraum gab es neue Stoffe und Farben sowie eine überarbeitete Instrumentenbeleuchtung.',NULL,NULL,NULL,5,2006,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-e','Opel','Corsa','E',2014,2019,'["Kleinwagen 3-Türer", "Kleinwagen 5-Türer"]','Kleinwagen','opel-corsa-d','Der Corsa E unterscheidet sich vom Vorgänger Corsa D durch eine deutlich modernisierte Frontpartie mit größeren, mandelförmigen Scheinwerfern, die oft mit LED-Tagfahrlicht in einer ''Flügel''-Form ausgestattet sind. Der Kühlergrill ist breiter und flacher, oft mit einer Chromspange, die in die Scheinwerfer übergeht. Am Heck fallen die breiteren, horizontal ausgerichteten Rückleuchten auf, die sich in die Heckklappe ziehen und dem Fahrzeug eine breitere Optik verleihen. Die Seitenlinie wirkt dynamischer, mit einer stärker ausgeprägten Sicke unterhalb der Fensterlinie.',NULL,NULL,'5.9',NULL,4,2014,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-corsa-f','Opel','Corsa','F',2019,NULL,'["Schrägheck"]','Kleinwagen','opel-corsa-e','Der Opel Corsa F ist die erste Generation, die auf der CMP-Plattform des PSA-Konzerns basiert. Er unterscheidet sich vom Vorgänger Corsa E durch eine deutlich modernere, dynamischere Formgebung mit schärferen Linien, flacheren Scheinwerfern und einer breiter wirkenden Front. Die Heckleuchten sind schmaler und horizontaler ausgerichtet. Im Innenraum dominieren ein freistehender Infotainment-Bildschirm und optional ein digitales Kombiinstrument.','Das Facelift (Modelljahr 2024, vorgestellt 2023) führte das Opel Vizor-Markengesicht ein, bei dem Scheinwerfer und Opel-Blitz in einem durchgehenden schwarzen Element integriert sind. Die Front- und Heckschürzen wurden neu gestaltet, und es gab neue Felgendesigns. Im Innenraum wurden das Infotainmentsystem und das digitale Kombiinstrument aktualisiert, sowie neue Sitzbezüge und ein überarbeitetes Lenkrad eingeführt.',NULL,NULL,NULL,4,2019,25000,'Alle 2 Jahre nach der ersten HU nach 3 Jahren',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-crossland-a','Opel','Crossland','A',2017,NULL,'["SUV", "Crossover"]','Mini-SUV','opel-meriva-b','Der Opel Crossland A zeichnet sich durch seine erhöhte Karosserie und SUV-ähnliche Optik aus. Charakteristisch sind die markanten, weit außen platzierten Scheinwerfer, die in die Opel-typische Chromspange des Kühlergrills übergehen. Die Seitenlinie ist von einer aufsteigenden Fensterlinie und einer optionalen Zweifarblackierung mit abgesetztem Dach geprägt. Im Vergleich zum Vorgänger Meriva B ist er höher und robuster gestaltet, mit einer stärker betonten Front und Heckpartie.','Im Jahr 2020 erfolgte ein Facelift, bei dem der Zusatz ''X'' im Modellnamen entfiel. Optisch wurde die Frontpartie überarbeitet und erhielt das neue Opel Vizor-Gesicht, bei dem Kühlergrill und Scheinwerfer zu einer Einheit verschmelzen. Die Nebelscheinwerfer wurden neu positioniert. Am Heck gab es leicht modifizierte Rückleuchten und einen neu gestalteten Stoßfänger.',NULL,NULL,NULL,5,2017,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-grandland-a','Opel','Grandland','A',2017,NULL,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Opel Grandland (ursprünglich Grandland X) zeichnet sich durch eine typische SUV-Form mit erhöhter Bodenfreiheit aus. Vor dem Facelift (bis 2021) hatte er eine klassische Kühlergrill-Optik mit Chromspange und das Opel-Logo in der Mitte, sowie Scheinwerfer mit einer markanten ''Doppel-Flügel''-LED-Tagfahrlichtsignatur. Nach dem Facelift (ab 2021) wurde die Front auf das ''Opel Vizor''-Design umgestellt, bei dem Kühlergrill und Scheinwerfer zu einer durchgehenden, schwarzen Einheit verschmelzen, die das Opel-Logo integriert. Die Heckleuchten sind schmaler und horizontaler als beim Vorgänger Antara.','Das Facelift im Jahr 2021 brachte eine umfassende Überarbeitung der Frontpartie mit sich. Der Grandland erhielt das neue ''Opel Vizor''-Gesicht, bei dem der Kühlergrill und die Scheinwerfer zu einer durchgehenden, schwarzen Einheit verschmelzen. Die Scheinwerfer wurden schlanker und erhielten optional IntelliLux LED Pixel Licht. Am Heck wurden die Schriftzüge und das Opel-Logo neu gestaltet, und der Modellname ''GRANDLAND'' ist nun mittig unter dem Logo platziert. Im Innenraum wurde das digitale ''Pure Panel'' eingeführt, das zwei große Bildschirme für Instrumente und Infotainment nahtlos integriert.',NULL,NULL,NULL,5,2017,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-grandland-b','Opel','Grandland','B',2024,NULL,'["SUV"]','Kompakt-SUV','opel-grandland-a','Die zweite Generation des Grandland ist sofort am markanten Opel Vizor-Frontdesign erkennbar, das Scheinwerfer und Kühlergrill nahtlos in einem schwarzen Band integriert. Ein weiteres Merkmal ist das beleuchtete Opel Blitz-Logo in der Front und der prominente ''GRANDLAND''-Schriftzug über die gesamte Breite der Heckklappe. Die Karosserie wirkt insgesamt kantiger und muskulöser als beim Vorgänger.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre nach Erstzulassung, danach alle 12 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-insignia-b','Opel','Insignia','B',2017,2022,'["Fließheck", "Kombi"]','Mittelklasse','opel-insignia-a','Der Insignia B (Grand Sport/Sports Tourer) ist deutlich flacher und dynamischer gezeichnet als sein Vorgänger. Er besitzt schmalere, schärfer geschnittene Scheinwerfer, die oft mit LED-Tagfahrlicht in Flügelform ausgestattet sind und optisch in den breiteren Kühlergrill übergehen. Eine charakteristische, geschwungene Linie zieht sich von der A-Säule bis zum Heck. Die Dachlinie des Grand Sport ist coupé-ähnlicher, während der Sports Tourer eine dynamischere Heckpartie mit schmaleren Rückleuchten aufweist.','Das Facelift im Jahr 2020 brachte eine überarbeitete Frontschürze mit integrierten Nebelscheinwerfern und einen neu gestalteten Kühlergrill mit feineren Lamellen. Die markanteste Änderung waren die neuen, schmaleren IntelliLux LED Pixel Licht Scheinwerfer, die nun 84 statt 32 LED-Elemente pro Seite besaßen. Am Heck wurden die Stoßfänger und die Endrohrblenden leicht modifiziert.',NULL,NULL,NULL,5,2017,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-karl-a','Opel','Karl','A',2015,2019,'["Schrägheck"]','Kleinstwagen','opel-agila-b','Der Opel Karl A ist ein kompakter Fünftürer mit einer relativ hohen Dachlinie und kurzen Überhängen. Er zeichnet sich durch die typische Opel-Front mit dem breiten Kühlergrill und der horizontalen Chromspange aus, die in die Scheinwerfer übergeht. Die Scheinwerfer sind eher schlicht und rechteckig geformt. Im Vergleich zum Vorgänger Agila B wirkt der Karl weniger van-artig und mehr wie ein konventioneller Kleinwagen.',NULL,NULL,NULL,NULL,4,2015,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-meriva-a','Opel','Meriva','A',2003,2010,'["Kompaktvan"]','Kompaktvan',NULL,'Der Meriva A zeichnet sich durch seine kompakte, hochbauende Karosserie mit einer markanten, nach hinten ansteigenden Fensterlinie aus. Die großen, leicht dreieckigen Scheinwerfer sind in die Kotflügel integriert und die Heckleuchten sind vertikal angeordnet. Im Vergleich zum Nachfolger (Meriva B) fehlen die gegenläufig öffnenden FlexDoors und die stärker ausgeprägten Sicken in den Seitenflanken.','Das Facelift im Jahr 2006 brachte eine überarbeitete Frontpartie mit einem größeren Kühlergrill, der nun eine breitere Chromspange trug, und neu gestalteten Nebelscheinwerfern. Die Heckleuchten erhielten eine leicht modifizierte Optik mit dunkleren Einsätzen. Zudem wurden neue Außenfarben und Felgendesigns eingeführt.',NULL,NULL,NULL,4,2003,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-meriva-b','Opel','Meriva','B',2010,2017,'["Minivan"]','Kompaktvan','opel-meriva-a','Der Meriva B ist deutlich runder und dynamischer gestaltet als sein Vorgänger. Sein markantestes Merkmal sind die gegenläufig öffnenden Türen (FlexDoors) hinten. Die Front zeigt einen größeren Kühlergrill mit einer breiten Chromspange und markante, weit in die Kotflügel gezogene Scheinwerfer. Am Heck fallen die breiteren, horizontal ausgerichteten Rückleuchten auf, die in die Heckklappe hineinreichen.','Im Herbst 2013 (Modelljahr 2014) erfolgte ein Facelift. Die Änderungen umfassten einen neu gestalteten Kühlergrill mit mehr Chrom, überarbeitete Scheinwerfer (optional mit LED-Tagfahrlicht), neue Rückleuchten (teilweise in LED-Technik), neue Leichtmetallräder und ein aktualisiertes Infotainmentsystem.',NULL,NULL,NULL,5,2010,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-mokka-a','Opel','Mokka','A',2012,2016,'["SUV"]','Mini-SUV',NULL,'Die erste Generation des Opel Mokka (Mokka A) zeichnet sich durch eine rundlichere, konventionellere SUV-Form aus. Auffällig sind die großen, mandelförmigen Scheinwerfer, die weit in die Kotflügel reichen, und der breite Kühlergrill mit einer markanten Chromspange, die das Opel-Logo trägt. Die Seitenlinie ist von einer aufsteigenden Sicke geprägt, die von den vorderen Türen bis zu den Rückleuchten verläuft. Im Vergleich zum Nachfolger (Mokka B) wirkt der Mokka A weniger futuristisch und hat eine höhere, weniger coupéartige Dachlinie.',NULL,NULL,NULL,NULL,5,2012,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-mokka-b','Opel','Mokka','B',2020,NULL,'["SUV"]','Kleinwagen-SUV','opel-mokka-a','Der Mokka B ist sofort an der neuen Opel-Designsprache ''Vizor'' erkennbar, die eine durchgehende, schwarze Blende über die gesamte Fahrzeugbreite an der Front bildet und die schmalen LED-Scheinwerfer integriert. Er hat eine deutlich sportlichere, coupéhaftere Silhouette als sein Vorgänger, oft mit einem kontrastfarbenen Dach. Die Karosserie ist kompakter und die Proportionen dynamischer.',NULL,NULL,NULL,NULL,4,2021,25000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-zafira-a','Opel','Zafira','A',1999,2005,'["Kompaktvan"]','Kompaktvan',NULL,'Der Opel Zafira A ist die erste Generation des Modells. Er zeichnet sich durch seine kompakte Van-Form mit dem charakteristischen Flex7-Sitzsystem aus. Die Frontpartie ist geprägt von runden, leicht mandelförmigen Scheinwerfern und einem schmalen Kühlergrill mit dem Opel-Blitz in der Mitte. Die Karosserie hat weichere, rundlichere Linien im Vergleich zum Nachfolger Zafira B, der kantiger und moderner wirkt. Die Heckleuchten sind vertikal angeordnet und reichen bis in die D-Säule.','Im Jahr 2003 erhielt der Zafira A ein Facelift. Die auffälligsten Änderungen waren Klarglas-Scheinwerfer vorne, eine überarbeitete Frontschürze, ein Kühlergrill mit einer breiteren Chromspange und neue Rückleuchtengrafiken. Im Innenraum gab es kleinere Anpassungen bei den Materialien und Zierelementen.',NULL,NULL,NULL,4,2001,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-zafira-b','Opel','Zafira','B',2005,2011,'["Kompaktvan"]','Kompaktklasse','opel-zafira-a','Der Opel Zafira B unterscheidet sich vom Vorgänger Zafira A durch ein deutlich moderneres, runderes Design. Auffällig sind die größeren, geschwungenen Scheinwerfer, die bis in die Kotflügel reichen, sowie die markantere, V-förmige Frontschürze. Die Seitenlinie ist fließender, und die Heckleuchten sind größer und runder gestaltet, oft mit einer Chromleiste zwischen ihnen. Im Innenraum wirkt das Cockpit aufgeräumter und moderner.','Im Februar 2008 erfolgte ein Facelift. Die Front erhielt einen neuen Kühlergrill mit breiterer Chromspange und neu gestalteten Nebelscheinwerfern. Die Heckleuchten wurden leicht modifiziert und erhielten eine dunklere Tönung. Im Innenraum wurden neue Dekorleisten und Stoffe eingeführt, und die Instrumente erhielten eine neue Grafik.',NULL,NULL,NULL,5,2005,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-zafira-c','Opel','Zafira','C',2011,2019,'["Kompaktvan"]','Kompaktklasse','opel-zafira-b','Der Zafira C, auch bekannt als Zafira Tourer, unterscheidet sich deutlich vom Vorgänger Zafira B durch eine dynamischere und fließendere Karosserielinie. Auffällig sind die bumerangförmigen Scheinwerfer, die sich bis in die Kotflügel ziehen und die Nebelscheinwerfer umfassen. Die Front wirkt breiter und sportlicher, die Dachlinie fällt sanfter nach hinten ab. Die Heckleuchten sind breiter und horizontaler ausgerichtet als beim Zafira B.','Im Jahr 2016 erhielt der Zafira C ein Facelift. Die markantesten Änderungen betrafen die Frontpartie: Die bumerangförmigen Scheinwerfer wichen einer konventionelleren, horizontalen Gestaltung mit LED-Tagfahrlicht. Der Kühlergrill wurde breiter und integrierte sich nahtloser in die Scheinwerfer. Auch die Frontschürze wurde überarbeitet, was dem Fahrzeug ein moderneres und aufgeräumteres Aussehen verlieh. Im Innenraum gab es ein neues Infotainmentsystem und ein überarbeitetes Armaturenbrett mit weniger Knöpfen.',NULL,NULL,NULL,5,2011,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('opel-zafira-life-1-generation','Opel','Zafira Life','1. Generation',2019,NULL,'["Großraumlimousine"]','Van','opel-zafira-c','Der Opel Zafira Life ist eine Großraumlimousine, die auf der EMP2-Plattform von PSA basiert und eng mit dem Peugeot Traveller, Citroën Spacetourer und Toyota Proace Verso verwandt ist. Er unterscheidet sich von seinen Vorgängern (Zafira A/B/C) durch seine deutlich größere, kastenförmige Karosserie mit Schiebetüren und eine Frontpartie im aktuellen Opel-Design mit markanten Scheinwerfern und dem typischen Opel-Grill. Die Front ist im Vergleich zu den PSA-Schwestermodellen eigenständig gestaltet.','Im Jahr 2024 erhielt der Zafira Life ein Facelift. Die auffälligsten Änderungen sind die Einführung des Opel Vizor-Frontdesigns, das die Scheinwerfer und den Kühlergrill zu einer durchgehenden Einheit verbindet. Auch die Stoßfänger wurden neu gestaltet. Im Innenraum gibt es ein neues digitales Cockpit und ein größeres Infotainment-Display.',NULL,NULL,NULL,5,2015,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-arona-erste-generation','Seat','Arona','Erste Generation',2017,NULL,'["SUV", "Crossover"]','Kleinwagen',NULL,'Der Seat Arona (erste Generation) unterscheidet sich vom Vorgänger (falls vorhanden) durch seine markante Frontpartie mit schmalen, scharf gezeichneten Scheinwerfern, einem trapezförmigen Kühlergrill und einer erhöhten Karosseriesilhouette. Die Seitenlinie weist eine dynamische Charakterlinie auf, und das Heck wird von horizontalen Rückleuchten und einer angedeuteten Unterfahrschutzblende geprägt. Er teilt sich die Plattform mit dem Ibiza, ist aber deutlich höher und robuster gestaltet.','Ein Facelift erfolgte im Jahr 2021. Erkennbar ist dies an einer überarbeiteten Front mit neu gestalteten Scheinwerfern und Stoßfängern, einem leicht modifizierten Kühlergrill und neuen Felgendesigns. Am Heck wurden ebenfalls die Stoßfänger angepasst und die Modellbezeichnung auf der Heckklappe im neuen Schriftzug-Design angebracht. Im Innenraum gab es ein neues Infotainmentsystem mit größerem Bildschirm und eine überarbeitete Materialanmutung.',NULL,NULL,NULL,5,2017,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ateca-erste-generation','Seat','Ateca','Erste Generation',2016,NULL,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Seat Ateca zeichnet sich durch eine dynamische Front mit scharf gezeichneten, dreieckigen LED-Scheinwerfern und einem trapezförmigen Kühlergrill aus. Die Seitenlinie ist von prägnanten Charakterlinien geprägt, die dem Fahrzeug eine sportliche Anmutung verleihen. Am Heck fallen die zweigeteilten Rückleuchten auf, die in die Heckklappe hineinragen und eine markante Lichtsignatur bilden. Im Vergleich zu späteren Facelifts oder Nachfolgern (falls vorhanden) fehlen noch die durchgehenden Leuchtbänder oder stärker modifizierte Stoßfänger.','Das Facelift im Jahr 2020 brachte eine überarbeitete Frontpartie mit neuen LED-Scheinwerfern, einem modifizierten Kühlergrill und neu gestalteten Stoßfängern. Am Heck wurden die Rückleuchten leicht angepasst und der Schriftzug ''Ateca'' in einer neuen, handschriftähnlichen Typografie platziert. Im Innenraum gab es ein neues Lenkrad, aktualisierte Infotainmentsysteme und verbesserte Assistenzsysteme.',NULL,NULL,NULL,5,2016,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ibiza-dritte-generation','Seat','Ibiza','Dritte Generation',2002,2008,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kleinwagen','seat-ibiza-zweite-generation','Die dritte Generation des Seat Ibiza (Typ 6L) zeichnet sich durch ein sportlicheres und kantigeres Design aus, das von Walter de Silva entworfen wurde. Im Vergleich zum runderen Vorgänger sind die Scheinwerfer markanter und nach hinten gezogen, die Karosserielinien sind schärfer und dynamischer. Die Frontpartie wirkt aggressiver mit einem größeren, trapezförmigen Kühlergrill und integrierten Nebelscheinwerfern in den unteren Lufteinlässen.','Im Jahr 2006 erfolgte ein Facelift. Die Änderungen waren subtil und umfassten eine leicht modifizierte Frontschürze mit neuen Nebelscheinwerfern, die nun runder waren. Die Heckleuchten erhielten eine leicht überarbeitete Optik, und im Innenraum wurden neue Materialien sowie ein überarbeitetes Kombiinstrument und eine neue Mittelkonsole eingeführt.',NULL,NULL,NULL,4,2002,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ibiza-erste-generation','Seat','Ibiza','Erste Generation',1984,1993,'["Schrägheck"]','Kleinwagen',NULL,'Die erste Generation des Seat Ibiza zeichnet sich durch ihr kantiges, von Giorgio Giugiaro entworfenes Design aus, das oft als ''System Porsche'' beworben wurde. Sie besitzt große, rechteckige Scheinwerfer, einen markanten Kühlergrill mit horizontalen Lamellen und eine insgesamt sehr geradlinige Karosserieform, die sich deutlich von den runderen Nachfolgern abgrenzt.','Im Jahr 1988 erfolgte ein Facelift, das eine überarbeitete Frontpartie mit neuem Kühlergrill und leicht geänderten Scheinwerfern umfasste. Auch die Stoßfänger wurden modifiziert und die Rückleuchten erhielten ein neues Design. Im Innenraum gab es ein neues Armaturenbrett und Lenkrad.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ibiza-fünfte-generation','Seat','Ibiza','Fünfte Generation',2017,NULL,'["5-Türer Schrägheck"]','Kleinwagen','seat-ibiza-vierte-generation','Die fünfte Generation des Seat Ibiza (Typ KJ) ist ausschließlich als Fünftürer erhältlich und basiert auf der MQB A0 Plattform. Sie zeichnet sich durch ein deutlich schärferes und kantigeres Design im Vergleich zum Vorgänger aus. Auffällig sind die markanten, oft dreieckigen LED-Tagfahrlichter in den Scheinwerfern und die breitere, aggressiver gestaltete Frontpartie. Am Heck sind die Leuchten breiter und ebenfalls kantiger geformt, oft mit LED-Technik.','Im Jahr 2021 erfolgte ein Facelift. Die auffälligsten Änderungen umfassen neu gestaltete LED-Scheinwerfer (serienmäßig) und LED-Nebelscheinwerfer, die nun eine andere Lichtsignatur aufweisen. Am Heck wurde der Modellschriftzug in einer neuen Handschrift-Optik platziert, und das Seat-Logo kann bei einigen Ausstattungslinien beleuchtet sein. Im Innenraum wurden das Infotainmentsystem und die Lüftungsdüsen neu gestaltet, wobei die Lüftungsdüsen nun eine markante runde Form erhalten haben.',NULL,NULL,NULL,5,2017,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ibiza-vierte-generation','Seat','Ibiza','Vierte Generation',2008,2017,'["Kleinwagen", "Kombi"]','Kleinwagen','seat-ibiza-dritte-generation','Die vierte Generation des Seat Ibiza zeichnet sich durch das sogenannte ''Arrow Design'' aus, das von Luc Donckerwolke entworfen wurde. Charakteristisch sind die pfeilförmig zulaufende Front mit scharf gezeichneten Scheinwerfern und einem trapezförmigen Kühlergrill. Die Seitenlinie ist dynamisch mit einer aufsteigenden Schulterlinie und einer markanten Sicke unterhalb der Fenster. Im Vergleich zum Vorgänger wirkt er deutlich sportlicher und kantiger.','Das erste Facelift im Jahr 2012 brachte leichte Änderungen an der Front mit sich, darunter neu gestaltete Stoßfänger, ein überarbeiteter Kühlergrill und optional erhältliche Bi-Xenon-Scheinwerfer mit LED-Tagfahrlicht. Auch die Heckleuchten wurden dezent modifiziert. Im Innenraum gab es ein neues Lenkrad und überarbeitete Instrumente. Ein umfassenderes Facelift erfolgte 2015, bei dem die Front erneut überarbeitet wurde, mit einem breiteren Kühlergrill und neuen Nebelscheinwerfern. Die Scheinwerfer erhielten eine neue Lichtsignatur. Im Innenraum wurden das Infotainmentsystem, die Materialien und die Lüftungsdüsen modernisiert.',NULL,NULL,NULL,5,2008,15000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-ibiza-zweite-generation','Seat','Ibiza','Zweite Generation',1993,2002,'["Schrägheck 3-türig", "Schrägheck 5-türig"]','Kleinwagen','seat-ibiza-erste-generation','Die zweite Generation des Ibiza (Typ 6K) zeichnet sich durch eine deutlich rundlichere und aerodynamischere Karosserie im Vergleich zum kantigen Vorgänger aus. Die Frontpartie ist geprägt von schmalen, horizontalen Scheinwerfern und einem kleinen Kühlergrill, der oft in die Motorhaube integriert ist. Die Seitenlinie ist fließender, und die Heckleuchten sind breiter und runder gestaltet als beim ersten Ibiza.','1996 (Modellpflege): Leichte Änderungen an Front- und Heckschürze, neue Scheinwerfer und Rückleuchten, überarbeiteter Innenraum mit neuen Materialien und Armaturenbrett. 1999 (Großes Facelift, oft als ''Ibiza GP01'' bezeichnet): Deutlich überarbeitete Front mit größeren, runderen Scheinwerfern und einem markanteren Kühlergrill. Die Stoßfänger wurden neu gestaltet, und die Heckleuchten erhielten eine modernere Optik. Der Innenraum wurde ebenfalls umfassend erneuert.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-leon-dritte-generation','Seat','Leon','Dritte Generation',2012,2020,'["Schrägheck 3-Türer", "Schrägheck 5-Türer", "Kombi 5-Türer"]','Kompaktklasse','seat-leon-zweite-generation','Die dritte Generation des Seat Leon (Typ 5F) zeichnet sich durch ein deutlich kantigeres und schärferes Design im Vergleich zum runderen Vorgänger aus. Auffällig sind die markanten, pfeilförmigen LED-Tagfahrlichter in den Scheinwerfern (sofern vorhanden) und die prägnante Sicke in der Seitenlinie, die sich von den vorderen Radläufen bis zu den Rückleuchten zieht. Die Front wirkt flacher und breiter, die Heckleuchten sind ebenfalls schmaler und kantiger gestaltet.','Das Facelift (Ende 2016, Modelljahr 2017) brachte eine leicht überarbeitete Frontpartie mit einem breiteren Kühlergrill und neuen Stoßfängern. Die Scheinwerfer erhielten eine neue Lichtsignatur mit Voll-LED-Technik. Am Heck wurden die Stoßfänger und die Innenstruktur der Rückleuchten dezent modifiziert. Im Innenraum gab es ein größeres Infotainment-Display (bis zu 8 Zoll) und neue Assistenzsysteme.',NULL,NULL,NULL,5,2012,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-leon-erste-generation','Seat','Leon','Erste Generation',1999,2006,'["Schräghecklimousine", "Kombi"]','Kompaktklasse','seat-toledo-erste-generation','Die erste Generation des Seat Leon (Typ 1M) basierte auf der Plattform des VW Golf IV. Erkennbar ist sie an den runden Scheinwerfern, der typischen Seat-Linienführung und den im Heck integrierten Türgriffen bei der Schräghecklimousine. Im Vergleich zum Vorgänger Toledo wurde die Karosserie deutlich sportlicher und kompakter gestaltet.','Ein Facelift erfolgte im Jahr 2005. Äußerlich erkennbar an überarbeiteten Scheinwerfern und Rückleuchten, einem modifizierten Kühlergrill und neuen Stoßfängern. Innen gab es Verbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,4,2002,NULL,'24 Monate','Die erste Generation des Seat Leon ist ein sportlich orientierter Kompaktwagen, der auf der Technik des VW Golf IV basiert. Achten Sie beim Kauf auf Rost an Radläufen und Schwellern, defekte Querlenkerlager und ausgeschlagene Spurstangenköpfe. Bei den Benzinmotoren sind die 1.8T-Varianten leistungsstark, aber anfällig für Ölverlust und defekte Zündspulen. Die Dieselmotoren (TDI) sind generell robuster, aber auf die Wartungshistorie achten. Die Kupplung kann bei sportlicher Fahrweise verschleißen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-leon-vierte-generation','Seat','Leon','Vierte Generation',2020,NULL,'["Kompaktwagen", "Kombi"]','Kompaktklasse','seat-leon-dritte-generation','Die vierte Generation des Seat Leon (Baureihe KL) ist an ihrer deutlich schärferen und moderneren Designsprache erkennbar. Auffällig sind die schmalen, pfeilförmigen LED-Scheinwerfer, die eine markante Lichtsignatur aufweisen. Am Heck zieht sich ein durchgehendes LED-Leuchtenband über die gesamte Breite, und der Modellschriftzug ''LEON'' ist in einer geschwungenen Schreibschrift ausgeführt. Im Vergleich zum Vorgänger wirkt die Karosserie gestreckter und dynamischer, mit einer flacheren Frontpartie und einer stärker ausgeprägten Seitenlinie.','Im Mai 2024 wurde ein Facelift vorgestellt, das optisch an einer überarbeiteten Frontschürze mit neuen Lufteinlässen und einem leicht modifizierten Kühlergrill erkennbar ist. Die Scheinwerfer erhielten eine neue interne Grafik mit optionalen Matrix-LED-Einheiten. Am Heck wurden die Leuchten leicht angepasst und die Heckschürze neu gestaltet. Im Innenraum gibt es ein größeres Infotainment-Display (bis zu 12,9 Zoll) und verbesserte Materialien.',NULL,NULL,NULL,5,2020,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-leon-zweite-generation','Seat','Leon','Zweite Generation',2005,2012,'["Schräghecklimousine", "Kombi"]','Kompaktklasse','seat-leon-erste-generation','Die zweite Generation des Seat Leon (Typ 1P) unterscheidet sich deutlich vom Vorgänger. Charakteristisch sind die schärfer gezeichneten Linien, die integrierten Rückleuchten, die sich bis in die Seiten ziehen, und die markante Front mit dem trapezförmigen Kühlergrill. Die hinteren Türgriffe sind wie beim Vorgänger in der C-Säule versteckt.','Im Jahr 2009 erhielt der Seat Leon ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill, neuen Scheinwerfern mit optionalem Tagfahrlicht und modifizierten Rückleuchten. Im Innenraum wurden die Materialien aufgewertet und die Bedienung verbessert.',NULL,NULL,NULL,5,2007,NULL,'2 Jahre','Die zweite Generation des Seat Leon bietet ein gutes Preis-Leistungs-Verhältnis. Achten Sie bei Gebrauchtwagen auf Rost an den Radläufen und der Heckklappe, sowie auf Probleme mit der Klimaanlage und der Elektrik. Die TSI-Motoren können anfällig für Steuerkettenprobleme sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('seat-tarraco-erste-generation','Seat','Tarraco','Erste Generation',2018,NULL,'["SUV"]','Mittelklasse-SUV',NULL,'Der Seat Tarraco der ersten Generation ist das größte SUV von Seat. Er zeichnet sich durch eine markante Frontpartie mit einem breiten, sechseckigen Kühlergrill und schmalen, scharf gezeichneten LED-Scheinwerfern aus. Die Seitenlinie ist kräftig und die Heckpartie wird von einem durchgehenden Leuchtenband dominiert, das die Rückleuchten miteinander verbindet. Im Vergleich zu den kleineren Seat SUVs Ateca und Arona ist der Tarraco deutlich länger und bietet optional sieben Sitze.',NULL,NULL,NULL,NULL,5,2019,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-citigo-erste-generation','Skoda','Citigo','Erste Generation',2011,2020,'["3-Türer", "5-Türer"]','Kleinstwagen',NULL,'Die erste Generation des Skoda Citigo ist eng verwandt mit dem VW Up! und Seat Mii. Sie zeichnet sich durch eine kompakte, kastenförmige Karosserie aus. Die Frontpartie besitzt den typischen Skoda-Kühlergrill mit vertikalen Lamellen und einem Chromrahmen, der in die leicht eckigen Scheinwerfer übergeht. Die Heckleuchten sind vertikal angeordnet und reichen bis in die C-Säule. Im Vergleich zu seinen Konzernbrüdern hat der Citigo eine eigenständige Front- und Heckgestaltung.','Im Jahr 2017 erhielt der Citigo ein Facelift. Die auffälligsten Änderungen waren ein neu gestalteter Kühlergrill, der breiter und markanter wirkte, sowie überarbeitete Stoßfänger vorne und hinten. Die Nebelscheinwerfer wurden neu positioniert und die Scheinwerfer erhielten optional integriertes LED-Tagfahrlicht. Am Heck gab es leichte Anpassungen an den Rückleuchten und dem Stoßfänger.',NULL,NULL,NULL,5,2011,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-enyaq-erste-generation','Skoda','Enyaq','Erste Generation',2020,NULL,'["SUV", "Crossover"]','Kompakt-SUV',NULL,'Die erste Generation des Skoda Enyaq zeichnet sich durch ein eigenständiges, modernes Elektro-SUV-Design aus. Typische Merkmale sind die geschlossene Frontpartie, die optional als beleuchtetes ''Crystal Face'' ausgeführt ist, die markanten, zweigeteilten LED-Scheinwerfer (obere Tagfahrlichtleiste, darunter die Hauptscheinwerfer) und die Skoda-typischen C-förmigen LED-Rückleuchten. Im Vergleich zu Verbrenner-SUVs von Skoda wirkt die Front flacher und aerodynamischer.',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-fabia-dritte-generation','Skoda','Fabia','Dritte Generation',2014,2021,'["Schrägheck", "Kombi"]','Kleinwagen','skoda-fabia-zweite-generation','Die dritte Generation des Skoda Fabia (Typ NJ) zeichnet sich durch ein deutlich schärferes und kantigeres Design im Vergleich zum runderen Vorgänger aus. Auffällig sind die breiteren, eckigeren Scheinwerfer, die oft mit LED-Tagfahrlicht ausgestattet sind und direkt an den Kühlergrill anschließen. Der Kühlergrill selbst ist breiter und flacher. Die Karosserie wirkt insgesamt sportlicher und dynamischer, mit prägnanten Sicken in den Seitenlinien und einer flacheren Dachlinie. Die Heckleuchten sind ebenfalls eckiger und breiter gestaltet.','Im Jahr 2018 erhielt der Fabia III ein Facelift. Die auffälligsten Änderungen umfassten neu gestaltete Front- und Heckschürzen, überarbeitete Scheinwerfer (optional erstmals mit Voll-LED-Technik) und Rückleuchten (ebenfalls optional mit LED-Technik). Der Kühlergrill wurde leicht modifiziert. Im Innenraum gab es neue Dekorleisten und Sitzbezüge sowie erweiterte Konnektivitäts- und Assistenzsysteme.',NULL,NULL,NULL,5,2014,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-fabia-erste-generation','Skoda','Fabia','Erste Generation',1999,2007,'["Schrägheck", "Kombi", "Stufenheck"]','Kleinwagen','skoda-felicia','Die erste Generation des Skoda Fabia zeichnet sich durch ein rundliches, aber dennoch klares Design aus. Die Front ist geprägt von großen, leicht mandelförmigen Scheinwerfern, die in die Kotflügel hineinragen, und einem schmalen Kühlergrill mit dem Skoda-Logo. Die Motorhaube fällt sanft ab. Die Seitenlinie ist eher schlicht, mit einer deutlichen Sicke unterhalb der Fensterlinie. Im Vergleich zum Vorgänger Felicia wirkt der Fabia deutlich moderner, runder und weniger kantig.','Im Jahr 2004 erfolgte ein Facelift. Die markantesten Änderungen waren leicht modifizierte Scheinwerfer mit integrierten Blinkern (zuvor separat), ein neu gestalteter Kühlergrill mit einer breiteren Chromleiste und ein überarbeiteter Stoßfänger vorne. Am Heck wurden die Rückleuchten leicht abgedunkelt und die Form der Stoßfänger angepasst. Im Innenraum gab es neue Materialien und Farben sowie ein überarbeitetes Kombiinstrument.',NULL,NULL,NULL,4,2000,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-fabia-zweite-generation','Skoda','Fabia','Zweite Generation',2007,2014,'["Kombi", "Schrägheck"]','Kleinwagen','skoda-fabia-erste-generation','Die zweite Generation des Skoda Fabia ist im Vergleich zum Vorgänger deutlich höher und rundlicher gestaltet. Die Front zeichnet sich durch größere, mandelförmige Scheinwerfer aus, die weiter in die Kotflügel reichen, und einen markanteren Kühlergrill mit vertikalen Lamellen. Die Dachlinie ist im Schrägheck-Modell stärker gewölbt, was an den Roomster erinnert. Die Heckleuchten sind ebenfalls größer und ragen weiter in die Seitenflanken hinein.','Im Jahr 2010 erhielt der Fabia ein Facelift. Die Front wurde überarbeitet mit einem breiteren Kühlergrill, der nun horizontalere Lamellen aufweist, und neu gestalteten Nebelscheinwerfern. Die Scheinwerfer erhielten eine leicht veränderte Innenstruktur. Auch die Stoßfänger vorne und hinten wurden modifiziert. Im Innenraum gab es neue Lenkräder und überarbeitete Materialien.',NULL,NULL,NULL,5,2007,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-kamiq-erste-generation','Skoda','Kamiq','Erste Generation',2018,NULL,'["SUV", "Crossover"]','Kleinwagen',NULL,'Der Skoda Kamiq der ersten Generation unterscheidet sich von seinen Vorgängern durch seine markante, zweigeteilte Scheinwerfer-Signatur mit schmalen Tagfahrlichtern oben und den Hauptscheinwerfern darunter. Die Skoda-typische, breite und kantige Kühlerniere ist ebenfalls ein charakteristisches Merkmal. Die Karosserieform ist die eines kompakten Crossovers mit erhöhter Sitzposition und robuster Anmutung.',NULL,NULL,NULL,NULL,5,2021,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-karoq-erste-generation','Skoda','Karoq','Erste Generation',2017,NULL,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Skoda Karoq, eingeführt 2017, zeichnet sich durch das typische Skoda-Design mit scharfen Linien, geteilten Scheinwerfern (obere Tagfahrlichter, untere Hauptscheinwerfer) und dem markanten Skoda-Kühlergrill aus. Die Heckleuchten sind oft C-förmig gestaltet. Im Vergleich zu seinem Vorgänger, dem Skoda Yeti, ist der Karoq deutlich konventioneller und moderner im Design.','Das Facelift erfolgte 2021. Erkennbar an einer überarbeiteten Front mit schmaleren Scheinwerfern, einem breiteren Kühlergrill und einer neu gestalteten Frontschürze. Am Heck wurden die Rückleuchten modifiziert und die Stoßfänger angepasst. Im Innenraum gab es ein neues digitales Cockpit und aktualisierte Infotainmentsysteme.',NULL,NULL,NULL,5,2017,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-kodiaq-erste-generation','Skoda','Kodiaq','Erste Generation',2016,2023,'["SUV"]','Mittelklasse-SUV',NULL,'Die erste Generation des Skoda Kodiaq zeichnet sich durch ihre markanten, zweigeteilten Frontscheinwerfer aus, bei denen die oberen schmalen LED-Tagfahrlichter über den darunterliegenden Hauptscheinwerfern positioniert sind. Der breite, aufrecht stehende Kühlergrill mit vertikalen Lamellen ist ein weiteres prägnantes Merkmal. Die Karosserie weist scharfe, präzise Linien und eine kantige Formgebung auf, insbesondere an den Radläufen und der Schulterlinie, was ihn von der runderen und moderneren Designsprache des Nachfolgers abgrenzt.','Das Facelift im Jahr 2021 brachte eine überarbeitete Frontpartie mit einem neu gestalteten, sechseckigen Kühlergrill, der aufrechter steht und breiter wirkt. Die Scheinwerfer wurden schlanker und erhielten eine neue LED-Matrix-Technologie als Option. Die Frontschürze wurde ebenfalls modifiziert, mit neuen Lufteinlässen und einer geänderten Nebelscheinwerferposition. Am Heck gab es dezente Änderungen an den Rückleuchten, die nun eine schärfere Grafik aufweisen, sowie eine neu gestaltete Heckschürze. Im Innenraum wurden neue Dekorleisten und verbesserte Infotainment-Systeme eingeführt.',NULL,NULL,NULL,5,2017,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-octavia-dritte-generation','Skoda','Octavia','Dritte Generation',2012,2020,'["Limousine", "Kombi"]','Kompaktklasse','skoda-octavia-zweite-generation','Die dritte Generation des Skoda Octavia (Typ 5E) zeichnet sich durch ein schärferes, kantigeres Design aus. Auffällig sind die geraden Linien und die prägnanten, rechteckigen Scheinwerfer, die nicht mehr so rundlich wie beim Vorgänger sind. Die Motorhaube weist eine deutliche V-förmige Sicke auf, die in den Kühlergrill mündet. Am Heck sind die C-förmigen Rückleuchten breiter und flacher gestaltet.','Das Facelift im Jahr 2017 brachte die auffälligste Änderung in Form von geteilten Frontscheinwerfern, die dem Fahrzeug ein markantes Vier-Augen-Gesicht verliehen. Zudem wurden der Kühlergrill und die Stoßfänger leicht überarbeitet. Im Innenraum gab es neue Infotainmentsysteme mit größeren Bildschirmen und leicht modifizierte Dekorleisten.',NULL,NULL,NULL,5,2013,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-octavia-erste-generation','Skoda','Octavia','Erste Generation',1996,2010,'["Limousine", "Kombi"]','Kompaktklasse',NULL,'Die erste Generation des Skoda Octavia (intern Typ 1U) wurde 1996 eingeführt. Sie teilt sich die Plattform mit dem VW Golf IV. Charakteristisch sind die relativ einfache, aber solide Karosserieform, die typische Skoda-Kühlergrill-Gestaltung der damaligen Zeit und die im Vergleich zum Golf IV längere Karosserie, was zu einem größeren Kofferraumvolumen führt. Die Scheinwerfer sind meist rechteckig und die Rückleuchten eher klassisch geformt.','Die erste Generation erhielt 2000 ein Facelift. Äußerlich erkennbar an überarbeiteten Scheinwerfern und Rückleuchten, einer modifizierten Frontschürze und einem leicht geänderten Kühlergrill. Im Innenraum gab es ebenfalls Detailverbesserungen bei Materialien und Ausstattung.',NULL,NULL,NULL,3,2001,NULL,'2 Jahre','Die erste Generation des Skoda Octavia ist bekannt für ihre Robustheit und das gute Preis-Leistungs-Verhältnis. Achten Sie beim Kauf auf Rost, insbesondere an Radläufen, Schwellern und der Heckklappe. Bei älteren Modellen können auch Fahrwerksteile und die Auspuffanlage verschleißanfällig sein. Die Motoren sind meist solide, aber regelmäßige Wartung ist entscheidend.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-octavia-zweite-generation','Skoda','Octavia','Zweite Generation',2004,2013,'["Limousine", "Kombi"]','Kompaktklasse','skoda-octavia-erste-generation','Die zweite Generation des Skoda Octavia unterscheidet sich vom Vorgänger durch deutlich größere, eckigere Scheinwerfer, die weiter in die Kotflügel reichen. Der Kühlergrill ist breiter und markanter, mit dem Skoda-Logo auf der Motorhaube. Am Heck sind die Rückleuchten breiter und reichen weiter in die Heckklappe hinein, während die Seitenlinie eine modernere, fließendere Form aufweist.','Das Facelift im Jahr 2008 brachte eine überarbeitete Frontpartie mit neuen, größeren und runderen Scheinwerfern, die nun eine leicht geschwungene Unterkante aufweisen. Der Kühlergrill wurde ebenfalls neu gestaltet und erhielt eine breitere Chromumrandung. Die Nebelscheinwerfer wurden eckiger. Am Heck wurden die Rückleuchten leicht modifiziert und erhielten eine neue Grafik. Im Innenraum gab es ein neues Lenkrad und überarbeitete Bedienelemente.',NULL,NULL,NULL,5,2004,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-scala-erste-generation','Skoda','Scala','Erste Generation',2019,NULL,'["Schräghecklimousine"]','Kompaktklasse',NULL,'Die erste Generation des Skoda Scala löste den Skoda Rapid (Spaceback) ab. Charakteristisch sind die scharfen Linien, die markante Skoda-Front mit dem breiten Kühlergrill und die optionalen Voll-LED-Scheinwerfer. Am Heck fallen die schmalen Rückleuchten und der Schriftzug ''SKODA'' anstelle des Logos auf.',NULL,NULL,NULL,NULL,5,2019,NULL,'24 Monate','Der Skoda Scala bietet viel Platz für seine Klasse und ein gutes Preis-Leistungs-Verhältnis. Achten Sie bei Gebrauchtwagen auf die Wartungshistorie und mögliche Roststellen an Radläufen und Schwellern.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-superb-dritte-generation','Skoda','Superb','Dritte Generation',2015,2023,'["Limousine", "Kombi"]','Mittelklasse','skoda-superb-zweite-generation','Die dritte Generation des Skoda Superb zeichnet sich durch eine deutlich schärfere und präzisere Linienführung aus, die ihn kantiger und dynamischer als seinen Vorgänger erscheinen lässt. Die Front ist breiter und flacher, mit schmalen, oft LED-bestückten Scheinwerfern, die eine markante C-förmige Tagfahrlichtsignatur aufweisen können. Die Skoda-Niere ist ebenfalls breiter und flacher. Am Heck fallen die schmaleren Rückleuchten auf, die sich weiter in die Heckklappe ziehen und ebenfalls eine C-förmige LED-Signatur zeigen. Der längere Radstand und die kürzeren Überhänge tragen zu den gestreckteren Proportionen bei.','Das Facelift im Jahr 2019 brachte eine überarbeitete Frontschürze mit einem breiteren Kühlergrill und einer Chromleiste zwischen den Nebelscheinwerfern. Die Scheinwerfer wurden optional mit Matrix-LED-Technologie angeboten. Am Heck wurde der Skoda-Schriftzug anstelle des Logos auf der Heckklappe platziert, und die Rückleuchten erhielten eine neue Grafik mit dynamischen Blinkern. Zudem wurden neue Leichtmetallräder und Lackfarben eingeführt.',NULL,NULL,NULL,5,2015,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-superb-erste-generation','Skoda','Superb','Erste Generation',2001,2008,'["Limousine"]','Obere Mittelklasse',NULL,'Die erste Generation des Skoda Superb basiert auf der verlängerten Plattform des VW Passat B5. Sie zeichnet sich durch eine klassische Stufenheck-Limousinenform aus, mit einer markanten, leicht abgerundeten Frontpartie, die von großen, rechteckigen Scheinwerfern und dem typischen Skoda-Kühlergrill mit vertikalen Lamellen dominiert wird. Die Seitenlinie ist elegant und unaufgeregt, das Heck wirkt solide und konservativ.','Im Jahr 2006 erfolgte ein Facelift. Die Front erhielt einen neu gestalteten Kühlergrill mit Chromrahmen und vertikalen Streben, sowie Klarglas-Scheinwerfer. Am Heck wurden die Rückleuchten leicht modifiziert und eine Chromleiste auf der Kofferraumklappe hinzugefügt. Im Innenraum gab es kleinere Änderungen an Materialien und Dekorelementen.',NULL,NULL,NULL,NULL,NULL,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('skoda-superb-zweite-generation','Skoda','Superb','Zweite Generation',2008,2015,'["Limousine", "Kombi"]','Obere Mittelklasse','skoda-superb-erste-generation','Die zweite Generation des Skoda Superb ist an ihrem deutlich moderneren und runderen Design im Vergleich zum Vorgänger erkennbar. Die Limousine zeichnet sich durch die einzigartige TwinDoor-Heckklappe aus, die wahlweise nur den Kofferraumdeckel oder die gesamte Heckklappe öffnet. Die Frontpartie besitzt einen breiteren Kühlergrill und geschwungene Scheinwerfer, die weit in die Kotflügel reichen. Die Heckleuchten sind breiter und reichen in die Heckklappe hinein. Der Superb II basiert auf der VW PQ46 Plattform.','Das Facelift im Jahr 2013 brachte neue Frontscheinwerfer (optional mit integriertem LED-Tagfahrlicht), einen überarbeiteten Kühlergrill und Stoßfänger sowie neue Nebelscheinwerfer. Am Heck wurden die Leuchten neu gestaltet und erhielten eine C-förmige LED-Lichtsignatur. Im Innenraum gab es kleinere Änderungen am Lenkrad und den Zierleisten.',NULL,NULL,NULL,5,2008,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-aygo-i','Toyota','Aygo','I',2005,2014,'["Kleinwagen", "Schräghecklimousine"]','A',NULL,'Der Toyota Aygo der ersten Generation (X10) wurde gemeinsam mit dem Peugeot 107 und dem Citroën C1 entwickelt. Erkennbar ist er an seinen charakteristischen, runden Scheinwerfern, der markanten, nach unten geöffneten Trapez-Kühlergrill-Öffnung und der leicht nach hinten abfallenden Dachlinie. Die Heckleuchten sind vertikal in die Heckklappe integriert.','Im Jahr 2008 erhielt der Aygo ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontschürze mit neu gestalteten Nebelscheinwerfer-Einfassungen, einem leicht modifizierten Kühlergrill und neuen Rückleuchten mit Klarglas-Elementen. Im Innenraum gab es Anpassungen bei Materialien und der Mittelkonsole.',NULL,NULL,NULL,4,2005,NULL,'24 Monate','Der Toyota Aygo I ist ein beliebtes Stadtauto, das vor allem durch seine Wendigkeit und niedrigen Betriebskosten besticht. Achten Sie beim Kauf auf Rost an den Radläufen und Schwellern, insbesondere bei Fahrzeugen, die viel im Winter gefahren wurden. Die Kupplung kann bei hoher Laufleistung verschleißen. Die Klimaanlage sollte auf Funktion geprüft werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-aygo-ii','Toyota','Aygo','II',2014,2021,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kleinstwagen','toyota-aygo-i','Die zweite Generation des Toyota Aygo ist sofort an ihrer markanten X-förmigen Frontpartie erkennbar, die sich von den Scheinwerfern bis zum unteren Kühlergrill erstreckt. Die Scheinwerfer sind schmaler und spitzer zulaufend als beim Vorgänger, und die Rückleuchten sind vertikal angeordnet und reichen bis in die Heckklappe hinein, was dem Fahrzeug ein moderneres und dynamischeres Aussehen verleiht.','Im Jahr 2018 erhielt der Aygo II ein Facelift. Die X-förmige Front wurde überarbeitet, wobei die X-Grafik nun dreidimensionaler wirkte und die Scheinwerfer eine neue LED-Lichtsignatur erhielten. Die Rückleuchten wurden ebenfalls leicht modifiziert und erhielten eine neue LED-Grafik. Zudem gab es neue Felgendesigns und Farben.',NULL,NULL,NULL,4,2014,15000,'alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-bz4x-erste-generation','Toyota','bZ4X','Erste Generation',2022,NULL,'["SUV"]','Kompakt-SUV',NULL,'Der Toyota bZ4X ist das erste rein elektrische SUV von Toyota. Er zeichnet sich durch ein futuristisches Design mit einer markanten Frontpartie, schmalen LED-Scheinwerfern und einer aerodynamischen Silhouette aus. Die Heckpartie wird von einem durchgehenden Leuchtenband dominiert.',NULL,NULL,NULL,NULL,5,2022,NULL,'','Der Toyota bZ4X ist eine gute Wahl für Käufer, die ein geräumiges und komfortables Elektro-SUV mit guter Reichweite suchen. Die Ladeinfrastruktur und die Verfügbarkeit von Schnellladestationen sollten vor dem Kauf geprüft werden.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-c-hr-i','Toyota','C-HR','I',2016,2023,'["SUV", "Crossover"]','Kompakt-SUV',NULL,'Der Toyota C-HR der ersten Generation (X10) zeichnet sich durch sein markantes, coupéartiges Design mit einer stark abfallenden Dachlinie und einer auffälligen C-Säulen-Gestaltung aus. Die Scheinwerfer sind schmal und ziehen sich weit in die Kotflügel. Die Rückleuchten sind durch ein schwarzes Band verbunden und ragen weit in die Seite. Im Vergleich zu traditionellen SUVs wirkt er deutlich sportlicher und weniger kastenförmig.','Das Facelift im Jahr 2019 brachte eine überarbeitete Frontpartie mit modifizierten Scheinwerfern und Stoßfängern. Auch die Rückleuchten wurden leicht angepasst und die Rückfahrscheinwerfer in die Hauptleuchten integriert. Im Innenraum gab es Aktualisierungen bei Infotainment und Konnektivität sowie neue Materialien.',NULL,NULL,NULL,5,2017,NULL,'2 Jahre','Der Toyota C-HR I ist bekannt für sein auffälliges Design und seine Zuverlässigkeit. Achten Sie beim Kauf auf den Zustand des Innenraums, insbesondere bei den oft beanspruchten Sitzen und dem Infotainmentsystem. Regelmäßige Wartung ist wichtig, um die Langlebigkeit des Hybridantriebs zu gewährleisten. Rost an den Radläufen oder Schwellern kann bei älteren Modellen ein Thema sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-c-hr-ii','Toyota','C-HR','II',2023,NULL,'["SUV", "Crossover"]','Kompakt-SUV','toyota-c-hr-i','Deutlich überarbeitetes Design mit schärferen Linien, markanterer Frontpartie mit schmaleren Scheinwerfern und einem durchgehenden LED-Leuchtenband am Heck. Die Dachlinie ist coupéhafter und die Seitenlinie dynamischer gestaltet als beim Vorgänger.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv10','Toyota','Camry','XV10',1991,1996,'["Limousine", "Kombi"]','Obere Mittelklasse','toyota-camry-v20','Die XV10-Generation zeichnet sich durch ein deutlich runderes und aerodynamischeres Design im Vergleich zum kantigeren Vorgänger V20 aus. Die Frontpartie ist flacher und breiter, oft mit einem horizontalen Lamellengrill und integrierten, geschwungenen Scheinwerfern. Die Heckleuchten sind breiter und ziehen sich um die Karosserie herum, teilweise in die Kofferraumklappe hinein. Die Karosserie wirkt insgesamt massiver und weniger filigran als die des V20.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv20','Toyota','Camry','XV20',1996,2001,'["Limousine", "Kombi"]','Mittelklasse','toyota-camry-xv10','Die XV20-Generation unterscheidet sich von ihrem Vorgänger durch eine rundere, aerodynamischere Karosserieform. Die Scheinwerfer sind größer und integrierter in die Frontpartie, die Heckleuchten sind breiter und horizontaler ausgerichtet. Die Seitenlinie wirkt fließender.','Ein Facelift fand im Jahr 1998 statt. Äußerlich erkennbar an leicht überarbeiteten Front- und Heckstoßfängern, neuen Felgendesigns und modifizierten Rückleuchten mit klareren Gläsern. Im Innenraum gab es kleinere Änderungen an der Mittelkonsole und der Materialanmutung.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv30','Toyota','Camry','XV30',2001,2006,'["Limousine"]','D-Segment','toyota-camry-xv20','Die XV30-Generation unterscheidet sich von ihrem Vorgänger durch eine deutlich rundere und stromlinienförmigere Karosserieform. Die Scheinwerfer sind größer und integrieren sich stärker in die Frontpartie, während die Heckleuchten eine horizontale Ausrichtung aufweisen und über die gesamte Breite des Hecks reichen. Die Seitenlinie wirkt insgesamt weicher und weniger kantig.','Ein Facelift erfolgte im Jahr 2004. Äußerlich erkennbar an einer überarbeiteten Frontschürze, neuen Scheinwerfer- und Rückleuchtengrafiken sowie modifizierten Felgendesigns. Im Innenraum gab es Anpassungen an der Mittelkonsole und der Materialauswahl.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv40','Toyota','Camry','XV40',2006,2011,'["Limousine"]','Obere Mittelklasse','toyota-camry-xv30','Der Camry XV40 zeichnet sich durch seine glatten, fließenden Linien und eine insgesamt rundlichere Form im Vergleich zum Vorgänger XV30 aus. Die Scheinwerfer sind größer und geschwungener, ziehen sich weit in die Kotflügel und sind nicht mehr so eckig wie beim XV30. Der Kühlergrill ist breiter und integriert sich harmonischer in die Frontpartie. Die Heckleuchten sind ebenfalls größer und horizontaler ausgerichtet, oft mit einem Chromstreifen, der sie verbindet.','Im Jahr 2009 erhielt der Camry XV40 ein leichtes Facelift. Die Änderungen umfassten einen neu gestalteten Kühlergrill mit feineren Lamellen, leicht modifizierte Frontstoßfänger mit neuen Nebelscheinwerfer-Einfassungen und überarbeitete Heckleuchten, die eine klarere Optik aufwiesen. Im Innenraum gab es kleinere Anpassungen an den Materialien und der Ausstattung.',NULL,NULL,NULL,NULL,NULL,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv50','Toyota','Camry','XV50',2011,2017,'["Limousine"]','Obere Mittelklasse','toyota-camry-xv40','Die XV50-Generation unterscheidet sich von ihrem Vorgänger durch eine deutlich schärfere und aerodynamischere Linienführung. Auffällig sind die schmaleren, nach hinten gezogenen Scheinwerfer, der trapezförmige Kühlergrill und die markanteren Sicken in der Motorhaube. Das Heck zeigt ebenfalls eine modernere Gestaltung mit horizontal ausgerichteten Rückleuchten.','Im Jahr 2014 erhielt der Camry ein Facelift. Äußerlich erkennbar an einem überarbeiteten Kühlergrill mit horizontalen Streben, modifizierten Scheinwerfern und Rückleuchten sowie neuen Stoßfängern. Im Innenraum wurden das Infotainmentsystem und die Materialien aufgewertet.',NULL,NULL,NULL,5,2011,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-camry-xv70','Toyota','Camry','XV70',2019,2024,'["Limousine"]','Obere Mittelklasse','toyota-camry-xv50','Der Camry XV70 zeichnet sich durch ein deutlich dynamischeres und schärferes Design im Vergleich zu früheren Generationen aus. Auffällig sind die schmalen, aggressiv gezeichneten LED-Scheinwerfer, der große, trapezförmige Kühlergrill, der sich bis in die Stoßstange zieht, und die markanten Sicken in den Seitenflanken. Die Dachlinie fällt coupéartig nach hinten ab, und die Heckleuchten sind schlank und horizontal ausgerichtet.','Das Facelift (Modelljahr 2021, Einführung in Europa Ende 2020) brachte subtile Änderungen: Der untere Kühlergrill erhielt eine neue, elegantere Struktur mit horizontalen Lamellen. Die Einfassungen der Nebelscheinwerfer wurden leicht überarbeitet. Im Innenraum wurde ein neues, freistehendes 9-Zoll-Infotainment-Display eingeführt, das höher auf dem Armaturenbrett positioniert ist. Zudem wurden erweiterte Sicherheitsfunktionen (Toyota Safety Sense 2.5+) integriert.',NULL,NULL,NULL,5,2017,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-corolla-ix','Toyota','Corolla','IX',2001,2007,'["Limousine", "Kombi", "Schrägheck"]','Kompaktklasse','toyota-corolla-viii','Die neunte Generation des Toyota Corolla (E130) unterscheidet sich deutlich von seinem Vorgänger. Auffällig sind die moderneren, abgerundeten Linien, die größeren Scheinwerfer, die sich weiter in die Kotflügel ziehen, und die neu gestaltete Frontpartie mit einem größeren Kühlergrill. Das Heck zeigt ebenfalls eine überarbeitete Form der Rückleuchten und Stoßfänger.','Ein Facelift fand im Jahr 2004 statt. Äußerlich erkennbar an leicht modifizierten Scheinwerfern und Rückleuchten, einem überarbeiteten Kühlergrill und neuen Stoßfängern. Im Innenraum gab es Anpassungen bei Materialien und der Mittelkonsole.',NULL,NULL,NULL,4,2004,NULL,'24 Monate','Der Toyota Corolla IX gilt als sehr zuverlässiges Fahrzeug mit geringen Pannenstatistiken. Achten Sie auf Rost an den Radläufen und Schwellern, insbesondere bei älteren Modellen. Die Motoren sind robust, aber regelmäßige Wartung ist wichtig. Die Ersatzteilversorgung ist gut.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-corolla-x','Toyota','Corolla','X',2007,2012,'["Schrägheck", "Kombi"]','Kompaktklasse','toyota-corolla-ix','Die zehnte Generation des Toyota Corolla (E150, in Europa primär als Schrägheck und Kombi angeboten) zeichnet sich durch eine deutlich rundlichere und fließendere Karosserieform im Vergleich zum kantigeren Vorgänger aus. Auffällig sind die großen, mandelförmigen Scheinwerfer, die weit in die Kotflügel reichen, sowie der breite, trapezförmige Kühlergrill, der von einer Chromleiste eingefasst sein kann. Die Seitenlinie ist glatter, und die Heckleuchten sind horizontal angeordnet und reichen in die Heckklappe hinein.','Im Jahr 2010 erfolgte ein Facelift. Die Frontpartie erhielt einen überarbeiteten Stoßfänger mit integrierten Nebelscheinwerfern und einem leicht modifizierten Kühlergrill. Die Scheinwerfer wurden dezent überarbeitet, und die Heckleuchten erhielten eine neue Grafik. Im Innenraum gab es kleinere Änderungen an Materialien und Farben sowie eine überarbeitete Instrumentenbeleuchtung.',NULL,NULL,NULL,5,2007,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-corolla-xi','Toyota','Corolla','XI',2013,2019,'["Limousine", "Kombi", "Schrägheck"]','C-Segment','toyota-corolla-x','Die elfte Generation (E170/E180) des Toyota Corolla unterscheidet sich von seinem Vorgänger durch eine deutlich modernere und schärfere Designsprache. Auffällig sind die schmaleren, nach innen gezogenen Scheinwerfer, die oft mit LED-Tagfahrlicht ausgestattet sind, sowie der markantere und breitere Kühlergrill, der in die Scheinwerfer übergeht. Die Heckleuchten sind ebenfalls neu gestaltet und oft horizontaler ausgerichtet. Die Karosserielinien wirken dynamischer und weniger rundlich als beim Vorgänger.','Das Facelift im Jahr 2016 brachte eine überarbeitete Frontpartie mit neu gestalteten Scheinwerfern, Stoßfängern und Kühlergrill. Am Heck wurden die Rückleuchten modifiziert. Im Innenraum gab es Verbesserungen bei Materialien und Infotainmentsystem.',NULL,NULL,NULL,5,2013,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-corolla-xii','Toyota','Corolla','XII',2018,NULL,'["Limousine", "Kombi", "Schrägheck"]','Kompaktklasse','toyota-auris-ii','Die zwölfte Generation des Toyota Corolla (E210) zeichnet sich durch ein deutlich dynamischeres Design aus. Auffällig sind die schmalen, scharf gezeichneten LED-Scheinwerfer, die in eine breite, V-förmige Front integriert sind. Der Kühlergrill ist groß und trapezförmig. Die Seitenlinie ist fließender als beim Vorgänger Auris, und die Heckleuchten sind schlank und ziehen sich weit in die Seitenflanken. Die Limousine hat ein klassisches Stufenheck, während der Kombi (Touring Sports) eine sportlichere Dachlinie aufweist.','Im Jahr 2022 erfolgte ein Facelift. Die optischen Änderungen sind subtil und umfassen eine leicht überarbeitete Frontschürze mit neuen Gittermustern, neue LED-Grafiken für die Scheinwerfer und Rückleuchten sowie neue Felgendesigns. Im Innenraum wurden das Infotainmentsystem und die digitalen Instrumente modernisiert. Die Hybridantriebe erhielten Leistungssteigerungen und Effizienzverbesserungen.',NULL,NULL,NULL,5,2019,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-achte-generation','Toyota','Hilux','Achte Generation',2015,NULL,'["Pickup"]','Pick-up','toyota-hilux-siebte-generation','Die achte Generation des Toyota Hilux zeichnet sich durch eine deutlich modernere und robustere Designsprache aus. Auffällig ist die prominente, trapezförmige Frontpartie mit einem großen, oft verchromten Kühlergrill, der von schlankeren, nach hinten gezogenen Scheinwerfern flankiert wird, die häufig LED-Tagfahrlicht integrieren. Im Vergleich zum Vorgänger wirkt die Karosserie muskulöser und skulpturaler, mit ausgeprägteren Radhäusern und einer insgesamt schärferen Linienführung. Die Seitenansicht zeigt eine höhere Gürtellinie und eine stärkere Präsenz.','Das erste Facelift (ab 2017/2018) brachte leichte Änderungen an der Frontpartie, insbesondere einen überarbeiteten Kühlergrill und Stoßfänger, um das Design frischer zu gestalten. Das zweite, größere Facelift (ab 2020) führte eine komplett neu gestaltete Front ein, mit einem noch massiveren, sechseckigen Kühlergrill, der von neuen, schmaleren LED-Scheinwerfern mit markanter Lichtsignatur eingerahmt wird. Auch die Nebelscheinwerfer und der untere Lufteinlass wurden überarbeitet. Im Innenraum gab es ein neues Infotainmentsystem mit größerem Touchscreen und verbesserter Konnektivität. Ein weiteres Update (ab 2023) brachte leichte optische Anpassungen und die Einführung eines Mild-Hybrid-Antriebs.',NULL,NULL,NULL,5,2016,15000,'2 Jahre (Erstzulassung: 3 Jahre)',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-dritte-generation','Toyota','Hilux','Dritte Generation',1978,1983,'["Pickup"]','Kleintransporter/Pickup','toyota-hilux-zweite-generation','Die dritte Generation des Toyota Hilux (intern als N30/N40 bezeichnet) unterscheidet sich von seinem Vorgänger durch eine kantigere Karosserieform, eine überarbeitete Frontpartie mit rechteckigen Scheinwerfern und eine breitere Spur. Die Ladefläche wurde ebenfalls leicht modifiziert.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-erste-generation','Toyota','Hilux','Erste Generation',1968,1978,'["Pickup"]','Nutzfahrzeug',NULL,'Die erste Generation des Toyota Hilux, auch bekannt als RN20, zeichnet sich durch sein einfaches, robustes Design aus. Charakteristisch sind die runden Scheinwerfer, ein schlicht gehaltener Kühlergrill und eine kastenförmige Karosserie mit deutlichen Längslinien. Die Ladefläche ist offen und typisch für einen Pickup dieser Ära.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','Die erste Generation des Toyota Hilux ist ein robustes Nutzfahrzeug, das für seine Langlebigkeit bekannt ist. Bei der Suche nach einem Exemplar sollte auf Rost an Fahrwerk, Ladefläche und Karosserie geachtet werden. Die Mechanik ist relativ einfach, was Reparaturen erleichtert, aber Ersatzteile können rar sein. Originalzustand und nachvollziehbare Historie sind wichtige Kriterien.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-fünfte-generation','Toyota','Hilux','Fünfte Generation',1988,1997,'["Single Cab", "Xtra Cab", "Double Cab"]','Pick-up','toyota-hilux-vierte-generation','Die fünfte Generation des Hilux zeichnet sich durch eine deutlich rundere und aerodynamischere Karosserie im Vergleich zum kantigen Vorgänger aus. Die Frontpartie integriert Scheinwerfer und Kühlergrill fließender, oft mit breiteren, rechteckigen Scheinwerfern. Die Kabine wirkt insgesamt moderner und weniger utilitaristisch.','Ein Facelift erfolgte um 1991/1992. Dabei wurden der Kühlergrill und die Scheinwerfer leicht überarbeitet, oft mit einem Wechsel zu klareren, integrierten Scheinwerfereinheiten und einem modifizierten Stoßfängerdesign. Auch im Innenraum gab es kleinere Aktualisierungen.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-sechste-generation','Toyota','Hilux','Sechste Generation',1997,2005,'["Single Cab", "Extra Cab", "Double Cab"]','Pick-up','toyota-hilux-fuenfte-generation','Die sechste Generation des Hilux zeichnet sich durch eine rundlichere, weniger kantige Karosserie im Vergleich zum Vorgänger aus. Die Frontpartie ist geprägt von größeren, abgerundeten Scheinwerfern, die in die Kotflügel übergehen, und einem breiteren Kühlergrill mit horizontalen Lamellen. Die Stoßfänger sind integrierter und weniger hervorstehend als bei der fünften Generation. Die Kabine wirkt insgesamt moderner und aerodynamischer.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-siebte-generation','Toyota','Hilux','Siebte Generation',2005,2015,'["Pick-up Single Cab", "Pick-up Extra Cab", "Pick-up Double Cab"]','Pick-up','toyota-hilux-sechste-generation','Die siebte Generation des Toyota Hilux (AN10/AN20/AN30) zeichnet sich durch ein deutlich moderneres und runderes Design im Vergleich zum kantigen Vorgänger aus. Die Scheinwerfer sind größer und stärker in die Front integriert, die Karosserielinien sind fließender. Das Interieur wurde ebenfalls komplett überarbeitet und wirkt weniger rustikal, mit einer Pkw-ähnlicheren Armaturentafel.','Der Hilux der siebten Generation erhielt zwei größere Facelifts. Das erste Facelift im Jahr 2008 brachte leichte Änderungen an Kühlergrill und Stoßfängern. Das zweite, umfassendere Facelift im Jahr 2011 führte eine komplett neue Frontpartie mit neu gestalteten Scheinwerfern, einem größeren Kühlergrill und einem überarbeiteten Stoßfänger ein. Auch das Interieur wurde mit neuen Materialien und einem aktualisierten Infotainmentsystem aufgewertet.',NULL,NULL,NULL,4,2008,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-vierte-generation','Toyota','Hilux','Vierte Generation',1983,1988,'["Pickup"]','Kompakt-Pickup','toyota-hilux-dritte-generation','Die vierte Generation des Toyota Hilux zeichnet sich durch eine kantigere, robustere Karosserie im Vergleich zum Vorgänger aus. Sie besitzt typischerweise rechteckige Scheinwerfer und einen markanten Kühlergrill, der oft den Schriftzug ''TOYOTA'' trägt. Die Frontscheibe ist weniger stark geneigt als bei modernen Pickups, und die Radläufe sind meist eckig oder leicht abgerundet. Im Innenraum gab es eine Modernisierung mit einem funktionaleren Armaturenbrett.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-hilux-zweite-generation','Toyota','Hilux','Zweite Generation',1972,1978,'["Pickup"]','Nutzfahrzeug','toyota-hilux-erste-generation','Die zweite Generation des Toyota Hilux (N20) zeichnet sich durch eine kantigere Karosserie im Vergleich zum Vorgänger aus. Die Frontpartie erhielt einen breiteren Kühlergrill, der oft von runden oder rechteckigen Scheinwerfern flankiert wurde, je nach Markt und Baujahr. Die Karosserielinien sind insgesamt geradliniger und weniger abgerundet als beim N10. Die Ladefläche ist integrierter in das Gesamtdesign.','Ein Facelift erfolgte 1975, bei dem die Frontpartie überarbeitet wurde. Die Scheinwerfer wurden von runden auf rechteckige Einheiten umgestellt (in einigen Märkten), der Kühlergrill erhielt ein neues Design mit horizontalen Lamellen und die Blinker wurden neu positioniert. Auch die Rückleuchten wurden leicht modifiziert.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j100','Toyota','Land Cruiser','J100',1998,2007,'["SUV"]','Oberklasse','toyota-land-cruiser-j80','Der J100 unterscheidet sich vom J80 durch eine deutlich rundere und modernere Karosserieform. Die Scheinwerfer sind größer und integrieren Blinker, die Kühlerniere ist breiter und flacher. Die Heckleuchten sind horizontaler und weniger vertikal orientiert als beim Vorgänger.','Im Jahr 2003 erhielt der J100 ein Facelift. Äußerlich erkennbar an überarbeiteten Scheinwerfern und Rückleuchten, einer modifizierten Frontschürze und neuen Felgendesigns. Im Innenraum gab es Änderungen am Armaturenbrett und der Mittelkonsole.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j200','Toyota','Land Cruiser','J200',2007,2021,'["SUV"]','Oberklasse-SUV','land-cruiser-j100','Der Land Cruiser J200 ist deutlich größer und massiver als sein Vorgänger J100. Er zeichnet sich durch eine bulligere Front mit größeren, eckigeren Scheinwerfern aus, die oft mit LED-Tagfahrlicht kombiniert sind. Die Karosserie wirkt insgesamt muskulöser und weniger abgerundet als beim J100. Die Heckleuchten sind vertikal angeordnet und breiter als beim Vorgänger.','Das erste Facelift (ab 2012) brachte eine überarbeitete Front mit einem größeren Kühlergrill, neuen Scheinwerfern (oft mit LED-Tagfahrlicht) und geänderten Stoßfängern. Auch die Heckleuchten wurden leicht modifiziert. Das zweite Facelift (ab 2015) führte zu einer noch markanteren Front mit einem massiveren, chrombetonten Kühlergrill, schlankeren LED-Scheinwerfern und einer neu gestalteten Motorhaube. Am Heck wurden die Leuchten und die Heckklappe ebenfalls überarbeitet.',NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j300','Toyota','Land Cruiser','J300',2021,NULL,'["SUV"]','Oberklasse-SUV','toyota-land-cruiser-j200','Der Land Cruiser J300 zeichnet sich durch eine modernere, kantigere Designsprache aus. Auffällig sind die breiteren, horizontal ausgerichteten Scheinwerfer, die nahtlos in den großen, trapezförmigen Kühlergrill übergehen. Die Seitenlinie wirkt muskulöser mit ausgeprägteren Radhäusern, und das Heck zeigt schlankere, horizontal verlaufende Rückleuchten, die durch eine Chromleiste verbunden sind. Im Vergleich zum J200 wirkt er insgesamt aggressiver und zeitgemäßer, behält aber die typische Robustheit bei.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre (Erstzulassung), danach 1 Jahr',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j40','Toyota','Land Cruiser','J40',1960,1984,'["SUV", "Pickup", "Cabriolet"]','Geländewagen','toyota-land-cruiser-j20_j30','Die J40-Generation zeichnet sich durch ihre robuste, kantige Karosserie mit runden Scheinwerfern und einem markanten, vertikalen Kühlergrill aus. Typisch sind die freistehenden vorderen Kotflügel, die oft mit seitlichen Lüftungsschlitzen versehen sind, sowie die nach außen angeschlagenen Türen. Im Vergleich zum Vorgänger J20/J30 wirkt die J40-Serie moderner und weniger militärisch, behält aber die hohe Bodenfreiheit und die ausgeprägte Geländetauglichkeit bei. Die Windschutzscheibe ist oft flach und kann bei einigen Modellen umgeklappt werden.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j60','Toyota','Land Cruiser','J60',1980,1990,'["Kombi"]','Oberklasse','toyota-land-cruiser-j40','Der J60 unterscheidet sich vom Vorgänger J40 durch seine deutlich größere und eckigere Karosserie. Charakteristisch sind die rechteckigen Scheinwerfer (oftmals vier), die breitere und flachere Kühlermaske sowie die vergrößerten Fensterflächen. Die Dachlinie ist höher und die Seitenlinie geradliniger.','Ein Facelift fand um 1985 statt. Erkennbar ist dies an den nunmehr runden Doppelscheinwerfern (bei vielen Modellen), einer leicht modifizierten Kühlermaske und neuen Innenraummaterialien. Die Heckleuchten wurden ebenfalls überarbeitet.',NULL,NULL,NULL,NULL,NULL,NULL,'','Der J60 ist ein robuster Geländewagen, der für seine Langlebigkeit bekannt ist. Achten Sie auf Rost, insbesondere an den Radläufen, Schwellern und am Unterboden. Die Motoren sind in der Regel zuverlässig, aber eine vollständige Wartungshistorie ist wichtig. Getriebe und Achsen sollten auf Geräusche und Spiel geprüft werden. Die Ersatzteilversorgung kann je nach Region variieren.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-land-cruiser-j80','Toyota','Land Cruiser','J80',1990,1997,'["SUV", "Geländewagen"]','Obere Mittelklasse SUV','toyota-land-cruiser-j70','Der Land Cruiser J80 zeichnet sich durch eine deutlich rundlichere und breitere Karosserie im Vergleich zum kantigen Vorgänger J70 aus. Er besitzt große, rechteckige Scheinwerfer, die in die Frontmaske integriert sind, und eine breite, flache Motorhaube. Die Frontscheibe ist stärker geneigt als beim J70, und die Seitenfenster sind größer.','Ein leichtes Facelift erfolgte 1995, bei dem die Scheinwerfer von rechteckig zu runderen, integrierten Einheiten wechselten und der Kühlergrill leicht überarbeitet wurde. Im Innenraum gab es Änderungen an den Sitzen und der Armaturentafel, einschließlich der Einführung von Airbags.',NULL,NULL,NULL,NULL,NULL,10000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-prius-xw10','Toyota','Prius','XW10',1997,2003,'["Limousine"]','Kompaktklasse',NULL,'Die erste Generation des Toyota Prius (XW10) ist eine kompakte, viertürige Stufenheck-Limousine mit einem eher unauffälligen, abgerundeten Design. Sie unterscheidet sich von späteren Generationen durch ihre klassischere Limousinenform, die noch nicht die ausgeprägte Keilform und das Fließheck der Nachfolger aufweist. Die Scheinwerfer und Rückleuchten sind schmal und horizontal ausgerichtet. Im Vergleich zum Nachfolger (XW11/XW20) wirkt die Karosserie weniger aerodynamisch optimiert und die Proportionen sind gedrungener.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre (nach Erstzulassung 3 Jahre)',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-prius-xw20','Toyota','Prius','XW20',2003,2009,'["Schrägheck"]','Kompaktklasse','toyota-prius-xw10','Der XW20 zeichnet sich durch seine markante, aerodynamische Keilform mit einem ausgeprägten Kamm-Heck aus. Die Scheinwerfer sind deutlich stärker nach hinten gezogen und integrierter als beim Vorgänger XW10. Die Heckleuchten sind vertikal in die C-Säule und den hinteren Kotflügel integriert, im Gegensatz zu den horizontalen Leuchten des XW10.',NULL,NULL,NULL,NULL,5,2004,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-prius-xw30','Toyota','Prius','XW30',2009,2015,'["Schrägheck"]','Kompaktklasse','toyota-prius-xw20','Die dritte Generation des Prius (XW30) ist erkennbar an ihrer aerodynamischeren, fließenderen Karosserieform im Vergleich zum Vorgänger. Die Scheinwerfer sind schmaler und ziehen sich weiter in die Kotflügel, die Frontschürze ist glatter gestaltet. Das Heck wirkt runder und die Rückleuchten sind vertikaler und schlanker als beim XW20, wobei sie sich nicht mehr so stark um die Ecke ziehen.','Im Jahr 2012 erhielt der Prius XW30 ein Facelift. Die auffälligsten Änderungen waren eine neu gestaltete Frontschürze mit integrierten LED-Tagfahrlichtern, leicht modifizierte Scheinwerfer mit dunkleren Einsätzen und eine überarbeitete Heckschürze. Im Innenraum gab es kleinere Anpassungen an Materialien und Farben sowie ein aktualisiertes Infotainmentsystem.',NULL,NULL,NULL,5,2009,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-prius-xw50','Toyota','Prius','XW50',2016,2022,'["Schrägheck"]','Kompaktklasse','toyota-prius-xw30','Die vierte Generation des Prius (XW50) zeichnet sich durch ein deutlich futuristischeres und kantigeres Design im Vergleich zum Vorgänger aus. Auffällig sind die schmalen, weit in die Kotflügel gezogenen Scheinwerfer mit markanten LED-Tagfahrlicht-Signaturen, die bis in den Stoßfänger reichen. Am Heck dominieren vertikale, bumerangförmige Rückleuchten, die tief in die Stoßfängerecken integriert sind und sich deutlich von den horizontalen Leuchten des XW30 abheben. Die Karosserie wirkt insgesamt flacher und aerodynamischer.','Das Facelift Ende 2018 (Modelljahr 2019) brachte eine Überarbeitung der Front- und Heckpartie. Die Scheinwerfer wurden leicht modifiziert und erhielten eine weniger zerklüftete Form. Die vertikalen Rückleuchten wurden durch horizontalere, L-förmige Leuchten ersetzt, die sich über die Heckklappe erstrecken und dem Fahrzeug ein breiteres Erscheinungsbild verleihen. Auch die Stoßfänger wurden dezent angepasst.',NULL,NULL,NULL,5,2016,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-rav4-i','Toyota','RAV4','I',1994,2000,'["SUV", "Kompakt-SUV"]','Kompakt-SUV',NULL,'Erste Generation des Toyota RAV4. Charakteristisch sind die runden Scheinwerfer, die markante, leicht nach außen gewölbte Karosserie und das außen angebrachte Reserverad am Heck. Die erste Generation war als 3- und 5-türige Variante erhältlich.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-rav4-ii','Toyota','RAV4','II',2000,2005,'["SUV"]','Kompakt-SUV','toyota-rav4-i','Der Toyota RAV4 II unterscheidet sich vom Vorgänger durch eine deutlich rundere und modernere Karosserieform. Die Scheinwerfer sind größer und integrieren sich stärker in die Frontpartie. Die Heckleuchten sind ebenfalls neu gestaltet und reichen weiter in die Seiten. Die Radhäuser sind stärker ausgeprägt und verleihen dem Fahrzeug einen robusteren Auftritt.','Im Jahr 2003 erhielt der RAV4 II ein Facelift. Äußerlich erkennbar an einer überarbeiteten Frontschürze, neuen Scheinwerfern mit Klarglasoptik und modifizierten Rückleuchten. Im Innenraum gab es Anpassungen am Armaturenbrett und der Mittelkonsole.',NULL,NULL,NULL,4,2004,NULL,'24 Monate','Der RAV4 II ist bekannt für seine Zuverlässigkeit. Achten Sie auf Rost an den Radläufen und Schwellern, besonders bei Fahrzeugen aus Regionen mit viel Streusalz. Die Motoren sind generell robust, aber regelmäßige Wartung ist entscheidend. Prüfen Sie das Fahrwerk auf Verschleißerscheinungen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-rav4-iii','Toyota','RAV4','III',2005,2012,'["SUV"]','Kompakt-SUV','toyota-rav4-ii','Die dritte Generation des RAV4 (XA30) ist deutlich größer und geräumiger als ihr Vorgänger. Sie zeichnet sich durch eine rundlichere, weniger kantige Karosserieform aus. Ein markantes Merkmal ist die seitlich öffnende Heckklappe, an der das Reserverad außen montiert ist. Die Scheinwerfer sind größer und fließender in die Front integriert als beim RAV4 II.','Das erste Facelift (Ende 2008/Anfang 2009) brachte eine überarbeitete Frontpartie mit einem neuen Kühlergrill (oft mit horizontalen Chromstreben), neuen Stoßfängern und leicht modifizierten Scheinwerfern. Die Nebelscheinwerfer erhielten eine neue Form. Das zweite Facelift (Ende 2010/Anfang 2011) führte erneut einen neuen Kühlergrill ein, der nun eine V-förmige Chromspange aufwies, sowie neu gestaltete Stoßfänger und Rückleuchten mit LED-Technik (je nach Ausstattung).',NULL,NULL,NULL,4,2006,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-rav4-iv','Toyota','RAV4','IV',2012,2018,'["SUV"]','Kompakt-SUV','toyota-rav4-iii','Der RAV4 IV (XA40) zeichnet sich durch ein deutlich schärferes und kantigeres Design im Vergleich zum runderen Vorgänger aus. Die Front wird von einem markanten, oft trapezförmigen Kühlergrill dominiert, der nahtlos in die schmaleren, nach hinten gezogenen Scheinwerfer übergeht. Im Gegensatz zu früheren Generationen ist das Reserverad nicht mehr an der Heckklappe montiert, und die Heckklappe öffnet nach oben statt zur Seite.','Ein Facelift erfolgte Ende 2015 (Modelljahr 2016). Dabei wurden die Frontpartie mit einem schlankeren oberen und einem größeren unteren Kühlergrill sowie neuen LED-Scheinwerfern (je nach Ausstattung) überarbeitet. Auch die Heckleuchten erhielten ein neues LED-Design, und die Stoßfänger vorne und hinten wurden modifiziert. Im Innenraum gab es verbesserte Materialien und ein aktualisiertes Infotainmentsystem. Mit dem Facelift wurde auch die Hybrid-Variante eingeführt.',NULL,NULL,NULL,5,2013,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-rav4-v','Toyota','RAV4','V',2018,NULL,'["SUV"]','Kompakt-SUV','toyota-rav4-iv','Der Toyota RAV4 V (XA50) unterscheidet sich von seinem Vorgänger durch eine deutlich kantigere und muskulösere Designsprache. Auffällig sind die schmaleren, aggressiver gezeichneten LED-Scheinwerfer, der größere und markantere Kühlergrill sowie die stark ausgeprägten Radhäuser. Die Heckleuchten sind ebenfalls schmaler und horizontaler gestaltet und verbinden sich optisch mit einer Chromleiste.','Im Rahmen eines Facelifts im Jahr 2022 erhielt der RAV4 V eine überarbeitete Front mit neu gestalteten Scheinwerfern und Tagfahrlichtern sowie eine neue Generation des Infotainmentsystems mit größerem Touchscreen und verbesserter Sprachsteuerung. Auch die Plug-in-Hybrid-Variante wurde technisch optimiert.',NULL,NULL,NULL,5,2019,NULL,'24 Monate','Der Toyota RAV4 V ist bekannt für seine Zuverlässigkeit, insbesondere die Hybrid-Varianten. Achten Sie bei Gebrauchtwagen auf den Zustand der Batterie bei den Hybridmodellen und auf regelmäßige Wartung. Die Verarbeitung ist solide, aber das Infotainmentsystem kann als etwas langsam empfunden werden. Die verschiedenen Ausstattungslinien bieten unterschiedliche Komfort- und Sicherheitsfeatures.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-supra-dritte-generation-(a70)','Toyota','Supra','Dritte Generation (A70)',1986,1993,'["Coupé"]','Sportwagen','toyota-supra-zweite-generation-(mk2)','Die dritte Generation (A70) unterscheidet sich deutlich von ihrem Vorgänger. Sie erhielt eine komplett neue, aerodynamischere Karosserieform mit einem längeren Radstand und einer markanten, flachen Frontpartie mit ausklappbaren Scheinwerfern. Die Heckleuchten wurden breiter und integrierter in das Design. Die Proportionen sind insgesamt muskulöser und moderner.','1988 gab es ein leichtes Facelift mit überarbeiteten Felgen und kleineren Detailänderungen. Ein weiteres Facelift im Jahr 1990 brachte eine überarbeitete Frontschürze, neue Scheinwerfer (feststehend statt ausklappbar bei einigen Modellen), geänderte Rückleuchten und eine breitere Spur.',NULL,NULL,NULL,NULL,NULL,NULL,'','Die A70 Supra ist ein begehrter Sportwagen mit potenziell hoher Leistung. Achten Sie auf Rost, insbesondere an Radläufen, Schwellern und im Bereich der Heckklappe. Der Motor (insbesondere der 3.0 Turbo) kann anfällig für Überhitzung sein, prüfen Sie daher den Zustand des Kühlsystems. Getriebe und Differential sollten auf Geräusche und Undichtigkeiten geprüft werden. Die ausklappbaren Scheinwerfer können mechanische Probleme aufweisen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-supra-erste-generation-(a40/a50)','Toyota','Supra','Erste Generation (A40/A50)',1978,1981,'["Coupé"]','Sportwagen',NULL,'Die erste Generation der Toyota Supra, intern als A40/A50 bezeichnet, unterscheidet sich von späteren Modellen durch ihre kantigere, klassische Sportwagen-Silhouette. Charakteristisch sind die runden Scheinwerfer (oft vierfach), die lange Motorhaube und das Heck mit den typischen Rückleuchten, die über die gesamte Breite des Fahrzeugs verlaufen. Die Karosserieform ist ein zweitüriges Coupé mit einem deutlichen Stufenheck.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','Die erste Generation der Toyota Supra (A40/A50) ist ein begehrter Klassiker. Bei der Suche nach einem Exemplar sollte auf Rost an typischen Stellen wie Radläufen, Schweller und Unterboden geachtet werden. Die Motoren (insbesondere der Reihensechszylinder) sind robust, aber eine Überprüfung des Zustands und der Wartungshistorie ist unerlässlich. Die Innenausstattung kann altersbedingte Abnutzungserscheinungen aufweisen. Ersatzteile können rar sein und erfordern Geduld bei der Beschaffung.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-supra-fünfte-generation-(a90)','Toyota','Supra','Fünfte Generation (A90)',2019,NULL,'["Coupé"]','Sportwagen','toyota-supra-vierte-generation-(a80)','Die fünfte Generation der Supra (A90) ist sofort an ihrem aggressiven und modernen Design erkennbar, das stark vom FT-1 Konzeptfahrzeug inspiriert ist. Charakteristisch sind die markante Doppelwölbung des Daches, die schmalen, langgezogenen LED-Scheinwerfer und die großen, oft schwarz abgesetzten Lufteinlässe in der Frontschürze. Im Vergleich zum Vorgänger A80 wirkt sie deutlich kompakter und muskulöser, mit einer kürzeren Heckpartie und ausgeprägten hinteren Kotflügeln.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-supra-vierte-generation-(a80)','Toyota','Supra','Vierte Generation (A80)',1993,2002,'["Coupé"]','Sportwagen','toyota-supra-dritte-generation-(a70)','Die vierte Generation (A80) unterscheidet sich deutlich von ihrem Vorgänger (A70). Sie hat eine deutlich rundere und aerodynamischere Karosserieform mit markanten, abgerundeten Linien. Die Scheinwerfer sind nun versenkbar (Pop-up-Scheinwerfer), was ein charakteristisches Merkmal ist. Die Heckleuchten sind zu einer durchgehenden Leiste verbunden. Die Proportionen sind insgesamt sportlicher und kompakter.','Es gab ein Facelift im Jahr 1997, das unter anderem leicht überarbeitete Felgendesigns und eine neue Farbpalette umfasste. Technisch gab es kleinere Anpassungen, aber die grundlegende Karosserieform und die markanten Merkmale blieben erhalten.',NULL,NULL,NULL,NULL,NULL,NULL,'','Die A80 Supra ist ein begehrter Sportwagen, dessen Wertentwicklung stark von Zustand und Laufleistung abhängt. Achten Sie auf Rost, insbesondere an Radläufen und Schwellern. Der Motor (2JZ-GTE) ist robust, aber bei stark getunten Fahrzeugen ist Vorsicht geboten. Getriebe und Fahrwerk sollten auf Spiel und Geräusche geprüft werden. Ersatzteile können teuer und schwer zu finden sein.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-supra-zweite-generation-(a60)','Toyota','Supra','Zweite Generation (A60)',1981,1986,'["Coupé", "Liftback Coupé"]','Sportcoupé','toyota-celica-supra-erste-generation-(a40-a50)','Die zweite Generation der Supra (A60) ist leicht an ihren charakteristischen Klappscheinwerfern zu erkennen, die sie deutlich vom Vorgänger (A40/A50) mit festen Scheinwerfern und dem Nachfolger (A70) mit ebenfalls Klappscheinwerfern, aber einer deutlich runderen Karosserieform abgrenzen. Die A60 zeichnet sich durch eine kantigere, aerodynamischere Linienführung und eine markante, oft zweifarbige Lackierung aus, die den sportlichen Charakter unterstreicht. Die Heckpartie ist typischerweise als Liftback gestaltet.','Im Jahr 1983 gab es ein leichtes Facelift, das hauptsächlich kosmetische Änderungen umfasste. Dazu gehörten eine überarbeitete Frontschürze mit integrierten Nebelscheinwerfern, neue Rückleuchten und eine modifizierte Heckschürze. Im Innenraum wurden kleinere Anpassungen an den Sitzen und der Instrumententafel vorgenommen.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-yaris-cross-i','Toyota','Yaris Cross','I',2021,NULL,'["SUV"]','Kleinwagen-SUV',NULL,'Der Yaris Cross I ist ein kompaktes SUV, das sich durch seine erhöhte Bodenfreiheit, die robust wirkende Kunststoffbeplankung an Radläufen und Schwellern sowie eine eigenständige Front- und Heckpartie vom Yaris Kleinwagen abgrenzt. Typisch sind die schmalen, horizontalen LED-Scheinwerfer und die vertikalen Lufteinlässe an den Seiten der Frontschürze. Am Heck fallen die durch eine schwarze Leiste verbundenen Rückleuchten auf.','Im Modelljahr 2024 (ab Anfang 2024) wurde ein leichtes Update eingeführt, das hauptsächlich technische Neuerungen wie einen stärkeren Hybridantrieb (''Hybrid 130'') und verbesserte Infotainment-Systeme umfasst. Optisch sind die Änderungen minimal und beschränken sich auf neue Lackfarben und Felgendesigns sowie eine leicht überarbeitete Innenraumgestaltung mit neuen Materialien und größeren Bildschirmen. Ein klassisches, umfassendes Facelift mit deutlich sichtbaren Änderungen an Front- oder Heckpartie fand nicht statt.',NULL,NULL,NULL,5,2021,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-yaris-i','Toyota','Yaris','I',1999,2005,'["Kleinwagen", "Schräghecklimousine"]','Kleinwagen',NULL,'Der Toyota Yaris I (intern XP10) löste den Starlet ab. Charakteristisch sind die runden, leicht nach oben gezogenen Scheinwerfer, die breite, trapezförmige Kühlernase und die leicht gewölbte Motorhaube. Die Seitenlinie ist durch eine markante Knicklinie unterhalb der Fensterlinie und eine aufrechte C-Säule gekennzeichnet. Im Vergleich zum Vorgänger ist die Karosserie deutlich moderner und runder gestaltet.','Ein Facelift erfolgte im Jahr 2003. Äußerlich erkennbar an leicht modifizierten Scheinwerfern und Rückleuchten, einem überarbeiteten Kühlergrill und neuen Stoßfängern. Im Innenraum gab es Anpassungen bei Materialien und der Mittelkonsole.',NULL,NULL,NULL,4,2000,NULL,'24 Monate','Der Yaris I ist bekannt für seine Zuverlässigkeit und niedrigen Unterhaltskosten. Achten Sie auf Rost an den Radläufen und Schwellern, insbesondere bei älteren Modellen. Die Kupplung kann bei hoher Laufleistung verschleißen. Die Elektrik ist meist unauffällig.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-yaris-ii','Toyota','Yaris','II',2005,2011,'["3-Türer", "5-Türer"]','Kleinwagen','toyota-yaris-i','Der Yaris II (XP9) ist im Vergleich zum Vorgänger (XP1) deutlich runder und weicher gezeichnet. Die Frontpartie wirkt bulliger mit größeren, mandelförmigen Scheinwerfern, die weiter in die Kotflügel reichen. Der Kühlergrill ist schmaler und sitzt höher. Die Seitenlinie ist fließender, und die Heckleuchten sind größer und ragen stärker in die Seitenflanken hinein, während sie beim Yaris I eher vertikal und schmal waren. Die Fensterlinie steigt nach hinten leicht an.','Im Jahr 2009 erfolgte ein leichtes Facelift. Die Änderungen waren subtil und umfassten eine leicht modifizierte Frontschürze mit einem breiteren, trapezförmigen unteren Lufteinlass, der nun eine Wabenstruktur aufweisen konnte. Die Nebelscheinwerferfassungen wurden überarbeitet. Am Heck gab es leicht getönte Rückleuchten und eine überarbeitete Heckschürze. Im Innenraum wurden neue Polsterstoffe und geringfügige Änderungen an den Bedienelementen vorgenommen.',NULL,NULL,NULL,5,2005,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-yaris-iii','Toyota','Yaris','III',2011,2020,'["Schräghecklimousine"]','Kleinwagen','toyota-yaris-ii','Der Yaris III unterscheidet sich vom Vorgänger durch eine deutlich größere und breitere Karosserie, eine markantere Front mit größeren Scheinwerfern und einem trapezförmigen Kühlergrill sowie ein neu gestaltetes Heck mit horizontalen Rückleuchten. Die Seitenlinie wirkt dynamischer mit einer stärker ausgeprägten Schulterlinie.','Das erste Facelift (2014) brachte eine überarbeitete Frontpartie mit neuem Kühlergrill und Stoßfängern, modifizierte Rückleuchten und neue Felgendesigns. Das zweite Facelift (2017) führte eine nochmals angepasste Front mit größerem Kühlergrill, neuen Scheinwerfern und LED-Tagfahrlicht ein. Auch das Heck wurde überarbeitet und das Interieur erhielt ein Update mit einem neuen Touchscreen und verbesserter Materialanmutung.',NULL,NULL,NULL,5,2011,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('toyota-yaris-iv','Toyota','Yaris','IV',2020,NULL,'["Kleinwagen"]','B','toyota-yaris-iii','Die vierte Generation des Toyota Yaris (XP210) unterscheidet sich deutlich von seinem Vorgänger. Auffällige Merkmale sind die deutlich schmaler und aggressiver gestalteten Scheinwerfer, die stark nach oben gezogen sind, die breitere und markantere ''Single-Frame''-ähnliche Frontpartie mit einem größeren Kühlergrill und die insgesamt dynamischere und coupéhaftere Silhouette mit einer stark abfallenden Dachlinie. Auch die Rückleuchten sind neu gestaltet und verbinden sich optisch über eine Leiste.',NULL,NULL,NULL,NULL,5,2020,NULL,'2 Jahre','Der Yaris IV setzt auf die neue GA-B-Plattform von Toyota, die für ein verbessertes Fahrverhalten und mehr Sicherheit sorgt. Besonders hervorzuheben ist das Hybrid-System, das in dieser Generation weiter optimiert wurde und eine hohe Effizienz verspricht. Die Sicherheitsausstattung ist bereits in der Basis sehr umfangreich. Achten Sie bei Gebrauchtwagen auf den Zustand der Hybrid-Batterie und lassen Sie die Wartungshistorie prüfen.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-arteon-typ-3h','Volkswagen','Arteon','Typ 3H',2017,NULL,'["Limousine", "Kombi"]','Obere Mittelklasse','volkswagen-cc-typ-3cc','Der Arteon Typ 3H zeichnet sich durch seine flache, coupéhafte Silhouette mit rahmenlosen Fenstern aus. Die Front dominiert ein breiter Kühlergrill, der nahtlos in die LED-Scheinwerfer übergeht und die gesamte Fahrzeugbreite betont. Im Vergleich zum Vorgänger VW CC wirkt er deutlich dynamischer und eigenständiger, mit einer markanteren Schulterlinie und einem stärker ausgeprägten Fastback-Heck.','Das Facelift im Jahr 2020 brachte eine überarbeitete Frontpartie mit einer durchgehenden LED-Lichtleiste im Kühlergrill (optional), neue Stoßfänger und eine leicht modifizierte Heckpartie. Im Innenraum wurden das Infotainmentsystem (MIB3) und das Lenkrad aktualisiert. Zudem wurde die Karosserievariante ''Shooting Brake'' (Kombi) eingeführt und Plug-in-Hybrid-Antriebe (eHybrid) sowie ein R-Modell ergänzt.',NULL,NULL,NULL,5,2017,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-caddy-ii','Volkswagen','Caddy','II',1995,2003,'["Kastenwagen", "Kombi", "Pickup"]','Hochdachkombi','volkswagen-caddy-i','Der Caddy II basiert auf dem VW Polo III (Typ 6N) und teilt sich mit diesem die Frontpartie. Charakteristisch sind die runden, in die Karosserie integrierten Scheinwerfer und die im Vergleich zum Vorgänger deutlich abgerundete Karosserieform. Die Front ist nahezu identisch mit dem Polo 6N, während der hintere Bereich als Kastenwagen, Kombi oder Pickup ausgeführt ist.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-caddy-iii','Volkswagen','Caddy','III',2003,2015,'["Kombi", "Kastenwagen"]','Kleinwagen','volkswagen-caddy-ii','Der Caddy III unterscheidet sich deutlich vom Vorgänger. Er basiert auf der Plattform des VW Golf V. Erkennbar ist er an den größeren Abmessungen, den moderneren Scheinwerfern und der kantigeren Linienführung. Die Heckpartie wurde ebenfalls neu gestaltet mit größeren Rückleuchten.','Im Jahr 2010 erhielt der Caddy III ein Facelift. Äußerlich erkennbar an einer überarbeiteten Front mit neuen Scheinwerfern, einem modifizierten Kühlergrill und Stoßfängern. Auch die Rückleuchten wurden leicht angepasst. Im Innenraum gab es neue Materialien und ein überarbeitetes Infotainmentsystem.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-caddy-iv','Volkswagen','Caddy','IV',2015,2020,'["Kastenwagen", "Kombi", "Maxi"]','Hochdachkombi','volkswagen-caddy-iii','Der Caddy IV unterscheidet sich vom Vorgänger durch eine deutlich modernere und schärfere Frontpartie mit einem breiteren Kühlergrill und neu gestalteten Scheinwerfern, die oft mit LED-Tagfahrlicht ausgestattet sind. Die Seitenlinie wirkt dynamischer, und das Heck wurde mit neuen Rückleuchten und einer überarbeiteten Heckklappe versehen. Im Innenraum wurde das Armaturenbrett komplett neu gestaltet und ein moderneres Infotainmentsystem integriert.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-caddy-v','Volkswagen','Caddy','V',2020,NULL,'["Hochdachkombi", "Kastenwagen", "Maxi", "California"]','Hochdachkombi','volkswagen-caddy-iv','Der Caddy V basiert auf dem Modularen Querbaukasten (MQB) und unterscheidet sich deutlich vom Vorgänger. Er hat eine flachere, dynamischere Front mit schmaleren LED-Scheinwerfern, die direkt in den Kühlergrill übergehen. Die Heckpartie ist durch vertikale, schmale LED-Rückleuchten gekennzeichnet, die bis in die D-Säule reichen. Die Seitenlinie wirkt gestreckter und moderner.',NULL,NULL,NULL,NULL,5,2021,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-i','Volkswagen','Golf','I',1974,1983,'["Schrägheck", "Cabriolet", "Pickup"]','Kompaktklasse','volkswagen-kaefer','Der Golf I zeichnet sich durch seine von Giorgetto Giugiaro entworfene, kantige und kompakte Karosserie aus. Er besitzt runde Frontscheinwerfer (spätere GTI-Modelle auch Doppelscheinwerfer) und eine charakteristische breite C-Säule. Im Gegensatz zum Vorgänger Käfer verfügt er über Frontmotor, Frontantrieb und Wasserkühlung.','1978 erfolgte ein Facelift mit größeren Rückleuchten, der Einführung von Kunststoffstoßstangen (statt Chrom) und einer überarbeiteten Armaturentafel. 1980 gab es weitere kleinere Änderungen, darunter ein neues Lenkrad und geänderte Türverkleidungen.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-ii','Volkswagen','Golf','II',1983,1992,'["Schrägheck 3-Türer", "Schrägheck 5-Türer"]','Kompaktklasse','volkswagen-golf-i','Der Golf II ist deutlich größer und runder als sein Vorgänger. Er besitzt integrierte Stoßfänger, die bündiger mit der Karosserie abschließen, und größere, rechteckige Scheinwerfer. Die C-Säule ist breiter und die Heckleuchten sind ebenfalls größer und rechteckiger gestaltet als beim Golf I.','Das erste Facelift erfolgte 1987 (Modelljahr 1988) mit der Einführung kleinerer Stoßfänger und eines geänderten Kühlergrills mit weniger Lamellen. Ein weiteres, kleineres Update 1989 (Modelljahr 1990) brachte größere, voluminösere Stoßfänger, die bis zum Ende der Baureihe verwendet wurden, sowie eine geänderte Seitenbeplankung und eine neue Kühlergrill-Optik.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-iii','Volkswagen','Golf','III',1991,1997,'["Schrägheck (3-Türer)", "Schrägheck (5-Türer)", "Variant (Kombi)", "Cabriolet"]','Kompaktklasse','volkswagen-golf-ii','Der Golf III zeichnet sich durch seine deutlich rundlicheren und weicheren Formen im Vergleich zum kantigen Vorgänger aus. Die Scheinwerfer sind breiter, flacher und gehen nahtlos in die Kotflügel über, während der Kühlergrill breiter und integrierter wirkt. Die Heckleuchten sind ebenfalls breiter und runder gestaltet. Die Karosserie wirkt insgesamt aerodynamischer und weniger eckig als beim Golf II.',NULL,NULL,NULL,NULL,NULL,NULL,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-iv','Volkswagen','Golf','IV',1997,2003,'["Schrägheck", "Variant", "Cabriolet"]','Kompaktklasse','volkswagen-golf-iii','Der Golf IV zeichnet sich durch eine deutlich rundlichere und modernere Formgebung im Vergleich zum kantigeren Golf III aus. Charakteristisch sind die klaren, integrierten Scheinwerfer, die nicht mehr durch eine separate Blinker-Einheit unterbrochen werden, sowie die breitere C-Säule, die ihm eine robustere Anmutung verleiht. Die Heckleuchten sind breiter und flacher als beim Vorgänger und reichen bis in die Seitenflanken.',NULL,NULL,NULL,NULL,4,1998,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-v','Volkswagen','Golf','V',2003,2008,'["Schrägheck 3-Türer", "Schrägheck 5-Türer", "Variant", "Plus"]','Kompaktklasse','volkswagen-golf-iv','Der Golf V zeichnet sich durch eine deutlich rundere und dynamischere Formgebung im Vergleich zum kantigeren Golf IV aus. Auffällig sind die doppelten, runden Scheinwerfer (Bi-Xenon-Option) hinter einer gemeinsamen Klarglasabdeckung, die dem Fahrzeug ein markantes ''Vieraugen''-Gesicht verleihen. Die Dachlinie ist höher und die C-Säule breiter und stärker geneigt. Die Heckleuchten sind größer und ragen stärker in die Seitenflanken hinein.',NULL,NULL,NULL,NULL,5,2003,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-vi','Volkswagen','Golf','VI',2008,2012,'["Schrägheck", "Variant", "Cabriolet"]','Kompaktklasse','volkswagen-golf-v','Der Golf VI zeichnet sich durch eine klarere und elegantere Linienführung im Vergleich zum Golf V aus. Die Scheinwerfer sind schmaler, horizontaler ausgerichtet und reichen nicht mehr so weit in die Kotflügel. Der Kühlergrill ist flacher und breiter. Am Heck sind die Rückleuchten breiter und zweigeteilt, wobei ein Teil in die Heckklappe ragt, im Gegensatz zu den runden, eher vertikalen Leuchten des Vorgängers. Die Seitenlinie wirkt gestreckter und weniger hochbeinig.',NULL,NULL,NULL,NULL,5,2008,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-vii','Volkswagen','Golf','VII',2012,2020,'["Schrägheck", "Kombi"]','Kompaktklasse','volkswagen-golf-vi','Der Golf VII unterscheidet sich vom Vorgänger durch eine deutlich flachere und gestrecktere Silhouette, eine schärfer gezeichnete Front mit schmaleren Scheinwerfern, die bis in den Kühlergrill reichen, und eine markantere Heckpartie mit horizontalen Rückleuchten. Die Linienführung ist insgesamt dynamischer und moderner.','Das Facelift im Jahr 2017 brachte eine überarbeitete Frontschürze, neue Scheinwerfer- und Rückleuchtendesigns (optional mit LED-Technik), sowie eine modernisierte Innenraumgestaltung mit optionalem volldigitalem Cockpit (Active Info Display) und einem größeren Infotainment-Bildschirm. Auch die Motorenpalette wurde angepasst.',NULL,NULL,NULL,5,2012,NULL,'24 Monate','Der Golf VII ist ein solider Kompaktwagen mit guter Verarbeitung und breiter Motorenauswahl. Achten Sie bei Gebrauchtwagen auf die Wartungshistorie, insbesondere bei TSI-Motoren (Steuerkette) und DSG-Getrieben. Rost ist bei gepflegten Fahrzeugen selten ein Thema. Modelle mit Allradantrieb (4MOTION) und die sportlichen GTI- und R-Varianten sind begehrt.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-golf-viii','Volkswagen','Golf','VIII',2019,NULL,'["Limousine", "Variant"]','Kompaktklasse','volkswagen-golf-vii','Der Golf VIII unterscheidet sich vom Vorgänger durch deutlich schmalere, tiefer in die Kotflügel gezogene LED-Scheinwerfer, die optional durch ein durchgehendes Leuchtenband verbunden sind. Im Innenraum dominieren zwei große Displays (Digital Cockpit Pro und Infotainment-System), die die meisten physischen Tasten ersetzen und ein stark digitalisiertes Bedienkonzept einführen. Die Karosserielinien sind insgesamt fließender, behalten aber die typische Golf-Silhouette bei.','Ein Facelift wurde Anfang 2024 vorgestellt (Modelljahr 2025). Es umfasst eine neu gestaltete Frontschürze, überarbeitete LED-Scheinwerfer (optional mit beleuchtetem VW-Logo) und neue LED-Rückleuchten. Im Innenraum wurde das Infotainmentsystem (MIB4) mit einem größeren Display und verbesserter Software aktualisiert, und die Lenkradtasten wurden wieder physisch ausgeführt.',NULL,NULL,NULL,5,2019,30000,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-id.-buzz-1.-generation','Volkswagen','ID. Buzz','1. Generation',2022,NULL,'["Kastenwagen", "Kleinbus"]','Van',NULL,'Der ID. Buzz zeichnet sich durch sein retro-futuristisches Design aus, das an den klassischen VW Bulli (T1) erinnert. Auffällige Merkmale sind die großen, zentral platzierten VW-Logos vorne und hinten, die durchgehenden LED-Lichtbänder an Front und Heck, die optional erhältliche Zweifarblackierung sowie die kurzen Überhänge und die großen Fensterflächen. Die Front ist rundlich und die Scheinwerfer sind in das durchgehende Lichtband integriert. Im Vergleich zu anderen modernen Vans oder Elektrofahrzeugen hebt er sich durch seine ikonische Form und die freundliche, bulli-ähnliche Optik ab.',NULL,NULL,NULL,NULL,5,2022,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-id.3-1.-generation','Volkswagen','ID.3','1. Generation',2020,2023,'["Kompaktwagen"]','Kompaktklasse',NULL,'Die 1. Generation des VW ID.3 zeichnet sich durch eine glatte Frontpartie mit einer durchgehenden Lichtleiste aus, die die VW-Logos verbindet. Die Scheinwerfer sind relativ groß und rundlich gestaltet. Die Motorhaube ist kurz und fällt steil ab. Am Heck sind die Rückleuchten zweigeteilt, wobei ein Teil in der Heckklappe sitzt und der andere in der Karosserie. Die C-Säule ist oft mit einem farblich abgesetzten Designelement versehen.',NULL,NULL,NULL,NULL,5,2020,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-id.4-1.-generation','Volkswagen','ID.4','1. Generation',2020,NULL,'["SUV"]','Kompakt-SUV',NULL,'Die 1. Generation des VW ID.4 zeichnet sich durch das typische, glatte ID-Design mit geschlossener Frontpartie und einem durchgehenden LED-Lichtband (optional) aus. Die Scheinwerfer sind schmal und laufen in die Kotflügel aus. Die Seitenansicht ist von fließenden Linien und bündigen Türgriffen geprägt, während das Heck ebenfalls ein durchgehendes LED-Leuchtenband (optional) und einen markanten Dachspoiler aufweist. Im Vergleich zu konventionellen VW-SUVs wie dem Tiguan wirkt der ID.4 deutlich futuristischer und runder, mit einer aerodynamisch optimierten Silhouette.','Im Modelljahr 2024 (Produktionsstart Ende 2023) gab es eine technische Überarbeitung mit stärkeren Motoren und einem neuen Infotainmentsystem. Optische Änderungen waren jedoch minimal und beschränkten sich auf Details wie neue Felgendesigns und leicht angepasste Schriftzüge, sodass kein klassisches Facelift im Sinne einer deutlichen visuellen Veränderung stattfand.',NULL,NULL,NULL,5,2021,NULL,'2 Jahre nach Erstzulassung, danach jährlich',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-id.5-1.-generation','Volkswagen','ID.5','1. Generation',2022,NULL,'["SUV-Coupé"]','Mittelklasse-SUV',NULL,'Der Volkswagen ID.5 ist das Coupé-Derivat des ID.4 und zeichnet sich durch seine markant abfallende Dachlinie aus, die in einem integrierten Heckspoiler mündet. Im Vergleich zum ID.4 besitzt er eine sportlichere, flachere Heckscheibe und eine eigenständige Heckklappe. Die Frontpartie ist weitgehend identisch mit dem ID.4, mit durchgehendem LED-Lichtband und beleuchtetem VW-Logo (optional).',NULL,NULL,NULL,NULL,5,2021,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-id.7-1.-generation','Volkswagen','ID.7','1. Generation',2023,NULL,'["Limousine", "Kombi"]','Obere Mittelklasse','Volkswagen Passat','Die 1. Generation des ID.7 zeichnet sich durch eine flache, aerodynamische Silhouette mit einer coupéhaften Dachlinie aus. Typisch sind das durchgehende LED-Lichtband an Front und Heck, die markanten, schmalen LED-Scheinwerfer und die prägnante C-Säule. Im Vergleich zu anderen ID.-Modellen wirkt der ID.7 gestreckter und eleganter, mit einem Fokus auf Effizienz und Langstreckenkomfort.',NULL,NULL,NULL,NULL,5,2023,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b1','Volkswagen','Passat','B1',1973,1981,'["Limousine", "Variant"]','Mittelklasse',NULL,'Der Passat B1 zeichnet sich durch sein von Giorgetto Giugiaro entworfenes, klares und kantiges Design aus. Die Frontpartie ist typischerweise mit rechteckigen Scheinwerfern versehen, wobei nach dem Facelift auch runde Doppelscheinwerfer erhältlich waren. Die Karosserie weist eine leichte Keilform auf. Im Vergleich zum Nachfolger B2 ist der B1 kompakter, hat eine weniger ausgeprägte C-Säule bei den Limousinen und eine insgesamt einfachere, weniger voluminöse Formgebung.','Das Facelift erfolgte 1977 (Modelljahr 1978). Wesentliche Änderungen umfassten eine überarbeitete Frontpartie mit neuen, größeren Kunststoffstoßfängern (ersetzen die vorherigen Chromstoßstangen), einen geänderten Kühlergrill und neue Heckleuchten. Optional waren nach dem Facelift auch runde Doppelscheinwerfer erhältlich.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b2','Volkswagen','Passat','B2',1981,1988,'["Limousine", "Variant", "Fließheck"]','Mittelklasse','volkswagen-passat-b1','Der Passat B2 zeichnet sich durch seine kantigere und größere Karosserie im Vergleich zum Vorgänger B1 aus. Die Frontpartie dominieren rechteckige Scheinwerfer, die oft bündig mit dem Kühlergrill abschließen. Die Limousinen-Variante (anfangs als Santana vermarktet) besitzt ein deutlich abgesetztes Stufenheck, während die Fließheck-Modelle eine große Heckklappe aufweisen. Die Seitenlinie ist geradliniger und weniger abgerundet als beim B1.','Im Jahr 1985 erfolgte ein Facelift, bei dem die Frontpartie überarbeitet wurde. Die Scheinwerfer und der Kühlergrill wurden leicht modifiziert, oft mit einer stärker integrierten Optik. Die Stoßfänger wurden modernisiert und waren nun oft in Wagenfarbe lackiert oder mit größeren Kunststoffelementen versehen. Auch die Heckleuchten erhielten ein leicht geändertes Design.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b3','Volkswagen','Passat','B3',1988,1993,'["Limousine", "Variant"]','Mittelklasse','volkswagen-passat-b2','Der Passat B3 zeichnet sich durch seine für die damalige Zeit sehr aerodynamische Form und insbesondere durch die markante, grilllose Front aus. Die Scheinwerfer und der Kühlergrill sind nahtlos in die Karosserie integriert, wobei der Lufteinlass unterhalb des Stoßfängers platziert ist. Im Vergleich zum Vorgänger B2 wirkt er deutlich runder und moderner, mit einer glatteren Seitenlinie und bündig abschließenden Scheiben.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b4','Volkswagen','Passat','B4',1993,1997,'["Limousine", "Variant"]','Mittelklasse','volkswagen-passat-b3','Der Passat B4 unterscheidet sich deutlich vom Vorgänger B3 durch eine komplett neu gestaltete Frontpartie mit einem konventionellen Kühlergrill (der B3 hatte keinen sichtbaren Kühlergrill). Die Scheinwerfer sind ebenfalls neu und größer, die Stoßfänger wurden überarbeitet. Am Heck sind die Rückleuchten, insbesondere beim Variant, leicht modifiziert.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b5','Volkswagen','Passat','B5',1996,2005,'["Limousine", "Variant"]','Mittelklasse','volkswagen-passat-b4','Der Passat B5 zeichnet sich durch eine deutlich rundere und fließendere Karosserie im Vergleich zum kantigeren Vorgänger B4 aus. Die Frontpartie ist V-förmig gestaltet, mit integrierten Scheinwerfern und einem schmalen Kühlergrill. Die Seitenlinie ist glatt, und die Heckleuchten sind horizontal angeordnet und in die Karosserie integriert. Er basiert auf der Plattform des Audi A4 B5, was sich in einem längs eingebauten Motor und einem längeren Vorderwagen widerspiegelt.','Das Facelift (oft als B5.5 bezeichnet) erfolgte im Herbst 2000 (Modelljahr 2001). Die auffälligsten Änderungen sind die neuen, größeren Klarglas-Scheinwerfer, die oft mit Chromapplikationen versehen sind. Der Kühlergrill wurde vergrößert und erhielt mehr Chrom. Die Stoßfänger vorne und hinten wurden neu gestaltet, und die Rückleuchten erhielten eine überarbeitete Optik, teilweise mit runden Elementen. Im Innenraum gab es kleinere Anpassungen an Materialien und Bedienelementen.',NULL,NULL,NULL,3,1997,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b6','Volkswagen','Passat','B6',2005,2010,'["Limousine", "Variant"]','Mittelklasse','volkswagen-passat-b5','Der Passat B6 zeichnet sich durch eine markante, V-förmige Chrom-Kühlergrill-Einheit aus, die sich deutlich vom horizontalen Grill des Vorgängers B5 unterscheidet. Die Scheinwerfer sind größer und integrierter in die Frontpartie, nicht mehr so schmal und geteilt wie beim B5.5. Die Karosserie wirkt insgesamt kantiger und dynamischer, mit einer höheren Gürtellinie und einer stärker ausgeprägten Schulterlinie.',NULL,NULL,NULL,NULL,5,2005,15000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b7','Volkswagen','Passat','B7',2010,2014,'["Limousine", "Variant"]','Mittelklasse','volkswagen-passat-b6','Der Passat B7 ist eine umfassende Weiterentwicklung des Vorgängers B6. Er unterscheidet sich durch eine komplett neu gestaltete Frontpartie mit breiterem, aufrechterem Kühlergrill und markanteren Scheinwerfern, die oft LED-Tagfahrlicht integrieren. Am Heck fallen die breiteren, zweigeteilten Rückleuchten auf, die sich bis in die Kofferraumklappe ziehen. Die Seitenlinie ist dem B6 ähnlich, jedoch wurden die Stoßfänger und Felgendesigns überarbeitet.',NULL,NULL,NULL,NULL,5,2010,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-passat-b8','Volkswagen','Passat','B8',2014,2023,'["Limousine", "Variant", "Alltrack"]','Mittelklasse','volkswagen-passat-b7','Der Passat B8 zeichnet sich durch eine deutlich schärfere und prägnantere Linienführung im Vergleich zum runderen Vorgänger B7 aus. Die flacheren, breiteren Scheinwerfer schließen direkt an den Kühlergrill an, der vier Chromlamellen aufweist, die optisch in die Scheinwerfer übergehen. Eine markante Sicke verläuft unterhalb der Fensterlinie von den Scheinwerfern bis zu den schmaleren, horizontal ausgerichteten Rückleuchten. Der Radstand ist länger, die Überhänge kürzer.','Das Facelift (Modelljahr 2019, vorgestellt 2018) brachte überarbeitete Stoßfänger vorne und hinten, neue LED-Scheinwerfer und -Rückleuchten (hinten mit dynamischem Blinklicht), einen leicht modifizierten Kühlergrill und neue Felgendesigns. Im Innenraum gab es ein neues Lenkrad, aktualisierte Infotainmentsysteme (MIB3) und eine verbesserte Digitalisierung des Cockpits (Digital Cockpit Pro).',NULL,NULL,NULL,5,2014,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-i','Volkswagen','Polo','I',1975,1981,'["Schrägheck", "Coupé", "Stufenheck"]','Kleinwagen',NULL,'Der Polo I zeichnet sich durch seine kantige, kompakte Form aus. Die Front ist geprägt von runden Scheinwerfern und einem schmalen Kühlergrill, der oft in die Karosseriefarbe integriert ist. Die Heckleuchten sind klein und rechteckig. Im Vergleich zum späteren Polo II ist er deutlich kleiner und weniger abgerundet.','Im Jahr 1979 erhielt der Polo I ein Facelift. Die markantesten Änderungen waren die Einführung von rechteckigen Scheinwerfern anstelle der ursprünglichen runden, ein überarbeiteter Kühlergrill mit integriertem VW-Logo und neue Stoßfänger aus Kunststoff. Auch die Heckleuchten wurden leicht modifiziert.',NULL,NULL,NULL,NULL,NULL,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-ii','Volkswagen','Polo','II',1981,1994,'["Schräghecklimousine", "Kombi"]','Kleinwagen','volkswagen-polo-i','Der Polo II unterscheidet sich deutlich vom Vorgänger durch seine kantigere Form und die nunmehr vier Scheinwerfer (bei vielen Modellen). Die Seitenlinie ist flacher und die Fensterflächen größer. Die Heckleuchten sind horizontaler und breiter gestaltet.','1985 wurde der Polo II überarbeitet. Äußerlich erkennbar an geänderten Stoßfängern, neuen Radkappen und teilweise anderen Kühlergrills. Technisch gab es Anpassungen bei den Motoren und Fahrwerk.',NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-iii','Volkswagen','Polo','III',1994,2002,'["Schrägheck", "Stufenheck", "Kombi"]','Kleinwagen','volkswagen-polo-ii','Der Polo III (intern 6N) zeichnet sich durch ein deutlich runderes und moderneres Design im Vergleich zum kantigen Vorgänger aus. Er besitzt große, ovale Scheinwerfer, die in die abgerundete Front integriert sind, sowie eine kompaktere, fließendere Karosserieform. Die Heckleuchten sind ebenfalls runder und breiter als beim Polo II.','Im Jahr 1999 erfolgte ein umfassendes Facelift (intern 6N2). Die Frontpartie wurde komplett überarbeitet mit klaren, leicht eckigeren Scheinwerfern und einem neuen Kühlergrill. Die Stoßfänger wurden modifiziert und die Heckleuchten erhielten ein neues Design. Im Innenraum gab es ein neues Armaturenbrett, verbesserte Materialien und eine modernere Mittelkonsole. Auch die Karosseriestruktur wurde leicht überarbeitet, um die Steifigkeit zu erhöhen.',NULL,NULL,NULL,3,1997,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-iv','Volkswagen','Polo','IV',2001,2009,'["Schräghecklimousine", "Kombi"]','Kleinwagen','volkswagen-polo-iii','Der Polo IV (9N) unterscheidet sich deutlich vom Vorgänger (6N2). Auffällig sind die runden Doppelscheinwerfer, die eine neue Designsprache einleiteten. Die Karosserie wurde kantiger und moderner gestaltet, die Heckleuchten erhielten eine horizontale Ausrichtung. Die C-Säule wurde breiter und integrierter in die Gesamtform.','Das Facelift im Jahr 2005 brachte eine überarbeitete Front mit neuen Scheinwerfern und Stoßfängern. Auch die Heckleuchten wurden modifiziert und die Heckklappe erhielt ein neues Design. Im Innenraum gab es Änderungen am Armaturenbrett und an der Mittelkonsole.',NULL,NULL,NULL,4,2002,NULL,'24 Monate','Der Polo IV gilt als solider Kleinwagen mit guter Verarbeitung. Achten Sie auf Rost an den Radläufen und Schwellern, insbesondere bei älteren Modellen. Probleme mit der Elektrik können auftreten, vor allem bei Fensterhebern und Zentralverriegelung. Die Motoren sind generell robust, aber regelmäßige Wartung ist wichtig.','2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-v','Volkswagen','Polo','V',2009,2017,'["Schrägheck", "Stufenheck"]','Kleinwagen','volkswagen-polo-iv','Der Polo V (Typ 6R) unterscheidet sich vom Vorgänger (Polo IV, Typ 9N/9N3) durch eine deutlich schärfere und kantigere Linienführung. Die Front ist geprägt von einem breiteren, flacheren Kühlergrill, der optisch mit den eckigeren Scheinwerfern eine Einheit bildet. Die Scheinwerfer ziehen sich weiter in die Kotflügel hinein. Am Heck sind die Leuchten breiter und horizontaler ausgerichtet, was dem Fahrzeug eine gestrecktere Optik verleiht.','Das Facelift (Typ 6C) im Jahr 2014 brachte eine leicht überarbeitete Frontschürze mit neuen Nebelscheinwerfern und optionalen LED-Tagfahrleuchten in den Hauptscheinwerfern. Die Heckschürze wurde ebenfalls dezent modifiziert, und die Rückleuchten erhielten eine neue Innenstruktur. Im Innenraum gab es ein neues Lenkrad und überarbeitete Infotainmentsysteme.',NULL,NULL,NULL,5,2009,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-polo-vi','Volkswagen','Polo','VI',2017,NULL,'["Schrägheck"]','Kleinwagen','volkswagen-polo-v','Der Polo VI (interne Bezeichnung AW) ist deutlich größer und breiter als sein Vorgänger, der Polo V. Er zeichnet sich durch schärfere, horizontal betonte Linien und eine flachere Silhouette aus. Die Scheinwerfer sind schmaler und ziehen sich weiter in die Kotflügel. Im Gegensatz zum Vorgänger gibt es den Polo VI ausschließlich als Fünftürer. Ein weiteres Merkmal ist das optionale Digital Cockpit im Innenraum.','Das Facelift im Jahr 2021 brachte eine umfassende Überarbeitung. Die Front erhielt neue Stoßfänger und optional die IQ.LIGHT LED-Matrix-Scheinwerfer, die durch ein durchgehendes LED-Lichtband im Kühlergrill verbunden sind. Am Heck wurden die Rückleuchten neu gestaltet und reichen nun bis in die Heckklappe hinein. Im Innenraum gab es ein neues Lenkrad, ein aktualisiertes Infotainmentsystem und Touch-Bedienfelder für die Klimaanlage.',NULL,'5',NULL,5,2017,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-sharan-i','Volkswagen','Sharan','I',1995,2010,'["Großraumlimousine"]','Großraum-Van',NULL,'Der Sharan I zeichnet sich durch seine kastenförmige, hohe Karosserie mit großen Fensterflächen aus. Die Front ist eher rundlich gestaltet, mit großen, rechteckigen Scheinwerfern und einem schmalen Kühlergrill, der oft durch eine horizontale Lamelle unterbrochen wird. Die Heckleuchten sind vertikal angeordnet und reichen bis in die D-Säule. Im Vergleich zum Nachfolger (Sharan II) fehlen ihm die Schiebetüren und die deutlich modernere, dynamischere Linienführung.','Im Jahr 2000 erfolgte ein umfassendes Facelift (oft als ''Sharan GP0'' oder ''Sharan 2000'' bezeichnet). Die Front wurde komplett überarbeitet mit neuen, größeren Klarglas-Doppelscheinwerfern, einem markanteren Kühlergrill mit Chromapplikationen und einer neuen Stoßstange. Die Heckleuchten erhielten eine neue Optik mit runden Elementen und die Heckklappe wurde leicht modifiziert. Im Innenraum wurden das Armaturenbrett, die Mittelkonsole und die Türverkleidungen erneuert, um eine modernere Anmutung zu erzielen.',NULL,NULL,NULL,3,1999,NULL,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-sharan-ii','Volkswagen','Sharan','II',2010,2022,'["Van", "Großraumlimousine"]','Van','volkswagen-sharan-i','Der Sharan II unterscheidet sich deutlich vom Vorgänger durch ein moderneres, kantigeres Design. Die Frontpartie ist geprägt von einem breiteren, flacheren Kühlergrill mit horizontalen Lamellen, der nahtlos in die schärfer gezeichneten, rechteckigen Scheinwerfer übergeht. Die Seitenlinie ist gestreckter und die Heckklappe weniger abgerundet als beim Sharan I.','Im Jahr 2015 erfolgte ein Facelift (intern als GP bezeichnet). Äußerlich erkennbar an leicht modifizierten LED-Rückleuchten, neuen Felgendesigns und einer leicht überarbeiteten Frontschürze. Im Innenraum gab es neue Infotainmentsysteme und Assistenzsysteme sowie eine Anpassung der Motorenpalette an die Euro-6-Norm.',NULL,NULL,NULL,5,2010,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-t-cross-c1','Volkswagen','T-Cross','C1',2019,NULL,'["SUV"]','Kleinwagen-SUV',NULL,'Der T-Cross C1 ist ein kompaktes SUV, das sich durch seine erhöhte Sitzposition und eine eigenständige Designsprache vom VW Polo abhebt, auf dessen Plattform er basiert. Charakteristisch sind die breite Front mit integrierten Scheinwerfern und einem markanten Kühlergrill. Am Heck zieht sich ein durchgehendes Leuchtenband über die gesamte Breite der Heckklappe, das die Rückleuchten miteinander verbindet. Die Karosserie wirkt robust und bietet eine gute Übersichtlichkeit.','Das Facelift (Modelljahr 2024, vorgestellt 2023) brachte eine überarbeitete Front- und Heckpartie mit neuen Stoßfängern und einer modifizierten Lichtsignatur, optional mit IQ.Light LED-Matrix-Scheinwerfern. Im Innenraum wurden die Materialien aufgewertet und ein neues Infotainmentsystem mit freistehendem Display eingeführt. Zudem gab es neue Außenfarben und Felgendesigns.',NULL,NULL,NULL,5,2019,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-t-roc-a1','Volkswagen','T-Roc','A1',2017,NULL,'["SUV", "Cabriolet"]','Kompakt-SUV',NULL,'Die erste Generation des T-Roc (A1) zeichnet sich durch eine markante Frontpartie mit breitem Kühlergrill aus, in den die LED-Tagfahrlichter (vor dem Facelift oft C-förmig) integriert sind. Die Scheinwerfer sind schmal und ziehen sich weit in die Kotflügel. Typisch sind auch die oft zweifarbige Lackierung mit abgesetztem Dach und die relativ kompakten Abmessungen. Im Vergleich zu größeren VW-SUVs wie dem Tiguan wirkt der T-Roc sportlicher und jugendlicher.','Das Facelift im Jahr 2021 brachte eine überarbeitete Frontpartie mit einem durchgehenden LED-Lichtband zwischen den Scheinwerfern (optional) und einer neu gestalteten Lichtsignatur. Die Stoßfänger wurden modifiziert und die Tagfahrlichter sind nun in die Hauptscheinwerfer integriert. Im Innenraum wurde das Infotainmentsystem modernisiert und die Bedienelemente für die Klimaanlage wurden digitalisiert (Touch-Slider statt Drehregler).',NULL,NULL,NULL,5,2017,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-taigo-2020','Volkswagen','Taigo','1. Generation (C1)',2020,NULL,'["SUV-Coupé"]','Kleinwagen-SUV',NULL,'Der Taigo basiert auf dem Polo VI und T-Cross, unterscheidet sich aber durch seine coupéhafte Dachlinie, die am Heck stark abfällt. Er verfügt über eine durchgehende Lichtleiste an der Front, die die Scheinwerfer verbindet, sowie eine ähnliche Lichtleiste am Heck. Die Frontscheinwerfer sind schmal und ziehen sich weit in die Kotflügel. Im Vergleich zum T-Cross ist er länger und flacher.',NULL,NULL,NULL,NULL,5,2022,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-tiguan-i','Volkswagen','Tiguan','I',2007,2016,'["SUV"]','Kompakt-SUV',NULL,'Die erste Generation des Tiguan zeichnet sich durch eine kompakte, eher rundliche Karosserie aus. Vor dem Facelift (bis 2011) besitzt er markante, runde Scheinwerfer und einen Kühlergrill mit drei horizontalen Lamellen. Nach dem Facelift (ab 2011) sind die Scheinwerfer eckiger und stärker in den nun zweilamelligen Kühlergrill integriert, oft mit optionalen LED-Tagfahrlichtern. Die Heckleuchten sind vor dem Facelift eher schlicht, nach dem Facelift zeigen sie eine L-förmige Lichtsignatur. Im Vergleich zum Nachfolger (Tiguan II) wirkt der Tiguan I deutlich weniger kantig und moderner.','Das Facelift erfolgte im Jahr 2011. Die Front wurde umfassend überarbeitet: Die Scheinwerfer erhielten eine eckigere Form und waren optional mit Bi-Xenon und LED-Tagfahrlicht erhältlich. Der Kühlergrill wurde von drei auf zwei Chromlamellen reduziert und der Stoßfänger neu gestaltet. Am Heck wurden die Rückleuchten mit einer neuen L-förmigen Lichtsignatur versehen und der hintere Stoßfänger angepasst. Im Innenraum gab es kleinere Änderungen bei den Materialien und dem Lenkrad.',NULL,NULL,NULL,5,2007,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-tiguan-ii','Volkswagen','Tiguan','II',2016,NULL,'["SUV"]','Kompakt-SUV','volkswagen-tiguan-i','Der Tiguan II zeichnet sich durch ein deutlich schärferes und kantigeres Design im Vergleich zum Vorgänger aus. Die Front ist geprägt von einer breiteren, horizontal ausgerichteten Kühlergrill-Einheit, die nahtlos in die schmaleren, eckigeren Scheinwerfer übergeht. Die Seitenlinie ist dynamischer mit einer markanten Schulterlinie, die sich von den vorderen Kotflügeln bis zu den Rückleuchten zieht. Die Heckleuchten sind breiter und flacher, oft mit einer charakteristischen LED-Grafik.','Das Facelift im Jahr 2020 brachte eine überarbeitete Frontpartie mit einem breiteren Kühlergrill, der nun das neue VW-Logo trägt, und neu gestalteten Scheinwerfern, die optional als IQ.LIGHT LED-Matrix-Scheinwerfer erhältlich waren. Der vordere Stoßfänger wurde ebenfalls modifiziert. Am Heck gab es neue LED-Grafiken für die Rückleuchten und einen überarbeiteten Stoßfänger. Im Innenraum wurden ein neues Lenkrad und touch-sensitive Bedienelemente für die Klimaanlage eingeführt.',NULL,'5.8','überdurchschnittlich',5,2016,30000,'2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-touareg-i','Volkswagen','Touareg','I',2002,2010,'["SUV"]','Obere Mittelklasse',NULL,'Die erste Generation des Touareg zeichnet sich durch eine kräftige, aber noch relativ runde Karosserieform aus. Vor dem Facelift (bis 2006) sind die Scheinwerfer markant rundlich gestaltet. Nach dem Facelift (ab 2007) wurden die Scheinwerfer leicht eckiger und erhielten eine ''Tränenform'' an der Innenseite, zudem wurde der Kühlergrill überarbeitet. Im Vergleich zum Nachfolger (Touareg II) wirkt die erste Generation massiver und weniger stromlinienförmig, mit einer deutlich weniger integrierten Frontpartie.','Das Facelift erfolgte Ende 2006 (Modelljahr 2007). Die markantesten Änderungen betrafen die Frontpartie: Neue, leicht eckigere Scheinwerfer (nicht mehr rein rund), ein überarbeiteter Kühlergrill mit mehr Chrom und ein neuer Stoßfänger. Auch die Heckleuchten erhielten eine leicht modifizierte Grafik. Im Innenraum gab es kleinere Anpassungen bei Materialien und Infotainment-Optionen.',NULL,NULL,NULL,5,2004,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-touareg-ii','Volkswagen','Touareg','II',2010,2018,'["SUV"]','Obere Mittelklasse SUV','volkswagen-touareg-i','Der Touareg II (Typ 7P) ist im Vergleich zum Vorgänger (Typ 7L) deutlich eleganter und weniger kantig gestaltet. Die Front zeichnet sich durch schmalere, horizontal ausgerichtete Scheinwerfer aus, die direkt in den breiteren Kühlergrill übergehen. Die erste Generation hatte rundlichere, stärker abgesetzte Scheinwerfer. Die Heckleuchten des Touareg II sind ebenfalls breiter und flacher, oft mit LED-Technik, während die des Vorgängers höher und schmaler waren. Die Karosserie wirkt insgesamt gestreckter und aerodynamischer.','Im Jahr 2014 erhielt der Touareg II ein Facelift. Die markantesten Änderungen umfassen eine neu gestaltete Front mit serienmäßigen Bi-Xenon-Scheinwerfern und einem Kühlergrill mit vier statt zwei horizontalen Chromlamellen. Die Stoßfänger vorne und hinten wurden ebenfalls modifiziert. Am Heck wurden die LED-Rückleuchten überarbeitet und die Nebelschlussleuchten in den Stoßfänger integriert. Im Innenraum gab es kleinere Detailänderungen, wie neue Aluminium-Drehschalter und eine erweiterte Farbauswahl für die Lederpolsterung.',NULL,NULL,NULL,5,2010,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-touareg-iii','Volkswagen','Touareg','III',2018,NULL,'["SUV"]','Obere Mittelklasse','volkswagen-touareg-ii','Der Touareg III zeichnet sich durch eine deutlich breitere Front mit einem großen Kühlergrill aus, der nahtlos in die schmalen, scharf gezeichneten LED-Scheinwerfer übergeht. Im Vergleich zum Vorgänger wirkt er flacher und breiter. Am Heck sind die Rückleuchten ebenfalls schmaler und breiter gezogen, oft durch eine Chromleiste verbunden. Im Innenraum dominiert das ''Innovision Cockpit'' mit zwei großen, miteinander verbundenen Bildschirmen.','Das Facelift im Jahr 2023 brachte eine überarbeitete Front mit einem neuen Kühlergrill und neu gestalteten IQ.Light HD-Matrix-Scheinwerfern, die nun über 38.400 LEDs pro Scheinwerfer verfügen. Am Heck wurde das VW-Logo beleuchtet und die Rückleuchten erhielten eine neue Lichtsignatur mit drei L-förmigen Elementen. Zudem wurden Fahrwerk und Lenkung optimiert.',NULL,NULL,NULL,5,2018,30000,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-touran-i','Volkswagen','Touran','I',2003,2015,'["Kompaktvan"]','Kompaktvan',NULL,'Der Touran I zeichnet sich durch seine funktionale, leicht kastenförmige Karosserie mit abgerundeten Kanten aus. Die Front ist geprägt von großen, rechteckigen Scheinwerfern und einem breiten Kühlergrill, der oft eine Chromspange trägt. Am Heck fallen die hohen, vertikalen Rückleuchten auf, die bis in die D-Säule reichen. Im Vergleich zum Nachfolger (Touran II) wirkt er weniger dynamisch und hat eine deutlich weniger integrierte Frontpartie, bei der Scheinwerfer und Kühlergrill klar voneinander getrennt sind.','Der Touran I erhielt zwei größere Facelifts. Das erste Facelift (GP, ab Ende 2006) brachte eine neue Frontpartie mit einem breiteren, V-förmigen Kühlergrill, der an den Golf V erinnerte, sowie leicht modifizierte Scheinwerfer. Die Heckleuchten wurden ebenfalls leicht überarbeitet. Das zweite Facelift (GP2, ab 2010) führte eine komplett neue Front ein, die sich stark am Design des Golf VI orientierte, mit schmaleren, horizontal ausgerichteten Scheinwerfern und einem flacheren Kühlergrill. Auch die Heckleuchten wurden erneut angepasst und erhielten eine modernere Optik.',NULL,NULL,NULL,5,2003,30000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-touran-ii','Volkswagen','Touran','II',2015,NULL,'["Van"]','Kompakt-Van','volkswagen-touran-i','Der Touran II unterscheidet sich vom Vorgänger durch eine deutlich gestrecktere und flachere Silhouette. Die Scheinwerfer sind schmaler und integrieren sich stärker in den Kühlergrill. Die Heckleuchten sind horizontaler und breiter gestaltet. Die Linienführung der Seitenwände ist klarer und weniger stark konturiert.','Im Jahr 2020 erhielt der Touran ein Facelift. Äußerlich erkennbar an einer leicht modifizierten Frontschürze und einem überarbeiteten Kühlergrill. Die Scheinwerfer erhielten eine neue Lichtsignatur mit LED-Technologie. Am Heck gab es dezente Anpassungen an der Stoßstange. Im Innenraum wurden das Infotainmentsystem und die digitalen Instrumente aktualisiert.',NULL,NULL,NULL,5,2015,NULL,'24 Monate',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-up-up','Volkswagen','Up','Up',2011,2023,'["3-Türer", "5-Türer"]','Kleinstwagen','volkswagen-fox-fox','Der Volkswagen Up zeichnet sich durch seine kompakte, kastenförmige Karosserie mit kurzen Überhängen aus. Die Frontpartie ist geprägt von einer schmalen, fast lächelnden Kühlergrillöffnung und großen, leicht abgerundeten Scheinwerfern. Ein markantes Merkmal am Heck ist die große, komplett schwarz gehaltene Glasheckklappe, die sich deutlich vom Vorgänger Volkswagen Fox abhebt, welcher eine konventionelle, lackierte Heckklappe besaß.','Das Facelift im Jahr 2016 brachte eine überarbeitete Frontschürze mit neu gestalteten Nebelscheinwerfern und einem integrierten Tagfahrlicht. Die Scheinwerfer erhielten eine neue Innenstruktur, und die Rückleuchten wurden ebenfalls leicht modifiziert. Im Innenraum gab es neue Dekorleisten und Infotainmentsysteme. Die Motorenpalette wurde um einen 1.0 TSI Turbomotor erweitert.',NULL,NULL,NULL,5,2011,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO baureihe (id,marke,modell,generation,bauzeitraum_von,bauzeitraum_bis,karosserie,segment,vorgaenger,erkennung_generation,facelift_merkmale,adac_pannenkennziffer,tuev_maengelquote,dekra_urteil,euro_ncap_sterne,euro_ncap_jahr,wartung_oel_km,wartung_hu_intervall,kaufberatung,letzte_aktualisierung,chassis_codes,verification) VALUES ('volkswagen-up-up-(facelift)','Volkswagen','Up','Up (Facelift)',2016,2023,'["3-Türer", "5-Türer"]','Kleinstwagen','volkswagen-up-up-(vor-facelift)','Das Facelift des VW Up ist erkennbar an der neu gestalteten Frontschürze mit integrierten Nebelscheinwerfern und einem markanteren Kühlergrill. Die Scheinwerfer erhielten ein neues Innenleben mit serienmäßigem LED-Tagfahrlicht. Am Heck wurden die Rückleuchten überarbeitet und erhielten eine neue Grafik. Im Innenraum gab es ein neues Infotainmentsystem und neue Dekorleisten.','Das Facelift brachte eine umfassende optische und technische Überarbeitung. Äußerlich fielen die neue Frontschürze mit breiterem Kühlergrill und integrierten Nebelscheinwerfern sowie das serienmäßige LED-Tagfahrlicht auf. Die Rückleuchten erhielten eine neue Lichtsignatur. Im Innenraum wurde das Armaturenbrett mit neuen Dekorleisten aufgewertet und ein neues Infotainmentsystem mit Smartphone-Integration (Composition Phone) eingeführt. Zudem gab es neue Außenfarben und Felgendesigns. Technisch wurden neue Motoren, darunter ein 1.0 TSI mit 90 PS, angeboten.',NULL,NULL,NULL,3,2017,15000,'Alle 2 Jahre',NULL,'2026-06',NULL,NULL);
INSERT INTO motorvariante (variante_id,baureihe_id,bezeichnung,motorcode,kraftstoff,hubraum_ccm,zylinder,leistung_ps,leistung_kw,drehmoment_nm,getriebe,antrieb,beschleunigung_0_100,vmax_kmh,verbrauch_wltp,verbrauch_real,co2_g_km,neupreis_ca_eur,heck_emblem,optische_unterscheidung,tankgroesse_liter,kofferraum_liter,batteriekapazitaet_kwh,anhaengelast_gebremst_kg,anhaengelast_ungebremst_kg,abgasnorm,felgengroesse_serie) VALUES ('audi-a1-8x-1-0-tfsi','audi-a1-8x','1.0 TFSI','CHZ','Benzin',999,3,95,70,160,'["manuell", "automatik"]','Front',10.9,186,4.7,NULL,107,NULL,'30 TFSI','Ein Endrohr',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
