INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (24,'bmw-3er-g20-g21','Basis','Basis','Serienausstattung, 17-Zoll-Leichtmetallräder, LED-Scheinwerfer, Sport-Lederlenkrad, Klimaautomatik.','Die Grundausstattung ohne spezifische Design- oder Sportpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (25,'bmw-3er-g20-g21','Sport Line','Ausstattungslinie','Schwarz hochglänzende Exterieur-Details (Niere, Lufteinlässe), spezifische Leichtmetallräder, Sportsitze, rote Kontrastnähte im Innenraum.','Betont den sportlichen Charakter mit spezifischen Designelementen und Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (26,'bmw-3er-g20-g21','Luxury Line','Ausstattungslinie','Chrom-Applikationen an Niere und Lufteinlässen, spezifische Leichtmetallräder, Edelholz-Interieurleisten, Lederausstattung.','Fokus auf Eleganz und Komfort mit hochwertigeren Materialien und Chrom-Akzenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (27,'bmw-3er-g20-g21','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze, M spezifische Interieurleisten.','Verleiht dem Fahrzeug ein deutlich sportlicheres Erscheinungsbild und verbessert die Fahrdynamik durch M-spezifische Komponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (28,'bmw-3er-g20-g21','M Performance','M Performance','Exklusive M Performance Designelemente (z.B. Cerium Grey Akzente an Niere, Spiegelkappen, trapezförmige Auspuffendrohre), M Sportbremse, M Sportdifferenzial (optional).','Für die Top-Motorisierungen (z.B. M340i/d), die eine Brücke zu den echten M-Modellen schlagen. Bietet gesteigerte Leistung und eine noch sportlichere Ausstattung als das M Sport Paket.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (44,'bmw-2er-coupe-f22','Basis','Basis','Standard-Stoßfänger, 16-Zoll-Leichtmetallräder, schwarze Fensterrahmen','Grundausstattung ohne spezifische Designelemente.');
