INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (46,'bmw-2er-coupe-f22','Luxury Line','Ausstattungslinie','Chrom-Applikationen an Nieren und Stoßfängern, edle Interieurleisten, Lederausstattung, 17-Zoll-Leichtmetallräder','Fokus auf Eleganz und Komfort mit hochwertigeren Materialien und Chrom-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (47,'bmw-2er-coupe-f22','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Stoßfänger, Seitenschweller), M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze','Umfassendes Sportpaket mit optischen und technischen Upgrades, die an die M-Modelle angelehnt sind.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (48,'bmw-2er-coupe-f22','M240i','M Performance','Eigenständige Frontschürze, spezifische Außenspiegelkappen (Cerium Grey), M Performance Abgasanlage, 18-Zoll-M-Leichtmetallräder','Leistungsstarkes M Performance Modell mit spezifischen Designelementen und technischen Verbesserungen gegenüber den regulären Modellen.');
