INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (57,'bmw-2er-active-tourer-f45','Sport Line','Ausstattungslinie','Sportliche Stoßfänger, spezifische Leichtmetallräder, Sportsitze, rote Akzente im Innenraum, schwarze Hochglanz-Zierelemente','Betont den sportlichen Charakter mit spezifischen Designelementen innen und außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (58,'bmw-2er-active-tourer-f45','Luxury Line','Ausstattungslinie','Chrom-Applikationen außen, spezifische Leichtmetallräder, Lederausstattung, Edelholz- oder Aluminium-Interieurleisten','Fokus auf Eleganz und hochwertige Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (59,'bmw-2er-active-tourer-f45','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Leichtmetallräder, M Sportfahrwerk, Sportsitze, M Lederlenkrad, M spezifische Interieurleisten','Sportlichste Ausstattungslinie mit optischen und fahrwerkstechnischen Verbesserungen, aber kein echtes M-Modell.');
