INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (63,'bmw-2er-coupe-g42','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, weniger Chrom-Applikationen.','Die Grundausstattung ohne spezifische Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (64,'bmw-2er-coupe-g42','M Sport','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, M-spezifische Felgen, M Sportfahrwerk, M Sportlenkrad, Sportsitze.','Betont den sportlichen Charakter des Fahrzeugs mit optischen und fahrwerksseitigen Anpassungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (65,'bmw-2er-coupe-g42','M Performance (M240i xDrive)','M Performance','Eigenständige Designelemente, größere Lufteinlässe, spezifische Außenspiegelkappen, trapezförmige Endrohre, M Performance Bremsanlage.','Stellt die Top-Motorisierung unterhalb des echten M2 dar, mit deutlichen Leistungs- und Fahrdynamik-Verbesserungen sowie spezifischer Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (66,'bmw-4er-f32-f33-f36','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Designelemente.','Grundausstattung ohne spezifische Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (67,'bmw-4er-f32-f33-f36','Sport Line','Ausstattungslinie','Schwarze Hochglanz-Akzente (Nieren, Lufteinlässe), rote Kontrastnähte im Innenraum, Sportlenkrad, Sportsitze.','Betont die sportliche Seite mit spezifischen Designelementen und Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (68,'bmw-4er-f32-f33-f36','Luxury Line','Ausstattungslinie','Chrom-Akzente (Nieren, Lufteinlässe), edlere Materialien im Innenraum, spezifische Felgen.','Fokus auf Eleganz und Komfort mit hochwertigeren Materialien und Chrom-Applikationen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (69,'bmw-4er-f32-f33-f36','M Sportpaket','Ausstattungslinie','Aggressivere M Aerodynamikpaket-Stoßfänger, M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze, M Fußstütze, M Einstiegsleisten.','Umfassendes Paket, das Optik, Fahrwerk und Interieur sportlicher gestaltet, aber noch kein echtes M-Modell ist.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (70,'bmw-4er-f32-f33-f36','M4','Echtes M-Modell','Breitere Kotflügel, spezifische M-Stoßfänger, Powerdome auf der Motorhaube, vier Endrohre, M-Spiegel, M-spezifische Felgen, M-Sportsitze, M-Lenkrad.','Eigenständiges Hochleistungsmodell mit deutlich modifizierter Technik (Motor, Fahrwerk, Bremsen) und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (71,'bmw-4er-g22-g23-g26','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Designelemente.','Die Grundausstattung ohne zusätzliche Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (72,'bmw-4er-g22-g23-g26','M Sport','Ausstattungslinie','Aggressivere Front- und Heckschürzen, M-spezifische Felgen, M Sportfahrwerk, M Sportlenkrad, Sportsitze.','Betont den sportlichen Charakter des Fahrzeugs mit optischen und technischen Upgrades.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (73,'bmw-4er-g22-g23-g26','M Performance (z.B. M440i)','M Performance','M Sportpaket serienmäßig, spezifische Außenspiegelkappen (Cerium Grey), trapezförmige Endrohre, M Performance Bremsanlage.','Stellt die Top-Modelle unterhalb der echten M-Modelle dar, mit leistungsstärkeren Motoren und sportlicherer Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (74,'bmw-4er-g22-g23-g26','M (z.B. M4)','Echtes M-Modell','Eigenständige Karosserie mit breiteren Kotflügeln, spezifische M-Niere, M-Außenspiegel, vier Endrohre, Carbon-Dach (optional), M-spezifische Felgen und Bremsanlage.','Die Hochleistungsmodelle von BMW M GmbH mit eigenständiger Technik, Motorisierung und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (75,'bmw-6er-e24','Basis (628 CSi, 630 CS, 633 CSi, 635 CSi)','Ausstattungslinie','Je nach Baujahr und Markt unterschiedliche Stoßstangen (Chrom oder Kunststoff), verschiedene Felgendesigns, optionale Lederausstattung und Klimaanlage.','Die Bezeichnungen beziehen sich primär auf die Motorisierung. Die Ausstattung konnte durch zahlreiche Optionen individualisiert werden.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (76,'bmw-6er-e24','M635CSi','Echtes M-Modell','M-Technic Front- und Heckschürze, M-Technic Seitenschweller, Heckspoiler, spezielle 16-Zoll-Kreuzspeichenfelgen, M-Embleme, Sportsitze im Innenraum, M-Lenkrad.','Das Topmodell der Baureihe mit dem Motor des M1 (S38B35), einem sportlich abgestimmten Fahrwerk und einer umfangreicheren Serienausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (77,'bmw-6er-e63-e64','Basis','Basis','Serienausstattung, je nach Baujahr und Markt variierend.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (78,'bmw-6er-e63-e64','M Sportpaket','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, M Leichtmetallräder, M Sportfahrwerk, Sportsitze, M Lederlenkrad.','Optionales Paket, das die Optik und das Fahrverhalten sportlicher gestaltet, aber kein echtes M-Modell ist.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (79,'bmw-6er-f12-f13-f06','Basis','Basis','Serienausstattung, je nach Markt und Baujahr mit unterschiedlichen Felgen und Interieur-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (80,'bmw-6er-f12-f13-f06','M Sportpaket','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, M Leichtmetallräder, M Sportfahrwerk, M Lederlenkrad, Sportsitze, spezielle Interieurleisten.','Betont den sportlichen Charakter des Fahrzeugs.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (81,'bmw-6er-f12-f13-f06','Individual','Ausstattungslinie','Umfangreiche Personalisierungsmöglichkeiten für Lackierungen, Lederfarben, Interieurleisten und spezielle Felgen.','Ermöglicht eine exklusive und individuelle Gestaltung des Fahrzeugs über die Standardoptionen hinaus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (82,'bmw-6er-f12-f13-f06','M6','Echtes M-Modell','Eigenständige, aggressivere Front- und Heckschürzen, M-spezifische Leichtmetallräder, M-Außenspiegel, Carbon-Dach (Coupé/Gran Coupé), M-Sportabgasanlage mit vier Endrohren, M-spezifisches Interieur mit Sportsitzen und M-Lenkrad.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor, Fahrwerk und Bremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (83,'bmw-6er-gran-turismo-g32','Basis','Basis','Serienausstattung, 17-Zoll-Leichtmetallräder, LED-Scheinwerfer, Chromzierleisten','Umfasst bereits eine gute Grundausstattung mit Komfort- und Sicherheitsfeatures.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (84,'bmw-6er-gran-turismo-g32','Luxury Line','Ausstattungslinie','Exklusive Chromapplikationen an Front und Heck, spezifische Leichtmetallräder (oft 19-Zoll), Lederausstattung, Edelholz-Interieurleisten.','Betont Eleganz und Komfort mit hochwertigeren Materialien und Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (85,'bmw-6er-gran-turismo-g32','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Leichtmetallräder (oft 19- oder 20-Zoll), M Sportfahrwerk, M Sportbremse (optional), M Sportlenkrad, Sportsitze, Interieurleisten in Aluminium oder Carbonoptik.','Fokus auf Sportlichkeit und Dynamik, sowohl optisch als auch fahrtechnisch.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (86,'bmw-8er-e31','Basis','Basis','Standard-Stoßfänger, je nach Motorisierung unterschiedliche Felgen und Auspuffendrohre.','Umfasste die Grundausstattung, die jedoch bereits sehr umfangreich war. Viele Optionen waren einzeln wählbar.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (87,'bmw-8er-e31','850CSi','Echtes M-Modell','Dezente M-Aerodynamik-Paket (Frontschürze, Seitenschweller, Heckschürze), M-Spiegel, spezielle 17-Zoll-Felgen, vierflutige Auspuffanlage, M-Embleme.','Von der BMW M GmbH entwickeltes Topmodell mit leistungsgesteigertem Motor, Sportfahrwerk und spezifischer Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (91,'bmw-8er-g15-g14-g16','Basis','Basis','Serienausstattung, je nach Markt und Baujahr mit unterschiedlichen Felgen und Interieur-Optionen.','Umfasst die Grundausstattung ohne spezifische Sport- oder Luxuspakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (92,'bmw-8er-g15-g14-g16','M Sport','Ausstattungslinie','Sportlichere Front- und Heckschürzen, M-spezifische Leichtmetallräder, M Sportbremse, M Sportlenkrad, Sportsitze.','Betont den sportlichen Charakter des Fahrzeugs, ohne ein echtes M-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (93,'bmw-8er-g15-g14-g16','M Performance','M Performance','Exklusive M Performance Designelemente, größere Bremsanlagen, spezifische Felgen, oft mit V8-Motoren (z.B. M850i).','Stellt die Brücke zwischen den zivilen Modellen und den reinrassigen M-Modellen dar, mit deutlich erhöhter Leistung und sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (94,'bmw-8er-g15-g14-g16','M','Echtes M-Modell','Aggressivere Aerodynamik-Pakete, M-spezifische Nieren, Außenspiegel, Auspuffanlagen mit vier Endrohren, M-Felgen, M-Sportsitze, M-spezifische Instrumente.','Die leistungsstärksten Varianten mit eigenständiger Fahrwerksabstimmung, Motorisierung und oft Allradantrieb mit Heckantriebsmodus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (95,'bmw-x1-e84','Basis','Basis','Standardausstattung, keine spezifischen Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (96,'bmw-x1-e84','xLine','Ausstattungslinie','Exterieur-Elemente in Titansilber matt (Nierenstäbe, Lufteinlässe, Unterfahrschutz), spezifische Leichtmetallräder, Interieur mit speziellen Stoff-/Lederkombinationen und Zierleisten.','Betont den robusten SUV-Charakter.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (97,'bmw-x1-e84','Sport Line','Ausstattungslinie','Exterieur-Elemente in Schwarz hochglänzend (Nierenstäbe, Lufteinlässe), spezifische Leichtmetallräder, Sportsitze, Interieur mit roten Akzenten und Zierleisten.','Betont den sportlichen Charakter.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (98,'bmw-x1-e84','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front-, Seiten- und Heckschürzen), M Sportfahrwerk, M Leichtmetallräder, Sportsitze, M Lederlenkrad, M Einstiegsleisten, Interieur mit Aluminium-Hexagon-Zierleisten.','Umfassendes Sportpaket für Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (99,'bmw-x1-f48','Advantage','Ausstattungslinie','Basis-Ausstattung, oft mit 17-Zoll-Leichtmetallrädern, Park Distance Control (PDC) hinten.','Erweitert die Serienausstattung um praktische Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (100,'bmw-x1-f48','Sport Line','Ausstattungslinie','Sportliche Akzente außen (z.B. schwarze Zierleisten, spezifische Stoßfänger), Sportsitze, rote Kontrastnähte im Innenraum, 18-Zoll-Leichtmetallräder.','Betont den dynamischen Charakter des Fahrzeugs.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (101,'bmw-x1-f48','xLine','Ausstattungslinie','Robuster Offroad-Look mit spezifischen Stoßfängern, Unterfahrschutz-Optik, matt-silbernen Akzenten, 18-Zoll-Leichtmetallrädern, Lederausstattung.','Hebt den SUV-Charakter hervor und bietet mehr Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (102,'bmw-x1-f48','M Sport','Ausstattungslinie','M Aerodynamikpaket, M Sportfahrwerk (optional), M Leichtmetallräder (18 oder 19 Zoll), Sportsitze, M Lederlenkrad, M spezifische Interieurleisten.','Maximale Sportlichkeit in Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (103,'bmw-x1-u11','Basis','Basis','Standard-Stoßfänger, 17-Zoll-Leichtmetallräder, schwarze Dachreling.','Grundausstattung ohne spezifische Design- oder Sportmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (104,'bmw-x1-u11','xLine','Ausstattungslinie','Spezifische Stoßfänger mit Unterfahrschutz-Optik, 18-Zoll-Leichtmetallräder, Aluminium-Dachreling, Akzente in Pearl Chrome.','Betont den robusten SUV-Charakter mit Offroad-Designelementen und hochwertigeren Materialien im Innenraum.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (105,'bmw-x1-u11','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), 18-Zoll-M-Leichtmetallräder, M Sportfahrwerk, M Hochglanz Shadow Line, M Lederlenkrad.','Fokus auf sportliche Optik und Fahrdynamik mit strafferem Fahrwerk und sportlicherem Interieur.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (106,'bmw-x2-f39','Basis','Basis','Standard-Stoßfänger, 17-Zoll-Leichtmetallräder, schwarze Kunststoffbeplankung','Grundausstattung, weniger sportlich oder luxuriös');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (107,'bmw-x2-f39','Advantage','Ausstattungslinie','Zusätzliche Komfortmerkmale, z.B. Klimaautomatik, Park Distance Control hinten','Fokus auf Komfort und Funktionalität');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (108,'bmw-x2-f39','Sport Line','Ausstattungslinie','Sportliche Stoßfänger, spezielle 18-Zoll-Räder, Sportsitze, rote Kontrastnähte im Innenraum','Betont die sportliche Seite mit spezifischen Designelementen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (109,'bmw-x2-f39','M Sport','Ausstattungslinie','M Aerodynamikpaket, M Sportfahrwerk, M Lederlenkrad, 19-Zoll-M Leichtmetallräder, Sportsitze','Umfassendes Sportpaket mit optischen und fahrdynamischen Verbesserungen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (110,'bmw-x2-f39','M Sport X','Ausstattungslinie','M Aerodynamikpaket mit Frozen Grey Akzenten, M Sportfahrwerk, 19-Zoll-M Leichtmetallräder, Sportsitze, spezifische Interieurleisten','Kombiniert M Sport mit Offroad-Elementen, einzigartige Frozen Grey Akzente');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (111,'bmw-x2-u10','Basis','Basis','Standard-Exterieur und -Interieur, 17-Zoll-Leichtmetallräder (modellabhängig), schwarze Kunststoffbeplankung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (112,'bmw-x2-u10','M Sport','Ausstattungslinie','M Aerodynamikpaket, M spezifische Front- und Heckschürze, M Leichtmetallräder (mind. 19 Zoll), M Sportfahrwerk, M Sportlenkrad, Sportsitze.','Sportlichere Optik und Fahrwerksabstimmung im Vergleich zur Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (113,'bmw-x2-u10','M Sport Pro','Ausstattungslinie','Erweitertes M Aerodynamikpaket, M Sportbremse, M Hochglanz Shadow Line mit erweiterten Umfängen, M Sicherheitsgurte, M Heckspoiler.','Erweitert die M Sport Ausstattung um weitere sportliche Details und Funktionen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (114,'bmw-x3-e83','Basis','Basis','Standardausstattung ohne spezifische Sport- oder Luxusmerkmale.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (115,'bmw-x3-e83','Executive','Ausstattungslinie','Betont Komfort und Eleganz, oft mit Lederausstattung, Navigationssystem und hochwertigeren Interieurleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (116,'bmw-x3-e83','Sportpaket','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezifische Leichtmetallräder, Aerodynamikpaket (geänderte Stoßfänger und Seitenschweller), Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (117,'bmw-x3-f25','Basis','Basis','Standard-Stoßfänger, 17-Zoll-Leichtmetallräder, schwarze Dachreling','Grundausstattung ohne spezifische Design- oder Sportpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (118,'bmw-x3-f25','xLine','Ausstattungslinie','Spezifische Stoßfänger mit Unterfahrschutz-Optik, matt-silberne Designelemente, 18-Zoll-Leichtmetallräder, Dachreling Aluminium satiniert','Betont den robusten und Offroad-Charakter des Fahrzeugs.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (119,'bmw-x3-f25','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front-, Seiten- und Heckschürzen), M Leichtmetallräder (18-19 Zoll), M Sportfahrwerk, M Sportlenkrad, Sportsitze, Hochglanz Shadow Line','Betont die sportliche Seite des X3 mit dynamischerem Design und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (120,'bmw-x3-g01','Basis','Basis','Standard-Stoßfänger, 18-Zoll-Leichtmetallräder, schwarze Fensterrahmen, keine spezifischen Designelemente.','Die Grundausstattung ohne spezifische Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (121,'bmw-x3-g01','xLine','Ausstattungslinie','Unterfahrschutz vorne und hinten in Gletscher-Silber, spezifische 19-Zoll-Leichtmetallräder, Akzente in Perlglanz Chrom, Dachreling in Aluminium satiniert.','Betont den robusten Offroad-Charakter des X3.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (122,'bmw-x3-g01','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), 19-Zoll-M Leichtmetallräder, M Sportfahrwerk, M Sportbremse (optional), M Hochglanz Shadow Line, Sportsitze.','Fokus auf sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (123,'bmw-x3-g01','M40i / M40d','M Performance','Eigenständige M Performance Designelemente (z.B. Cerium Grey Akzente an Niere, Spiegelkappen, Lufteinlässen), spezifische M Leichtmetallräder, M Sportabgasanlage, M Sportbremse, M Sportdifferenzial.','Leistungsstarke Modelle mit sportlicher Abstimmung und exklusiven Designmerkmalen, unterhalb der echten M-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (124,'bmw-x3-g01','X3 M','Echtes M-Modell','Extrem aggressives M Aerodynamikpaket, große Lufteinlässe, M spezifische Niere, M Außenspiegel, M Leichtmetallräder bis 21 Zoll, M Sportabgasanlage mit vier Endrohren, M Compound-Bremse, M spezifische Interieur-Details.','Das Topmodell mit eigenständigem Hochleistungsmotor, Fahrwerk und Bremsanlage, entwickelt von der BMW M GmbH.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (125,'bmw-x3-g45','Basis','Basis','Standard-Exterieur und Interieur, 18-Zoll-Leichtmetallräder','Grundausstattung ohne spezifische Design- oder Sportmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (126,'bmw-x3-g45','M Sport','Ausstattungslinie','M Aerodynamikpaket, M Leichtmetallräder (mind. 19 Zoll), M Sportfahrwerk, M Sportlenkrad, Sportsitze','Betont sportliches Design und Fahrverhalten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (127,'bmw-x4-f26','Basis','Basis','Serienausstattung ohne spezifische Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (128,'bmw-x4-f26','xLine','Ausstattungslinie','Betont den robusten Offroad-Charakter mit spezifischen Stoßfängern, Unterfahrschutz-Elementen und Leichtmetallrädern.','Exterieur- und Interieur-Details in mattem Aluminium oder Chrom, spezielle Sitzbezüge.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (129,'bmw-x4-f26','M Sport','Ausstattungslinie','Sportlichere Optik mit M Aerodynamikpaket, M Leichtmetallrädern und Shadow Line Hochglanz.','M Sportfahrwerk, M Lederlenkrad, Sportsitze, spezifische Interieurleisten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (130,'bmw-x4-g02','Basis','Basis','Serienausstattung, 18-Zoll-Leichtmetallräder, LED-Scheinwerfer, Sportsitze vorne, Klimaautomatik.','Die Grundausstattung ohne spezifische Design- oder Sportpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (131,'bmw-x4-g02','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Sportfahrwerk, 19-Zoll-M-Leichtmetallräder, M Lederlenkrad, Sportsitze, M spezifische Interieurleisten.','Betont die sportliche Optik und Fahrdynamik durch spezifische M-Komponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (132,'bmw-x4-g02','M Performance (z.B. M40i, M40d)','M Performance','Exklusive M Performance Designelemente (z.B. Cerium Grey Akzente an Nieren, Spiegelkappen, Lufteinlässen), größere Bremsanlage, spezifische M Leichtmetallräder, M Sportabgasanlage.','Stellt eine Brücke zwischen den regulären Modellen und den ''echten'' M-Modellen dar, mit leistungsgesteigerten Motoren und sportlicherer Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (133,'bmw-x4-g02','X4 M','Echtes M-Modell','Aggressiveres M Aerodynamikpaket, M spezifische Front- und Heckschürze, M Außenspiegel, 20- oder 21-Zoll-M-Leichtmetallräder, M Sportabgasanlage mit vier Endrohren, M spezifisches Interieur mit M Sportsitzen und M Lenkrad.','Das Topmodell mit eigenständigem M Motor, M spezifischem Fahrwerk, M xDrive Allradsystem und maximaler Performance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (134,'bmw-x5-e53','Basis','Basis','Standard-Stoßfänger, kleinere Felgenoptionen','Grundausstattung, oft mit optionalen Paketen wie ''Executive'' oder ''Comfort'' erweitert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (135,'bmw-x5-e53','Sportpaket','Ausstattungslinie','Sportlichere Stoßfänger, größere Leichtmetallräder, Sportfahrwerk, Sportsitze, Shadow Line (schwarze Zierleisten)','Fokus auf sportlicheres Fahrverhalten und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (136,'bmw-x5-e70','Basis','Basis','Standard-Stoßfänger, 18-Zoll-Leichtmetallräder, schwarze Dachreling.','Grundausstattung, oft mit Stoff- oder Teilledersitzen und Basissystemen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (137,'bmw-x5-e70','Sportpaket','Ausstattungslinie','Sportliche Stoßfänger vorne und hinten, breitere Radläufe, größere Leichtmetallräder (oft 19 oder 20 Zoll), Sportfahrwerk, Sportsitze.','Fokus auf sportlicheres Aussehen und Fahrverhalten, oft mit Shadow Line Exterieur.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (138,'bmw-x5-e70','M Sportpaket','M Performance','M Aerodynamikpaket (spezifische Front-, Heckschürze und Seitenschweller), M Leichtmetallräder (oft 20 Zoll), M Sportfahrwerk, M Lederlenkrad, Sportsitze mit M Logo, Shadow Line Exterieur.','Umfassendes Paket, das Optik, Fahrwerk und Interieur sportlicher gestaltet, aber kein echtes M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (139,'bmw-x5-f15','Basis','Basis','Standard-Stoßfänger, 18-Zoll-Leichtmetallräder, schwarze Dachreling','Umfasst die Grundausstattung ohne spezifische Design- oder Sportpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (140,'bmw-x5-f15','Design Pure Experience','Ausstattungslinie','Unterfahrschutz vorne und hinten in mattem Silber, spezifische Lufteinlässe, Endrohrblenden in mattem Chrom, 19-Zoll-Leichtmetallräder','Betont den robusten und Offroad-Charakter des Fahrzeugs.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (141,'bmw-x5-f15','Design Pure Excellence','Ausstattungslinie','Chrom-Applikationen an Front und Heck, spezifische Nierenstäbe, Endrohrblenden in Hochglanzchrom, 19-Zoll-Leichtmetallräder','Hebt den luxuriösen und eleganten Charakter hervor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (142,'bmw-x5-f15','M Sportpaket','M Performance','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Leichtmetallräder (mind. 19 Zoll), M Sportfahrwerk, M Sportlenkrad, Sportsitze','Betont die sportliche Seite des X5 mit optischen und fahrwerkstechnischen Anpassungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (143,'bmw-x5-f15','BMW Individual','Ausstattungslinie','Exklusive Lackierungen, spezielle Lederpolsterungen, Edelholz- oder Pianolack-Interieurleisten, 20-Zoll-Leichtmetallräder','Ermöglicht eine hochgradige Personalisierung des Fahrzeugs mit exklusiven Materialien und Farben.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (144,'bmw-x5-g05','Standard','Basis','Klassisches BMW Design, ausgewogene Optik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (145,'bmw-x5-g05','xLine','Ausstattungslinie','Betont Robustheit und Offroad-Charakter, spezifische Designelemente in Aluminium satiniert (z.B. Nierenstäbe, Lufteinlässe, Dachreling), Unterfahrschutzoptik vorne und hinten.','Fokus auf Eleganz und Geländetauglichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (146,'bmw-x5-g05','M Sport','Ausstattungslinie','Betont Sportlichkeit, aerodynamische M-Paket-Anbauteile (spezifische Front- und Heckschürze, Seitenschweller), größere Lufteinlässe, M Sportbremse, M Sportfahrwerk, M Leichtmetallräder.','Fokus auf Dynamik und sportliches Auftreten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (147,'bmw-x5-g05','M Performance (z.B. M50i, M60i)','M Performance','Noch sportlichere Optik als M Sport, spezifische M Performance Designelemente (z.B. Cerium Grey Akzente, trapezförmige Endrohre), stärkere Motoren.','Leistungsstarke Modelle unterhalb der echten M-Modelle mit sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (148,'bmw-x5-g05','X5 M Competition','Echtes M-Modell','Eigenständiges, aggressives M-Design mit großen Lufteinlässen, M-spezifischen Nieren, Außenspiegeln, Heckspoiler und Diffusor, vier Endrohre, M Leichtmetallräder.','Das Topmodell der Baureihe mit maximaler Performance und eigenständiger M-Entwicklung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (152,'bmw-x6-e71','Basis','Basis','Standard-Stoßfänger, kleinere Felgen (z.B. 19 Zoll), keine spezifischen Aerodynamik-Anbauteile.','Umfasst die Grundausstattung ohne spezifische Sport- oder Luxuspakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (153,'bmw-x6-e71','M Sportpaket','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Leichtmetallräder (größer, z.B. 20 Zoll), Shadow Line hochglänzend, M Sportfahrwerk (optional).','Betont den sportlichen Charakter des Fahrzeugs durch optische und teilweise technische Modifikationen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (154,'bmw-x6-e71','X6 M','Echtes M-Modell','Eigenständige, noch aggressivere Front- und Heckschürzen, vierflutige Abgasanlage, spezielle M Leichtmetallräder, Powerdome auf der Motorhaube, M Außenspiegel.','Das Topmodell mit eigenständigem Hochleistungsmotor, M spezifischem Fahrwerk und Bremsanlage sowie exklusiven M Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (159,'bmw-x6-f16','Basis','Basis','Serienausstattung, 19-Zoll-Leichtmetallräder, Xenon-Scheinwerfer, Teilledersitze, Klimaautomatik.','Die Grundausstattung ohne spezifische Design- oder Sportpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (160,'bmw-x6-f16','M Sportpaket','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), 19- oder 20-Zoll M Leichtmetallräder, M Sportfahrwerk, M Lederlenkrad, Sportsitze, M Fußstütze und Einstiegsleisten.','Betont den sportlichen Charakter des Fahrzeugs durch optische und fahrwerksseitige Modifikationen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (161,'bmw-x6-f16','Design Pure Extravagance','Ausstattungslinie','Exklusive Lackierungen, 20-Zoll-Leichtmetallräder, spezifische Interieur-Akzente (z.B. Edelholz, Bicolor-Lederausstattung), Aluminium-Trittbretter.','Fokus auf luxuriöse und individuelle Optik im Innen- und Außenbereich.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (162,'bmw-x6-f16','BMW X6 M','Echtes M-Modell','Eigenständiges, aggressiveres M Aerodynamikpaket, 21-Zoll M Leichtmetallräder, M spezifische Doppelstreben-Niere, M Außenspiegel, vierflutige Abgasanlage, M Sportsitze, M spezifisches Cockpit mit M Head-Up Display.','Eigenständiges Hochleistungsmodell mit deutlich stärkerem Motor, M spezifischem Fahrwerk, Bremsen und Antriebsstrang.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (163,'bmw-x6-g06','Basis','Basis','Serienausstattung, 19-Zoll-Leichtmetallräder, LED-Scheinwerfer, Sportsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (164,'bmw-x6-g06','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), 20-Zoll-M-Leichtmetallräder, M Sportbremse, M Sportfahrwerk, M Hochglanz Shadow Line.','Sportlichere Optik und Fahrwerksabstimmung gegenüber der Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (165,'bmw-x6-g06','M60i xDrive','M Performance','Eigenständige M-Designelemente, M-spezifische Niere, 21-Zoll-M-Leichtmetallräder, M Sportabgasanlage, M Außenspiegelkappen in Schwarz Hochglanz.','Leistungsstärkere Motorisierung und sportlichere Ausstattung als M Sport, aber unterhalb der echten M-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (166,'bmw-x6-g06','X6 M Competition','Echtes M-Modell','Exklusives M-Design mit aggressiverer Frontschürze, M-spezifische Doppelsteg-Niere, 21/22-Zoll-M-Leichtmetallräder, M Außenspiegel, M Sportabgasanlage mit vier Endrohren, M Carbon-Dach (optional).','Höchste Leistungsstufe mit eigenständigem M-Motor, M-Fahrwerk, M-Bremsanlage und M-spezifischen Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (167,'bmw-x7-g07','Standard','Basis','Klassische BMW-Optik, weniger sportlich akzentuiert, oft mit Chrom-Applikationen.','Die Basisausstattung bietet bereits einen hohen Standard an Luxus und Technik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (168,'bmw-x7-g07','M Sport','Ausstattungslinie','Sportlichere Front- und Heckschürzen, M-spezifische Felgen, Shadow Line (schwarze Zierleisten), M-Sportbremse optional.','Betont den sportlichen Charakter des X7, ohne ein echtes M-Modell zu sein. Verfügbar für alle Motorisierungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (169,'bmw-x7-g07','M60i (vor LCI: M50i)','M Performance','Eigenständige M-Performance-Designelemente, größere Lufteinlässe, spezifische Abgasanlage, M-Embleme.','Top-Motorisierung unterhalb des Alpina, mit sportlicher Abstimmung von Fahrwerk und Motor. Bietet eine Mischung aus Luxus und hoher Performance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (170,'bmw-x7-g07','Alpina XB7','Echtes M-Modell','Alpina-spezifische Front- und Heckschürzen, 21-Zoll-Alpina Classic Felgen (optional 23 Zoll), Alpina-Schriftzüge, blaue Bremssättel.','Exklusives Modell von Alpina mit umfassenden Modifikationen an Motor, Fahrwerk und Interieur für höchste Performance und Luxus. Streng limitiert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (171,'bmw-z4-e85','Basis','Basis','Serienausstattung, 16-Zoll-Leichtmetallräder, schwarze Interieurleisten.','Grundausstattung, viele Optionen waren einzeln wählbar.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (172,'bmw-z4-e85','M Sportpaket','Ausstattungslinie','M Aerodynamikpaket, M Sportfahrwerk, M Leichtmetallräder (z.B. Sternspeiche 108), Sportsitze, M Lederlenkrad, M Einstiegsleisten.','Umfassendes Paket zur sportlichen Aufwertung von Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (173,'bmw-z4-e86','Basis','Basis','Serienausstattung, 16- oder 17-Zoll-Leichtmetallräder, Sportsitze','Die Grundausstattung bot bereits eine gute Basis an Komfort- und Sicherheitsmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (174,'bmw-z4-e86','M Sportpaket','Ausstattungslinie','M Aerodynamikpaket, M Sportfahrwerk, M Leichtmetallräder, Sportsitze mit M-Logo, M Lederlenkrad','Betont die sportliche Optik und Fahrdynamik, ohne die Leistungssteigerung eines echten M-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (175,'bmw-z4-e86','Z4 M Coupé','Echtes M-Modell','Eigenständige Front- und Heckschürzen, vier Endrohre, M-spezifische Leichtmetallräder, M-Außenspiegel, M-Sportsitze, M-Instrumente','Das Topmodell mit dem S54-Motor aus dem E46 M3, eigenständigem Fahrwerk und Bremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (176,'bmw-z4-e89','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen M-Badges.','Die Grundausstattung ohne zusätzliche Sport- oder Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (177,'bmw-z4-e89','M Sportpaket','Ausstattungslinie','Sportlichere Front- und Heckschürze, M-spezifische Leichtmetallräder, M Sportfahrwerk, M Lederlenkrad, Sportsitze, M-Badges an den Seiten.','Betont den sportlichen Charakter des Fahrzeugs durch optische und technische Upgrades.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (178,'bmw-z4-g29','Basis','Basis','Serienausstattung, 17-Zoll-Leichtmetallräder, LED-Scheinwerfer, Sportlenkrad, Sportsitze.','Die Grundausstattung ohne spezifische Designpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (179,'bmw-z4-g29','M Sport','Ausstattungslinie','M Aerodynamikpaket, 18-Zoll-M-Leichtmetallräder, M Sportfahrwerk, M Sportbremse (optional), M Lederlenkrad, Sportsitze mit M spezifischer Polsterung.','Betont die sportliche Optik und Fahrdynamik mit spezifischen M-Komponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (180,'bmw-z4-g29','M40i','M Performance','Exklusive 18-Zoll- oder 19-Zoll-M-Leichtmetallräder, M Aerodynamikpaket, M Sportfahrwerk adaptiv, M Sportbremse, trapezförmige Endrohre, Cerium Grey Akzente (Nieren, Spiegelkappen).','Die Top-Motorisierung mit dem Reihensechszylinder und einer umfassenden M Performance Ausstattung ab Werk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (181,'bmw-i3-i01','Basis','Basis','Standard-Ausstattung, oft mit 19-Zoll-Leichtmetallrädern, Interieur in ''Atelier''-Design.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (182,'bmw-i3-i01','Loft','Ausstattungslinie','Helleres Interieur mit Stoff- und Sensatec-Bezügen, spezifische Farbakzente.','Bietet eine modernere und hellere Innenraumgestaltung als die Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (183,'bmw-i3-i01','Lodge','Ausstattungslinie','Natürliche Materialien wie Wolle und Leder, warme Farbtöne.','Fokus auf Nachhaltigkeit und natürliche Ästhetik im Innenraum.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (184,'bmw-i3-i01','Suite','Ausstattungslinie','Hochwertiges Lederinterieur, oft mit Holzapplikationen, luxuriösere Anmutung.','Die luxuriöseste Ausstattungslinie mit Fokus auf Komfort und Premium-Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (185,'bmw-i3-i01','i3s','M Performance','Sportlichere Front- und Heckschürze, schwarze Radlaufverkleidungen, breitere Spur, 20-Zoll-Leichtmetallräder, spezifische ''i3s''-Embleme.','Die sportlichere Variante mit höherer Leistung, strafferem Fahrwerk und optischen Differenzierungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (186,'bmw-ix-i20','Basis','Basis','Serienmäßige Ausstattung mit 20-Zoll-Leichtmetallrädern, LED-Scheinwerfern und der charakteristischen BMW iX Designsprache.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (187,'bmw-ix-i20','Sportpaket','Ausstattungslinie','Umfasst sportlichere Stoßfänger vorne und hinten, spezifische 21- oder 22-Zoll-Leichtmetallräder und blaue Bremssättel (optional).','Betont die dynamische Seite des Fahrzeugs durch sportlichere Designelemente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (188,'bmw-ix-i20','BMW Individual','Ausstattungslinie','Ermöglicht eine Personalisierung mit exklusiven Lackierungen, speziellen Lederpolsterungen und Interieurleisten.','Bietet eine höhere Exklusivität und Individualisierungsmöglichkeiten über die Serienausstattung hinaus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (189,'bmw-1er-e87','Basis','Basis','Unlackierte Stoßfängerunterteile (je nach Baujahr), kleinere Stahl- oder Leichtmetallfelgen, keine Nebelscheinwerfer serienmäßig.','Grundausstattung ohne besondere optische oder funktionale Extras.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (190,'bmw-1er-e87','Advantage','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, oft in Wagenfarbe lackierte Stoßfängerunterteile.','Erweiterte Komfort- und Funktionsausstattung gegenüber der Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (191,'bmw-1er-e87','Sport Line','Ausstattungslinie','Sportsitze, Sportlenkrad, spezifische Leichtmetallfelgen, schwarze Hochglanz-Akzente im Interieur, Sportfahrwerk (optional).','Betont die sportliche Seite mit entsprechenden Interieur- und Exterieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (192,'bmw-1er-e87','Urban Line','Ausstattungslinie','Spezifische Leichtmetallfelgen, Interieur-Akzente in hellen Farben oder Aluminium, oft mit Stoff-Leder-Kombinationen.','Fokus auf modernes, urbanes Design und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (193,'bmw-1er-e87','M Sportpaket','M Performance','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Leichtmetallfelgen, M Sportfahrwerk, Sportsitze, M Lederlenkrad, M Einstiegsleisten, Shadow Line (schwarze Fensterrahmen).','Umfassendes Paket, das das Fahrzeug optisch und fahrdynamisch an die M-Modelle annähert, jedoch ohne Leistungssteigerung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (199,'bmw-1er-f20-f21','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Designelemente. Meist kleinere Felgen, unlackierte Stoßfängerunterteile (je nach Baujahr), keine speziellen Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (200,'bmw-1er-f20-f21','Sport Line','Ausstattungslinie','Schwarze Hochglanz-Niere, schwarze Außenspiegelkappen (optional), spezielle Leichtmetallräder, schwarze Endrohrblende, Sportsitze mit roten Akzenten im Innenraum.','Betont den sportlichen Charakter mit schwarzen Akzenten und sportlicherer Innenausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (201,'bmw-1er-f20-f21','Urban Line','Ausstattungslinie','Weiße oder silberne Akzente an der Niere und den Lufteinlässen, spezielle Leichtmetallräder, Interieur mit Acrylglas-Akzenten und Stoff-/Lederkombinationen.','Fokus auf modernes, urbanes Design mit hellen Akzenten und einer stilvollen Innenausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (202,'bmw-1er-f20-f21','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze, M Fußstütze und Einstiegsleisten.','Umfassendes Sportpaket mit aggressiverer Optik, strafferem Fahrwerk und sportlicherer Innenausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (203,'bmw-1er-f20-f21','M135i / M140i','M Performance','Eigenständige Frontschürze mit größeren Lufteinlässen, graue Außenspiegelkappen, spezifische M Leichtmetallräder, zwei Endrohre links und rechts, M Performance Schriftzüge.','Top-Modelle mit leistungsstarkem Sechszylinder-Motor, M Performance Fahrwerk und spezifischen optischen Merkmalen, die sie von den regulären M Sport Modellen abheben.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (204,'bmw-1er-f40','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Designelemente.','Die Grundausstattung ohne zusätzliche Design- oder Komfortpakete.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (205,'bmw-1er-f40','Advantage','Ausstattungslinie','Leichtmetallräder, Park Distance Control (PDC) hinten, Geschwindigkeitsregelung.','Fokus auf Komfort- und Funktionserweiterungen gegenüber der Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (206,'bmw-1er-f40','Sport Line','Ausstattungslinie','Spezifische 17-Zoll-Leichtmetallräder, sportlichere Stoßfänger mit schwarzen Akzenten, Sportsitze, schwarze Hochglanz-Zierelemente.','Betont den sportlichen Charakter mit spezifischen Designelementen innen und außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (207,'bmw-1er-f40','Luxury Line','Ausstattungslinie','Exklusive 17-Zoll-Leichtmetallräder, Chrom-Akzente an Niere und Stoßfängern, Lederausstattung, Edelholz-Interieurleisten.','Fokus auf Eleganz und hochwertige Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (208,'bmw-1er-f40','M Sport','Ausstattungslinie','M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), 17- oder 18-Zoll M Leichtmetallräder, M Sportfahrwerk, M Sportlenkrad, Sportsitze, Shadow Line Hochglanz.','Deutlich sportlicheres Erscheinungsbild und Fahrwerkseinstellungen, angelehnt an die M Performance Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (209,'bmw-1er-f40','M135i xDrive','M Performance','Eigenständige Frontschürze mit größeren Lufteinlässen, M spezifische Niere mit Mesh-Struktur, 18-Zoll M Leichtmetallräder, M Sportbremse, zwei runde Endrohre, M Heckspoiler.','Top-Modell mit dem stärksten Motor, Allradantrieb und umfassender M Performance Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (210,'bmw-1er-f40','128ti','M Performance','M Aerodynamikpaket mit roten Akzenten (z.B. Lufteinlässe, Seitenschweller), 18-Zoll M Leichtmetallräder, M Sportbremse mit roten Sätteln, zwei runde Endrohre, spezifische Heckschürze.','Sportmodell mit Frontantrieb, das sich durch rote Designelemente und eine sportliche Abstimmung vom M135i abhebt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (229,'mercedes-benz-a-klasse-w168','Classic','Basis','Einfachste Ausstattung, oft mit unlackierten Stoßfängern (frühe Modelle) oder schlichteren Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (230,'mercedes-benz-a-klasse-w168','Elegance','Ausstattungslinie','Chromapplikationen an Kühlergrill und Stoßfängern, Leichtmetallräder, oft Holz- oder Aluminiumzierleisten im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (231,'mercedes-benz-a-klasse-w168','Avantgarde','Ausstattungslinie','Sportlichere Optik mit dunkleren Scheinwerfern, speziellen Leichtmetallrädern, Sportsitzen und Aluminium- oder Carbon-Optik-Zierelementen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (232,'mercedes-benz-a-klasse-w169','Classic','Basis','Grundausstattung, oft mit Stahlfelgen und einfacheren Interieurmaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (233,'mercedes-benz-a-klasse-w169','Elegance','Ausstattungslinie','Chromapplikationen an Stoßfängern und Seitenleisten, Leichtmetallräder, Komfortsitze, Holz- oder Aluminiumzierleisten im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (234,'mercedes-benz-a-klasse-w169','Avantgarde','Ausstattungslinie','Sportlichere Optik mit spezifischen Leichtmetallrädern, tiefergelegtem Fahrwerk, Sportsitzen, Aluminium- oder Carbon-Optik-Zierelementen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (235,'mercedes-benz-a-klasse-w176','Basis','Basis','Einfachere Stoßfänger, kleinere Felgen, keine Chromapplikationen oder Sportelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (236,'mercedes-benz-a-klasse-w176','Style','Ausstattungslinie','Leichtmetallräder, Chromzierleisten, Komfortsitze mit speziellen Stoff-/Ledernachbildung-Bezügen, farbige Kontrastnähte.','Betont Komfort und Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (237,'mercedes-benz-a-klasse-w176','Urban','Ausstattungslinie','Sportlichere Stoßfänger, 17-Zoll-Leichtmetallräder, verchromte Endrohrblenden, Sportsitze mit speziellen Stoff-/Ledernachbildung-Bezügen.','Sportlich-elegante Ausrichtung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (238,'mercedes-benz-a-klasse-w176','AMG Line','Ausstattungslinie','AMG Styling (Frontschürze, Heckschürze, Seitenschweller), 18-Zoll-AMG-Leichtmetallräder, Sportfahrwerk, gelochte Bremsscheiben vorne, Sportsitze, Multifunktions-Sportlenkrad, rote Kontrastnähte.','Betont die sportliche Optik und Fahrdynamik, ohne ein echtes AMG-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (239,'mercedes-benz-a-klasse-w176','A 45 AMG','Echtes M-Modell','Eigenständige AMG-Frontschürze mit größeren Lufteinlässen, AMG-Kühlergrill mit Doppellamelle, AMG-Heckschürze mit Diffusor und zwei eckigen Endrohren, AMG-Leichtmetallräder, AMG-Sportfahrwerk, AMG-Hochleistungsbremsanlage, AMG-Sportsitze, AMG-Performance-Lenkrad.','Das Topmodell mit eigenständigem Hochleistungsmotor und spezifischen AMG-Komponenten für maximale Performance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (240,'mercedes-benz-a-klasse-w177','Basis','Basis','Standard-Stoßfänger, 16-Zoll-Räder, schwarze Fensterrahmen, keine Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (241,'mercedes-benz-a-klasse-w177','Progressive Line','Ausstattungslinie','Verchromte Zierelemente an Front- und Heckschürze, 17-Zoll-Leichtmetallräder, sichtbare Endrohrblenden (je nach Motorisierung), Komfortsitze.','Bietet eine gehobene Optik und Komfortausstattung gegenüber der Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (242,'mercedes-benz-a-klasse-w177','AMG Line','Ausstattungslinie','AMG Styling-Paket mit spezifischer Frontschürze, Seitenschwellerverkleidungen und Heckschürze, 18-Zoll-AMG-Leichtmetallräder, Sportfahrwerk, Sportsitze, Multifunktions-Sportlenkrad in Leder Nappa.','Betont die sportliche Seite mit AMG-Designelementen und sportlicherer Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (243,'mercedes-benz-a-klasse-w177','Mercedes-AMG A 35','M Performance','AMG-spezifische Frontschürze mit Flics, AMG-Kühlergrill mit vertikalen Lamellen (nach Facelift), AMG-Heckschürze mit Diffusor und zwei runden Endrohren, 18- oder 19-Zoll-AMG-Leichtmetallräder, AMG-Sportfahrwerk.','Erste Leistungsstufe der AMG-Modelle, mit deutlicher Leistungssteigerung und sportlicherer Optik als die AMG Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (244,'mercedes-benz-a-klasse-w177','Mercedes-AMG A 45 S','Echtes M-Modell','AMG-spezifische Frontschürze mit größeren Lufteinlässen, AMG-Kühlergrill mit vertikalen Lamellen, breitere Kotflügel, AMG-Heckschürze mit Diffusor und vier runden Endrohren, 19-Zoll-AMG-Schmiederäder, AMG-Aerodynamik-Paket optional.','Das Topmodell der Baureihe mit der höchsten Leistung und den umfassendsten AMG-spezifischen Modifikationen in Fahrwerk, Motor und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (245,'mercedes-benz-b-klasse-w245','Classic','Basis','Einfachere Stoffbezüge, weniger Chrom-Applikationen, Stahlräder mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (246,'mercedes-benz-b-klasse-w245','Avantgarde','Ausstattungslinie','Hochwertigere Stoffe oder Lederausstattung, Leichtmetallfelgen, Chrom-Applikationen, Nebelscheinwerfer.','Umfangreichere Komfort- und Designmerkmale im Vergleich zur Classic-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (247,'mercedes-benz-b-klasse-w245','Elegance','Ausstattungslinie','Besonders hochwertige Materialien, Leder-Applikationen, größere Leichtmetallfelgen, Ambientebeleuchtung.','Fokus auf Luxus und Komfort, übertrifft die Avantgarde-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (248,'mercedes-benz-b-klasse-w246','Style','Ausstattungslinie','Exterieur mit Chrom-Applikationen, Interieur mit speziellen Zierelementen und Stoff-/Ledernachbildung ARTICO-Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (249,'mercedes-benz-b-klasse-w246','Urban','Ausstattungslinie','Sportlicherer Look mit 17-Zoll-Leichtmetallrädern, verchromten Endrohrblenden, Interieur mit Sportsitzen und Kontrastziernähten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (250,'mercedes-benz-b-klasse-w246','AMG Line','Ausstattungslinie','AMG Styling-Paket (Frontschürze, Heckschürze, Seitenschweller), 18-Zoll-AMG Leichtmetallräder, Sportfahrwerk, gelochte Bremsscheiben vorne, Interieur mit Sportsitzen, Multifunktions-Sportlenkrad und AMG Fußmatten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (251,'mercedes-benz-b-klasse-w247','Basis','Basis','Serienmäßige Ausstattung, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (252,'mercedes-benz-b-klasse-w247','Progressive Line','Ausstattungslinie','Umfasst 17-Zoll-Leichtmetallräder, Chromzierleisten an den Seitenfenstern, sichtbare Endrohrblenden und eine hochwertigere Innenausstattung mit Zierelementen in Carbon-Optik oder Aluminium.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (253,'mercedes-benz-b-klasse-w247','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen im AMG-Design, 18-Zoll-AMG-Leichtmetallräder, tiefergelegtes Komfortfahrwerk, Sportsitze, Sportlenkrad und spezifische AMG-Fußmatten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (254,'mercedes-benz-c-klasse-w202','Classic','Basis','Einfachere Stoffbezüge, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (255,'mercedes-benz-c-klasse-w202','Esprit','Ausstattungslinie','Sportlichere Akzente, z.B. andere Sitzbezüge, teilweise farbige Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (256,'mercedes-benz-c-klasse-w202','Sport','Ausstattungslinie','Tiefergelegtes Fahrwerk, sportlichere Sitze, andere Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (257,'mercedes-benz-c-klasse-w202','Elegance','Ausstattungslinie','Hochwertigere Materialien, mehr Holz- oder Wurzelholz-Applikationen, Ledersitze optional.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (258,'mercedes-benz-c-klasse-w203','Classic','Basis','Dezente Chromapplikationen, klassischer Kühlergrill mit Lamellen und Stern auf der Motorhaube, kleinere Felgen.','Die Basisausstattung, fokussiert auf Komfort und Funktionalität.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (259,'mercedes-benz-c-klasse-w203','Elegance','Ausstattungslinie','Umfangreichere Chromzierleisten an Stoßfängern und Seitenleisten, feineres Holzdekor im Innenraum, spezifische Leichtmetallräder, klassischer Kühlergrill mit Stern auf der Motorhaube.','Betont Eleganz und Komfort mit hochwertigeren Materialien und mehr Ausstattungsumfang als Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (260,'mercedes-benz-c-klasse-w203','Avantgarde','Ausstattungslinie','Sportlicherer Kühlergrill mit drei Lamellen und großem Stern im Grill (nach Facelift), sportlichere Front- und Heckschürzen, tiefergelegtes Fahrwerk, spezifische Leichtmetallräder, Aluminium- oder dunkles Holzdekor im Innenraum, blaue Wärmeschutzverglasung.','Betont Sportlichkeit und Modernität, mit strafferem Fahrwerk und dynamischerer Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (261,'mercedes-benz-c-klasse-w203','AMG','Echtes M-Modell','Eigenständige, aggressivere Front- und Heckschürzen, Seitenschweller, spezifische AMG-Leichtmetallräder, Sportabgasanlage mit zwei Endrohren, AMG-Schriftzüge, Sportbremsanlage, AMG-Sportlenkrad und Sportsitze.','Die Top-Performance-Modelle von AMG mit leistungsstärkeren Motoren, sportlicherem Fahrwerk und exklusiver Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (262,'mercedes-benz-c-klasse-w204','Avantgarde','Ausstattungslinie','Sportlichere Optik mit anderem Kühlergrill (Stern im Grill integriert), andere Stoßfänger, 17-Zoll-Leichtmetallräder, Sportsitze, Sportfahrwerk.','Abgrenzung zur "Classic" durch sportlichere Elemente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (263,'mercedes-benz-c-klasse-w204','Elegance','Ausstattungslinie','Komfortorientierte Ausstattung mit Chromapplikationen, anderem Kühlergrill (klassisch mit Haubenstern), 16-Zoll-Leichtmetallräder, Komfortfahrwerk.','Abgrenzung zur "Classic" durch mehr Chrom und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (264,'mercedes-benz-c-klasse-w204','Classic','Basis','Einstiegsmodell mit einfacherer Ausstattung und weniger optischen Akzenten.','Grundmodell ohne die spezifischen Merkmale von Avantgarde und Elegance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (265,'mercedes-benz-c-klasse-w204','AMG Sport','M Performance','Sportliche Optik mit AMG-Styling-Elementen, größeren Rädern, Sportfahrwerk, Sportsitzen.','Zwischen den normalen Ausstattungslinien und den echten AMG-Modellen angesiedelt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (266,'mercedes-benz-c-klasse-w204','C 63 AMG','Echtes M-Modell','Breitere Karosserie, spezifische AMG-Stoßfänger und -Schweller, vierflutige Abgasanlage, größere Bremsen, AMG-spezifische Felgen, AMG-Sportfahrwerk.','Deutlich leistungsstärkere und optisch aggressivere Version des C-Klasse Coupés/Limousinen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (267,'mercedes-benz-c-klasse-w205','Avantgarde','Ausstattungslinie','Sportlichere Optik mit Stern auf der Haube, dynamischere Frontschürze und Seitenschweller.','Standard-Ausstattungslinie mit Fokus auf Sportlichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (268,'mercedes-benz-c-klasse-w205','Exclusive','Ausstattungslinie','Klassische Mercedes-Optik mit Stern auf der Haube, Chrom-Applikationen, elegantere Front.','Fokus auf Komfort und klassische Eleganz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (269,'mercedes-benz-c-klasse-w205','AMG Line','Ausstattungslinie','AMG-spezifische Front- und Heckschürze, Seitenschweller, größere Leichtmetallräder, Sportfahrwerk.','Sportliche Optik, die an die AMG-Modelle angelehnt ist, aber nicht die volle Performance bietet.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (270,'mercedes-benz-c-klasse-w205','C 43 AMG','M Performance','AMG-spezifische Optik mit vier Endrohren, spezifische Felgen, Sportfahrwerk, stärkere Bremsanlage.','Leistungsstärkere Version mit V6-Biturbomotor, aber nicht die Top-Performance der V8-AMG-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (271,'mercedes-benz-c-klasse-w205','C 63 AMG / C 63 S AMG','Echtes M-Modell','Breitere Karosserie, spezifische AMG-Front- und Heckschürze, vierflutige Abgasanlage, leistungsstarke Bremsanlage, AMG-Sportfahrwerk.','Die Top-Performance-Modelle mit V8-Biturbomotor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (272,'mercedes-benz-c-klasse-w206','Avantgarde','Ausstattungslinie','Kühlergrill mit Zentralstern und zwei Lamellen, 17-Zoll-Leichtmetallräder, Chromzierrat.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (273,'mercedes-benz-c-klasse-w206','AMG Line','Ausstattungslinie','AMG-spezifische Frontschürze, Seitenschwellerverkleidungen und Heckschürze, 18-Zoll-AMG-Leichtmetallräder, Diamantgrill.','Sportlicher und aggressiver im Design als Avantgarde.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (274,'mercedes-benz-c-klasse-w206','C 43 4MATIC','M Performance','AMG-spezifische Kühlerverkleidung mit vertikalen Streben, vierflutige Abgasanlage, spezifische AMG-Leichtmetallräder.','Deutlich sportlicher als die AMG Line, mit leistungsstärkerem Motor und spezifischen Fahrwerkskomponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (275,'mercedes-benz-c-klasse-w206','C 63 S E PERFORMANCE','Echtes M-Modell','Breitere Karosserie, spezifische AMG-Frontschürze, Heckdiffusor, vierflutige Abgasanlage, 19- oder 20-Zoll-AMG-Leichtmetallräder.','Das Topmodell mit höchster Leistung und Performance, exklusiven Designmerkmalen und fortschrittlichster Hybridtechnologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (276,'mercedes-benz-e-klasse-w210','Classic','Basis','Einfachere Stoffbezüge, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (277,'mercedes-benz-e-klasse-w210','Elegance','Ausstattungslinie','Hochwertigere Stoff- oder Lederbezüge, Holzeinlagen im Innenraum, mehr Chrom-Applikationen außen.','Deutlich aufgewerteter Innenraum und mehr Komfortmerkmale im Vergleich zur Classic-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (278,'mercedes-benz-e-klasse-w210','Avantgarde','Ausstattungslinie','Sportlichere Sitze, dunklere Innenraummaterialien, Aluminium-Applikationen, strafferes Fahrwerk.','Fokussiert auf eine sportlichere Optik und Haptik im Vergleich zu Classic und Elegance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (279,'mercedes-benz-e-klasse-w210','AMG','M Performance','Spezifische AMG-Stoßfänger, Seitenschweller, Felgen, Sportfahrwerk, stärkere Bremsen, AMG-Schriftzüge.','Deutlich sportlicher und leistungsstärker als die regulären Ausstattungslinien, mit spezifischen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (280,'mercedes-benz-e-klasse-w211','Classic','Basis','Einfachere Radkappen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (281,'mercedes-benz-e-klasse-w211','Elegance','Ausstattungslinie','Mehr Chrom-Elemente an Front und Heck, hochwertigere Innenraummaterialien, oft mit Holzdekor.','Deutlich aufgewertete Optik und Haptik im Vergleich zur Classic-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (282,'mercedes-benz-e-klasse-w211','Avantgarde','Ausstattungslinie','Sportlichere Optik mit anderen Stoßfängern, oft mit größeren Leichtmetallfelgen, dunklere Innenraumakzente, strafferes Fahrwerk.','Fokussiert auf eine sportlichere Ausrichtung im Vergleich zu Elegance und Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (283,'mercedes-benz-e-klasse-w211','AMG','M Performance','Spezifische AMG-Stoßfänger, Seitenschweller, größere AMG-Felgen, vierflutige Abgasanlage, AMG-Schriftzüge.','Deutlich sportlicher und leistungsstärker als die regulären Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (284,'mercedes-benz-e-klasse-w212','Classic','Ausstattungslinie','Klassischer Kühlergrill mit drei Lamellen und Stern auf der Motorhaube, dezente Chromapplikationen, 16-Zoll-Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (285,'mercedes-benz-e-klasse-w212','Elegance','Ausstattungslinie','Klassischer Kühlergrill mit drei Lamellen und Stern auf der Motorhaube, zusätzliche Chromzierleisten an Stoßfängern und Seitenleisten, 17-Zoll-Leichtmetallräder, hochwertigere Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (286,'mercedes-benz-e-klasse-w212','Avantgarde','Ausstattungslinie','Sportlicher Kühlergrill mit zwei Lamellen und großem Mercedes-Stern mittig im Grill, sportlichere Front- und Heckschürzen, tiefergelegtes Fahrwerk, 17- oder 18-Zoll-Leichtmetallräder, LED-Tagfahrlicht, sportlichere Innenraumgestaltung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (287,'mercedes-benz-e-klasse-w212','AMG Sport-Paket','Ausstattungslinie','AMG-Styling-Elemente (Frontschürze, Heckschürze, Seitenschweller), spezifische AMG-Leichtmetallräder, Sportfahrwerk, gelochte Bremsscheiben vorne, Sportlenkrad, Sportsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (288,'mercedes-benz-e-klasse-w212','E 63 AMG','Echtes M-Modell','Eigenständige, aggressivere AMG-Frontschürze mit größeren Lufteinlässen, breitere Kotflügel, spezifische AMG-Leichtmetallräder, AMG-Sportabgasanlage mit vier Endrohren, AMG-spezifische Heckschürze und Diffusor, AMG-Performance-Bremsanlage.','Deutlich leistungsstärkerer Motor, eigenständiges Fahrwerk und Bremsanlage, umfangreiche AMG-spezifische Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (289,'mercedes-benz-e-klasse-w213','Basis','Basis','Klassischer Kühlergrill mit Stern auf der Motorhaube, kleinere Felgen, weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (290,'mercedes-benz-e-klasse-w213','Avantgarde','Ausstattungslinie','Sportlicherer Kühlergrill mit integriertem Stern, sichtbare Endrohrblenden, größere Leichtmetallräder, Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (291,'mercedes-benz-e-klasse-w213','Exclusive','Ausstattungslinie','Klassischer Kühlergrill mit Lamellen und Stern auf der Motorhaube, mehr Chromapplikationen, elegante Felgendesigns.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (292,'mercedes-benz-e-klasse-w213','AMG Line','Ausstattungslinie','Aggressiveres AMG-Styling-Paket (Frontschürze, Heckschürze, Seitenschweller), Diamantgrill, größere AMG-Leichtmetallräder, Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (293,'mercedes-benz-e-klasse-w213','Mercedes-AMG E 43/53/63','Echtes M-Modell','Eigenständige AMG-Frontschürze, Panamericana-Grill (ab E 53/63), breitere Kotflügel (E 63), spezifische AMG-Felgen, Sportabgasanlage mit vier Endrohren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (294,'mercedes-benz-e-klasse-w214','Avantgarde','Ausstattungslinie','Kühlergrill mit zwei Lamellen und integriertem Mercedes-Stern, Chrom-Zierelemente, 17-Zoll-Leichtmetallräder (serienmäßig), sportlichere Front- und Heckschürze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (295,'mercedes-benz-e-klasse-w214','Exclusive','Ausstattungslinie','Klassischer Kühlergrill mit drei Lamellen und Mercedes-Stern auf der Motorhaube, zusätzliche Chrom-Applikationen, 18-Zoll-Leichtmetallräder (serienmäßig), elegantere Front- und Heckschürze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (296,'mercedes-benz-e-klasse-w214','AMG Line','Ausstattungslinie','AMG-spezifischer Kühlergrill mit vertikalen Streben, AMG-Styling-Paket (Frontschürze, Heckschürze, Seitenschweller), 19-Zoll-Leichtmetallräder (serienmäßig), Sportfahrwerk (optional), AMG-Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (306,'mercedes-benz-s-klasse-w126','Standard','Basis','Weniger Chromzierrat, einfachere Stoff- oder Kunstlederausstattung, kleinere Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (307,'mercedes-benz-s-klasse-w126','SE/SEL (Langversion)','Ausstattungslinie','Längerer Radstand, mehr Platz im Fond, oft mit besserer Ausstattung wie Leder, Klimaanlage, elektrische Sitze.','Erkennbar am längeren Radstand und den zusätzlichen Fondtüren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (308,'mercedes-benz-s-klasse-w126','SEC (Coupé)','Ausstattungslinie','Keine B-Säule, rahmenlose Fenster, sportlichere Linienführung, oft mit besserer Ausstattung.','Deutlich erkennbar an der Coupé-Karosserie und dem fehlenden B-Säulen-Bereich.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (309,'mercedes-benz-s-klasse-w126','AMG','M Performance','Spezifische AMG-Felgen, Frontspoiler, Heckspoiler, oft mit Leistungssteigerung und sportlicherer Innenausstattung.','Erkennbar an den spezifischen AMG-Anbauteilen und Emblemen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (310,'mercedes-benz-s-klasse-w140','Standard','Basis','Die Basismodelle (z.B. 300 SE/SEL, S 320) waren bereits sehr gut ausgestattet, aber optisch weniger auffällig als die Topmodelle. Sie verfügten über die typische Mercedes-Benz-Linienführung ohne zusätzliche Sport- oder Luxuspakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (311,'mercedes-benz-s-klasse-w140','Langversion (SEL/S-Klasse Lang)','Ausstattungslinie','Erkennbar an der deutlich verlängerten Karosserie, insbesondere im Bereich der hinteren Türen, was den Fondpassagieren mehr Beinfreiheit bot.','Längerer Radstand und Karosserie im Vergleich zur Standard-Limousine.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (312,'mercedes-benz-s-klasse-w140','Coupé (C140 / CL-Klasse)','Ausstattungslinie','Zweitürige Karosserieform mit rahmenlosen Scheiben, eigenständiger Dachlinie und sportlicherer Anmutung. Die Coupés wurden ab 1996 als CL-Klasse vermarktet.','Zweitüriges Coupé im Gegensatz zur viertürigen Limousine.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (313,'mercedes-benz-s-klasse-w140','V12-Modelle (600 SE/SEL, S 600)','Ausstattungslinie','Oft mit spezifischen Leichtmetallrädern, V12-Emblemen an den Kotflügeln und einer noch luxuriöseren Innenausstattung. Äußerlich nur subtile Unterschiede zu den anderen Modellen.','Top-Motorisierung und höchste Serienausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (314,'mercedes-benz-s-klasse-w220','Classic','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (315,'mercedes-benz-s-klasse-w220','Elegance','Ausstattungslinie','Mehr Chromzierrat, hochwertigere Materialien im Innenraum, oft mit Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (316,'mercedes-benz-s-klasse-w220','Avantgarde','Ausstattungslinie','Sportlicherer Look mit dunkleren Akzenten, spezifische Leichtmetallfelgen, oft mit Xenon-Scheinwerfern und sportlicherem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (317,'mercedes-benz-s-klasse-w220','AMG','Echtes M-Modell','Aggressivere Front- und Heckschürzen, Seitenschweller, spezifische AMG-Felgen, Sportauspuffanlage, AMG-Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (318,'mercedes-benz-s-klasse-w221','Basis','Basis','Serienmäßige Ausstattung ohne spezifische optische Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (319,'mercedes-benz-s-klasse-w221','AMG Sport-Paket','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, spezielle AMG-Leichtmetallräder und verchromte Endrohrblenden.','Optische Aufwertung in Richtung AMG-Design, jedoch keine echten AMG-Motoren oder Fahrwerkskomponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (320,'mercedes-benz-s-klasse-w221','Designo','Ausstattungslinie','Exklusive Lackierungen, hochwertige Lederpolsterungen, spezielle Holz- oder Klavierlackzierleisten im Innenraum.','Fokus auf Individualisierung und luxuriöse Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (321,'mercedes-benz-s-klasse-w221','S 63 AMG','Echtes M-Modell','Eigenständige AMG-Frontschürze mit größeren Lufteinlässen, AMG-Seitenschweller, AMG-Heckschürze mit Diffusor und vierflutiger Abgasanlage, spezifische AMG-Leichtmetallräder, AMG-Schriftzüge.','Umfassende technische und optische Modifikationen durch AMG, inklusive leistungsstärkerem Motor, Sportfahrwerk und Bremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (322,'mercedes-benz-s-klasse-w221','S 65 AMG','Echtes M-Modell','Ähnliche AMG-Designelemente wie der S 63 AMG, jedoch oft mit noch exklusiveren Felgendesigns und V12-Biturbo-Emblemen an den Kotflügeln.','Die Top-Motorisierung von AMG mit V12-Biturbo-Motor und entsprechenden Leistungsmerkmalen, noch exklusiver als der S 63 AMG.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (323,'mercedes-benz-s-klasse-w222','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Sport- oder Luxuspakete. Klassischer Mercedes-Stern auf der Motorhaube.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (324,'mercedes-benz-s-klasse-w222','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, größere AMG-Leichtmetallräder, gelochte Bremsscheiben. Im Innenraum Sportlenkrad und AMG-Fußmatten.','Betont die sportliche Seite der S-Klasse, ohne ein echtes AMG-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (325,'mercedes-benz-s-klasse-w222','Exclusive Line','Ausstattungslinie','Verchromte Zierelemente, spezielle Leichtmetallräder, erweiterte Leder- und Holzapplikationen im Innenraum, oft mit dem klassischen Mercedes-Stern auf der Motorhaube.','Fokus auf maximalen Luxus und Komfort, oft mit exklusiven Materialien und Ausstattungsdetails.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (326,'mercedes-benz-s-klasse-w222','Mercedes-Maybach','Ausstattungslinie','Deutlich verlängerter Radstand, spezifischer Kühlergrill mit feinen vertikalen Streben, Maybach-Embleme an der C-Säule, exklusive Lackierungen (oft Zweifarbenlackierung), luxuriösester Innenraum mit Einzelsitzen im Fond.','Positioniert als Submarke für höchste Exklusivität und Luxus, noch oberhalb der regulären S-Klasse.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (327,'mercedes-benz-s-klasse-w222','Mercedes-AMG S 63 / S 65','Echtes M-Modell','Aggressivere AMG-Frontschürze mit großen Lufteinlässen, AMG-spezifischer Kühlergrill, AMG-Leichtmetallräder, Sportabgasanlage mit vier Endrohren, AMG-Schriftzüge. Im Innenraum AMG-Sportsitze, Sportlenkrad und spezifische Anzeigen.','Echte Hochleistungsmodelle von AMG mit eigenständigen Motoren und Fahrwerksabstimmungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (328,'mercedes-benz-s-klasse-w223','Basis','Basis','Serienausstattung mit klassischem Kühlergrill und Mercedes-Stern auf der Motorhaube, 18-Zoll-Leichtmetallräder, LED High Performance-Scheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (329,'mercedes-benz-s-klasse-w223','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen im AMG-Design, spezifische Seitenschweller, größere Leichtmetallräder (oft 19 oder 20 Zoll), sichtbare Endrohrblenden, gelochte Bremsscheiben vorne.','Betont die sportliche Seite des Fahrzeugs mit dynamischerem Exterieur und Interieur.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (330,'mercedes-benz-s-klasse-w223','Maybach','Ausstattungslinie','Exklusiver Kühlergrill mit feinen vertikalen Chromstreben, Maybach-Embleme an der C-Säule, optional Zweifarbenlackierung, spezifische Felgendesigns, verlängerter Radstand, besonders luxuriöses Interieur mit First-Class-Fond.','Positioniert sich als ultra-luxuriöse Variante mit Fokus auf maximalen Komfort und Exklusivität, insbesondere für den Fondpassagier.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (331,'mercedes-benz-cls-c219','Basis','Basis','Serienausstattung, oft mit Stoff- oder Teilledersitzen, kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (332,'mercedes-benz-cls-c219','Avantgarde','Ausstattungslinie','Umfasst in der Regel hochwertigere Materialien im Innenraum, größere Leichtmetallräder, Chromzierleisten und eine sportlichere Fahrwerksabstimmung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (333,'mercedes-benz-cls-c219','Designo','Ausstattungslinie','Exklusive Lackierungen, hochwertige Lederpolsterungen (oft Nappa), spezielle Holz- oder Aluminiumzierleisten und erweiterte Individualisierungsmöglichkeiten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (334,'mercedes-benz-cls-c219','AMG Sportpaket','M Performance','Sportlichere Front- und Heckschürzen, Seitenschweller, spezielle AMG-Leichtmetallräder, Sportfahrwerk und Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (335,'mercedes-benz-cls-c219','CLS 55 AMG','Echtes M-Modell','Eigenständige AMG-Frontschürze mit größeren Lufteinlässen, AMG-Seitenschweller, AMG-Heckschürze mit Diffusoroptik, vierflutige Abgasanlage, spezifische AMG-Leichtmetallräder, AMG-Sportfahrwerk und AMG-Bremsanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (336,'mercedes-benz-cls-c219','CLS 63 AMG','Echtes M-Modell','Nachfolger des CLS 55 AMG, ähnliche AMG-spezifische Karosserieanbauteile, jedoch mit dem 6,2-Liter-V8-Saugmotor, ebenfalls vierflutige Abgasanlage und spezifische AMG-Räder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (337,'mercedes-benz-cls-c218','Avantgarde','Ausstattungslinie','Serienmäßige Avantgarde-Linie mit sportlicherer Optik, z.B. andere Stoßfänger und Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (338,'mercedes-benz-cls-c218','Exclusive','Ausstattungslinie','Fokus auf Luxus und Komfort, z.B. andere Lederausstattungen, Holzeinlagen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (339,'mercedes-benz-cls-c218','AMG Line','Ausstattungslinie','Sportlichere Anbauteile, größere Felgen, spezifische Innenraumdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (340,'mercedes-benz-cls-c257','CLS 350 d / 400 d','Ausstattungslinie','Serienmäßige AMG Line Exterieur mit sportlichen Stoßfängern, Seitenschwellern und spezifischen Felgen. Innenraum mit Sportsitzen und Leder-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (341,'mercedes-benz-cls-c257','CLS 450','Ausstattungslinie','Ähnlich der Diesel-Varianten, oft mit zusätzlichen Komfort- und Technologie-Paketen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (342,'mercedes-benz-cls-c257','AMG CLS 53 4MATIC+','M Performance','AMG-spezifische Frontschürze mit A-Wing, Panamericana-Kühlergrill, breitere Kotflügel, vierflutige Abgasanlage, spezifische AMG-Felgen, AMG-Sportlenkrad, Sportsitze mit AMG-Branding.','Deutlich sportlicherer Auftritt und Performance im Vergleich zu den Standard-CLS-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (343,'mercedes-benz-glb-x247','Basis','Basis','Serienmäßige Ausstattung, oft mit 17-Zoll-Leichtmetallrädern, schwarzem Kühlergrill mit zwei Lamellen, unlackierten Stoßfängern (je nach Markt/Modelljahr).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (344,'mercedes-benz-glb-x247','Progressive','Ausstattungslinie','Verchromte Zierelemente, 18-Zoll-Leichtmetallräder, Kühlergrill mit zwei Lamellen und Chrom-Einlegern, sichtbare Endrohrblenden.','Umfangreichere Serienausstattung als die Basis, hochwertigere Materialien im Innenraum.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (345,'mercedes-benz-glb-x247','AMG Line','Ausstattungslinie','AMG Styling-Paket mit spezifischer Front- und Heckschürze, Seitenschwellerverkleidungen, 19-Zoll-AMG-Leichtmetallräder, Sportbremsanlage, Kühlergrill mit Diamantmuster oder vertikalen Lamellen (nach Facelift).','Sportlichere Optik und Fahrwerksabstimmung, AMG-spezifische Interieurdetails wie Sportsitze und Sportlenkrad.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (346,'mercedes-benz-glb-x247','Mercedes-AMG GLB 35 4MATIC','M Performance','AMG-spezifischer Kühlergrill (Panamericana-Optik nach Facelift), AMG-Frontschürze mit Flics, AMG-Heckschürze mit Diffusoroptik, zwei runde Endrohrblenden, 19-Zoll-AMG-Leichtmetallräder (optional größer).','Deutlich leistungsstärkerer Motor, AMG Performance Fahrwerk, AMG Sportlenkung, AMG Hochleistungs-Bremsanlage, spezifische AMG-Interieurdetails.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (347,'mercedes-benz-ml-klasse-w163','Classic','Basis','Einfachere Felgen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (348,'mercedes-benz-ml-klasse-w163','Avantgarde','Ausstattungslinie','Leichtmetallfelgen, teilweise mehr Chrom-Elemente, sportlichere Anmutung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (349,'mercedes-benz-ml-klasse-w163','Elegance','Ausstattungslinie','Hochwertigere Materialien im Innenraum, oft mit Lederbezügen, mehr Chrom-Applikationen, größere Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (350,'mercedes-benz-ml-klasse-w164','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Chrom-Applikationen oder Sport-Design-Elemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (351,'mercedes-benz-ml-klasse-w164','Sport-Paket Exterieur','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische Leichtmetallräder, verchromte Auspuffendrohre, Trittbretter in Aluminium-Optik mit Gumminoppen.','Fokus auf sportlichere Optik im Vergleich zur Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (352,'mercedes-benz-ml-klasse-w164','Offroad-Pro-Paket','Ausstattungslinie','Unterfahrschutz vorne und hinten, spezifische Offroad-Design-Elemente, teilweise andere Felgenoptionen.','Fokus auf Geländetauglichkeit mit technischer Ausstattung wie Untersetzungsgetriebe und Sperrdifferenzialen, sowie optischen Schutzkomponenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (353,'mercedes-benz-ml-klasse-w166','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Design-Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (354,'mercedes-benz-ml-klasse-w166','Design-Paket Exterieur','Ausstattungslinie','Unterfahrschutz vorne und hinten in Chromoptik, spezifische Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (355,'mercedes-benz-ml-klasse-w166','AMG Line Exterieur','Ausstattungslinie','AMG Styling (Front- und Heckschürze, Seitenschweller), spezifische AMG Leichtmetallräder, Sportbremsanlage.','Betont den sportlichen Charakter mit aggressiverem Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (356,'mercedes-benz-ml-klasse-w166','Offroad-Paket','Ausstattungslinie','Unterfahrschutz, spezifische Offroad-Optik-Elemente, teilweise mit speziellen Felgen.','Fokus auf Geländetauglichkeit mit technischer Ausstattung wie Untersetzung und Differentialsperre.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (357,'mercedes-benz-gle-w166-facelift','GLE 300 d 4MATIC','Ausstattungslinie','Serienmäßige 18-Zoll-Leichtmetallräder, Chrom-Applikationen, LED-Tagfahrlicht.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (358,'mercedes-benz-gle-w166-facelift','GLE 400 4MATIC','Ausstattungslinie','Serienmäßige 19-Zoll-Leichtmetallräder, Sport-Stoßfänger, spezifische Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (359,'mercedes-benz-gle-w166-facelift','AMG GLE 43 4MATIC','M Performance','AMG Styling, 20-Zoll-AMG-Leichtmetallräder, Sportabgasanlage, rote Bremssättel.','Deutlich sportlichere Optik und Haptik im Vergleich zu den Standardmodellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (360,'mercedes-benz-gle-w166-facelift','AMG GLE 63 4MATIC','Echtes M-Modell','AMG-spezifische Frontschürze, breitere Kotflügel, 21-Zoll-AMG-Leichtmetallräder, AMG-Sportbremsanlage, vierflutige Abgasanlage.','Höchste Performance-Variante mit entsprechend aggressiver Optik und leistungsstärkstem Motor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (361,'mercedes-benz-gle-coupé-c292','Basis','Basis','Standard-Stoßfänger, 19-Zoll-Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (362,'mercedes-benz-gle-coupé-c292','AMG Line','Ausstattungslinie','AMG-Styling (Front-/Heckschürze, Seitenschweller), größere Leichtmetallräder (oft 20 Zoll), Sportbremsanlage, spezifische Polsterung und Zierelemente im Innenraum.','Deutlich sportlichere Optik im Vergleich zur Basislinie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (363,'mercedes-benz-gle-coupé-c292','Mercedes-AMG GLE 43 4MATIC Coupé','M Performance','Spezifische AMG-Frontschürze mit Lufteinlässen, verchromte Doppelendrohre, 21-Zoll-AMG-Leichtmetallräder, rote Bremssättel, AMG-spezifisches Interieur.','Deutlich sportlicher als die AMG Line, mit leistungsgesteigertem Motor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (364,'mercedes-benz-gle-coupé-c292','Mercedes-AMG GLE 63 S 4MATIC Coupé','Echtes M-Modell','Breitere Kotflügel, spezifische AMG-Kühlerverkleidung (''Panamericana'' bei späteren Facelifts, hier aber noch nicht), vierflutige Abgasanlage, 22-Zoll-AMG-Leichtmetallräder, Hochleistungsbremsanlage, Performance-Sitze.','Das Spitzenmodell mit maximaler Leistung und sportlicher Ausrichtung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (365,'mercedes-benz-gle-w167','GLE 350 d 4MATIC','Ausstattungslinie','Serienmäßige AMG Line Exterieur mit spezifischen Stoßfängern, Seitenschwellern und 20-Zoll-Leichtmetallrädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (366,'mercedes-benz-gle-w167','GLE 450 4MATIC','Ausstattungslinie','Ähnlich der 350 d Linie, aber mit spezifischen Motorisierungsmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (367,'mercedes-benz-gle-w167','AMG GLE 53 4MATIC+','M Performance','AMG-spezifische Panamericana-Kühlergrill, Frontschürze mit größeren Lufteinlässen, Heckdiffusor, vierflutige Abgasanlage, 21-Zoll-Leichtmetallräder.','Deutlich sportlichere Optik und Fahrwerkseinstellungen im Vergleich zu den Standard-GLE-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (368,'mercedes-benz-gle-w167','AMG GLE 63 4MATIC+','Echtes M-Modell','AMG Panamericana-Kühlergrill, breitere Kotflügel, spezifische AMG-Stoßfänger vorne und hinten, vierflutige Abgasanlage, 21- oder 22-Zoll-Leichtmetallräder.','Höchste Performance-Variante mit V8-Motor und entsprechendem Fahrwerk sowie Bremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (369,'mercedes-benz-gle-coupé-c167','GLE 350 d 4MATIC Coupé','Ausstattungslinie','Serienmäßige AMG Line Exterieur mit spezifischen Stoßfängern, Seitenschwellern und 19-Zoll-Leichtmetallrädern. Innenraum mit Sportsitzen und Leder-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (370,'mercedes-benz-gle-coupé-c167','GLE 400 d 4MATIC Coupé','Ausstattungslinie','Identisch zur GLE 350 d 4MATIC Coupé, jedoch mit stärkerem Motor.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (371,'mercedes-benz-gle-coupé-c167','GLE 450 4MATIC Coupé','Ausstattungslinie','Serienmäßige AMG Line Exterieur, 20-Zoll-Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (372,'mercedes-benz-gle-coupé-c167','AMG GLE 53 4MATIC+ Coupé','M Performance','AMG spezifische Kühlerverkleidung (Panamericana-Grill), breitere Radhäuser, größere Bremsanlage, 21-Zoll-Leichtmetallräder, spezifische AMG-Stoßfänger und Endrohre.','Deutlich sportlicher und aggressiver im Design als die regulären Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (373,'mercedes-benz-gle-coupé-c167','AMG GLE 63 4MATIC+ Coupé','Echtes M-Modell','AMG Panamericana-Grill, breitere Kotflügel, spezifische AMG-Front- und Heckschürzen, vierflutige Abgasanlage, 22-Zoll-Leichtmetallräder, rote Bremssättel.','Das Spitzenmodell mit maximaler Performance und exklusiver Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (374,'mercedes-benz-gle-coupé-c167','AMG GLE 63 S 4MATIC+ Coupé','Echtes M-Modell','Identisch zur AMG GLE 63 4MATIC+ Coupé, jedoch mit nochmals gesteigerter Leistung und exklusiveren Details.','Das absolute Topmodell der Baureihe.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (375,'mercedes-benz-gl-klasse-x164','Basis','Basis','Serienmäßige Ausstattung ohne spezifische optische Pakete. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (376,'mercedes-benz-gl-klasse-x164','Grand Edition','Ausstattungslinie','Sondermodell mit exklusiven 20-Zoll-Leichtmetallrädern, Bi-Xenon-Scheinwerfern mit abgedunkeltem Gehäuse, LED-Tagfahrlicht, dunklen Heckleuchten, speziellen Lackierungen und Chrom-Applikationen. Innenraum mit zweifarbiger Lederausstattung, Holz- oder Aluminiumzierleisten und speziellen Fußmatten.','Exklusives Sondermodell zum Ende der Bauzeit mit umfangreicherer Serienausstattung und einzigartigen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (377,'mercedes-benz-gls-x166','GLS 350 d 4MATIC','Ausstattungslinie','Standard-Stoßfänger, 19-Zoll-Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (378,'mercedes-benz-gls-x166','GLS 400 4MATIC','Ausstattungslinie','Standard-Stoßfänger, 19-Zoll-Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (379,'mercedes-benz-gls-x166','GLS 500 4MATIC','Ausstattungslinie','Standard-Stoßfänger, 20-Zoll-Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (380,'mercedes-benz-gls-x166','GLS 63 AMG 4MATIC','M Performance','AMG-spezifische Front- und Heckschürze, 21-Zoll-Leichtmetallräder, vergrößerte Bremsanlage, spezifische Auspuffanlage.','Deutlich sportlichere Optik und Performance-orientierte Ausstattung im Vergleich zu den Standardmodellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (381,'mercedes-benz-gls-x167','Basis','Basis','Serienmäßige Ausstattung, oft mit 19- oder 20-Zoll-Leichtmetallrädern, LED High Performance-Scheinwerfern und dem MBUX-Infotainmentsystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (382,'mercedes-benz-gls-x167','AMG Line','Ausstattungslinie','Sportlicherer Look mit spezifischen AMG-Styling-Elementen wie Front- und Heckschürze, Seitenschwellerverkleidungen, größeren Leichtmetallrädern (oft 21 oder 22 Zoll) und gelochten Bremsscheiben. Im Innenraum oft mit Sportlenkrad und AMG-Fußmatten.','Betont die sportliche Optik und Fahrdynamik, ohne ein echtes AMG-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (383,'mercedes-benz-gls-x167','Maybach GLS 600','Ausstattungslinie','Exklusiver Kühlergrill mit feinen vertikalen Chromstreben, Maybach-Embleme, spezifische 22- oder 23-Zoll-Schmiederäder, optional Zweifarbenlackierung. Innenraum mit luxuriöseren Materialien, Einzelsitzen im Fond (Executive-Sitze), erweiterten Komfortfunktionen und Maybach-spezifischen Details.','Stellt die höchste Luxus- und Komfortstufe dar, mit Fokus auf den Fondpassagier und exklusiver Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (384,'mercedes-benz-gls-x167','Mercedes-AMG GLS 63 4MATIC+','Echtes M-Modell','AMG-spezifischer Panamericana-Kühlergrill, AMG-Frontschürze mit großen Lufteinlässen, breitere Radläufe, AMG-Abgasanlage mit zwei Doppelendrohren, 21- oder 22-Zoll-AMG-Leichtmetallräder. Im Interieur Sportsitze, AMG Performance Lenkrad, AMG-spezifische Anzeigen im MBUX und Carbon-Zierelemente.','Das leistungsstärkste Modell der Baureihe mit einem V8-Biturbomotor, AMG-spezifischem Fahrwerk und Bremsanlage sowie einer betont sportlichen Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (385,'mercedes-benz-sl-r230','Standard','Basis','Serienmäßige Ausstattung ohne besondere optische Hervorhebungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (386,'mercedes-benz-sl-r230','AMG','M Performance','Spezifische AMG-Stoßfänger, Seitenschweller, größere Leichtmetallräder, vierflutige Abgasanlage, AMG-Schriftzüge.','Deutlich sportlichere Optik und stärkere Motorisierung im Vergleich zu den Standardmodellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (387,'mercedes-benz-sl-r231','Basis','Basis','Standard-Kühlergrill, 17- oder 18-Zoll-Leichtmetallräder, keine spezifischen AMG-Styling-Elemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (388,'mercedes-benz-sl-r231','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, spezifische AMG-Leichtmetallräder (oft 19 Zoll), gelochte Bremsscheiben, Sportfahrwerk.','Bietet eine sportlichere Optik und Fahrdynamik, ohne ein echtes AMG-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (389,'mercedes-benz-sl-r231','Designo','Ausstattungslinie','Exklusive Lackierungen, hochwertige Lederpolsterungen (oft Nappa), spezielle Zierelemente im Innenraum (z.B. Klavierlack, Holz), Designo-Schriftzüge.','Fokus auf luxuriöse und individuelle Ausstattung, Materialien und Farben.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (390,'mercedes-benz-sl-r231','AMG SL 63','Echtes M-Modell','Aggressivere AMG-Frontschürze mit größeren Lufteinlässen, AMG-spezifischer Kühlergrill, breitere Seitenschweller, AMG-Heckschürze mit Diffusor und vier eckigen Endrohren, AMG-Leichtmetallräder (oft 19/20 Zoll), AMG-Sportbremsanlage, V8 BITURBO-Schriftzüge an den Kotflügeln.','Eigenständiges Hochleistungsmodell von Mercedes-AMG mit deutlich stärkerem Motor, spezifischem Fahrwerk und Bremsen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (391,'mercedes-benz-sl-r231','AMG SL 65','Echtes M-Modell','Ähnlich dem SL 63, jedoch oft mit spezifischen AMG-Leichtmetallrädern und V12 BITURBO-Schriftzügen an den Kotflügeln. Manchmal auch mit Carbon-Applikationen oder anderen exklusiven Details.','Das Topmodell der Baureihe mit V12-Motor, noch exklusiverer Ausstattung und höchster Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (392,'mercedes-benz-sl-r232','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische Seitenschweller, größere Leichtmetallräder, AMG-spezifische Auspuffendrohre.','Standard bei allen SL-Modellen, betont den sportlichen Charakter.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (393,'mercedes-benz-sl-r232','AMG Performance','M Performance','Optional für die AMG-Modelle, beinhaltet oft zusätzliche Aerodynamik-Elemente, größere Bremsanlagen und spezifische Felgendesigns.','Fokus auf verbesserte Fahrdynamik und sportlichere Optik, über die AMG Line hinausgehend.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (394,'mercedes-benz-v-klasse-w638','Trend','Ausstattungslinie','Basis-Ausstattung, oft mit Stahlfelgen und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (395,'mercedes-benz-v-klasse-w638','Fashion','Ausstattungslinie','Mittlere Ausstattung, oft mit Leichtmetallfelgen, lackierten Stoßfängern und einer etwas hochwertigeren Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (396,'mercedes-benz-v-klasse-w638','Ambiente','Ausstattungslinie','Top-Ausstattung, oft mit größeren Leichtmetallfelgen, Chrom-Paket, getönten Scheiben und einer luxuriöseren Innenausstattung (z.B. Leder, Holzapplikationen).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (397,'mercedes-benz-viano-w639','Ambiente','Ausstattungslinie','Umfasst in der Regel eine bessere Innenraumgestaltung, mehr Komfortfunktionen und teilweise optische Akzente im Vergleich zur Basisversion.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (398,'mercedes-benz-viano-w639','Avantgarde','Ausstattungslinie','Stellt die höchste Ausstattungslinie dar, mit nochmals verbesserter Materialqualität, zusätzlichen Komfort- und Technikfeatures sowie exklusiveren Designelementen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (399,'mercedes-benz-v-klasse-w447','V-Klasse','Basis','Standard-Stoßfänger, einfache Felgen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (400,'mercedes-benz-v-klasse-w447','Avantgarde','Ausstattungslinie','Chrom-Applikationen, spezifische Felgendesigns, höherwertige Innenraummaterialien.','Deutlich aufgewertete Optik und Haptik im Vergleich zur Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (401,'mercedes-benz-v-klasse-w447','Exclusive','Ausstattungslinie','Umfangreiche Chrom-Elemente, Lederpolsterung, Ambientebeleuchtung, edlere Holz- oder Metall-Dekore.','Höchste Ausstattungsstufe mit maximalem Komfort und Luxus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (410,'mercedes-benz-cla-c117','CLA','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (411,'mercedes-benz-cla-c117','Urban','Ausstattungslinie','Sportlich-elegante Optik mit spezifischen Leichtmetallrädern, verchromten Endrohrblenden und Komfortsitzen.','Positioniert über der Basislinie, mit Fokus auf urbanen Stil und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (412,'mercedes-benz-cla-c117','AMG Line','Ausstattungslinie','Sportliche AMG Styling-Elemente (Frontschürze, Heckschürze, Seitenschweller), 18-Zoll AMG Leichtmetallräder, Sportfahrwerk, gelochte Bremsscheiben vorne, Sportsitze und Multifunktions-Sportlenkrad.','Betont die sportliche Seite des Fahrzeugs, ohne ein echtes AMG-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (413,'mercedes-benz-cla-c117','AMG CLA 45','Echtes M-Modell','Eigenständige AMG Frontschürze mit Flics, AMG Kühlergrill mit Doppellamelle, AMG Leichtmetallräder, AMG Sportabgasanlage mit zwei Doppelendrohren, AMG Heckspoiler (optional), AMG Sportsitze und AMG Performance Lenkrad.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor und spezifischen AMG-Fahrwerks- und Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (414,'mercedes-benz-cla-shooting-brake-x117','Basis','Basis','Serienausstattung ohne spezifische Sport- oder Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (415,'mercedes-benz-cla-shooting-brake-x117','Urban','Ausstattungslinie','Betont einen modernen und urbanen Stil mit spezifischen Leichtmetallrädern, verchromten Zierelementen und Komfortausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (416,'mercedes-benz-cla-shooting-brake-x117','AMG Line','Ausstattungslinie','Sportlichere Optik durch AMG Styling-Elemente (Front- und Heckschürze, Seitenschweller), Diamantgrill, spezifische AMG Leichtmetallräder und tiefergelegtes Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (417,'mercedes-benz-cla-shooting-brake-x117','Mercedes-AMG CLA 45 4MATIC Shooting Brake','Echtes M-Modell','Eigenständige AMG Frontschürze mit Flics, AMG Kühlergrill, breitere Kotflügel, AMG Leichtmetallräder, AMG Sportabgasanlage mit zwei Doppelendrohren und AMG Heckschürze mit Diffusor.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor und Fahrwerksabstimmung von AMG.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (418,'mercedes-benz-cla-c118','Progressive Line','Ausstattungslinie','Dezente Chrom-Applikationen, 17-Zoll-Leichtmetallräder, Komfortsitze, Multifunktions-Sportlenkrad in Leder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (419,'mercedes-benz-cla-c118','AMG Line','Ausstattungslinie','AMG Styling (Frontschürze, Heckschürze, Seitenschweller), 18-Zoll-AMG-Leichtmetallräder, Sportsitze, Sportfahrwerk, gelochte Bremsscheiben vorne, Multifunktions-Sportlenkrad in Nappaleder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (420,'mercedes-benz-cla-c118','Mercedes-AMG CLA 35','M Performance','AMG-spezifische Frontschürze mit Flics, AMG-Kühlergrill, Heckschürze mit Diffusor und zwei runden Endrohren, 18-Zoll-AMG-Leichtmetallräder, AMG Performance Lenkrad, Sportsitze.','Leistungsstärker als die AMG Line, aber unterhalb der echten M-Modelle positioniert. Verfügt über einen 2,0-Liter-Turbomotor mit 306 PS und Allradantrieb.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (421,'mercedes-benz-cla-c118','Mercedes-AMG CLA 45 S','Echtes M-Modell','AMG-spezifische Frontschürze mit größeren Lufteinlässen, AMG-Kühlergrill mit vertikalen Streben, breitere Kotflügel, Heckschürze mit Diffusor und vier runden Endrohren, 19-Zoll-AMG-Leichtmetallräder, AMG Performance Sitze, AMG Performance Lenkrad.','Das Topmodell der Baureihe mit dem stärksten Serien-Vierzylinder-Turbomotor der Welt (421 PS), AMG SPEEDSHIFT DCT 8G Getriebe und AMG Performance 4MATIC+ Allradantrieb mit Drift-Modus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (422,'mercedes-benz-cla-shooting-brake-x118','Progressive Line','Ausstattungslinie','Umfasst unter anderem eine spezifische Kühlermaske, 17-Zoll-Leichtmetallräder, Sportsitze mit Stoff/Ledernarbenausstattung und Ambientebeleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (423,'mercedes-benz-cla-shooting-brake-x118','AMG Line','Ausstattungslinie','Sportlichere Optik mit AMG-spezifischen Stoßfängern, 18-Zoll-Leichtmetallrädern, Sportfahrwerk, Multifunktions-Sportlenkrad und Sportsitzen mit Leder/Mikrofaser.','Deutlich sportlicher als die Progressive Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (424,'mercedes-benz-cla-shooting-brake-x118','CLA 35 4MATIC','M Performance','AMG-spezifische Front- und Heckschürze, spezifischer Kühlergrill, 18-Zoll-Leichtmetallräder, zwei Endrohre, Sportlenkrad, Sportsitze.','Deutlich sportlicher und leistungsstärker als die regulären Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (425,'mercedes-benz-cla-shooting-brake-x118','CLA 45 S 4MATIC+','Echtes M-Modell','AMG-spezifische Aerodynamik-Elemente, 19-Zoll-Leichtmetallräder, vier Endrohre, AMG-Sportfahrwerk, AMG-Sitze, AMG-Lenkrad.','Das Topmodell mit höchster Leistung und sportlichster Auslegung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (426,'mercedes-benz-gla-x156','Style','Ausstattungslinie','Serienmäßige Ausstattung, Stoff-/Ledernachbildung ARTICO-Sitze, 17-Zoll-Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (427,'mercedes-benz-gla-x156','Urban','Ausstattungslinie','Sportlichere Optik mit 18-Zoll-Leichtmetallrädern, Sportsitze, spezifische Zierelemente, verchromte Endrohrblenden.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (428,'mercedes-benz-gla-x156','AMG Line','Ausstattungslinie','AMG Styling-Paket (Frontschürze, Heckschürze, Seitenschweller), 19-Zoll-AMG Leichtmetallräder, Sportfahrwerk, Sportsitze in Ledernachbildung ARTICO/Mikrofaser DINAMICA, Multifunktions-Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (429,'mercedes-benz-gla-x156','Mercedes-AMG GLA 45 4MATIC','Echtes M-Modell','Eigenständiges AMG-Design mit spezifischer Frontschürze, AMG Kühlergrill, AMG Leichtmetallräder, AMG Sportabgasanlage mit zwei Endrohren, AMG Performance-Sitze optional.','Das Topmodell der Baureihe mit deutlich leistungsstärkerem Motor und spezifischer Fahrwerksabstimmung von AMG.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (430,'mercedes-benz-gla-h247','Basis','Basis','Serienmäßige Ausstattung, oft mit kleineren Felgen und weniger Chrom-Applikationen. Innenraum mit Standard-Stoffpolstern und grundlegenden Zierelementen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (431,'mercedes-benz-gla-h247','Progressive','Ausstattungslinie','Dezent sportlichere Optik mit spezifischen Stoßfängern, verchromten Zierelementen und größeren Leichtmetallrädern. Im Innenraum hochwertigere Materialien und Polsterungen.','Bietet eine Aufwertung gegenüber der Basis, ohne die volle Sportlichkeit der AMG Line zu erreichen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (432,'mercedes-benz-gla-h247','AMG Line','Ausstattungslinie','Sehr sportliche Optik mit AMG-Styling-Paket (spezifische Front- und Heckschürzen, Seitenschweller), Diamantgrill, größeren AMG-Leichtmetallrädern und Sportfahrwerk. Innenraum mit Sportsitzen, Sportlenkrad und AMG-spezifischen Zierelementen.','Betont die sportliche Seite des GLA, sowohl optisch als auch durch das straffere Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (433,'mercedes-benz-gla-h247','Mercedes-AMG GLA 35 4MATIC','M Performance','Eigenständige AMG-Frontschürze, AMG-Kühlergrill mit vertikalen Lamellen, spezifische AMG-Leichtmetallräder, AMG-Abgasanlage mit zwei runden Endrohren. Innenraum mit AMG-Sportsitzen, AMG-Performance-Lenkrad und spezifischen AMG-Anzeigen.','Stellt den Einstieg in die echten AMG-Modelle dar, mit deutlicher Leistungssteigerung und sportlicherer Abstimmung als die AMG Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (434,'mercedes-benz-gla-h247','Mercedes-AMG GLA 45 S 4MATIC+','Echtes M-Modell','Noch aggressivere AMG-Frontschürze, breitere Radläufe, AMG-Kühlergrill mit vertikalen Lamellen, größere AMG-Leichtmetallräder, AMG-Hochleistungsbremsanlage, AMG-Abgasanlage mit zwei großen, eckigen Endrohren. Innenraum mit noch sportlicheren AMG-Performance-Sitzen und exklusiven AMG-Details.','Das Topmodell der Baureihe mit der höchsten Leistung und der konsequentesten Sportauslegung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (435,'mercedes-benz-glc-x253','Basis','Basis','Standard-Kühlergrill, 17-Zoll-Leichtmetallräder, schwarze Dachreling, unlackierte Unterfahrschutz-Optik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (436,'mercedes-benz-glc-x253','Exclusive Line','Ausstattungslinie','Kühlergrill mit zwei Lamellen und Chrom-Einlegern, Chrom-Zierelemente an Front- und Heckschürze, 18-Zoll-Leichtmetallräder, polierte Aluminium-Dachreling.','Betont Eleganz und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (437,'mercedes-benz-glc-x253','AMG Line','Ausstattungslinie','AMG-spezifische Frontschürze mit großen Lufteinlässen, Diamantgrill mit einzelnen Lamellen, AMG-Leichtmetallräder (mind. 19 Zoll), Sportfahrwerk, verchromte Endrohrblenden, AMG-Styling-Heckschürze.','Betont Sportlichkeit und Dynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (438,'mercedes-benz-g-klasse-w-460','Basis','Basis','Funktionale Ausstattung, oft mit Stahlfelgen, unlackierten Stoßfängern und minimalistischem Interieur. Fokus auf Robustheit und Geländetauglichkeit.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (439,'mercedes-benz-g-klasse-w-460','230 G','Ausstattungslinie','Bezeichnung für Modelle mit dem 2,3-Liter-Benzinmotor. Optisch oft ähnlich der Basis, aber mit der spezifischen Motorisierung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (440,'mercedes-benz-g-klasse-w-460','240 GD','Ausstattungslinie','Bezeichnung für Modelle mit dem 2,4-Liter-Dieselmotor. Optisch oft ähnlich der Basis, aber mit der spezifischen Motorisierung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (441,'mercedes-benz-g-klasse-w-460','280 GE','Ausstattungslinie','Top-Benzinmodell der Baureihe. Konnte mit optionalen Komfortmerkmalen ausgestattet werden, blieb aber im Kern funktional. Äußerlich oft durch die Motorbezeichnung erkennbar.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (442,'mercedes-benz-g-klasse-w-460','300 GD','Ausstattungslinie','Top-Dieselmodell der Baureihe. Äußerlich oft durch die Motorbezeichnung erkennbar.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (443,'mercedes-benz-g-klasse-w-461','Professional','Ausstattungslinie','Robuste Stoßfänger, oft mit Schutzgittern für Scheinwerfer, Schnorchel, Dachgepäckträger, grobstollige Bereifung, schlichte Lackierungen (oft Uni-Farben).','Fokus auf Geländetauglichkeit und Robustheit, weniger Komfort und Luxus als zivile W 463 Modelle. Oft mit speziellen Fahrwerken und Unterfahrschutz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (444,'mercedes-benz-g-klasse-w-461','Pur','Ausstattungslinie','Ähnlich dem Professional, aber oft als Basis für individuelle Aufbauten oder als schlichtere zivile Variante gedacht. Weniger Anbauteile als der Professional.','Betont die Reduktion auf das Wesentliche, ohne den Fokus auf militärische oder extreme Offroad-Anwendungen wie der Professional.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (445,'mercedes-benz-g-klasse-w-463','Classic','Basis','Grundausstattung, oft mit Stoffpolstern und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (446,'mercedes-benz-g-klasse-w-463','Elegance','Ausstattungslinie','Hochwertigere Materialien, Lederausstattung, Holzapplikationen im Innenraum, oft mit Leichtmetallrädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (447,'mercedes-benz-g-klasse-w-463','Avantgarde','Ausstattungslinie','Sportlichere Optik, oft mit spezifischen Leichtmetallrädern, teilweise dunkleren Interieur-Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (448,'mercedes-benz-g-klasse-w-463','G 500','Ausstattungslinie','V8-Motor, spezifische Embleme, oft mit Vollausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (449,'mercedes-benz-g-klasse-w-463','G 55 AMG','Echtes M-Modell','Aggressivere Frontschürze, breitere Radläufe, spezifische AMG-Felgen, Sidepipes (seitliche Auspuffrohre), AMG-Embleme.','Deutlich leistungsgesteigerter Motor, Sportfahrwerk, Sportbremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (450,'mercedes-benz-g-klasse-w-463','G 63 AMG','Echtes M-Modell','Ähnlich dem G 55 AMG, aber mit modernerem Design nach dem Facelift 2012, spezifischer AMG-Kühlergrill, LED-Tagfahrlicht, größere Räder.','Nochmals leistungsstärkerer Motor (Biturbo-V8), weiterentwickeltes Fahrwerk und Bremsen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (451,'mercedes-benz-g-klasse-w-463','G 65 AMG','Echtes M-Modell','Ähnlich dem G 63 AMG, aber mit V12-Motor und spezifischen V12-Emblemen.','Exklusiver V12-Biturbo-Motor, höchste Leistungsstufe.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (452,'mercedes-benz-g-klasse-w-463-(ab-2018)','G 350 d','Basis','Standard-Kühlergrill, 18-Zoll-Leichtmetallräder, keine spezifischen AMG-Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (453,'mercedes-benz-g-klasse-w-463-(ab-2018)','G 400 d','Ausstattungslinie','Ähnlich dem G 350 d, oft mit optionalen größeren Rädern oder Design-Paketen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (454,'mercedes-benz-g-klasse-w-463-(ab-2018)','G 500','Ausstattungslinie','Standard-Kühlergrill, oft mit 19- oder 20-Zoll-Leichtmetallrädern, keine spezifischen AMG-Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (455,'mercedes-benz-g-klasse-w-463-(ab-2018)','AMG G 63','Echtes M-Modell','AMG-spezifischer Panamericana-Kühlergrill mit vertikalen Streben, breitere Radläufe, größere Lufteinlässe in der Frontschürze, seitliche Endrohre (Sidepipes), 20-Zoll-AMG-Leichtmetallräder (optional bis 22 Zoll), rote Bremssättel.','Deutlich sportlichere Optik und Performance-Orientierung im Vergleich zu den zivilen Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (456,'mercedes-amg-gt-c190','AMG GT','Basis','Grundmodell mit sportlicher, aber weniger extremer Optik als die stärkeren Varianten. Verfügt über die typische AMG-GT-Form, aber ohne die breiteren Kotflügel oder spezifischen Aerodynamik-Elemente der Topmodelle.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (457,'mercedes-amg-gt-c190','AMG GT S','Ausstattungslinie','Ähnlich dem Basis-GT, aber oft mit größeren Rädern, roten Bremssätteln und dezenteren sportlichen Akzenten. Optisch nur geringfügig vom GT zu unterscheiden, bis auf spezifische Felgendesigns und Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (458,'mercedes-amg-gt-c190','AMG GT C','M Performance','Deutlich breitere Karosserie am Heck (wie GT R), breitere Reifen, spezifische Heckschürze und Endrohre. Der Panamericana-Grill war hier oft schon vor dem Facelift Standard. Erhältlich als Coupé und Roadster.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (459,'mercedes-amg-gt-c190','AMG GT R','Echtes M-Modell','Extrem aggressive Optik mit breiteren Kotflügeln vorne und hinten, großem feststehendem Heckflügel, Panamericana-Kühlergrill (von Anfang an), spezifischer Frontschürze mit aktiven Aerodynamik-Elementen und zentralem Endrohr.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (460,'mercedes-amg-gt-c190','AMG GT R Pro','Echtes M-Modell','Basierend auf dem GT R, aber mit zusätzlichen Aerodynamik-Elementen aus Carbon (z.B. Frontflics, größere Diffusor-Finnen), speziellen Felgen und einer noch stärker auf Rennstrecke ausgelegten Optik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (461,'mercedes-amg-gt-c190','AMG GT Black Series','Echtes M-Modell','Das extremste Modell mit massiven Aerodynamik-Anbauten, riesigem, mehrfach verstellbarem Heckflügel, großer Lufthutze auf der Motorhaube, breitester Karosserie und vielen Carbon-Komponenten. Optisch unverkennbar als Topmodell.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (468,'mercedes-benz-eqa-h243','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Design-Pakete. Verfügt über die grundlegenden EQA-Designmerkmale wie die Black Panel-Front und durchgehende Lichtbänder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (469,'mercedes-benz-eqa-h243','Progressive','Ausstattungslinie','Bietet zusätzliche Komfort- und Designelemente im Innen- und Außenbereich, wie zum Beispiel spezifische Leichtmetallräder und hochwertigere Interieur-Materialien.','Umfangreichere Ausstattung als die Basisversion, aber weniger sportlich als AMG Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (470,'mercedes-benz-eqa-h243','AMG Line','Ausstattungslinie','Sportlichere Optik durch AMG Styling-Elemente wie spezifische Front- und Heckschürzen, Seitenschweller, AMG Leichtmetallräder und eine tiefergelegte Fahrwerkseinstellung. Im Innenraum finden sich Sportsitze und ein Sportlenkrad.','Deutlich sportlichere Optik und Haptik im Vergleich zu Progressive, jedoch keine echten M-Modell-Leistungssteigerungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (471,'mercedes-benz-eqb-x243','Progressive','Ausstattungslinie','Serienmäßige Ausstattung, oft mit 18-Zoll-Leichtmetallrädern, LED High Performance-Scheinwerfern und Komfortsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (472,'mercedes-benz-eqb-x243','Electric Art','Ausstattungslinie','Betont elektrische Designelemente, oft mit spezifischen Leichtmetallrädern, blauen Akzenten im Interieur und speziellen Sitzbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (473,'mercedes-benz-eqb-x243','AMG Line','Ausstattungslinie','Sportlichere Optik mit AMG Styling-Elementen (Frontschürze, Heckschürze, Seitenschweller), spezifischen AMG Leichtmetallrädern und Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (474,'mercedes-benz-eqe-v295','Electric Art Line','Ausstattungslinie','Betont das progressive und luxuriöse Design mit spezifischen Zierelementen, Felgen und Interieurdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (475,'mercedes-benz-eqe-v295','AMG Line','Ausstattungslinie','Sportlichere Optik mit AMG-spezifischen Stoßfängern, Seitenschwellern, Felgen und Interieur (z.B. Sportsitze, Sportlenkrad).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (476,'mercedes-benz-eqe-v295','Mercedes-AMG EQE 43 4MATIC','M Performance','Dezente AMG-Optik mit spezifischen AMG-Felgen, Frontschürze und Heckdiffusor.','Erste Performance-Stufe von AMG mit höherer Leistung und sportlicherer Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (477,'mercedes-benz-eqe-v295','Mercedes-AMG EQE 53 4MATIC+','Echtes M-Modell','Aggressivere AMG-Optik mit spezifischen AMG-Felgen, Frontschürze, Heckdiffusor und optionalen Carbon-Paketen.','Top-Performance-Modell von AMG mit maximaler Leistung, umfangreichen Fahrwerksmodifikationen und spezifischen AMG-Fahrmodi.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (478,'mercedes-benz-eqs-v297','Standard','Basis','Klarer, eleganter Look mit serienmäßigen LED-Scheinwerfern und integriertem Mercedes-Stern im Black-Panel-Grill.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (479,'mercedes-benz-eqs-v297','AMG Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische AMG-Leichtmetallräder, Black-Panel-Grill mit AMG-spezifischer Optik (vertikale Streben oder Sternenmuster).','Betont die sportliche Seite des EQS mit dynamischeren Designelementen und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (480,'mercedes-benz-eqs-v297','Electric Art Line','Ausstattungslinie','Betont den luxuriösen und technologischen Charakter mit spezifischen Felgendesigns und Interieur-Akzenten.','Fokus auf Eleganz und moderne Ästhetik, oft mit helleren Interieurfarben und speziellen Zierelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (481,'mercedes-benz-eqs-v297','Mercedes-AMG EQS 53 4MATIC+','Echtes M-Modell','Eigenständige AMG-Frontschürze mit A-Wing-Design, AMG-spezifischer Black-Panel-Grill mit vertikalen Chromstreben, größere Bremsanlage, AMG-Leichtmetallräder, Heckspoiler.','Das Performance-Modell von AMG mit deutlich gesteigerter Leistung, sportlicherem Fahrwerk und spezifischen AMG-Designmerkmalen innen und außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (488,'bmw-3er-e21','315','Basis','Einzelscheinwerfer, einfachere Radkappen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (489,'bmw-3er-e21','316','Basis','Einzelscheinwerfer, einfachere Radkappen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (490,'bmw-3er-e21','318','Ausstattungslinie','Einzelscheinwerfer, oft mit Chromzierrat',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (491,'bmw-3er-e21','320','Ausstattungslinie','Doppelscheinwerfer, oft mit Chromzierrat',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (492,'bmw-3er-e21','320i','Ausstattungslinie','Doppelscheinwerfer, oft mit Chromzierrat, ''i''-Emblem',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (493,'bmw-3er-e21','323i','Ausstattungslinie','Doppelscheinwerfer, oft mit Chromzierrat, ''i''-Emblem, stärkster Motor der Baureihe',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (494,'bmw-3er-e30','Standard','Basis','Einfache Stoßstangen, kleinere Scheinwerfer (je nach Baujahr), weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (495,'bmw-3er-e30','Sport','Ausstattungslinie','Oft mit M-Technik-Paket (Sportfahrwerk, Schalensitze, M-Lenkrad, Spoilerlippen), größere Scheinwerfer, oft Alufelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (496,'bmw-3er-e30','M3','Echtes M-Modell','Deutlich modifizierte Karosserie mit breiteren Kotflügeln, spezifischen Spoilern, M-Spiegeln, eigenständigem Kühlergrill und Heckspoiler. Spezifische Felgen.','Deutlich aggressivere Optik und Performance im Vergleich zu den zivilen Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (502,'bmw-3er-e46','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (503,'bmw-3er-e46','Executive','Ausstattungslinie','Oft mit Leichtmetallrädern, Klimaautomatik, Multifunktionslenkrad.','Komfortorientierte Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (504,'bmw-3er-e46','Sport Edition','Ausstattungslinie','Sportfahrwerk, Sportsitze, M-Lederlenkrad, spezifische Leichtmetallräder.','Sportlichere Optik und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (505,'bmw-3er-e46','M Sportpaket','M Performance','M Aerodynamikpaket (spezifische Front- und Heckschürzen, Seitenschweller), M Sportfahrwerk, M Leichtmetallräder, Sportsitze, M Lederlenkrad.','Umfassendes Sportpaket mit optischen und technischen Verbesserungen, aber kein echtes M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (506,'bmw-3er-e46','M3','Echtes M-Modell','Breitere Kotflügel, spezifische Front- und Heckschürzen, Powerdome auf der Motorhaube, vier Endrohre, M-spezifische Leichtmetallräder, M-Außenspiegel.','Eigenständiges Hochleistungsmodell mit spezifischem Motor und Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (507,'bmw-3er-e90','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (508,'bmw-3er-e90','Edition Lifestyle','Ausstattungslinie','Spezielle Lackierungen, Leichtmetallräder, Interieur-Akzente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (509,'bmw-3er-e90','Edition Exclusive','Ausstattungslinie','Hochwertigere Materialien im Innenraum, spezielle Leichtmetallräder, Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (510,'bmw-3er-e90','M Sportpaket','M Performance','Aggressivere Front- und Heckschürzen, Seitenschweller, M-Leichtmetallräder, Sportfahrwerk, M-Lenkrad, Sportsitze.','Bietet sportliche Optik und Fahrwerksabstimmung, ist aber kein echtes M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (511,'bmw-3er-f30','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Design-Akzente. Schwarze Nierenstäbe, unlackierte Kunststoffteile an der Front- und Heckschürze (je nach Baujahr/Markt), kleinere Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (512,'bmw-3er-f30','Sport Line','Ausstattungslinie','Schwarze Hochglanz-Akzente an der Niere, den Lufteinlässen und der Heckschürze. Rote Kontrastnähte im Innenraum, Sportsitze, spezifische Leichtmetallräder.','Betont sportliche Optik und Haptik, unterscheidet sich durch rote Akzente und schwarze Hochglanz-Elemente von anderen Linien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (513,'bmw-3er-f30','Luxury Line','Ausstattungslinie','Chrom-Akzente an der Niere, den Lufteinlässen und der Heckschürze. Edlere Materialien im Innenraum, wie Holzapplikationen und Lederpolsterung, spezifische Leichtmetallräder.','Fokus auf Eleganz und Komfort durch Chrom-Details und hochwertige Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (514,'bmw-3er-f30','Modern Line','Ausstattungslinie','Satinierte Aluminium-Akzente an der Niere und den Lufteinlässen. Helle Innenraumfarben, offenporige Holzapplikationen, spezifische Leichtmetallräder.','Betont eine moderne, helle und minimalistische Ästhetik. Wurde später durch andere Linien ersetzt oder integriert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (515,'bmw-3er-f30','M Sportpaket','M Performance','Aggressivere Front- und Heckschürze, Seitenschweller, M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze, M spezifische Interieurleisten und Fußmatten. Blaue Bremssättel bei M Sportbremse.','Deutlich sportlichere Optik und Fahrdynamik durch aerodynamische Anbauteile, strafferes Fahrwerk und M-spezifische Details. Nicht zu verwechseln mit einem echten M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (520,'bmw-3er-g20-g21','M340i / M340d','M Performance','M spezifische Designelemente (z.B. Cerium Grey Akzente an Niere, Spiegelkappen), M Sportbremse, M Sportdifferenzial, trapezförmige Endrohre.','Leistungsstarke Motoren mit M Performance-Abstimmung, aber noch unterhalb der echten M-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (521,'bmw-3er-g20-g21','M3','Echtes M-Modell','Eigenständige, deutlich breitere Karosserie mit ausgestellten Radhäusern, große, vertikale Doppelniere, M spezifische Front- und Heckschürze, vier Endrohre, Carbon-Dach (optional).','Eigenständiger Hochleistungsmotor, umfassende Fahrwerksmodifikationen und ein deutlich aggressiveres Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (522,'bmw-5er-e12','Basis','Basis','Standardausstattung ohne spezifische sportliche oder luxuriöse Akzente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (523,'bmw-5er-e28','Basis','Basis','Standardausstattung ohne spezifische Sport- oder Luxusmerkmale.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (524,'bmw-5er-e28','M5','Echtes M-Modell','Dezente Sportoptik mit spezifischen Front- und Heckschürzen, Seitenschwellern, M-Emblemen und speziellen Felgen. Im Vergleich zu späteren M-Modellen optisch eher zurückhaltend.','Das Topmodell der Baureihe mit dem leistungsstarken M88/3 Reihensechszylinder-Motor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (525,'bmw-5er-e34','Basis','Basis','Standardausstattung ohne spezifische optische Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (526,'bmw-5er-e34','Executive','Ausstattungslinie','Oft mit Leichtmetallrädern, Holzapplikationen im Innenraum, Lederausstattung optional.','Fokus auf Komfort und gehobene Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (527,'bmw-5er-e34','Sportpaket','Ausstattungslinie','Sportfahrwerk, Sportsitze, M-Technic-Lenkrad, oft mit spezifischen Leichtmetallrädern.','Betont sportliche Fahreigenschaften und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (528,'bmw-5er-e34','M5','Echtes M-Modell','Eigenständige Front- und Heckschürzen, Seitenschweller, M-spezifische Leichtmetallräder (z.B. ''Turbinenräder''), M-Außenspiegel, M-Embleme.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor und Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (529,'bmw-5er-e39','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Sport- oder Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (530,'bmw-5er-e39','Executive','Ausstattungslinie','Oft mit Chromleisten an den Fenstern, hochwertigeren Interieurmaterialien wie Holzapplikationen, Komfortsitzen und erweiterten Komfortfunktionen.','Fokus auf Komfort und Eleganz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (531,'bmw-5er-e39','Sportpaket','Ausstattungslinie','Sportliche Stoßfänger (oft M-Technik-Optik), Sportfahrwerk, Sportsitze, M-Lederlenkrad, spezifische Leichtmetallräder.','Fokus auf sportliche Optik und Fahrdynamik, aber keine echten M-Motoren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (532,'bmw-5er-e39','M5','Echtes M-Modell','Eigenständige Front- und Heckschürzen, Seitenschweller, vier Endrohre, M-spezifische Leichtmetallräder, M-Außenspiegel, M-Embleme, M-Sportsitze, M-Kombiinstrument.','Eigenständiges Hochleistungsmodell mit exklusivem Motor und Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (533,'bmw-5er-e60','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (534,'bmw-5er-e60','Executive','Ausstattungslinie','Oft mit Chromapplikationen, Lederausstattung und erweiterten Komfortfunktionen.','Fokus auf Komfort und Eleganz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (535,'bmw-5er-e60','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezifische Leichtmetallräder, oft mit Shadow Line (schwarze Fensterrahmen statt Chrom).','Fokus auf Dynamik und sportliches Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (536,'bmw-5er-e60','M Sportpaket','M Performance','Aggressivere Front- und Heckschürzen, Seitenschweller, M-Leichtmetallräder, M-Sportfahrwerk, Sportsitze, M-Lederlenkrad, Shadow Line.','Optische und fahrwerkstechnische Annäherung an die M-Modelle, jedoch ohne deren Hochleistungsmotoren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (537,'bmw-5er-e60','M5','Echtes M-Modell','Eigenständige, sehr aggressive Front- und Heckschürzen, vier Endrohre, M-spezifische Leichtmetallräder, Kiemen an den vorderen Kotflügeln, M-Außenspiegel, M-Sportfahrwerk, M-Sportsitze, M-Lederlenkrad.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor (V10), verstärktem Fahrwerk und Bremsen, sowie spezifischen M-Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (538,'bmw-5er-f10','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Designelemente. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (539,'bmw-5er-f10','Luxury Line','Ausstattungslinie','Betont Eleganz und Komfort mit Chromapplikationen an der Niere, den Lufteinlässen und den Fensterrahmen. Spezifische Leichtmetallräder und Interieurleisten in Edelholz oder Hochglanzschwarz.','Fokus auf Luxus und Komfort, im Gegensatz zur sportlicheren Modern Line oder M Sport.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (540,'bmw-5er-f10','Modern Line','Ausstattungslinie','Setzt auf ein zeitgemäßes, helles Design mit satinierten Aluminium-Akzenten an der Niere, den Lufteinlässen und den Fensterrahmen. Spezifische Leichtmetallräder und helle Interieurfarben.','Fokus auf modernes, helles Design, im Gegensatz zur klassischen Eleganz der Luxury Line oder der Sportlichkeit der M Sport.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (541,'bmw-5er-f10','Sport Line','Ausstattungslinie','Betont die Sportlichkeit mit schwarzen Hochglanz-Akzenten an der Niere und den Lufteinlässen. Spezifische Leichtmetallräder und sportlichere Interieurdetails wie rote Kontrastnähte.','Fokus auf Sportlichkeit, aber weniger umfassend als das M Sport Paket.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (542,'bmw-5er-f10','M Sport Paket','M Performance','Umfasst ein M Aerodynamikpaket mit spezifischen Front- und Heckschürzen sowie Seitenschwellern. M Leichtmetallräder, M Sportfahrwerk, M Sportlenkrad und Sportsitze. Oft mit Shadow Line (schwarze Fensterrahmen).','Deutlich sportlichere Optik und Fahrdynamik im Vergleich zu den anderen Ausstattungslinien, aber kein echtes M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (543,'bmw-5er-f10','M5','Echtes M-Modell','Eigenständige, sehr aggressive Frontschürze mit großen Lufteinlässen, breitere Kotflügel, M-spezifische Seitenschweller, M-Außenspiegel, Heckschürze mit Diffusor und vier Endrohren. M-spezifische Leichtmetallräder und M-Bremsanlage.','Eigenständiges Hochleistungsmodell mit deutlich stärkerem Motor, angepasstem Fahrwerk und spezifischen M-Designelementen, die über das M Sport Paket hinausgehen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (544,'bmw-5er-g30','Basis','Basis','Serienausstattung ohne spezifische Designpakete. Meist kleinere Felgen, weniger Chromapplikationen, Standard-Stoßfänger.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (545,'bmw-5er-g30','Luxury Line','Ausstattungslinie','Betont Eleganz mit Chromapplikationen an der Niere, den Lufteinlässen, den Fensterrahmen und der Heckschürze. Spezifische Leichtmetallräder und Interieur-Akzente.','Fokus auf Komfort und Eleganz, im Gegensatz zur sportlicheren M Sport Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (546,'bmw-5er-g30','Sport Line','Ausstattungslinie','Sportlichere Akzente in Schwarz Hochglanz an der Niere und den Lufteinlässen. Spezifische Leichtmetallräder und sportlichere Sitze im Innenraum.','Sportlichere Optik als die Basis- oder Luxury Line, aber weniger umfassend als die M Sport Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (547,'bmw-5er-g30','M Sport Paket','Ausstattungslinie','Aggressiver gestaltete Front- und Heckschürzen, Seitenschweller, M Sportfahrwerk, M Leichtmetallräder, M Sportlenkrad, Sportsitze und spezifische Interieurleisten. Shadow Line (schwarze Zierleisten) oft optional oder serienmäßig.','Umfassendes Sportpaket, das sowohl Exterieur als auch Interieur und Fahrwerk umfasst. Deutlich sportlicher als Luxury oder Sport Line.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (548,'bmw-5er-g30','M Performance','M Performance','Deutlich sportlichere Optik und Technik als das M Sport Paket. Erkennbar an spezifischen Aerodynamik-Komponenten, größeren Bremsen, M Performance spezifischen Felgen, oft mit grauen oder schwarzen Akzenten (z.B. Außenspiegelkappen, Nierenrahmen). Leistungsgesteigerte Motoren.','Stellt eine Brücke zwischen den regulären Modellen mit M Sport Paket und den echten M-Modellen dar. Bietet mehr Leistung und sportlichere Abstimmung als das M Sport Paket, ist aber nicht so extrem wie ein M5.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (549,'bmw-7er-e23','Basis','Basis','Standard-Stoßstangen, einfache Scheinwerfer, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (550,'bmw-7er-e23','Highline','Ausstattungslinie','Umfangreichere Chrom-Pakete, oft mit Leder-Innenausstattung, Klimaanlage, elektrischen Fensterhebern.','Deutlich aufgewertete Innenausstattung und mehr Komfort-Features im Vergleich zur Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (551,'bmw-7er-e32','Basis','Basis','Standardausstattung ohne spezifische optische Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (552,'bmw-7er-e32','Highline','Ausstattungslinie','Umfasste oft erweiterte Lederausstattung, elektrische Sitze, Klimaautomatik und weitere Komfortmerkmale.','Fokus auf Luxus und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (553,'bmw-7er-e32','750iL','Ausstattungslinie','Längerer Radstand (L-Version), oft mit spezifischen Felgen und der V12-Motorisierung.','Topmodell mit V12-Motor und verlängertem Radstand, höchste Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (554,'bmw-7er-e38','Basis','Basis','Standard-Stoßfänger, keine spezifischen Embleme, in der Regel kleinere Felgen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (555,'bmw-7er-e38','Executive','Ausstattungslinie','Chromapplikationen, oft spezielle Leichtmetallräder, erweiterte Lederausstattung','Fokus auf Komfort und luxuriöse Ausstattung');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (556,'bmw-7er-e38','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezielle Leichtmetallräder, oft Shadow-Line (schwarze Zierleisten statt Chrom)','Fokus auf sportlicheres Fahrverhalten und Optik');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (557,'bmw-7er-e38','Highline','Ausstattungslinie','Umfangreichste Luxusausstattung, oft mit Volleder, Holzapplikationen, Komfortsitzen und weiteren Extras','Höchste Komfort- und Luxusausstattungslinie');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (558,'bmw-7er-e65/e66','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Chrom- oder Sportapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (559,'bmw-7er-e65/e66','Executive','Ausstattungslinie','Oft mit Chromzierleisten, Komfortsitzen, hochwertigeren Lederoptionen und erweiterten Holzapplikationen im Innenraum.','Fokus auf Komfort und Luxus, oft mit erweiterten Assistenzsystemen und Infotainment-Funktionen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (560,'bmw-7er-e65/e66','Sportpaket','Ausstattungslinie','Sportlichere Stoßfänger, größere Leichtmetallräder, Sportfahrwerk, Sportsitze und spezifische Interieurleisten (z.B. Aluminium oder dunkles Holz).','Betont die Fahrdynamik und ein sportlicheres Erscheinungsbild.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (561,'bmw-7er-f01/f02','Standard','Basis','Serienmäßige Felgen, dezente Chrom-Applikationen, Stoff- oder Lederpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (562,'bmw-7er-f01/f02','Luxury Line','Ausstattungslinie','Exklusivere Felgendesigns, zusätzliche Chrom-Elemente an Front und Heck, erweiterte Lederausstattung, Holzdekor.','Betont den luxuriösen Charakter mit mehr edlen Details im Innen- und Außenbereich.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (563,'bmw-7er-f01/f02','M Sportpaket','Ausstattungslinie','Sportlichere Stoßfänger, Seitenschweller, M-spezifische Felgen, M-Logo an verschiedenen Stellen, Sportsitze, M-Lenkrad.','Fokus auf eine sportlichere Optik und Haptik, ohne die Leistung zu steigern.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (564,'bmw-7er-g11/g12','Standard','Basis','Serienmäßige Felgen, dezente Chromapplikationen, Standard-Sitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (565,'bmw-7er-g11/g12','Design Pure Excellence','Ausstattungslinie','Größere Felgen, erweiterte Chrom-Elemente, exklusivere Leder- und Holzapplikationen im Innenraum, Komfortsitze.','Betont Luxus und Eleganz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (566,'bmw-7er-g11/g12','M Sportpaket','M Performance','Sportlichere Stoßfänger, Seitenschweller, spezifische Felgen, M-Logo, Sportsitze, M-Lenkrad.','Betont Sportlichkeit und Dynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (567,'bmw-7er-g70','Basis','Basis','Serienausstattung ohne spezifische Sport- oder Luxuspakete. Kann je nach Markt variieren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (568,'bmw-7er-g70','M Sport Paket','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische M Leichtmetallräder, M Hochglanz Shadow Line, M Sportbremse (optional).','Betont die sportliche Seite des Fahrzeugs, im Gegensatz zur eher luxuriösen oder dezenten Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (569,'bmw-7er-g70','Executive Lounge','Ausstattungslinie','Fokus auf Komfort und Luxus im Fond, oft mit speziellen Sitzen, Entertainment-Systemen und hochwertigeren Materialien.','Stärker auf den Chauffeur-Betrieb und den Komfort der Fondpassagiere ausgelegt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (570,'bmw-i4-g26','Basis','Basis','Standard-Stoßfänger, 17-Zoll-Leichtmetallräder, keine spezifischen Sport- oder Luxus-Akzente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (571,'bmw-i4-g26','M Sport','Ausstattungslinie','Aggressiver gestaltete Front- und Heckschürzen, M-spezifische Leichtmetallräder (oft 18 oder 19 Zoll), M Sportfahrwerk, M Sportlenkrad, Shadow Line Exterieurumfänge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (572,'bmw-i4-g26','M50','M Performance','Noch sportlichere M-Aerodynamik-Paket-Elemente, spezifische M Leichtmetallräder (oft 19 oder 20 Zoll), M Sportbremsanlage (oft mit blauen Sätteln), M Außenspiegelkappen in Cerium Grey, M Heckspoiler, M Performance spezifische Interieur-Details.','Das M50-Modell ist das erste rein elektrische M Performance Modell und bietet neben optischen Merkmalen auch eine deutlich höhere Leistung und ein angepasstes Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (573,'bmw-i5-g60','eDrive40','Ausstattungslinie','Serienmäßige 18-Zoll-Leichtmetallräder, spezifische i5-Elemente wie blaue Akzente, geschlossene Niere.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (574,'bmw-i5-g60','M60','M Performance','Serienmäßige 19-Zoll-Leichtmetallräder (optional größer), M spezifische Aerodynamik-Elemente, M-Sportfahrwerk, M-Sportbremse, schwarze Akzente.','Deutlich sportlicherer Auftritt im Vergleich zum eDrive40, M-spezifische Designmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (575,'bmw-i7-g70','i7 eDrive50','Basis','Standard-Exterieur und -Interieur, kann durch optionale Pakete wie M Sport oder Pure Excellence individualisiert werden.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (576,'bmw-i7-g70','i7 xDrive60','Ausstattungslinie','Standard-Exterieur und -Interieur, kann durch optionale Pakete wie M Sport oder Pure Excellence individualisiert werden. Äußerlich kaum vom eDrive50 zu unterscheiden, primär durch Motorisierung und Serienausstattung differenziert.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (577,'bmw-i7-g70','i7 M70 xDrive','M Performance','Serienmäßig mit M Sport Exterieur-Paket, spezifischen M Leichtmetallrädern, M Hochglanz Shadow Line, M Außenspiegeln und M Logos. Optional mit M Performance spezifischen Lackierungen und Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (578,'bmw-ix1-u11','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Designpakete. Kann blaue Akzente an Front, Seite und Heck aufweisen, die die elektrische Natur betonen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (579,'bmw-ix1-u11','xLine','Ausstattungslinie','Betont den robusten Offroad-Charakter mit spezifischen Stoßfängern, Unterfahrschutz-Optik in Silber, satinierten Aluminium-Akzenten an der Niere und den Fensterrahmen sowie spezifischen Leichtmetallrädern.','Fokus auf Robustheit und Outdoor-Look im Vergleich zur Basis und M Sport.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (580,'bmw-ix1-u11','M Sport','M Performance','Sportlichere Optik mit M Aerodynamikpaket (spezifische Front- und Heckschürze, Seitenschweller), M Hochglanz Shadow Line, M spezifischen Leichtmetallrädern und optionalen M Sportbremsen. Die blauen iX1-Akzente entfallen hier zugunsten einer sportlicheren, einheitlichen Optik.','Deutlich sportlichere Ausrichtung und Optik im Vergleich zur Basis und xLine.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (581,'bmw-ix3-g08','Inspiring','Ausstattungslinie','Umfasst in der Regel 19-Zoll-Leichtmetallräder, LED-Scheinwerfer, Sportsitze, Klimaautomatik und ein Navigationssystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (582,'bmw-ix3-g08','Impressive','Ausstattungslinie','Baut auf ''Inspiring'' auf und ergänzt meist 20-Zoll-Leichtmetallräder, adaptive LED-Scheinwerfer, Head-up-Display, Harman Kardon Soundsystem und erweiterte Fahrerassistenzsysteme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (583,'audi-a1-8x','Attraction','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (584,'audi-a1-8x','Ambition','Ausstattungslinie','Sportlichere Optik mit größeren Leichtmetallrädern, Sportfahrwerk und sportlicheren Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (585,'audi-a1-8x','S line','Ausstattungslinie','Noch sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, S line Schriftzügen und oft größeren Rädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (586,'audi-a1-8x','active kit','Ausstattungslinie','Offroad-Look mit spezifischen Anbauteilen wie Radlaufblenden und Stoßfängern im SUV-Stil.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (587,'audi-a1-gb','Basis','Basis','Serienmäßige Ausstattung, 15-Zoll-Räder, schwarze Kunststoffelemente an den Schwellern und Radläufen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (588,'audi-a1-gb','advanced','Ausstattungslinie','Sportlichere Optik mit 16-Zoll-Rädern, spezifische Stoßfänger und Diffusor-Optik am Heck.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (589,'audi-a1-gb','S line','Ausstattungslinie','Noch sportlichere Optik mit 17-Zoll-Rädern, S line Stoßfänger, S line Dachkantenspoiler und spezifischen Lufteinlässen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (590,'audi-a1-gb','edition one','Ausstattungslinie','Sondermodell zur Markteinführung mit exklusiven Designelementen, wie z.B. 18-Zoll-Räder, schwarze Akzente und spezielle Lackierungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (591,'audi-a3-typ-8l','Attraction','Ausstattungslinie','Komfortorientierte Basisausstattung, oft mit kleineren Rädern und weniger sportlichen Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (592,'audi-a3-typ-8l','Ambition','Ausstattungslinie','Sportlichere Ausstattung mit strafferem Fahrwerk, Sportsitzen und größeren Rädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (593,'audi-a3-typ-8l','Ambiente','Ausstattungslinie','Luxuriösere Ausstattung mit Komfortmerkmalen wie Klimaautomatik, Holz- oder Aluminiumapplikationen und Velours- oder Ledersitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (594,'audi-a3-typ-8l','S3','Echtes M-Modell','Deutlich sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, Dachspoiler, 17-Zoll-Leichtmetallrädern, Bi-Xenon-Scheinwerfern (nach Facelift) und zwei Endrohren. Innen Sportsitze und spezifische Dekoreinlagen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (595,'audi-a3-typ-8p','Attraction','Basis','Serienmäßige Ausstattung, oft mit kleineren Rädern und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (596,'audi-a3-typ-8p','Ambition','Ausstattungslinie','Sportlichere Ausrichtung mit Sportfahrwerk, Sportsitzen, größeren Leichtmetallrädern und spezifischen Interieurdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (597,'audi-a3-typ-8p','Ambiente','Ausstattungslinie','Komfortorientierte Ausstattung mit Komfortfahrwerk, hochwertigeren Materialien im Innenraum, oft mit Holz- oder Aluminiumeinlagen und zusätzlichen Komfortfunktionen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (598,'audi-a3-typ-8p','S line','Ausstattungslinie','Umfasst ein Sportpaket mit spezifischen Stoßfängern, Seitenschwellern, S line Schriftzügen, Sportfahrwerk und exklusiven Leichtmetallrädern. Innenraum mit Sportsitzen, S line Lenkrad und Dekoreinlagen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (599,'audi-a3-typ-8p','S3','M Performance','Deutlich sportlichere Optik mit spezifischen Stoßfängern, breiteren Schwellern, vierflutiger Abgasanlage, S3-Emblemen und größeren Rädern. Innenraum mit Sportsitzen und S3-spezifischen Details.','Leistungsstärkeres Modell mit Allradantrieb und sportlicherer Abstimmung als die zivilen A3-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (600,'audi-a3-typ-8p','RS3','Echtes M-Modell','Extrem sportliche Optik mit verbreiterten Radhäusern, RS-spezifischen Stoßfängern, großem Singleframe-Kühlergrill mit Wabenstruktur, ovalen Endrohren und RS-Emblemen. Innenraum mit RS-Sportsitzen und exklusiven Materialien.','Das Topmodell der Baureihe mit dem leistungsstärksten Motor (Fünfzylinder-Turbo) und einer nochmals geschärften Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (601,'audi-a3-typ-8v','Attraction','Basis','Grundausstattung, oft mit kleineren Rädern und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (602,'audi-a3-typ-8v','Ambition','Ausstattungslinie','Sportlicher ausgerichtet, oft mit größeren Rädern, Sportfahrwerk und Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (603,'audi-a3-typ-8v','Ambiente','Ausstattungslinie','Komfortorientiert, oft mit hochwertigeren Materialien im Innenraum, Komfortsitzen und zusätzlichen Chromdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (604,'audi-a3-typ-8v','S line','Ausstattungslinie','Umfasst ein sportliches Exterieur-Paket (spezifische Stoßfänger, Seitenschweller, S line Schriftzüge), Sportfahrwerk und S line Interieur-Details.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (605,'audi-a3-typ-8v','S3','M Performance','Deutlich sportlichere Optik mit spezifischen Stoßfängern, vierflutiger Abgasanlage, S-spezifischem Kühlergrill und größeren Rädern.','Leistungsstärkeres Modell mit Allradantrieb und sportlicherer Abstimmung als die zivilen A3-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (606,'audi-a3-typ-8v','RS3','Echtes M-Modell','Aggressivste Optik mit breiteren Radhäusern, RS-spezifischem Singleframe-Grill mit Quattro-Schriftzug, großen Lufteinlässen, ovalen Endrohren und RS-spezifischen Felgen.','Top-Modell der Baureihe mit dem 2.5 TFSI Fünfzylinder-Motor, extrem hoher Leistung und Rennstrecken-orientierter Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (607,'audi-a3-typ-8y','A3','Basis','Grundausstattung, oft mit kleineren Rädern und weniger sportlichen Anbauteilen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (608,'audi-a3-typ-8y','advanced','Ausstattungslinie','Betont die Eleganz und den Komfort, oft mit Chromapplikationen, spezifischen Felgendesigns und hochwertigeren Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (609,'audi-a3-typ-8y','S line','Ausstattungslinie','Sportlichere Optik mit S line Stoßfängern, Seitenschwellern, Sportfahrwerk, S line Emblemen und spezifischen Felgen. Im Innenraum Sportsitze und S line Lenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (610,'audi-a3-typ-8y','A3 allstreet','Ausstattungslinie','Erhöhte Bodenfreiheit, spezifische Offroad-Optik mit Radlaufblenden, Unterfahrschutz-Elementen und eigenständigem Kühlergrill. Nur als Sportback verfügbar.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (611,'audi-a3-typ-8y','S3','M Performance','Deutlich sportlichere Front- und Heckschürzen, vierflutige Abgasanlage, größere Bremsen, spezifische S-Design-Felgen, S-Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (612,'audi-a3-typ-8y','RS3','Echtes M-Modell','Extrem aggressive Optik mit breiteren Radläufen, RS-spezifischem Singleframe-Grill, großen Lufteinlässen, RS-Sportabgasanlage mit ovalen Endrohren, RS-Bremsanlage, RS-Felgen und RS-Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (613,'audi-a4-b5','Basis','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Polsterstoffe',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (614,'audi-a4-b5','Ambition','Ausstattungslinie','Sportfahrwerk, Sportsitze, Leichtmetallräder, Sportlenkrad','Fokus auf sportliche Optik und Fahrdynamik');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (615,'audi-a4-b5','Ambiente','Ausstattungslinie','Komfortsitze, Holz- oder Aluminiumeinlagen im Innenraum, Leichtmetallräder, oft Klimaautomatik','Fokus auf Komfort und Eleganz');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (616,'audi-a4-b5','Attraction','Ausstattungslinie','Leichtmetallräder, verbesserte Polsterstoffe, oft elektrische Fensterheber vorn','Fokus auf eine ausgewogene Ausstattung mit gehobenem Standard');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (617,'audi-a4-b5','S line','Ausstattungslinie','Sportliche Stoßfänger, S line Schriftzüge, spezielle Leichtmetallräder, Sportsitze, Sportfahrwerk','Noch sportlicher als Ambition, oft erst nach dem Facelift verfügbar');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (618,'audi-a4-b5','S4','Echtes M-Modell','Eigenständige Front- und Heckschürzen, breitere Kotflügel, spezielle Leichtmetallräder, vierflutige Abgasanlage, S4-Embleme, Sportsitze mit S4-Prägung','Eigenständiges Hochleistungsmodell mit V6 Biturbo Motor');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (619,'audi-a4-b5','RS4','Echtes M-Modell','Extrem verbreiterte Kotflügel, eigenständige Front- und Heckschürzen, große Lufteinlässe, spezielle 18-Zoll-Leichtmetallräder, ovale Endrohre, RS4-Embleme, Recaro Sportsitze','Top-Hochleistungsmodell, nur als Avant erhältlich, mit V6 Biturbo Motor und nochmals gesteigerter Leistung');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (620,'audi-a4-b6','Basis','Basis','Standard-Stoßfänger, kleinere Radgrößen, oft ohne Nebelscheinwerfer, schwarze Fensterrahmen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (621,'audi-a4-b6','Ambition','Ausstattungslinie','Sportfahrwerk, Sportsitze, Leichtmetallräder, oft mit Nebelscheinwerfern','Fokus auf sportliche Optik und Fahrdynamik');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (622,'audi-a4-b6','Ambiente','Ausstattungslinie','Komfortsitze, Holz- oder Aluminiumeinlagen im Innenraum, oft mit Klimaautomatik und weiteren Komfortfeatures','Fokus auf Komfort und Eleganz');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (623,'audi-a4-b6','S line','Ausstattungslinie','Spezifische Front- und Heckstoßfänger, S line Schriftzüge, Sportfahrwerk, größere Leichtmetallräder, Sportsitze mit S line Prägung','Deutlich sportlichere Optik und Fahrwerksabstimmung, angelehnt an die S-Modelle');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (624,'audi-a4-b7','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Zierleisten',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (625,'audi-a4-b7','Ambition','Ausstattungslinie','Sportfahrwerk, Sportsitze, 17-Zoll-Leichtmetallräder, Aluminium-Dekoreinlagen','Betont sportliche Ausrichtung');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (626,'audi-a4-b7','Ambiente','Ausstattungslinie','Komfortfahrwerk, Komfortsitze, 16-Zoll-Leichtmetallräder, Holz- oder Aluminium-Dekoreinlagen, Lichtpaket','Betont Komfort und Eleganz');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (627,'audi-a4-b7','S line','Ausstattungslinie','S line Exterieurpaket (spezifische Stoßfänger, Kühlergrill, S line Schriftzüge), S line Sportfahrwerk, Sportsitze mit S line Prägung, 18-Zoll-Leichtmetallräder','Umfassendes Sportpaket mit optischen und technischen Modifikationen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (628,'audi-a4-b7','S4','M Performance','Dezente sportliche Modifikationen, vierflutige Abgasanlage, spezifische S-Modell-Felgen, Aluminium-Außenspiegelgehäuse','Sportmodell mit leistungsstärkerem Motor (V8) und angepasstem Fahrwerk, aber noch unterhalb des RS-Modells positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (629,'audi-a4-b7','RS4','Echtes M-Modell','Breitere Kotflügel, große Lufteinlässe, RS-spezifische Stoßfänger, ovale Endrohre, RS-Felgen, tiefergelegtes Fahrwerk','Top-Sportmodell mit hochdrehendem V8-Motor, deutlich verbreiterter Karosserie und maximaler Performance-Ausrichtung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (630,'audi-a4-b8','Basis','Basis','Einfache Stoffpolster, 16-Zoll-Stahlräder mit Radkappen oder einfache Leichtmetallräder, schwarze Fensterrahmen, keine Nebelscheinwerfer (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (631,'audi-a4-b8','Attraction','Ausstattungslinie','Stoffausstattung, 16-Zoll-Leichtmetallräder, schwarze Fensterrahmen.','Fokus auf Komfort und Funktionalität, ohne sportliche oder luxuriöse Akzente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (632,'audi-a4-b8','Ambition','Ausstattungslinie','Sportsitze vorne, Sportfahrwerk, 17-Zoll-Leichtmetallräder, Aluminium-Dekoreinlagen, verchromte Auspuffendrohre (modellabhängig).','Betont sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (633,'audi-a4-b8','Ambiente','Ausstattungslinie','Lederlenkrad, Klimaautomatik, Licht-/Regensensor, Geschwindigkeitsregelanlage, 17-Zoll-Leichtmetallräder, Chrompaket außen (Fensterrahmen, Dachreling bei Avant).','Fokus auf Komfort und Eleganz mit hochwertigerer Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (634,'audi-a4-b8','S line Sportpaket','Ausstattungslinie','S line Sportfahrwerk, 18-Zoll-Leichtmetallräder, S line Stoßfänger vorne und hinten, S line Schriftzüge, Sportsitze mit S line Prägung, schwarzer Dachhimmel.','Umfassendes Sportpaket mit optischen und fahrdynamischen Verbesserungen, die über die Ambition-Linie hinausgehen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (635,'audi-a4-b8','S line Exterieurpaket','Ausstattungslinie','S line Stoßfänger vorne und hinten, S line Kühlergrill, S line Schriftzüge, verchromte Auspuffendrohre (modellabhängig).','Rein optisches Paket, das dem Fahrzeug eine sportlichere Erscheinung verleiht, ohne das Fahrwerk oder den Innenraum zu beeinflussen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (643,'audi-a4-b9','Basis','Basis','Grundausstattung, oft mit kleineren Felgen, weniger Chromapplikationen und einfacheren Interieurmaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (644,'audi-a4-b9','design','Ausstattungslinie','Betont Eleganz und Komfort mit spezifischen Stoßfängern, Chromzierleisten und hochwertigeren Materialien im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (645,'audi-a4-b9','sport','Ausstattungslinie','Betont Sportlichkeit mit spezifischen Stoßfängern, Sportfahrwerk (optional), Sportsitzen und sportlichen Akzenten im Interieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (646,'audi-a4-b9','S line','Ausstattungslinie','Umfasst sportliche Exterieur- und Interieur-Pakete, oft mit S line Stoßfängern, größeren Rädern, Sportfahrwerk und S line Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (647,'audi-a4-b9','Black Edition','Ausstattungslinie','Basierend auf S line, aber mit schwarzen Designelementen wie Kühlergrill, Fensterleisten und Außenspiegelgehäusen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (648,'audi-a4-b9','S4','M Performance','Deutlich sportlichere Optik mit spezifischen Stoßfängern, vierflutiger Abgasanlage, S-spezifischem Kühlergrill und größeren Bremsen. Im Innenraum Sportsitze und S-spezifische Details.','Deutlich leistungsstärkerer Motor (V6-Turbobenziner oder V6-Turbodiesel nach Facelift) und sportlichere Fahrwerksabstimmung als die zivilen A4-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (649,'audi-a4-b9','RS4 Avant','Echtes M-Modell','Extrem sportliche Optik mit verbreiterten Radhäusern, großen Lufteinlässen, RS-spezifischem Kühlergrill, ovalen Endrohren und großen Leichtmetallrädern. Im Innenraum RS-Sportsitze und Carbon-Applikationen.','Top-Modell der Baureihe mit Biturbo-V6-Motor, RS-spezifischem Fahrwerk, Allradantrieb quattro und extrem hoher Performance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (650,'audi-a5-i','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Exterieur-Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (651,'audi-a5-i','Ambition','Ausstattungslinie','Sportlichere Sitze, Sportfahrwerk (optional), größere Felgen als Basis.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (652,'audi-a5-i','Ambiente','Ausstattungslinie','Komfortorientierte Ausstattung, oft mit Holz- oder Aluminiumeinlagen im Innenraum, Komfortsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (653,'audi-a5-i','S line','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, S line Schriftzüge, Sportfahrwerk, größere Räder, Sportsitze, schwarzer Dachhimmel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (654,'audi-a5-i','S5','M Performance','Eigenständige Front- und Heckschürzen, vierflutige Abgasanlage, S-spezifische Kühlergrill-Optik, Aluminium-Außenspiegelgehäuse, größere Bremsanlage, S-Sportsitze.','Deutlich leistungsstärker als die zivilen A5-Modelle, aber unterhalb des RS5 positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (655,'audi-a5-i','RS5','Echtes M-Modell','Breitere Radhäuser, RS-spezifische Frontschürze mit großen Lufteinlässen, RS-Kühlergrill, ovale Endrohre, feststehender Heckspoiler (Coupé) oder adaptiver Spoiler (Sportback), RS-Sportsitze, Carbon-Applikationen.','Das Topmodell der Baureihe mit eigenständigem Hochleistungsmotor und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (656,'audi-a5-ii','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, grundlegende Interieur-Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (657,'audi-a5-ii','design','Ausstattungslinie','Spezifische Stoßfänger mit Chromapplikationen, glänzende Zierleisten, spezielle Felgendesigns, Interieur mit farbigen Akzenten und hochwertigeren Materialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (658,'audi-a5-ii','sport','Ausstattungslinie','Sportlichere Stoßfänger, größere Felgen, Sportsitze, Sportfahrwerk (optional), Aluminium-Applikationen im Interieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (659,'audi-a5-ii','S line','Ausstattungslinie','Aggressiver gestaltete Stoßfänger vorne und hinten, S line Schriftzüge, Sportfahrwerk (optional), größere Felgen, Sportsitze mit S line Prägung, schwarzer Dachhimmel, gelochte Bremsscheiben (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (660,'audi-a5-ii','S5','M Performance','Eigenständige Front- und Heckschürzen, vier Endrohre, S-spezifischer Kühlergrill, größere Bremsanlage, S-Sportsitze, spezifische Leichtmetallräder.','Deutlich leistungsstärker als die zivilen A5-Modelle, mit sportlicherer Fahrwerksabstimmung und spezifischen Antriebssträngen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (661,'audi-a5-ii','RS5','Echtes M-Modell','Extrem aggressive Frontschürze mit großen Lufteinlässen, breitere Radhäuser, RS-spezifischer Kühlergrill, ovale Endrohre, RS-Sportsitze, RS-spezifische Leichtmetallräder, RS-Sportfahrwerk.','Das Topmodell der Baureihe mit dem stärksten Motor, maximaler Performance und einer nochmals geschärften Optik und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (662,'audi-a6-c4','Basis','Basis','Einfache Ausstattung, oft mit Stahlfelgen und Radkappen, unlackierte Stoßleisten (je nach Markt und Baujahr).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (663,'audi-a6-c4','Ambition','Ausstattungslinie','Sportlichere Akzente, oft mit Leichtmetallfelgen, Sportfahrwerk, Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (664,'audi-a6-c4','Ambiente','Ausstattungslinie','Komfortorientierte Ausstattung, oft mit hochwertigeren Stoffen oder Leder, Holzapplikationen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (665,'audi-a6-c4','Avantgarde','Ausstattungslinie','Luxuriösere Ausstattung, oft mit Vollausstattung, speziellen Leichtmetallfelgen, Lederinterieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (666,'audi-a6-c4','S6','Echtes M-Modell','Deutlich sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, größeren Leichtmetallfelgen, doppelten Endrohren, S6-Emblemen.','Topmodell mit leistungsstärkeren Motoren (V8 oder 2.2 Turbo Fünfzylinder), Sportfahrwerk, Sportbremsanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (667,'audi-a6-c5','Basis','Basis','Standard-Stoßfänger, kleinere Radgrößen, keine Chromapplikationen (außer Fensterrahmen)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (668,'audi-a6-c5','Ambition','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezifische Leichtmetallräder','Fokus auf sportliche Optik und Fahrdynamik');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (669,'audi-a6-c5','Ambiente','Ausstattungslinie','Komfortsitze, Holz- oder Aluminiumeinlagen im Innenraum, spezifische Leichtmetallräder','Fokus auf Komfort und Eleganz');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (670,'audi-a6-c5','Advance','Ausstattungslinie','Kombination aus Komfort- und Sportelementen, oft mit zusätzlichen Ausstattungsdetails','Umfassendere Ausstattungspakete');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (671,'audi-a6-c5','S line','Ausstattungslinie','Sportliche Stoßfänger, Seitenschweller, S line Schriftzüge, Sportfahrwerk, größere Räder','Deutlich sportlichere Optik und Fahrwerksabstimmung, angelehnt an S-Modelle');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (672,'audi-a6-c5','S6','Echtes M-Modell','Eigenständige Front- und Heckschürzen, breitere Kotflügel, vierflutige Abgasanlage, spezifische S6-Räder, Aluminium-Außenspiegel','Hochleistungsmodell mit V8-Motor und Allradantrieb, eigenständige Fahrwerksabstimmung');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (673,'audi-a6-c5','RS6','Echtes M-Modell','Nochmals breitere Kotflügel, aggressive Frontschürze mit großen Lufteinlässen, ovale Endrohre, RS6-spezifische Räder, Dachspoiler (Avant)','Top-Performance-Modell mit Biturbo-V8-Motor, nochmals verstärktem Fahrwerk und Bremsen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (674,'audi-a6-c5','allroad quattro','Ausstattungslinie','Unlackierte Radlaufverbreiterungen und Stoßfängerunterteile, erhöhte Bodenfreiheit, Dachreling, Unterfahrschutz-Optik','Geländegängige Variante mit Luftfederung und permanentem Allradantrieb');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (675,'audi-a6-c6','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, keine spezifischen Designelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (676,'audi-a6-c6','S line','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Schriftzüge, Sportfahrwerk, größere Leichtmetallräder, Sportsitze im Innenraum.','Betont die sportliche Optik und Fahrdynamik, ohne die Leistungssteigerung eines S- oder RS-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (677,'audi-a6-c6','quattro GmbH (Individualisierung)','Ausstattungslinie','Umfassende Individualisierungsmöglichkeiten für Lackierung, Interieur und Ausstattung, oft mit exklusiven Materialien und Designs.','Bietet eine höhere Exklusivität und Personalisierung als die regulären Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (678,'audi-a6-c6','S6','Echtes M-Modell','Dezente, aber sportliche Karosserieanpassungen (z.B. spezifische Stoßfänger, vierflutige Abgasanlage, S6-Embleme), größere Bremsanlage, spezifische Leichtmetallräder, Aluminium-Außenspiegelgehäuse.','Deutlich leistungsstärker als die zivilen A6-Modelle, mit V10-Motor und sportlicherer Abstimmung von Fahrwerk und Bremsen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (679,'audi-a6-c6','RS6','Echtes M-Modell','Breitere Kotflügel, aggressivere Front- und Heckschürzen, ovale Doppelendrohre, RS6-Embleme, große Bremsanlage, spezifische RS-Räder, Lufteinlässe in der Motorhaube.','Das Topmodell der Baureihe mit extrem hoher Leistung (V10 Biturbo), maximaler Fahrdynamik und einer deutlich aggressiveren Optik als der S6.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (680,'audi-a6-c7','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Designpakete. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (681,'audi-a6-c7','Sport','Ausstattungslinie','Sportlichere Stoßfänger, Sportfahrwerk (optional), Sportsitze, spezifische Felgendesigns, oft mit glänzend schwarzen oder Aluminium-Applikationen im Interieur.','Fokus auf sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (682,'audi-a6-c7','Design','Ausstattungslinie','Elegantere Stoßfänger, Chromapplikationen außen, Komfortsitze, spezifische Felgendesigns, hochwertige Materialien und Dekoreinlagen im Interieur.','Fokus auf Eleganz und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (683,'audi-a6-c7','S line','Ausstattungslinie','Aggressiver gestaltete Stoßfänger, S line Schriftzüge, Sportfahrwerk, Sportsitze, spezifische Felgen, oft mit schwarzem Dachhimmel und Aluminium-Dekoreinlagen.','Umfasst das S line Exterieur- und Interieurpaket, welches eine sportlichere Optik und Ausstattung bietet als die ''Sport''-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (684,'audi-a6-c7','allroad quattro','Ausstattungslinie','Eigene Karosserie mit Radlaufverbreiterungen und Seitenschwellern in Kontrastfarbe (oft Grau), Unterfahrschutz vorne und hinten, erhöhte Bodenfreiheit, spezifischer Kühlergrill mit vertikalen Chromstreben, Dachreling.','Eigenständiges Modell mit Offroad-Optik und -Fähigkeiten, serienmäßig mit Luftfederung und quattro-Antrieb.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (685,'audi-a6-c7','S6','M Performance','Deutlich sportlichere Stoßfänger, S-spezifischer Kühlergrill, vierflutige Abgasanlage, S-spezifische Felgen, Aluminium-Außenspiegelgehäuse, Sportsitze mit S-Prägung, S-Lenkrad.','Leistungsgesteigertes Modell mit sportlicherer Abstimmung und Optik, aber unterhalb des RS6 positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (686,'audi-a6-c7','RS6 Avant','Echtes M-Modell','Extrem breite Radhäuser, RS-spezifische Stoßfänger mit großen Lufteinlässen, RS-Kühlergrill mit Wabenstruktur, ovale Doppelendrohre, RS-spezifische Felgen, RS-Sportsitze, RS-Lenkrad, RS-spezifische Instrumente.','Das Topmodell der Baureihe mit maximaler Leistung und extrem sportlicher Auslegung, nur als Avant erhältlich.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (687,'audi-a6-c8','Basis','Basis','Standard-Stoßfänger, kleinere Felgen, weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (688,'audi-a6-c8','sport','Ausstattungslinie','Sportlichere Stoßfänger, spezifische Felgen, Sportsitze, sportlich abgestimmtes Fahrwerk (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (689,'audi-a6-c8','design','Ausstattungslinie','Elegantere Stoßfänger, spezifische Felgen, erweiterte Chrom- oder Aluminiumapplikationen, Komfortsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (690,'audi-a6-c8','S line','Ausstattungslinie','Sehr sportliche Stoßfänger, S line Schriftzüge, größere Felgen, Sportfahrwerk, Sportsitze mit S line Prägung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (691,'audi-a6-c8','S6','M Performance','Eigenständige Front- und Heckschürzen, vier Endrohre, S-spezifischer Kühlergrill, größere Bremsanlage, S-Sportsitze.','Deutlich leistungsstärker als die zivilen Modelle, aber unterhalb des RS6 positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (692,'audi-a6-c8','RS6 Avant','Echtes M-Modell','Extrem verbreiterte Radhäuser, eigenständige Front mit großen Lufteinlässen, ovale Doppelendrohre, RS-spezifischer Kühlergrill, RS-Sportsitze, RS-Bremsanlage.','Das Topmodell der Baureihe mit maximaler Performance und eigenständiger Karosserie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (693,'audi-a7-typ-4g','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Sport- oder Designpakete. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (694,'audi-a7-typ-4g','S line Sportpaket','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Schriftzüge, Sportfahrwerk, größere Leichtmetallräder, Sportsitze im Innenraum.','Fokus auf sportliche Optik und Fahrdynamik, ohne die Leistungssteigerung eines S- oder RS-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (695,'audi-a7-typ-4g','S line Exterieurpaket','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Schriftzüge, Diffusoreinsatz am Heck.','Rein optisches Paket, das die sportliche Erscheinung des Fahrzeugs betont, ohne Änderungen am Fahrwerk oder Interieur des S line Sportpakets.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (696,'audi-a7-typ-4g','design selection','Ausstattungslinie','Exklusive Farbkombinationen und Materialien im Innenraum, spezielle Dekoreinlagen, oft mit Komfortsitzen.','Fokus auf luxuriöse und individuelle Innenraumgestaltung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (697,'audi-a7-typ-4g','Audi S7','M Performance','Eigenständige Front- und Heckschürzen, vierflutige Abgasanlage, S-spezifische Kühlergrill-Optik, größere Bremsanlage, S-Embleme.','Deutlich leistungsstärker als die zivilen A7-Modelle, aber unterhalb des RS7 positioniert. Bietet eine sportliche Performance mit hohem Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (698,'audi-a7-typ-4g','Audi RS7','Echtes M-Modell','Extrem aggressive Frontschürze mit großen Lufteinlässen, breitere Kotflügel, RS-spezifischer Kühlergrill, ovale Doppelendrohre, RS-Bremsanlage, RS-Embleme.','Das Topmodell der Baureihe mit maximaler Performance und Rennsport-Genen. Deutlich leistungsstärker und optisch aggressiver als der S7.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (699,'audi-a7-typ-4k','Basis','Basis','Standard-Exterieur und Interieur, oft mit kleineren Felgen und weniger sportlichen Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (700,'audi-a7-typ-4k','advanced','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische Felgen, oft Chrom-Applikationen.','Positioniert über der Basislinie, bietet eine sportlichere Optik und erweiterte Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (701,'audi-a7-typ-4k','S line','Ausstattungslinie','Sehr sportliches Exterieur mit S line Stoßfängern, Seitenschwellern, S line Emblemen, Sportfahrwerk und spezifischen Felgen. Im Interieur Sportsitze, S line Lenkrad und Dekoreinlagen.','Die sportlichste Ausstattungslinie unterhalb der echten S- und RS-Modelle, mit Fokus auf Dynamik und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (702,'audi-a7-typ-4k','S7','M Performance','Eigenständige Front- und Heckschürzen, vier Endrohre, S-spezifische Felgen, Aluminium-Optik an Spiegeln und Zierleisten.','Deutlich leistungsstärker als die zivilen A7-Modelle, mit sportlicherem Fahrwerk und Bremsen, aber noch unterhalb des RS7 positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (703,'audi-a7-typ-4k','RS7','Echtes M-Modell','Extrem aggressive Front mit breiteren Radhäusern, RS-spezifischer Singleframe-Grill, große Lufteinlässe, ovale Doppelendrohre, RS-spezifische Felgen und Bremsanlagen.','Das Topmodell der Baureihe mit maximaler Leistung, Rennsport-Technologie und einer kompromisslos sportlichen Auslegung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (704,'audi-a8-d2','Basis','Basis','Serienausstattung ohne spezifische Sport- oder Luxuspakete. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (705,'audi-a8-d2','S8','Echtes M-Modell','Sportlichere Front- und Heckschürzen, spezifische 18-Zoll-Leichtmetallräder, verchromte Außenspiegelgehäuse, S8-Embleme. Im Innenraum Sportsitze und spezifische Dekoreinlagen.','Deutlich sportlichere Abstimmung von Fahrwerk und Motorisierung (stärkerer Motor, strafferes Fahrwerk, größere Bremsen) im Vergleich zu den zivilen A8-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (706,'audi-a8-d3','Basis','Basis','Serienmäßige Ausstattung ohne spezifische optische Pakete.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (707,'audi-a8-d3','S line','Ausstattungslinie','Sportlichere Front- und Heckstoßstangen, Seitenschweller, S line Embleme, größere Leichtmetallräder, Sportfahrwerk.','Betont die sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (708,'audi-a8-d4','Basis','Basis','Serienausstattung ohne spezifische Sport- oder Luxuspakete. Kann je nach Markt variieren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (709,'audi-a8-d4','S line','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Schriftzüge, Sportfahrwerk (optional), größere Räder, Sportsitze im Innenraum.','Betont die sportliche Seite des Fahrzeugs, ohne ein echtes S-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (710,'audi-a8-d4','Audi design selection','Ausstattungslinie','Exklusive Farbkombinationen für Interieur, hochwertige Materialien wie spezielle Leder- und Holzapplikationen, erweiterte Komfortausstattung.','Fokus auf luxuriöse und individuelle Gestaltung des Innenraums.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (711,'audi-a8-d5','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Sport- oder Designelemente. Fokus auf Komfort und Eleganz.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (712,'audi-a8-d5','S line','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Embleme, spezifische Leichtmetallräder, oft dunklere Akzente und Sportfahrwerk.','Betont die sportliche Seite des A8, ohne ein echtes S-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (713,'audi-a8-d5','Audi design selection','Ausstattungslinie','Exklusive Interieur-Farb- und Materialkombinationen, spezielle Dekoreinlagen, hochwertige Leder- und Stoffbezüge.','Fokus auf luxuriöse und individuelle Gestaltung des Innenraums.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (714,'audi-q2-ga','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Designpakete, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (715,'audi-q2-ga','design','Ausstattungslinie','Betont das elegante und urbane Design mit spezifischen Stoßfängern, Kontrastlackierung für das Blade an der C-Säule und speziellen Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (716,'audi-q2-ga','sport','Ausstattungslinie','Hebt den dynamischen Charakter hervor mit sportlicheren Stoßfängern, größeren Lufteinlässen, Sportsitzen im Innenraum und spezifischen Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (717,'audi-q2-ga','S line','Ausstattungslinie','Umfasst ein sportliches Exterieur-Paket mit S line spezifischen Stoßfängern, Kühlergrill, Diffusor, S line Schriftzügen und oft größeren Felgen. Innenraum mit Sportsitzen, S line Lenkrad und Dekoreinlagen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (718,'audi-q2-ga','SQ2','Echtes M-Modell','Eigenständiges, sehr sportliches Design mit spezifischen Stoßfängern, vier Endrohren, tiefergelegtem Fahrwerk, größeren Bremsen und SQ2-spezifischen Felgen. Innenraum mit Sportsitzen und SQ2-Logos.','Deutlich leistungsstärkerer Motor, sportlicheres Fahrwerk und Bremsanlage im Vergleich zu den zivilen Q2-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (719,'audi-q3-i','Basis','Basis','Standard-Stoßfänger, kleinere Räder (z.B. 16 oder 17 Zoll), keine Chromapplikationen oder Sport-Design-Elemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (720,'audi-q3-i','Ambition','Ausstattungslinie','Sportlichere Akzente, z.B. größere Leichtmetallräder, Sportsitze, Aluminium-Dekorelemente im Innenraum.','Fokus auf Sportlichkeit und Dynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (721,'audi-q3-i','Ambiente','Ausstattungslinie','Komfortorientierte Ausstattung, z.B. größere Leichtmetallräder, Komfortsitze, Chromapplikationen außen, Holz- oder Aluminium-Dekorelemente im Innenraum.','Fokus auf Komfort und Eleganz.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (722,'audi-q3-i','S line','Ausstattungslinie','Umfasst S line Exterieurpaket (spezifische Stoßfänger, Diffusor, S line Schriftzüge), S line Sportpaket (Sportfahrwerk, Sportsitze, S line Lenkrad, schwarzer Dachhimmel).','Deutlich sportlichere Optik und Fahrdynamik, oft in Kombination mit Ambition.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (723,'audi-q3-ii','Standard','Basis','Serienmäßige 17-Zoll-Leichtmetallräder, Stoff-Sitzbezüge, manuell verstellbare Sitze, Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (724,'audi-q3-ii','Advanced','Ausstattungslinie','18-Zoll-Leichtmetallräder, spezifische Stoßfänger- und Lufteinlass-Designs, LED-Scheinwerfer, Parkassistent.','Erweitert die Serienausstattung um optische und funktionale Elemente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (725,'audi-q3-ii','S line','Ausstattungslinie','19-Zoll-Leichtmetallräder, S line Exterieurpaket (sportlichere Stoßfänger, Diffusor-Einsatz), S line Interieurpaket (Sportsitze mit Leder/Stoff-Kombination, Sportlederlenkrad, Dekoreinlagen).','Betont den sportlichen Charakter mit spezifischen Design-Elementen innen und außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (726,'audi-q3-ii','Black line','Ausstattungslinie','Schwarz-Paket (schwarze Anbauteile, Kühlergrillrahmen, Fensterzierleisten), 19- oder 20-Zoll-Leichtmetallräder in Schwarz.','Fokussiert auf eine dunkle, aggressive Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (727,'audi-q3-ii','RS Q3','M Performance','Breitere Karosserie, RS-spezifischer Wabengrill, größere Lufteinlässe, RS-Stoßfänger, 20-Zoll-Räder, RS-Sportabgasanlage, RS-Sportsitze.','Deutlich sportlicher und leistungsstärker als die regulären Q3-Modelle, mit eigenständigem Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (728,'audi-q5-i','Basis','Basis','Standard-Stoßfänger, 17-Zoll-Leichtmetallräder, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (729,'audi-q5-i','Sport','Ausstattungslinie','Sportfahrwerk, 18-Zoll-Leichtmetallräder, Sportsitze, Aluminium-Dekoreinlagen.','Deutlich sportlichere Optik und Haptik im Innenraum und Exterieur.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (730,'audi-q5-i','Design','Ausstattungslinie','Chrom-Paket, Lederausstattung, erweiterte Dekoreinlagen.','Fokus auf Eleganz und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (731,'audi-q5-i','S line','M Performance','S line Exterieurpaket (spezifische Stoßfänger, Schweller), S line Interieurpaket (Sportsitze mit S line Prägung, Sportlederlenkrad), 19-Zoll-Leichtmetallräder.','Deutlich sportlicher als ''Sport'' und ''Design'', aber kein vollwertiges M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (732,'audi-q5-ii','Basis','Basis','Standard-Stoßfänger, kleinere Räder, schwarze Kunststoffbeplankung an den Radläufen und Schwellern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (733,'audi-q5-ii','advanced','Ausstattungslinie','Sportlichere Stoßfänger, verchromte Elemente am Kühlergrill und den Lufteinlässen, größere Räder, Kontrastlackierung der Anbauteile (z.B. in Manhattangrau).','Positioniert über der Basislinie, mit sportlich-eleganten Akzenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (734,'audi-q5-ii','S line','Ausstattungslinie','Noch sportlichere Stoßfänger mit größeren Lufteinlässen, S line spezifischer Kühlergrill, S line Embleme, Sportfahrwerk, größere Räder, oft in Wagenfarbe lackierte Anbauteile.','Betont die sportliche Seite des Q5, mit dynamischerem Exterieur und Interieur (Sportsitze, S line Lenkrad).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (735,'audi-q5-ii','SQ5','Echtes M-Modell','Eigenständiger Singleframe-Kühlergrill mit Doppelstreben, spezifische Stoßfänger vorne und hinten, vier Endrohre (oft trapezförmig), größere Bremsanlage mit S-Logo, 20-Zoll-Räder serienmäßig, Aluminium-Außenspiegelgehäuse.','Das Topmodell der Baureihe mit eigenständigem, leistungsstarkem Motor und sportlichster Abstimmung von Fahrwerk und Bremsen. Deutlich aggressiveres Erscheinungsbild.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (736,'audi-q7-typ-4l','Basis','Basis','Umfasst die Standardausstattung ohne spezifische Designpakete. Oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (737,'audi-q7-typ-4l','S line Exterieurpaket','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, S line Schriftzüge an den vorderen Kotflügeln, verchromte Endrohrblenden, spezielle Leichtmetallräder.','Fokus auf sportliche Optik außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (738,'audi-q7-typ-4l','S line Sportpaket','Ausstattungslinie','Zusätzlich zum Exterieurpaket: Sportsitze, S line Sportlenkrad, schwarzer Dachhimmel, S line Einstiegsleisten, Sportfahrwerk.','Kombiniert sportliche Optik mit sportlicher Innenausstattung und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (739,'audi-q7-typ-4m','Q7','Basis','Serienausstattung, oft mit 18-Zoll-Leichtmetallrädern, Xenon-Scheinwerfern (vor Facelift) oder LED-Scheinwerfern (nach Facelift), Aluminium-Dachreling.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (740,'audi-q7-typ-4m','design','Ausstattungslinie','Betont Eleganz und Komfort. Oft mit spezifischen Leichtmetallrädern, Chrom-Applikationen an Exterieur und Interieur, Komfortsitzen und erweiterten Interieur-Paketen.','Umfangreichere Komfort- und Designmerkmale im Vergleich zur Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (741,'audi-q7-typ-4m','sport','Ausstattungslinie','Betont Sportlichkeit. Oft mit größeren Leichtmetallrädern, sportlicherem Stoßfängerdesign, Sportsitzen, Sportfahrwerk (optional) und spezifischen Interieur-Applikationen.','Sportlichere Optik und Fahrdynamik-Optionen im Vergleich zur Basis und design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (742,'audi-q7-typ-4m','S line','Ausstattungslinie','Umfasst ein S line Exterieurpaket mit spezifischen Stoßfängern, Seitenschwellern, S line Schriftzügen, größeren Rädern und oft einem S line Sportfahrwerk. Im Interieur Sportsitze, S line Lenkrad und Dekoreinlagen.','Deutlich sportlichere Optik und Haptik als die anderen Ausstattungslinien, aber kein echtes S-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (743,'audi-q8-i','Basis','Basis','Serienmäßige Ausstattung ohne spezifische Sport- oder Designpakete. Oft mit kleineren Felgen und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (744,'audi-q8-i','S line','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, S line Embleme, spezifische Leichtmetallräder, Sportfahrwerk (optional), Sportsitze im Innenraum.','Betont die sportliche Seite des Q8 mit dynamischeren Designelementen und Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (745,'audi-q8-i','Black Edition','Ausstattungslinie','Umfasst das Optikpaket schwarz, schwarze Außenspiegelgehäuse, schwarze Dachreling (falls vorhanden), abgedunkelte Scheiben hinten und spezifische schwarze Leichtmetallräder.','Fokus auf eine dunkle, exklusive Optik durch den Einsatz von schwarzen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (746,'audi-q8-i','SQ8','M Performance','Eigenständige Front- und Heckschürzen, vierflutige Abgasanlage, größere Bremsanlage, spezifische SQ8-Embleme, sportlichere Felgen, Aluminium-Optik an Spiegeln und Lufteinlässen.','Deutlich leistungsstärker als die zivilen Modelle, mit sportlicherem Fahrwerk und spezifischen Designmerkmalen, die die höhere Performance unterstreichen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (747,'audi-q8-i','RS Q8','Echtes M-Modell','Noch aggressivere Frontschürze mit größeren Lufteinlässen, RS-spezifischer Singleframe-Grill, breitere Radhäuser, ovale RS-Abgasendrohre, RS-Bremsanlage (optional Keramikbremse), RS-Embleme, spezifische RS-Felgen, RS-Sportsitze und -Lenkrad im Innenraum.','Das Topmodell der Baureihe mit maximaler Performance, extrem sportlicher Abstimmung und exklusiven RS-Designelementen, die es klar von allen anderen Q8-Modellen abgrenzen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (748,'audi-tt-typ-8n','Basis','Basis','Standard-Felgen, Stoff-Sitze, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (749,'audi-tt-typ-8n','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, oft größere Felgen, Leder/Alcantara-Kombination.','Deutlich sportlichere Abstimmung und Optik im Innenraum.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (750,'audi-tt-typ-8n','Quattro Sport','M Performance','Leichtgewichtige Felgen, Schalensitze, oft ohne Rückbank, stärkere Bremsen, dezente Spoilerlippe.','Fokussiert auf Performance und Gewichtsreduktion, exklusiver als die Sport-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (751,'audi-tt-typ-8j','Standard','Basis','Serienmäßige 17-Zoll-Leichtmetallräder, Stoff-Sportsitze, Klimaanlage, elektr. Fensterheber.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (752,'audi-tt-typ-8j','S line','Ausstattungslinie','S line Sportfahrwerk, S line Schriftzüge, spezifische S line Stoßfänger und Schweller, 18-Zoll-Leichtmetallräder, Sportsitze mit Leder/Stoff-Kombination.','Umfangreicheres Sportpaket, optisch aggressiver als die Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (753,'audi-tt-typ-8j','TTS','M Performance','Spezifische Front- und Heckschürze, vierflutige Abgasanlage, TTS-Schriftzüge, 18- oder 19-Zoll-Leichtmetallräder, Sportsitze mit Leder/Alcantara.','Leistungsgesteigerte Version mit sportlicherer Optik und Fahrwerk, aber kein vollwertiges M-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (754,'audi-tt-typ-8j','TT RS','Echtes M-Modell','Aggressivere Frontschürze, großer Heckflügel, ovaler Endrohr-Doppelauspuff, RS-Schriftzüge, 19-Zoll-Leichtmetallräder, RS-Sportsitze.','Topmodell mit höchster Leistung und sportlichster Auslegung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (755,'audi-tt-typ-fv','Basis','Basis','Serienmäßige Ausstattung, oft mit kleineren Felgen und weniger sportlichen Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (756,'audi-tt-typ-fv','sport','Ausstattungslinie','Sportlichere Sitze, spezifische Felgen, sportlich abgestimmtes Fahrwerk (optional).','Bietet eine sportlichere Optik und Haptik als die Basislinie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (757,'audi-tt-typ-fv','design','Ausstattungslinie','Betont Eleganz und Komfort, oft mit spezifischen Interieur-Materialien und Felgendesigns.','Fokus auf Design und Komfort im Gegensatz zur Sportlichkeit der ''sport''-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (758,'audi-tt-typ-fv','S line','Ausstattungslinie','Umfasst S line Exterieur-Paket (spezifische Stoßfänger, Schweller, S line Schriftzüge), S line Sportfahrwerk, größere Felgen, Sportsitze im Innenraum.','Deutlich sportlichere Optik und Fahrwerksabstimmung, angelehnt an die S-Modelle, aber ohne deren Motorisierung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (759,'audi-tt-typ-fv','TTS','M Performance','Eigenständige Front- und Heckschürzen, vier ovale Endrohre, spezifische 18-Zoll-Felgen (optional größer), Aluminium-Optik-Spiegelkappen, TTS-Schriftzüge.','Leistungsgesteigerte Variante mit sportlicherer Abstimmung und eigenständigen Designelementen, unterhalb des echten M-Modells (TT RS).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (760,'audi-tt-typ-fv','TT RS','Echtes M-Modell','Aggressivere Frontschürze mit großen Lufteinlässen, fester Heckflügel (optional), zwei große ovale Endrohre, RS-spezifische Felgen, RS-Schriftzüge, Matrix-OLED-Rückleuchten (Facelift), RS-Sportsitze.','Das Topmodell der Baureihe mit dem stärksten Motor (5-Zylinder), eigenständigem Fahrwerk und maximaler Performance-Ausrichtung. Deutlich von den anderen Modellen abgrenzbar durch Optik und Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (761,'audi-rs-2-avant-b4','RS 2 Avant','Echtes M-Modell','Porsche-Außenspiegel, Porsche-Bremsanlage mit roten Sätteln, 17-Zoll-Leichtmetallräder im Porsche-Design, spezifische Front- und Heckstoßfänger, durchgehendes rotes Heckleuchtenband, RS 2-Embleme',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (762,'audi-rs-4-avant-b5','RS 4 Avant','Echtes M-Modell','Exklusive Front- und Heckschürzen, verbreiterte Kotflügel, spezifische 18-Zoll-Leichtmetallräder, RS-spezifischer Wabengrill, ovale Auspuffendrohre.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (763,'audi-rs-6-c5','RS 6','Echtes M-Modell','Verbreiterte Kotflügel, RS-spezifische Front- und Heckschürzen, ovale Doppelendrohre, Aluminium-Außenspiegelgehäuse, RS-Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (764,'audi-rs-6-c5','RS 6 plus','Echtes M-Modell','Zusätzlich zur RS 6 Ausstattung: Schwarze Optikpakete (Kühlergrill, Dachreling), RS 6 plus Schriftzüge, spezielle 19-Zoll-Leichtmetallräder.','Leistungsgesteigerte Version des RS 6 mit höherer Endgeschwindigkeit und exklusiven Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (765,'audi-rs-4-b7','RS 4','Echtes M-Modell','Breitere Radhäuser, spezifische Front- und Heckschürzen, Singleframe-Kühlergrill mit Wabenstruktur, Aluminium-Außenspiegelgehäuse, zwei ovale Endrohre, 19-Zoll-Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (766,'audi-rs-6-c6','RS 6','Echtes M-Modell','Serienmäßig mit spezifischen RS-Stoßfängern, verbreiterten Kotflügeln, RS-Kühlergrill mit Wabenstruktur, ovalen Endrohren, 19-Zoll-Leichtmetallrädern (optional 20 Zoll), LED-Tagfahrlicht und RS-Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (767,'audi-tt-rs-8j','TT RS','Echtes M-Modell','Aggressive Front- und Heckschürzen, Wabengrill mit TT RS-Logo, ovale Endrohre, spezifische Leichtmetallräder, fester Heckspoiler (optional) oder ausfahrbarer Heckspoiler.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (768,'audi-tt-rs-8j','TT RS plus','Echtes M-Modell','Zusätzlich zum TT RS: Schwarze Außenspiegelgehäuse, schwarzer Kühlergrillrahmen, spezielle 19-Zoll-Räder im 5-Arm-Rotor-Design, rote Bremssättel (optional).','Leistungsgesteigerte Version des TT RS.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (769,'audi-rs-5-8t','RS 5','M Performance','Breitere Kotflügel, spezifische RS-Stoßfänger vorne und hinten, RS-Schriftzüge, ovalen Auspuffendrohre, 19- oder 20-Zoll-Räder, Sportsitze.','Deutlich sportlicher und aggressiver im Design als die S5-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (770,'audi-rs-3-sportback-8p','RS 3 Sportback','Echtes M-Modell','Spezifische RS-Front- und Heckschürzen, verbreiterte Kotflügel, Wabenkühlergrill mit ''quattro''-Schriftzug, Dachkantenspoiler, zwei ovale Endrohre, RS-spezifische Leichtmetallräder, Aluminium-Optik an Spiegelkappen und Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (771,'audi-rs-4-avant-b8','RS 4 Avant','Echtes M-Modell','RS-spezifischer Singleframe-Kühlergrill mit Wabenstruktur, verbreiterte Kotflügel, RS-Stoßfänger vorne und hinten, ovale Endrohre, Dachkantenspoiler, 19-Zoll-Leichtmetallräder (optional 20 Zoll), RS-Sportsitze, RS-Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (772,'audi-rs-q3-8u','RS Q3','Echtes M-Modell','RS-spezifischer Singleframe-Kühlergrill mit Wabenstruktur, RS-Stoßfänger vorne und hinten, verbreiterte Radläufe, Dachkantenspoiler, ovales Endrohr, RS-Sportfahrwerk, 19-Zoll-Leichtmetallräder (optional 20 Zoll), Sportsitze mit RS-Prägung, RS-Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (773,'audi-rs-q3-8u','RS Q3 performance','M Performance','Exklusive Lackierungen (z.B. Ascariblau Metallic), matt-titanfarbene Designelemente (z.B. Kühlergrillrahmen, Lufteinlässe, Dachreling, Außenspiegelgehäuse), 20-Zoll-Leichtmetallräder im 5-Doppelspeichen-Design, RS-Sportsitze in Leder-Alcantara mit blauen Kontrastnähten, Carbon-Applikationen im Innenraum.','Leistungsgesteigerte Motorvariante (367 PS statt 340 PS), exklusive Designmerkmale und Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (774,'audi-rs-6-avant-c7','RS 6 Avant','Echtes M-Modell','Spezifische RS-Front- und Heckschürzen, verbreiterte Radhäuser, RS-Kühlergrill mit Wabenstruktur, ovale Endrohre, RS-Sportfahrwerk, große Bremsanlage, RS-spezifische Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (775,'audi-rs-6-avant-c7','RS 6 Avant performance','Echtes M-Modell','Zusätzlich zur RS 6 Ausstattung: Spezifische 21-Zoll-Leichtmetallräder, matt-titanfarbene oder glanzgedrehte Optikpakete, RS-Sportsitze mit Kontrastnähten und RS-Prägung, teilweise Carbon-Applikationen im Interieur.','Leistungsgesteigerte Motorisierung (4.0 TFSI mit 605 PS statt 560 PS), höhere Höchstgeschwindigkeit (optional bis 305 km/h).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (776,'audi-rs-7-sportback-c7','RS 7 Sportback','Echtes M-Modell','Serienmäßig mit RS-spezifischer Front- und Heckschürze, Wabenkühlergrill, breiteren Radhäusern, ovalen Endrohren, RS-Sportfahrwerk, 20-Zoll-Leichtmetallrädern, RS-Sportsitzen und RS-spezifischen Interieur-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (777,'audi-rs-7-sportback-c7','RS 7 Sportback performance','Echtes M-Modell','Zusätzlich zum RS 7 Sportback: Leistungssteigerung, spezifische 21-Zoll-Leichtmetallräder, optionales RS-Sportfahrwerk plus mit Dynamic Ride Control (DRC), spezielle Designelemente wie matt-titanfarbene Akzente an Front und Heck, optionales Optikpaket Carbon.','Die ''performance''-Variante bietet eine höhere Motorleistung und oft eine noch sportlichere Abstimmung von Fahrwerk und Getriebe, sowie exklusive Designmerkmale und Felgen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (778,'audi-rs-3-sportback-8v','RS 3 Sportback','Echtes M-Modell','Exklusive RS-Designelemente wie breitere Radhäuser, RS-spezifische Stoßfänger vorne und hinten, Singleframe-Kühlergrill mit Wabenstruktur und quattro-Schriftzug, ovale RS-Abgasendrohre, Dachkantenspoiler, 19-Zoll-Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (779,'audi-tt-rs-fv/8s','TT RS','Echtes M-Modell','Serienmäßig mit spezifischem RS-Design, feststehendem Heckflügel (optional entfallbar), RS-Sportabgasanlage, 19-Zoll-Leichtmetallrädern, RS-Sportsitzen und RS-spezifischen Anzeigen im Virtual Cockpit.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (780,'audi-tt-rs-fv/8s','TT RS Iconic Edition','Ausstattungslinie','Sondermodell (2022) limitiert auf 100 Exemplare. Exklusive Nardograu-Lackierung, Matrix-LED-Scheinwerfer, 20-Zoll-Leichtmetallräder in Schwarz, Aerokit mit Front-Sideblades, Frontsplitter, Flics, Seitenschwellern und feststehendem Carbon-Heckflügel. Innen mit RS-Sportsitzen in Leder-Alcantara mit Wabensteppung und gelben Kontrastnähten, nummerierter Plakette.','Exklusives Sondermodell mit umfangreicherer Serienausstattung und spezifischen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (781,'audi-rs-5-b9','RS 5','M Performance','Serienmäßig mit RS-spezifischer Optik, darunter breitere Kotflügel, markanterer Kühlergrill, RS-Schriftzüge, ovale Auspuffendrohre, spezifische Felgen und RS-Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (782,'audi-rs-4-avant-b9','RS 4 Avant','Echtes M-Modell','RS-spezifische Front- und Heckschürzen, breitere Radhäuser, RS-Sportfahrwerk, RS-Abgasanlage mit ovalen Endrohren, 19-Zoll-Leichtmetallräder (optional 20 Zoll), RS-Sportsitze, RS-Sportlenkrad, spezifische RS-Dekorelemente im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (783,'audi-rs-q8-4m','RS Q8','Echtes M-Modell','RS-spezifischer Singleframe-Kühlergrill in Wabenstruktur, RS-Stoßfänger vorne und hinten, verbreiterte Radläufe, ovale RS-Abgasendrohre, 22-Zoll-Leichtmetallräder (optional bis 23 Zoll), RS-Sportsitze, RS-Sportfahrwerk adaptive air suspension.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (784,'audi-rs-6-avant-c8','RS 6 Avant','Echtes M-Modell','Serienmäßig mit RS-spezifischem Exterieur (breite Radhäuser, RS-Stoßfänger, ovalen Endrohren, Wabenkühlergrill), 21-Zoll-Leichtmetallrädern, RS-Sportsitzen und RS-Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (785,'audi-rs-6-avant-c8','RS 6 Avant performance','Echtes M-Modell','Zusätzlich zur RS 6 Avant Ausstattung: Leistungssteigerung, optimiertes RS-Sportfahrwerk plus mit Dynamic Ride Control (DRC), RS-Keramikbremsanlage optional, 22-Zoll-Leichtmetallräder im 5-Y-Speichen-Design, mattgraue Exterieur-Details (Spiegelkappen, Frontspoiler, Diffusor), RS-Einstiegsleisten mit Projektion.','Leistungsgesteigerte Variante mit Fokus auf noch mehr Fahrdynamik und exklusiven Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (786,'audi-rs-7-sportback-c8','RS 7 Sportback','Echtes M-Modell','RS-spezifische Front- und Heckschürze, verbreiterte Radhäuser, ovale Doppelendrohre, RS-Sportfahrwerk, große Bremsanlage, spezifische Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (787,'audi-rs-7-sportback-c8','RS 7 Sportback performance','Echtes M-Modell','Leichtere 22-Zoll-Räder, mattgraue oder mattcarbonfarbene Exterieur-Details, RS-Sportsitze mit blauen Kontrastnähten, erweiterte Serienausstattung.','Leistungssteigerung und Gewichtsreduktion gegenüber dem Standard RS 7.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (788,'audi-rs-q3-f3','RS Q3','Echtes M-Modell','RS-spezifischer Singleframe-Grill mit Wabenstruktur, RS-Stoßfänger vorne und hinten, breite Radhäuser, RS-Abgasanlage mit ovalen Endrohren, 20-Zoll-Leichtmetallräder (optional 21 Zoll), RS-Sportsitze, RS-Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (789,'audi-rs-q3-f3','RS Q3 Sportback','Echtes M-Modell','Wie RS Q3, jedoch mit coupéartiger Dachlinie, flacherer Heckscheibe und spezifischem Heckdesign.','Unterscheidet sich vom RS Q3 durch die Karosserieform (Coupé-SUV).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (790,'audi-rs-3-8y','RS 3','Echtes M-Modell','RS-spezifischer Singleframe-Kühlergrill mit Wabengitter, breite Radhäuser, RS-Stoßfänger vorne und hinten, zwei große ovale Endrohre, RS-Sportfahrwerk, 19-Zoll-Leichtmetallräder, RS-Sportsitze, RS-Sportlenkrad, RS-spezifische Anzeigen im Virtual Cockpit.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (791,'audi-rs-3-8y','RS 3 performance edition','Ausstattungslinie','Zusätzlich zur RS 3 Ausstattung: Spezielle 19-Zoll-Schmiederäder, RS-Schalensitze mit Mikrofaserbezug, schwarze Optikpakete, abgedunkelte Matrix-LED-Scheinwerfer, RS-Sportabgasanlage mit schwarzen Endrohren, spezifische Designelemente im Innenraum.','Limitiert auf 300 Exemplare. Höhere Leistung (407 PS), RS-Keramikbremsanlage vorne, adaptives Fahrwerk mit RS-spezifischer Abstimmung, erhöhte Höchstgeschwindigkeit (290 km/h).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (792,'audi-rs-e-tron-gt-typ-ge','RS e-tron GT','Echtes M-Modell','Sportlichere Front- und Heckschürzen, spezifische RS-Designelemente, größere Bremsanlage (optional Keramikbremsen), RS-spezifische Felgen, RS-Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (793,'audi-rs-e-tron-gt-typ-ge','RS e-tron GT performance','Echtes M-Modell','Nochmals geschärfte Optik gegenüber dem RS e-tron GT, oft mit spezifischen Design-Paketen, exklusiven Felgen und weiteren Performance-Akzenten. Deutlich höhere Leistung.','Abgrenzung zum ''normalen'' RS e-tron GT durch nochmals gesteigerte Leistung, spezifische Fahrwerksabstimmung und oft exklusive Designmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (798,'audi-r8-typ-42','R8 Coupé','Basis','Standard-Karosserieform, Sideblades in Kontrastfarbe oder Wagenfarbe, je nach Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (799,'audi-r8-typ-42','R8 Spyder','Basis','Offene Karosserieform mit Stoffverdeck, keine Sideblades im klassischen Sinne, stattdessen seitliche Lufteinlässe hinter den Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (800,'audi-r8-typ-42','R8 GT','Ausstattungslinie','Limitierte Sonderedition (333 Coupés, 333 Spyder) mit feststehendem Carbon-Heckflügel, Carbon-Frontsplitter, Carbon-Außenspiegeln, roten Bremssätteln und spezifischen Leichtmetallrädern. Deutlich aggressivere Optik.','Leistungsgesteigert (560 PS), gewichtsreduziert, sportlichere Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (801,'audi-r8-typ-42','R8 V10 plus (ab Facelift)','Ausstattungslinie','Carbon-Elemente an Frontsplitter, Außenspiegeln, Sideblades und Diffusor. Spezifische 19-Zoll-Räder, rote Bremssättel. Optionaler fester Heckflügel.','Leistungsgesteigerter V10-Motor (550 PS), serienmäßig mit S tronic Getriebe, Carbon-Keramik-Bremsen und Sportfahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (802,'audi-e-tron-2019','e-tron','Basis','Serienmäßige Ausstattung, oft mit 19-Zoll-Rädern und Standard-LED-Scheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (803,'audi-e-tron-2019','advanced','Ausstattungslinie','Betonung von Robustheit und Offroad-Look, oft mit spezifischen Stoßfängern und Radlaufblenden in Kontrastfarbe.','Umfasst zusätzliche Komfort- und Designelemente gegenüber der Basis.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (804,'audi-e-tron-2019','S line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, S line Schriftzügen, größeren Rädern und oft Sportfahrwerk.','Fokus auf sportliches Design und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (805,'audi-e-tron-2019','e-tron S','Echtes M-Modell','Breitere Radläufe, drei Elektromotoren (zwei an der Hinterachse), spezifische S-Designelemente an Front und Heck, größere Bremsanlage.','Das Performance-Modell der Baureihe mit deutlich mehr Leistung und sportlicherer Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (806,'audi-q8-e-tron-2023','Q8 e-tron','Basis','Serienausstattung mit 19-Zoll-Leichtmetallrädern, LED-Scheinwerfern, MMI Navigation plus mit MMI touch response.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (807,'audi-q8-e-tron-2023','advanced','Ausstattungslinie','Betont den robusten SUV-Charakter mit spezifischen Anbauteilen in Kontrastfarbe, 20-Zoll-Leichtmetallrädern und Aluminium-Dachreling.','Umfasst zusätzliche Designelemente und Komfortausstattungen gegenüber der Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (808,'audi-q8-e-tron-2023','S line','Ausstattungslinie','Sportlichere Optik mit S line Stoßfängern, 20-Zoll-Leichtmetallrädern im S-Design, S line Schriftzügen, Sportsitzen und spezifischen Interieur-Applikationen.','Fokus auf sportliches Design und Fahrerlebnis, oft mit Sportfahrwerk kombiniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (809,'audi-q8-e-tron-2023','SQ8 e-tron','Echtes M-Modell','Eigenständiges, noch aggressiveres Design mit breiteren Radläufen, spezifischen Stoßfängern, 20-Zoll-Rädern (optional bis 22 Zoll), vier Endrohrblenden (optisch) und SQ8-spezifischen Emblemen. Verfügt über drei Elektromotoren.','Das Topmodell mit deutlich höherer Leistung, sportlicherem Fahrwerk und exklusiven Designmerkmalen, die es klar von den anderen Varianten abgrenzen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (810,'audi-q4-e-tron-2021','Basis','Basis','Serienmäßige Ausstattung, oft mit kleineren Rädern und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (811,'audi-q4-e-tron-2021','advanced','Ausstattungslinie','Betont den Offroad-Charakter mit spezifischen Stoßfängern, Kontrastlackierung und größeren Rädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (812,'audi-q4-e-tron-2021','S line','Ausstattungslinie','Sportlichere Optik mit S line Stoßfängern, spezifischem Kühlergrill, Sportfahrwerk (optional) und S line Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (813,'audi-e-tron-gt-typ-4j','e-tron GT quattro','Basis','Serienmäßige Ausstattung mit 20-Zoll-Rädern, LED-Scheinwerfern und Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (814,'audi-e-tron-gt-typ-4j','RS e-tron GT','Echtes M-Modell','Aggressiveres Design mit spezifischen Stoßfängern, größeren Lufteinlässen, RS-spezifischen 20- oder 21-Zoll-Rädern und optionalen Keramikbremsen mit roten Sätteln. RS-Logos an Front, Heck und im Interieur.','Leistungsstärkere Motoren, sportlichere Fahrwerksabstimmung, erweiterte Serienausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (815,'audi-e-tron-gt-typ-4j','RS e-tron GT performance','Echtes M-Modell','Nochmals geschärftes Design mit spezifischen Aerodynamik-Elementen, exklusiven Lackierungen und optionalen Leichtbau-Komponenten. RS-Logos und Performance-Embleme.','Die leistungsstärkste Variante mit maximaler Performance und exklusiven Ausstattungsdetails.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (816,'volkswagen-up-up','take up!','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (anfangs), einfachste Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (817,'volkswagen-up-up','move up!','Ausstattungslinie','Lackierte Außenspiegel und Türgriffe, Radio ''Composition Phone'' (nach Facelift), Klimaanlage optional.','Bietet mehr Komfort als ''take up!'', z.B. elektrische Fensterheber vorne und Zentralverriegelung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (818,'volkswagen-up-up','high up!','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Chromapplikationen, Lederlenkrad, Klimaanlage serienmäßig.','Umfangreichere Ausstattung mit Fokus auf Komfort und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (819,'volkswagen-up-up','up! beats','Ausstattungslinie','Spezielle Designelemente außen (z.B. Streifen), 15-Zoll-Leichtmetallfelgen, BeatsAudio Soundsystem.','Sondermodell mit Fokus auf Sound und jugendliches Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (820,'volkswagen-up-up','up! GTI','Echtes M-Modell','GTI-spezifische Front- und Heckschürze, 17-Zoll-Leichtmetallfelgen, rote Zierleisten, karierte Sportsitze, Sportfahrwerk.','Sportmodell mit leistungsstärkerem Motor (1.0 TSI mit 115 PS) und sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (821,'volkswagen-up-up','e-up!','Ausstattungslinie','Blaue Zierleisten an Front und Heck, spezifische Leichtmetallfelgen, Ladeanschluss hinter dem VW-Logo.','Die rein elektrische Variante des Up! mit eigenständigem Antrieb und spezifischen Designakzenten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (822,'volkswagen-up-up','cross up!','Ausstattungslinie','Offroad-Optik mit schwarzen Radlaufverbreiterungen, Seitenschwellern und Stoßfängern, erhöhte Bodenfreiheit, Dachreling.','Variante mit robusterer Optik und leicht erhöhter Bodenfreiheit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (823,'volkswagen-up-up-(facelift)','take up!','Basis','Einfache Ausstattung, Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (824,'volkswagen-up-up-(facelift)','move up!','Ausstattungslinie','Zusätzlich zur take up! Ausstattung: Klimaanlage, Radio ''Composition Phone'', elektrische Fensterheber vorne, Zentralverriegelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (825,'volkswagen-up-up-(facelift)','high up!','Ausstattungslinie','Zusätzlich zur move up! Ausstattung: Leichtmetallräder, Nebelscheinwerfer, Sitzheizung vorne, Lederlenkrad, Ambientebeleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (826,'volkswagen-up-up-(facelift)','up! beats','Ausstattungslinie','Spezielle Designelemente innen und außen, 300-Watt-Soundsystem von BeatsAudio, 15-Zoll-Leichtmetallräder, spezielle Folierungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (827,'volkswagen-up-up-(facelift)','up! GTI','Ausstattungslinie','Sportliche Optik mit roten Zierstreifen, speziellen Stoßfängern, 17-Zoll-Leichtmetallrädern, Dachkantenspoiler, Sportsitzen mit Karomuster, Sportfahrwerk.','Sportmodell mit leistungsstärkerem Motor und strafferem Fahrwerk, angelehnt an die GTI-Tradition.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (828,'volkswagen-up-up-(facelift)','e-up!','Ausstattungslinie','Blaue Zierelemente, spezifische Leichtmetallräder, Ladeanschluss hinter dem VW-Logo.','Rein elektrisch angetriebene Variante.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (829,'volkswagen-polo-i','Polo','Basis','Einfache Ausstattung, oft ohne viel Chromzierrat.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (830,'volkswagen-polo-i','Polo L','Ausstattungslinie','Leicht verbesserte Ausstattung gegenüber der Basisversion, oft mit zusätzlichen Chromleisten oder Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (831,'volkswagen-polo-i','Polo GL','Ausstattungslinie','Gehobene Ausstattung, oft mit Veloursitzen, Radio und weiteren Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (832,'volkswagen-polo-i','Polo GT','Ausstattungslinie','Sportlichere Ausstattung, oft mit speziellen Felgen, Sportlenkrad und stärkeren Motoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (833,'volkswagen-polo-ii','Standard','Basis','Einfache Stoßfänger, Stahlfelgen, weniger Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (834,'volkswagen-polo-ii','CL','Ausstattungslinie','Etwas bessere Innenausstattung, eventuell mit Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (835,'volkswagen-polo-ii','GL','Ausstattungslinie','Umfangreichere Ausstattung, oft mit besserer Polsterung, eventuell mit Drehzahlmesser.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (836,'volkswagen-polo-ii','GT','Ausstattungslinie','Sportlichere Optik, oft mit anderen Felgen, Schalensitzen und sportlichem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (837,'volkswagen-polo-ii','G40','M Performance','Breitere Kotflügel, spezielle Felgen, sportliche Anbauteile, oft mit roten Akzenten.','Deutlich sportlicher und leistungsstärker als andere Linien, erkennbar an den breiteren Karosserieteilen und dem G-Lader.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (838,'volkswagen-polo-iii','Basis','Basis','Einfache Stahlfelgen, unlackierte Stoßfänger (anfangs), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (839,'volkswagen-polo-iii','CL','Ausstattungslinie','Leicht verbesserte Innenraummaterialien, oft Radkappen, teilweise lackierte Stoßfänger.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (840,'volkswagen-polo-iii','GL','Ausstattungslinie','Umfangreichere Ausstattung, oft lackierte Stoßfänger, elektrische Fensterheber (optional), bessere Sitzbezüge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (841,'volkswagen-polo-iii','GT','Ausstattungslinie','Sportlichere Akzente, oft Leichtmetallfelgen, Sportsitze, Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (842,'volkswagen-polo-iii','Highline','Ausstattungslinie','Top-Ausstattungslinie, oft Leichtmetallfelgen, Klimaanlage (optional), hochwertige Innenraummaterialien, volle Lackierung der Stoßfänger.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (843,'volkswagen-polo-iii','GTI','Echtes M-Modell','Exklusive Front- und Heckschürzen, Seitenschweller, 15-Zoll-Leichtmetallfelgen, rote Bremssättel, Sportsitze mit speziellem Bezug, rote Ziernähte.','Das GTI-Modell ist die sportliche Speerspitze der Baureihe mit leistungsstärkerem Motor, strafferem Fahrwerk und spezifischen optischen Merkmalen, die es deutlich von den zivileren Modellen abgrenzen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (844,'volkswagen-polo-iv','Basis','Basis','Einfache Stoßfänger, Stahlfelgen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (845,'volkswagen-polo-iv','Trendline','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, teilweise lackierte Stoßfänger.','Höherwertige Materialien im Innenraum, mehr Komfortfunktionen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (846,'volkswagen-polo-iv','Comfortline','Ausstattungslinie','Alufelgen, Klimaanlage, elektrische Fensterheber vorne, bessere Sitzbezüge.','Umfangreichere Komfort- und Technikfeatures.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (847,'volkswagen-polo-iv','Highline','Ausstattungslinie','Größere Alufelgen, Lederlenkrad, Sportsitze, Klimaautomatik.','Top-Ausstattung mit den meisten Extras.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (848,'volkswagen-polo-iv','GTI','M Performance','Sportfahrwerk, spezifische Felgen, rote Bremssättel, Sportsitze, Doppelrohr-Auspuff.','Deutlich sportlichere Optik und Fahrleistungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (849,'volkswagen-polo-v','Trendline','Basis','Stahlräder mit Radkappen, unlackierte Türgriffe und Außenspiegel (anfangs), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (850,'volkswagen-polo-v','Comfortline','Ausstattungslinie','Lackierte Türgriffe und Außenspiegel, oft Leichtmetallräder (optional), hochwertigere Stoffpolsterung, Chromapplikationen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (851,'volkswagen-polo-v','Highline','Ausstattungslinie','Serienmäßige Leichtmetallräder, Sportsitze, Lederlenkrad, Klimaautomatik, Nebelscheinwerfer, Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (852,'volkswagen-polo-v','BlueMotion','Ausstattungslinie','Aerodynamisch optimierte Karosserieteile (z.B. Frontschürze, Heckspoiler), spezielle Leichtmetallräder, BlueMotion-Schriftzüge.','Fokus auf maximale Kraftstoffeffizienz durch spezielle Motorisierungen und Aerodynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (853,'volkswagen-polo-v','GTI','Echtes M-Modell','Sportfahrwerk, 17-Zoll-Leichtmetallräder, rote Bremssättel, Doppelendrohr-Auspuffanlage, GTI-spezifische Front- und Heckschürze, Sportsitze mit Karomuster (Clark-Karo), rote Ziernähte im Innenraum.','Top-Sportmodell mit leistungsstarkem Motor und sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (854,'volkswagen-polo-v','R-Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, R-Line-Logos, spezielle Leichtmetallräder, Sportlenkrad, Sportsitze.','Optisches Sportpaket, das das Aussehen des GTI imitiert, aber nicht dessen Motorisierung oder Fahrwerksabstimmung hat.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (855,'volkswagen-polo-vi','Trendline','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (vor Facelift), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (856,'volkswagen-polo-vi','Comfortline','Ausstattungslinie','Leichtmetallräder (optional), lackierte Türgriffe und Außenspiegel, Chromapplikationen, bessere Sitzbezüge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (857,'volkswagen-polo-vi','Highline','Ausstattungslinie','Umfangreichere Ausstattung, größere Leichtmetallräder, LED-Scheinwerfer (optional), Sportsitze, Klimaautomatik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (858,'volkswagen-polo-vi','Style','Ausstattungslinie','Nach Facelift eingeführt, ersetzt Highline. Bietet u.a. IQ.LIGHT LED-Matrix-Scheinwerfer, 16-Zoll-Leichtmetallräder, Ambientebeleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (859,'volkswagen-polo-vi','Life','Ausstattungslinie','Nach Facelift eingeführt, ersetzt Comfortline. Bietet u.a. 15-Zoll-Leichtmetallräder, Multifunktionslenkrad, Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (860,'volkswagen-polo-vi','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, R-Line-Emblemen, größeren Leichtmetallrädern, Sportfahrwerk (optional).','Fokus auf sportliche Optik, nicht auf Leistungssteigerung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (861,'volkswagen-polo-vi','GTI','Echtes M-Modell','Spezifische GTI-Stoßfänger, Wabenstruktur im Kühlergrill, rote Zierleisten, 17- oder 18-Zoll-Leichtmetallräder, Doppelendrohr-Auspuffanlage, Sportsitze mit Karomuster (Clark-Karo), Sportfahrwerk.','Das Topmodell mit leistungsstärkerem Motor und sportlicher Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (862,'volkswagen-golf-i','Basis','Basis','Einfache Ausstattung, oft mit unlackierten Stoßstangen und Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (863,'volkswagen-golf-i','GL','Ausstattungslinie','Gehobene Ausstattung, oft mit Chromzierleisten, Velourssitzen und besseren Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (864,'volkswagen-golf-i','GTI','Ausstattungslinie','Sportliche Optik mit breiteren Radläufen, Frontspoiler, Heckspoiler, roten Zierstreifen am Kühlergrill und oft Doppelscheinwerfern. Innen Sportsitze und Golfball-Schaltknauf.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (865,'volkswagen-golf-i','Diesel','Ausstattungslinie','Äußerlich oft kaum von den Benzinmodellen zu unterscheiden, manchmal mit ''Diesel''-Schriftzug am Heck.','Unterschied sich primär durch den Dieselmotor und die damit verbundenen technischen Anpassungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (866,'volkswagen-golf-ii','C','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen, keine Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (867,'volkswagen-golf-ii','CL','Ausstattungslinie','Etwas bessere Ausstattung als C, oft mit lackierten Stoßfängern (spätere Modelle), Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (868,'volkswagen-golf-ii','GL','Ausstattungslinie','Komfortorientiert, oft mit Veloursitzen, Drehzahlmesser, Colorverglasung, breiteren Seitenleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (869,'volkswagen-golf-ii','GT','Ausstattungslinie','Sportlicher angehaucht, oft mit Sportsitzen, Drehzahlmesser, breiteren Reifen, Spoilerlippe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (870,'volkswagen-golf-ii','GTI','Echtes M-Modell','Markante rote Zierleisten im Kühlergrill, breitere Radläufe, Sportsitze, Sportlenkrad, oft mit speziellen Leichtmetallfelgen, Doppelendrohr.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (871,'volkswagen-golf-ii','G60','Echtes M-Modell','Ähnlich dem GTI, aber oft mit speziellen Felgen (z.B. BBS RM), Ladeluftkühler-Öffnung in der Frontschürze, G60-Schriftzüge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (872,'volkswagen-golf-ii','Country','Ausstattungslinie','Höhergelegte Karosserie, Allradantrieb (Syncro), Unterfahrschutz, Reserverad am Heck, Bullbar vorne, oft Zweifarblackierung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (873,'volkswagen-golf-iii','CL','Basis','Einfache Ausstattung, oft mit unlackierten Stoßfängern und Außenspiegeln, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (874,'volkswagen-golf-iii','GL','Ausstattungslinie','Umfangreichere Ausstattung als CL, oft mit lackierten Stoßfängern, Velourssitzen, Drehzahlmesser.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (875,'volkswagen-golf-iii','GT','Ausstattungslinie','Sportlichere Optik mit Sportsitzen, oft Leichtmetallfelgen, Nebelscheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (876,'volkswagen-golf-iii','GTI','Ausstattungslinie','Sportmodell mit spezifischen Stoßfängern, Seitenschwellern, roten Zierleisten im Kühlergrill, Sportsitzen, Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (877,'volkswagen-golf-iii','VR6','Ausstattungslinie','Topmodell mit breiteren Kotflügeln, spezifischen Stoßfängern, Doppelscheinwerfern, 15-Zoll-Leichtmetallfelgen, Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (878,'volkswagen-golf-iii','Bon Jovi','Ausstattungslinie','Sondermodell mit speziellen Polsterstoffen, Radio, Leichtmetallfelgen, oft in bestimmten Farben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (879,'volkswagen-golf-iii','Pink Floyd','Ausstattungslinie','Sondermodell mit speziellen Polsterstoffen, Radio, Leichtmetallfelgen, oft in bestimmten Farben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (880,'volkswagen-golf-iii','Rolling Stones','Ausstattungslinie','Sondermodell mit speziellen Polsterstoffen, Radio, Leichtmetallfelgen, oft in bestimmten Farben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (881,'volkswagen-golf-iii','Highline','Ausstattungslinie','Hochwertige Ausstattung mit Lederausstattung (optional), Klimaanlage (optional), Leichtmetallfelgen, oft in Metallic-Lackierungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (882,'volkswagen-golf-iv','Basis','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (anfangs), einfache Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (883,'volkswagen-golf-iv','Trendline','Ausstattungslinie','Leicht verbesserte Ausstattung, oft mit lackierten Stoßfängern und Außenspiegeln, optionalen Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (884,'volkswagen-golf-iv','Comfortline','Ausstattungslinie','Komfortorientiert, oft mit Velours-Sitzbezügen, Klimaanlage, elektrischen Fensterhebern und besseren Audiosystemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (885,'volkswagen-golf-iv','Highline','Ausstattungslinie','Top-Ausstattung mit Sportsitzen, Lederlenkrad, Leichtmetallfelgen, Nebelscheinwerfern und oft Klimaautomatik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (886,'volkswagen-golf-iv','GTI','Ausstattungslinie','Sportliche Akzente wie spezielle Stoßfänger, Sportsitze, Leichtmetallfelgen, rote Ziernähte im Innenraum.','Sportliche Ausrichtung mit stärkeren Motoren (z.B. 1.8T, VR5, VR6, TDI).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (887,'volkswagen-golf-iv','R32','Echtes M-Modell','Aggressivere Front- und Heckschürzen, große Lufteinlässe, 18-Zoll-Leichtmetallfelgen, Doppelendrohre mittig, Recaro-Sportsitze, blaue Bremssättel.','Das Topmodell der Baureihe mit 3.2-Liter VR6-Motor, Allradantrieb (4Motion) und spezifischer Sportabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (888,'volkswagen-golf-v','Trendline','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe und Außenspiegel (anfangs), schwarze Dachreling beim Variant.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (889,'volkswagen-golf-v','Comfortline','Ausstattungslinie','Leichtmetallfelgen (oft 15 Zoll), lackierte Türgriffe und Außenspiegel, Chromzierleisten an den Seitenfenstern (teilweise), Komfortsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (890,'volkswagen-golf-v','Sportline','Ausstattungslinie','Sportfahrwerk, Sportsitze, Leichtmetallfelgen (oft 16 Zoll), Nebelscheinwerfer, dunkle Rückleuchten (teilweise).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (891,'volkswagen-golf-v','Highline','Ausstattungslinie','Umfangreichere Ausstattung, oft größere Leichtmetallfelgen (16 oder 17 Zoll), Chromzierleisten, Klimaautomatik, Multifunktionslenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (892,'volkswagen-golf-v','GT','Ausstattungslinie','Sportliche Optik mit speziellen Stoßfängern, Kühlergrill mit Wabenstruktur, 17-Zoll-Leichtmetallfelgen, Sportfahrwerk, Doppelendrohr (je nach Motorisierung).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (893,'volkswagen-golf-v','GTI','Ausstattungslinie','Markanter Wabenkühlergrill mit roter Umrandung, spezielle Front- und Heckschürzen, 17- oder 18-Zoll-Leichtmetallfelgen (z.B. ''Denver''), Doppelendrohr links, Sportsitze mit ''Interlagos''-Karo-Muster.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (894,'volkswagen-golf-v','R32','Ausstattungslinie','Aggressive Frontschürze mit großen Lufteinlässen, mittig platzierte Doppelendrohre, 18-Zoll-Leichtmetallfelgen (z.B. ''Zolder''), blaue Bremssättel, Bi-Xenon-Scheinwerfer, R32-Schriftzüge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (895,'volkswagen-golf-vi','Trendline','Basis','Stahlräder mit Radkappen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (896,'volkswagen-golf-vi','Comfortline','Ausstattungslinie','Leichtmetallräder (oft 16 Zoll), lackierte Türgriffe und Außenspiegel, Chromzierleisten an den Seitenfenstern, Komfortsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (897,'volkswagen-golf-vi','Highline','Ausstattungslinie','Größere Leichtmetallräder (oft 17 Zoll), Sportsitze mit Alcantara-Bezügen, Klimaautomatik, Nebelscheinwerfer mit Chromeinfassung, Chromzierleisten an Front und Heck.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (898,'volkswagen-golf-vi','GTI','Echtes M-Modell','Sportfahrwerk, spezielle 17- oder 18-Zoll-Leichtmetallräder, rote Zierleiste im Kühlergrill, Sportsitze mit Karomuster, Doppelendrohr-Auspuffanlage, spezifische Front- und Heckschürzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (899,'volkswagen-golf-vi','GTD','M Performance','Ähnliche sportliche Optik wie der GTI, jedoch mit grauer Zierleiste im Kühlergrill, spezifische Leichtmetallräder, Sportsitze, Doppelendrohr-Auspuffanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (900,'volkswagen-golf-vi','R','Echtes M-Modell','Sehr sportliche Front- und Heckschürzen, zentrale Doppelendrohr-Auspuffanlage, 18- oder 19-Zoll-Leichtmetallräder, Bi-Xenon-Scheinwerfer, Sportsitze mit R-Logo, tiefergelegtes Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (901,'volkswagen-golf-vii','Trendline','Basis','Einfachere Stoßfänger, Stahlräder mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (902,'volkswagen-golf-vii','Comfortline','Ausstattungslinie','Leichtmetallräder, Chromzierleisten, bessere Innenraummaterialien.','Umfangreichere Komfortausstattung als Trendline.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (903,'volkswagen-golf-vii','Highline','Ausstattungslinie','Größere Leichtmetallräder, Bi-Xenon-Scheinwerfer (optional), Sportsitze, erweiterte Chrom-Applikationen.','Höchste Komfort- und Designausstattung der zivilen Linien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (904,'volkswagen-golf-vii','GTI','M Performance','Rot umrandeter Kühlergrill mit Wabenstruktur, spezifische GTI-Felgen, rote Bremssättel, Doppelrohr-Auspuffanlage, Sportsitze mit Karomuster.','Sportliche Top-Version mit leistungsgesteigertem Motor und sportlichem Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (905,'volkswagen-golf-vii','R','Echtes M-Modell','Aggressivere Frontschürze, vier Endrohre der Abgasanlage, spezifische R-Felgen, blaue Bremssättel, Sportsitze mit Leder.','Das Spitzenmodell der Golf VII Baureihe mit Allradantrieb und höchster Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (906,'volkswagen-golf-viii','Golf','Basis','Grundausstattung mit 16-Zoll-Stahlrädern, LED-Scheinwerfern und -Rückleuchten, Digital Cockpit.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (907,'volkswagen-golf-viii','Life','Ausstattungslinie','Zusätzlich u.a. 16-Zoll-Leichtmetallräder, Komfortsitze, Klimaautomatik, Ambientebeleuchtung.','Erweitert die Basisausstattung um Komfort- und Designmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (908,'volkswagen-golf-viii','Style','Ausstattungslinie','Zusätzlich u.a. 17-Zoll-Leichtmetallräder, Sportsitze vorne, Matrix-LED-Scheinwerfer (optional), Chromapplikationen.','Fokus auf Eleganz und erweiterte Komfortausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (909,'volkswagen-golf-viii','R-Line','Ausstattungslinie','Sportliche Front- und Heckstoßfänger, 17-Zoll-Leichtmetallräder (optional größer), Sportfahrwerk, R-Line-Logos, Sportsitze.','Betont die sportliche Optik und Fahrdynamik, ohne ein echtes Sportmodell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (910,'volkswagen-golf-viii','GTI','M Performance','Wabenstruktur im Kühlergrill, rote Zierleiste, spezifische 17- oder 18-Zoll-Leichtmetallräder, Doppelendrohr, Sportsitze mit Karomuster.','Sportmodell mit leistungsstärkerem Motor und sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (911,'volkswagen-golf-viii','GTE','M Performance','Blaue Zierleiste im Kühlergrill, spezifische Leichtmetallräder, Doppelendrohr (oft verdeckt), Sportsitze.','Plug-in-Hybrid-Sportmodell mit Fokus auf Effizienz und Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (912,'volkswagen-golf-viii','GTD','M Performance','Wabenstruktur im Kühlergrill, silberne Zierleiste, spezifische Leichtmetallräder, Doppelendrohr links, Sportsitze.','Sportlicher Diesel mit hohem Drehmoment und Langstreckentauglichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (913,'volkswagen-golf-viii','R','Echtes M-Modell','Eigenständige Front- und Heckschürze, 18- oder 19-Zoll-Leichtmetallräder, blaue Bremssättel, vier Endrohre, R-Logos, Sportsitze mit R-Prägung.','Top-Sportmodell mit Allradantrieb und höchster Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (914,'volkswagen-passat-b1','Basis','Basis','Einfache Ausstattung, oft mit unlackierten Stoßfängern (vor Facelift Chrom), Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (915,'volkswagen-passat-b1','L','Ausstattungslinie','Etwas erweiterte Ausstattung gegenüber der Basis, oft mit zusätzlichen Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (916,'volkswagen-passat-b1','LS','Ausstattungslinie','Komfortorientierte Ausstattung, oft mit besseren Sitzen und zusätzlichen Interieurdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (917,'volkswagen-passat-b1','GL','Ausstattungslinie','Luxuriösere Ausstattung, oft mit Veloursitzen, Chromzierrat (vor Facelift) oder speziellen Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (918,'volkswagen-passat-b1','TS','Ausstattungslinie','Sportlichere Ausstattung, oft mit Drehzahlmesser und speziellen Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (919,'volkswagen-passat-b2','C','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (920,'volkswagen-passat-b2','CL','Ausstattungslinie','Etwas erweiterte Komfortmerkmale gegenüber ''C''.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (921,'volkswagen-passat-b2','GL','Ausstattungslinie','Umfassendere Ausstattung, oft mit Chromzierrat, besseren Sitzbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (922,'volkswagen-passat-b2','GT','Ausstattungslinie','Sportlichere Optik, oft mit Spoilern, Sportsitzen, speziellen Felgen und sportlicherem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (923,'volkswagen-passat-b3','CL','Basis','Einfachere Ausstattung, oft mit unlackierten Stoßfängern und Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (924,'volkswagen-passat-b3','GL','Ausstattungslinie','Umfangreichere Ausstattung als CL, oft mit lackierten Stoßfängern, Velourssitzen und elektrischen Fensterhebern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (925,'volkswagen-passat-b3','GT','Ausstattungslinie','Sportlichere Ausstattung, oft mit Sportsitzen, Leichtmetallfelgen, Nebelscheinwerfern und sportlicherem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (926,'volkswagen-passat-b4','CL','Basis','Einfachere Ausstattung, oft mit Stahlfelgen und unlackierten Stoßfängern (je nach Baujahr und Markt).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (927,'volkswagen-passat-b4','GL','Ausstattungslinie','Umfangreichere Ausstattung als CL, oft mit lackierten Stoßfängern, elektrischen Fensterhebern und Zentralverriegelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (928,'volkswagen-passat-b4','GT','Ausstattungslinie','Sportlicher ausgerichtet, oft mit Leichtmetallfelgen, Sportsitzen und sportlicherem Fahrwerk. Verfügbar für stärkere Motorisierungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (929,'volkswagen-passat-b4','VR6','Ausstattungslinie','Spezifische Ausstattung für das Topmodell mit VR6-Motor, oft mit exklusiven Felgen, Sportsitzen und spezifischen Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (930,'volkswagen-passat-b5','Basis','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Polsterstoffe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (931,'volkswagen-passat-b5','Comfortline','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Außenspiegel und Türgriffe, Komfortsitze, Holz- oder Aluminium-Dekoreinlagen im Innenraum.','Bietet mehr Komfort- und Designmerkmale als die Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (932,'volkswagen-passat-b5','Trendline','Ausstattungslinie','Sportlichere Akzente, z.B. Sportsitze, kleinere Leichtmetallfelgen, sportlichere Polsterstoffe.','Fokus auf sportlichere Optik und Haptik im Vergleich zur Comfortline.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (933,'volkswagen-passat-b5','Highline','Ausstattungslinie','Umfangreiche Serienausstattung, größere Leichtmetallfelgen, Chromapplikationen, Lederausstattung (optional oder Serie), hochwertige Dekoreinlagen.','Die Top-Ausstattungslinie mit maximalem Komfort und Luxus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (934,'volkswagen-passat-b6','Trendline','Basis','Stahlfelgen mit Radkappen, schwarze Dachreling (Variant), unlackierte Türgriffe und Spiegelkappen (frühe Modelle), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (935,'volkswagen-passat-b6','Comfortline','Ausstattungslinie','Leichtmetallfelgen, verchromte Zierleisten an den Seitenfenstern, lackierte Türgriffe und Spiegelkappen, Komfortsitze mit hochwertigerem Stoffbezug, Lederlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (936,'volkswagen-passat-b6','Sportline','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezielle Leichtmetallfelgen, dunkle Interieur-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (937,'volkswagen-passat-b6','Highline','Ausstattungslinie','Größere Leichtmetallfelgen, Chromzierleisten an Front und Heck, teilweise Lederausstattung (Alcantara/Leder), Holz- oder Aluminium-Dekoreinlagen im Innenraum, beheizbare Vordersitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (938,'volkswagen-passat-b6','R36','Echtes M-Modell','Eigenständige Front- und Heckschürze, breitere Radläufe, Bi-Xenon-Scheinwerfer, 18-Zoll-Leichtmetallfelgen, verchromte Doppelendrohre, Sportsitze mit R-Logo, Aluminium-Dekor.','Topmodell mit 3.6L VR6 Motor und Allradantrieb, sportlichste Abstimmung und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (939,'volkswagen-passat-b7','Trendline','Basis','Stahlräder mit Radkappen, schwarze Dachreling (Variant), unlackierte Türgriffe und Außenspiegelgehäuse (frühe Modelle), keine Nebelscheinwerfer serienmäßig.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (940,'volkswagen-passat-b7','Comfortline','Ausstattungslinie','Leichtmetallräder, Chromleisten an den Seitenfenstern, lackierte Türgriffe und Außenspiegelgehäuse, Nebelscheinwerfer mit statischem Kurvenlicht.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (941,'volkswagen-passat-b7','Highline','Ausstattungslinie','Größere Leichtmetallräder, Chromzierleisten an Front und Heck, verchromte Dachreling (Variant), LED-Rückleuchten, Sportsitze mit Alcantara/Leder-Bezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (942,'volkswagen-passat-b7','R-Line','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, Seitenschweller, R-Line Schriftzüge, spezielle Leichtmetallräder, Sportfahrwerk, Sportsitze im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (943,'volkswagen-passat-b7','Alltrack','Ausstattungslinie','Erhöhte Bodenfreiheit, Offroad-Beplankung an Radläufen und Schwellern, Unterfahrschutz-Optik vorne und hinten, spezielle Leichtmetallräder, Alltrack-Schriftzüge.','Serienmäßig mit Allradantrieb (4MOTION) und Offroad-Fahrprogramm.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (944,'volkswagen-passat-b8','Trendline','Basis','Stahlräder mit Radkappen (oft 16 Zoll), schwarze Dachreling (Variant), unlackierte Türgriffe und Außenspiegelgehäuse (frühe Modelle), keine Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (945,'volkswagen-passat-b8','Comfortline','Ausstattungslinie','Leichtmetallräder (oft 16 oder 17 Zoll), Chromzierleisten an den Seitenfenstern, lackierte Türgriffe und Außenspiegelgehäuse, Dachreling in Schwarz (Variant).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (946,'volkswagen-passat-b8','Highline','Ausstattungslinie','Größere Leichtmetallräder (oft 17 oder 18 Zoll), Chromzierleisten an den Seitenfenstern und am Kühlergrill, LED-Scheinwerfer (optional oder Serie je nach Baujahr), verchromte Dachreling (Variant).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (947,'volkswagen-passat-b8','R-Line','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, Seitenschweller, R-Line Embleme, spezifische Leichtmetallräder, oft Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (948,'volkswagen-passat-b8','Business','Ausstattungslinie','Basierend auf Comfortline oder Highline, oft mit zusätzlichen Komfort- und Navigationspaketen, äußerlich meist unauffällig, kann aber spezifische Felgen haben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (949,'volkswagen-passat-b8','Elegance','Ausstattungslinie','Nach dem Facelift eingeführt, ersetzt teilweise Highline. Betont Eleganz mit Chromapplikationen, spezifischen Felgen und hochwertigeren Materialien im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (950,'volkswagen-passat-b8','R','Echtes M-Modell',NULL,'Kein echtes R-Modell für den Passat B8 verfügbar.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (951,'volkswagen-arteon-typ-3h','Arteon','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chromapplikationen als höhere Linien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (952,'volkswagen-arteon-typ-3h','Elegance','Ausstattungslinie','Betont Eleganz mit Chromzierleisten, spezifischen Felgen und hochwertigeren Materialien im Innenraum.','Fokus auf Komfort und stilvolles Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (953,'volkswagen-arteon-typ-3h','R-Line','Ausstattungslinie','Sportlichere Optik mit R-Line Stoßfängern, Seitenschwellern, spezifischen Felgen und R-Line Emblemen. Im Innenraum Sportsitze und Sportlenkrad.','Fokus auf sportliches Aussehen, ohne die Leistungssteigerung eines echten R-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (954,'volkswagen-arteon-typ-3h','R','Echtes M-Modell','Exklusive R-Design-Stoßfänger, größere Lufteinlässe, blaue Bremssättel, spezifische 20-Zoll-Felgen, vierflutige Abgasanlage. Im Innenraum Sportsitze mit R-Logo und spezielle Dekorelemente.','Top-Performance-Modell mit leistungsstärkerem Motor und sportlicher Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (955,'volkswagen-t-roc-a1','T-Roc','Basis','Einstiegsmodell, oft mit kleineren Felgen und weniger Chrom-Applikationen. Vor Facelift: Halogen-Scheinwerfer möglich.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (956,'volkswagen-t-roc-a1','Life','Ausstattungslinie','Bietet erweiterte Komfortmerkmale wie Leichtmetallräder, Klimaautomatik und verbesserte Infotainment-Systeme. Nach Facelift: oft mit LED-Scheinwerfern.','Positioniert über der Basislinie, mit Fokus auf Komfort und Alltagstauglichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (957,'volkswagen-t-roc-a1','Style','Ausstattungslinie','Betont Design und Individualisierung, oft mit zweifarbiger Lackierung, Chrom-Paket, größeren Leichtmetallrädern und speziellen Sitzbezügen. Vor Facelift: C-förmige LED-Tagfahrlichter.','Fokus auf Design und gehobene Optik, oft mit mehr Individualisierungsmöglichkeiten als ''Life''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (958,'volkswagen-t-roc-a1','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern (vorne und hinten), R-Line-Emblemen, Sportfahrwerk (optional), größeren Leichtmetallrädern und Sportsitzen im Innenraum. Nach Facelift: oft mit durchgehendem LED-Lichtband an der Front.','Bietet eine sportlichere Optik und Haptik, ohne die Leistungssteigerung eines echten R-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (959,'volkswagen-t-roc-a1','T-Roc R','Echtes M-Modell','Deutlich aggressivere Front- und Heckschürzen, vierflutige Abgasanlage, größere Bremsanlage, spezifische R-Leichtmetallräder, R-Logo an Kühlergrill und Heck, Sportsitze mit R-Branding. Nach Facelift: blaue Bremssättel, Matrix-LED-Scheinwerfer serienmäßig.','Das Topmodell mit leistungsstärkerem Motor, Allradantrieb und sportlicher Fahrwerksabstimmung, klar erkennbar an den R-spezifischen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (960,'volkswagen-t-cross-c1','T-Cross','Basis','Grundausstattung, oft mit Stahlfelgen oder kleineren Leichtmetallrädern, grundlegende Stoffbezüge im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (961,'volkswagen-t-cross-c1','Life','Ausstattungslinie','Zusätzliche Komfortmerkmale wie Leichtmetallräder, Klimaanlage, Multifunktionslenkrad, oft Chromapplikationen.','Bietet mehr Komfort und Ausstattung als die Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (962,'volkswagen-t-cross-c1','Style','Ausstattungslinie','Hochwertigere Ausstattung mit größeren Leichtmetallrädern, LED-Scheinwerfern, Ambientebeleuchtung, verchromten Zierelementen und besseren Sitzbezügen.','Fokus auf Design und gehobenen Komfort, über Life positioniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (963,'volkswagen-t-cross-c1','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen R-Line Stoßfängern, Seitenschwellern, R-Line Emblemen, größeren Leichtmetallrädern und Sportsitzen im Innenraum.','Betont die sportliche Seite des T-Cross, ohne ein echtes M-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (964,'volkswagen-taigo-2020','Life','Ausstattungslinie','Basis-Ausstattung mit 16-Zoll-Leichtmetallrädern, LED-Scheinwerfern und Dachreling.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (965,'volkswagen-taigo-2020','Style','Ausstattungslinie','Umfangreichere Ausstattung mit 17-Zoll-Leichtmetallrädern, IQ.LIGHT LED-Matrixscheinwerfern und Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (966,'volkswagen-taigo-2020','R-Line','Ausstattungslinie','Sportliche Optik mit spezifischen R-Line Stoßfängern, 17-Zoll-Leichtmetallrädern (optional 18 Zoll), Sportfahrwerk und R-Line Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (967,'volkswagen-tiguan-i','Trend & Fun','Basis','Einstiegsmodell, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (968,'volkswagen-tiguan-i','Sport & Style','Ausstattungslinie','Sportlichere Optik mit größeren Leichtmetallrädern, Dachreling und oft Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (969,'volkswagen-tiguan-i','Track & Field','Ausstattungslinie','Offroad-orientierte Optik mit einem speziellen Frontstoßfänger für einen größeren Böschungswinkel (28 Grad statt 18 Grad), Unterfahrschutz und oft spezifischen Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (970,'volkswagen-tiguan-i','R-Line','Ausstattungslinie','Sportpaket mit spezifischen Stoßfängern, Seitenschwellern, Heckspoiler, R-Line-Emblemen und größeren Leichtmetallrädern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (971,'volkswagen-tiguan-i','CityScape','Ausstattungslinie','Sondermodell mit spezifischen Designelementen, oft basierend auf ''Sport & Style'' oder ''Trend & Fun'', mit besonderen Felgen und Interieurdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (972,'volkswagen-tiguan-ii','Trendline','Basis','Einfachere Ausstattung, kleinere Räder, oft ohne Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (973,'volkswagen-tiguan-ii','Comfortline','Ausstattungslinie','Umfangreichere Serienausstattung, oft mit Leichtmetallrädern, Dachreling und Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (974,'volkswagen-tiguan-ii','Highline','Ausstattungslinie','Top-Ausstattung, größere Leichtmetallräder, LED-Scheinwerfer, Chrompaket, oft mit Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (975,'volkswagen-tiguan-ii','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, R-Line-Logos, größeren Rädern und Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (976,'volkswagen-tiguan-ii','Elegance','Ausstattungslinie','Nach dem Facelift eingeführt, ersetzt teilweise Highline. Fokus auf Eleganz mit Chromdetails, hochwertigen Materialien im Innenraum und spezifischen Felgendesigns.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (977,'volkswagen-tiguan-ii','Life','Ausstattungslinie','Nach dem Facelift eingeführt, ersetzt teilweise Comfortline. Bietet eine gute Balance aus Ausstattung und Preis.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (978,'volkswagen-touran-i','Conceptline','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Polsterstoffe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (979,'volkswagen-touran-i','Trendline','Ausstattungslinie','Lackierte Türgriffe und Außenspiegel, oft mit Klimaanlage und Radio.','Bietet mehr Komfort- und Sicherheitsausstattung als die Conceptline.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (980,'volkswagen-touran-i','Comfortline','Ausstattungslinie','Leichtmetallfelgen (optional), bessere Sitzbezüge, zusätzliche Ablagen, oft mit Tempomat und Parksensoren.','Erweitert die Trendline um weitere Komfort- und Designmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (981,'volkswagen-touran-i','Highline','Ausstattungslinie','Größere Leichtmetallfelgen, Chromapplikationen, Sportsitze, Klimaautomatik, hochwertige Innenraummaterialien.','Die Top-Ausstattungslinie mit maximalem Komfort und exklusiven Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (982,'volkswagen-touran-i','CrossTouran','Ausstattungslinie','Offroad-Optik mit schwarzen Radlaufverbreiterungen, Seitenschwellern und speziellen Stoßfängern, erhöhte Bodenfreiheit, spezielle Leichtmetallfelgen.','Eine eigenständige Variante mit robustem Offroad-Look und leicht erhöhter Bodenfreiheit, basierend auf der Comfortline-Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (983,'volkswagen-touran-ii','Trendline','Basis','Standard-Stoßfänger, Außenspiegel und Türgriffe in Wagenfarbe, Stahlräder mit Radabdeckungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (984,'volkswagen-touran-ii','Comfortline','Ausstattungslinie','Chromzierleisten an Kühlergrill und Seitenfenstern, Leichtmetallräder, Nebelscheinwerfer.','Umfangreichere Komfort- und Designmerkmale im Vergleich zur Trendline.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (985,'volkswagen-touran-ii','Highline','Ausstattungslinie','Sportlichere Frontschürze, Bi-Xenon-Scheinwerfer mit LED-Tagfahrlicht, größere Leichtmetallräder, Ledersitze (optional).','Höchste Ausstattungslinie mit Fokus auf Komfort und sportliches Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (986,'volkswagen-touran-ii','R-Line','M Performance','Spezifische R-Line Front- und Heckschürze, Seitenschweller, R-Line Emblem, größere Leichtmetallräder, Sportfahrwerk.','Sportliche Optikpaket-Linie, basierend auf der Highline.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (987,'volkswagen-touareg-i','Basis','Basis','Weniger Chromapplikationen, kleinere Felgen, oft unlackierte Stoßfängerunterteile (je nach Markt und Baujahr).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (988,'volkswagen-touareg-i','Executive','Ausstattungslinie','Umfangreichere Chromzierleisten, größere Leichtmetallräder, oft Lederausstattung und erweiterte Komfortmerkmale.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (989,'volkswagen-touareg-i','R50','Ausstattungslinie','Sportlichere Front- und Heckschürzen, verbreiterte Radläufe, 21-Zoll-Leichtmetallräder ''Omanyt'', spezifische Lackierungen, blaue Bremssättel, R-Logo-Embleme.','Top-Modell mit dem stärksten Dieselmotor (V10 TDI mit 350 PS), sportlich abgestimmtes Fahrwerk und exklusive Innenausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (990,'volkswagen-touareg-ii','Touareg','Basis','Grundausstattung, oft mit 17-Zoll-Leichtmetallrädern, schwarze Dachreling, keine spezifischen Chrom-Applikationen über das Standardmaß hinaus.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (991,'volkswagen-touareg-ii','Terrain Tech','Ausstattungslinie','Speziell für Offroad-Einsatz konzipiert, oft mit Unterfahrschutz, verstärktem Fahrwerk und spezifischen Felgen. Äußerlich dezente Unterschiede zur Basis, Fokus auf Funktionalität.','Verfügt über ein erweitertes Offroad-Paket mit Mitteldifferenzialsperre, Reduktionsgetriebe und größerem Kraftstofftank (100 Liter statt 85 Liter).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (992,'volkswagen-touareg-ii','Executive Edition','Ausstattungslinie','Hochwertige Ausstattung mit spezifischen 19-Zoll-Leichtmetallrädern, abgedunkelten Scheiben hinten, LED-Rückleuchten und Chrom-Applikationen.','Bietet eine erweiterte Komfort- und Designausstattung, oft mit Ledersitzen, Navigationssystem und weiteren Assistenzsystemen serienmäßig.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (993,'volkswagen-touareg-ii','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern vorne und hinten, Seitenschwellern, Dachkantenspoiler, R-Line Emblemen und größeren Leichtmetallrädern (oft 19 oder 20 Zoll).','Fokus auf sportliches Design, ohne die Leistungssteigerung eines echten R-Modells. Innenraum mit Sportsitzen und R-Line Lenkrad.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (994,'volkswagen-touareg-iii','Atmosphere','Ausstattungslinie','Betont Eleganz und Luxus mit Holz- und Chromapplikationen im Innenraum, spezifischen Felgendesigns und einer eher klassischen Optik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (995,'volkswagen-touareg-iii','Elegance','Ausstattungslinie','Fokus auf moderne Ästhetik mit gebürstetem Aluminium und Chrom im Innenraum, spezifischen Felgen und einer klaren, zeitgemäßen Linienführung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (996,'volkswagen-touareg-iii','R-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, größeren Felgen, R-Line-Logos und sportlichen Akzenten im Innenraum (z.B. Sportsitze, schwarzer Dachhimmel).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (997,'volkswagen-touareg-iii','Touareg R','Echtes M-Modell','Top-Modell mit Plug-in-Hybrid-Antrieb, spezifischen R-Design-Elementen wie blauen Bremssätteln, 20-Zoll-Felgen, R-Logos, sportlicher Front- und Heckschürze und exklusiven Interieurdetails.','Das Top-Modell der Baureihe mit Fokus auf Performance und exklusiver Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (998,'volkswagen-caddy-ii','Basis','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger und Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (999,'volkswagen-caddy-ii','Kombi','Ausstattungslinie','Verglaste Seitenfenster im Fond, Rücksitze, oft mit lackierten Stoßfängern und Radkappen.','Personenbeförderung im Gegensatz zum Kastenwagen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1000,'volkswagen-caddy-iii','Caddy','Basis','Einfache Stoßfänger in Schwarz, Stahlfelgen, Basis-Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1001,'volkswagen-caddy-iii','Life','Ausstattungslinie','Stoßfänger in Wagenfarbe, Leichtmetallfelgen (optional), verbesserte Innenraummaterialien, Klimaanlage.','Höherwertige Ausstattung und mehr Komfort als die Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1002,'volkswagen-caddy-iii','Trendline','Ausstattungslinie','Ähnlich wie Life, aber mit zusätzlichen Komfortmerkmalen und optionalen Paketen.','Eine gehobenere Variante der Life-Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1003,'volkswagen-caddy-iii','Comfortline','Ausstattungslinie','Umfangreichere Ausstattung, oft mit besseren Sitzen, mehr Chrom-Applikationen und erweiterten Funktionalitäten.','Die höchste Ausstattungslinie vor den Sondermodellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1004,'volkswagen-caddy-iii','Maxi','Ausstattungslinie','Längerer Radstand und vergrößerter Laderaum, verfügbar in verschiedenen Ausstattungsvarianten (z.B. Maxi Life).','Fokus auf maximalen Platz, unabhängig von der spezifischen Ausstattungslinie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1005,'volkswagen-caddy-iv','Conceptline','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Stoßfängern (je nach Markt und Konfiguration).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1006,'volkswagen-caddy-iv','Trendline','Ausstattungslinie','Umfangreichere Ausstattung als Conceptline, oft mit lackierten Stoßfängern, Klimaanlage und Radio.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1007,'volkswagen-caddy-iv','Comfortline','Ausstattungslinie','Höherwertige Ausstattung mit Komfortmerkmalen wie Leichtmetallfelgen, Multifunktionslenkrad, verbesserter Infotainment-System.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1008,'volkswagen-caddy-iv','Highline','Ausstattungslinie','Top-Ausstattungslinie mit weiteren Komfort- und Designelementen, z.B. LED-Scheinwerfer (optional), Klimaautomatik, Navigationssystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1009,'volkswagen-caddy-iv','Generation Four','Ausstattungslinie','Sondermodell zur Einführung der Generation IV, oft mit speziellen Designelementen und umfangreicher Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1010,'volkswagen-caddy-iv','Beach','Ausstattungslinie','Freizeit- und Camping-orientierte Ausstattung mit Schlafgelegenheit und praktischen Details für Outdoor-Aktivitäten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1011,'volkswagen-caddy-iv','Edition 35','Ausstattungslinie','Sondermodell zum 35-jährigen Jubiläum des Caddy, mit exklusiven Designmerkmalen und erweiterter Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1012,'volkswagen-caddy-v','Caddy','Basis','Unlackierte Stoßfänger (teilweise), Stahlfelgen, grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1013,'volkswagen-caddy-v','Caddy Life','Ausstattungslinie','Lackierte Stoßfänger, Radzierblenden oder Leichtmetallräder (optional), verbesserte Innenraumausstattung.','Komfortorientierte Ausstattung für Privatkunden.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1014,'volkswagen-caddy-v','Caddy Style','Ausstattungslinie','Chromapplikationen, LED-Scheinwerfer, Leichtmetallräder, hochwertige Innenraummaterialien.','Top-Ausstattungslinie mit Fokus auf Design und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1015,'volkswagen-caddy-v','Caddy California','Ausstattungslinie','Integrierte Mini-Küche, Klappbett, Camping-spezifische Details.','Camping-Variante mit spezieller Ausstattung für Übernachtungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1016,'volkswagen-caddy-v','Caddy Cargo','Ausstattungslinie','Geschlossener Laderaum, unlackierte Stoßfänger (Basis), robuste Materialien.','Nutzfahrzeug-Variante für gewerbliche Zwecke.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1017,'volkswagen-sharan-i','Conceptline','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Stoßfängern (frühe Modelle).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1018,'volkswagen-sharan-i','Trendline','Ausstattungslinie','Etwas umfangreichere Ausstattung als Conceptline, oft mit elektrischen Fensterhebern und Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1019,'volkswagen-sharan-i','Comfortline','Ausstattungslinie','Komfortorientierte Ausstattung, oft mit besseren Sitzen, Leichtmetallfelgen und erweiterten Komfortfunktionen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1020,'volkswagen-sharan-i','Highline','Ausstattungslinie','Top-Ausstattungslinie mit Lederausstattung, Klimaautomatik, hochwertigeren Materialien und weiteren Extras.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1021,'volkswagen-sharan-i','Family','Ausstattungslinie','Spezielle Ausstattung für Familien, oft mit zusätzlichen Ablagen oder Kindersitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1022,'volkswagen-sharan-ii','Trendline','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Scheinwerfer',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1023,'volkswagen-sharan-ii','Comfortline','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Außenspiegel, Chromzierleisten an den Seitenfenstern (teilweise), Komfortsitze',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1024,'volkswagen-sharan-ii','Highline','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-Xenon-Scheinwerfer (vor Facelift) oder LED-Scheinwerfer (nach Facelift), Chromzierleisten an Front und Heck, Sportsitze oder Lederausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1025,'volkswagen-id.3-1.-generation','Pure Performance','Basis','Einstiegsmodell, oft mit kleineren Rädern und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1026,'volkswagen-id.3-1.-generation','Pro','Ausstattungslinie','Mittlere Ausstattung, oft mit erweiterten Infotainment-Funktionen und Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1027,'volkswagen-id.3-1.-generation','Pro S','Ausstattungslinie','Top-Ausstattung, oft mit größeren Rädern, Panoramadach, Premium-Interieur und erweiterten Assistenzsystemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1028,'volkswagen-id.3-1.-generation','1st','Ausstattungslinie','Sondermodell zur Markteinführung, oft mit exklusiven Farben, Felgen und umfangreicher Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1029,'volkswagen-id.4-1.-generation','Pure','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1030,'volkswagen-id.4-1.-generation','Pro','Ausstattungslinie','Umfangreichere Ausstattung, oft mit größeren Felgen, optionalen IQ.Light LED-Matrix-Scheinwerfern und mehr Design-Elementen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1031,'volkswagen-id.4-1.-generation','Pro Performance','Ausstattungslinie','Wie Pro, aber mit stärkerem Antrieb. Optisch kaum Unterschiede zur Pro-Linie.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1032,'volkswagen-id.4-1.-generation','GTX','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, schwarzen Design-Elementen, GTX-Logos, größeren Felgen und oft einer Zweifarblackierung mit schwarzem Dach. Rote Ziernähte im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1033,'volkswagen-id.5-1.-generation','Pro','Basis','Standard-Stoßfänger, 19-Zoll-Leichtmetallräder, LED-Scheinwerfer',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1034,'volkswagen-id.5-1.-generation','Pro Performance','Ausstattungslinie','Ähnlich Pro, aber mit stärkerem Antrieb','Stärkerer Elektromotor als Pro.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1035,'volkswagen-id.5-1.-generation','GTX','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, spezifische 20- oder 21-Zoll-Leichtmetallräder, GTX-Logos, Matrix-LED-Scheinwerfer (IQ.Light) serienmäßig, schwarze Akzente','Allradantrieb (Dualmotor), sportlichere Fahrwerksabstimmung, exklusive Designelemente innen und außen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1036,'volkswagen-id.7-1.-generation','Pro','Ausstattungslinie','Basis-Ausstattung mit 19-Zoll-Leichtmetallrädern, LED-Scheinwerfern und -Rückleuchten, Infotainmentsystem mit 15-Zoll-Display.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1037,'volkswagen-id.7-1.-generation','Pro S','Ausstattungslinie','Erweiterte Ausstattung, oft mit größerer Batteriekapazität und höherer Reichweite. Optisch können größere Felgen oder spezifische Designelemente hinzukommen.','Hauptsächlich durch die größere Batteriekapazität und damit verbundene höhere Reichweite vom ''Pro'' Modell abgegrenzt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1038,'volkswagen-id.7-1.-generation','Tourer','Ausstattungslinie','Kombi-Variante mit erweitertem Kofferraumvolumen und einer geänderten Heckpartie. Behält die Front des ID.7 bei.','Karosserieform als Kombi, bietet mehr Laderaum und Variabilität im Vergleich zur Limousine.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1039,'volkswagen-id.-buzz-1.-generation','Pro','Ausstattungslinie','Standardausstattung, 19-Zoll-Leichtmetallräder, LED-Scheinwerfer, beheizbare Frontscheibe, Infotainmentsystem mit 10-Zoll-Display.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1040,'volkswagen-id.-buzz-1.-generation','Cargo','Ausstattungslinie','Kastenwagen-Variante mit geschlossenen Seitenwänden hinten (optional mit Fenstern), robustere Innenraumgestaltung, meist Stahlfelgen oder kleinere Leichtmetallräder, Fokus auf Funktionalität und Ladekapazität.','Primär für gewerbliche Nutzung konzipiert, mit zwei oder drei Vordersitzen und großem Laderaum anstelle der hinteren Sitzreihe.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1041,'opel-corsa-a','Corsa','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1042,'opel-corsa-a','LS','Ausstattungslinie','Leicht verbesserte Ausstattung gegenüber der Basis, oft mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1043,'opel-corsa-a','GL','Ausstattungslinie','Komfortorientierte Ausstattung, oft mit Veloursitzen und besseren Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1044,'opel-corsa-a','GT','Ausstattungslinie','Sportlichere Optik mit speziellen Felgen, Spoilerlippe und sportlicheren Sitzen. Vor dem Facelift oft mit roten Zierstreifen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1045,'opel-corsa-a','GSi','Ausstattungslinie','Top-Sportmodell mit markanten Spoilern, Seitenschwellern, speziellen Leichtmetallfelgen und Sportsitzen. Nach dem Facelift mit runderen Anbauteilen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1046,'opel-corsa-a','Swing','Ausstattungslinie','Sondermodell, oft mit speziellen Polstern und Farben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1047,'opel-corsa-a','Joy','Ausstattungslinie','Sondermodell, oft mit speziellen Polstern und Farben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1048,'opel-corsa-b','City','Basis','Einfache Ausstattung, oft ohne elektrische Fensterheber oder Zentralverriegelung, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1049,'opel-corsa-b','Swing','Ausstattungslinie','Etwas gehobenere Ausstattung als City, oft mit Drehzahlmesser, Veloursitze, teilweise Zentralverriegelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1050,'opel-corsa-b','Sport','Ausstattungslinie','Sportlichere Optik mit Sportsitzen, Sportlenkrad, oft Leichtmetallfelgen, Spoiler und tiefergelegtem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1051,'opel-corsa-b','GSi','Ausstattungslinie','Top-Sportmodell mit spezifischen Stoßfängern, Seitenschwellern, Heckspoiler, Sportsitzen und Leichtmetallfelgen. Nur als 3-Türer erhältlich.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1052,'opel-corsa-b','CD','Ausstattungslinie','Komfortorientierte Ausstattung mit Features wie elektrischen Fensterhebern, Zentralverriegelung, Radio, oft mit Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1058,'opel-corsa-c','Basis','Basis','Einfache Stahlfelgen, unlackierte Stoßfänger (teilweise), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1059,'opel-corsa-c','Enjoy','Ausstattungslinie','Oft mit Radkappen oder Leichtmetallfelgen, lackierte Stoßfänger, teilweise Nebelscheinwerfer.','Komfortorientierte Ausstattung mit Extras wie Klimaanlage, CD-Radio, elektrische Fensterheber vorne.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1060,'opel-corsa-c','Elegance','Ausstattungslinie','Leichtmetallfelgen, Chromapplikationen, Nebelscheinwerfer, lackierte Türgriffe und Spiegelkappen.','Hochwertigere Ausstattung mit zusätzlichen Komfort- und Designmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1061,'opel-corsa-c','Sport','Ausstattungslinie','Sportliche Leichtmetallfelgen, Spoiler (teilweise), Sportsitze, Sportfahrwerk.','Fokus auf sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1062,'opel-corsa-c','GSi','Ausstattungslinie','Spezifische Leichtmetallfelgen, dezente Spoiler, Sportsitze, Sportlenkrad, GSi-Embleme.','Top-Sportmodell unterhalb des OPC, mit stärkeren Motoren und sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1063,'opel-corsa-d','Selection','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (teilweise), einfache Polsterstoffe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1064,'opel-corsa-d','Edition','Ausstattungslinie','Oft mit Klimaanlage, Radio-CD-System, elektrischen Fensterhebern vorn.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1065,'opel-corsa-d','Innovation','Ausstattungslinie','Leichtmetallräder, Nebelscheinwerfer, Chromapplikationen, bessere Polsterstoffe, oft mit Klimaautomatik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1066,'opel-corsa-d','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezielle Leichtmetallräder, Sportlenkrad, oft mit Dachspoiler.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1067,'opel-corsa-d','GSi','Ausstattungslinie','Sportliche Front- und Heckschürzen, Seitenschweller, 17-Zoll-Leichtmetallräder, Sportsitze, verchromtes Auspuffendrohr.','Positioniert unterhalb des OPC, aber sportlicher als die regulären Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1068,'opel-corsa-d','OPC','Echtes M-Modell','Aggressive Frontschürze mit großen Lufteinlässen, markante Seitenschweller, Heckschürze mit Diffusor und zentralem Dreiecks-Auspuffrohr, 17- oder 18-Zoll-Leichtmetallräder, Recaro-Sportsitze, OPC-spezifische Instrumente und Lenkrad.','Das Topmodell der Baureihe mit dem stärksten Motor und einer umfassenden sportlichen Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1069,'opel-corsa-e','Selection','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (teilweise), einfache Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1070,'opel-corsa-e','Edition','Ausstattungslinie','Oft mit Klimaanlage, Radio CD 3.0 BT, elektrische Fensterheber vorn, Außenspiegel elektrisch einstell- und beheizbar.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1071,'opel-corsa-e','Innovation','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Leichtmetallrädern, Nebelscheinwerfern, Chromapplikationen, IntelliLink Infotainmentsystem, Klimaautomatik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1072,'opel-corsa-e','Color Edition','Ausstattungslinie','Kontrastfarbenes Dach, spezielle Leichtmetallräder, sportliche Akzente im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1073,'opel-corsa-e','OPC Line','M Performance','Sportliche Front- und Heckschürzen, Seitenschweller, Dachspoiler, Sportfahrwerk, OPC Line Lenkrad und Schaltknauf.','Optikpaket, das an die OPC-Modelle angelehnt ist, aber nicht die volle Motorleistung oder Fahrwerksabstimmung eines echten OPC bietet.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1074,'opel-corsa-e','OPC','Echtes M-Modell','Aggressivere Frontschürze mit großen Lufteinlässen, markante Seitenschweller, Heckschürze mit Diffusor und zentralem Doppelrohrauspuff, 17- oder 18-Zoll-Leichtmetallräder, Recaro Sportsitze, OPC-spezifische Instrumente.','Das Topmodell mit leistungsstarkem Motor (1.6 Turbo), Sportfahrwerk und spezifischer Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1075,'opel-corsa-f','Edition','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe und Außenspiegel (je nach Baujahr/Markt), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1076,'opel-corsa-f','Elegance','Ausstattungslinie','Leichtmetallfelgen, Chromapplikationen an den Fenstern, LED-Scheinwerfer (optional oder serienmäßig), hochwertigere Innenraummaterialien.','Bietet mehr Komfort- und Designmerkmale als die Edition.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1077,'opel-corsa-f','GS Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, schwarze Akzente (Dach, Spiegelkappen), Sportsitze, 17-Zoll-Leichtmetallfelgen, rote Ziernähte im Innenraum.','Betont die sportliche Optik und Fahrdynamik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1078,'opel-corsa-f','Ultimate','Ausstattungslinie','Umfangreichste Ausstattung, oft mit IntelliLux LED Matrix Licht, größeren Leichtmetallfelgen, Panorama-Glasdach (optional), Lederausstattung (optional).','Die Top-Ausstattungslinie mit maximalem Komfort und Technologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1079,'opel-astra-f','GL','Ausstattungslinie','Oft mit Radkappen, unlackierte Stoßfänger (frühe Modelle), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1080,'opel-astra-f','LS','Ausstattungslinie','Ähnlich GL, oft mit geringfügig besserer Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1081,'opel-astra-f','GT','Ausstattungslinie','Sportlicher angehaucht, oft mit Nebelscheinwerfern, Sportsitzen, Drehzahlmesser, lackierten Stoßfängern (spätere Modelle).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1082,'opel-astra-f','CD','Ausstattungslinie','Komfortorientiert, oft mit Velourspolstern, elektrischen Fensterhebern, Zentralverriegelung, lackierten Stoßfängern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1083,'opel-astra-f','GSi','Ausstattungslinie','Sportmodell mit spezifischen Stoßfängern, Seitenschwellern, Heckspoiler, Sportsitzen, Alufelgen, oft mit 16V-Schriftzug.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1084,'opel-astra-f','Sportive','Ausstattungslinie','Sportliche Optik, oft mit Alufelgen, Sportsitzen, Lederlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1085,'opel-astra-f','Club','Ausstattungslinie','Sondermodell, oft mit spezifischen Polstern und Ausstattungsdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1086,'opel-astra-f','Dream','Ausstattungslinie','Sondermodell, oft mit speziellen Lackierungen und Innenausstattungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1087,'opel-astra-g','Basis','Basis','Stahlfelgen, unlackierte Stoßfänger (oftmals), einfache Stoffbezüge, manuelle Fensterheber',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1088,'opel-astra-g','Comfort','Ausstattungslinie','Leicht verbesserte Stoffe, elektrische Fensterheber vorne, Zentralverriegelung, oft in Wagenfarbe lackierte Stoßfänger',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1089,'opel-astra-g','Edition','Ausstattungslinie','Spezielle Polsterstoffe, oft Klimaanlage und Radio serienmäßig, Leichtmetallfelgen optional',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1090,'opel-astra-g','Sport','Ausstattungslinie','Sportsitze, Sportfahrwerk, Leichtmetallfelgen, oft Lederlenkrad und Schaltknauf, weiße Instrumentenbeleuchtung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1091,'opel-astra-g','Elegance','Ausstattungslinie','Hochwertigere Stoffe oder Teilleder, Holz- oder Aluminiumapplikationen im Innenraum, Klimaautomatik, Nebelscheinwerfer, Leichtmetallfelgen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1092,'opel-astra-g','Executive','Ausstattungslinie','Umfangreiche Ausstattung, oft mit Ledersitzen, Navigationssystem (optional), Xenon-Scheinwerfer (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1093,'opel-astra-g','OPC','Echtes M-Modell','Aggressivere Front- und Heckschürzen, Seitenschweller, großer Heckspoiler (beim Coupé), spezielle Leichtmetallfelgen, Recaro-Sportsitze, Sportlenkrad, blaue Instrumentenbeleuchtung','Performance-Modell mit leistungsstärkeren Motoren und angepasstem Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1094,'opel-astra-h','Essentia','Basis','Einfache Radzierblenden, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1095,'opel-astra-h','Enjoy','Ausstattungslinie','In Wagenfarbe lackierte Türgriffe und Außenspiegel, oft Leichtmetallfelgen optional, bessere Stoffe im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1096,'opel-astra-h','Edition','Ausstattungslinie','Ähnlich wie Enjoy, oft mit zusätzlichen Komfortmerkmalen oder speziellen Felgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1097,'opel-astra-h','Sport','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, Sportfahrwerk, Sportsitze, spezielle Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1098,'opel-astra-h','Cosmo','Ausstattungslinie','Hochwertigere Materialien im Innenraum (z.B. Teilleder), Chromapplikationen, Klimaautomatik, oft größere Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1099,'opel-astra-h','OPC','Echtes M-Modell','Sehr aggressive Frontschürze mit großen Lufteinlässen, markante Seitenschweller, Heckspoiler, zentraler Doppelauspuff, 18- oder 19-Zoll-Leichtmetallfelgen, Recaro-Sportsitze, OPC-spezifische Instrumente.','Das Topmodell der Baureihe mit eigenständigem, leistungsstarkem Motor und umfassenden Fahrwerksmodifikationen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1100,'opel-astra-j','Selection','Basis','Stahlfelgen, unlackierte Türgriffe (teilweise), grundlegende Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1101,'opel-astra-j','Edition','Ausstattungslinie','Leichtmetallfelgen (optional), Klimaanlage, Radio CD 300/400, elektrische Fensterheber vorn',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1102,'opel-astra-j','Sport','Ausstattungslinie','Sportsitze, Sportfahrwerk (optional), 17-Zoll-Leichtmetallfelgen, Chromleisten an den Seitenfenstern',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1103,'opel-astra-j','Innovation','Ausstattungslinie','17-Zoll-Leichtmetallfelgen, Klimaautomatik, Licht- und Regensensor, Teilledersitze (optional), Navi (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1104,'opel-astra-j','Business Edition','Ausstattungslinie','Navigationssystem, Parkpilot, Sitzheizung, Tempomat',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1105,'opel-astra-j','Active','Ausstattungslinie','Spezielle Leichtmetallfelgen, Teilleder-Ausstattung, Klimaautomatik, Sitzheizung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1106,'opel-astra-j','GTC','Ausstattungslinie','Eigenständige Coupé-Karosserie, sportlicheres Fahrwerk, 18-Zoll-Leichtmetallfelgen, Sportsitze','Eigenständiges Karosseriedesign als 3-Türer Coupé.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1107,'opel-astra-j','OPC','Echtes M-Modell','Aggressiveres Bodykit, große Lufteinlässe, zentraler Sportauspuff, 19-Zoll-Leichtmetallfelgen, Recaro-Sportsitze, Brembo-Bremsanlage','Top-Sportmodell mit 206 kW (280 PS) Motorisierung und spezifischem Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1108,'opel-astra-k','Selection','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe (teilweise), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1109,'opel-astra-k','Edition','Ausstattungslinie','Leichtmetallfelgen (oft 16 Zoll), lackierte Türgriffe, Klimaanlage, Radio mit Touchscreen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1110,'opel-astra-k','Dynamic','Ausstattungslinie','Sportlichere Stoßfänger, größere Leichtmetallfelgen (oft 17 Zoll), Sportsitze, LED-Rückleuchten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1111,'opel-astra-k','Innovation','Ausstattungslinie','Chromzierleisten, größere Leichtmetallfelgen (oft 17 oder 18 Zoll), IntelliLux LED Matrix-Licht (optional oder serienmäßig bei höheren Ausstattungen), Navigationssystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1112,'opel-astra-k','Ultimate','Ausstattungslinie','Exklusive Leichtmetallfelgen, IntelliLux LED Matrix-Licht, Lederausstattung, Premium-Infotainmentsystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1113,'opel-astra-k','GS Line','Ausstattungslinie','Sportliche Designelemente, schwarze Akzente, Sportsitze, spezifische Leichtmetallfelgen.','Ersetzte teilweise die Dynamic-Linie nach dem Facelift.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1114,'opel-astra-l','Edition','Basis','Grundausstattung, oft mit 16-Zoll-Stahlrädern oder kleineren Leichtmetallrädern, grundlegende LED-Beleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1115,'opel-astra-l','Elegance','Ausstattungslinie','Zusätzliche Chrom-Applikationen, größere Leichtmetallräder (z.B. 17 Zoll), verbesserte Innenraummaterialien, oft mit AGR-Sitzen.','Bietet mehr Komfort- und Designmerkmale als die Edition.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1116,'opel-astra-l','GS Line','Ausstattungslinie','Sportlichere Optik mit schwarzen Akzenten (Dach, Spiegelkappen), spezifische Leichtmetallräder (z.B. 18 Zoll), sportlichere Stoßfänger, oft mit Alcantara-Sitzen.','Fokus auf sportliches Design und Fahrdynamik, ohne ein echtes M-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1117,'opel-astra-l','Ultimate','Ausstattungslinie','Umfangreichste Ausstattung, oft mit Matrix-LED-Licht (Intelli-Lux LED Pixel Licht), größeren Leichtmetallrädern (z.B. 18 Zoll), Premium-Interieur mit Leder und erweiterten Assistenzsystemen.','Die Top-Ausstattungslinie mit maximalem Komfort und Technologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1118,'opel-insignia-b','Selection','Basis','Einfache Radzierblenden, unlackierte Türgriffe (teilweise), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1119,'opel-insignia-b','Edition','Ausstattungslinie','Leichtmetallräder (oft 17 Zoll), verchromte Fensterleisten, verbesserte Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1120,'opel-insignia-b','Business Edition','Ausstattungslinie','Ähnlich Edition, aber mit Fokus auf Komfort- und Konnektivitätsfeatures für Vielfahrer (z.B. Navigationssystem, Parksensoren).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1121,'opel-insignia-b','Dynamic','Ausstattungslinie','Sportlichere Akzente, größere Leichtmetallräder (oft 18 Zoll), Sportsitze, dunkle Dachhimmel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1122,'opel-insignia-b','Innovation','Ausstattungslinie','Umfangreiche Komfort- und Technikfeatures, oft mit IntelliLux LED Matrix Licht (vor Facelift), hochwertige Materialien, größere Leichtmetallräder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1123,'opel-insignia-b','Ultimate','Ausstattungslinie','Top-Ausstattung mit allen verfügbaren Optionen, exklusive Leichtmetallräder, Premium-Interieur, oft mit Head-up-Display und adaptiver Fahrwerksregelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1124,'opel-insignia-b','GSi','M Performance','Aggressivere Front- und Heckschürzen, spezielle 20-Zoll-Leichtmetallräder, Brembo-Bremsanlage, Sportfahrwerk, GSi-spezifische Sportsitze und Lenkrad.','Deutlich sportlicher positioniert als die zivilen Modelle, mit spezifischer Fahrwerksabstimmung und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1125,'opel-insignia-b','Country Tourer','Ausstattungslinie','Erhöhte Bodenfreiheit, robuste Kunststoffbeplankung an Radläufen und Schwellern, Unterfahrschutz-Optik an Front und Heck, spezifische Leichtmetallräder.','Nur als Sports Tourer (Kombi) erhältlich, mit Offroad-Optik und Allradantrieb (optional/serienmäßig je nach Motorisierung).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1126,'opel-mokka-a','Selection','Basis','Stahlräder mit Radkappen, unlackierte Stoßfängerunterteile (je nach Baujahr/Markt), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1127,'opel-mokka-a','Edition','Ausstattungslinie','Leichtmetallräder (oft 17 Zoll), Nebelscheinwerfer, Dachreling, Chromleisten an den Seitenfenstern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1128,'opel-mokka-a','Innovation','Ausstattungslinie','Größere Leichtmetallräder (oft 18 Zoll), Bi-Xenon-Scheinwerfer mit adaptivem Fahrlicht (AFL+), Chrom-Applikationen, getönte Scheiben hinten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1129,'opel-mokka-a','Color Edition','Ausstattungslinie','Kontrastfarbenes Dach und Außenspiegel, spezielle Leichtmetallräder, oft sportlichere Akzente im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1130,'opel-mokka-b','Mokka','Basis','Grundausstattung, oft mit 16-Zoll-Stahlrädern oder kleineren Leichtmetallrädern, grundlegende Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1131,'opel-mokka-b','Edition','Ausstattungslinie','Erweiterte Komfortmerkmale, oft mit 16- oder 17-Zoll-Leichtmetallrädern, Infotainmentsystem mit Touchscreen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1132,'opel-mokka-b','Elegance','Ausstattungslinie','Fokus auf Komfort und Design, oft mit 17-Zoll-Leichtmetallrädern, Chromapplikationen, hochwertigeren Sitzbezügen, optionalem Zweifarbdach.',NULL);
