INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1135,'opel-grandland-a','Selection','Basis','Stahlräder mit Radkappen, unlackierte Stoßfängerunterteile (je nach Baujahr), grundlegende Ausstattung.',NULL);
