INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1137,'opel-grandland-a','Business Edition','Ausstattungslinie','Ähnlich der Edition, aber mit zusätzlichen Komfort- und Konnektivitätsmerkmalen, oft für Flottenkunden optimiert.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1138,'opel-grandland-a','Elegance','Ausstattungslinie','Hochwertigere Leichtmetallräder, Chromapplikationen, oft Dach in Kontrastfarbe (optional), LED-Scheinwerfer.',NULL);
