INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1141,'opel-crossland-a','Selection','Basis','Stahlräder mit Radkappen, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1142,'opel-crossland-a','Edition','Ausstattungslinie','Leichtmetallräder (optional), lackierte Türgriffe und Außenspiegel, Dachreling (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1143,'opel-crossland-a','Innovation','Ausstattungslinie','Spezifische Leichtmetallräder, Chromapplikationen an Fensterrahmen und Front, LED-Scheinwerfer (optional), Zweifarblackierung (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1144,'opel-crossland-a','Ultimate','Ausstattungslinie','Exklusive Leichtmetallräder, Voll-LED-Scheinwerfer, Dach in Kontrastfarbe, Lederausstattung (optional), erweiterte Assistenzsysteme',NULL);
