INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1148,'opel-adam-a','Glam','Ausstattungslinie','Eleganter und luxuriöser, oft mit mehr Chrom, Panoramadach und hochwertigeren Materialien im Innenraum.','Eine der drei Haupt-Ausstattungslinien, die den Adam von Anfang an prägten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1149,'opel-adam-a','Slam','Ausstattungslinie','Sportlicher Look mit größeren Leichtmetallfelgen, Sportfahrwerk und sportlichen Akzenten im Innenraum.','Eine der drei Haupt-Ausstattungslinien, die den Adam von Anfang an prägten.');
