INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1154,'opel-karl-a','Innovation','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Nebelscheinwerfern, Infotainmentsystem, Tempomat',NULL);
