INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1161,'opel-zafira-a','Basis','Basis','Stahlfelgen, unlackierte Stoßfänger (teilweise), einfache Stoffbezüge',NULL);
