INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1191,'opel-meriva-b','Selection','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1192,'opel-meriva-b','Edition','Ausstattungslinie','Leichtmetallräder (optional), lackierte Türgriffe und Außenspiegel, Klimaanlage, Radio-CD.','Umfangreichere Komfortausstattung als Selection.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1193,'opel-meriva-b','Innovation','Ausstattungslinie','Hochwertigere Leichtmetallräder, Chromapplikationen, Nebelscheinwerfer, Teilledersitze (optional).','Top-Ausstattung mit vielen Komfort- und Designmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1194,'opel-meriva-b','Color Edition','Ausstattungslinie','Kontrastfarbenes Dach, spezielle Leichtmetallräder, sportlichere Akzente im Innenraum.','Betont sportlich-individuelles Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1195,'ford-fiesta-mk1','Popular','Basis','Sehr einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen ohne Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1196,'ford-fiesta-mk1','L','Ausstattungslinie','Etwas verbesserte Innenausstattung, oft mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1197,'ford-fiesta-mk1','Ghia','Ausstattungslinie','Luxuriösere Ausstattung mit Chromzierrat, Velourssitzen, oft mit speziellen Radkappen oder Leichtmetallfelgen (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1198,'ford-fiesta-mk1','S','Ausstattungslinie','Sportlichere Optik mit Streifen, speziellen Sitzen, Drehzahlmesser und oft breiteren Reifen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1199,'ford-fiesta-mk1','XR2','Ausstattungslinie','Top-Sportmodell mit markanten Kunststoffverbreiterungen an den Radläufen, Frontspoiler, Heckspoiler, speziellen Leichtmetallfelgen und Nebelscheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1200,'ford-fiesta-mk2','Basis','Basis','Einfache Stoßfänger, Stahlfelgen, weniger Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1201,'ford-fiesta-mk2','L','Ausstattungslinie','Leicht verbesserte Ausstattung, eventuell mit Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1202,'ford-fiesta-mk2','GL','Ausstattungslinie','Umfangreichere Ausstattung, eventuell mit besserer Polsterung und mehr Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1203,'ford-fiesta-mk2','XR2','M Performance','Sportliche Optik mit spezifischen Stoßfängern, Seitenschwellern, Leichtmetallfelgen und oft mit sportlicherer Innenausstattung.','Deutlich sportlicher als die Standardmodelle, oft mit stärkeren Motoren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1204,'ford-fiesta-mk3','Fiesta','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1205,'ford-fiesta-mk3','CLX','Ausstattungslinie','Etwas gehobenere Ausstattung, oft mit Radkappen, teilweise lackierte Stoßfänger.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1206,'ford-fiesta-mk3','Ghia','Ausstattungslinie','Top-Ausstattungslinie mit Chromakzenten, besseren Sitzbezügen, oft Leichtmetallfelgen, elektrische Fensterheber und Zentralverriegelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1207,'ford-fiesta-mk3','XR2i','Ausstattungslinie','Sportliche Variante mit spezifischen Stoßfängern, Seitenschwellern, Heckspoiler, Sportfahrwerk und Sportsitzen. Erkennbar an den ''XR2i''-Schriftzügen.','Sportliche Ausrichtung, leistungsstärkere Motoren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1208,'ford-fiesta-mk3','RS Turbo','Ausstattungslinie','Die leistungsstärkste Variante mit noch aggressiverer Optik als der XR2i, spezifischen 14-Zoll-Leichtmetallfelgen, Lufthutze auf der Motorhaube und RS-Emblemen.','Spitzenmodell in Bezug auf Leistung und Sportlichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1209,'ford-fiesta-mk3','Si','Ausstattungslinie','Sportlich angehauchte Ausstattungslinie, oft mit Sportsitzen, Leichtmetallfelgen und dezenten Spoilern. Positioniert unterhalb des XR2i.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1210,'ford-fiesta-mk4','Basis','Basis','Einfache Radkappen, unlackierte Stoßfänger, keine Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1211,'ford-fiesta-mk4','Trend','Ausstattungslinie','Leicht verbesserte Radkappen, teilweise lackierte Stoßfänger, oft mit Nebelscheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1212,'ford-fiesta-mk4','Ghia','Ausstattungslinie','Vollständig lackierte Stoßfänger, oft Leichtmetallfelgen, Chromapplikationen (z.B. am Kühlergrill), Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1213,'ford-fiesta-mk4','Sport','Ausstattungslinie','Sportliche Stoßfänger, Seitenschweller, Heckspoiler, Leichtmetallfelgen, Sportsitze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1214,'ford-fiesta-mk5','Ambiente','Basis','Einfache Ausstattung, oft mit unlackierten Stoßfängern und Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1215,'ford-fiesta-mk5','Trend','Ausstattungslinie','Zusätzlich zur Ambiente-Ausstattung oft mit lackierten Stoßfängern, elektrischen Fensterhebern vorne und Zentralverriegelung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1216,'ford-fiesta-mk5','Ghia','Ausstattungslinie','Luxuriösere Ausstattung mit Chromapplikationen, Leichtmetallfelgen, Klimaanlage und besseren Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1217,'ford-fiesta-mk5','Sport','Ausstattungslinie','Sportlichere Optik mit speziellen Stoßfängern, Seitenschwellern, Heckspoiler, Sportfahrwerk und Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1218,'ford-fiesta-mk5','ST','Echtes M-Modell','Topmodell mit aggressivem Bodykit, großen Leichtmetallfelgen, Sportfahrwerk, doppelter Auspuffanlage und Recaro-Sportsitzen.','Deutlich leistungsstärkerer Motor (2.0 Duratec mit 150 PS) und spezifische Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1219,'ford-fiesta-mk6','Ambiente','Basis','Einfache Ausstattung, oft mit unlackierten Stoßfängern und Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1220,'ford-fiesta-mk6','Trend','Ausstattungslinie','Lackierte Stoßfänger, oft mit Radkappen oder optionalen Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1221,'ford-fiesta-mk6','Ghia','Ausstattungslinie','Chromapplikationen, Nebelscheinwerfer, oft Leichtmetallfelgen, hochwertigere Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1222,'ford-fiesta-mk6','Sport','Ausstattungslinie','Sportlichere Front- und Heckschürzen, Seitenschweller, Heckspoiler, Sportfahrwerk, spezielle Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1223,'ford-fiesta-mk6','ST','Echtes M-Modell','Aggressivere Frontschürze, Wabengrill, 17-Zoll-Leichtmetallfelgen, Doppelendrohr, Recaro-Sportsitze, Sportfahrwerk.','Topmodell mit leistungsstärkstem Motor (150 PS) und spezifischer sportlicher Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1224,'ford-fiesta-mk7','Ambiente','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Türgriffen/Spiegeln (je nach Baujahr/Markt).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1225,'ford-fiesta-mk7','Trend','Ausstattungslinie','Etwas umfangreichere Ausstattung als Ambiente, oft mit lackierten Außenspiegeln und Türgriffen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1226,'ford-fiesta-mk7','Titanium','Ausstattungslinie','Hochwertigere Ausstattung, oft mit Leichtmetallfelgen, Chrom-Applikationen, Nebelscheinwerfern und LED-Tagfahrlicht (nach Facelift).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1227,'ford-fiesta-mk7','Sport','Ausstattungslinie','Sportlichere Optik mit speziellen Stoßfängern, Seitenschwellern, Heckspoiler und Sportfahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1228,'ford-fiesta-mk7','ST-Line','Ausstattungslinie','Nach Facelift eingeführt, sportliche Optik ähnlich dem ST, aber ohne dessen Motorisierung. Mit speziellem Kühlergrill, Stoßfängern und Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1229,'ford-fiesta-mk7','ST','Echtes M-Modell','Eigenständige sportliche Front- und Heckschürzen, großer Heckspoiler, spezielle Leichtmetallfelgen, Doppelrohr-Auspuffanlage, Recaro-Sportsitze im Innenraum.','Deutlich leistungsstärkerer Motor (1.6 EcoBoost mit 182 PS, später 200 PS im ST200), Sportfahrwerk, größere Bremsen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1230,'ford-focus-mk1','Ambiente','Basis','Einfachere Radkappen, weniger Chrom-Applikationen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1231,'ford-focus-mk1','Trend','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, bessere Stoffpolsterung, elektrische Fensterheber vorne.','Umfangreichere Ausstattung als Ambiente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1232,'ford-focus-mk1','Ghia','Ausstattungslinie','Chrom-Applikationen, Leder-Stoff-Polsterung, Klimaanlage, bessere Audioanlage.','Höchste Komfort-Ausstattungslinie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1233,'ford-focus-mk1','ST170','M Performance','Sportfahrwerk, größere Leichtmetallfelgen, Sportsitze, spezifische Karosserie-Anbauteile, Doppelrohr-Auspuff.','Sportliche Variante mit leistungsgesteigertem Motor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1234,'ford-focus-mk2','Ambiente','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffbezüge',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1235,'ford-focus-mk2','Trend','Ausstattungslinie','Lackierte Außenspiegel und Türgriffe, oft mit Radkappen oder optionalen Leichtmetallfelgen, verbesserte Innenraummaterialien',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1236,'ford-focus-mk2','Ghia','Ausstattungslinie','Chromapplikationen (Kühlergrill, Fensterrahmen), Leichtmetallfelgen, Nebelscheinwerfer, oft Holz- oder Aluminium-Dekor im Innenraum',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1237,'ford-focus-mk2','Titanium','Ausstattungslinie','Sportlichere Leichtmetallfelgen, spezielle Kühlergrill-Optik, oft getönte Scheiben, Aluminium-Dekor im Innenraum, Sportsitze',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1238,'ford-focus-mk2','Sport','Ausstattungslinie','Sportfahrwerk, spezielle Leichtmetallfelgen, Sportsitze, oft Spoilerpaket',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1239,'ford-focus-mk2','ST','Echtes M-Modell','Aggressiveres Bodykit mit größeren Lufteinlässen, zentraler Doppelauspuff, 18-Zoll-Leichtmetallfelgen, Recaro-Sportsitze, markante Lackfarben (z.B. Electric Orange)','Deutlich leistungsstärkerer Motor (2.5L Turbo), Sportfahrwerk, größere Bremsen, spezifische ST-Logos und Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1240,'ford-focus-mk2','RS','Echtes M-Modell','Extrem breite Kotflügel, großer Heckflügel, massive Frontschürze mit großen Lufteinlässen, 19-Zoll-Leichtmetallfelgen, zentraler Auspuff, Recaro-Schalensitze','Das Topmodell der Baureihe mit nochmals deutlich gesteigerter Leistung (2.5L Turbo mit 305 PS), RevoKnuckle-Vorderradaufhängung zur Reduzierung von Antriebseinflüssen, Sperrdifferenzial und spezifischer RS-Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1241,'ford-focus-mk3','Ambiente','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1242,'ford-focus-mk3','Trend','Ausstattungslinie','Leichtmetallräder (optional), lackierte Türgriffe und Außenspiegel, Klimaanlage, Radio/CD mit Ford SYNC (später).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1243,'ford-focus-mk3','Business','Ausstattungslinie','Basierend auf Trend, oft mit Navigationssystem und Parksensoren.','Speziell für Flottenkunden und Geschäftsfahrzeuge konzipiert, mit Fokus auf Komfort- und Navigationsfunktionen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1244,'ford-focus-mk3','Titanium','Ausstattungslinie','16- oder 17-Zoll-Leichtmetallräder, Chromzierleisten, LED-Tagfahrlicht (nach Facelift), Sportsitze, Klimaautomatik, Ford Power-Startfunktion.','Höhere Komfort- und Designausstattung mit vielen Extras serienmäßig.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1245,'ford-focus-mk3','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezielle Leichtmetallräder, sportliche Stoßfänger (oft in Kombination mit Titanium oder Trend).','Fokus auf sportlicheres Fahrverhalten und Optik, oft als Paket oder eigenständige Linie erhältlich.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1246,'ford-focus-mk3','ST-Line','Ausstattungslinie','Sportliches Bodykit (Stoßfänger, Seitenschweller), Sportfahrwerk, spezielle Leichtmetallräder, Sportsitze, schwarzer Dachhimmel.','Nach Facelift eingeführt, bietet sportliche Optik und Fahrwerkseinstellungen ohne die Leistungssteigerung der echten ST-Modelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1247,'ford-focus-mk3','Vignale','Ausstattungslinie','Exklusive Lackierungen, spezielle 17- oder 18-Zoll-Leichtmetallräder, Chrom-Applikationen, Lederausstattung, erweiterte Komfortausstattung.','Ab 2016 als Top-Ausstattungslinie mit Premium-Anspruch, hochwertigeren Materialien und exklusiven Services.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1248,'ford-focus-mk3','ST','M Performance','Aggressiveres Bodykit, zentraler Doppelauspuff, 18-Zoll-Leichtmetallräder, Recaro-Sportsitze, Sportfahrwerk, spezielle Lackierungen (z.B. Tangerine Scream).','Sportmodell mit leistungsstärkerem Motor (2.0 EcoBoost, 250 PS), strafferem Fahrwerk und direkterer Lenkung. Deutlich von den zivilen Modellen abgegrenzt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1249,'ford-focus-mk3','RS','Echtes M-Modell','Extrem aggressives Bodykit, großer Heckspoiler, breitere Kotflügel, 19-Zoll-Leichtmetallräder, Brembo-Bremsanlage, Recaro-Schalensitze, spezielle Lackierungen (z.B. Nitrous-Blau).','Das Top-Performance-Modell mit Allradantrieb, 2.3 EcoBoost Motor (350 PS), Drift-Modus und Rennstrecken-tauglicher Abstimmung. Eine eigenständige Entwicklung mit maximaler Performance.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1250,'ford-focus-mk4','Trend','Basis','Einfache Ausstattung, meist mit kleineren Stahlfelgen oder Basis-Leichtmetallfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Infotainment-Systeme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1251,'ford-focus-mk4','Cool & Connect','Ausstattungslinie','Erweiterte Konnektivitätsfunktionen, oft mit Touchscreen-Radio und Klimaanlage. Äußerlich ähnlich dem Trend, aber mit besseren Infotainment-Optionen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1252,'ford-focus-mk4','Titanium','Ausstattungslinie','Hochwertigere Materialien im Innenraum, Chrom-Applikationen an der Karosserie, größere Leichtmetallfelgen, LED-Tagfahrlicht, verbesserte Komfortausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1253,'ford-focus-mk4','ST-Line','Ausstattungslinie','Sportlichere Optik mit speziellen Stoßfängern, Seitenschwellern, Heckspoiler, Sportfahrwerk, dunklerem Kühlergrill, ST-Line-Emblemen und größeren Leichtmetallfelgen. Innen Sportsitze und Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1254,'ford-focus-mk4','Active','Ausstattungslinie','Crossover-Optik mit erhöhter Bodenfreiheit, robusten Kunststoffbeplankungen an Radläufen und Schwellern, spezifischen Stoßfängern mit Unterfahrschutz-Optik und Dachreling. Oft mit speziellen Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1255,'ford-focus-mk4','Vignale','Ausstattungslinie','Luxuriöse Ausstattung mit exklusiven Designelementen, wie speziellem Kühlergrill, Chrom-Details, größeren Leichtmetallfelgen, Lederausstattung und erweiterten Komfortfunktionen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1256,'ford-focus-mk4','ST','Echtes M-Modell','Sehr sportliche Optik mit aggressiveren Stoßfängern, großem Heckspoiler, zentralem Doppelauspuff, großen Leichtmetallfelgen, roten Bremssätteln und ST-Emblemen. Innen Recaro-Sportsitze und spezifisches Sportlenkrad.','Deutlich leistungsstärkerer Motor, Sportfahrwerk, Hochleistungsbremsanlage, spezifische Fahrprogramme.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1257,'ford-kuga-mk1','Trend','Basis','Stahlräder mit Radzierblenden, unlackierte Stoßfängerunterteile und Seitenschweller (oft in Schwarz), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1258,'ford-kuga-mk1','Titanium','Ausstattungslinie','Leichtmetallräder, verchromte Zierleisten (z.B. am Kühlergrill), lackierte Stoßfängerunterteile und Seitenschweller in Wagenfarbe, Dachreling, Nebelscheinwerfer mit Chromumrandung, oft getönte Scheiben hinten.','Umfangreichere Serienausstattung als Trend, z.B. Klimaautomatik, Tempomat, Sportsitze.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1259,'ford-kuga-mk2','Trend','Basis','Grundausstattung, oft mit 17-Zoll-Stahlfelgen oder einfachen Leichtmetallfelgen, unlackierte Stoßfängerunterteile (je nach Baujahr/Markt), grundlegende Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1260,'ford-kuga-mk2','Titanium','Ausstattungslinie','Umfangreichere Ausstattung, oft mit 17- oder 18-Zoll-Leichtmetallfelgen, Chrom-Applikationen an Fensterrahmen und Kühlergrill, Nebelscheinwerfer, Teilleder- oder hochwertige Stoffpolsterung.','Bietet mehr Komfort- und Designmerkmale als der Trend, wie Klimaautomatik, Tempomat und verbesserte Infotainment-Systeme.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1261,'ford-kuga-mk2','Titanium S','Ausstattungslinie','Sportlichere Optik basierend auf Titanium, oft mit speziellen 18- oder 19-Zoll-Leichtmetallfelgen, Sportfahrwerk, Dachspoiler, sportlicheren Stoßfängern und Seitenschwellern.','Fokus auf sportliches Design und Fahrverhalten, über dem normalen Titanium angesiedelt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1262,'ford-kuga-mk2','ST-Line','Ausstattungslinie','Eingeführt mit dem Facelift. Sehr sportliche Optik mit spezifischen 18- oder 19-Zoll-Leichtmetallfelgen, schwarzem Kühlergrill, sportlichen Stoßfängern, Seitenschwellern, Dachspoiler, Sportfahrwerk und ST-Line-Emblemen. Innen mit Sportsitzen und roten Ziernähten.','Betont die sportliche Seite des Kuga, ohne ein echtes M-Modell zu sein. Positioniert über Titanium.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1263,'ford-kuga-mk2','Vignale','Ausstattungslinie','Luxuriöseste Ausstattungslinie (eingeführt mit dem Facelift). Exklusive 18- oder 19-Zoll-Leichtmetallfelgen, spezielle Chrom-Details, Vignale-Kühlergrill, hochwertige Lackierungen, Vollleder-Ausstattung im Innenraum mit gesteppten Sitzen und erweiterten Komfortfunktionen.','Premium-Ausstattung mit Fokus auf Luxus, Komfort und exklusiven Serviceleistungen. Die Top-Ausstattungslinie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1264,'ford-kuga-mk3','Titanium','Ausstattungslinie','Chrom-Applikationen an Fensterrahmen und Kühlergrill, 17-Zoll-Leichtmetallräder, LED-Scheinwerfer, Dachreling',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1265,'ford-kuga-mk3','ST-Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, schwarze Designelemente (Kühlergrill, Dachreling), 18- oder 19-Zoll-Leichtmetallräder, Sportfahrwerk, ST-Line-Logos',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1266,'ford-kuga-mk3','Vignale','Ausstattungslinie','Exklusive Chrom-Details, spezielle 18- oder 19-Zoll-Leichtmetallräder, Vignale-Embleme, Premium-Lackierungen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1267,'ford-kuga-mk3','Active','Ausstattungslinie','Robuste Offroad-Optik mit spezifischen Stoßfängern, Radhausverkleidungen und Seitenschwellern in Schwarz, erhöhte Bodenfreiheit, 17- oder 18-Zoll-Leichtmetallräder, Active-Logos (eingeführt mit Facelift)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1268,'ford-puma-mk1','Puma','Basis','Standardausstattung, oft mit 15-Zoll-Stahlfelgen oder einfachen Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1269,'ford-puma-mk1','Puma Sport','Ausstattungslinie','Sportlichere Ausstattung, oft mit 15- oder 16-Zoll-Leichtmetallfelgen, Sportsitzen und spezifischen Interieur-Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1270,'ford-puma-mk1','Puma Thunder','Ausstattungslinie','Sondermodell mit spezifischen Lackierungen (z.B. Moondust Silver), 15-Zoll-Leichtmetallfelgen im 6-Speichen-Design, Klimaanlage und CD-Radio.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1271,'ford-puma-mk1','Puma Black','Ausstattungslinie','Sondermodell, ausschließlich in Panther Black Metallic lackiert, mit 15-Zoll-Leichtmetallfelgen, Klimaanlage und beheizbarer Frontscheibe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1272,'ford-puma-mk1','Puma Millennium','Ausstattungslinie','Limitiertes Sondermodell (1000 Stück), ausschließlich in Racing Yellow lackiert, mit 15-Zoll-Leichtmetallfelgen, Klimaanlage, beheizbarer Frontscheibe und Recaro-Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1273,'ford-puma-mk1','Puma Racing','Echtes M-Modell','Limitiertes Sondermodell (500 Stück), ausschließlich in Imperial Blue lackiert, mit breiteren Kotflügeln, 17-Zoll-Speedline-Leichtmetallfelgen, größeren Bremsen, Recaro-Sportsitzen und einem überarbeiteten Fahrwerk. Deutlich aggressiveres Erscheinungsbild.','Entwickelt von Ford Racing, mit umfangreichen technischen Modifikationen (Motor, Fahrwerk, Bremsen, Karosserie).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1274,'ford-puma-mk2','Titanium','Ausstattungslinie','Chrom-Applikationen an Kühlergrill und Fensterrahmen, 17-Zoll-Leichtmetallräder, Nebelscheinwerfer mit Abbiegelicht.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1275,'ford-puma-mk2','ST-Line','Ausstattungslinie','Sportlichere Front- und Heckschürze, schwarze Akzente, 17- oder 18-Zoll-Leichtmetallräder, Sportfahrwerk, Dachspoiler.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1276,'ford-puma-mk2','ST-Line X','Ausstattungslinie','Erweitert die ST-Line mit zusätzlichen Designelementen wie größeren Rädern (oft 18 oder 19 Zoll), dunkleren Scheiben hinten und weiteren Interieur-Upgrades.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1277,'ford-puma-mk2','Vignale','Ausstattungslinie','Exklusive Chrom-Details, spezielle 18-Zoll-Leichtmetallräder, Lederausstattung, Premium-Lackierungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1278,'ford-puma-mk2','ST','Echtes M-Modell','Aggressivere Frontschürze, großer Heckspoiler, Doppelrohr-Auspuffanlage, 19-Zoll-Leichtmetallräder, Recaro-Sportsitze, ST-spezifische Lackierungen.','Das ST-Modell ist die sportliche Top-Variante mit einem leistungsstärkeren Motor, einem strafferen Fahrwerk und spezifischen Performance-Merkmalen, die es deutlich von den anderen Ausstattungslinien abgrenzen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1279,'ford-mondeo-mk1','CL','Basis','Einfachere Stoßfänger, oft schwarze Türgriffe und Spiegel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1280,'ford-mondeo-mk1','GLX','Ausstattungslinie','Lackierte Stoßfänger, oft mit Chromleisten, elektrische Fensterheber vorne.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1281,'ford-mondeo-mk1','Ghia','Ausstattungslinie','Höherwertige Materialien im Innenraum, oft mit Leichtmetallfelgen, Nebelscheinwerfern, Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1282,'ford-mondeo-mk1','ST200','M Performance','Sportfahrwerk, spezifische Leichtmetallfelgen, Schalensitze, Heckspoiler, sportliche Frontschürze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1283,'ford-mondeo-mk2','CLX','Basis','Einfache Radkappen, unlackierte Stoßfänger (teilweise), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1284,'ford-mondeo-mk2','GLX','Ausstattungslinie','Bessere Radkappen, teilweise lackierte Stoßfänger, elektrische Fensterheber vorne.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1285,'ford-mondeo-mk2','Ghia','Ausstattungslinie','Leichtmetallfelgen, verchromte Zierleisten, Nebelscheinwerfer, hochwertige Stoff- oder Lederausstattung, Holzdekor im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1286,'ford-mondeo-mk2','Trend','Ausstattungslinie','Sportlichere Optik mit speziellen Leichtmetallfelgen, Sportsitze, oft in Verbindung mit stärkeren Motoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1287,'ford-mondeo-mk2','ST24','Ausstattungslinie','Sportfahrwerk, 16-Zoll-Leichtmetallfelgen, spezielle Front- und Heckschürzen, Sportsitze, V6-Motor.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1288,'ford-mondeo-mk2','ST200','Ausstattungslinie','Exklusives Bodykit, 17-Zoll-Leichtmetallfelgen, Recaro-Sportsitze, spezielle Lackierungen (z.B. Imperial Blue), leistungsgesteigerter V6-Motor.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1289,'ford-mondeo-mk3','Ambiente','Basis','Einfachere Stoßfänger, Stahlfelgen mit Radkappen.','Grundlegende Ausstattung, weniger Komfortmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1290,'ford-mondeo-mk3','Trend','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, lackierte Türgriffe.','Erweiterte Komfort- und Sicherheitsausstattung gegenüber Ambiente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1291,'ford-mondeo-mk3','Ghia','Ausstattungslinie','Chromapplikationen, Ledersitze (optional), bessere Materialien im Innenraum.','Höchste Komfort- und Luxusausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1292,'ford-mondeo-mk3','ST220','M Performance','Sportliche Stoßfänger, Seitenschweller, größere Leichtmetallfelgen, Doppelrohr-Auspuffanlage, Sportsitze.','Sportliche Top-Version mit leistungsstärkerem Motor und spezifischem Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1293,'ford-mondeo-mk4','Ambiente','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1294,'ford-mondeo-mk4','Trend','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer, verbesserte Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1295,'ford-mondeo-mk4','Ghia','Ausstattungslinie','Chromapplikationen (Kühlergrill, Fensterrahmen), hochwertige Leichtmetallfelgen, Teilleder- oder Velourspolsterung, Holz- oder Aluminium-Dekor im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1296,'ford-mondeo-mk4','Titanium','Ausstattungslinie','Sportlichere Leichtmetallfelgen, sportlichere Frontschürze (teilweise), Aluminium-Dekor im Innenraum, Sportsitze (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1297,'ford-mondeo-mk4','Titanium S','Ausstattungslinie','Sportfahrwerk, spezifische 18-Zoll-Leichtmetallfelgen, sportliches Bodykit (Front- und Heckschürze, Seitenschweller), Sportsitze mit roten Nähten, dunkle Scheinwerferhintergründe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1298,'ford-mustang-first-generation','Standard','Basis','Grundlegende Ausstattung, oft mit kleineren Motoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1299,'ford-mustang-first-generation','GT (Gran Turismo)','Ausstattungslinie','Sportlichere Optik, oft mit stärkeren Motoren, speziellen Emblemen und Fahrwerksverbesserungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1300,'ford-mustang-first-generation','Mach 1','Ausstattungslinie','Sportliches Sondermodell mit speziellen Styling-Elementen wie Motorhauben-Scoops, Streifen und oft leistungsstärkeren Motoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1301,'ford-mustang-first-generation','Boss 302 / Boss 429','M Performance','Homologationsmodelle für den Rennsport mit stark modifizierten Motoren und Fahrwerken, speziellen Karosserieanbauteilen und Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1302,'ford-mustang-first-generation','Shelby GT350 / GT500','Echtes M-Modell','Von Shelby American getunte Versionen mit signifikanten Leistungssteigerungen, Fahrwerksmodifikationen, aggressiver Optik und speziellen Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1303,'ford-mustang-second-generation','Base','Basis','Einfache Ausstattung, oft mit kleineren Motoren und weniger Chromzierrat.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1304,'ford-mustang-second-generation','Ghia','Ausstattungslinie','Luxuriöser orientierte Ausstattung mit Vinyl-Dach, zusätzlichen Chromakzenten und gehobener Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1305,'ford-mustang-second-generation','Mach 1','Ausstattungslinie','Sportlichere Optik mit speziellen Felgen, Sportfahrwerk, optionalen Streifen und Spoilern. War nur als Hatchback erhältlich.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1306,'ford-mustang-second-generation','Cobra II','Ausstattungslinie','Ab 1976 erhältlich, basierend auf dem Mach 1. Auffällige Rennstreifen, Cobra-Embleme, Front- und Heckspoiler, Lufthutze auf der Motorhaube (oft nur Attrappe).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1307,'ford-mustang-second-generation','King Cobra','Ausstattungslinie','Nur 1978 erhältlich. Aggressivere Optik mit einem großen Cobra-Aufkleber auf der Motorhaube, speziellen Felgen, Spoilern und einem Frontschürzen-Design.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1308,'ford-mustang-third-generation','L','Basis','Einfache Ausstattung, oft mit kleineren Motoren und weniger Chromzierrat.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1309,'ford-mustang-third-generation','GL','Ausstattungslinie','Etwas gehobenere Ausstattung als das L-Modell, oft mit mehr Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1310,'ford-mustang-third-generation','GLX','Ausstattungslinie','Luxuriösere Ausstattung mit zusätzlichen Komfort- und Ästhetikmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1311,'ford-mustang-third-generation','GT','Ausstattungslinie','Sportlichere Optik mit speziellen Felgen, Spoilern und oft einem aggressiveren Bodykit. Verfügbar mit leistungsstärkeren Motoren (insbesondere dem 5.0L V8).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1312,'ford-mustang-third-generation','LX','Ausstattungslinie','Oft als ''Sleeper'' bekannt, da es die leistungsstärkeren Motoren (wie den 5.0L V8) in einem optisch dezenteren Paket ohne die aggressiven GT-Anbauteile bot.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1313,'ford-mustang-third-generation','SVO','Ausstattungslinie','Einzigartige Frontpartie mit bündigen Scheinwerfern (vor dem Facelift), speziellen Felgen und einem Heckspoiler. Fokus auf Performance mit einem turbogeladenen Vierzylinder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1314,'ford-mustang-third-generation','Cobra','Echtes M-Modell','Spezielle Cobra-Embleme, einzigartige Felgen, oft mit einem aggressiveren Bodykit und speziellen Lackierungen. Nur in den letzten Baujahren (1993) als ''Cobra'' und ''Cobra R'' erhältlich.','Die Cobra-Modelle von 1993 waren die leistungsstärksten und exklusivsten Varianten der Fox Body Generation, entwickelt von Fords Special Vehicle Team (SVT), mit signifikanten Leistungs- und Fahrwerksverbesserungen gegenüber den GT-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1315,'ford-mustang-fourth-generation','Base','Basis','Einfache Ausstattung, oft mit kleineren Rädern und weniger Chrom-Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1316,'ford-mustang-fourth-generation','GT','Ausstattungslinie','Sportlichere Optik mit speziellen Felgen, GT-Emblemen und oft einem Heckspoiler. Verfügte über den V8-Motor.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1317,'ford-mustang-fourth-generation','Cobra','Echtes M-Modell','Aggressivere Frontschürze, spezielle Cobra-Embleme, einzigartige Felgen und oft eine andere Motorhaube mit Lufteinlässen. Deutlich leistungsstärker als der GT.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1318,'ford-mustang-fourth-generation','Mach 1','Ausstattungslinie','Eingeführt im Modelljahr 2003. Retro-Designelemente wie eine ''Shaker''-Motorhaube, spezielle 17-Zoll-Felgen, mattschwarze Streifen und ein Heckspoiler. Verfügte über einen leistungsstärkeren V8-Motor als der GT.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1319,'ford-mustang-fifth-generation','V6','Basis','Kleinere Räder, oft ohne Nebelscheinwerfer oder mit einfacheren Felgen. Nach dem Facelift (2010) mit eigenständiger Frontschürze.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1320,'ford-mustang-fifth-generation','GT','Ausstattungslinie','Größere Räder, Nebelscheinwerfer in der Frontschürze, GT-Embleme, oft mit Heckspoiler. Nach dem Facelift (2010) mit Powerdome-Motorhaube und spezifischer Front.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1321,'ford-mustang-fifth-generation','Shelby GT500','Echtes M-Modell','Aggressivere Frontschürze mit großen Lufteinlässen, Cobra-Embleme statt Pony, breitere Reifen, spezielle Felgen, markanter Heckspoiler, oft mit Rennstreifen. Nach dem Facelift (2010) noch aggressiveres Design mit größeren Kühleröffnungen.','Topmodell mit Kompressor-V8-Motor, deutlich leistungsstärker und sportlicher als der GT.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1322,'ford-mustang-fifth-generation','Boss 302','M Performance','Spezifische Frontschürze, seitliche C-Streifen, Heckspoiler, 19-Zoll-Felgen, oft in auffälligen Farben wie ''Grabber Blue'' oder ''Competition Orange''.','Limitierte, rennstreckenorientierte Variante des GT mit leistungsgesteigertem 5.0L Coyote V8, strafferem Fahrwerk und spezieller Abgasanlage.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1323,'ford-mustang-sixth-generation','EcoBoost','Basis','Standard-Frontschürze, kleinere Felgen, einzelne Auspuffanlage (bis Facelift), Doppelendrohre (ab Facelift).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1324,'ford-mustang-sixth-generation','GT','Ausstattungslinie','Aggressivere Frontschürze, größere Felgen, Doppelendrohre (bis Facelift), vier Endrohre (ab Facelift), GT-Embleme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1325,'ford-mustang-sixth-generation','Bullitt','Ausstattungslinie','Exklusive Lackierung Dark Highland Green, schwarze Torq Thrust-Felgen, keine Pony- oder GT-Embleme, Bullitt-Emblem am Heck, rote Bremssättel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1326,'ford-mustang-sixth-generation','Mach 1','Ausstattungslinie','Einzigartige Frontschürze mit größeren Lufteinlässen, spezielle 19-Zoll-Felgen, Mach 1-Streifen und -Embleme, vier Endrohre.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1327,'ford-mustang-sixth-generation','Shelby GT350','Echtes M-Modell','Deutlich aggressivere Frontpartie mit großem Kühlergrill und Lufteinlässen, breitere Kotflügel, spezielle Felgen, großer Heckspoiler, Shelby-Embleme, vier Endrohre.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1328,'ford-mustang-sixth-generation','Shelby GT500','Echtes M-Modell','Extrem aggressive Front mit riesigem Kühlergrill und Lufteinlässen, breitere Karosserie, aerodynamische Anbauteile, großer Heckflügel, Shelby-Embleme, vier Endrohre.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1329,'ford-mustang-mach-e-first-generation','Select','Basis','Standard-LED-Scheinwerfer, 18-Zoll-Leichtmetallräder, schwarze Akzente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1330,'ford-mustang-mach-e-first-generation','Premium','Ausstattungslinie','Matrix-LED-Scheinwerfer, 19-Zoll-Leichtmetallräder, lackierte Radhausverkleidungen, rote Bremssättel (bei AWD).','Umfangreichere Komfort- und Technikausstattung, wie z.B. B&O Soundsystem, 360-Grad-Kamera.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1331,'ford-mustang-mach-e-first-generation','California Route 1','Ausstattungslinie','Spezifische 18-Zoll-Räder mit Aero-Abdeckungen, schwarze Außenspiegelkappen, spezielle Embleme.','Fokus auf maximale Reichweite, oft nur mit Heckantrieb und großer Batterie verfügbar.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1332,'ford-mustang-mach-e-first-generation','GT','Echtes M-Modell','Einzigartiger beleuchteter Kühlergrill, 20-Zoll-Leichtmetallräder, rote Bremssättel, GT-spezifische Front- und Heckschürzen, Sportsitze.','Leistungsstärkste Variante mit Allradantrieb, sportlicherer Fahrwerksabstimmung und exklusiven Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1333,'ford-ecosport-first-generation','Ambiente','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (marktabhängig), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1334,'ford-ecosport-first-generation','Trend','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, Dachreling, Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1335,'ford-ecosport-first-generation','Titanium','Ausstattungslinie','Größere Leichtmetallfelgen, Chrom-Applikationen an Kühlergrill und Fenstern, Teilledersitze, Klimaautomatik, Keyless-Go.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1336,'ford-ecosport-first-generation','ST-Line','Ausstattungslinie','Sportlichere Stoßfänger, Seitenschweller, spezielle Leichtmetallfelgen, schwarzer Kühlergrill, Sportfahrwerk, rote Ziernähte im Innenraum, Sportlenkrad (eingeführt mit dem Facelift 2017).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1337,'ford-ecosport-second-generation','Ambiente','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Türgriffen/Spiegeln bei frühen Modellen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1338,'ford-ecosport-second-generation','Trend','Ausstattungslinie','Bietet grundlegende Komfortmerkmale, oft mit Leichtmetallfelgen und lackierten Anbauteilen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1339,'ford-ecosport-second-generation','Titanium','Ausstattungslinie','Umfassendere Ausstattung mit Chromakzenten, größeren Leichtmetallfelgen, Nebelscheinwerfern und oft Dachreling.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1340,'ford-ecosport-second-generation','ST-Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, dunklen Akzenten, Sportfahrwerk und ST-Line-Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1341,'ford-ecosport-second-generation','Active','Ausstattungslinie','Robusterer Offroad-Look mit spezifischen Stoßfängern, Radhausverkleidungen, erhöhter Bodenfreiheit und Active-Emblemen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1342,'ford-galaxy-first-generation','Ambiente','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Stoßfängern (je nach Baujahr).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1343,'ford-galaxy-first-generation','Trend','Ausstattungslinie','Bietet mehr Komfortmerkmale als die Basis, oft mit lackierten Stoßfängern und Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1344,'ford-galaxy-first-generation','Ghia','Ausstattungslinie','Top-Ausstattungslinie mit Chromapplikationen, Leichtmetallfelgen, Nebelscheinwerfern und oft getönten Scheiben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1345,'ford-galaxy-first-generation','Business','Ausstattungslinie','Spezielle Ausstattung für Flottenkunden, oft mit praktischen Features.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1346,'ford-galaxy-second-generation','Ambiente','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1347,'ford-galaxy-second-generation','Trend','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, verbesserte Stoffpolsterung, Klimaanlage (manuell).','Bietet mehr Komfort- und Designmerkmale als die Basisversion Ambiente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1348,'ford-galaxy-second-generation','Ghia','Ausstattungslinie','Hochwertigere Leichtmetallfelgen, Chromapplikationen außen, Nebelscheinwerfer, Klimaautomatik, Tempomat, Lederlenkrad, verbesserte Audioanlage.','Fokus auf Komfort und gehobene Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1349,'ford-galaxy-second-generation','Titanium','Ausstattungslinie','Sportlichere Leichtmetallfelgen, sportlichere Frontschürze (teilweise), getönte Scheiben hinten, Sportsitze, Keyless-Go, erweiterte Konnektivität.','Fokus auf Sportlichkeit und moderne Technologie, oft parallel oder als Ersatz für Ghia angeboten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1350,'skoda-fabia-erste-generation','Classic','Basis','Einfache Radkappen, unlackierte Türgriffe und Außenspiegel (oft), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1351,'skoda-fabia-erste-generation','Comfort','Ausstattungslinie','Lackierte Stoßfänger, oft elektrische Fensterheber vorne, bessere Sitzbezüge.','Bietet mehr Komfort- und Sicherheitsmerkmale als ''Classic''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1352,'skoda-fabia-erste-generation','Ambiente','Ausstattungslinie','Leichtmetallfelgen optional, Nebelscheinwerfer, bessere Innenraummaterialien, oft Klimaanlage.','Positioniert über ''Comfort'' mit zusätzlichen Komfort- und Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1353,'skoda-fabia-erste-generation','Elegance','Ausstattungslinie','Hochwertigere Sitzbezüge, oft Klimaautomatik, Leichtmetallfelgen, Chromapplikationen im Innenraum.','Die Top-Ausstattungslinie mit umfassenderer Ausstattung und gehobener Anmutung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1354,'skoda-fabia-erste-generation','RS','Echtes M-Modell','Sportliche Front- und Heckschürzen, 16-Zoll-Leichtmetallfelgen, Heckspoiler, Sportsitze, RS-Logos.','Das sportliche Topmodell mit stärkerem Motor (1.9 TDI PD 96 kW) und strafferem Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1355,'skoda-fabia-zweite-generation','Classic','Basis','Einfache Radzierblenden, unlackierte Türgriffe und Außenspiegel (anfangs), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1356,'skoda-fabia-zweite-generation','Ambiente','Ausstattungslinie','Lackierte Außenspiegel und Türgriffe, oft Leichtmetallfelgen optional, bessere Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1357,'skoda-fabia-zweite-generation','Elegance','Ausstattungslinie','Hochwertigere Polsterstoffe, serienmäßige Leichtmetallfelgen, Nebelscheinwerfer, Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1358,'skoda-fabia-zweite-generation','Sport','Ausstattungslinie','Sportlichere Stoßfänger, spezielle Leichtmetallfelgen, Sportsitze, Sportfahrwerk (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1359,'skoda-fabia-zweite-generation','Monte Carlo','Ausstattungslinie','Schwarzes Dach, schwarze Außenspiegel, schwarze Leichtmetallfelgen, schwarzer Kühlergrill, sportliche Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1360,'skoda-fabia-zweite-generation','RS','Echtes M-Modell','Eigenständige Front- und Heckschürzen, Doppelendrohr, größere Leichtmetallfelgen, rote Bremssättel, RS-Logos, Sportsitze.','Topmodell mit leistungsstarkem Motor (1.4 TSI mit 180 PS), Sportfahrwerk und spezifischer Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1361,'skoda-fabia-dritte-generation','Active','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Türgriffen/Spiegelkappen in den frühesten Versionen. Weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1362,'skoda-fabia-dritte-generation','Ambition','Ausstattungslinie','Umfangreichere Ausstattung als Active, oft mit Leichtmetallfelgen, Nebelscheinwerfern und lackierten Anbauteilen. Teilweise Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1363,'skoda-fabia-dritte-generation','Style','Ausstattungslinie','Top-Ausstattungslinie mit hochwertigeren Materialien, größeren Leichtmetallfelgen, Chromzierleisten, oft mit LED-Tagfahrlicht (vor Facelift) oder Voll-LED-Scheinwerfern (nach Facelift).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1364,'skoda-fabia-dritte-generation','Monte Carlo','Ausstattungslinie','Sportlich orientierte Ausstattung mit schwarzen Designelementen (Dach, Spiegelkappen, Kühlergrill, Leichtmetallfelgen), Sportfahrwerk und Sportsitzen. Oft in auffälligen Farben erhältlich.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1365,'skoda-fabia-dritte-generation','Cool Plus','Ausstattungslinie','Sondermodell, oft mit Klimaanlage und Radio als Kernausstattung, optisch meist an Ambition angelehnt.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1366,'skoda-octavia-erste-generation','Classic','Basis','Einfachere Stoßfänger, oft ohne Nebelscheinwerfer, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1367,'skoda-octavia-erste-generation','Ambiente','Ausstattungslinie','Leicht verbesserte Stoßfänger, oft mit Nebelscheinwerfern, Alufelgen möglich.','Umfangreichere Komfortausstattung als Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1368,'skoda-octavia-erste-generation','Elegance','Ausstattungslinie','Verchromte Zierleisten, bessere Alufelgen, oft mit zusätzlichen Komfortmerkmalen.','Höchste Ausstattungslinie mit Fokus auf Komfort und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1369,'skoda-octavia-erste-generation','RS','M Performance','Sportlicheres Fahrwerk, größere Alufelgen, spezifische Front- und Heckschürzen, Sportsitze, Doppelrohr-Auspuff.','Sportmodell mit leistungsstärkeren Motoren und dynamischer Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1370,'skoda-octavia-zweite-generation','Classic','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Türgriffen/Spiegeln in den frühesten Modellen. Weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1371,'skoda-octavia-zweite-generation','Ambiente','Ausstattungslinie','Etwas gehobenere Ausstattung, oft mit lackierten Türgriffen und Spiegeln, teilweise Leichtmetallfelgen. Innenraum mit besseren Stoffen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1372,'skoda-octavia-zweite-generation','Elegance','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Leichtmetallfelgen, Chromzierleisten, Nebelscheinwerfern. Im Innenraum hochwertigere Materialien und Komfortmerkmale.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1373,'skoda-octavia-zweite-generation','Laurin & Klement','Ausstattungslinie','Top-Ausstattungslinie mit exklusiven Leichtmetallfelgen, Bi-Xenon-Scheinwerfern (falls nicht Serie), Chrompaket. Innenraum mit Lederausstattung und Holz- oder Aluminiumapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1374,'skoda-octavia-zweite-generation','RS','Ausstattungslinie','Sportliche Optik mit spezifischen Stoßfängern, Heckspoiler, Doppelendrohren, größeren Leichtmetallfelgen und RS-Logos. Innenraum mit Sportsitzen und sportlichen Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1375,'skoda-octavia-zweite-generation','Scout','Ausstattungslinie','Offroad-Optik mit erhöhter Bodenfreiheit, robusten Kunststoffbeplankungen an Radläufen und Schwellern, Unterfahrschutz-Optik an Front und Heck, spezifische Leichtmetallfelgen und Dachreling. Nur als Kombi erhältlich.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1376,'skoda-octavia-dritte-generation','Active','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1377,'skoda-octavia-dritte-generation','Ambition','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Außenspiegel, erweiterte Komfortausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1378,'skoda-octavia-dritte-generation','Style','Ausstattungslinie','Hochwertigere Leichtmetallfelgen, Chromapplikationen, LED-Tagfahrlicht (vor Facelift), verbesserte Innenraummaterialien',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1379,'skoda-octavia-dritte-generation','Elegance','Ausstattungslinie','(Vor Facelift) Ähnlich wie Style, oft mit zusätzlichen Komfort- und Designelementen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1380,'skoda-octavia-dritte-generation','Laurin & Klement','Ausstattungslinie','Exklusive Leichtmetallfelgen, Bi-Xenon-Scheinwerfer (vor Facelift), Lederausstattung, spezielle Dekorleisten, umfangreichste Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1381,'skoda-octavia-dritte-generation','Scout','Ausstattungslinie','Erhöhte Bodenfreiheit, Offroad-Beplankung an Radläufen und Stoßfängern, Unterfahrschutz-Optik, Allradantrieb serienmäßig',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1382,'skoda-octavia-dritte-generation','RS','Ausstattungslinie','Sportliche Stoßfänger, Heckspoiler, größere Leichtmetallfelgen, Sportfahrwerk, Sportsitze, rote Bremssättel (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1383,'skoda-superb-erste-generation','Classic','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1384,'skoda-superb-erste-generation','Comfort','Ausstattungslinie','Leichtmetallfelgen (oft 16 Zoll), lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer, Chromzierleisten an den Seitenfenstern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1385,'skoda-superb-erste-generation','Elegance','Ausstattungslinie','Hochwertigere Leichtmetallfelgen (oft 17 Zoll), Xenon-Scheinwerfer (optional oder Serie), Chromzierleisten an Stoßfängern und Seiten, oft Lederausstattung oder hochwertige Stoffe, Holz- oder Aluminiumapplikationen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1386,'skoda-superb-erste-generation','Laurin & Klement','Ausstattungslinie','Exklusive Leichtmetallfelgen, spezielle Lackierungen, umfangreiche Chromapplikationen, hochwertige Lederausstattung mit L&K-Logos, erweiterte Komfortausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1387,'skoda-superb-zweite-generation','Active','Basis','Einfache Ausstattung, oft mit Stahlfelgen und unlackierten Türgriffen/Spiegeln in frühen Modellen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1388,'skoda-superb-zweite-generation','Ambition','Ausstattungslinie','Umfangreichere Ausstattung als Active, oft mit Leichtmetallfelgen und Nebelscheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1389,'skoda-superb-zweite-generation','Elegance','Ausstattungslinie','Hochwertigere Materialien im Innenraum, oft mit Leder- oder Teilledersitzen, Klimaautomatik, Xenon-Scheinwerfern und größeren Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1390,'skoda-superb-zweite-generation','GreenLine','Ausstattungslinie','Aerodynamische Optimierungen (z.B. tiefergelegtes Fahrwerk, spezielle Felgen), oft mit ''GreenLine''-Emblemen.','Fokus auf Kraftstoffeffizienz durch technische Anpassungen (Start-Stopp, Rekuperation) und aerodynamische Maßnahmen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1391,'skoda-superb-zweite-generation','Laurin & Klement','Ausstattungslinie','Exklusivste Ausstattung mit spezifischen Leichtmetallfelgen, Bi-Xenon-Scheinwerfern, Lederausstattung, speziellen Zierleisten und ''Laurin & Klement''-Emblemen.','Top-Ausstattungslinie mit maximalem Komfort und Luxus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1392,'skoda-superb-dritte-generation','Active','Basis','Stahlräder oder einfache Leichtmetallräder, unlackierte Türgriffe und Außenspiegel (je nach Markt/Baujahr), grundlegende Scheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1393,'skoda-superb-dritte-generation','Ambition','Ausstattungslinie','Leichtmetallräder, verchromte Zierleisten an den Seitenfenstern, Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1394,'skoda-superb-dritte-generation','Style','Ausstattungslinie','Größere Leichtmetallräder, LED-Scheinwerfer, Chromzierleisten an Front und Heck, oft getönte Scheiben hinten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1395,'skoda-superb-dritte-generation','L&K (Laurin & Klement)','Ausstattungslinie','Exklusive Leichtmetallräder, L&K-Schriftzüge an den Kotflügeln, spezifische Chromapplikationen, oft Voll-LED-Scheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1396,'skoda-superb-dritte-generation','SportLine','Ausstattungslinie','Schwarze Designelemente (Kühlergrill, Außenspiegel, Dachreling beim Kombi), Sportfahrwerk, größere Leichtmetallräder in Schwarz, getönte Scheiben, Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1397,'skoda-superb-dritte-generation','Scout','Ausstattungslinie','Erhöhte Bodenfreiheit, Offroad-Beplankung an Radläufen und Schwellern, Unterfahrschutz-Optik an Front und Heck, spezifische Leichtmetallräder, Dachreling in Silber.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1398,'skoda-scala-erste-generation','Active','Basis','Stahlräder, einfache Scheinwerfer, unlackierte Außenspiegel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1399,'skoda-scala-erste-generation','Ambition','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, lackierte Außenspiegel, bessere Innenraummaterialien.','Umfangreichere Serienausstattung als Active, z.B. Klimaanlage, Radio.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1400,'skoda-scala-erste-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen, Voll-LED-Scheinwerfer, Chrom-Applikationen, bessere Sitze.','Höchste Ausstattungslinie mit vielen Komfort- und Technik-Features serienmäßig.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1401,'skoda-scala-erste-generation','Monte Carlo','Ausstattungslinie','Sportliche Optik mit schwarzen Akzenten, spezifische Felgen, Sportsitze, Panoramadach.','Sondermodell mit sportlichem Fokus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1402,'skoda-kamiq-erste-generation','Ambition','Ausstattungslinie','Umfasst typischerweise 16-Zoll-Leichtmetallfelgen, Nebelscheinwerfer, Dachreling, Klimaanlage, Infotainmentsystem mit Touchscreen.','Basis für höhere Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1403,'skoda-kamiq-erste-generation','Style','Ausstattungslinie','Zusätzlich zu Ambition oft mit größeren Leichtmetallfelgen (z.B. 17 Zoll), LED-Scheinwerfern, Ambientebeleuchtung, Zwei-Zonen-Klimaautomatik, besseren Sitzbezügen.','Höherwertige Ausstattung im Vergleich zu Ambition.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1404,'skoda-kamiq-erste-generation','Sportline','Ausstattungslinie','Dynamischere Optik mit spezifischen Stoßfängern, Sportsitzen, Sportfahrwerk, größeren Felgen, schwarzen Akzenten.','Fokus auf sportlicheres Design und Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1405,'skoda-kamiq-erste-generation','Monte Carlo','Ausstattungslinie','Exklusive Designelemente wie schwarze Anbauteile, spezifische Felgen, rote Akzente im Innenraum, Sportsitze, Panoramadach (optional).','Top-Ausstattungslinie mit besonderem, sportlich-elegantem Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1406,'skoda-karoq-erste-generation','Ambition','Ausstattungslinie','Standard-Stoßfänger, 17-Zoll-Leichtmetallfelgen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1407,'skoda-karoq-erste-generation','Style','Ausstattungslinie','Chrom-Applikationen am Kühlergrill und an den Seitenfenstern, 18-Zoll-Leichtmetallfelgen, bessere Scheinwerfer (optional LED).','Höherwertige Materialien im Innenraum, mehr Komfortausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1408,'skoda-karoq-erste-generation','Sportline','Ausstattungslinie','Dynamischere Front- und Heckschürzen, schwarze Anbauteile, 19-Zoll-Leichtmetallfelgen, Sportsitze, schwarzer Dachhimmel.','Fokussiert auf sportlicheres Aussehen und Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1409,'skoda-karoq-erste-generation','Scout','Ausstattungslinie','Robusteres SUV-Design mit Unterfahrschutz vorne und hinten, grauen Anbauteilen, 18-Zoll-Leichtmetallfelgen, erhöhte Bodenfreiheit (optional mit Allradantrieb).','Offroad-orientierte Optik und Funktionalität.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1410,'skoda-kodiaq-erste-generation','Active','Basis','Grundausstattung, oft mit kleineren Stahlfelgen oder einfachen Leichtmetallfelgen, unlackierte Stoßfängerunterteile (je nach Markt/Modelljahr), grundlegende Scheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1411,'skoda-kodiaq-erste-generation','Ambition','Ausstattungslinie','Zusätzliche Chromapplikationen, größere Leichtmetallfelgen, Nebelscheinwerfer, oft mit Dachreling.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1412,'skoda-kodiaq-erste-generation','Style','Ausstattungslinie','Umfangreichere Chromdetails, größere und elegantere Leichtmetallfelgen, Voll-LED-Scheinwerfer (oft optional oder serienmäßig), elektrische Heckklappe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1413,'skoda-kodiaq-erste-generation','SportLine','Ausstattungslinie','Sportlichere Optik mit schwarzen Designelementen (Kühlergrillrahmen, Außenspiegelkappen, Dachreling), spezielle Leichtmetallfelgen, sportlichere Stoßfänger, getönte Scheiben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1414,'skoda-kodiaq-erste-generation','L&K (Laurin & Klement)','Ausstattungslinie','Luxuriöseste Ausstattung mit exklusiven Leichtmetallfelgen, spezifischen Chromdetails, L&K-Schriftzügen, oft mit adaptiven Voll-LED-Scheinwerfern und Panoramadach.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1415,'skoda-kodiaq-erste-generation','RS','Echtes M-Modell','Aggressivere Front- und Heckschürzen, spezifische RS-Leichtmetallfelgen, rote Bremssättel, schwarze Designelemente, RS-Logos, Doppelendrohre.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1416,'skoda-enyaq-erste-generation','Enyaq','Basis','Grundausstattung, oft mit kleineren Rädern und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1417,'skoda-enyaq-erste-generation','Loft','Ausstattungslinie','Modernes Interieur mit hellen Stoffen und Dekorelementen.','Eine der ersten Interieur-Design-Suiten, die eine wohnliche Atmosphäre schaffen soll.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1418,'skoda-enyaq-erste-generation','Lounge','Ausstattungslinie','Kombination aus Stoff und Leder, oft mit farbigen Kontrastnähten.','Fokus auf Komfort und eine etwas gehobenere Anmutung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1419,'skoda-enyaq-erste-generation','Suite','Ausstattungslinie','Volllederausstattung, oft in dunklen Tönen, mit spezifischen Dekoreinlagen.','Luxuriöseste Interieur-Option mit hochwertigen Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1420,'skoda-enyaq-erste-generation','SportLine','Ausstattungslinie','Sportlichere Optik mit schwarzen Akzenten (Kühlergrillrahmen, Spiegelkappen, Dachreling), spezifischen Leichtmetallrädern, tiefergelegtem Sportfahrwerk und Sportsitzen im Innenraum.','Betont die dynamische Seite des Enyaq, ohne ein echtes M-Modell zu sein.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1421,'skoda-enyaq-erste-generation','RS','Echtes M-Modell','Exklusives RS-Design mit spezifischen Stoßfängern, schwarzen Designelementen, großen Leichtmetallrädern, RS-Logos, Sportfahrwerk und Sportsitzen mit RS-Branding im Innenraum. Oft mit dem ''Crystal Face'' serienmäßig.','Die Top-Performance-Variante mit der höchsten Leistung und sportlichster Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1422,'skoda-citigo-erste-generation','Active','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (anfangs), einfache Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1423,'skoda-citigo-erste-generation','Ambition','Ausstattungslinie','Teilweise lackierte Stoßfänger, elektrische Fensterheber vorne, Zentralverriegelung, Radio.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1424,'skoda-citigo-erste-generation','Elegance','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Klimaanlage, beheizbare Außenspiegel, Lederlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1425,'skoda-citigo-erste-generation','Style','Ausstattungslinie','Nach dem Facelift eingeführt, ersetzte Elegance. Bietet ähnliche Komfortmerkmale wie Elegance, oft mit zusätzlichen Designelementen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1426,'skoda-citigo-erste-generation','Monte Carlo','Ausstattungslinie','Sportliche Optik mit schwarzen Designelementen (Dach, Spiegelkappen, Felgen), Sportfahrwerk, getönte Scheiben.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1427,'skoda-citigo-erste-generation','Citigoᵉ iV','Ausstattungslinie','Elektrische Version, erkennbar an spezifischen Felgen, Ladeanschluss hinter dem Kühlergrill, ''iV''-Schriftzug.','Rein elektrischer Antrieb.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1428,'seat-ibiza-erste-generation','L','Basis','Einfache Ausstattung, oft unlackierte Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1429,'seat-ibiza-erste-generation','GL','Ausstattungslinie','Etwas verbesserte Ausstattung gegenüber ''L'', oft mit mehr Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1430,'seat-ibiza-erste-generation','GLX','Ausstattungslinie','Höhere Ausstattungslinie mit zusätzlichen Komfort- und Designelementen, wie z.B. Drehzahlmesser, Velourssitze, teilweise Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1431,'seat-ibiza-erste-generation','SXi','Ausstattungslinie','Sportlichere Variante, oft mit speziellen Felgen, Spoilerlippen und sportlicherem Interieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1432,'seat-ibiza-zweite-generation','Basis','Basis','Einfache Radkappen, unlackierte Stoßfänger (oft), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1433,'seat-ibiza-zweite-generation','Stella','Ausstattungslinie','Leicht verbesserte Ausstattung, oft mit lackierten Stoßfängern und besseren Sitzbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1434,'seat-ibiza-zweite-generation','Signo','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Nebelscheinwerfern, Leichtmetallfelgen (optional), Klimaanlage (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1435,'seat-ibiza-zweite-generation','Sport','Ausstattungslinie','Sportlichere Optik mit speziellen Stoßfängern, Seitenschwellern, Sportfahrwerk und Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1436,'seat-ibiza-zweite-generation','Cupra','Echtes M-Modell','Sehr sportliche Optik mit spezifischen Front- und Heckschürzen, großen Lufteinlässen, breiteren Kotflügeln, großen Leichtmetallfelgen, Sportfahrwerk und Recaro-Sportsitzen. Deutlich erkennbar an den Cupra-Logos.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1437,'seat-ibiza-dritte-generation','Reference','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffbezüge im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1438,'seat-ibiza-dritte-generation','Stylance','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, bessere Sitzbezüge, Klimaanlage (oft Serie).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1439,'seat-ibiza-dritte-generation','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezifische Leichtmetallfelgen, sportlichere Front- und Heckschürzen (teilweise), verchromtes Auspuffendrohr.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1440,'seat-ibiza-dritte-generation','FR','M Performance','Eigenständige Front- und Heckschürzen, 16- oder 17-Zoll-Leichtmetallfelgen, Sportfahrwerk, Sportsitze mit FR-Logo, Doppelendrohr-Auspuffanlage.','Positioniert unterhalb des Cupra, bietet eine sportliche Optik und Motorisierung, aber nicht die extreme Performance des Cupra.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1441,'seat-ibiza-dritte-generation','Cupra','Echtes M-Modell','Exklusive Front- und Heckschürzen, größere Lufteinlässe, 17-Zoll-Leichtmetallfelgen, Cupra-spezifisches Sportfahrwerk, Hochleistungsbremsanlage, Sportsitze mit Cupra-Logo, zentrales Auspuffendrohr (beim 1.8T) oder Doppelendrohr (beim 1.9 TDI).','Das Topmodell der Baureihe mit der höchsten Motorleistung und einer auf maximale Sportlichkeit ausgelegten Ausstattung und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1442,'seat-ibiza-vierte-generation','Reference','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise in frühen Modellen), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1443,'seat-ibiza-vierte-generation','Style','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer, erweiterte Komfortausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1444,'seat-ibiza-vierte-generation','Sport','Ausstattungslinie','Sportfahrwerk, spezielle Leichtmetallfelgen, Sportsitze, sportliche Akzente im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1445,'seat-ibiza-vierte-generation','FR','Ausstattungslinie','Sportliche Front- und Heckstoßfänger, FR-spezifische Leichtmetallfelgen, Doppelendrohr-Auspuffanlage, FR-Logo, Sportsitze, Sportlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1446,'seat-ibiza-vierte-generation','Cupra','Echtes M-Modell','Aggressivere Frontschürze mit größeren Lufteinlässen, Cupra-spezifische Leichtmetallfelgen, zentraler trapezförmiger Auspuff, Cupra-Logo, Sportsitze, Sportfahrwerk, leistungsstarke Bremsanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1452,'seat-ibiza-fünfte-generation','Reference','Basis','Stahlräder, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Scheinwerfer ohne LED-Technik (vor Facelift).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1453,'seat-ibiza-fünfte-generation','Style','Ausstattungslinie','Leichtmetallräder, lackierte Türgriffe und Außenspiegel, LED-Tagfahrlicht (vor Facelift), Chromapplikationen.','Bietet mehr Komfort- und Designmerkmale als die Reference-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1454,'seat-ibiza-fünfte-generation','FR','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, spezielle Leichtmetallräder, Doppelendrohr-Optik, FR-Logos, Sportfahrwerk, abgedunkelte Scheiben hinten.','Betont die sportliche Seite des Ibiza mit dynamischerem Design und Fahrwerksabstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1455,'seat-ibiza-fünfte-generation','Xcellence','Ausstattungslinie','Exklusive Leichtmetallräder, Chromzierleisten an den Fenstern, Voll-LED-Scheinwerfer (optional vor Facelift, oft Serie danach), spezielle Innenraumapplikationen.','Fokus auf Eleganz und Komfort mit hochwertigerer Ausstattung und Designelementen. Wurde nach dem Facelift durch die ''Style Edition'' oder ''FR Edition'' ersetzt bzw. integriert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1456,'seat-leon-erste-generation','Reference','Basis','Einfachere Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1457,'seat-leon-erste-generation','Stylance','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, lackierte Türgriffe.','Umfangreichere Komfortausstattung als Reference.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1458,'seat-leon-erste-generation','Sport','Ausstattungslinie','Sportfahrwerk, größere Leichtmetallfelgen, spezifische Sitzbezüge.','Fokus auf sportlicheres Fahrverhalten und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1459,'seat-leon-erste-generation','Cupra','M Performance','Aggressivere Frontschürze, Cupra-Schriftzüge, Sportsitze, größere Bremsanlage, spezifische Leichtmetallfelgen.','Leistungsstärkste Variante mit sportlicher Abstimmung und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1460,'seat-leon-zweite-generation','Reference','Basis','Einfachere Stoßfänger, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1461,'seat-leon-zweite-generation','Style','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, bessere Innenraummaterialien.','Umfangreichere Ausstattung als Reference.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1462,'seat-leon-zweite-generation','Sport','Ausstattungslinie','Sportfahrwerk, Sportsitze, spezifische Zierleisten.','Fokussiert auf sportlicheres Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1463,'seat-leon-zweite-generation','Cupra','M Performance','Aggressivere Frontschürze, größere Leichtmetallfelgen, Doppelrohr-Auspuffanlage, Cupra-Schriftzüge.','Leistungsstärkste Variante mit sportlicher Optik und Fahrwerk.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1464,'seat-leon-dritte-generation','Reference','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Scheinwerfer ohne LED-Tagfahrlicht (vor Facelift).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1465,'seat-leon-dritte-generation','Style','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer, LED-Tagfahrlicht (optional oder serienmäßig je nach Baujahr).','Bietet mehr Komfort- und Designmerkmale als die Reference-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1466,'seat-leon-dritte-generation','FR (Formula Racing)','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, spezielle Leichtmetallfelgen, Doppelendrohr-Auspuffanlage (je nach Motorisierung), FR-Logos, Sportsitze, Sportfahrwerk.','Betont die sportliche Seite des Leon mit optischen und fahrwerkstechnischen Anpassungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1467,'seat-leon-dritte-generation','Xcellence','Ausstattungslinie','Chromapplikationen an der Front und den Seitenfenstern, spezielle Leichtmetallfelgen, Voll-LED-Scheinwerfer (oft serienmäßig), Komfortsitze.','Fokus auf Eleganz und Komfort, oft mit höherwertiger Innenausstattung und mehr Assistenzsystemen (nach Facelift eingeführt).');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1468,'seat-leon-dritte-generation','Cupra','Echtes M-Modell','Eigenständige, aggressivere Front- und Heckschürzen, große Lufteinlässe, spezielle Cupra-Leichtmetallfelgen, größere Bremsanlage, Doppel- oder Vierrohr-Auspuffanlage, Cupra-Logos, Sportsitze mit Alcantara/Leder, tiefergelegtes Fahrwerk.','Das Topmodell mit leistungsstärksten Motoren und umfassenden sportlichen Modifikationen an Fahrwerk, Bremsen und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1469,'seat-leon-vierte-generation','Reference','Basis','Grundausstattung, oft mit kleineren Rädern und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1470,'seat-leon-vierte-generation','Style','Ausstattungslinie','Erweiterte Komfortmerkmale, oft mit Leichtmetallrädern und zusätzlichen Designelementen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1471,'seat-leon-vierte-generation','BusinessLine','Ausstattungslinie','Speziell für Geschäftskunden konzipiert, oft mit Navigationssystem und Parksensoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1472,'seat-leon-vierte-generation','Xcellence','Ausstattungslinie','Fokus auf Eleganz und Komfort, mit Chromdetails, speziellen Felgen und hochwertigerer Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1473,'seat-leon-vierte-generation','FR','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, größeren Rädern, Sportfahrwerk und FR-Logos. Oft mit roten Ziernähten im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1474,'seat-leon-vierte-generation','VZ','Echtes M-Modell','Top-Sportmodell unter der Marke Cupra. Eigenständige Cupra-Logos, aggressivere Front- und Heckschürzen, größere Bremsen, spezielle Felgen und Sportabgasanlage. Deutlich von den Seat-Modellen abgegrenzt.','Die VZ-Modelle werden unter der eigenständigen Marke Cupra vertrieben und stellen die leistungsstärksten Varianten dar, die sich sowohl optisch als auch technisch deutlich von den Seat-Modellen abheben.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1475,'seat-arona-erste-generation','Reference','Basis','Einfachere Felgen, weniger Chrom-Applikationen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1476,'seat-arona-erste-generation','Style','Ausstattungslinie','Leicht verbesserte Felgen, mehr Komfortfunktionen, optional zweifarbige Lackierung.','Umfangreichere Serienausstattung als Reference, z.B. Klimaanlage, Radio.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1477,'seat-arona-erste-generation','Xcellence','Ausstattungslinie','Hochwertigere Materialien im Innenraum, größere Felgen, zusätzliche Chrom-Akzente, LED-Scheinwerfer.','Fokus auf Komfort und Design, z.B. Klimaautomatik, Parksensoren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1478,'seat-arona-erste-generation','FR (Formula Racing)','M Performance','Sportlicheres Design mit spezifischen Stoßfängern, roten Bremssätteln (optional), Sportsitzen, größeren Felgen.','Betont den sportlichen Charakter, z.B. strafferes Fahrwerk, spezifische Interieur-Details.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1479,'seat-ateca-erste-generation','Reference','Basis','Stahlfelgen (oft mit Radkappen), unlackierte Türgriffe und Außenspiegel (je nach Markt/Baujahr), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1480,'seat-ateca-erste-generation','Style','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer, Chromzierleisten an den Seitenfenstern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1481,'seat-ateca-erste-generation','Xcellence','Ausstattungslinie','Größere Leichtmetallfelgen, Voll-LED-Scheinwerfer, Chrom-Paket außen, Dachreling in Chrom oder Silber, spezielle Stoßfängerdesign-Elemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1482,'seat-ateca-erste-generation','FR','Ausstattungslinie','Sportlichere Stoßfänger vorne und hinten, spezielle FR-Leichtmetallfelgen, schwarze Dachreling, FR-Logos, Doppelendrohr-Optik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1483,'seat-ateca-erste-generation','FR Black Edition','Ausstattungslinie','Basierend auf FR, zusätzlich mit schwarzen Designelementen wie schwarzen Leichtmetallfelgen, schwarzen Außenspiegelkappen und schwarzer Dachreling.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1484,'seat-tarraco-erste-generation','Reference','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1485,'seat-tarraco-erste-generation','Style','Ausstattungslinie','Erweiterte Ausstattung, oft mit Leichtmetallfelgen, Dachreling und zusätzlichen Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1486,'seat-tarraco-erste-generation','Xcellence','Ausstattungslinie','Hochwertige Ausstattung mit Chromdetails, größeren Leichtmetallfelgen, Voll-LED-Scheinwerfern und oft Lederausstattung oder Teilleder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1487,'seat-tarraco-erste-generation','FR','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, größeren Leichtmetallfelgen, roten Ziernähten im Innenraum und sportlicherem Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1488,'cupra-formentor-erste-generation','Formentor','Basis','Grundausstattung, oft mit 18-Zoll-Leichtmetallrädern, LED-Scheinwerfern und -Rückleuchten, Sportsitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1489,'cupra-formentor-erste-generation','VZ','Ausstattungslinie','Sportlichere Optik mit größeren Leichtmetallrädern (oft 19 Zoll), spezifischen Stoßfängern, Sportfahrwerk, VZ-spezifischen Details im Innenraum.','Steht für ''Veloz'' (spanisch für schnell) und kennzeichnet die leistungsstärkeren Motorisierungen und sportlicheren Ausstattungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1490,'cupra-formentor-erste-generation','VZ5','Echtes M-Modell','Exklusiv mit 2,5-Liter-Fünfzylinder-Motor. Erkennbar an spezifischen 20-Zoll-Leichtmetallrädern, Carbon-Applikationen (z.B. an den Seitenschwellern und dem Heckdiffusor), vier diagonal angeordneten Endrohren und einer aggressiveren Front- und Heckschürze.','Die Top-Performance-Variante mit exklusivem Motor und spezifischen Designelementen, die die höchste Leistungsstufe signalisieren.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1491,'cupra-born-erste-generation','Born','Basis','Grundausstattung, oft mit 18-Zoll-Leichtmetallrädern, LED-Beleuchtung vorne und hinten, sportliche Stoßfänger.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1492,'cupra-born-erste-generation','VZ','Ausstattungslinie','Stärkere Motorisierung, oft mit größeren Rädern (z.B. 19 oder 20 Zoll), spezifischen VZ-Logos, sportlicheren Sitzen und Fahrwerksabstimmung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1493,'cupra-leon-erste-generation','Basis','Basis','Standard-Felgen, weniger sportliche Akzente im Exterieur und Interieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1494,'cupra-leon-erste-generation','V','Ausstattungslinie','Sportliche Frontschürze, Cupra-Logo, spezifische Felgen, Sportsitze, Cupra-Lenkrad.','Deutlich sportlicher als die Basisversion, mit Fokus auf Performance-Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1495,'cupra-leon-erste-generation','VZ','M Performance','Nochmals gesteigerte sportliche Optik, größere Felgen, optionale Performance-Pakete, stärkere Bremsanlage.','Die Top-Version mit Fokus auf maximale Sportlichkeit und Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1496,'toyota-aygo-i','Aygo','Basis','Standard-Stoßfänger, einfache Radkappen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1497,'toyota-aygo-i','Aygo Cool','Ausstattungslinie','Oft mit Klimaanlage, elektrischen Fensterhebern vorne, Radio/CD-Player.','Erweiterte Komfortausstattung gegenüber der Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1498,'toyota-aygo-i','Aygo Sport','Ausstattungslinie','Sportlichere Akzente wie z.B. Leichtmetallfelgen, getönte Scheiben, Lederlenkrad, Sportsitze.','Fokus auf sportlicheres Aussehen und Gefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1499,'toyota-aygo-ii','x','Basis','Einstiegsmodell, oft mit unlackierten Türgriffen und Außenspiegeln, Stahlfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1500,'toyota-aygo-ii','x-play','Ausstattungslinie','Zusätzlich zur Basisausstattung oft mit Klimaanlage, Bluetooth-Radio, lackierten Außenspiegeln und Türgriffen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1501,'toyota-aygo-ii','x-cite','Ausstattungslinie','Auffällige Farbgebung (z.B. Cyan Splash, Mandarin Pop), oft mit Kontrastdach, Leichtmetallfelgen, Nebelscheinwerfern.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1502,'toyota-aygo-ii','x-clusiv','Ausstattungslinie','Hochwertigere Ausstattung, oft mit Teilledersitzen, Klimaautomatik, 15-Zoll-Leichtmetallfelgen, Smart-Key-System.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1503,'toyota-aygo-ii','x-wave','Ausstattungslinie','Ausstattung mit elektrischem Faltdach (Canvas-Dach), oft in Kombination mit anderen Ausstattungslinien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1504,'toyota-aygo-ii','x-trend','Ausstattungslinie','Sportlichere Optik, oft mit speziellen Leichtmetallfelgen, dunklen Akzenten und sportlichen Interieurdetails.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1505,'toyota-yaris-i','Sol','Basis','Grundlegende Ausstattung, oft mit Stahlfelgen und einfacheren Stoffbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1506,'toyota-yaris-i','Luna','Ausstattungslinie','Zusätzlich oft mit Klimaanlage, elektrischen Fensterhebern vorne, Zentralverriegelung und besserer Audioanlage.','Höherwertige Materialien und mehr Komfortausstattung als Sol.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1507,'toyota-yaris-i','GTS','Ausstattungslinie','Sportlichere Optik mit spezifischen Felgen, Schürzen und oft Sportsitzen.','Fokus auf sportliches Design und Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1508,'toyota-yaris-ii','Yaris','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (modellabhängig), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1509,'toyota-yaris-ii','Luna','Ausstattungslinie','Oft mit lackierten Außenspiegeln und Türgriffen, Klimaanlage, CD-Radio.','Bietet mehr Komfort- und Sicherheitsmerkmale als die Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1510,'toyota-yaris-ii','Sol','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Lederlenkrad, Klimaautomatik, oft mit zusätzlichen Chromapplikationen.','Umfangreichere Ausstattung mit Fokus auf Komfort und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1511,'toyota-yaris-ii','Executive','Ausstattungslinie','Top-Ausstattung, oft mit größeren Leichtmetallfelgen, Smart-Key-System, Navigationssystem (optional), Teilledersitze.','Die höchste Ausstattungslinie mit allen verfügbaren Komfort- und Technikmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1512,'toyota-yaris-iii','Life','Basis','Einfache Stahlfelgen, unlackierte Türgriffe und Spiegel (je nach Baujahr/Ausstattungsvariante), Basis-Interieur.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1513,'toyota-yaris-iii','Comfort','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Spiegel, Klimaanlage, Radio/CD-Player, elektrische Fensterheber vorne.','Höherwertige Materialien im Innenraum, mehr Komfortfunktionen als ''Life''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1514,'toyota-yaris-iii','Style','Ausstattungslinie','Größere Leichtmetallfelgen, Nebelscheinwerfer, Lederlenkrad, Klimaautomatik, Touchscreen-Infotainmentsystem (je nach Baujahr).','Sportlichere Optik, erweiterte Komfort- und Technologieausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1515,'toyota-yaris-iii','Sport','Ausstattungslinie','Spezifische Sportfelgen, Sportsitze, sportliche Akzente im Innenraum, oft mit stärkeren Motorisierungen.','Fokus auf sportliches Design und Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1516,'toyota-yaris-iii','Hybrid','Ausstattungslinie','Spezifische Hybrid-Embleme, oft mit aerodynamischen Anbauteilen, blaue Akzente im Innenraum.','Fokus auf Effizienz und Hybrid-Antriebstechnologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1517,'toyota-yaris-iv','Active','Basis','Standard-Stoßfänger, einfache Scheinwerfer, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1518,'toyota-yaris-iv','Comfort','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Chrom-Applikationen.','Umfangreichere Komfortausstattung im Innenraum, bessere Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1519,'toyota-yaris-iv','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-LED-Scheinwerfer, abgedunkelte Scheiben.','Höchste Ausstattungsvariante mit Premium-Features wie Ledersitzen, Head-up-Display und erweiterten Assistenzsystemen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1520,'toyota-yaris-iv','GR Sport','Ausstattungslinie','Sportlichere Stoßfänger, spezifische Leichtmetallfelgen, rote Akzente, GR-Logos.','Optisch und teilweise fahrwerkstechnisch an den GR Yaris angelehnt, aber kein reines Performance-Modell.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1521,'toyota-yaris-cross-i','Comfort','Ausstattungslinie','Basis-Ausstattung, oft mit 16-Zoll-Stahlfelgen oder Leichtmetallfelgen, grundlegende Exterieur-Details ohne zusätzliche Chrom- oder Kontrastelemente.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1522,'toyota-yaris-cross-i','Business Edition','Ausstattungslinie','Ähnlich Comfort, aber mit Fokus auf Business-Kunden, oft mit zusätzlichen Konnektivitäts- und Komfortmerkmalen wie Navigationssystem oder Parksensoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1523,'toyota-yaris-cross-i','Style','Ausstattungslinie','Aufgewertetes Exterieur mit 17- oder 18-Zoll-Leichtmetallfelgen, oft mit Bi-Tone-Lackierung (Dach in Kontrastfarbe), LED-Scheinwerfern und Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1524,'toyota-yaris-cross-i','Adventure','Ausstattungslinie','Betont den Offroad-Charakter mit spezifischen 18-Zoll-Leichtmetallfelgen, Unterfahrschutz-Optik vorne und hinten, Dachreling und oft einer Bi-Tone-Lackierung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1525,'toyota-yaris-cross-i','Elegant','Ausstattungslinie','Fokus auf Eleganz und Komfort, oft mit 18-Zoll-Leichtmetallfelgen, hochwertigeren Materialien im Innenraum, LED-Scheinwerfern und dezenten Chrom-Akzenten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1526,'toyota-yaris-cross-i','GR Sport','Ausstattungslinie','Sportlichere Optik mit spezifischen 18-Zoll-Leichtmetallfelgen, GR Sport-Emblemen, sportlicherem Kühlergrill, Diffusor-Optik am Heck und roten Ziernähten im Innenraum. Verfügt über ein sportlicher abgestimmtes Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1527,'toyota-yaris-cross-i','Premiere Edition','Ausstattungslinie','Einführungsmodell mit Vollausstattung, oft basierend auf der Adventure-Linie, aber mit zusätzlichen Komfort- und Technologiepaketen wie Head-up-Display, JBL-Soundsystem und elektrischer Heckklappe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1528,'toyota-corolla-ix','Luna','Ausstattungslinie','Basis-Ausstattung mit Fokus auf Funktionalität.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1529,'toyota-corolla-ix','Sol','Ausstattungslinie','Erweiterte Komfortausstattung, oft mit Leichtmetallfelgen und Nebelscheinwerfern.','Umfangreicher als Luna.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1530,'toyota-corolla-ix','Executive','Ausstattungslinie','Top-Ausstattung mit Lederpolsterung, Klimaautomatik und weiteren Komfortmerkmalen.','Höchste Ausstattungsvariante mit den meisten Extras.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1531,'toyota-corolla-x','Corolla','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (in einigen Märkten), grundlegende Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1532,'toyota-corolla-x','Luna','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, Nebelscheinwerfer (optional)','Erweiterte Komfortausstattung gegenüber der Basisversion, z.B. Klimaanlage, CD-Radio');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1533,'toyota-corolla-x','Sol','Ausstattungslinie','Hochwertigere Leichtmetallfelgen, Chromapplikationen, getönte Scheiben hinten (optional)','Umfassendere Komfort- und Sicherheitsausstattung, z.B. Klimaautomatik, Regensensor, Tempomat');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1534,'toyota-corolla-x','Executive','Ausstattungslinie','Exklusive Leichtmetallfelgen, Lederausstattung (optional), Xenon-Scheinwerfer (optional)','Top-Ausstattungslinie mit maximalem Komfort und allen verfügbaren Optionen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1535,'toyota-corolla-xi','Life','Basis','Standard-Stoßfänger, einfache Scheinwerfer, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1536,'toyota-corolla-xi','Comfort','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Chrom-Applikationen.','Umfangreichere Komfortausstattung im Innenraum, bessere Materialien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1537,'toyota-corolla-xi','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-LED-Scheinwerfer (je nach Baujahr/Ausstattung), verchromte Zierleisten.','Top-Ausstattung mit Lederpolsterung, Navigationssystem, erweiterte Assistenzsysteme.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1538,'toyota-corolla-xii','Comfort','Ausstattungslinie','Grundausstattung, oft mit 16-Zoll-Stahlfelgen oder Leichtmetallfelgen, grundlegende LED-Beleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1539,'toyota-corolla-xii','Business Edition','Ausstattungslinie','Erweiterte Konnektivität und Komfortmerkmale, oft mit Navigationssystem und Parksensoren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1540,'toyota-corolla-xii','GR Sport','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, 17- oder 18-Zoll-Leichtmetallfelgen, GR Sport-Emblemen, schwarzem Dach und sportlicheren Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1541,'toyota-corolla-xii','Executive','Ausstattungslinie','Top-Ausstattung mit hochwertigeren Materialien, größeren Leichtmetallfelgen (oft 18 Zoll), Voll-LED-Scheinwerfern, Chromapplikationen und oft Ledersitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1542,'toyota-c-hr-i','Active','Basis','Standard-Felgen, weniger Chrom-Akzente, Basis-Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1543,'toyota-c-hr-i','Style','Ausstattungslinie','Leichtmetallfelgen, teilweise Chrom-Applikationen, bessere Stoff- oder Ledersitze, erweiterte Infotainment-Funktionen.','Höherwertige Materialien und mehr Komfortmerkmale als ''Active''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1544,'toyota-c-hr-i','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-LED-Scheinwerfer, Lederausstattung, Premium-Soundsystem, erweiterte Assistenzsysteme.','Top-Ausstattung mit den meisten Komfort- und Technologie-Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1545,'toyota-c-hr-i','GR Sport','M Performance','Sportliche Stoßfänger, spezifische Felgen, GR Sport-Embleme, Sportsitze, schwarze Akzente im Innenraum.','Optisch sportlichere Variante, basierend auf höheren Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1546,'toyota-c-hr-ii','Active','Basis','Standard-Felgen, einfache Scheinwerfer, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1547,'toyota-c-hr-ii','GR Sport','Ausstattungslinie','Sportlichere Stoßfänger, spezifische Felgendesigns, GR-Logos, dunklere Akzente im Innenraum.','Abgrenzung durch sportlichere Optik und spezifische GR-Elemente.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1548,'toyota-rav4-i','Basis','Basis',NULL,NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1549,'toyota-rav4-ii','Sol','Basis','Standard-Stoßfänger, einfache Stoffpolsterung, manuelle Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1550,'toyota-rav4-ii','Luna','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, elektrische Fensterheber vorne und hinten, CD-Radio.','Höherwertige Stoff- oder Lederpolsterung, optional mit Klimaanlage und Tempomat.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1551,'toyota-rav4-ii','Executive','Ausstattungslinie','Lederausstattung, Klimaautomatik, Sitzheizung, Tempomat, größere Leichtmetallfelgen.','Top-Ausstattung mit allen Komfortmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1552,'toyota-rav4-iii','Basis','Basis','Stahlfelgen, unlackierte Stoßfängerunterteile (je nach Markt und Baujahr), einfachere Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1553,'toyota-rav4-iii','Executive','Ausstattungslinie','Leichtmetallfelgen, Dachreling, Nebelscheinwerfer, oft Chromapplikationen.','Umfassendere Komfort- und Sicherheitsausstattung als die Basismodelle.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1554,'toyota-rav4-iii','Sol','Ausstattungslinie','Leichtmetallfelgen, Dachreling, Nebelscheinwerfer, oft in Verbindung mit höherwertigen Sitzbezügen.','Mittlere Ausstattungslinie, die Komfort und Funktionalität verbindet.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1555,'toyota-rav4-iii','Life','Ausstattungslinie','Leichtmetallfelgen, Dachreling, oft mit Privacy-Verglasung hinten.','Oft eine gut ausgestattete Variante mit Fokus auf Komfort und Alltagstauglichkeit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1556,'toyota-rav4-iv','Active','Basis','Stahlfelgen mit Radkappen, unlackierte Stoßfängerunterteile (je nach Markt/Baujahr), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1557,'toyota-rav4-iv','Comfort','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, oft Dachreling, verbesserte Innenraummaterialien.','Bietet mehr Komfort- und Designmerkmale als die Basis ''Active''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1558,'toyota-rav4-iv','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, LED-Scheinwerfer (nach Facelift), Chrom-Applikationen, Lederausstattung, Privacy-Glas.','Die Top-Ausstattungslinie mit umfangreichen Komfort-, Sicherheits- und Designmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1559,'toyota-rav4-iv','Business Edition','Ausstattungslinie','Spezifische Leichtmetallfelgen, Navigationssystem, oft Parksensoren.','Auf Flottenkunden und Vielfahrer zugeschnitten, mit Fokus auf Konnektivität und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1560,'toyota-rav4-v','Comfort','Basis','Standard-Felgen, weniger Chrom-Applikationen, Basis-Stoffpolsterung.','Grundlegende Ausstattung mit Fokus auf Funktionalität.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1561,'toyota-rav4-v','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, mehr Chrom-Elemente an Front und Heck, Ledersitze, erweiterte Assistenzsysteme.','Höherwertige Materialien und mehr Komfort- und Sicherheitsfeatures als Comfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1562,'toyota-rav4-v','Adventure','Ausstattungslinie','Robusteres Design mit speziellen Stoßfängern, Unterfahrschutz-Optik, größere Felgen, spezifische Innenraumakzente.','Fokus auf Offroad-Optik und erhöhte Robustheit.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1563,'toyota-rav4-v','GR Sport','Ausstattungslinie','Sportlichere Optik mit spezifischen Felgen, schwarzen Akzenten, Sportsitzen im Innenraum, GR-Logos.','Sportlichere Ausrichtung mit dynamischen Designelementen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1564,'toyota-camry-xv10','GL','Ausstattungslinie','Basis-Ausstattung, oft mit Stahlfelgen und Radkappen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1565,'toyota-camry-xv10','GLi','Ausstattungslinie','Mittlere Ausstattung, oft mit elektrischen Fensterhebern, Zentralverriegelung, teilweise Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1566,'toyota-camry-xv10','GX','Ausstattungslinie','Höhere Ausstattung, oft mit Klimaautomatik, Tempomat, hochwertigeren Stoffen oder Lederoption, Leichtmetallfelgen serienmäßig.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1567,'toyota-camry-xv10','V6','Ausstattungslinie','Bezeichnung für Modelle mit dem 3.0L V6-Motor, oft in Verbindung mit gehobener Ausstattung (ähnlich GX oder darüber).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1568,'toyota-camry-xv20','Basis','Basis','Einfachere Stoffpolsterung, weniger Chrom-Applikationen, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1569,'toyota-camry-xv20','GXL','Ausstattungslinie','Bessere Stoff- oder Lederpolsterung, Leichtmetallfelgen, mehr Chrom-Akzente, Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1570,'toyota-camry-xv30','Solara','Basis','Standard-Felgen, einfachere Stoffpolsterung, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1571,'toyota-camry-xv30','Executive','Ausstattungslinie','Leichtmetallfelgen, Lederpolsterung, Klimaautomatik, elektrische Sitzverstellung, bessere Audioanlage.','Höherwertige Materialien und mehr Komfortausstattung im Vergleich zur Solara-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1572,'toyota-camry-xv40','Basis','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe (markt-/baujahrabhängig), einfachere Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1573,'toyota-camry-xv40','LE','Ausstattungslinie','Leichtmetallfelgen (oft 16 Zoll), verchromte Türgriffe, verbesserte Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1574,'toyota-camry-xv40','SE','Ausstattungslinie','Sportlichere Front- und Heckstoßfänger, Heckspoiler, größere Leichtmetallfelgen (oft 17 Zoll), Sportfahrwerk, dunklere Scheinwerfer-Einfassungen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1575,'toyota-camry-xv40','XLE','Ausstattungslinie','Chromakzente, größere Leichtmetallfelgen (oft 16 oder 17 Zoll), Nebelscheinwerfer, Ledersitze, Holz- oder Aluminium-Applikationen im Innenraum.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1576,'toyota-camry-xv40','Hybrid','Ausstattungslinie','Spezifische Hybrid-Embleme, oft aerodynamisch optimierte Leichtmetallfelgen, blaue Akzente an den Toyota-Logos.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1577,'toyota-camry-xv50','L','Basis','Standardfelgen, einfachere Stoffpolsterung, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1578,'toyota-camry-xv50','LE','Ausstattungslinie','Leichtmetallfelgen, verbesserte Stoffpolsterung, mehr Chrom-Akzente.','Erweiterte Komfort- und Technikmerkmale gegenüber der L-Ausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1579,'toyota-camry-xv50','SE','Ausstattungslinie','Sportlichere Optik mit spezifischen Felgen, abgedunkelten Scheiben, Sportsitzen und aerodynamischen Anbauteilen.','Fokus auf sportlicheres Design und Fahrgefühl.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1580,'toyota-camry-xv50','XLE','Ausstattungslinie','Hochwertigere Materialien, Lederpolsterung, größere Leichtmetallfelgen, erweiterte Komfortausstattung.','Top-Ausstattung mit maximalem Luxus und Komfort.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1581,'toyota-camry-xv70','Business Edition','Ausstattungslinie','Basis-Ausstattung, oft mit 17-Zoll-Leichtmetallfelgen, LED-Scheinwerfern und -Rückleuchten, aber ohne die sportlicheren Akzente höherer Linien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1582,'toyota-camry-xv70','Executive','Ausstattungslinie','Umfangreichere Ausstattung, oft mit 18-Zoll-Leichtmetallfelgen, Ledersitzen, Navigationssystem und erweiterten Komfortfunktionen. Äußerlich dezenter als die ''Style''-Linie.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1583,'toyota-camry-xv70','Style','Ausstattungslinie','Sportlichere Optik mit spezifischen 18-Zoll-Leichtmetallfelgen, oft mit schwarzen Außenspiegelkappen und einem sportlicher abgestimmten Fahrwerk. Innenraumakzente können variieren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1584,'toyota-prius-xw10','Basis','Basis','Unauffälliges Exterieur ohne spezifische Designelemente, meist mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1585,'toyota-prius-xw20','Basis','Basis','Stahlfelgen mit Radkappen, unlackierte Türgriffe (in einigen Märkten), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1586,'toyota-prius-xw20','Executive','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, lackierte Türgriffe, höherwertige Stoffbezüge oder Teilleder, Navigationssystem (optional).','Umfasst in der Regel zusätzliche Komfort- und Technologiemerkmale gegenüber der Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1587,'toyota-prius-xw30','Executive','Ausstattungslinie','In der Regel mit 17-Zoll-Leichtmetallfelgen, Nebelscheinwerfern und Chromapplikationen. Innen oft mit Teilleder- oder Ledersitzen und einem größeren Touchscreen-Display.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1588,'toyota-prius-xw30','Comfort','Ausstattungslinie','Oft mit 15- oder 16-Zoll-Leichtmetallfelgen, Stoffpolsterung und einem kleineren Infotainment-Display. Weniger Chromdetails als die Executive-Linie.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1589,'toyota-prius-xw30','Life','Basis','Meist mit Stahlfelgen und Radkappen, einfacherer Stoffpolsterung und grundlegender Ausstattung. Keine Nebelscheinwerfer serienmäßig.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1590,'toyota-prius-xw50','Comfort','Ausstattungslinie','Basis-Ausstattung, oft mit 15-Zoll-Leichtmetallfelgen, LED-Scheinwerfern und -Rückleuchten, Toyota Touch 2 Multimediasystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1591,'toyota-prius-xw50','Executive','Ausstattungslinie','Erweiterte Ausstattung, oft mit 17-Zoll-Leichtmetallfelgen, Nebelscheinwerfern, Teilleder- oder Ledersitzen, Head-up-Display, JBL-Soundsystem (optional).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1592,'toyota-prius-xw50','Business Edition','Ausstattungslinie','Oft auf Flottenkunden zugeschnitten, mit Navigationssystem und erweiterten Konnektivitätsfunktionen, kann optisch der Comfort- oder Executive-Linie ähneln.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1593,'toyota-land-cruiser-j60','Standard','Basis','Einfachere Stoßfänger, weniger Chrom-Applikationen, oft kleinere Räder.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1594,'toyota-land-cruiser-j60','VX','Ausstattungslinie','Verchromte Stoßfänger, oft Leichtmetallfelgen, mehr Chrom-Applikationen, Klimaanlage, elektrische Fensterheber.','Höherwertige Materialien im Innenraum, mehr Komfortausstattung im Vergleich zur Standard-Version.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1595,'toyota-land-cruiser-j80','STD (Standard)','Basis','Einfache Ausstattung, oft mit Stahlspeichenrädern, manuellen Fensterhebern und ohne Klimaanlage.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1596,'toyota-land-cruiser-j80','GX','Ausstattungslinie','Mittlere Ausstattung, oft mit elektrischen Fensterhebern, Klimaanlage und optionalen Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1597,'toyota-land-cruiser-j80','VX (VXL)','Ausstattungslinie','Top-Ausstattung mit luxuriöseren Merkmalen wie Ledersitzen, elektrischen Sitzen, Schiebedach, ABS und optionalen Differentialsperren.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1598,'toyota-land-cruiser-j100','GX','Basis','Einfachere Felgen, weniger Chrom-Applikationen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1599,'toyota-land-cruiser-j100','VX','Ausstattungslinie','Leichtmetallfelgen, mehr Chrom-Akzente, Lederpolsterung (optional), verbesserte Audioanlage.','Höherwertige Materialien und mehr Komfortausstattung im Vergleich zur GX-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1600,'toyota-land-cruiser-j200','Executive','Ausstattungslinie','Umfasst in der Regel Lederausstattung, Navigationssystem, Schiebedach und erweiterte Assistenzsysteme. Äußerlich oft an größeren Leichtmetallfelgen und Chromapplikationen erkennbar.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1601,'toyota-land-cruiser-j200','Life','Ausstattungslinie','Bietet eine gute Grundausstattung mit Komfortmerkmalen wie Klimaautomatik und Infotainmentsystem. Äußerlich weniger Chrom und kleinere Felgen als die Executive-Linie.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1602,'toyota-land-cruiser-j200','V8','Ausstattungslinie','Bezieht sich primär auf die Motorisierung (V8-Benziner oder -Diesel). Optisch oft mit den Top-Ausstattungslinien wie Executive kombiniert, kann aber auch als eigenständige Bezeichnung für die Motorisierungsvariante dienen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1603,'toyota-land-cruiser-j300','GX','Basis','Grundausstattung, oft mit Stahlfelgen oder kleineren Leichtmetallfelgen, weniger Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1604,'toyota-land-cruiser-j300','GXL','Ausstattungslinie','Zusätzliche Komfortmerkmale, größere Leichtmetallfelgen, mehr Chromdetails, LED-Scheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1605,'toyota-land-cruiser-j300','VX','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Ledersitzen, erweiterten Assistenzsystemen, Premium-Audiosystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1606,'toyota-land-cruiser-j300','Sahara','Ausstattungslinie','Top-Ausstattungslinie mit allen verfügbaren Luxus- und Technologiemerkmalen, exklusive Felgen, oft mit spezifischen Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1607,'toyota-land-cruiser-j300','GR Sport','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, schwarzen Akzenten, GR Sport-Emblemen, oft mit speziellen Offroad-Fahrwerkskomponenten wie E-KDSS.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1608,'toyota-hilux-erste-generation','Standard','Basis','Einfache Stahlfelgen, grundlegende Innenausstattung, keine zusätzlichen Zierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1609,'toyota-hilux-zweite-generation','Standard','Basis','Einfache Stahlfelgen, unlackierte Stoßfänger, minimale Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1610,'toyota-hilux-zweite-generation','Deluxe','Ausstattungslinie','Verchromte Stoßfänger, Zierleisten, eventuell Radkappen.','Bietet mehr Komfortmerkmale im Innenraum wie Teppichboden, bessere Sitze und Radio.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1611,'toyota-hilux-fünfte-generation','Basis','Basis','Einfache Stahlfelgen, unlackierte Stoßfänger, minimale Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1612,'toyota-hilux-fünfte-generation','SR5','Ausstattungslinie','Oft mit Leichtmetallfelgen, verchromten Stoßfängern und Außenspiegeln, optionalen Grafiken an den Seiten.','Die SR5-Linie bot eine gehobene Ausstattung mit mehr Komfortmerkmalen und einer ansprechenderen Optik im Vergleich zur Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1613,'toyota-hilux-sechste-generation','Basis','Basis','Einfache Stahlfelgen, unlackierte Stoßfänger und Außenspiegel, grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1614,'toyota-hilux-sechste-generation','SR5','Ausstattungslinie','Leichtmetallfelgen, verchromte Stoßfänger und Kühlergrill, oft lackierte Außenspiegel, verbesserte Innenausstattung mit Stoffbezügen.','Die SR5-Linie bot mehr Komfort- und Designmerkmale als die Basismodelle und war oft mit stärkeren Motoren oder Allradantrieb kombiniert.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1615,'toyota-hilux-siebte-generation','Basis','Basis','Stahlfelgen, unlackierte Stoßfänger, einfache Stoffbezüge, manuelle Klimaanlage (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1616,'toyota-hilux-siebte-generation','Comfort','Ausstattungslinie','Teilweise lackierte Stoßfänger, elektrische Fensterheber, Zentralverriegelung, Radio-CD-System',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1617,'toyota-hilux-siebte-generation','Executive','Ausstattungslinie','Leichtmetallfelgen, verchromte Außenspiegel und Türgriffe, Nebelscheinwerfer, Klimaautomatik, Lederlenkrad, optional Ledersitze',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1618,'toyota-hilux-achte-generation','Duty','Basis','Stahlfelgen, unlackierte Stoßfänger (oft), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1619,'toyota-hilux-achte-generation','Comfort','Ausstattungslinie','Leichtmetallfelgen, lackierte Stoßfänger, oft Nebelscheinwerfer.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1620,'toyota-hilux-achte-generation','Executive','Ausstattungslinie','Größere Leichtmetallfelgen, Chrom-Applikationen (Kühlergrill, Spiegelkappen), LED-Scheinwerfer, Trittbretter.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1621,'toyota-hilux-achte-generation','Invincible','Ausstattungslinie','Exklusive Leichtmetallfelgen, spezifische Front- und Heckstoßfänger, Radhausverbreiterungen, oft schwarze Designelemente, LED-Scheinwerfer.','Top-Ausstattungslinie mit sportlich-robustem Offroad-Look.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1622,'toyota-hilux-achte-generation','GR Sport','Ausstattungslinie','Spezifischer Kühlergrill mit ''TOYOTA''-Schriftzug, sportliche Stoßfänger, rote Akzente, GR Sport-Logos, spezielle Leichtmetallfelgen, oft Bilstein-Stoßdämpfer.','Sportlichste Ausstattungslinie mit Fokus auf Offroad-Performance und dynamischem Design.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1623,'toyota-supra-erste-generation-(a40/a50)','Standard','Basis','Grundlegende Ausstattung, oft mit manuellen Fensterhebern und einfacheren Sitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1624,'toyota-supra-erste-generation-(a40/a50)','GTS','Ausstattungslinie','Oft mit sportlicheren Akzenten, besseren Sitzen, optionalen Leichtmetallfelgen und manchmal mit einem Schiebedach.','Die GTS-Variante bot eine gehobenere Ausstattung und sportlichere Optionen im Vergleich zur Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1625,'toyota-supra-zweite-generation-(a60)','P-Type','Ausstattungslinie','Breitere Kotflügelverbreiterungen aus Kunststoff, größere Räder und Reifen, sportlichere Innenausstattung mit Sportsitzen.','Die P-Type (Performance Type) war auf sportliche Leistung und Optik ausgelegt.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1626,'toyota-supra-zweite-generation-(a60)','L-Type','Ausstattungslinie','Schmalere Karosserie ohne Kotflügelverbreiterungen, kleinere Räder, luxuriösere Innenausstattung mit Lederoptionen und digitalen Armaturen.','Die L-Type (Luxury Type) konzentrierte sich auf Komfort und Luxus.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1627,'toyota-supra-dritte-generation-(a70)','Standard','Basis','Grundlegende Ausstattung, oft mit Stoffpolsterung, manueller Klimaanlage und einfacherem Audiosystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1628,'toyota-supra-dritte-generation-(a70)','GT Turbo','Ausstattungslinie','Oft mit Lederausstattung, elektrischen Sitzen, besserem Audiosystem, Klimaautomatik und spezifischen Felgendesigns.','Höherwertige Materialien und mehr Komfortfunktionen im Vergleich zur Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1629,'toyota-supra-dritte-generation-(a70)','2.0 Twin Turbo','Ausstattungslinie','Ähnlich der GT Turbo, aber mit dem kleineren Twin-Turbo-Motor. Kann spezifische Designelemente aufweisen.','Unterschied im Motor und potenziell in der spezifischen Ausstattung im Vergleich zu den 3.0-Liter-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1630,'toyota-supra-vierte-generation-(a80)','SZ','Basis','Standard-Felgen, weniger aggressive Spoiler.','Die SZ-Variante war die Basisversion mit dem kleineren Saugmotor und weniger Leistung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1631,'toyota-supra-vierte-generation-(a80)','SZ-R','Ausstattungslinie','Leicht verbesserte Felgen, oft mit größerem Heckspoiler.','Die SZ-R bot eine bessere Ausstattung und den stärkeren Saugmotor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1632,'toyota-supra-vierte-generation-(a80)','RZ','M Performance','Leichtmetallfelgen, oft mit größerem Heckspoiler, sportlichere Sitze.','Die RZ-Variante war die Top-Version mit dem legendären 2JZ-GTE Twin-Turbo-Motor.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1633,'toyota-supra-vierte-generation-(a80)','RZ-S','M Performance','Ähnlich RZ, aber mit Fokus auf Komfort.','Die RZ-S war eine Variante der RZ mit Fokus auf Komfort, z.B. Lederausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1639,'toyota-supra-fünfte-generation-(a90)','Supra','Basis','Grundausstattung, oft mit 18-Zoll-Leichtmetallrädern und weniger sportlichen Akzenten als höhere Linien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1640,'toyota-supra-fünfte-generation-(a90)','Supra Dynamic','Ausstattungslinie','Umfasst in der Regel sportlichere Details wie 19-Zoll-Leichtmetallräder, rote Bremssättel und ein adaptives Fahrwerk.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1641,'toyota-supra-fünfte-generation-(a90)','Supra Premium','Ausstattungslinie','Bietet zusätzliche Komfort- und Technologiemerkmale wie ein JBL-Soundsystem, Head-up-Display und Lederausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1642,'toyota-supra-fünfte-generation-(a90)','Supra Jarama Racetrack Edition','Ausstattungslinie','Sondermodell mit exklusiver Lackierung (z.B. Horizon Blue), mattschwarzen 19-Zoll-Rädern und spezifischen Interieur-Details.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1643,'toyota-supra-fünfte-generation-(a90)','Supra Fuji Speedway Edition','Ausstattungslinie','Sondermodell mit weißer Lackierung, mattschwarzen 19-Zoll-Rädern und roten Außenspiegelkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1644,'toyota-bz4x-erste-generation','Comfort','Basis','18-Zoll-Leichtmetallfelgen, LED-Scheinwerfer, Rückfahrkamera, Klimaautomatik.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1645,'toyota-bz4x-erste-generation','Executive','Ausstattungslinie','Zusätzlich zu Comfort: 20-Zoll-Leichtmetallfelgen, Panorama-Glasdach, Ledersitze, beheizbares Lenkrad, erweiterte Sicherheitsfeatures.','Umfangreichere Komfort- und Technologieausstattung im Vergleich zur Comfort-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1646,'toyota-bz4x-erste-generation','Premium','Ausstattungslinie','Zusätzlich zu Executive: Head-up-Display, Premium-Soundsystem, erweiterte Assistenzsysteme, spezielle Designelemente.','Höchste Ausstattungslinie mit maximalem Komfort und modernster Technologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1647,'hyundai-i10-erste-generation','Classic','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Stoffbezüge.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1648,'hyundai-i10-erste-generation','Comfort','Ausstattungslinie','Oft mit lackierten Türgriffen und Außenspiegeln, Klimaanlage, Radio-CD-System, elektrische Fensterheber vorne.','Bietet mehr Komfort- und Sicherheitsmerkmale als die Classic-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1649,'hyundai-i10-erste-generation','Style','Ausstattungslinie','Leichtmetallfelgen (optional), Nebelscheinwerfer, Lederlenkrad und -schaltknauf, erweiterte Audiofunktionen, oft mit zusätzlichen Chrom-Applikationen.','Die höchste Ausstattungslinie mit Fokus auf Komfort und Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1650,'hyundai-i10-zweite-generation','Classic','Basis','Einfachere Radabdeckungen, weniger Chrom-Applikationen, Basis-Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1651,'hyundai-i10-zweite-generation','Trend','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Klimaanlage, elektrisch verstellbare Fensterheber vorne.','Umfangreichere Komfort- und Designmerkmale als Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1652,'hyundai-i10-zweite-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen, Klimaautomatik, beheizbares Lenkrad, Rückfahrkamera, Infotainmentsystem mit Touchscreen.','Höchste Ausstattungslinie mit den meisten Komfort- und Technologie-Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1653,'hyundai-i10-dritte-generation','Pure','Basis','Einfache Stahlfelgen, unlackierte Türgriffe und Spiegel, grundlegende Innenraummaterialien.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1654,'hyundai-i10-dritte-generation','Select','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Spiegel, verbesserte Innenraummaterialien, Klimaanlage.','Höherwertige Materialien und mehr Komfortausstattung als die Pure-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1655,'hyundai-i10-dritte-generation','Trend','Ausstattungslinie','Größere Leichtmetallfelgen, Nebelscheinwerfer, Lederlenkrad, Infotainmentsystem mit Touchscreen, Rückfahrkamera.','Umfangreichere Technologie- und Komfortmerkmale als die Select-Linie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1656,'hyundai-i10-dritte-generation','N Line','M Performance','Sportlicheres Design mit spezifischen Stoßfängern, roten Akzenten, größeren Leichtmetallfelgen, Sportsitzen, Doppelrohrauspuff.','Deutlich sportlichere Optik und Haptik im Vergleich zu den anderen Ausstattungslinien.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1657,'hyundai-i20-erste-generation','Classic','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Polsterstoffe.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1658,'hyundai-i20-erste-generation','Comfort','Ausstattungslinie','Oft mit lackierten Türgriffen und Außenspiegeln, Klimaanlage, Radio-CD-System.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1659,'hyundai-i20-erste-generation','Style','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, Lederlenkrad, Klimaautomatik (optional), verbesserte Audiosysteme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1660,'hyundai-i20-erste-generation','Premium','Ausstattungslinie','Umfangreichere Ausstattung, oft mit zusätzlichen Komfort- und Sicherheitsmerkmalen, wie z.B. Parksensoren, Regensensor, Lichtsensor.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1661,'hyundai-i20-zweite-generation','Classic','Basis','Grundlegende Ausstattung, oft mit Stahlfelgen und einfacheren Stoffbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1662,'hyundai-i20-zweite-generation','Trend','Ausstattungslinie','Verbesserte Innenraummaterialien, oft mit Leichtmetallfelgen, Klimaanlage und besserem Audiosystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1663,'hyundai-i20-zweite-generation','Style','Ausstattungslinie','Höchste Ausstattungsvariante mit Klimaautomatik, Navigationssystem, Sitzheizung und weiteren Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1664,'hyundai-i20-zweite-generation','N Line','Ausstattungslinie','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, größeren Leichtmetallfelgen und sportlichen Akzenten im Innenraum.','Optisch und teilweise fahrwerkstechnisch angelehnt an die N-Modelle, aber keine reine Performance-Variante.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1665,'hyundai-i20-dritte-generation','Pure','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), grundlegende Ausstattung ohne viele Komfort- oder Design-Extras.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1666,'hyundai-i20-dritte-generation','Select','Ausstattungslinie','Leichtmetallfelgen (optional), lackierte Türgriffe und Außenspiegel, erweiterte Komfortmerkmale wie Klimaanlage und Radio mit Farbdisplay.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1667,'hyundai-i20-dritte-generation','Trend','Ausstattungslinie','Leichtmetallfelgen, LED-Tagfahrlicht, Nebelscheinwerfer, erweiterte Infotainment-Systeme, Rückfahrkamera.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1668,'hyundai-i20-dritte-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen, Voll-LED-Scheinwerfer, abgedunkelte Scheiben hinten, Zweifarblackierung (optional), digitale Instrumente, größere Infotainment-Bildschirme.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1669,'hyundai-i20-dritte-generation','Prime','Ausstattungslinie','Umfassendste Ausstattung mit allen verfügbaren Komfort- und Sicherheitsfeatures, oft mit spezifischen Designelementen wie Chromakzenten oder speziellen Sitzbezügen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1670,'hyundai-i20-dritte-generation','N Line','M Performance','Sportlichere Front- und Heckschürzen, spezifische Leichtmetallfelgen, N Line-Embleme, Sportsitze, rote Ziernähte im Innenraum, Doppelendrohr-Auspuffblende.','Betont die sportliche Optik und Haptik, ohne die Leistungssteigerung eines echten N-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1671,'hyundai-i30-erste-generation','Classic','Basis','Einfachere Radkappen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1672,'hyundai-i30-erste-generation','Style','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, teilweise mehr Chrom.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1673,'hyundai-i30-erste-generation','Premium','Ausstattungslinie','Größere Leichtmetallfelgen, Klimaautomatik, Lederlenkrad.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1674,'hyundai-i30-zweite-generation','Classic','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfachere Scheinwerfer ohne LED-Tagfahrlicht.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1675,'hyundai-i30-zweite-generation','Trend','Ausstattungslinie','Leichtmetallfelgen (oft 15 oder 16 Zoll), Nebelscheinwerfer, teilweise LED-Tagfahrlicht, lackierte Türgriffe und Außenspiegel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1676,'hyundai-i30-zweite-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen (oft 16 oder 17 Zoll), LED-Tagfahrlicht, Chromapplikationen, Projektionsscheinwerfer, teilweise getönte Scheiben hinten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1677,'hyundai-i30-zweite-generation','Premium','Ausstattungslinie','Umfangreichste Ausstattung, oft 17-Zoll-Leichtmetallfelgen, Xenon-Scheinwerfer (optional), Panoramadach (optional), Chromzierleisten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1678,'hyundai-i30-zweite-generation','Sport','Ausstattungslinie','Sportlichere Optik mit speziellen Leichtmetallfelgen, Sportfahrwerk, Sportsitze, rote Ziernähte im Innenraum, oft dunklerer Dachhimmel.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1679,'hyundai-i30-dritte-generation','Pure','Basis','Einfache Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise bei frühen Modellen), grundlegende Ausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1680,'hyundai-i30-dritte-generation','Select','Ausstattungslinie','Oft mit Klimaanlage, Radio und elektrischen Fensterhebern ausgestattet. Äußerlich meist mit Radkappen oder kleineren Leichtmetallfelgen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1681,'hyundai-i30-dritte-generation','Trend','Ausstattungslinie','Umfangreichere Ausstattung, oft mit Leichtmetallfelgen, Nebelscheinwerfern, Lederlenkrad und Infotainmentsystem.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1682,'hyundai-i30-dritte-generation','Style','Ausstattungslinie','Hochwertigere Materialien, größere Leichtmetallfelgen, LED-Scheinwerfer (optional/serienmäßig je nach Baujahr), oft mit Chromapplikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1683,'hyundai-i30-dritte-generation','Premium','Ausstattungslinie','Top-Ausstattung mit allen verfügbaren Komfort- und Sicherheitsfeatures, exklusive Felgendesigns, oft mit Panoramadach und Ledersitzen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1684,'hyundai-i30-dritte-generation','N Line','M Performance','Sportlichere Optik mit spezifischen Stoßfängern, Seitenschwellern, N Line-Kühlergrill, größeren Leichtmetallfelgen, roten Akzenten im Innenraum und Sportsitzen. Oft mit sportlicher abgestimmtem Fahrwerk.','Bietet eine sportliche Optik und Fahrwerksabstimmung, aber nicht die volle Performance eines echten N-Modells.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1685,'hyundai-i30-dritte-generation','N','Echtes M-Modell','Aggressiveres Aerodynamik-Kit mit größeren Lufteinlässen, roten Zierleisten, Heckspoiler, doppelten Endrohren, spezifischen 18- oder 19-Zoll-Leichtmetallfelgen, N-Sportsitzen und N-Lenkrad mit blauen Tasten.','Ein eigenständiges Hochleistungsmodell mit leistungsstärkerem Motor, verstärktem Fahrwerk, größerer Bremsanlage und spezifischer N-Abstimmung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1686,'hyundai-kona-erste-generation','Pure','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (modellabhängig), einfachere Scheinwerfer',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1687,'hyundai-kona-erste-generation','Select','Ausstattungslinie','Leichtmetallfelgen, lackierte Türgriffe und Außenspiegel, erweiterte Komfortmerkmale',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1688,'hyundai-kona-erste-generation','Trend','Ausstattungslinie','Größere Leichtmetallfelgen, LED-Tagfahrlicht (falls nicht Serie), Dachreling, erweiterte Infotainment-Optionen',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1689,'hyundai-kona-erste-generation','Style','Ausstattungslinie','Spezifische Leichtmetallfelgen, Voll-LED-Scheinwerfer, Chromapplikationen, Teilledersitze',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1690,'hyundai-kona-erste-generation','Prime','Ausstattungslinie','Exklusive Leichtmetallfelgen, Lederausstattung, Head-up-Display, erweiterte Assistenzsysteme',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1691,'hyundai-kona-erste-generation','N Line','Ausstattungslinie','Sportlichere Front- und Heckschürzen, spezifische Leichtmetallfelgen, N Line Embleme, farbige Akzente im Innenraum, Doppelendrohr-Optik','Sportlich orientierte Optikpakete, keine Leistungssteigerung wie bei echten N-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1692,'hyundai-kona-zweite-generation','Prime','Basis','Standard-Stoßfänger, 16-Zoll-Stahlräder mit Radkappen, Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1693,'hyundai-kona-zweite-generation','Select','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, beheizbares Lederlenkrad, Rückfahrkamera.','Erweitert die Prime-Ausstattung um Komfort- und Designmerkmale.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1694,'hyundai-kona-zweite-generation','Style','Ausstattungslinie','17-Zoll-Leichtmetallfelgen, LED-Scheinwerfer, Klimaautomatik, Navigationssystem mit 10,25-Zoll-Touchscreen, Ambientebeleuchtung.','Bietet eine gehobenere Ausstattung mit moderner Technologie und verbesserter Optik.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1695,'hyundai-kona-zweite-generation','Premium','Ausstattungslinie','18-Zoll-Leichtmetallfelgen, Lederausstattung, elektrisch verstellbarer Fahrersitz, Bose-Soundsystem, Head-up-Display.','Die Top-Ausstattungslinie mit maximalem Komfort und Premium-Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1696,'hyundai-tucson-erste-generation','GL','Basis','Stahlfelgen, unlackierte Stoßfänger (in einigen Märkten), grundlegende Innenausstattung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1697,'hyundai-tucson-erste-generation','GLS','Ausstattungslinie','Leichtmetallfelgen, lackierte Stoßfänger, Nebelscheinwerfer, Dachreling.','Bietet mehr Komfort- und Sicherheitsmerkmale als die GL-Variante.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1698,'hyundai-tucson-erste-generation','Limited','Ausstattungslinie','Exklusive Leichtmetallfelgen, verchromte Akzente, Lederausstattung, oft mit Schiebedach.','Die Top-Ausstattungslinie mit den meisten Komfort- und Luxusmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1699,'hyundai-tucson-zweite-generation','Classic','Basis','Stahlfelgen, unlackierte Stoßfängerunterteile (je nach Markt/Modelljahr), grundlegende Ausstattung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1700,'hyundai-tucson-zweite-generation','Comfort','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, teilweise lackierte Stoßfängerunterteile, Dachreling',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1701,'hyundai-tucson-zweite-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen, verchromte Zierelemente, Teilledersitze, Klimaautomatik',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1702,'hyundai-tucson-zweite-generation','Premium','Ausstattungslinie','Volllederausstattung, Xenon-Scheinwerfer, Navigationssystem, Panorama-Glasdach (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1703,'hyundai-tucson-dritte-generation','Classic','Basis','Einfachere Felgen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1704,'hyundai-tucson-dritte-generation','Trend','Ausstattungslinie','Leichtmetallfelgen, Dachreling, Nebelscheinwerfer.','Umfangreichere Serienausstattung als Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1705,'hyundai-tucson-dritte-generation','Style','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-Xenon-Scheinwerfer (optional/je nach Baujahr), Chrom-Akzente, Ledersitze (optional).','Höherwertige Materialien und mehr Komfortfunktionen als Trend.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1706,'hyundai-tucson-dritte-generation','Premium','Ausstattungslinie','Top-Ausstattung mit größeren Felgen, Panoramadach (optional), erweiterte Assistenzsysteme, Lederausstattung.','Die luxuriöseste Variante mit dem höchsten Ausstattungsniveau.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1707,'hyundai-tucson-vierte-generation','Pure','Basis','Standard-Felgen, weniger Chrom-Applikationen, Basis-Stoffpolsterung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1708,'hyundai-tucson-vierte-generation','Select','Ausstattungslinie','Leichtmetallfelgen, erweiterte Chrom-Elemente, bessere Stoff- oder Teilleder-Polsterung, erweiterte Infotainment-Funktionen.','Umfangreichere Serienausstattung als Pure, z.B. Parksensoren vorne und hinten, Rückfahrkamera.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1709,'hyundai-tucson-vierte-generation','Prime','Ausstattungslinie','Größere Leichtmetallfelgen, Lederpolsterung, Ambientebeleuchtung, erweiterte Fahrerassistenzsysteme, Panorama-Glasdach (optional).','Höchste Ausstattungslinie mit maximalem Komfort und Technologie.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1710,'hyundai-tucson-vierte-generation','N Line','M Performance','Sportlicheres Design mit spezifischen Stoßfängern, Seitenschwellern, größeren Felgen, N Line-Emblemen, Sportsitzen, roten Akzenten im Innenraum.','Optisch und innen sportlicher als Prime, aber keine Leistungssteigerung im Vergleich zu echten M-Modellen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1711,'hyundai-santa-fe-erste-generation','Classic','Basis','Einfachere Stoßfänger, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1712,'hyundai-santa-fe-erste-generation','Style','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, lackierte Stoßfänger.','Höherwertige Materialien im Innenraum, mehr Komfortausstattung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1713,'hyundai-santa-fe-erste-generation','Premium','Ausstattungslinie','Dachreling, getönte Scheiben, größere Leichtmetallfelgen.','Umfangreichste Ausstattung mit Lederpolsterung, Klimaanlage, elektrischen Fensterhebern rundum.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1714,'hyundai-santa-fe-zweite-generation','Comfort','Ausstattungslinie','Grundausstattung, oft mit 17-Zoll-Leichtmetallfelgen, Dachreling und unlackierten Stoßfängerunterteilen (je nach Markt und Baujahr).',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1715,'hyundai-santa-fe-zweite-generation','Style','Ausstattungslinie','Erweiterte Ausstattung, oft mit 18-Zoll-Leichtmetallfelgen, verchromten Türgriffen und Nebelscheinwerfern. Nach dem Facelift teilweise mit LED-Rückleuchten.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1716,'hyundai-santa-fe-zweite-generation','Premium','Ausstattungslinie','Top-Ausstattung, oft mit größeren Leichtmetallfelgen (z.B. 19 Zoll), Xenon-Scheinwerfern (nach Facelift), verchromten Akzenten und Privacy-Verglasung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1717,'hyundai-santa-fe-dritte-generation','Classic','Basis','Einfachere Felgen, weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1718,'hyundai-santa-fe-dritte-generation','Style','Ausstattungslinie','Leichtmetallfelgen, Dachreling, Nebelscheinwerfer, Chrom-Elemente.','Umfangreichere Serienausstattung als Classic.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1719,'hyundai-santa-fe-dritte-generation','Premium','Ausstattungslinie','Größere Leichtmetallfelgen, Bi-Xenon-Scheinwerfer (optional), Ledersitze, Panorama-Glas-Schiebedach (optional).','Höchste Ausstattungsvariante mit den meisten Komfort- und Designmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1720,'hyundai-santa-fe-vierte-generation','Trend','Ausstattungslinie','Basis-Ausstattung, oft mit 17- oder 18-Zoll-Leichtmetallfelgen, grundlegende LED-Beleuchtung.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1721,'hyundai-santa-fe-vierte-generation','Style','Ausstattungslinie','Umfangreichere Ausstattung, oft mit 18- oder 19-Zoll-Leichtmetallfelgen, Chrom-Applikationen, verbesserte Scheinwerfer.','Bietet mehr Komfort- und Sicherheitsmerkmale als ''Trend''.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1722,'hyundai-santa-fe-vierte-generation','Prime','Ausstattungslinie','Top-Ausstattung, oft mit 19- oder 20-Zoll-Leichtmetallfelgen, Voll-LED-Beleuchtung, Panoramadach, spezifische Designelemente wie dunkle Chrom-Akzente (insbesondere nach dem Facelift).','Umfasst nahezu alle verfügbaren Optionen und Premium-Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1723,'hyundai-santa-fe-vierte-generation','Signature','Ausstattungslinie','Nach dem Facelift eingeführte Top-Ausstattung, oft mit exklusiven 20-Zoll-Felgen, spezifischen Lackierungen und Interieur-Details, die den Premium-Anspruch unterstreichen.','Positioniert sich als luxuriöseste Variante mit allen verfügbaren Technologien und Komfortmerkmalen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1724,'hyundai-ioniq-5-erste-generation','Pure','Basis','Standard-Felgen, weniger Chrom-Akzente, Basis-Sitze.','Einstiegsmodell mit kleinerer Batterie und Heckantrieb.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1725,'hyundai-ioniq-5-erste-generation','Style','Ausstattungslinie','Größere Felgen, verbesserte Scheinwerfer-Technologie, höherwertige Sitzbezüge.','Mittleres Ausstattungsniveau mit mehr Komfort- und Technologie-Features.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1726,'hyundai-ioniq-5-erste-generation','Premium','Ausstattungslinie','Größere Felgen, Panorama-Glasdach (optional), erweiterte Assistenzsysteme, Leder-Ausstattung.','Top-Ausstattungslinie mit maximalem Komfort und den meisten verfügbaren Optionen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1727,'hyundai-ioniq-5-erste-generation','N-Line','Ausstattungslinie','Sportlichere Stoßfänger, spezifische Felgen, N-Line-Embleme, Sportsitze.','Sportlich orientierte Ausstattungslinie mit optischen und teils dynamischen Anpassungen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1728,'hyundai-ioniq-6-erste-generation','Base','Basis','Grundausstattung, oft mit kleineren Felgen und weniger Chrom-Applikationen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1729,'hyundai-ioniq-6-erste-generation','Dynamiq','Ausstattungslinie','Umfangreichere Ausstattung als die Basis, oft mit größeren Leichtmetallfelgen und zusätzlichen Komfortmerkmalen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1730,'hyundai-ioniq-6-erste-generation','Techniq','Ausstattungslinie','Top-Ausstattungslinie mit allen verfügbaren Optionen, wie z.B. Digital-Außenspiegel, Head-up-Display und Premium-Soundsystem. Oft mit spezifischen Felgendesigns.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1731,'kia-picanto-ba','Basis','Basis','Einfache Stoßfänger in Wagenfarbe oder schwarz, Stahlfelgen mit Radkappen.',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1732,'kia-picanto-ba','LX','Ausstattungslinie','Stoßfänger in Wagenfarbe, eventuell Leichtmetallfelgen, Nebelscheinwerfer (je nach Baujahr/Facelift).','Umfangreichere Ausstattung als Basis, z.B. elektrische Fensterheber vorne, Zentralverriegelung.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1733,'kia-picanto-ba','EX','Ausstattungslinie','Ähnlich LX, eventuell mit zusätzlichen Chrom-Applikationen.','Höchste Ausstattungslinie mit z.B. Klimaanlage, elektrischen Fensterhebern hinten.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1734,'kia-picanto-ta','Attract','Basis','Stahlfelgen, unlackierte Türgriffe und Außenspiegel (teilweise), einfache Stoffpolsterung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1735,'kia-picanto-ta','Edition 7','Ausstattungslinie','Klimaanlage, Radio-CD-Kombination, elektrische Fensterheber vorne','Bietet eine grundlegende Komfortausstattung über der Basisversion.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1736,'kia-picanto-ta','Spirit','Ausstattungslinie','Leichtmetallfelgen, Nebelscheinwerfer, LED-Tagfahrlicht (nach Facelift), beheizbare Außenspiegel, Lederlenkrad und -schaltknauf','Umfangreichere Komfort- und Designmerkmale, oft mit zusätzlichen Sicherheitssystemen.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1737,'kia-picanto-ta','Dream-Team Edition','Ausstattungslinie','Spezielle Leichtmetallfelgen, Privacy-Verglasung hinten, oft mit Navigationssystem und Rückfahrkamera','Sondermodell mit erweitertem Ausstattungsumfang und oft Preisvorteil.');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1738,'kia-picanto-ja','Spirit','Ausstattungslinie','Alufelgen, Nebelscheinwerfer, Chrom-Applikationen','Höherwertige Materialien im Innenraum, bessere Sitzpolsterung');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1739,'kia-picanto-ja','Platinum','Ausstattungslinie','Größere Alufelgen, Lederlenkrad, Rückfahrkamera','Top-Ausstattung mit den meisten Komfortmerkmalen');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1740,'kia-picanto-ja','GT-Line','Ausstattungslinie','Sportlicheres Design mit roten Akzenten, spezifische Felgen, Doppelrohrauspuff','Optisch sportlichste Variante');
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1741,'kia-rio-dc','Basis','Basis','Stahlfelgen, unlackierte Stoßfänger (teilweise), einfache Stoffbezüge',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1742,'kia-rio-dc','LS','Ausstattungslinie','Teilweise lackierte Stoßfänger, elektrische Fensterheber vorne, Zentralverriegelung',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1743,'kia-rio-dc','GS','Ausstattungslinie','Vollständig lackierte Stoßfänger, Nebelscheinwerfer, Klimaanlage (optional oder Serie), elektrische Fensterheber rundum, Alufelgen (optional)',NULL);
INSERT INTO ausstattungslinie (id,baureihe_id,name,typ,optische_merkmale,abgrenzung) VALUES (1744,'kia-rio-jb','Basis','Basis','Einfache Stoßfänger, Stahlfelgen mit Radkappen.',NULL);
