INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1,'bmw-m4-f82','CFK-Dach Klarlack','Klarlack blättert durch UV','alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (2,'bmw-m4-f82','Hinterachsträger-Buchse','nur eine Gummibuchse, kann unter Lastwechseln reißen','alle','mittel');
