INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (4,'bmw-m4-g82','(allgemein)','zu jung für breit dokumentierte Serienschwächen; vereinzelt Kühlsystem/Infotainment-Software gemeldet','—','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (14,'bmw-3er-g20-g21','Software/Infotainment','Bei frühen Modellen (Baujahr 2019-2020) gab es vereinzelt Berichte über Software-Bugs, Abstürze des Infotainmentsystems oder Probleme mit der Konnektivität. Dies wurde meist durch Updates behoben.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (15,'bmw-3er-g20-g21','Bremsen','Bei sportlicher Fahrweise oder häufigem Kurzstreckenbetrieb kann der Verschleiß der Bremsbeläge und -scheiben überdurchschnittlich hoch sein, insbesondere bei leistungsstärkeren Varianten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (16,'bmw-3er-g20-g21','Knarzgeräusche Innenraum','Selten wurden leichte Knarz- oder Klappergeräusche aus dem Bereich des Armaturenbretts oder der Türverkleidungen gemeldet, oft auf Materialspannungen zurückzuführen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (21,'bmw-1er-f20-f21','Batterie / Start-Stopp-System','Besonders bei frühen Modellen kann die Batterie schnell schwächeln, was zu Fehlfunktionen des Start-Stopp-Systems und anderen Elektronikproblemen führen kann.','2011-2013','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (22,'bmw-1er-f20-f21','Fahrwerk (Verschleißteile)','Bei höheren Laufleistungen können Querlenker, Spurstangenköpfe und Stoßdämpfer verschleißen, was sich durch Poltern oder unpräzises Fahrverhalten äußert.','Ab ca. 100.000 km','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (25,'bmw-2er-coupe-f22','Steuerkette (N20/N26 Motoren)','Bei frühen Baujahren der Vierzylinder-Benziner (N20/N26) kann es zu Problemen mit der Steuerkette kommen, die zu Motorschäden führen können.','2013-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (26,'bmw-2er-coupe-f22','Elektronik','Gelegentliche Ausfälle oder Fehlfunktionen von Infotainmentsystem, Sensoren oder Komfortelektronik.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (27,'bmw-2er-coupe-f22','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern oder Spurstangenköpfen kann zu Poltergeräuschen oder unpräzisem Fahrverhalten führen.','Ab ca. 80.000 km','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (28,'bmw-2er-coupe-f22','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (29,'bmw-2er-gran-coupe-f44','Software/Infotainment','Vereinzelt Berichte über Software-Bugs, Abstürze des Infotainmentsystems oder Probleme mit der Konnektivität.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (30,'bmw-2er-gran-coupe-f44','Knarzgeräusche Innenraum','Manche Nutzer berichten von Knarz- oder Klappergeräuschen im Innenraum, insbesondere im Bereich des Armaturenbretts oder der Türverkleidungen.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (31,'bmw-2er-active-tourer-f45','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse, kann zu vorzeitigem Austausch führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (32,'bmw-2er-active-tourer-f45','Beleuchtung','Ausfall von Glühlampen oder Problemen mit der Einstellung der Scheinwerfer, insbesondere bei Xenon- oder LED-Systemen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (33,'bmw-2er-active-tourer-f45','Ölverlust','Leichter Ölverlust an Motor oder Getriebe kann bei der HU beanstandet werden. Oft sind Dichtungen oder Ventildeckel betroffen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (34,'bmw-2er-active-tourer-f45','Fahrwerk (Vorderachse)','Vereinzelt können ausgeschlagene Querlenkerlager oder Spurstangenköpfe auftreten, was zu Geräuschen oder unpräzisem Fahrverhalten führt.','Frühe Baujahre (2014-2016)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (35,'bmw-4er-f32-f33-f36','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder leistungsstarken Modellen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (36,'bmw-4er-f32-f33-f36','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern oder Spurstangenköpfen kann zu Poltergeräuschen oder unpräzisem Fahrverhalten führen.','Ab ca. 100.000 km','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (37,'bmw-4er-f32-f33-f36','Elektronik (iDrive/Infotainment)','Gelegentliche Software-Probleme, Abstürze oder Ausfälle des iDrive-Systems. Meist durch Updates behebbar.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (38,'bmw-4er-f32-f33-f36','Panoramadach (F36 Gran Coupé)','Knarzgeräusche oder Undichtigkeiten können auftreten, oft durch verschmutzte Dichtungen oder Mechanik.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (39,'bmw-6er-e24','Karosserie (Rost)','Rost ist das größte Problem. Betroffen sind Schweller, Radläufe, Wagenheberaufnahmen, Front- und Heckscheibenrahmen, Tankdeckelbereich, Türeinstiege und der Kofferraumboden.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (40,'bmw-6er-e24','Elektrik','Probleme mit Fensterhebern, Zentralverriegelung, Kombiinstrument (Pixelfehler, Ausfall), Kabelbaum (altersbedingte Brüchigkeit), Relais und Sicherungen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (41,'bmw-6er-e24','Fahrwerk','Verschleiß an Gummilagern, Buchsen, Spurstangenköpfen und Stoßdämpfern führt zu unpräzisem Fahrverhalten und Geräuschen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (42,'bmw-6er-e24','Dichtungen (Motor, Getriebe, Differential)','Altersbedingte Undichtigkeiten an Motor (Ventildeckel, Ölwanne), Getriebe und Differential sind häufig und führen zu Ölverlust.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (43,'bmw-6er-e63-e64','Elektronik / iDrive','Ausfälle oder Fehlfunktionen des iDrive-Systems, der Komfortelektronik (Fensterheber, Zentralverriegelung) oder der Sensoren.','Alle Baujahre, besonders frühe Modelle.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (44,'bmw-6er-e63-e64','Rost','Rostbildung an der Heckklappe (unter der Chromleiste), an den Radläufen und an den Türunterkanten, besonders bei frühen Baujahren.','2003-2006','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (45,'bmw-6er-e63-e64','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','Alle Baujahre, alters- und laufleistungsbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (46,'bmw-6er-e63-e64','Panoramadach (E63 Coupé)','Probleme mit der Mechanik oder Undichtigkeiten des optionalen Panoramadachs.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (47,'bmw-6er-e63-e64','Verdeck (E64 Cabrio)','Undichtigkeiten, Funktionsstörungen der Verdeckmechanik oder Verschleiß des Verdeckstoffs.','Alle Baujahre, altersbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (48,'bmw-6er-f12-f13-f06','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, besonders bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (49,'bmw-6er-f12-f13-f06','Elektronik','Probleme mit dem iDrive-System, Ausfall von Komfortfunktionen (Sitzheizung, Klimaanlage) oder Fehlermeldungen durch defekte Sensoren.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (50,'bmw-6er-f12-f13-f06','Panoramadach (Gran Coupé)','Vereinzelt Berichte über Knarzgeräusche oder Undichtigkeiten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (51,'bmw-6er-gran-turismo-g32','Luftfederung Hinterachse','Die serienmäßige Luftfederung an der Hinterachse kann im Alter undicht werden oder Kompressorprobleme aufweisen, was zu einem Absinken des Hecks führt.','Alle Baujahre, insbesondere bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (52,'bmw-6er-gran-turismo-g32','Elektronik / Software','Wie bei vielen modernen BMWs können sporadische Softwarefehler oder Fehlermeldungen auftreten, die oft durch Updates behoben werden können.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (53,'bmw-8er-e31','Kabelbaum','Alterung und Versprödung der Isolierungen, insbesondere im Motorraum und an der Heckklappe, führt zu Kurzschlüssen und Fehlfunktionen.','Alle Baujahre, besonders frühe Modelle.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (54,'bmw-8er-e31','Elektronik / Steuergeräte','Fehlfunktionen der komplexen Bordelektronik, Ausfall von Komfortfunktionen (Klima, Fensterheber, Zentralverriegelung) oder Motorsteuerung.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (55,'bmw-8er-e31','Fahrwerk','Verschleiß an Querlenkern, Spurstangen, Stabilisatorlagern und Stoßdämpfern führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre, altersbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (56,'bmw-8er-e31','Klimaanlage','Undichtigkeiten im System, defekte Kompressoren oder Steuerungen.','Alle Baujahre, altersbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (57,'bmw-8er-e31','Servolenkung','Undichtigkeiten an Schläuchen oder Lenkgetriebe, Ausfall der Servounterstützung.','Alle Baujahre, altersbedingt.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (62,'bmw-8er-g15-g14-g16','Infotainmentsystem / Elektronik','Gelegentliche Berichte über Software-Glitches, Einfrieren des Systems oder Probleme mit der Konnektivität (Apple CarPlay/Android Auto). Meist durch Software-Updates behebbar.','2018-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (63,'bmw-8er-g15-g14-g16','Verarbeitung Innenraum','Vereinzelt Berichte über Knarzgeräusche oder lose Zierleisten, insbesondere bei frühen Modellen. Meist geringfügig und behebbar.','2018-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (64,'bmw-8er-g15-g14-g16','Bremsanlage (bei M Performance/M Modellen)','Hoher Verschleiß der Bremsbeläge und -scheiben bei sportlicher Fahrweise. Dies ist jedoch eher ein Verschleißmerkmal als ein Mangel.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (65,'bmw-x1-e84','Steuerkette (N47 Dieselmotoren)','Kann sich längen oder reißen, was zu kapitalem Motorschaden führen kann. Betrifft vor allem frühe Baujahre des N47.','2009-2011 (insbesondere bis 03/2011)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (66,'bmw-x1-e84','Fahrwerk (Querlenker, Stoßdämpfer)','Verschleiß der Querlenkerlager und Stoßdämpfer, besonders an der Vorderachse, führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre, alters- und laufleistungsbedingt','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (67,'bmw-x1-e84','Bremsanlage','Erhöhter Verschleiß von Bremsscheiben und -belägen, manchmal auch Probleme mit der Feststellbremse.','Alle Baujahre, laufleistungsbedingt','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (68,'bmw-x1-e84','Panoramadach','Undichtigkeiten oder Probleme mit der Mechanik (Verklemmen, Geräusche).','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (69,'bmw-x1-e84','Injektoren (N43/N53 Benziner)','Defekte Injektoren können zu unrundem Motorlauf, Leistungsverlust und erhöhtem Verbrauch führen.','2009-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (70,'bmw-x1-f48','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder hohem Stadtanteil.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (71,'bmw-x1-f48','Fahrwerk (Vorderachse)','Vereinzelt ausgeschlagene Querlenkerlager oder Spurstangenköpfe, was zu Poltergeräuschen führen kann.','Frühe Baujahre (2015-2017)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (72,'bmw-x1-f48','Infotainmentsystem','Gelegentliche Software-Probleme oder Aussetzer des iDrive-Systems. Meist durch Updates behebbar.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (73,'bmw-x1-f48','Panoramadach','Vereinzelt Klappergeräusche oder Probleme mit der Mechanik des Schiebedachs.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (74,'bmw-x2-f39','Bremsen','Bei sportlicher Fahrweise kann der Verschleiß der Bremsbeläge und -scheiben erhöht sein.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (75,'bmw-x2-f39','Fahrwerk (Vorderachse)','Vereinzelt können Poltergeräusche von der Vorderachse auftreten, oft durch verschlissene Stabilisatorlager oder Querlenkerbuchsen verursacht.','Frühe Baujahre (2017-2019)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (76,'bmw-x2-f39','Infotainmentsystem (iDrive)','Gelegentliche Software-Bugs oder langsame Reaktionen des Systems. Meist durch Updates behebbar.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (77,'bmw-x3-e83','Verteilergetriebe (VTG)','Probleme mit dem Stellmotor oder der Elektronik des Verteilergetriebes, oft erkennbar an Ruckeln, Geräuschen oder Fehlermeldungen (4x4-Leuchte). Regelmäßiger Ölwechsel des VTG kann vorbeugen.','Alle Baujahre, besonders bei mangelnder Wartung','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (78,'bmw-x3-e83','Rost','Häufiger Rostbefall an der Heckklappe, insbesondere im Bereich der Kennzeichenbeleuchtung und des Heckscheibenwischers. Auch an den Türkanten und Radläufen möglich.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (79,'bmw-x3-e83','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen, Stabilisatorlagern und Stoßdämpfern führt zu Poltern, unpräzisem Fahrverhalten und erhöhtem Reifenverschleiß.','Alle Baujahre, besonders bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (80,'bmw-x3-e83','Panoramadach','Undichtigkeiten, verstopfte Abläufe oder Defekte an der Mechanik des Schiebedachs können zu Wassereintritt und Funktionsstörungen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (81,'bmw-x3-e83','Klimaanlage','Defekte Klimakompressoren oder undichte Kondensatoren sind keine Seltenheit.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (82,'bmw-x3-f25','Panoramadach','Knarzgeräusche, Undichtigkeiten, Probleme mit der Mechanik (Öffnen/Schließen).','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (83,'bmw-x3-f25','Verteilergetriebe (VTG)','Bei xDrive-Modellen kann es zu Ruckeln, Geräuschen oder Fehlermeldungen kommen. Oft durch verschlissene Stellmotoren oder Ölwechselmangel verursacht.','Alle Baujahre, besonders bei hohen Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (84,'bmw-x3-f25','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, verstärkt bei hohen Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (85,'bmw-x3-f25','Elektronik','Diverse Sensoren (z.B. ABS, PDC), iDrive-System oder Komfortfunktionen können sporadisch ausfallen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (86,'bmw-x3-g01','Infotainmentsystem (iDrive)','Gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen, insbesondere bei frühen Baujahren vor dem LCI.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (87,'bmw-x3-g01','Panoramadach','Vereinzelt Berichte über Knarzgeräusche oder Undichtigkeiten, meist durch verstopfte Abläufe.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (88,'bmw-x3-g01','Fahrwerk (M Sportfahrwerk)','Bei Fahrzeugen mit M Sportfahrwerk kann es zu erhöhtem Verschleiß an Querlenkerlagern oder Stoßdämpfern kommen, insbesondere bei sportlicher Fahrweise oder schlechten Straßen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (89,'bmw-x4-f26','Verteilergetriebe','Kann bei Allradmodellen (xDrive) zu Ruckeln oder Geräuschen führen, oft durch verschlissene Lamellenkupplungen oder Stellmotoren.','Alle Baujahre, insbesondere bei hoher Laufleistung oder unregelmäßigem Reifenwechsel (unterschiedliche Abrollumfänge).','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (90,'bmw-x4-f26','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, abhängig von Fahrweise und Straßenbedingungen.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (91,'bmw-x4-f26','Bremsanlage','Erhöhter Verschleiß von Bremsbelägen und -scheiben, insbesondere bei sportlicher Fahrweise oder hohem Stadtanteil.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (92,'bmw-x4-g02','Infotainment/Software','Gelegentliche Software-Glitches oder kleinere Aussetzer des Infotainment-Systems (iDrive). Meist durch Updates behebbar.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (93,'bmw-x4-g02','Bremsen','Bei sportlicher Fahrweise oder leistungsstarken Motoren kann der Bremsenverschleiß erhöht sein. Insbesondere bei M Performance oder M Modellen.','','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (94,'bmw-x4-g02','Panoramadach','Vereinzelt Berichte über Knarzgeräusche oder Undichtigkeiten am Panoramadach. Oft durch Justierung oder Reinigung der Dichtungen behebbar.','2018-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (95,'bmw-x5-e53','Rost','Häufig an der Heckklappe (unter der Scheibe, Griffleiste), den Türkanten und den Radläufen.','Alle Baujahre, besonders ältere Modelle und solche ohne Garagenplatz.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (96,'bmw-x5-e53','Fahrwerk','Verschleiß an Querlenkern, Spurstangen, Koppelstangen. Bei Modellen mit Luftfederung hinten können die Luftbälge undicht werden oder der Kompressor ausfallen.','Alle Baujahre, alters- und laufleistungsbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (97,'bmw-x5-e53','Elektrik','Defekte Fensterheber, Ausfall der Park Distance Control (PDC), Pixelfehler im Kombiinstrument, Probleme mit dem Gebläseendwiderstand (Igel).','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (98,'bmw-x5-e53','Automatikgetriebe','Bei mangelnder oder fehlender Getriebeölwartung können Ruckeln, Schaltverzögerungen oder der komplette Ausfall auftreten.','Alle Baujahre, besonders bei hohen Laufleistungen.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (99,'bmw-x5-e53','Panoramadach','Undichtigkeiten, Schwergängigkeit oder Defekte der Mechanik.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (100,'bmw-x5-e70','Luftfederung (Hinterachse)','Defekte Luftbälge oder Kompressoren können zu einem Absinken des Hecks führen. Besonders bei Fahrzeugen mit Anhängerkupplung oder hoher Laufleistung.','Alle Baujahre, besonders ab ca. 100.000 km','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (101,'bmw-x5-e70','Panoramadach','Verstopfte Abläufe können zu Wassereintritt führen. Defekte Mechanik oder Geräusche beim Öffnen/Schließen sind ebenfalls bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (102,'bmw-x5-e70','iDrive-System','Softwarefehler, Ausfälle des Controllers oder des Bildschirms.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (103,'bmw-x5-e70','Getriebe (Automatik)','Ruckeln beim Schalten, verzögerte Gangwechsel oder Notlauf. Oft durch verschlissene Mechatronik oder verunreinigtes Öl.','Alle Baujahre, besonders bei hoher Laufleistung und ohne Getriebeölwechsel','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (104,'bmw-x5-f15','Luftfederung (Hinterachse)','Defekte Luftbälge oder Kompressoren können zu einem Absinken des Hecks führen. Besonders bei Fahrzeugen mit hoher Laufleistung oder häufiger Beladung.','Alle Baujahre, verstärkt ab 100.000 km','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (105,'bmw-x5-f15','Bremsanlage','Hoher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder schweren Motorisierungen. Bremssättel können festgehen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (106,'bmw-x5-f15','Panoramadach','Knarzgeräusche, Undichtigkeiten oder Probleme mit der Mechanik (Öffnen/Schließen) können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (107,'bmw-x5-f15','Elektronik / iDrive','Vereinzelt Berichte über Ausfälle des iDrive-Systems, Sensorfehler oder Probleme mit der Komfortelektronik.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (108,'bmw-x5-g05','Infotainmentsystem (iDrive)','Vereinzelt Berichte über Software-Bugs, Abstürze oder langsame Reaktionen, insbesondere bei frühen Baujahren.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (109,'bmw-x5-g05','Luftfederung','Wie bei vielen Fahrzeugen mit Luftfederung können im Alter Defekte an den Luftbälgen oder dem Kompressor auftreten. Bei frühen Modellen gab es vereinzelt Berichte über Undichtigkeiten.','2018-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (115,'bmw-x6-e71','Luftfederung Hinterachse','Defekte Luftfederbälge oder Kompressoren können zu einem Absinken des Hecks oder Fehlermeldungen führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (116,'bmw-x6-e71','Panoramadach','Probleme mit der Mechanik (Verklemmen, Geräusche) oder Undichtigkeiten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (117,'bmw-x6-e71','iDrive-System / Elektronik','Ausfälle des iDrive-Controllers, des Navigationssystems oder anderer elektronischer Komponenten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (118,'bmw-x6-e71','Vorderachse','Verschleiß an Querlenkern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle, besonders bei hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (119,'bmw-x6-e71','Bremsanlage','Hoher Verschleiß an Bremsbelägen und -scheiben, insbesondere bei sportlicher Fahrweise und schweren Motorisierungen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (124,'bmw-x6-f16','Luftfederung (Hinterachse)','Defekte Luftbälge oder Kompressor können zu einer absinkenden Hinterachse führen. Oft durch Materialermüdung oder Undichtigkeiten.','Alle Baujahre, insbesondere bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (125,'bmw-x6-f16','Elektronik / Infotainment','Ausfälle oder Fehlfunktionen des iDrive-Systems, der Navigation oder anderer elektronischer Komponenten. Software-Updates können oft helfen, aber auch Hardware-Defekte sind möglich.','Alle Baujahre, oft sporadisch.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (126,'bmw-x6-f16','Panoramadach','Undichtigkeiten oder Probleme mit der Mechanik (Öffnen/Schließen) des Panoramadachs.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (127,'bmw-x6-f16','Bremsen','Hoher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise und den leistungsstärkeren Modellen.','Alle Baujahre, abhängig von Fahrweise.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (128,'bmw-x7-g07','Luftfederung','Probleme mit Kompressor, Ventilen oder Luftbälgen können zu ungleichmäßigem Niveau oder Ausfall führen.','Alle Baujahre, insbesondere bei hoher Laufleistung oder im Winter.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (129,'bmw-x7-g07','Elektronik / Software','Gelegentliche Ausfälle oder Fehlfunktionen des Infotainmentsystems (iDrive), der Assistenzsysteme oder anderer elektronischer Komponenten.','Alle Baujahre, oft durch Software-Updates behebbar.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (130,'bmw-x7-g07','Bremsen','Hoher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder schweren Motorisierungen.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (131,'bmw-z4-e85','Verdeckmechanismus','Der Elektromotor für das Verdeck kann ausfallen, oft durch Wassereintritt im Kofferraum. Auch die Gestänge und Sensoren können Probleme bereiten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (132,'bmw-z4-e85','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','Alle Baujahre, besonders bei höheren Laufleistungen','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (133,'bmw-z4-e85','Elektronik','Probleme mit Fensterhebern, PDC-Sensoren und gelegentlich der Zentralverriegelung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (134,'bmw-z4-e86','Lenkgetriebe','Kann Spiel entwickeln oder Geräusche verursachen, insbesondere bei Modellen mit Servotronic.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (135,'bmw-z4-e86','Rost','Vereinzelt an den hinteren Radläufen und unter den Türdichtungen möglich.','Alle Baujahre, besonders bei mangelnder Pflege','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (136,'bmw-z4-e86','Fahrwerk (Buchsen, Lager)','Verschleiß an Querlenkerlagern und Stabilisatorbuchsen, führt zu Poltern und unpräzisem Fahrverhalten.','Alle Baujahre, abhängig von Fahrweise und Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (137,'bmw-z4-e89','Hardtop-Mechanismus','Probleme mit Sensoren, Elektromotoren oder der Mechanik können zu Fehlfunktionen beim Öffnen oder Schließen des Daches führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (138,'bmw-z4-e89','Wassereintritt','Undichtigkeiten an den Dichtungen des Hardtops oder im Kofferraumbereich können zu Wassereintritt führen, was Elektronikschäden oder Schimmelbildung verursachen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (139,'bmw-z4-e89','Elektrische Servolenkung (EPS)','Ausfälle oder sporadische Fehlfunktionen der elektrischen Servolenkung, oft durch defekte Sensoren oder Steuergeräte.','Frühe Baujahre (bis ca. 2011)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (140,'bmw-z4-e89','Fahrwerk (Querlenker, Stoßdämpfer)','Verschleiß an Querlenkerlagern und Stoßdämpfern, insbesondere bei sportlicher Fahrweise oder hohen Laufleistungen, führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre, insbesondere bei höheren Laufleistungen','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (141,'bmw-i3-i01','Ladeelektronik / Ladeanschluss','Vereinzelt können Probleme mit der Ladeelektronik oder dem Ladeanschluss auftreten, die zu Fehlermeldungen oder unterbrochenen Ladevorgängen führen.','2013-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (142,'bmw-i3-i01','Range Extender (REX) Motor','Bei seltenem Gebrauch des REX-Motors kann es zu Verkokungen oder Startschwierigkeiten kommen. Regelmäßige Nutzung oder Wartung ist empfehlenswert.','Alle REX-Modelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (143,'bmw-i3-i01','Fahrwerk (Querlenker, Spurstangen)','Obwohl generell robust, können bei hoher Laufleistung oder schlechten Straßenverhältnissen Verschleiß an Querlenkern oder Spurstangenköpfen auftreten, was sich durch Poltern oder unpräzises Fahrverhalten äußert.','Ab ca. 80.000 km','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (144,'bmw-ix-i20','Software/Infotainment','Vereinzelt Berichte über kleinere Software-Bugs oder Systemabstürze, insbesondere in den frühen Baujahren. Meist durch Over-the-Air-Updates behebbar.','2021-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (145,'bmw-ix-i20','Ladeelektronik','In seltenen Fällen können Probleme beim Laden an bestimmten Ladesäulen oder mit der Kommunikation zwischen Fahrzeug und Ladesäule auftreten.','2021-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (146,'bmw-1er-e87','Steuerkette (N47 Dieselmotoren)','Die Steuerkette der N47-Dieselmotoren (ab ca. 2007) kann sich längen oder reißen, was zu kapitalen Motorschäden führt. Oft kündigt sich dies durch Rasseln im Bereich des Motors an.','2007-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (147,'bmw-1er-e87','Turbolader (Dieselmotoren)','Defekte Turbolader, insbesondere bei den frühen Dieselmodellen, können zu Leistungsverlust und erhöhtem Ölverbrauch führen.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (148,'bmw-1er-e87','Injektoren/Hochdruckpumpe (Benzinmotoren N43/N53)','Bei den Direkteinspritzer-Benzinmotoren (N43/N53) können Injektoren und die Hochdruckpumpe ausfallen, was zu unrundem Motorlauf, Leistungsverlust und Motorkontrollleuchte führt.','2007-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (149,'bmw-1er-e87','Fahrwerk (Querlenker, Stoßdämpfer)','Verschleiß an Querlenkerlagern und Stoßdämpfern ist alters- und laufleistungsbedingt häufig. Äußert sich durch Poltern, schwammiges Fahrverhalten oder ungleichmäßigen Reifenverschleiß.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (150,'bmw-1er-e87','Elektrik/Elektronik','Probleme mit der Batterie (oft durch Kurzstrecke), defekte Fensterheber, Ausfall von Sensoren (z.B. ABS/DSC-Sensoren) oder der Zentralverriegelung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (157,'bmw-1er-f20-f21','Steuerkette (N47 Dieselmotoren)','Geräusche aus dem Motorraum (Rasseln), insbesondere beim Kaltstart. Kann zu Motorschäden führen. Betrifft vor allem frühe Baujahre des N47.','2011-2013 (N47), vereinzelt auch später','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (158,'bmw-1er-f20-f21','Steuerkette (N20 Benzinmotoren)','Ähnlich wie beim N47 können auch die N20-Benziner Probleme mit der Steuerkette und dem Kettenspanner aufweisen, was zu Motorschäden führen kann.','2011-2013 (N20)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (159,'bmw-1er-f20-f21','Wasserpumpe','Defekte Wasserpumpen (oft elektrisch) können zu Überhitzung des Motors führen. Symptome sind Kühlmittelverlust oder Warnleuchten.','Alle Baujahre, häufiger bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (160,'bmw-1er-f20-f21','Injektoren (Dieselmotoren)','Probleme mit den Injektoren können zu unrundem Motorlauf, Leistungsverlust und erhöhtem Verbrauch führen.','Alle Baujahre, häufiger bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (161,'bmw-1er-f20-f21','Achsaufhängung / Querlenker','Verschleiß an Gummilagern und Querlenkern kann zu Poltergeräuschen, unpräzisem Fahrverhalten und ungleichmäßigem Reifenverschleiß führen. Häufig ein Mangel bei der HU.','Alle Baujahre, zunehmend mit Alter und Laufleistung','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (162,'bmw-1er-f20-f21','Bremsleitungen / Bremsschläuche','Korrosion an Bremsleitungen oder poröse Bremsschläuche können bei der Hauptuntersuchung bemängelt werden.','Ältere Baujahre, insbesondere ab 6-7 Jahren','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (163,'bmw-1er-f40','Software / Infotainment','Frühe Baujahre können gelegentlich Software-Probleme oder kleinere Bugs im Infotainmentsystem (iDrive 7) aufweisen, die sich in Abstürzen oder langsamer Reaktion äußern können. Meist durch Updates behebbar.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (164,'bmw-1er-f40','Fahrwerk (Knarzgeräusche)','Einige Nutzer berichten von Knarz- oder Quietschgeräuschen aus dem Bereich der Vorderachse oder des Fahrwerks, insbesondere bei niedrigen Geschwindigkeiten oder über Unebenheiten. Oft sind es Gummilager oder Stabilisatoren.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (165,'bmw-1er-f40','Bremsen (M135i/128ti)','Bei sportlicher Fahrweise kann der Verschleiß der Bremsbeläge und -scheiben bei den leistungsstärkeren Modellen (M135i, 128ti) erhöht sein. Auch Quietschen der Bremsen ist gelegentlich ein Thema.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (190,'mercedes-benz-a-klasse-w168','Rost','Besonders an Türkanten, Heckklappe, Radläufen und im Bereich der Wagenheberaufnahmen. Auch der Unterboden und die Achsaufnahmen können betroffen sein.','Alle Baujahre, besonders vor Facelift (bis 2001).','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (191,'mercedes-benz-a-klasse-w168','Automatikgetriebe','Probleme mit dem CVT-Getriebe (Autotronic), das zu Ruckeln, Schaltproblemen oder komplettem Ausfall neigen kann. Reparaturen sind oft teuer.','Alle Baujahre mit Automatikgetriebe.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (192,'mercedes-benz-a-klasse-w168','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern. Auch die Federbrüche an der Hinterachse sind bekannt.','Alle Baujahre, besonders bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (193,'mercedes-benz-a-klasse-w168','Elektronik','Ausfälle von Fensterhebern, Zentralverriegelung, Kombiinstrument oder dem Gebläsemotor. Auch Probleme mit dem Motorsteuergerät sind möglich.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (194,'mercedes-benz-a-klasse-w168','Bremsleitungen','Korrosion an den Bremsleitungen, insbesondere im Bereich des Unterbodens, kann zu Undichtigkeiten führen.','Alle Baujahre, besonders ältere Fahrzeuge.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (195,'mercedes-benz-a-klasse-w169','Automatikgetriebe (CVT, Autotronic)','Probleme mit der Steuerungselektronik, Ruckeln, Notlauf, Ausfall. Reparaturen sind oft sehr teuer.','Alle Baujahre, besonders frühe Modelle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (196,'mercedes-benz-a-klasse-w169','Rost','Kann an Türkanten, Heckklappe, Radläufen und Unterboden auftreten, insbesondere bei Fahrzeugen, die nicht regelmäßig gepflegt wurden.','Alle Baujahre, verstärkt bei älteren Modellen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (197,'mercedes-benz-a-klasse-w169','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','Alle Baujahre, abhängig von Fahrweise und Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (198,'mercedes-benz-a-klasse-w169','Elektronik','Fehlermeldungen im Kombiinstrument, Probleme mit der Zentralverriegelung, Ausfall von Sensoren (z.B. ABS/ESP).','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (199,'mercedes-benz-a-klasse-w169','Dieselmotoren (OM640)','Probleme mit Injektoren, Turbolader und dem Dieselpartikelfilter (DPF), insbesondere bei Kurzstreckenfahrzeugen.','Alle Baujahre der Dieselmodelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (200,'mercedes-benz-a-klasse-w176','Automatikgetriebe (7G-DCT)','Ruckeln beim Anfahren, Schaltverzögerungen, Notlauf oder Totalausfall. Oft sind Software-Updates oder der Austausch von Mechatronik-Einheiten notwendig.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (201,'mercedes-benz-a-klasse-w176','Steuerkette','Bei einigen Motoren (insbesondere M270/M274) kann es zu Längungen der Steuerkette kommen, was zu Geräuschen und im schlimmsten Fall zu Motorschäden führen kann.','2012-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (202,'mercedes-benz-a-klasse-w176','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise. Auch Quietschen kann auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (203,'mercedes-benz-a-klasse-w176','Fahrwerk (Poltern/Knarzen)','Geräusche von der Vorderachse (Poltern, Knarzen) können auf verschlissene Querlenkerbuchsen oder Stabilisatorlager hindeuten.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (204,'mercedes-benz-a-klasse-w176','Elektronik','Vereinzelt Berichte über Fehlfunktionen des Infotainmentsystems, Ausfälle von Sensoren oder Problemen mit der Start-Stopp-Automatik.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (205,'mercedes-benz-a-klasse-w177','MBUX-Infotainmentsystem','Vereinzelt Berichte über Software-Fehler, Abstürze oder langsame Reaktionen des Systems. Dies kann sich in nicht reagierenden Bildschirmen oder Problemen mit der Sprachsteuerung äußern.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (206,'mercedes-benz-a-klasse-w177','12V-Batterie','Bei frühen Modellen gab es Berichte über eine erhöhte Entladung der 12V-Batterie, insbesondere bei Kurzstreckenfahrten oder längeren Standzeiten, was zu Startproblemen führen konnte.','2018-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (207,'mercedes-benz-a-klasse-w177','Automatikgetriebe (DCT)','In seltenen Fällen wurden Ruckeln oder Schaltverzögerungen bei den Doppelkupplungsgetrieben (7G-DCT und 8G-DCT) gemeldet. Meist durch Software-Updates behebbar.','2018-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (208,'mercedes-benz-b-klasse-w245','Steuerkette (Benzinmotoren)','Bei einigen Benzinmotoren kann es zu Längung der Steuerkette und damit zu Geräuschen und Motorschäden kommen.','2005-2009','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (209,'mercedes-benz-b-klasse-w245','Rost','Anfällig für Rostbildung an Radläufen, Schwellern und Türkanten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (210,'mercedes-benz-b-klasse-w245','Klimaanlage','Defekte Kompressoren oder Lecks im System sind häufig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (211,'mercedes-benz-b-klasse-w245','Automatikgetriebe','Probleme mit Schaltvorgängen oder Ausfall des Getriebes.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (212,'mercedes-benz-b-klasse-w246','Automatikgetriebe (7G-DCT)','Vereinzelt können Ruckeln, Schaltprobleme oder Geräusche auftreten, insbesondere bei höheren Laufleistungen. Software-Updates oder Getriebespülungen können Abhilfe schaffen, in seltenen Fällen ist ein Austausch notwendig.','2011-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (213,'mercedes-benz-b-klasse-w246','Bremsanlage','Überdurchschnittlicher Verschleiß von Bremsscheiben und -belägen, insbesondere an der Vorderachse. Auch Feststellbremsen können Probleme bereiten.','2011-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (214,'mercedes-benz-b-klasse-w246','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','2011-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (215,'mercedes-benz-b-klasse-w246','Elektronik','Störungen im Infotainmentsystem (Comand/Audio 20), Ausfälle von Sensoren oder Fehlermeldungen im Kombiinstrument sind vereinzelt bekannt.','2011-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (216,'mercedes-benz-b-klasse-w247','MBUX-Infotainmentsystem','Gelegentliche Software-Probleme, wie Einfrieren des Systems oder verzögerte Reaktionen. Updates können Abhilfe schaffen.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (217,'mercedes-benz-b-klasse-w247','12V-Bordnetz','Vereinzelt Berichte über entladene 12V-Batterien, insbesondere bei Fahrzeugen, die häufig Kurzstrecken fahren oder längere Zeit stehen.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (218,'mercedes-benz-c-klasse-w202','Rost','An Radläufen, Schwellern, Türen (Unterkanten), Heckklappe.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (219,'mercedes-benz-c-klasse-w202','Kühler','Undichtigkeiten am Kühler.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (220,'mercedes-benz-c-klasse-w202','Einspritzpumpe (Diesel)','Defekte Einspritzpumpen bei älteren Dieselmotoren.','Vor-Facelift','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (221,'mercedes-benz-c-klasse-w202','Fensterheber','Defekte Fensterhebermechanismen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (222,'mercedes-benz-c-klasse-w202','Zentralverriegelung','Ausfall der Zentralverriegelung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (223,'mercedes-benz-c-klasse-w203','Rost','Besonders an Türkanten, Radläufen, Heckklappe (T-Modell), Federaufnahmen und unter den Zierleisten. Betrifft vor allem frühe Baujahre.','2000-2004','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (224,'mercedes-benz-c-klasse-w203','Elektronik','Probleme mit dem SAM-Modul (Signal-Erfass- und Ansteuer-Modul), defekte Fensterheber, Ausfall des Kombiinstruments, Probleme mit dem Zentralverriegelungssystem.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (225,'mercedes-benz-c-klasse-w203','Automatikgetriebe (722.6)','Kann zu Ruckeln, Schaltproblemen oder Notlauf führen, oft durch defekte Elektrohydraulik-Steuerplatte oder verschlissene Wandlerüberbrückungskupplung.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (226,'mercedes-benz-c-klasse-w203','Vorderachse','Verschleiß an Querlenkern, Traggelenken und Spurstangenköpfen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (227,'mercedes-benz-c-klasse-w203','Dieselmotoren (CDI)','Probleme mit Injektoren, Turbolader, AGR-Ventil und Glühkerzen. Bei den Vierzylinder-CDI-Motoren (OM611/OM646) können auch undichte Injektoren zu ''Black Death'' führen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (228,'mercedes-benz-c-klasse-w203','Kompressormotoren (M271)','Probleme mit der Steuerkette (Längung, Verschleiß der Gleitschienen) und dem Nockenwellenversteller, was zu Motorschäden führen kann.','2002-2007','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (229,'mercedes-benz-c-klasse-w204','Rost','Anfällig für Korrosion an Radläufen, Schwellern, Türen und Heckklappe, besonders bei Fahrzeugen mit geringer Pflege oder in salzreichen Regionen.','2007-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (230,'mercedes-benz-c-klasse-w204','Automatikgetriebe (7G-Tronic)','Kann bei hoher Laufleistung Schaltprobleme oder Ruckeln entwickeln. Regelmäßiger Getriebeölwechsel ist wichtig.','2007-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (231,'mercedes-benz-c-klasse-w204','Dieselmotoren (OM651)','Potenzielle Probleme mit dem Turbolader, den Injektoren oder dem AGR-Ventil. Auch die Steuerkette kann sich längen.','2008-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (232,'mercedes-benz-c-klasse-w204','Klimaanlage','Defekte des Klimakompressors oder Undichtigkeiten im System sind keine Seltenheit.','2007-2014','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (233,'mercedes-benz-c-klasse-w205','Automatikgetriebe (7G-TRONIC PLUS / 9G-TRONIC)','Bei einigen Modellen kann es zu Ruckeln, Schaltproblemen oder einem vorzeitigen Verschleiß kommen, insbesondere bei mangelnder Wartung.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (234,'mercedes-benz-c-klasse-w205','Infotainmentsystem (COMAND)','Gelegentliche Software-Probleme, Abstürze oder Aussetzer des Displays.','Gesamte Baureihe','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (235,'mercedes-benz-c-klasse-w205','Kühlsystem','Undichtigkeiten am Kühler oder an Schläuchen können zu Kühlmittelverlust führen.','Gesamte Baureihe','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (236,'mercedes-benz-e-klasse-w210','Rost','Starke Korrosionsanfälligkeit an Radläufen, Schwellern, Türkanten, Kofferraumdeckel, Scheibenrahmen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (237,'mercedes-benz-e-klasse-w210','Kühler','Undichtigkeiten am Automatikgetriebekühler, der im Hauptkühler integriert ist, können zum Durchmischen von Getriebeöl und Kühlwasser führen.','Vor-Facelift (bis 2000)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (238,'mercedes-benz-e-klasse-w210','Fensterheber','Defekte Fensterhebermechanismen, insbesondere bei den hinteren Fenstern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (239,'mercedes-benz-e-klasse-w210','Einspritzpumpe (Diesel)','Probleme mit der Lucas-Einspritzpumpe bei den OM604/OM605/OM606 Dieselmotoren.','Vor-Facelift (bis 2000)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (240,'mercedes-benz-e-klasse-w210','Zentralverriegelung','Ausfall der Zentralverriegelung, oft durch defekte Steuergeräte oder Pumpen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (241,'mercedes-benz-e-klasse-w211','SBC-Bremssystem (Sensotronic Brake Control)','Hydraulisch-elektronisches Bremssystem, das bei Modellen vor dem Facelift verbaut wurde. Kann Ausfälle oder Fehlermeldungen aufweisen, teure Reparatur.','2002-2006','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (242,'mercedes-benz-e-klasse-w211','Rost','Korrosion an Radläufen (insbesondere hinten), Türkanten, Heckklappe (Kombi) und Batteriefach.','Gesamte Baureihe, aber häufiger bei älteren Modellen vor dem Facelift.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (243,'mercedes-benz-e-klasse-w211','Elektronik','Diverse elektronische Probleme, z.B. mit Fensterhebern, Zentralverriegelung, Sensoren, Klimaanlage.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (244,'mercedes-benz-e-klasse-w211','Luftfederung (ABC/Airmatic)','Bei Kombi-Modellen und einigen Limousinen verbaut. Kann zu Undichtigkeiten oder Ausfällen der Kompressoren und Federbeine führen.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (245,'mercedes-benz-e-klasse-w212','Rost','Frühe Baujahre können an den Türkanten, der Heckklappe und unter den Dichtungen Rost aufweisen, insbesondere bei Fahrzeugen, die nicht regelmäßig gepflegt wurden.','2009-2011','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (246,'mercedes-benz-e-klasse-w212','Automatikgetriebe (7G-Tronic)','Probleme mit dem Wandler, Schaltrucken oder Notlauf können auftreten. Oft hilft ein Getriebeölwechsel oder ein Software-Update, in schwereren Fällen ist eine Reparatur des Schaltschiebergehäuses oder des Wandlers nötig.','Alle Baujahre, insbesondere bei mangelnder Wartung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (247,'mercedes-benz-e-klasse-w212','Lenkung','Geräusche oder Spiel in der Lenkung, insbesondere bei der elektrischen Lenkung nach dem Facelift. Auch die Servopumpe bei älteren Modellen kann Probleme bereiten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (248,'mercedes-benz-e-klasse-w212','Injektoren (Dieselmotoren)','Bei den CDI-Motoren können undichte oder defekte Injektoren zu unrundem Motorlauf, Leistungsverlust oder erhöhtem Kraftstoffverbrauch führen.','2009-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (249,'mercedes-benz-e-klasse-w212','Airmatic Luftfederung','Defekte Luftfedern oder Kompressoren können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Reparaturen sind oft kostspielig.','Alle Baujahre (wenn verbaut)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (250,'mercedes-benz-e-klasse-w212','Steuerkette (Vierzylinder-Benziner M271)','Bei den Kompressor-Motoren M271 (E 200/250 CGI) kann es zu Problemen mit der Steuerkette und den Nockenwellenverstellern kommen, was zu Motorschäden führen kann.','2009-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (251,'mercedes-benz-e-klasse-w213','9G-Tronic Automatikgetriebe','Vereinzelt Berichte über Ruckeln, Schaltverzögerungen oder Geräusche, insbesondere bei niedrigen Geschwindigkeiten oder beim Anfahren. Oft durch Software-Updates behebbar.','2016-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (252,'mercedes-benz-e-klasse-w213','Luftfederung (Airmatic)','Mögliche Undichtigkeiten oder Defekte an den Luftbälgen/Kompressor, was zu einem Absinken des Fahrzeugs oder ungleichmäßiger Höhe führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (253,'mercedes-benz-e-klasse-w213','Infotainmentsystem (MBUX/Comand)','Gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen des Systems. Meist durch Updates behebbar.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (254,'mercedes-benz-e-klasse-w213','Lenkung','Vereinzelt Berichte über Knarzgeräusche oder ein leichtes Spiel in der Lenkung.','2016-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (278,'mercedes-benz-s-klasse-w126','Rost','Korrosion an Radläufen, Schwellerenden, Wagenheberaufnahmen, Türen (Unterkanten), Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (279,'mercedes-benz-s-klasse-w126','Automatikgetriebe','Schaltprobleme, Ruckeln, Leckagen bei hoher Laufleistung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (280,'mercedes-benz-s-klasse-w126','Elektrische Fensterheber','Langsamkeit, Ausfall, Geräusche.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (281,'mercedes-benz-s-klasse-w126','Klimaanlage','Defekte Kompressoren, Leckagen im System.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (282,'mercedes-benz-s-klasse-w126','Vorderachse','Verschleiß an Querlenkern und Spurstangenköpfen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (283,'mercedes-benz-s-klasse-w140','Kabelbäume','Die Isolierung der Kabelbäume, insbesondere im Motorraum, kann aufgrund von Materialalterung (biologisch abbaubarer Kunststoff) brüchig werden, was zu Kurzschlüssen und Fehlfunktionen führt.','1991-1995','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (284,'mercedes-benz-s-klasse-w140','Klimaanlage','Probleme mit dem Klimakompressor, undichten Leitungen oder dem Verdampfer sind häufig. Auch die Elektronik der Klimaanlage kann ausfallen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (285,'mercedes-benz-s-klasse-w140','Automatikgetriebe','Verschleiß der Wandlerüberbrückungskupplung, Schaltprobleme oder Ölverlust können auftreten. Regelmäßige Getriebeölwechsel sind entscheidend.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (286,'mercedes-benz-s-klasse-w140','Rost','Obwohl die W140 als robust gilt, kann Rost an den Radläufen, Türkanten, Wagenheberaufnahmen und unter den Dichtungen auftreten, insbesondere bei Fahrzeugen, die nicht gut gepflegt wurden.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (287,'mercedes-benz-s-klasse-w140','Elektronik (diverse)','Fehlfunktionen von Fensterhebern, Sitzverstellungen, Zentralverriegelung oder dem Kombiinstrument sind aufgrund des Alters und der Komplexität der Elektronik möglich.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (288,'mercedes-benz-s-klasse-w140','Fahrwerk (Luftfederung bei S 600 Coupé)','Bei Modellen mit Luftfederung (z.B. S 600 Coupé) können Undichtigkeiten an den Luftbälgen oder Defekte am Kompressor auftreten, was zu einem Absinken des Fahrzeugs führt.','Alle (mit Luftfederung)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (289,'mercedes-benz-s-klasse-w220','Active Body Control (ABC)-Fahrwerk','Defekte an den Federbeinen, der Tandempumpe, den Druckspeichern oder den Leitungen sind häufig. Dies führt zu einem Absinken des Fahrzeugs oder Fehlermeldungen. Reparaturen sind sehr teuer.','Alle Baujahre, besonders vor dem Facelift','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (290,'mercedes-benz-s-klasse-w220','Rost','Rostbildung an Radläufen, Türkanten, Kofferraumdeckel und unter den Zierleisten ist ein bekanntes Problem, insbesondere bei Fahrzeugen, die nicht regelmäßig gepflegt wurden.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (291,'mercedes-benz-s-klasse-w220','Elektronik','Diverse Elektronikprobleme, z.B. mit dem COMAND-System, Fensterhebern, Sitzverstellung, Keyless-Go oder der Zentralverriegelung. Auch die SAM-Module (Signal Acquisition and Actuation Module) können ausfallen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (292,'mercedes-benz-s-klasse-w220','Automatikgetriebe (722.6)','Probleme mit dem Wandler, der Elektronikplatte oder dem Schaltschieberkasten können zu Schaltrucken, Notlauf oder Getriebeschäden führen. Ölwechselintervalle sind entscheidend.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (293,'mercedes-benz-s-klasse-w220','Luftfederung (Airmatic)','Bei Fahrzeugen ohne ABC kann die Airmatic Probleme bereiten, z.B. undichte Luftbälge oder defekte Kompressoren, was zum Absinken des Fahrzeugs führt.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (294,'mercedes-benz-s-klasse-w220','Bremsanlage (SBC - Sensotronic Brake Control)','Bei Modellen mit SBC (bis 2005) kann die Lebenserwartung der SBC-Einheit erreicht sein, was zu einer Fehlermeldung und einem notwendigen, teuren Austausch führt. Mercedes-Benz hat hier Kulanzregelungen gehabt.','2002-2005 (Modelle mit SBC)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (295,'mercedes-benz-s-klasse-w221','Airmatic Luftfederung','Defekte Kompressoren, undichte Federbeine oder Ventileinheiten können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders betroffen sind die vorderen Federbeine.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (296,'mercedes-benz-s-klasse-w221','7G-Tronic Automatikgetriebe','Ruckeln beim Schalten, Schaltverzögerungen oder Notlauf können auf Probleme mit der Elektronik (Schaltschieberkasten) oder dem Drehmomentwandler hindeuten. Ölwechselintervalle sind entscheidend.','Frühe Baujahre (bis ca. 2008)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (297,'mercedes-benz-s-klasse-w221','Rost','Obwohl die W221-Generation als rostresistenter gilt als ihre Vorgänger, können an den Türkanten, Radläufen und unter den Zierleisten vereinzelt Rostansätze auftreten, insbesondere bei Fahrzeugen aus Regionen mit Streusalzeinsatz.','Alle Baujahre, insbesondere ältere Modelle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (298,'mercedes-benz-s-klasse-w221','Elektronik (COMAND, Keyless-Go)','Ausfälle des COMAND-Systems (Bildschirm schwarz, Funktionen ohne Reaktion), Probleme mit dem Keyless-Go-System (Türgriffe reagieren nicht, Startprobleme) oder Fehlermeldungen im Kombiinstrument sind möglich.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (299,'mercedes-benz-s-klasse-w221','Bremsanlage','Übermäßiger Verschleiß der Bremsen, insbesondere bei leistungsstarken Modellen, sowie gelegentliche Probleme mit der SBC-Bremse (Sensotronic Brake Control) bei frühen Modellen, die jedoch später durch eine konventionelle Bremsanlage ersetzt wurde.','Alle Baujahre (Verschleiß), frühe Baujahre (SBC-Probleme)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (300,'mercedes-benz-s-klasse-w222','Luftfederung (Airmatic)','Defekte an den Luftfederbälgen oder dem Kompressor können zu einem Absinken des Fahrzeugs oder ungleichmäßiger Höhe führen. Dies äußert sich oft durch Geräusche oder eine Fehlermeldung im Display.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (301,'mercedes-benz-s-klasse-w222','Infotainmentsystem (COMAND Online)','Gelegentliche Softwareprobleme, Abstürze oder Ausfälle des Bildschirms können auftreten. Auch die Bedienung über das Touchpad kann manchmal haken.','Frühe Baujahre (2013-2015)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (302,'mercedes-benz-s-klasse-w222','Elektronik (diverse Sensoren und Steuergeräte)','Die komplexe Elektronik kann zu sporadischen Fehlermeldungen führen, z.B. bei Assistenzsystemen, Türgriffen oder der Ambientebeleuchtung. Oft sind es kleinere Fehler, die durch Software-Updates behoben werden können.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (303,'mercedes-benz-s-klasse-w222','Bremsen','Aufgrund des hohen Fahrzeuggewichts und der Motorleistung kann der Verschleiß an Bremsbelägen und -scheiben überdurchschnittlich hoch sein, insbesondere bei sportlicher Fahrweise.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (304,'mercedes-benz-cls-c219','SBC-Bremse (Sensotronic Brake Control)','Die elektrohydraulische Bremse kann nach einer bestimmten Anzahl von Bremsvorgängen oder Betriebsstunden eine Fehlermeldung anzeigen und muss dann ausgetauscht werden. Dies ist ein teurer Defekt.','2004-2006 (spätere Modelle wurden auf konventionelle Bremsen umgestellt)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (305,'mercedes-benz-cls-c219','Airmatic Luftfederung','Undichtigkeiten an den Luftbälgen oder Defekte am Kompressor können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (306,'mercedes-benz-cls-c219','7G-Tronic Automatikgetriebe','Kann zu Ruckeln, Schaltverzögerungen oder Notlauf führen, oft verursacht durch Probleme mit der Elektronik (EHS-Einheit) oder dem Drehmomentwandler.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (307,'mercedes-benz-cls-c219','Rost','Rost kann an den Türkanten, Radläufen und am Kofferraumdeckel auftreten, insbesondere bei Fahrzeugen, die nicht regelmäßig gepflegt wurden.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (308,'mercedes-benz-cls-c219','Elektronikprobleme','Diverse kleinere Elektronikprobleme wie defekte Fensterheber, Ausfall des Comand-Systems oder Probleme mit der Zentralverriegelung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (309,'mercedes-benz-cls-c218','Kettenspanner (Dieselmotoren)','Vor allem bei den älteren OM651 Dieselmotoren kann es zu Problemen mit dem Kettenspanner kommen, was zu Motorschäden führen kann.','2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (310,'mercedes-benz-cls-c218','Getriebe (Automatik)','Gelegentliche Probleme mit dem 7G-Tronic Automatikgetriebe, wie Ruckeln oder Schaltprobleme.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (311,'mercedes-benz-cls-c218','Rost','Anfällig für Rostbildung an Radläufen, Schwellern und Heckklappe, besonders bei Fahrzeugen, die viel im Winter bewegt wurden.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (312,'mercedes-benz-cls-c218','Elektronik','Diverse elektronische Probleme, z.B. mit dem Infotainmentsystem, Sensoren oder der Beleuchtung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (313,'mercedes-benz-cls-c257','Luftfederung (AIR BODY CONTROL)','Potenzielle Undichtigkeiten oder Ausfälle der Luftbälge und Kompressoren, was zu Absacken des Fahrzeugs oder Fehlermeldungen führt.','2018-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (314,'mercedes-benz-cls-c257','Infotainmentsystem (MBUX)','Software-Probleme, Abstürze, träge Reaktionen oder Probleme mit der Konnektivität bei frühen Modellen.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (315,'mercedes-benz-cls-c257','Partikelfilter (Diesel)','Verstopfung des Dieselpartikelfilters bei überwiegender Kurzstreckenfahrten, was zu Leistungsverlust und erhöhten Emissionen führt.','2018-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (316,'mercedes-benz-glb-x247','MBUX-Infotainmentsystem','Gelegentliche Softwarefehler, Abstürze oder langsame Reaktionen des Systems. Betrifft vor allem frühe Baujahre.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (317,'mercedes-benz-glb-x247','Knarzgeräusche im Innenraum','Berichte über Knarz- oder Klappergeräusche, insbesondere aus dem Bereich des Armaturenbretts oder der Türverkleidungen.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (318,'mercedes-benz-glb-x247','12V-Batterie','Vereinzelt Berichte über frühzeitige Entladung oder Defekte der 12V-Starterbatterie, was zu Startproblemen führen kann.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (319,'mercedes-benz-ml-klasse-w163','Rost','Besonders anfällig sind Radläufe, Schwellerschweller, Türkanten und der Bereich um die Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (320,'mercedes-benz-ml-klasse-w163','Elektronik','Probleme mit Fensterhebern, Zentralverriegelung, Klimaanlage und dem Kombiinstrument.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (321,'mercedes-benz-ml-klasse-w163','Fahrwerk','Verschleiß an Stoßdämpfern, Querlenkern und Spurstangenköpfen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (322,'mercedes-benz-ml-klasse-w163','Automatikgetriebe','Bei einigen Modellen kann es zu Schaltproblemen oder Ausfällen kommen, insbesondere bei hoher Laufleistung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (323,'mercedes-benz-ml-klasse-w164','Luftfederung (Airmatic)','Defekte Luftfedern (Luftbälge), Kompressor oder Ventilblock können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders die vorderen Luftfedern sind anfällig.','Alle Baujahre, insbesondere ältere Fahrzeuge mit höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (324,'mercedes-benz-ml-klasse-w164','Automatikgetriebe (7G-Tronic)','Probleme mit der Elektronik (Schaltplatte/EHS-Einheit) oder dem Drehmomentwandler können zu Ruckeln, Schaltverzögerungen oder Notlauf führen. Ölverlust am Getriebe ist ebenfalls möglich.','Alle Baujahre, insbesondere frühe Modelle.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (325,'mercedes-benz-ml-klasse-w164','Dieselmotoren (OM642 V6 CDI)','Undichtigkeiten am Ölkühler (oft durch defekte Dichtungen), defekte Drallklappen im Ansaugkrümmer, Injektorenprobleme und Turboladerschäden sind bekannt. Auch der Partikelfilter kann sich zusetzen.','Alle Baujahre, insbesondere bei mangelnder Wartung oder Kurzstreckenbetrieb.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (326,'mercedes-benz-ml-klasse-w164','Rost','Rost kann an der Heckklappe (insbesondere unter der Chromleiste), an den Türkanten, Radläufen und am Unterboden auftreten, obwohl der W164 im Vergleich zum W163 verbessert wurde.','Spätere Baujahre und Fahrzeuge, die Streusalz ausgesetzt waren.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (327,'mercedes-benz-ml-klasse-w164','Elektronik','Diverse Elektronikprobleme wie Fehlfunktionen der Parksensoren, des Navigationssystems, der Fensterheber oder des Keyless-Go-Systems können auftreten.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (328,'mercedes-benz-ml-klasse-w166','Luftfederung (Airmatic)','Defekte an den Luftfederbälgen oder dem Kompressor können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders betroffen sind die vorderen Federbeine.','2011-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (329,'mercedes-benz-ml-klasse-w166','Automatikgetriebe (7G-Tronic Plus)','Ruckeln beim Schalten, verzögerte Gangwechsel oder Notlauf können auf Probleme mit der Getriebesteuerung (Mechatronik) oder dem Drehmomentwandler hindeuten.','2011-2013','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (330,'mercedes-benz-ml-klasse-w166','AdBlue-System','Fehlermeldungen bezüglich des AdBlue-Systems, verstopfte Injektoren oder defekte Sensoren können auftreten, was im schlimmsten Fall zu einem Startverbot des Motors führen kann.','2011-2015 (insbesondere Dieselmodelle)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (331,'mercedes-benz-ml-klasse-w166','Elektronik','Vereinzelt können Fehlfunktionen der Bordelektronik, des Infotainmentsystems (COMAND) oder der Assistenzsysteme auftreten.','2011-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (332,'mercedes-benz-ml-klasse-w166','Bremsanlage','Überdurchschnittlicher Verschleiß von Bremsscheiben und -belägen, insbesondere bei leistungsstärkeren Modellen oder sportlicher Fahrweise.','2011-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (333,'mercedes-benz-gle-w166-facelift','Getriebe (Automatik)','Gelegentliche Schaltprobleme, Ruckeln oder Aussetzer, insbesondere bei höheren Laufleistungen.','2015-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (334,'mercedes-benz-gle-w166-facelift','Elektronik','Probleme mit dem Infotainmentsystem, Ausfälle von Sensoren oder Steuergeräten.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (335,'mercedes-benz-gle-w166-facelift','Fahrwerk (Luftfederung)','Undichtigkeiten an Luftbälgen oder Kompressorprobleme, was zu Absinken des Fahrzeugs führt.','2015-2019','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (336,'mercedes-benz-gle-coupé-c292','Abgasrückführung (AGR)','Verkokung des AGR-Ventils und des Kühlers, was zu Leistungsverlust und erhöhten Emissionen führt.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (337,'mercedes-benz-gle-coupé-c292','Partikelfilter (DPF)','Verstopfung des Partikelfilters, insbesondere bei Kurzstreckenfahrzeugen, was zu Fehlermeldungen und Leistungsabfall führt.','2015-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (338,'mercedes-benz-gle-coupé-c292','Luftfederung (AIRMATIC)','Undichtigkeiten an Luftbälgen, defekte Kompressoren oder Steuergeräte können zu Absacken des Fahrzeugs und Fehlermeldungen führen.','2015-2019','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (339,'mercedes-benz-gle-coupé-c292','Getriebe (Automatik 7G-TRONIC PLUS / 9G-TRONIC)','Ruckeln beim Schalten, Probleme mit dem Drehmomentwandler oder dem Getriebesteuergerät.','2015-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (340,'mercedes-benz-gle-w167','Infotainmentsystem (MBUX)','Gelegentliche Software-Aussetzer, träge Reaktionen oder Probleme mit der Sprachsteuerung.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (341,'mercedes-benz-gle-w167','Getriebe (9G-TRONIC)','Ruckelige Schaltvorgänge, insbesondere bei niedrigen Geschwindigkeiten oder im Stadtverkehr.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (342,'mercedes-benz-gle-w167','Luftfederung (AIRMATIC)','Ausfall von Luftbälgen oder Kompressor, was zu einem Absinken des Fahrzeugs führt.','2019-2023','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (343,'mercedes-benz-gle-coupé-c167','Luftfederung (AIRMATIC)','Bei einigen Modellen kann es zu Undichtigkeiten oder Ausfällen der Luftfederung kommen, was zu einem Absinken des Fahrzeugs führt.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (344,'mercedes-benz-gle-coupé-c167','Infotainmentsystem (MBUX)','Gelegentliche Software-Probleme, Abstürze oder träge Reaktionen des Touchscreens und der Sprachsteuerung.','2019-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (345,'mercedes-benz-gle-coupé-c167','Getriebe (9G-TRONIC)','Bei einigen Fahrzeugen wurden Probleme mit dem Automatikgetriebe gemeldet, wie z.B. Ruckeln beim Schalten oder verzögerte Reaktionen.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (346,'mercedes-benz-gl-klasse-x164','Luftfederung (Airmatic)','Defekte an Kompressor, Luftbälgen oder Ventilen führen zu ungleichmäßigem Niveau oder komplettem Absinken des Fahrzeugs. Besonders betroffen sind die vorderen Federbeine.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (347,'mercedes-benz-gl-klasse-x164','Automatikgetriebe (7G-Tronic)','Probleme mit dem Schaltschieberkasten (Elektrohydraulische Steuereinheit), was zu Schaltrucken, Notlauf oder Getriebeschäden führen kann. Ölverlust an der Getriebedurchführung ist ebenfalls bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (348,'mercedes-benz-gl-klasse-x164','Rost','Rostbildung kann an der Heckklappe (insbesondere unter der Chromleiste), an den Türkanten und im Bereich der Radläufe auftreten.','Ältere Baujahre, insbesondere vor Facelift','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (349,'mercedes-benz-gl-klasse-x164','Injektoren (Dieselmotoren)','Undichte oder defekte Injektoren können zu Leistungsverlust, unrundem Motorlauf und erhöhtem Kraftstoffverbrauch führen. Oft erkennbar an Rußablagerungen im Motorraum.','Alle Baujahre, besonders OM642','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (350,'mercedes-benz-gl-klasse-x164','Turbolader (Dieselmotoren)','Defekte am Turbolader, oft durch verstopfte Ölleitungen oder Lagerschäden, können zu Leistungsverlust und erhöhtem Ölverbrauch führen.','Alle Baujahre, besonders OM642','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (351,'mercedes-benz-gl-klasse-x164','Lenkung','Verschleiß an Spurstangenköpfen und Querlenkerlagern kann zu Poltergeräuschen und unpräzisem Lenkverhalten führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (352,'mercedes-benz-gls-x166','Luftfederung (AIRMATIC)','Probleme mit Kompressor, Luftbälgen und Sensoren können zu Absinken des Fahrzeugs oder Fehlermeldungen führen.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (353,'mercedes-benz-gls-x166','Elektronik','Diverse Fehlermeldungen im Kombiinstrument oder Infotainmentsystem, Probleme mit Steuergeräten.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (354,'mercedes-benz-gls-x166','Rost','An Radläufen, Schwellern und an der Heckklappe kann Rostbildung auftreten, insbesondere bei Fahrzeugen mit geringer Pflege.','Gesamte Baureihe','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (355,'mercedes-benz-gls-x167','MBUX-Infotainmentsystem','Gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen des Systems. Dies kann die Bedienung von Navigation, Radio oder Fahrzeugeinstellungen beeinträchtigen.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (356,'mercedes-benz-gls-x167','Luftfederung (Airmatic/E-Active Body Control)','Vereinzelt Berichte über Undichtigkeiten oder Kompressorprobleme, die zu einem Absinken des Fahrzeugniveaus oder Fehlermeldungen führen können. Dies kann den Fahrkomfort und die Fahrsicherheit beeinträchtigen.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (357,'mercedes-benz-gls-x167','Elektrische Heckklappe','Manchmal funktioniert die elektrische Heckklappe nicht zuverlässig, öffnet oder schließt nicht vollständig oder reagiert nicht auf Befehle.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (358,'mercedes-benz-sl-r230','ABC-Fahrwerk (Active Body Control)','Hydrauliklecks, defekte Federbeine, Pumpenversagen. Kann zu hohen Reparaturkosten führen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (359,'mercedes-benz-sl-r230','Rost','Radläufe, Schweller, Unterboden, Türkanten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (360,'mercedes-benz-sl-r230','Elektronik','Probleme mit Steuergeräten, Sensoren, Fensterhebern, Dachhydraulik.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (361,'mercedes-benz-sl-r230','Getriebe','Schaltprobleme, Ruckeln, insbesondere bei älteren Automatikgetrieben.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (362,'mercedes-benz-sl-r231','ABC-Fahrwerk (Active Body Control)','Bei Fahrzeugen mit dem optionalen ABC-Fahrwerk können Undichtigkeiten an den Federbeinen, der Pumpe oder den Leitungen auftreten, was zu einem Absinken des Fahrzeugs oder Fehlermeldungen führt. Reparaturen sind sehr kostspielig.','Alle Baujahre mit ABC-Fahrwerk','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (363,'mercedes-benz-sl-r231','Getriebe (7G-Tronic / 9G-Tronic)','Insbesondere bei der 7G-Tronic können Schaltrucke, verzögerte Gangwechsel oder Getriebeprobleme auftreten. Die 9G-Tronic ist robuster, aber auch hier sind Probleme nicht gänzlich ausgeschlossen. Regelmäßige Getriebeölwechsel sind entscheidend.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (364,'mercedes-benz-sl-r231','Elektronik','Wie bei vielen modernen Mercedes-Modellen kann es zu sporadischen Elektronikproblemen kommen, z.B. Ausfälle des Infotainmentsystems, Fehlermeldungen von Sensoren oder Problemen mit der Keyless-Go-Funktion.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (365,'mercedes-benz-sl-r231','Verdeckmechanismus','Obwohl der R231 als robuster gilt als sein Vorgänger, können bei älteren Fahrzeugen oder mangelnder Pflege Probleme mit dem Variodach-Mechanismus auftreten, z.B. Undichtigkeiten, Sensorfehler oder Schwergängigkeit.','Spätere Baujahre oder Fahrzeuge mit hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (366,'mercedes-benz-v-klasse-w638','Rost','Starke Rostbildung an Karosserie (Radläufe, Schweller, Heckklappe, Türen) und tragenden Teilen. Besonders betroffen sind Fahrzeuge vor dem Facelift.','1996-2003','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (367,'mercedes-benz-v-klasse-w638','Automatikgetriebe','Probleme mit dem Automatikgetriebe, insbesondere bei den Dieselmodellen. Anfällig für Schaltrucke, Notlauf und Defekte.','1996-2003','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (368,'mercedes-benz-v-klasse-w638','Luftfederung (Hinterachse)','Defekte an den Luftbälgen und dem Kompressor der optionalen Luftfederung, was zu einem Absinken des Hecks führt.','1996-2003','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (369,'mercedes-benz-v-klasse-w638','Bremsanlage','Überdurchschnittlicher Verschleiß von Bremsscheiben und -belägen, teilweise auch Probleme mit festrostenden Bremssätteln.','1996-2003','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (370,'mercedes-benz-v-klasse-w638','Elektronik','Diverse kleinere Elektronikprobleme, z.B. mit Fensterhebern, Zentralverriegelung oder der Instrumentenbeleuchtung.','1996-2003','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (371,'mercedes-benz-viano-w639','Rost','Anfällig für Korrosion, besonders an Radläufen, Schwellern, Türen und der Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (372,'mercedes-benz-viano-w639','Automatikgetriebe','Kann bei einigen Modellen Probleme bereiten, wie Ruckeln oder Ausfälle. Regelmäßiger Getriebeölwechsel ist wichtig.','Variiert, aber häufiger bei älteren Modellen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (373,'mercedes-benz-viano-w639','Klimaanlage','Ausfälle des Klimakompressors oder Undichtigkeiten im System sind möglich.','Variiert','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (374,'mercedes-benz-viano-w639','Elektronik','Vereinzelte Probleme mit der Bordelektronik, wie Fehlermeldungen oder Ausfälle von Sensoren.','Variiert','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (375,'mercedes-benz-v-klasse-w447','Getriebe (Automatik)','Gelegentliche Schaltprobleme, Ruckeln oder Aussetzer, insbesondere bei älteren Modellen oder hoher Laufleistung.','2014-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (376,'mercedes-benz-v-klasse-w447','AdBlue-System','Probleme mit der AdBlue-Pumpe oder dem Sensor, was zu Fehlermeldungen und Einschränkungen der Motorleistung führen kann.','2016-2020','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (377,'mercedes-benz-v-klasse-w447','Elektronik (Infotainment/Steuergeräte)','Sporadische Ausfälle des Infotainmentsystems, Navigationsprobleme oder Fehlermeldungen von diversen Steuergeräten.','2014-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (387,'mercedes-benz-cla-c117','Automatikgetriebe (7G-DCT)','Ruckeln beim Anfahren, Schaltverzögerungen, gelegentliche Aussetzer oder Notlauf. Betrifft vor allem frühe Baujahre.','2013-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (388,'mercedes-benz-cla-c117','Bremsen','Überdurchschnittlicher Verschleiß von Bremsbelägen und -scheiben, insbesondere bei sportlicher Fahrweise. Quietschen der Bremsen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (389,'mercedes-benz-cla-c117','Fahrwerk','Poltern oder Klappern von der Vorderachse, oft verursacht durch verschlissene Querlenkerlager oder Stabilisatorstreben.','2013-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (390,'mercedes-benz-cla-c117','Elektronik','Vereinzelt Berichte über Ausfälle des Infotainmentsystems, Fehlermeldungen von Sensoren oder Probleme mit der Start-Stopp-Automatik.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (391,'mercedes-benz-cla-c117','Dieselmotoren (OM651)','Probleme mit Injektoren und der Hochdruckpumpe, insbesondere bei frühen Modellen. Kann zu unrundem Motorlauf oder Leistungsverlust führen.','2013-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (392,'mercedes-benz-cla-shooting-brake-x117','Automatikgetriebe (7G-DCT)','Vereinzelt Berichte über Ruckeln, Schaltprobleme oder Undichtigkeiten, insbesondere bei höheren Laufleistungen. Kann zu teuren Reparaturen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (393,'mercedes-benz-cla-shooting-brake-x117','Bremsanlage','Überdurchschnittlicher Verschleiß von Bremsbelägen und -scheiben, insbesondere an der Vorderachse. Kann bei sportlicher Fahrweise verstärkt auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (394,'mercedes-benz-cla-shooting-brake-x117','Elektronik','Gelegentliche Fehlermeldungen oder Ausfälle von Infotainment-System, Sensoren oder Assistenzsystemen. Oft durch Software-Updates behebbar.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (395,'mercedes-benz-cla-shooting-brake-x117','Fahrwerk','Bei Fahrzeugen mit Sportfahrwerk oder AMG Line kann es zu erhöhtem Verschleiß an Querlenkern oder Stabilisatorlagern kommen, was sich durch Poltergeräusche äußert.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (396,'mercedes-benz-cla-c118','MBUX-Infotainmentsystem','Gelegentliche Software-Probleme, Abstürze oder langsame Reaktionen des Systems. Betrifft vor allem frühe Baujahre.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (397,'mercedes-benz-cla-c118','Bremsen','Bei einigen Fahrzeugen erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (398,'mercedes-benz-cla-c118','Knarzgeräusche im Innenraum','Vereinzelt Berichte über Knarz- oder Klappergeräusche aus dem Armaturenbrett oder den Türverkleidungen.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (399,'mercedes-benz-cla-shooting-brake-x118','Infotainmentsystem MBUX','Gelegentliche Software-Probleme, Abstürze oder langsame Reaktionszeiten.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (400,'mercedes-benz-cla-shooting-brake-x118','Getriebe (Doppelkupplung)','Ruckeln beim Anfahren oder Schaltprobleme bei einigen Modellen.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (401,'mercedes-benz-cla-shooting-brake-x118','Partikelfilter (Diesel)','Verstopfung des Partikelfilters bei häufigen Kurzstreckenfahrten.','2019-2023','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (402,'mercedes-benz-gla-x156','Automatikgetriebe (7G-DCT)','Vereinzelt Berichte über Ruckeln, Schaltverzögerungen oder Geräusche, insbesondere bei Modellen der frühen Baujahre. Software-Updates oder in seltenen Fällen Getriebetausch können Abhilfe schaffen.','2013-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (403,'mercedes-benz-gla-x156','Bremsen','Überdurchschnittlicher Verschleiß von Bremsbelägen und -scheiben, insbesondere bei sportlicher Fahrweise oder Modellen mit stärkeren Motoren. Dies ist jedoch oft nutzungsabhängig.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (404,'mercedes-benz-gla-x156','Fahrwerk','Bei einigen Fahrzeugen können Geräusche von der Vorderachse auftreten, oft verursacht durch verschlissene Querlenkerlager oder Stabilisatorbuchsen.','2013-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (405,'mercedes-benz-gla-x156','Elektronik','Gelegentliche Fehlermeldungen oder Ausfälle von Infotainmentsystem, Navigationssystem oder Sensoren. Oft durch Software-Updates behebbar.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (406,'mercedes-benz-glc-x253','Hinterachsgetriebe','Bei einigen Modellen kann es zu Geräuschen oder Undichtigkeiten am Hinterachsgetriebe kommen, was auf Materialermüdung oder Fertigungsfehler hindeutet. Dies kann bis zum Getriebeschaden führen.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (407,'mercedes-benz-glc-x253','Luftfederung (AIR BODY CONTROL)','Probleme mit der Luftfederung, wie undichte Luftbälge oder defekte Kompressoren, können zu einem Absinken des Fahrzeugniveaus oder Fehlermeldungen führen. Reparaturen sind oft kostspielig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (408,'mercedes-benz-glc-x253','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse, wird häufiger berichtet. Dies kann zu vorzeitigem Austauschbedarf führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (409,'mercedes-benz-glc-x253','Infotainmentsystem (COMAND/MBUX)','Softwarefehler, Abstürze oder langsame Reaktionen des Infotainmentsystems können auftreten. Beim Facelift-Modell mit MBUX sind diese Probleme seltener, aber nicht ausgeschlossen.','2015-2019 (COMAND), vereinzelt 2019-2022 (MBUX)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (410,'mercedes-benz-g-klasse-w-460','Rost','Die Karosserie, insbesondere an Radläufen, Schwellern, Türen, Heckklappe und Rahmen, ist stark rostanfällig. Auch der Unterboden und die Federaufnahmen sind betroffen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (411,'mercedes-benz-g-klasse-w-460','Fahrwerk','Verschleiß an Achsen, Lenkung und Bremsen ist alters- und nutzungsbedingt häufig. Spiel in der Lenkung und ausgeschlagene Gelenke sind typisch.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (412,'mercedes-benz-g-klasse-w-460','Motor und Getriebe','Bei den älteren Motoren können Undichtigkeiten (Ölverlust) und Verschleiß an Einspritzpumpen (Diesel) auftreten. Die Schaltgetriebe sind robust, aber altersbedingter Verschleiß an Synchronringen ist möglich. Automatikgetriebe können bei mangelnder Wartung Probleme bereiten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (413,'mercedes-benz-g-klasse-w-460','Elektrik','Altersbedingte Probleme mit der Elektrik, wie korrodierte Kontakte, defekte Schalter oder Kabelbaumschäden, sind nicht ungewöhnlich.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (414,'mercedes-benz-g-klasse-w-461','Rost','Wie bei vielen älteren Geländewagen ist Rost ein großes Thema, insbesondere an Rahmen, Karosseriekanten, Türen und Radläufen. Regelmäßige Kontrolle und Vorsorge sind unerlässlich.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (415,'mercedes-benz-g-klasse-w-461','Antriebsstrang (Kardanwellen, Achsen)','Bei intensivem Geländeeinsatz oder mangelnder Wartung können Verschleiß an Kardanwellen, Achsen und Differentialen auftreten. Geräusche oder Vibrationen sind Warnzeichen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (416,'mercedes-benz-g-klasse-w-461','Bremsanlage','Verschleiß an Bremsbelägen und -scheiben ist normal, aber auch Bremssättel können festgehen oder Leitungen korrodieren, besonders bei Fahrzeugen, die viel im Gelände bewegt wurden.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (417,'mercedes-benz-g-klasse-w-461','Elektronik (selten, aber möglich)','Obwohl der W 461 im Vergleich zum W 463 sehr robust und einfach gehalten ist, können altersbedingt oder durch Feuchtigkeitseintritt Probleme mit der Elektrik (z.B. Beleuchtung, Fensterheber) auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (418,'mercedes-benz-g-klasse-w-463','Rost','Besonders an Türunterkanten, Heckklappe, Radläufen, Scheibenrahmen und im Bereich der Anbauteile. Rahmen und Karosserie sind getrennt, was zu Spaltkorrosion führen kann.','Alle Baujahre, besonders ältere Modelle ohne regelmäßige Pflege.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (419,'mercedes-benz-g-klasse-w-463','Elektronik','Fehlfunktionen von Steuergeräten, Sensoren (z.B. ABS, ESP), Fensterhebern, Zentralverriegelung und dem COMAND-System.','Besonders Modelle ab den späten 1990ern und frühen 2000ern.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (420,'mercedes-benz-g-klasse-w-463','Automatikgetriebe','Undichtigkeiten, Schaltprobleme, Ruckeln oder Notlauf. Besonders bei hohen Laufleistungen und mangelnder Getriebeölwartung.','Alle Baujahre, insbesondere bei starker Beanspruchung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (421,'mercedes-benz-g-klasse-w-463','Fahrwerk','Verschleiß an Stoßdämpfern, Federn, Querlenkern und Buchsen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','Alle Baujahre, abhängig von Fahrweise und Einsatzgebiet.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (422,'mercedes-benz-g-klasse-w-463','Motor (Diesel)','Bei den CDI-Motoren können Injektoren, Turbolader und die Hochdruckpumpe Probleme bereiten. Bei älteren Dieseln auch Undichtigkeiten.','Besonders 270 CDI, 400 CDI.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (423,'mercedes-benz-g-klasse-w-463','Motor (Benzin)','Bei den V8-Motoren können Zündkerzen, Zündspulen, Nockenwellensensoren und bei älteren Modellen auch die Motorkabelbäume Probleme verursachen.','Alle Baujahre, abhängig von Wartung.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (424,'mercedes-amg-gt-c190','Batterie','Die 12V-Batterie kann bei längeren Standzeiten oder seltener Nutzung schnell entladen sein, was zu Startproblemen führt. Dies ist bei Sportwagen mit vielen elektronischen Verbrauchern nicht unüblich.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (425,'mercedes-amg-gt-c190','Bremsen','Bei sportlicher Fahrweise oder Rennstreckeneinsatz kann der Verschleiß der Bremsbeläge und -scheiben (insbesondere bei den optionalen Keramikbremsen) hoch sein, was zu hohen Wartungskosten führt.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (426,'mercedes-amg-gt-c190','Reifen','Der Verschleiß der Hochleistungsreifen, insbesondere an der Hinterachse, kann bei sportlicher Fahrweise sehr hoch sein.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (430,'mercedes-amg-gt-c190','Infotainmentsystem (COMAND)','Gelegentlich können Softwarefehler oder Abstürze des COMAND-Systems auftreten. Dies ist meist durch ein Software-Update behebbar.','Frühe Baujahre (bis Facelift)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (437,'bmw-3er-e21','Rost','Der E21 ist sehr anfällig für Rost, insbesondere an Radläufen, Schwellern, Wagenheberaufnahmen, Türen, Kofferraumboden, Frontscheibenrahmen und den Federbeinaufnahmen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (438,'bmw-3er-e21','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt häufig. Die Hinterachslager können ausgeschlagen sein.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (439,'bmw-3er-e21','Bremsanlage','Festgehende Bremssättel, undichte Bremsleitungen und verschlissene Bremsscheiben/Beläge sind typische Alterserscheinungen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (440,'bmw-3er-e21','Motor (Vergaser)','Bei den Vergasermotoren (insbesondere 316, 318, 320) können Undichtigkeiten, Falschluft und verschlissene Vergaser zu Startschwierigkeiten und unrundem Lauf führen.','Alle Baujahre mit Vergasermotoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (441,'bmw-3er-e21','Elektrik','Altersbedingte Probleme mit Kabelbäumen, Korrosion an Steckverbindungen, Ausfall von Instrumenten oder Beleuchtung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (442,'bmw-3er-e30','Karosserie','Rostbefall an Radläufen, Schwellern, Wagenheberaufnahmen, Heckklappe, Batteriekasten.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (443,'bmw-3er-e30','Fahrwerk','Verschleiß an Querlenkerlagern, Stoßdämpfern, Gummilagern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (444,'bmw-3er-e30','Kühlsystem','Undichtigkeiten am Kühler, defekte Wasserpumpe, poröse Schläuche.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (451,'bmw-3er-e46','Hinterachsaufhängung (HA-Achsträger)','Risse im Blech der Karosserie an den Befestigungspunkten des Hinterachsträgers. Betrifft vor allem frühe Baujahre und leistungsstärkere Modelle.','1998-2002','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (452,'bmw-3er-e46','Querlenker und Spurstangen','Verschleiß der Gummilager und Kugelgelenke führt zu Poltergeräuschen, unpräzisem Fahrverhalten und erhöhtem Reifenverschleiß.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (453,'bmw-3er-e46','Fensterheber','Defekte Mechanik oder Motoren, insbesondere bei Coupé und Cabrio.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (454,'bmw-3er-e46','Rost','Kann an Radläufen, Heckklappe (Touring), Türkanten und unter den Dichtungen auftreten.','Spätere Baujahre und Fahrzeuge mit schlechter Pflege','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (455,'bmw-3er-e46','Kühlsystem','Verschleiß von Wasserpumpe, Thermostat, Ausgleichsbehälter und Schläuchen kann zu Überhitzung führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (456,'bmw-3er-e46','Vanossystem (Nockenwellenverstellung)','Verschleiß der Dichtringe oder Magnetventile kann zu Leistungsverlust, unruhigem Leerlauf und erhöhtem Verbrauch führen.','Alle Baujahre mit Vanos','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (457,'bmw-3er-e90','Steuerkette (N47 Dieselmotoren)','Bei den 4-Zylinder-Dieselmotoren (N47) kann es zu Problemen mit der Steuerkette kommen, die zu einem Motorschaden führen können. Auffällig ist ein Rasseln aus dem Motorraum.','2007-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (458,'bmw-3er-e90','Injektoren/Hochdruckpumpe (N54 Benzinmotoren)','Die Direkteinspritzer-Benzinmotoren (insbesondere N54) können Probleme mit den Injektoren und der Hochdruckpumpe aufweisen, was zu Leistungsverlust und unrundem Motorlauf führt.','2006-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (459,'bmw-3er-e90','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (460,'bmw-3er-e90','Elektronik (iDrive-System)','Frühe Versionen des iDrive-Systems können Ausfälle oder Fehlfunktionen zeigen.','2005-2007','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (461,'bmw-3er-e90','Turbolader (Dieselmotoren)','Bei einigen Dieselmotoren kann der Turbolader vorzeitig verschleißen, was sich durch Leistungsverlust und erhöhten Ölverbrauch äußert.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (462,'bmw-3er-f30','Steuerkette (N47 Dieselmotoren)','Bei den Vierzylinder-Dieselmotoren (N47) kann es zu Problemen mit der Steuerkette kommen, die zu einem Motorschaden führen können. Dies äußert sich oft durch rasselnde Geräusche aus dem Motorraum.','2011-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (463,'bmw-3er-f30','Turbolader (N20/N26 Benzinmotoren)','Bei den Vierzylinder-Benzinmotoren (N20/N26) können Turboladerschäden auftreten, oft verbunden mit erhöhtem Ölverbrauch oder Leistungsverlust.','2011-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (464,'bmw-3er-f30','Elektronik/Infotainment','Vereinzelt können Störungen im iDrive-System, Ausfälle von Sensoren oder Probleme mit der Fahrzeugelektronik auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (465,'bmw-3er-f30','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern oder Spurstangenköpfen kann zu Poltergeräuschen oder unpräzisem Fahrverhalten führen.','Ab ca. 80.000 km Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (469,'bmw-5er-e12','Rost','Der E12 ist stark anfällig für Rost, insbesondere an Radläufen, Schwellern, Türen, Kotflügeln, dem Bereich um die Scheinwerfer und die Heckscheibe sowie an den Wagenheberaufnahmen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (470,'bmw-5er-e12','Motor','Bei den M20-Motoren (ab 520/6) können Probleme mit der Nockenwelle und den Kipphebeln auftreten. Die M30-Motoren sind generell robust, aber auf regelmäßige Wartung angewiesen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (471,'bmw-5er-e12','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt häufig. Auch die Hinterachsaufnahmen können bei starker Beanspruchung Risse aufweisen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (472,'bmw-5er-e12','Elektrik','Altersbedingte Probleme mit Kabelbäumen, Sicherungskästen und einzelnen elektrischen Komponenten (Fensterheber, Beleuchtung) sind möglich.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (473,'bmw-5er-e28','Rost','Typische Roststellen finden sich an den Radläufen, Schwellern, Wagenheberaufnahmen, Türen (unten), Heckblech und im Bereich der Frontscheibe.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (474,'bmw-5er-e28','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt häufig. Die Hinterachsaufhängung kann ausgeschlagen sein.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (475,'bmw-5er-e28','Elektronik','Probleme mit der Elektrik können auftreten, insbesondere bei der Zentralverriegelung, Fensterhebern und dem Kombiinstrument (Pixelfehler, defekte Anzeigen).','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (476,'bmw-5er-e28','Motor (speziell M30-Motoren)','Ölverlust an Dichtungen (Ventildeckel, Ölwanne), defekte Wasserpumpen und Thermostate. Bei mangelnder Wartung können sich die Kipphebelwellen einlaufen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (477,'bmw-5er-e28','Bremsanlage','Festsitzende Bremssättel und verschlissene Bremsschläuche sind altersbedingt häufig.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (478,'bmw-5er-e34','Rost','Rost kann an den Radläufen, Schwellern, Wagenheberaufnahmen, Tankdeckelbereich und unter den Dichtungen der Heckklappe (Touring) auftreten.','Alle Baujahre, besonders bei mangelnder Pflege.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (479,'bmw-5er-e34','Fahrwerk','Verschleiß an Querlenkern, Spurstangen, Koppelstangen und Stoßdämpfern führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre, alters- und laufleistungsbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (480,'bmw-5er-e34','Kühlsystem','Undichtigkeiten an Kühler, Wasserpumpe, Thermostatgehäuse und Schläuchen. Anfälligkeit für Überhitzung, besonders bei den Sechszylindermotoren.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (481,'bmw-5er-e34','Elektrik/Elektronik','Probleme mit dem Kombiinstrument (Pixelfehler), Fensterhebern, Zentralverriegelung und der Klimaanlage.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (482,'bmw-5er-e34','Motor (M50-Motoren)','Probleme mit der VANOS-Einheit (Geräusche, Leistungsverlust) und der Zylinderkopfdichtung bei Überhitzung.','Ab 1992 (M50-Motoren).','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (483,'bmw-5er-e34','Motor (V8-Motoren M60)','Verschleiß der Nikasil-Beschichtung der Zylinderlaufbahnen bei Verwendung von schwefelhaltigem Kraftstoff (betrifft hauptsächlich frühe Modelle und bestimmte Märkte).','1992-1994 (M60B30/M60B40).','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (484,'bmw-5er-e39','Vorderachse','Verschleiß an Querlenkern, Spurstangen und Koppelstangen führt zu Poltergeräuschen und unpräzisem Fahrverhalten. Besonders betroffen sind die Gummilager.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (485,'bmw-5er-e39','Hinterachse','Verschleiß der Integrallenker und Tonnenlager kann zu instabilem Fahrverhalten führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (486,'bmw-5er-e39','Kühlsystem','Alterung von Kühlerschläuchen, Thermostatgehäuse (oft aus Kunststoff), Wasserpumpe und Kühler kann zu Undichtigkeiten und Überhitzung führen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (487,'bmw-5er-e39','Rost','Rostbildung an Heckklappe (insbesondere Touring), Türkanten, Wagenheberaufnahmen und unter den Kotflügeln.','Alle Baujahre, besonders ältere Modelle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (488,'bmw-5er-e39','Pixelfehler im Kombiinstrument/MID','Ausfall einzelner Pixel im Display des Kombiinstruments oder des Multi-Informations-Displays (MID) ist ein häufiges Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (489,'bmw-5er-e39','Fensterheber','Defekte Fensterhebermechanismen, oft durch gebrochene Kunststoffteile oder Seilzüge.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (490,'bmw-5er-e39','Servolenkung','Undichtigkeiten an Servoleitungen oder der Servopumpe können auftreten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (491,'bmw-5er-e39','Dieselmotoren (M57)','Probleme mit Drallklappen im Ansaugkrümmer (können abbrechen und Motorschäden verursachen), Injektoren und Turbolader.','Alle Baujahre mit M57-Motor','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (492,'bmw-5er-e60','iDrive-System','Frühe Versionen des iDrive-Systems können fehlerhaft sein, abstürzen oder die Bedienung erschweren. Software-Updates können helfen, aber Hardwaredefekte sind möglich.','2003-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (493,'bmw-5er-e60','Elektronik (allgemein)','Diverse Elektronikprobleme, z.B. mit Fensterhebern, Zentralverriegelung, PDC-Sensoren oder dem Lichtmodul (FRM).','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (494,'bmw-5er-e60','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, besonders bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (495,'bmw-5er-e60','Dieselmotoren (N47, M57)','Der N47-Motor (4-Zylinder-Diesel) ist bekannt für Probleme mit der Steuerkette. Der M57-Motor (6-Zylinder-Diesel) kann Probleme mit Drallklappen im Ansaugtrakt, Turboladerdefekten und Injektoren aufweisen.','N47: ab 2007; M57: Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (496,'bmw-5er-e60','Automatikgetriebe','Bei hoher Laufleistung können Schaltrucke oder Getriebeschäden auftreten, oft durch unzureichende oder fehlende Getriebeölwechsel.','Alle Baujahre, besonders ab 150.000 km','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (497,'bmw-5er-e60','Kabelbaum Heckklappe (Touring E61)','Bruch des Kabelbaums in der Heckklappe führt zu Ausfällen von Heckscheibenheizung, Scheibenwischer, Radioempfang oder der Heckklappenöffnung.','Alle Baujahre des E61 Touring','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (498,'bmw-5er-e60','V10-Motor (M5)','Der S85-V10-Motor des M5 ist anfällig für Lagerschäden (Pleuellager), Vanos-Pumpendefekte und Drosselklappensteller-Probleme. Hoher Wartungsaufwand und teure Reparaturen.','Alle Baujahre des M5','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (499,'bmw-5er-f10','Steuerkette (N47 Dieselmotoren)','Bei den Vierzylinder-Dieselmotoren (N47) kann es zu Problemen mit der Steuerkette kommen, die zu einem Motorschaden führen können. Dies äußert sich oft durch rasselnde Geräusche.','2010-2013 (insbesondere frühe Baujahre)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (500,'bmw-5er-f10','Injektoren und Hochdruckpumpe (N54/N63 Benzinmotoren)','Bei den frühen Sechszylinder-Turbobenzinern (N54) und den V8-Motoren (N63) können Injektoren und die Hochdruckpumpe ausfallen, was zu unrundem Motorlauf und Leistungsverlust führt.','2010-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (501,'bmw-5er-f10','Fahrwerk (Vorderachse)','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre (insbesondere bei höherer Laufleistung)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (502,'bmw-5er-f10','Elektronik (iDrive, Komfortfunktionen)','Gelegentliche Ausfälle oder Fehlfunktionen des iDrive-Systems, der Komfortzugang oder anderer elektronischer Komponenten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (503,'bmw-5er-f10','Automatikgetriebe (ZF 8HP)','Obwohl das ZF 8HP-Getriebe generell robust ist, können bei sehr hoher Laufleistung oder mangelnder Wartung (Ölwechsel) Schaltprobleme auftreten.','Alle Baujahre (insbesondere bei sehr hoher Laufleistung)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (504,'bmw-5er-g30','Infotainmentsystem (iDrive)','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des iDrive-Systems. Betrifft meist frühe Baujahre.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (505,'bmw-5er-g30','Fahrwerk (Luftfederung hinten)','Bei Modellen mit optionaler Luftfederung an der Hinterachse (insbesondere Touring) können Defekte an den Luftbälgen oder dem Kompressor auftreten, was zu einem Absinken des Hecks führt.','Alle Baujahre mit Luftfederung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (506,'bmw-5er-g30','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder Modellen mit stärkeren Motoren. Dies ist jedoch oft nutzungsabhängig.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (507,'bmw-7er-e23','Rost','An Radläufen, Schwellern, Türen und Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (508,'bmw-7er-e23','Elektronik','Probleme mit der Bordelektronik, insbesondere bei älteren Modellen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (509,'bmw-7er-e23','Getriebe','Automatikgetriebe können anfällig sein.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (510,'bmw-7er-e32','Automatikgetriebe','Verschleiß und Defekte, insbesondere bei hohen Laufleistungen und mangelnder Wartung (Ölwechsel).','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (511,'bmw-7er-e32','Rost','Kann an Radläufen, Schwellern, Wagenheberaufnahmen und unter den Dichtungen auftreten, besonders bei schlecht gepflegten Exemplaren.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (512,'bmw-7er-e32','Elektronik','Probleme mit dem Bordcomputer, Fensterhebern, Klimaanlage und anderen elektrischen Komponenten aufgrund von Alterung und Korrosion.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (513,'bmw-7er-e32','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (514,'bmw-7er-e32','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe, was zu Überhitzung führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (515,'bmw-7er-e38','Vorderachse','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (516,'bmw-7er-e38','Automatikgetriebe','Bei hohen Laufleistungen können Schaltprobleme, Ruckeln oder Ausfälle auftreten, insbesondere bei mangelnder Getriebewartung (Ölwechsel).','Alle Baujahre, insbesondere Modelle mit 5HP24-Getriebe (V8-Motoren)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (517,'bmw-7er-e38','Elektronik','Pixelfehler im Kombiinstrument und im Bordmonitor sind häufig. Auch Probleme mit Fensterhebern, Zentralverriegelung und dem Navigationssystem können auftreten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (518,'bmw-7er-e38','Rost','Rost kann an den Türkanten, Radläufen, der Heckklappe und unter den Zierleisten auftreten, insbesondere bei schlecht gepflegten Exemplaren.','Alle Baujahre, verstärkt bei älteren Fahrzeugen','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (519,'bmw-7er-e38','Kühlsystem','Alterung von Schläuchen, Thermostatgehäuse und Wasserpumpe kann zu Undichtigkeiten und Überhitzung führen.','Alle Baujahre, insbesondere bei V8-Motoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (520,'bmw-7er-e65/e66','iDrive-System','Frühe Versionen des iDrive-Systems können komplex in der Bedienung sein und neigen zu Softwarefehlern oder Ausfällen des Controllers/Bildschirms.','2001-2004 (vor Facelift)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (521,'bmw-7er-e65/e66','Elektronik (allgemein)','Diverse elektronische Probleme, z.B. mit Fensterhebern, Zentralverriegelung, Parksensoren, Lichtmodulen oder der Batterieentladung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (522,'bmw-7er-e65/e66','Automatikgetriebe (ZF 6HP)','Kann bei hohen Laufleistungen oder mangelnder Wartung (Ölwechsel) zu Ruckeln, Schaltproblemen oder Ausfällen neigen. Besonders die Mechatronik ist anfällig.','Alle Baujahre, insbesondere bei hohen Laufleistungen','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (523,'bmw-7er-e65/e66','Fahrwerk (Luftfederung hinten)','Defekte an den Luftfedern oder dem Kompressor können zu einer einseitig abgesenkten Karosserie oder einem Ausfall der Niveauregulierung führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (524,'bmw-7er-e65/e66','Motor (V8-Benziner N62)','Bekannt für Probleme mit Ventilschaftdichtungen (hoher Ölverbrauch), Kühlwasserrohren (Leckagen) und VANOS-Einheiten.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (525,'bmw-7er-f01/f02','Luftfederung (Hinterachse)','Undichtigkeiten an den Luftbälgen oder Kompressorprobleme können zu einem Absinken des Fahrzeugs führen.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (526,'bmw-7er-f01/f02','Elektronik (Infotainment, Steuergeräte)','Diverse elektronische Störungen, Ausfälle von Displays oder Steuergeräten sind möglich.','Gesamte Baureihe','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (527,'bmw-7er-f01/f02','Turbolader (Dieselmotoren)','Bei einigen Dieselmotoren kann es zu Problemen mit dem Turbolader kommen, insbesondere bei hoher Laufleistung.','2008-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (528,'bmw-7er-g11/g12','Luftfederung','Probleme mit Luftbälgen und Kompressor können zu Absinken des Fahrzeugs oder Fehlermeldungen führen.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (529,'bmw-7er-g11/g12','Elektronik','Diverse elektronische Störungen, z.B. im Infotainmentsystem, bei Sensoren oder Steuergeräten.','2015-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (530,'bmw-7er-g11/g12','Kühlmittelverlust','Undichtigkeiten im Kühlsystem, insbesondere an Leitungen und Anschlüssen.','2016-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (531,'audi-a1-8x','Steuerkette (1.2 TFSI, 1.4 TFSI)','Bei den frühen TFSI-Motoren kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen. Dies kann zu Motorschäden führen.','Vor allem Modelle bis ca. 2012/2013','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (532,'audi-a1-8x','Wasserpumpe (TFSI-Motoren)','Undichtigkeiten oder Defekte an der Wasserpumpe sind keine Seltenheit, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (533,'audi-a1-8x','DSG-Getriebe (S tronic)','Bei den S tronic Doppelkupplungsgetrieben (insbesondere 7-Gang DQ200) können Probleme mit der Mechatronik oder dem Kupplungspaket auftreten, die sich durch Ruckeln, Schaltverzögerungen oder Ausfälle äußern.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (534,'audi-a1-8x','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (535,'audi-a1-8x','Klimaanlage','Ausfälle oder mangelnde Kühlleistung der Klimaanlage, oft bedingt durch undichte Leitungen oder defekte Kompressoren.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (536,'audi-a3-typ-8l','Zündspulen','Defekte Zündspulen können zu Motorruckeln und Leistungsverlust führen. Betrifft vor allem die 1.8T-Motoren.','Alle Baujahre, besonders vor Facelift','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (537,'audi-a3-typ-8l','Luftmassenmesser (LMM)','Ausfälle des LMM sind häufig und äußern sich in schlechter Gasannahme und Leistungsverlust.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (538,'audi-a3-typ-8l','Turbolader','Bei den 1.8T-Motoren kann es zu Turboladerschäden kommen, oft durch mangelnde Ölversorgung oder Überhitzung.','Alle Baujahre (1.8T)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (539,'audi-a3-typ-8l','Querlenkerlager','Verschleiß der Querlenkerlager führt zu Poltergeräuschen an der Vorderachse und unpräzisem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (540,'audi-a3-typ-8l','Fensterheber','Defekte Fensterhebermechanismen sind ein bekanntes Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (541,'audi-a3-typ-8l','Rost','Rost kann an den vorderen Kotflügeln (im Bereich der Schweller), an der Heckklappe und an den Türunterkanten auftreten.','Ältere Baujahre, besonders bei mangelnder Pflege','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (542,'audi-a3-typ-8l','Klimaanlage','Undichtigkeiten im Klimasystem oder Defekte am Klimakompressor sind nicht selten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (543,'audi-a3-typ-8p','Zweimassenschwungrad (ZMS)','Besonders bei Dieselmotoren und leistungsstärkeren Benzinern kann das ZMS vorzeitig verschleißen, was sich durch Ruckeln beim Anfahren, Vibrationen und Geräusche äußert.','Alle Baujahre, insbesondere bei hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (544,'audi-a3-typ-8p','Steuerkette (1.4 TFSI, 1.8 TFSI, 2.0 TFSI)','Probleme mit gelängten Steuerketten oder defekten Kettenspannern können zu Motorschäden führen. Anzeichen sind Rasseln nach dem Kaltstart.','Vor allem Modelle bis ca. 2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (545,'audi-a3-typ-8p','DSG-Getriebe (S tronic)','Defekte an der Mechatronik oder verschlissene Kupplungen können zu Schaltproblemen, Ruckeln oder dem Ausfall von Gängen führen.','Alle Baujahre, insbesondere bei hoher Laufleistung und mangelnder Wartung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (546,'audi-a3-typ-8p','Turbolader (TFSI-Motoren)','Ausfälle des Turboladers, oft durch mangelnde Ölversorgung oder Materialermüdung, führen zu Leistungsverlust und erhöhtem Ölverbrauch.','Alle Baujahre, insbesondere bei hoher Laufleistung','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (547,'audi-a3-typ-8p','Fensterheber','Defekte an den Fensterhebermechanismen oder -motoren, die zum Ausfall der Fensterfunktion führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (548,'audi-a3-typ-8p','Rost (Heckklappe, Kotflügel)','Vereinzelt kann Rost an der Heckklappe (oft im Bereich der Kennzeichenbeleuchtung) oder an den vorderen Kotflügeln auftreten.','Ältere Baujahre, insbesondere bei mangelnder Pflege','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (549,'audi-a3-typ-8v','Wasserpumpe','Undichtigkeiten an der Wasserpumpe, insbesondere bei den 1.4 TFSI und 1.8 TFSI Motoren, können zu Kühlmittelverlust führen.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (550,'audi-a3-typ-8v','Mechatronik (S tronic Getriebe)','Probleme mit der Mechatronik des Doppelkupplungsgetriebes (S tronic) können zu Schaltruckeln, Notlauf oder komplettem Ausfall führen. Betrifft vor allem die 7-Gang-S tronic.','2012-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (551,'audi-a3-typ-8v','Steuerkette (1.2 TFSI, 1.4 TFSI)','Bei frühen Baujahren der kleineren TFSI-Motoren kann es zu Problemen mit der Steuerkette (Längung, Rasseln) kommen, was im schlimmsten Fall zu Motorschäden führen kann.','2012-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (552,'audi-a3-typ-8v','Bremsen','Erhöhter Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse, wird häufiger berichtet.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (553,'audi-a3-typ-8v','Elektronik (MMI-System)','Vereinzelt können Softwarefehler oder Ausfälle des MMI-Infotainmentsystems auftreten, die sich durch Neustarts oder Funktionsstörungen äußern.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (554,'audi-a4-b5','Vorderachse (Mehrlenkerachse)','Verschleiß der Querlenkerlager und Traggelenke führt zu Poltergeräuschen, unpräzisem Fahrverhalten und erhöhtem Reifenverschleiß. Ein häufiges Problem aufgrund der komplexen Konstruktion.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (555,'audi-a4-b5','Turbolader (bei 1.8T und S4/RS4)','Defekte Turbolader sind bei den aufgeladenen Motoren keine Seltenheit, oft durch mangelnde Ölversorgung oder Überhitzung. Äußert sich durch Leistungsverlust, erhöhten Ölverbrauch oder laute Geräusche.','Alle Baujahre mit Turbomotoren','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (556,'audi-a4-b5','Zündspulen (bei 1.8T)','Ausfälle der Zündspulen führen zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte.','Alle Baujahre mit 1.8T Motor','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (557,'audi-a4-b5','Kühlmitteltemperatursensor','Defekte Sensoren können zu Startproblemen, unruhigem Motorlauf oder falschen Temperaturanzeigen führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (558,'audi-a4-b5','Ölverlust (verschiedene Stellen)','Motoren können an verschiedenen Stellen Öl verlieren, z.B. an der Ventildeckeldichtung, Kurbelwellensimmerring oder Ölwannendichtung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (559,'audi-a4-b5','Rost','Obwohl Audi für gute Rostvorsorge bekannt ist, können ältere B5 Modelle an den vorderen Kotflügeln (im Bereich der Schweller), an den Türunterkanten und am Heckklappengriff (Avant) Rost aufweisen.','Spätere Baujahre und Fahrzeuge mit Vorschäden','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (560,'audi-a4-b5','Klimaanlage','Undichtigkeiten im System oder Defekte am Klimakompressor sind häufig, was zu einem Ausfall der Kühlfunktion führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (561,'audi-a4-b6','Vorderachse (Querlenker)','Verschleiß der Gummilager und Kugelgelenke der Mehrlenker-Vorderachse führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (562,'audi-a4-b6','Multitronic-Getriebe (Automatik)','Probleme mit der Steuerungselektronik und dem Anfahrkupplungspaket können zu Ruckeln, Leistungsverlust oder Totalausfall führen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (563,'audi-a4-b6','Zündspulen (Benziner)','Defekte Zündspulen führen zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (564,'audi-a4-b6','Ölpumpe (1.8T Motoren)','Verstopfung des Ölsiebs der Ölpumpe durch Ölkohleablagerungen kann zu mangelnder Schmierung und Motorschäden führen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (565,'audi-a4-b6','Fensterheber','Defekte Mechanik oder Motoren der elektrischen Fensterheber.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (566,'audi-a4-b7','Multitronic-Getriebe (Automatik)','Probleme mit der Haltbarkeit und dem Verschleiß der Lamellenpakete, insbesondere bei höheren Laufleistungen. Kann zu Ruckeln, Leistungsverlust oder Totalausfall führen.','2004-2008','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (567,'audi-a4-b7','Vorderachse (Querlenker)','Verschleiß der Gummilager und Kugelgelenke der Querlenker, was zu Poltergeräuschen, unpräzisem Fahrverhalten und erhöhtem Reifenverschleiß führen kann.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (568,'audi-a4-b7','Zündspulen (Benzinmotoren)','Ausfälle der Zündspulen, was zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte führt.','2004-2008','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (569,'audi-a4-b7','Turbolader (insbesondere 2.0 TFSI)','Verschleiß oder Defekte am Turbolader, oft verbunden mit erhöhtem Ölverbrauch oder Leistungsverlust.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (570,'audi-a4-b7','Dieselfilter (DPF) und AGR-Ventil (Dieselmotoren)','Verstopfung des Dieselpartikelfilters und Defekte am Abgasrückführungsventil, besonders bei Kurzstreckenfahrzeugen, was zu Leistungsverlust und Motorkontrollleuchte führt.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (571,'audi-a4-b8','Multitronic-Getriebe (CVT)','Bekannt für Ruckeln, Leistungsverlust und vorzeitigen Verschleiß, insbesondere bei höheren Laufleistungen. Kann zu teuren Reparaturen oder einem Getriebetausch führen.','Alle Baujahre mit Multitronic','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (572,'audi-a4-b8','Steuerkette (bei bestimmten TFSI-Motoren)','Probleme mit gelängten Steuerketten und defekten Kettenspannern, was zu Motorschäden führen kann. Äußert sich oft durch Rasseln beim Kaltstart.','Vor allem 1.8 TFSI und 2.0 TFSI Motoren der ersten Baujahre (ca. 2007-2011)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (573,'audi-a4-b8','Ölverbrauch (bei bestimmten TFSI-Motoren)','Erhöhter Ölverbrauch, insbesondere bei den 1.8 TFSI und 2.0 TFSI Motoren, oft bedingt durch fehlerhafte Kolbenringe. Kann zu Motorschäden führen, wenn nicht regelmäßig kontrolliert und nachgefüllt wird.','Vor allem 1.8 TFSI und 2.0 TFSI Motoren der ersten Baujahre (ca. 2007-2011)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (574,'audi-a4-b8','Wasserpumpe','Undichtigkeiten und Defekte an der Wasserpumpe, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre, insbesondere bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (575,'audi-a4-b8','Elektronik (MMI, Komfortsysteme)','Ausfälle oder Fehlfunktionen des MMI-Systems, der Fensterheber oder anderer Komfortelektronik. Oft durch Softwarefehler oder defekte Steuergeräte verursacht.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (576,'audi-a4-b8','Vorderachse (Querlenker, Spurstangenköpfe)','Verschleiß an den Gummilagern der Querlenker und Spurstangenköpfen, was sich durch Poltern oder unpräzises Fahrverhalten äußern kann. Typisch für Audi-Modelle mit Mehrlenkerachse.','Alle Baujahre, insbesondere bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (581,'audi-a4-b9','Wasserpumpe','Undichtigkeiten an der Wasserpumpe, insbesondere bei den 2.0 TFSI Motoren, können zu Kühlmittelverlust führen.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (582,'audi-a4-b9','Virtual Cockpit / MMI-System','Softwarefehler, gelegentliche Abstürze oder Pixelfehler im digitalen Kombiinstrument (Virtual Cockpit) oder im MMI-Infotainmentsystem.','2015-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (583,'audi-a4-b9','S tronic Getriebe (DSG)','Bei einigen Fahrzeugen mit S tronic Getriebe können Ruckeln, Schaltverzögerungen oder ungewöhnliche Geräusche auftreten. Oft sind Mechatronik-Probleme die Ursache.','2015-2019','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (584,'audi-a4-b9','AdBlue-System','Fehlermeldungen oder Funktionsstörungen des AdBlue-Systems, insbesondere bei Fahrzeugen mit höherer Laufleistung, können zu Startproblemen führen.','2016-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (585,'audi-a5-i','Steuerkette (V6 TFSI)','Bei den 3.0 TFSI Motoren (S5 und einige A5) kann es zu Problemen mit der Steuerkette und den Kettenspannern kommen, was zu Rasseln und im schlimmsten Fall zu Motorschäden führen kann.','2007-2012 (vor Facelift besonders betroffen)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (586,'audi-a5-i','Ölverbrauch (2.0 TFSI)','Einige 2.0 TFSI Motoren (insbesondere die EA888 Gen. 2) neigen zu erhöhtem Ölverbrauch aufgrund von Kolbenringen, die den Ölabstreifring nicht korrekt abdichten. Dies kann teure Reparaturen erfordern.','2008-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (587,'audi-a5-i','Multitronic-Getriebe','Das stufenlose Multitronic-Getriebe (oft in Frontantriebsmodellen verbaut) kann bei höheren Laufleistungen und Belastungen zu Ruckeln, Leistungsverlust oder Ausfällen neigen. Reparaturen sind oft sehr kostspielig.','Alle Baujahre mit Multitronic','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (588,'audi-a5-i','Wasserpumpe','Undichtigkeiten oder Defekte an der Wasserpumpe sind keine Seltenheit und können zu Kühlmittelverlust und Überhitzung führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (589,'audi-a5-i','Elektronik (MMI, Komfortsysteme)','Vereinzelt können Störungen im MMI-System (Ausfälle, Neustarts) oder bei Komfortsystemen wie Fensterhebern oder Zentralverriegelung auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (590,'audi-a5-ii','Software/Infotainment','Berichte über gelegentliche Software-Fehler, Abstürze des Infotainmentsystems oder Probleme mit der Konnektivität (z.B. Apple CarPlay/Android Auto).','Alle Baujahre, insbesondere frühe Modelle vor dem Facelift.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (591,'audi-a5-ii','Bremsen','Bei einigen Modellen kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen, insbesondere bei sportlicher Fahrweise. Auch Quietschen der Bremsen wurde vereinzelt berichtet.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (592,'audi-a5-ii','Wasserpumpe','Vereinzelt wurden Defekte an der Wasserpumpe gemeldet, die zu Kühlmittelverlust oder Überhitzung führen können.','Frühe Baujahre (ca. 2016-2018)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (593,'audi-a6-c4','Vorderachse','Verschleiß an Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (594,'audi-a6-c4','Rost','Obwohl die Karosserie gut verzinkt ist, können an den Türkanten, Radläufen und unter den Dichtungen Rostansätze auftreten, insbesondere bei schlecht gepflegten Exemplaren.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (595,'audi-a6-c4','Elektronik','Probleme mit dem Kombiinstrument (Pixelfehler), Fensterhebern und der Zentralverriegelung können auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (596,'audi-a6-c4','Bremsanlage','Festgehende Bremssättel, insbesondere hinten, sind ein bekanntes Problem.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (597,'audi-a6-c4','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe können zu Kühlmittelverlust führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (598,'audi-a6-c5','Vorderachse','Verschleiß der Querlenker und Spurstangenköpfe führt zu Poltergeräuschen und unpräzisem Fahrverhalten. Die Mehrlenkerachse ist komplex und reparaturanfällig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (599,'audi-a6-c5','Automatikgetriebe (Multitronic)','Besonders die Multitronic-Getriebe (CVT) der frühen Baujahre sind anfällig für Defekte, die sich durch Ruckeln, Leistungsverlust oder Totalausfall äußern können. Hohe Reparaturkosten.','1999-2003','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (600,'audi-a6-c5','Turbolader','Bei den 2.7T und 2.5 TDI Motoren können die Turbolader verschleißen oder undicht werden, was zu Leistungsverlust und erhöhtem Ölverbrauch führt.','Alle mit Turbo-Motoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (601,'audi-a6-c5','Zahnriemen (2.5 TDI)','Der Zahnriemenwechsel beim 2.5 TDI ist aufwendig und teuer. Wird das Wechselintervall überzogen, droht ein Motorschaden.','Alle mit 2.5 TDI','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (602,'audi-a6-c5','Luftfederung (allroad quattro)','Defekte an den Luftfedern oder dem Kompressor können zu einer einseitigen Absenkung des Fahrzeugs oder zum Ausfall der Höhenverstellung führen.','Alle allroad quattro','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (603,'audi-a6-c5','Elektronik','Probleme mit dem Kombiinstrument (Pixelfehler), Fensterhebern, Zentralverriegelung oder der Klimaanlagensteuerung sind nicht selten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (604,'audi-a6-c6','Multitronic-Getriebe (Automatik)','Probleme mit der Haltbarkeit und dem Verschleiß der Lamellenpakete, insbesondere bei höheren Laufleistungen. Kann zu Ruckeln, Leistungsverlust oder Totalausfall führen.','2004-2007 (insbesondere frühe Baujahre)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (605,'audi-a6-c6','Kettenspanner und Steuerkette (V6/V8 FSI Motoren)','Verschleiß der Kettenspanner und Längung der Steuerkette, was zu Rasseln beim Kaltstart und im schlimmsten Fall zu Motorschäden führen kann. Reparatur ist sehr aufwendig und teuer, da der Motor ausgebaut werden muss.','2004-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (606,'audi-a6-c6','Luftfahrwerk (Adaptive Air Suspension)','Defekte Kompressoren, undichte Luftbälge oder Sensoren können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Reparaturen sind kostspielig.','2004-2011 (insbesondere bei Fahrzeugen mit hoher Laufleistung)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (607,'audi-a6-c6','Injektoren (Dieselmotoren, insbesondere 3.0 TDI)','Verschleiß oder Verstopfung der Injektoren kann zu unrundem Motorlauf, Leistungsverlust und erhöhtem Kraftstoffverbrauch führen. Austausch ist teuer.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (608,'audi-a6-c6','Partikelfilter (DPF) (Dieselmotoren)','Verstopfung des Partikelfilters, insbesondere bei überwiegendem Kurzstreckenbetrieb, was zu Leistungsverlust und Notlauf führen kann. Reinigung oder Austausch ist erforderlich.','2005-2011 (Fahrzeuge mit DPF)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (609,'audi-a6-c6','MMI-System (Multi Media Interface)','Softwarefehler, Ausfälle des Bildschirms oder einzelner Komponenten (z.B. CD-Wechsler, Navigation).','2004-2011','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (610,'audi-a6-c6','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei leistungsstärkeren Modellen und sportlicher Fahrweise.','2004-2011','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (611,'audi-a6-c7','S tronic (Doppelkupplungsgetriebe)','Probleme mit dem Mechatronik-Modul, Ruckeln beim Schalten, Schaltverzögerungen oder Ausfall des Getriebes. Kann zu teuren Reparaturen führen.','2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (612,'audi-a6-c7','Kettenspanner (V6 TFSI Motoren)','Verschleiß der Kettenspanner kann zu Rasseln beim Kaltstart und im schlimmsten Fall zu Motorschäden führen. Reparatur ist aufwendig und teuer.','2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (613,'audi-a6-c7','LED-Scheinwerfer','Ausfall einzelner LED-Segmente oder ganzer Scheinwerfer. Austausch ist kostspielig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (614,'audi-a6-c7','Luftfederung (allroad, S6, RS6, optional)','Undichtigkeiten an den Luftbälgen oder Defekte am Kompressor können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (615,'audi-a6-c7','MMI-System','Softwarefehler, Abstürze oder Ausfall einzelner Funktionen (Navigation, Radio). Oft durch Software-Updates behebbar.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (616,'audi-a6-c7','Wasserpumpe (insbesondere 3.0 TFSI)','Undichtigkeiten oder Lagerschäden können zu Kühlmittelverlust und Überhitzung führen.','2011-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (617,'audi-a6-c8','MMI-Infotainmentsystem','Gelegentliche Software-Probleme, Abstürze oder langsame Reaktionen der Touchscreens. Updates können Abhilfe schaffen.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (618,'audi-a6-c8','Mild-Hybrid-System (Riemenstartergenerator)','Bei frühen Modellen gab es vereinzelt Ausfälle des Riemenstartergenerators, was zu Startproblemen oder dem Ausfall des 48V-Bordnetzes führen kann.','2018-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (619,'audi-a6-c8','Bremsen (Verschleiß)','Insbesondere bei leistungsstärkeren Varianten und sportlicher Fahrweise kann der Bremsenverschleiß überdurchschnittlich hoch sein.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (620,'audi-a7-typ-4g','S tronic Getriebe (DL501)','Probleme mit dem Mechatronik-Modul, Ruckeln beim Schalten, Notlauf. Betrifft vor allem frühe Baujahre und Fahrzeuge mit hoher Laufleistung.','2010-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (621,'audi-a7-typ-4g','Kettenspanner (V6 TFSI)','Verschleiß der Kettenspanner kann zu Rasseln beim Kaltstart und im schlimmsten Fall zu Motorschäden führen. Eine aufwendige Reparatur ist erforderlich.','2010-2013','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (622,'audi-a7-typ-4g','Luftfahrwerk','Undichtigkeiten an den Luftfedern oder Defekte am Kompressor können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (623,'audi-a7-typ-4g','LED-Scheinwerfer','Ausfall einzelner LED-Segmente oder ganzer Scheinwerfer. Ein Austausch ist oft teuer.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (624,'audi-a7-typ-4g','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise und leistungsstärkeren Modellen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (625,'audi-a8-d2','Multitronic-Getriebe (bei Frontantrieb)','Die Multitronic-Getriebe (stufenloses Automatikgetriebe) können bei höheren Laufleistungen zu Problemen mit der Steuerungselektronik und dem Verschleiß der Lamellenpakete neigen, was zu Ruckeln, Leistungsverlust oder Totalausfall führen kann.','Alle Baujahre mit Multitronic (nicht alle D2 hatten Multitronic, vor allem die V8-Modelle hatten Tiptronic).','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (626,'audi-a8-d2','Fahrwerk (Querlenker, Spurstangen)','Aufgrund des hohen Fahrzeuggewichts und der komplexen Mehrlenkerachse können die Gummilager und Kugelgelenke der Querlenker und Spurstangen verschleißen, was sich durch Poltern, schwammiges Fahrverhalten und ungleichmäßigen Reifenverschleiß äußert.','Alle Baujahre, insbesondere bei hohen Laufleistungen.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (627,'audi-a8-d2','Elektronik (Klimaanlage, Fensterheber, Zentralverriegelung)','Altersbedingt können verschiedene elektronische Komponenten ausfallen, darunter die Bedieneinheit der Klimaanlage (Pixelfehler), Fensterhebermotoren oder die Zentralverriegelung.','Alle Baujahre, zunehmend mit dem Alter.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (628,'audi-a8-d2','Servolenkung','Undichtigkeiten an der Servopumpe oder den Leitungen können zu Ölverlust und einem Ausfall der Servounterstützung führen.','Alle Baujahre, insbesondere bei hohen Laufleistungen.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (629,'audi-a8-d3','Luftfahrwerk','Defekte Kompressoren, undichte Federbeine oder Ventile können zu einem Absinken des Fahrzeugs führen, insbesondere nach längerer Standzeit. Reparaturen sind kostspielig.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (630,'audi-a8-d3','Multitronic-Getriebe (bei Frontantriebsmodellen)','Probleme mit der Steuerungselektronik oder dem Lamellenpaket können zu Ruckeln, Leistungsverlust oder Totalausfall führen. Nicht alle D3 hatten Multitronic, die meisten waren Quattro mit Tiptronic.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (631,'audi-a8-d3','Elektronik (MMI, Komfortsysteme)','Ausfälle des MMI-Systems (Bildschirm, Radio, Navigation), defekte Steuergeräte für Komfortfunktionen (Fensterheber, Zentralverriegelung) oder Batterieentladung durch Kriechströme.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (632,'audi-a8-d3','Bremsanlage','Übermäßiger Verschleiß der Bremsen, insbesondere bei leistungsstarken Modellen. Festgehende Bremssättel sind ebenfalls bekannt.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (633,'audi-a8-d3','Vorderachse','Verschleiß an Querlenkern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (634,'audi-a8-d4','Luftfahrwerk','Defekte Kompressoren, undichte Federbeine oder Ventile können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders bei älteren Fahrzeugen und hohen Laufleistungen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (635,'audi-a8-d4','Elektronik / MMI','Ausfälle oder Fehlfunktionen des Infotainmentsystems (MMI), der Navigation oder anderer elektronischer Komponenten. Softwareprobleme oder defekte Steuergeräte.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (636,'audi-a8-d4','Getriebe (Automatik)','Bei einigen Fahrzeugen, insbesondere mit dem 8-Gang-tiptronic-Getriebe, können Ruckeln, Schaltverzögerungen oder Geräusche auftreten. Oft durch verschlissene Mechatronik oder unzureichende Getriebespülungen verursacht.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (637,'audi-a8-d4','LED-Scheinwerfer (Matrix-LED)','Ausfall einzelner LED-Segmente oder ganzer Scheinwerfer. Reparatur ist oft teuer, da meist der komplette Scheinwerfer getauscht werden muss.','Ab Facelift (2013)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (638,'audi-a8-d5','Luftfederung','Probleme mit undichten Luftfedern oder Kompressoren können zu einem Absinken des Fahrzeugniveaus oder Fehlermeldungen führen.','Ab 2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (639,'audi-a8-d5','Infotainmentsystem (MMI)','Gelegentliche Softwarefehler, Abstürze oder langsame Reaktionen des Touchscreen-Systems wurden berichtet.','Ab 2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (640,'audi-a8-d5','Elektronische Assistenzsysteme','Fehlfunktionen oder sporadische Ausfälle von Sensoren für Parkassistent, Spurhalteassistent oder adaptiven Tempomat.','Ab 2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (641,'audi-q2-ga','Wasserpumpe','Bei einigen Motoren, insbesondere den 1.5 TFSI, können Undichtigkeiten an der Wasserpumpe auftreten, was zu Kühlmittelverlust führt.','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (642,'audi-q2-ga','Mechatronik (S tronic Getriebe)','Probleme mit der Mechatronik des Doppelkupplungsgetriebes S tronic können zu Schaltruckeln, Leistungsverlust oder dem Ausfall des Getriebes führen.','2016-2019','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (643,'audi-q2-ga','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise oder häufigem Stadtverkehr.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (644,'audi-q2-ga','Infotainmentsystem (MMI)','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des MMI-Systems wurden berichtet.','2016-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (645,'audi-q3-i','Steuerkette (1.4 TFSI, 2.0 TFSI)','Bei den TFSI-Motoren, insbesondere den frühen Baujahren, kann es zu Problemen mit der Steuerkette (Längung) und dem Kettenspanner kommen, was zu Motorschäden führen kann.','ca. 2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (646,'audi-q3-i','Wasserpumpe','Undichtigkeiten an der Wasserpumpe sind keine Seltenheit und können zu Kühlmittelverlust führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (647,'audi-q3-i','DSG-Getriebe (S tronic)','Probleme mit dem Doppelkupplungsgetriebe, insbesondere dem 7-Gang-DSG (DQ200), können sich durch Ruckeln, Schaltverzögerungen oder Ausfälle äußern. Oft ist die Mechatronik betroffen.','ca. 2011-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (648,'audi-q3-i','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit sportlicher Fahrweise oder hohem Stadtanteil.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (649,'audi-q3-i','Elektronik','Vereinzelt können Störungen der Bordelektronik auftreten, z.B. Ausfälle des Infotainmentsystems oder Fehlermeldungen von Sensoren.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (650,'audi-q3-ii','Kühlmittelleitungen','Bei einigen Modellen können Kühlmittelleitungen porös werden und zu Undichtigkeiten führen.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (651,'audi-q3-ii','DSG-Getriebe','Vereinzelt Probleme mit der Mechatronik oder Schaltprobleme bei älteren DSG-Getrieben.','2018-2020','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (652,'audi-q3-ii','Infotainmentsystem','Gelegentliche Software-Abstürze oder träge Reaktionen des Touchscreens.','2018-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (653,'audi-q5-i','Partikelfilter (Diesel)','Verstopfung des Partikelfilters, insbesondere bei Kurzstreckenfahrzeugen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (654,'audi-q5-i','Kettenspanner (TFSI-Motoren)','Verschleiß des Kettenspanners kann zu Steuerkettenrasseln und im schlimmsten Fall zum Überspringen der Steuerkette führen.','Frühe Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (655,'audi-q5-i','S tronic Getriebe','Ruckeln beim Anfahren oder Schalten, Probleme mit der Mechatronik.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (656,'audi-q5-ii','AdBlue-System','Probleme mit dem AdBlue-System, insbesondere bei Dieselmotoren, können zu Fehlermeldungen und im schlimmsten Fall zu einem Notlaufprogramm führen. Oft sind Sensoren oder die Pumpe betroffen.','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (657,'audi-q5-ii','Wasserpumpe','Undichtigkeiten an der Wasserpumpe können zu Kühlmittelverlust und Überhitzung führen. Dies betrifft vor allem die 2.0 TFSI Motoren.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (658,'audi-q5-ii','Software/Elektronik','Gelegentliche Software-Fehler können zu Ausfällen oder Fehlfunktionen des Infotainmentsystems, der Assistenzsysteme oder des digitalen Kombiinstruments führen. Meist durch Updates behebbar.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (659,'audi-q5-ii','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit sportlicher Fahrweise oder hohem Gewicht.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (660,'audi-q7-typ-4l','Luftfederung','Defekte Kompressoren, undichte Federbälge oder Sensoren können zu Problemen mit der Niveauregulierung führen. Äußert sich durch einseitiges Absinken des Fahrzeugs oder Fehlermeldungen.','Alle Baujahre, insbesondere bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (661,'audi-q7-typ-4l','Automatikgetriebe (Tiptronic)','Bei hohen Laufleistungen können Schaltrucke, verzögertes Schalten oder Notlauf auftreten. Oft sind verschlissene Wandler oder Mechatronik-Einheiten die Ursache.','Alle Baujahre, insbesondere ab 150.000 km','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (662,'audi-q7-typ-4l','Bremsanlage','Hoher Verschleiß von Bremsscheiben und -belägen aufgrund des hohen Fahrzeuggewichts und der Motorleistung. Festgehende Bremssättel sind ebenfalls bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (663,'audi-q7-typ-4l','Panoramadach (Open Sky)','Undichtigkeiten oder Defekte an der Mechanik des Schiebedachs können zu Wassereintritt oder Funktionsstörungen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (664,'audi-q7-typ-4l','Elektronik (MMI, Sensoren)','Ausfälle des MMI-Systems, defekte Parksensoren oder Probleme mit der Zentralverriegelung können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (665,'audi-q7-typ-4m','Luftfahrwerk','Probleme mit undichten Luftfedern oder Kompressoren können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen.','Alle Baujahre, insbesondere bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (666,'audi-q7-typ-4m','MMI-Infotainmentsystem','Softwarefehler, Abstürze oder Ausfälle des Bildschirms können auftreten, insbesondere bei frühen Modellen vor dem Facelift. Nach dem Facelift können die Touchscreens manchmal träge reagieren.','2015-2018 (vor Facelift), vereinzelt auch danach.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (667,'audi-q7-typ-4m','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere bei Modellen mit stärkeren Motoren und häufigem Anhängerbetrieb.','Alle Baujahre, abhängig von Fahrweise und Nutzung.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (668,'audi-q7-typ-4m','AdBlue-System','Fehlermeldungen oder Störungen im AdBlue-System, die zu einem Notlaufprogramm führen können.','Alle Dieselmodelle.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (669,'audi-q8-i','Infotainmentsystem (MMI)','Berichte über gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen des MMI-Systems, insbesondere in den frühen Baujahren. Dies kann sich auf Navigation, Konnektivität und andere Funktionen auswirken.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (670,'audi-q8-i','Luftfederung','Einige Nutzer berichten von Problemen mit der adaptiven Luftfederung, die zu ungleichmäßigem Niveau oder Fehlermeldungen führen können. Dies kann auf undichte Komponenten oder defekte Sensoren zurückzuführen sein.','2018-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (671,'audi-q8-i','Bremsen (Verschleiß)','Bei sportlicher Fahrweise oder hohem Fahrzeuggewicht kann der Verschleiß der Bremsbeläge und -scheiben überdurchschnittlich hoch sein, insbesondere bei den leistungsstärkeren Modellen wie SQ8 und RS Q8.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (672,'audi-tt-typ-8n','Rost','Besonders anfällig an Radläufen, Schwellern, Türen und Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (673,'audi-tt-typ-8n','Zahnriemen (1.8T)','Bei vielen Modellen wurde der Zahnriemenwechsel vernachlässigt, was zu Motorschäden führen kann.','1998-2006','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (674,'audi-tt-typ-8n','Fahrwerk','Verschleiß an Querlenkern, Stoßdämpfern und Domlagern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (675,'audi-tt-typ-8n','Kupplung/Getriebe','Bei sportlicher Fahrweise kann es zu erhöhtem Verschleiß kommen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (676,'audi-tt-typ-8j','Kupplung (bei Schaltgetriebe)','Verschleißerscheinungen, Rupfen oder Geräusche können auftreten, insbesondere bei sportlicher Fahrweise.','2006-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (677,'audi-tt-typ-8j','Steuerkettenspanner (bei TFSI-Motoren)','Defekte Steuerkettenspanner können zu Rasseln und im schlimmsten Fall zu Motorschäden führen.','2006-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (678,'audi-tt-typ-8j','Haldex-Kupplung (Allradantrieb)','Bei Modellen mit Allradantrieb kann es zu Problemen mit der Haldex-Kupplung kommen, z.B. Ruckeln oder Ausfall der hinteren Traktion.','2006-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (679,'audi-tt-typ-8j','Klimakompressor','Ausfälle des Klimakompressors sind keine Seltenheit.','2006-2014','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (680,'audi-tt-typ-fv','Wasserpumpe','Undichtigkeiten oder Defekte an der Wasserpumpe, insbesondere bei den 2.0 TFSI Motoren.','2014-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (681,'audi-tt-typ-fv','Mechatronik des S tronic Getriebes','Probleme mit der Mechatronik des Doppelkupplungsgetriebes können zu Schaltproblemen oder Ausfällen führen.','2014-2017','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (682,'audi-tt-typ-fv','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise. Bei einigen Modellen kann es zu Rubbeln oder Geräuschen kommen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (683,'audi-tt-typ-fv','Elektronik / Virtual Cockpit','Vereinzelt Berichte über Softwarefehler, Pixelfehler oder Ausfälle des Virtual Cockpits. Meist durch Software-Updates behebbar.','2014-2016','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (684,'audi-rs-2-avant-b4','Turbolader','Der KKK K24-7200 Turbolader ist bei unsachgemäßer Behandlung oder mangelnder Wartung anfällig für Verschleiß und kann bei hohen Laufleistungen oder Leistungssteigerungen Probleme bereiten.','1994-1995','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (685,'audi-rs-2-avant-b4','Bremsanlage','Obwohl die Porsche-Bremsen sehr leistungsfähig sind, können die Bremsscheiben bei extremer Beanspruchung oder Alterung Risse entwickeln. Ersatzteile sind teuer.','1994-1995','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (686,'audi-rs-2-avant-b4','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt und kann die Fahrpräzision beeinträchtigen. Originalteile sind oft teuer.','1994-1995','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (687,'audi-rs-2-avant-b4','Elektronik/Kabelbaum','Altersbedingte Probleme mit dem Kabelbaum, insbesondere im Motorraum, können zu sporadischen Fehlern oder Ausfällen von Sensoren und Aktuatoren führen.','1994-1995','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (688,'audi-rs-2-avant-b4','Lack und Karosserie','Rost ist bei gut gepflegten Exemplaren selten, kann aber an typischen Stellen wie Radläufen oder unter Dichtungen auftreten, insbesondere bei Fahrzeugen, die im Winter gefahren wurden.','1994-1995','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (689,'audi-rs-4-avant-b5','Turbolader','Die K04-Turbolader können bei unsachgemäßer Wartung oder Leistungssteigerung vorzeitig verschleißen oder Schäden erleiden.','1999-2001','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (690,'audi-rs-4-avant-b5','Ladeluftkühler','Undichtigkeiten im Ladeluftsystem können zu Leistungsverlust führen.','1999-2001','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (691,'audi-rs-4-avant-b5','Bremsanlage','Die serienmäßige Bremsanlage kann bei sportlicher Fahrweise an ihre Grenzen stoßen und ist anfällig für Verschleiß.','1999-2001','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (692,'audi-rs-4-avant-b5','Fahrwerk','Verschleiß an Querlenkern und anderen Fahrwerkskomponenten ist altersbedingt häufig.','1999-2001','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (693,'audi-rs-4-avant-b5','Zündspulen','Defekte Zündspulen können zu Motorruckeln und Leistungsverlust führen.','1999-2001','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (694,'audi-rs-6-c5','Automatikgetriebe (Tiptronic)','Probleme mit dem Drehmomentwandler, Schaltrucken, Notlaufprogramm. Kann bei hohen Laufleistungen oder unsachgemäßer Wartung auftreten.','2002-2004','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (695,'audi-rs-6-c5','Dynamic Ride Control (DRC) Fahrwerk','Undichtigkeiten in den Dämpfern oder Leitungen, was zu einem Verlust der Dämpfung und einer Beeinträchtigung des Fahrverhaltens führt. Reparatur ist aufwendig und teuer.','2002-2004','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (696,'audi-rs-6-c5','Turbolader','Verschleiß der Turbolader, insbesondere bei Fahrzeugen, die häufig unter Volllast gefahren wurden oder bei denen die Ölwechselintervalle nicht eingehalten wurden. Kann zu Leistungsverlust und erhöhtem Ölverbrauch führen.','2002-2004','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (697,'audi-rs-6-c5','Bremsanlage','Hoher Verschleiß der Bremsbeläge und -scheiben aufgrund der hohen Motorleistung und des Fahrzeuggewichts. Die Keramikbremse war optional und ist sehr teuer im Ersatz.','2002-2004','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (698,'audi-rs-6-c5','Zündspulen','Ausfälle der Zündspulen, was zu Motorruckeln und Leistungsverlust führen kann. Ein bekanntes Problem bei VAG-Motoren dieser Ära.','2002-2004','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (699,'audi-rs-4-b7','FSI-Motor (4.2 V8)','Verkokung der Einlassventile durch Direkteinspritzung, was zu Leistungsverlust und unrundem Motorlauf führen kann. Regelmäßige Reinigung (Walnussstrahlen) ist erforderlich.','2006-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (700,'audi-rs-4-b7','Dynamic Ride Control (DRC) Fahrwerk','Undichtigkeiten in den Dämpfern oder Leitungen des hydraulischen DRC-Systems, was zu einem Verlust der Dämpfungswirkung und einem schwammigen Fahrverhalten führt. Reparatur ist oft teuer.','2006-2008','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (701,'audi-rs-4-b7','Kupplung (Schaltgetriebe)','Bei sportlicher Fahrweise oder Leistungssteigerung kann die Kupplung frühzeitig verschleißen.','2006-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (702,'audi-rs-4-b7','Bremsanlage','Hoher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei sportlicher Fahrweise. Die Bremsen sind leistungsstark, aber auch kostenintensiv im Unterhalt.','2006-2008','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (703,'audi-rs-6-c6','Dynamic Ride Control (DRC) Fahrwerk','Undichtigkeiten an den Dämpfern und Leitungen des hydraulischen DRC-Fahrwerks können zu Komfortverlust und schlechterem Fahrverhalten führen. Reparaturen sind aufwendig und teuer.','2008-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (704,'audi-rs-6-c6','Keramikbremsanlage (optional)','Hoher Verschleiß bei sportlicher Fahrweise, sehr hohe Ersatzteilkosten für Scheiben und Beläge.','2008-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (705,'audi-rs-6-c6','Getriebe (Tiptronic)','Bei sehr hoher Beanspruchung oder mangelnder Wartung können Verschleißerscheinungen oder Schaltprobleme auftreten. Getriebeölwechsel sind entscheidend.','2008-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (706,'audi-rs-6-c6','Elektronik','Vereinzelt können Fehlermeldungen oder Ausfälle von Komfortelektronik (MMI, Sensoren) auftreten.','2008-2010','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (707,'audi-tt-rs-8j','Haldex-Kupplung','Probleme mit der Haldex-Kupplung, die für den Allradantrieb zuständig ist, können zu Ausfällen des Allradsystems führen. Oft sind die Pumpe oder das Steuergerät betroffen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (708,'audi-tt-rs-8j','Bremsanlage','Bei sportlicher Fahrweise kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen. Auch Fading ist bei extremer Belastung möglich.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (709,'audi-tt-rs-8j','Fahrwerk','Verschleiß an Querlenkerlagern und Stoßdämpfern, insbesondere bei Fahrzeugen mit hohem Kilometerstand oder sportlicher Nutzung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (710,'audi-tt-rs-8j','Klimaanlage','Defekte am Klimakompressor oder undichte Leitungen können zu einem Ausfall der Klimaanlage führen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (711,'audi-rs-5-8t','Getriebe (S tronic)','Mögliche Probleme mit der Mechatronik und Schaltprobleme, insbesondere bei frühen Modellen.','2010-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (712,'audi-rs-5-8t','Kupplung','Verschleißerscheinungen und Ruckeln beim Anfahren können auftreten.','2010-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (713,'audi-rs-5-8t','Kühlersystem','Undichtigkeiten am Kühler und an den Schläuchen sind möglich.','2010-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (714,'audi-rs-5-8t','Rost','Besonders an den Radläufen, der Heckklappe und den Türkanten.','2010-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (715,'audi-rs-3-sportback-8p','S tronic Getriebe (DQ500)','Bei einigen Fahrzeugen können Ruckeln, Schaltverzögerungen oder Geräusche auftreten, insbesondere bei hohen Laufleistungen oder sportlicher Fahrweise. Dies kann auf Verschleiß der Kupplungen oder Probleme mit der Mechatronik hindeuten.','2011-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (716,'audi-rs-3-sportback-8p','Bremsanlage','Die Bremsanlage, insbesondere die vorderen Scheiben, kann bei sehr sportlicher Fahrweise oder auf der Rennstrecke an ihre Grenzen stoßen und zu erhöhtem Verschleiß oder Fading neigen. Geräusche beim Bremsen sind ebenfalls möglich.','2011-2012','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (717,'audi-rs-3-sportback-8p','Fahrwerk','Aufgrund der sportlichen Auslegung und des Alters können Verschleiß an Fahrwerkskomponenten wie Querlenkerlagern, Stoßdämpfern oder Domlagern auftreten, was sich durch Poltern oder eine unpräzise Lenkung bemerkbar machen kann.','2011-2012','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (718,'audi-rs-4-avant-b8','S tronic Getriebe','Probleme mit dem Doppelkupplungsgetriebe, insbesondere bei hohen Laufleistungen oder sportlicher Fahrweise. Kann sich durch Ruckeln, Schaltverzögerungen oder Notlauf bemerkbar machen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (719,'audi-rs-4-avant-b8','Bremsanlage','Hoher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere bei sportlicher Fahrweise. Die Keramikbremse (optional) ist langlebiger, aber sehr teuer im Ersatz.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (720,'audi-rs-4-avant-b8','Fahrwerk','Verschleiß an Querlenkern und Koppelstangen, was zu Poltergeräuschen oder unpräzisem Fahrverhalten führen kann. Das optionale Sportfahrwerk plus mit Dynamic Ride Control (DRC) kann Undichtigkeiten an den Dämpfern aufweisen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (721,'audi-rs-4-avant-b8','Ölverbrauch','Einige Fahrzeuge zeigen erhöhten Ölverbrauch, insbesondere bei sportlicher Fahrweise. Regelmäßige Kontrolle des Ölstands ist ratsam.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (722,'audi-rs-q3-8u','Bremsanlage','Bei sportlicher Fahrweise kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen. Vereinzelt wurden auch Geräusche oder Rubbeln der Bremsen berichtet.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (723,'audi-rs-q3-8u','Fahrwerk','Das RS-Sportfahrwerk ist straff ausgelegt. Bei Fahrzeugen mit hoher Laufleistung können Verschleiß an Querlenkerlagern oder Stoßdämpfern auftreten, was sich durch Poltergeräusche bemerkbar machen kann.','Ab ca. 2013','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (724,'audi-rs-q3-8u','Getriebe (S tronic)','Obwohl das S tronic-Getriebe im Allgemeinen robust ist, gab es in seltenen Fällen Berichte über Ruckeln oder Schaltprobleme, insbesondere bei hohen Laufleistungen. Ein regelmäßiger Getriebeölwechsel ist hier entscheidend.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (725,'audi-rs-6-avant-c7','Luftfahrwerk','Probleme mit undichten Luftfedern oder defekten Kompressoren können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen.','2013-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (726,'audi-rs-6-avant-c7','Getriebe (ZF 8HP)','Obwohl robust, können bei sehr hoher Laufleistung oder extremer Beanspruchung Schaltrucke oder verzögertes Schalten auftreten. Ölwechsel sind entscheidend.','2013-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (727,'audi-rs-6-avant-c7','Bremsanlage','Die serienmäßige Stahlbremsanlage kann bei sportlicher Fahrweise hohen Verschleiß zeigen. Die optionalen Keramikbremsen sind langlebiger, aber teuer im Ersatz.','2013-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (728,'audi-rs-7-sportback-c7','Luftfahrwerk','Probleme mit undichten Luftfedern oder Kompressoren können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Betrifft vor allem Fahrzeuge mit höherer Laufleistung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (729,'audi-rs-7-sportback-c7','Bremsanlage','Bei sehr sportlicher Fahrweise kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen. Die optionalen Keramikbremsen sind langlebiger, aber sehr teuer im Ersatz.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (730,'audi-rs-7-sportback-c7','MMI-Infotainmentsystem','Gelegentliche Software-Fehler, Abstürze oder Ausfälle des Bildschirms sind möglich. Meist durch Software-Updates behebbar.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (731,'audi-rs-7-sportback-c7','Getriebe (ZF 8-Gang-Automatik)','Obwohl das ZF 8HP-Getriebe als robust gilt, können bei extrem hoher Beanspruchung oder mangelnder Wartung (Ölwechsel) Schaltrucke oder Verzögerungen auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (732,'audi-rs-3-sportback-8v','Bremsanlage','Bei sportlicher Fahrweise kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen. Vereinzelt Berichte über rubbelnde Bremsen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (733,'audi-rs-3-sportback-8v','S-Tronic Getriebe (DQ500)','Obwohl das DQ500 als robust gilt, können bei sehr hoher Beanspruchung oder mangelnder Wartung (Ölwechsel) Probleme mit der Mechatronik oder dem Kupplungspaket auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (734,'audi-rs-3-sportback-8v','Fahrwerk (Magnetic Ride)','Bei Fahrzeugen mit optionalem Magnetic Ride Fahrwerk können im Alter Defekte an den Dämpfern auftreten, was zu einer verminderten Dämpfung oder Geräuschen führt.','Ältere Baujahre (ab ca. 5-7 Jahren)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (735,'audi-rs-5-b9','Getriebe (Automatik)','Vereinzelt Probleme mit der Schaltperformance und Haltbarkeit bei hoher Belastung. Regelmäßiger Getriebeölwechsel ist wichtig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (736,'audi-rs-5-b9','Motor (2.9 TFSI)','Potenzielle Probleme mit den Turboladern und der Kühlung bei frühen Modellen. Regelmäßige Inspektion empfohlen.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (737,'audi-rs-5-b9','Fahrwerk','Verschleiß an Fahrwerkskomponenten wie Stoßdämpfern und Querlenkern bei sportlicher Fahrweise.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (742,'audi-r8-typ-42','Kupplung (R tronic)','Bei Modellen mit dem automatisierten Schaltgetriebe R tronic kann es zu erhöhtem Verschleiß der Kupplung kommen, insbesondere bei sportlicher Fahrweise oder häufigem Rangieren. Dies äußert sich in Ruckeln beim Anfahren oder Schalten.','2006-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (743,'audi-r8-typ-42','Magnetische Dämpfer (Magnetic Ride)','Die adaptiven Dämpfer können im Laufe der Zeit undicht werden oder ihre Funktion verlieren, was zu einem schlechteren Fahrkomfort und Fahrverhalten führt. Ein Austausch ist kostspielig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (744,'audi-r8-typ-42','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen können zu einem Ausfall der Klimaanlage führen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (745,'audi-r8-typ-42','Ölverbrauch (V8-Motor)','Einige V8-Motoren können einen erhöhten Ölverbrauch aufweisen, der regelmäßig kontrolliert werden sollte.','2006-2015 (V8-Modelle)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (746,'audi-e-tron-2019','Ladeklappen','Probleme mit der Mechanik der elektrischen Ladeklappen, die sich nicht immer korrekt öffnen oder schließen.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (747,'audi-e-tron-2019','12V-Batterie','Vereinzelt Berichte über frühzeitige Entladung oder Defekte der 12V-Bordnetzbatterie, was zu Startproblemen führen kann.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (748,'audi-e-tron-2019','Software / Infotainment','Anfängliche Software-Bugs im MMI-System, die zu Abstürzen oder Fehlfunktionen führten. Meist durch Updates behoben.','2019-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (749,'audi-q4-e-tron-2021','Software/Infotainment','Berichte über gelegentliche Software-Fehler, Abstürze des Infotainmentsystems oder Probleme mit der Konnektivität.','2021-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (750,'audi-q4-e-tron-2021','12V-Batterie','Einige Nutzer berichteten von Problemen mit der 12V-Batterie, die zu Startschwierigkeiten oder Ausfällen von Komfortfunktionen führen können.','2021-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (751,'volkswagen-up-up','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse. Auch Rost an den Bremsscheiben bei geringer Nutzung ist ein Thema.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (752,'volkswagen-up-up','Auspuffanlage','Rostbildung am Endschalldämpfer und den Rohren, was zu vorzeitigem Austausch führen kann.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (753,'volkswagen-up-up','Fahrwerk (Achsen/Lenkung)','Vereinzelt können ausgeschlagene Spurstangenköpfe oder Traggelenke auftreten, was sich durch Poltergeräusche bemerkbar macht.','Ab ca. 80.000 km Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (754,'volkswagen-up-up','Zündkerzen/Zündspulen (Benziner)','Bei den 1.0 MPI Benzinmotoren können defekte Zündkerzen oder Zündspulen zu unrundem Motorlauf oder Leistungsverlust führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (755,'volkswagen-up-up','Getriebe (ASG automatisiertes Schaltgetriebe)','Das automatisierte Schaltgetriebe (ASG) kann ruckelig schalten oder Schaltpausen aufweisen. Vereinzelt gab es auch Probleme mit der Steuerung oder dem Aktuator.','Alle Baujahre mit ASG','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (756,'volkswagen-up-up-(facelift)','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse. Bei geringer Laufleistung können bereits Riefenbildung oder Rost auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (757,'volkswagen-up-up-(facelift)','Auspuffanlage','Rostbildung am Endschalldämpfer und den Rohren kann zu vorzeitigem Austausch führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (758,'volkswagen-up-up-(facelift)','Fahrwerk (Achsen und Lenkung)','Geringfügige Mängel an Achsaufhängungen und Lenkgelenken sind bei der HU feststellbar, jedoch selten gravierend.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (759,'volkswagen-polo-i','Rost','Der Polo I ist stark rostanfällig, insbesondere an Radläufen, Schwellern, Türen, Heckklappe und im Bereich der Federbeindome.','1975-1981','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (760,'volkswagen-polo-i','Bremsanlage','Verschleiß an Bremsleitungen, Bremsschläuchen und Radbremszylindern ist altersbedingt häufig. Auch festgerostete Bremsen sind ein Problem.','1975-1981','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (761,'volkswagen-polo-i','Motor','Ölverlust an Motor und Getriebe, verschlissene Zylinderkopfdichtungen und Probleme mit der Zündanlage sind typische Alterserscheinungen.','1975-1981','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (762,'volkswagen-polo-i','Fahrwerk','Verschlissene Stoßdämpfer, Federbrüche und ausgeschlagene Gummilager sind häufige Mängel.','1975-1981','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (763,'volkswagen-polo-ii','Rost','Besonders an Radläufen, Schwellern, Türen und Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (764,'volkswagen-polo-ii','Fahrwerk','Verschleiß an Querlenkern, Stoßdämpfern und Buchsen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (765,'volkswagen-polo-ii','Elektrik','Probleme mit der Verkabelung, Schaltern und Instrumentenbeleuchtung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (766,'volkswagen-polo-iii','Querlenkerlager','Verschleiß der Gummilager an den Querlenkern der Vorderachse führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (767,'volkswagen-polo-iii','Bremsanlage','Rost an den Bremsscheiben und -leitungen, insbesondere an der Hinterachse, kann zu ungleichmäßiger Bremswirkung führen. Festgehende Bremssättel sind ebenfalls ein Problem.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (768,'volkswagen-polo-iii','Zündanlage','Probleme mit Zündspulen und Zündkabeln, insbesondere bei den 1.4-Liter-Motoren, können zu Motorruckeln und Leistungsverlust führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (769,'volkswagen-polo-iii','Auspuffanlage','Durchrostung der Auspuffanlage, insbesondere des Endschalldämpfers, ist ein häufiges Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (770,'volkswagen-polo-iii','Fensterheber','Defekte an den elektrischen Fensterhebern, oft durch gebrochene Plastikführungen oder defekte Motoren.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (771,'volkswagen-polo-iii','Wegfahrsperre','Probleme mit der Wegfahrsperre, die das Starten des Motors verhindert, oft durch defekte Lesespulen oder Steuergeräte.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (772,'volkswagen-polo-iv','Rost','An Radläufen, Schwellern und Türkanten.','2001-2009','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (773,'volkswagen-polo-iv','Elektrik','Probleme mit Fensterhebern, Zentralverriegelung, Klimaanlage.','2001-2009','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (774,'volkswagen-polo-iv','Fahrwerk','Verschleiß an Stoßdämpfern und Querlenkern.','2001-2009','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (775,'volkswagen-polo-v','Steuerkette (1.2 TSI, 1.4 TSI)','Probleme mit gelängten Steuerketten und defekten Kettenspannern können zu Motorschäden führen. Äußert sich durch Rasseln nach dem Kaltstart.','2009-2014 (vor allem frühe Baujahre des 1.2 TSI/1.4 TSI)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (776,'volkswagen-polo-v','Wasserpumpe (1.2 TSI, 1.4 TSI)','Undichtigkeiten an der Wasserpumpe, oft in Verbindung mit dem Thermostatgehäuse, führen zu Kühlmittelverlust.','2009-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (777,'volkswagen-polo-v','DSG-Getriebe (DQ200, 7-Gang)','Probleme mit der Mechatronik und dem Trockenkupplungspaket können zu Ruckeln, Schaltfehlern oder komplettem Ausfall führen.','2009-2014 (insbesondere frühe Baujahre)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (778,'volkswagen-polo-v','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (779,'volkswagen-polo-v','Fahrwerk (Querlenkerlager, Stoßdämpfer)','Verschleiß der Querlenkerlager und Stoßdämpfer kann zu Poltergeräuschen und beeinträchtigtem Fahrverhalten führen.','Ab ca. 80.000 km Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (780,'volkswagen-polo-vi','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse. Kann zu Rubbeln oder Geräuschen führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (781,'volkswagen-polo-vi','Fahrwerk (Achsen/Lenkung)','Bei der Hauptuntersuchung werden überdurchschnittlich oft Mängel an Achsen, Lenkung und Radaufhängung festgestellt, insbesondere ausgeschlagene Spurstangenköpfe oder defekte Gelenke.','Ab ca. 2019/2020 (mit zunehmendem Alter/Laufleistung)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (782,'volkswagen-polo-vi','Beleuchtung','Mängel an der Beleuchtungsanlage, insbesondere Scheinwerfer und Rückleuchten, sind häufiger als beim Durchschnitt. Dies kann von defekten Leuchtmitteln bis zu Problemen mit der Einstellung reichen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (783,'volkswagen-polo-vi','1.0 TSI Motoren (speziell EA211)','Einige Berichte über erhöhten Ölverbrauch oder Ruckeln bei bestimmten 1.0 TSI Motoren. Dies ist jedoch nicht flächendeckend und betrifft eher Einzelfälle.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (784,'volkswagen-golf-i','Rost','Der Golf I ist stark rostanfällig, insbesondere an Radläufen, Schwellern, Türen, Heckklappe, Tankstutzenbereich und den Federbeinaufnahmen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (785,'volkswagen-golf-i','Motor','Bei den Benzinmotoren können Probleme mit der Zündung, dem Vergaser (insbesondere bei älteren Modellen) und der Ölversorgung auftreten. Dieselmotoren sind robust, aber bei mangelnder Wartung anfällig für Zylinderkopfdichtungsschäden.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (786,'volkswagen-golf-i','Getriebe','Verschleiß an den Synchronringen, insbesondere im zweiten Gang, ist häufig. Auch Undichtigkeiten können auftreten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (787,'volkswagen-golf-i','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt üblich. Die Federbeinaufnahmen sind rostanfällig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (788,'volkswagen-golf-i','Elektrik','Altersbedingte Probleme mit Kabelbrüchen, korrodierten Kontakten und Ausfällen von Lichtmaschine oder Anlasser sind möglich.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (789,'volkswagen-golf-ii','Rost','Rostbildung an Radläufen, Schwellern, Tankstutzenbereich, Heckklappe und im Bereich der Windschutzscheibe ist häufig. Auch die Wagenheberaufnahmen sind oft betroffen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (790,'volkswagen-golf-ii','Bremsanlage','Verschleiß an Bremsscheiben und -belägen, festgerostete Bremssättel hinten (insbesondere bei Scheibenbremsen) und undichte Bremsleitungen sind altersbedingt häufig.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (791,'volkswagen-golf-ii','Kühlsystem','Undichtigkeiten an Kühlerschläuchen, Wasserpumpe und Kühler selbst sind altersbedingt möglich. Thermostat kann klemmen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (792,'volkswagen-golf-ii','Elektrik','Probleme mit der Elektrik können auftreten, insbesondere bei älteren Kabelbäumen. Typisch sind Ausfälle von Fensterhebern, Zentralverriegelung oder Beleuchtung. Korrosion an Steckverbindungen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (793,'volkswagen-golf-ii','G-Lader (G60-Modelle)','Der G-Lader ist ein hochbelastetes Bauteil und kann bei mangelnder Wartung oder hoher Laufleistung verschleißen, was zu Leistungsverlust und teuren Reparaturen führt.','Alle Baujahre (G60)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (794,'volkswagen-golf-iii','Rost','Rostbildung an Radläufen, Schwellern, Heckklappe (insbesondere unter der Griffleiste), Tankdeckel und im Bereich der Wagenheberaufnahmen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (795,'volkswagen-golf-iii','Hinterachslager','Verschleiß der Hinterachslager führt zu Poltergeräuschen und beeinträchtigtem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (796,'volkswagen-golf-iii','Fensterheber','Defekte an den elektrischen Fensterhebern, oft durch gebrochene Kunststoffteile oder Seilzüge.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (797,'volkswagen-golf-iii','Wegfahrsperre','Probleme mit der elektronischen Wegfahrsperre (Transponder im Schlüssel, Lesespule), die das Starten des Motors verhindern.','Ab ca. 1994','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (798,'volkswagen-golf-iii','Zündverteiler','Defekte am Zündverteiler (insbesondere bei den 1.8L und 2.0L Motoren) können zu Zündaussetzern und schlechtem Motorlauf führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (799,'volkswagen-golf-iii','Kühlsystem','Undichtigkeiten an Kühler, Schläuchen oder Wasserpumpe, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (800,'volkswagen-golf-iii','Getriebe (Schaltgetriebe)','Verschleiß an den Synchronringen, insbesondere im 2. Gang, was zu schwergängigen oder kratzenden Schaltvorgängen führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (801,'volkswagen-golf-iv','Fensterheber','Defekte Fensterhebermechanismen, insbesondere die Kunststoffgleiter, führen zum Herunterfallen der Scheibe.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (802,'volkswagen-golf-iv','Türschlösser/Mikroschalter','Defekte Mikroschalter in den Türschlössern führen zu Fehlfunktionen der Zentralverriegelung, Innenbeleuchtung oder Alarmanlage.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (803,'volkswagen-golf-iv','Luftmassenmesser (LMM)','Besonders bei TDI-Motoren kann der LMM ausfallen, was zu Leistungsverlust führt.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (804,'volkswagen-golf-iv','Querlenkerlager','Verschleiß der Gummilager an den Querlenkern der Vorderachse führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (805,'volkswagen-golf-iv','Rost','Rost kann an den vorderen Kotflügeln (im Bereich der Schweller), an der Heckklappe (Griffleiste) und an den Schwellern auftreten.','Ältere Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (806,'volkswagen-golf-iv','Zündspulen','Bei Benzinmotoren, insbesondere den 1.8T-Motoren, können Zündspulen ausfallen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (807,'volkswagen-golf-v','Steuerkette (TSI-Motoren)','Bei den 1.4 TSI-Motoren (insbesondere den frühen Baujahren) kann es zu Problemen mit der Steuerkette kommen, die sich längt und zu unruhigem Motorlauf, Rasseln oder im schlimmsten Fall zu einem Motorschaden führen kann.','2003-2008 (insbesondere 1.4 TSI)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (808,'volkswagen-golf-v','Turbolader (TSI-Motoren)','Defekte Turbolader sind bei den TSI-Motoren keine Seltenheit. Anzeichen sind Leistungsverlust, erhöhter Ölverbrauch oder pfeifende Geräusche.','2003-2008 (insbesondere 1.4 TSI)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (809,'volkswagen-golf-v','Zweimassenschwungrad (Dieselmotoren)','Bei Dieselmotoren kann das Zweimassenschwungrad verschleißen, was sich durch Ruckeln beim Anfahren, Vibrationen oder Klappergeräusche bemerkbar macht.','2003-2008 (insbesondere 1.9 TDI, 2.0 TDI)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (810,'volkswagen-golf-v','Injektoren (2.0 TDI PD-Motoren)','Die Pumpe-Düse-Injektoren der frühen 2.0 TDI-Motoren können ausfallen, was zu unrundem Motorlauf, Leistungsverlust oder Startschwierigkeiten führt. Dies betrifft vor allem die Motoren mit Siemens-Injektoren.','2003-2005 (2.0 TDI PD)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (811,'volkswagen-golf-v','Rost (Heckklappe, Kotflügel)','Rostbildung kann an der Heckklappe (insbesondere im Bereich der Kennzeichenbeleuchtung und des VW-Emblems) sowie an den vorderen Kotflügeln (im Bereich der Schwellerübergänge) auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (812,'volkswagen-golf-v','Elektronik (Fensterheber, Zentralverriegelung)','Probleme mit der Fahrzeugelektronik, wie defekte Fensterhebermotoren, Steuergeräte für die Zentralverriegelung oder Ausfälle von Sensoren, sind bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (813,'volkswagen-golf-v','Klimaanlage','Undichtigkeiten im Klimasystem oder Defekte am Klimakompressor können zu einem Ausfall der Klimaanlage führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (814,'volkswagen-golf-vi','Steuerkette (TSI-Motoren)','Probleme mit gelängten Steuerketten und defekten Kettenspannern, was zu Motorschäden führen kann. Betrifft vor allem die 1.2 TSI und 1.4 TSI Motoren.','2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (815,'volkswagen-golf-vi','Wasserpumpe (TSI-Motoren)','Undichtigkeiten und Defekte an der Wasserpumpe, oft in Verbindung mit dem Thermostatgehäuse.','2008-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (816,'volkswagen-golf-vi','DSG-Getriebe (DQ200, 7-Gang)','Probleme mit dem Mechatronik-Modul und der Kupplung, was zu Ruckeln, Schaltproblemen oder komplettem Ausfall führen kann.','2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (817,'volkswagen-golf-vi','Injektoren (TDI-Motoren)','Ausfälle der Piezo-Injektoren bei den 2.0 TDI Motoren, was zu unrundem Motorlauf oder Leistungsverlust führt.','2008-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (818,'volkswagen-golf-vi','Rost','Vereinzelt Rost an der Heckklappe (Griffleiste), den Radläufen oder unter den Türdichtungen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (819,'volkswagen-golf-vii','DSG-Automatikgetriebe','Bei einigen Modellen können Probleme mit der Mechatronik oder Kupplung auftreten, was zu Ruckeln oder Schaltproblemen führt.','2012-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (820,'volkswagen-golf-vii','TSI-Motoren (Steuerkette)','Bei einigen älteren TSI-Motoren kann es zu Problemen mit der Steuerkette (Längung, Überspringen) kommen, was zu Motorschäden führen kann.','2012-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (821,'volkswagen-golf-vii','Klimaanlage','Gelegentlich Ausfälle des Klimakompressors oder Undichtigkeiten im System.','2013-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (822,'volkswagen-golf-viii','Software/Infotainment','Anfängliche Modelle litten unter zahlreichen Softwarefehlern, Abstürzen des Infotainmentsystems, Fehlermeldungen und Problemen mit der Konnektivität. Updates haben die Situation verbessert, aber nicht vollständig behoben.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (823,'volkswagen-golf-viii','12V-Batterie','Berichte über frühzeitige Entladung oder Defekte der 12V-Starterbatterie, insbesondere bei Fahrzeugen mit vielen Kurzstrecken oder längeren Standzeiten.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (824,'volkswagen-golf-viii','eTSI (Mild-Hybrid) System','Vereinzelt gab es Probleme mit dem 48V-Mild-Hybrid-System, die zu Fehlermeldungen oder Leistungsverlust führen konnten.','2020-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (825,'volkswagen-golf-viii','Verarbeitung/Materialqualität Innenraum','Kritik an der Materialauswahl und Verarbeitungsqualität im Innenraum, insbesondere bei den Basismodellen, die im Vergleich zum Vorgänger als weniger wertig empfunden wurden (z.B. Hartplastik, Knarzgeräusche).','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (826,'volkswagen-passat-b1','Rost','Der Passat B1 ist stark rostanfällig, insbesondere an Radläufen, Schwellern, Türen, Heckklappe, Tankstutzenbereich und den Federbeinaufnahmen.','Alle Baujahre (1973-1981)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (827,'volkswagen-passat-b1','Motor','Die Motoren gelten als robust, können aber bei mangelnder Wartung Ölverlust und Verschleiß an Nockenwellen und Hydrostößeln aufweisen. Die Vergaser können im Alter Probleme bereiten.','Alle Baujahre (1973-1981)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (828,'volkswagen-passat-b1','Getriebe','Manuelle Getriebe sind meist langlebig, können aber bei hohen Laufleistungen und schlechter Wartung Geräusche entwickeln oder schwergängig werden. Automatikgetriebe sind seltener und können anfälliger sein.','Alle Baujahre (1973-1981)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (829,'volkswagen-passat-b1','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt häufig. Die Bremsanlage kann bei längeren Standzeiten festrosten.','Alle Baujahre (1973-1981)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (830,'volkswagen-passat-b1','Elektrik','Altersbedingte Probleme mit Kabelbrüchen, korrodierten Kontakten und Ausfällen von Lichtmaschine oder Anlasser sind möglich.','Alle Baujahre (1973-1981)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (831,'volkswagen-passat-b2','Rost','Der Passat B2 ist anfällig für Rost, insbesondere an Radläufen, Schwellern, Türen, Heckklappe (Variant) und den Federbeinaufnahmen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (832,'volkswagen-passat-b2','Bremsanlage','Verschleiß an Bremsscheiben und -belägen, festgerostete Bremssättel und undichte Bremsleitungen sind häufige Probleme.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (833,'volkswagen-passat-b2','Fahrwerk','Verschlissene Querlenkerlager, Spurstangenköpfe und Stoßdämpfer führen zu unpräzisem Fahrverhalten und Geräuschen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (834,'volkswagen-passat-b2','Elektrik','Probleme mit der Elektrik können auftreten, z.B. defekte Lichtmaschinen, Anlasser, Fensterheber oder Korrosion an Steckverbindungen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (835,'volkswagen-passat-b2','Kraftstoffsystem (Vergaser)','Bei Vergasermotoren können Undichtigkeiten, verstopfte Düsen oder Probleme mit der Kaltstartautomatik auftreten.','Alle (Vergasermodelle)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (836,'volkswagen-passat-b3','Rost','Rostbildung an Radläufen, Schwellern, Heckklappe (insbesondere beim Variant) und Tankdeckelbereich ist häufig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (837,'volkswagen-passat-b3','Elektronik','Probleme mit der Elektrik, insbesondere Fensterhebern, Zentralverriegelung und der Instrumentenbeleuchtung, können auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (838,'volkswagen-passat-b3','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern ist altersbedingt häufig.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (839,'volkswagen-passat-b3','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe sind altersbedingt möglich und können zu Überhitzung führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (840,'volkswagen-passat-b4','Vorderachse','Verschleiß an Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (841,'volkswagen-passat-b4','Rost','Rost kann an den Radläufen, Schwellern und am Unterboden auftreten, insbesondere bei schlecht gepflegten Exemplaren.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (842,'volkswagen-passat-b4','Elektronik','Probleme mit der Elektrik, insbesondere Fensterhebern, Zentralverriegelung und der Beleuchtung, sind altersbedingt möglich.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (843,'volkswagen-passat-b4','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe können zu Kühlmittelverlust und Überhitzung führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (844,'volkswagen-passat-b4','Dieselmotoren (TDI)','Bei den TDI-Motoren können Probleme mit dem Turbolader, der Einspritzpumpe und dem Zahnriemen auftreten, wenn Wartungsintervalle nicht eingehalten wurden.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (845,'volkswagen-passat-b5','Vorderachse (Mehrlenkerachse)','Verschleiß an den Querlenkern und Spurstangenköpfen führt zu Poltergeräuschen, unpräzisem Fahrverhalten und erhöhtem Reifenverschleiß. Besonders betroffen sind die oberen Querlenker.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (846,'volkswagen-passat-b5','Turbolader (insbesondere 1.8T und TDI)','Defekte Turbolader aufgrund von mangelnder Ölversorgung, Überhitzung oder Materialermüdung. Symptome sind Leistungsverlust, erhöhter Ölverbrauch und pfeifende Geräusche.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (847,'volkswagen-passat-b5','Fensterheber','Defekte an den Fensterhebermechanismen, oft durch gebrochene Kunststoffteile oder Seilzüge. Fenster lassen sich nicht mehr öffnen oder schließen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (848,'volkswagen-passat-b5','Kühlmitteltemperatursensor','Fehlfunktionen des Sensors können zu ungenauen Temperaturanzeigen, erhöhtem Kraftstoffverbrauch oder Startschwierigkeiten führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (849,'volkswagen-passat-b5','Luftmassenmesser (LMM)','Defekte LMM führen zu Leistungsverlust, Ruckeln und erhöhtem Kraftstoffverbrauch, da die Motorsteuerung falsche Luftmengenwerte erhält.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (850,'volkswagen-passat-b5','Rost','Rostbildung kann an den vorderen Kotflügeln (im Bereich der Schweller und Radläufe), an der Heckklappe (insbesondere beim Variant unter der Chromleiste) und an den Türunterkanten auftreten.','Ältere Baujahre, insbesondere vor Facelift','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (851,'volkswagen-passat-b6','Steuerkette (1.4 TSI, 1.8 TSI, 2.0 TSI)','Probleme mit gelängten Steuerketten und defekten Kettenspannern können zu Motorschäden führen. Symptome sind Rasseln beim Kaltstart.','2007-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (852,'volkswagen-passat-b6','DSG-Getriebe (DQ200, 7-Gang Trockenkupplung)','Probleme mit der Mechatronik und verschleißenden Kupplungen können zu Ruckeln, Schaltproblemen oder komplettem Ausfall führen.','2007-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (853,'volkswagen-passat-b6','Ölverbrauch (1.8 TSI, 2.0 TSI)','Erhöhter Ölverbrauch aufgrund von Kolbenringen, die nicht richtig abdichten. Kann zu Motorschäden führen, wenn nicht regelmäßig kontrolliert und nachgefüllt wird.','2007-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (854,'volkswagen-passat-b6','Elektronik (Feststellbremse, Lenksäulensteuergerät)','Ausfälle der elektronischen Parkbremse (oft durch defekte Stellmotoren oder Kabelbaum) und Probleme mit dem Lenksäulensteuergerät (Lenkradschloss, Zündschloss) sind häufig.','2005-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (855,'volkswagen-passat-b6','Injektoren (2.0 TDI PD)','Defekte Piezo-Injektoren können zu unrundem Motorlauf, Leistungsverlust und im schlimmsten Fall zu Motorschäden führen. Betrifft vor allem die Pumpe-Düse-Motoren.','2005-2008','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (856,'volkswagen-passat-b6','Turbolader (TSI- und TDI-Motoren)','Defekte Turbolader, oft durch mangelnde Ölversorgung oder Materialermüdung, können zu Leistungsverlust und teuren Reparaturen führen.','2005-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (857,'volkswagen-passat-b6','Rost (Heckklappe, Türen)','Rostbildung an der Heckklappe (insbesondere um das Kennzeichenlicht) und an den Türkanten ist ein bekanntes Problem.','2005-2010','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (858,'volkswagen-passat-b7','Steuerkette (bei 1.4 TSI und 1.8 TSI)','Kann sich längen, was zu unruhigem Motorlauf, Rasseln beim Kaltstart und im schlimmsten Fall zu Motorschäden führen kann. Betrifft vor allem frühe Baujahre.','2010-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (859,'volkswagen-passat-b7','DSG-Getriebe (insbesondere DQ200 7-Gang-Trockenkupplung)','Probleme mit Ruckeln, Schaltverzögerungen oder Ausfällen der Mechatronik. Kann teure Reparaturen nach sich ziehen.','Alle Baujahre, besonders bei hohen Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (860,'volkswagen-passat-b7','Wasserpumpe (bei TSI-Motoren)','Undichtigkeiten oder Ausfälle der Wasserpumpe, oft in Verbindung mit dem Thermostatgehäuse, führen zu Kühlmittelverlust und Überhitzung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (861,'volkswagen-passat-b7','Injektoren (bei 2.0 TDI Common-Rail)','Defekte Injektoren können zu unrundem Motorlauf, Leistungsverlust und erhöhtem Kraftstoffverbrauch führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (862,'volkswagen-passat-b7','Elektronik (diverse)','Ausfälle von Komfortelektronik wie Fensterhebern, Klimaanlage oder Infotainmentsystem. Auch Probleme mit der Parkbremse sind bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (863,'volkswagen-passat-b8','Wasserpumpe','Undichtigkeiten und Defekte an der Wasserpumpe, insbesondere bei den 1.4 TSI und 2.0 TSI Motoren.','2014-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (864,'volkswagen-passat-b8','DSG-Getriebe (DQ200, 7-Gang-Trockenkupplung)','Probleme mit der Mechatronik, Ruckeln beim Anfahren oder Schalten, erhöhter Verschleiß der Kupplungen. Betrifft vor allem die kleineren Motorisierungen.','2014-2017','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (865,'volkswagen-passat-b8','AdBlue-System','Fehlermeldungen und Ausfälle des AdBlue-Systems, insbesondere der NOx-Sensoren oder der AdBlue-Pumpe, was zu Notlauf oder Startverweigerung führen kann.','2015-2020','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (866,'volkswagen-passat-b8','Infotainmentsystem (Software)','Gelegentliche Software-Abstürze, langsame Reaktion oder Verbindungsprobleme mit Bluetooth/Apple CarPlay/Android Auto.','2014-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (867,'volkswagen-passat-b8','Elektronische Parkbremse','Fehlfunktionen oder Blockieren der elektronischen Parkbremse, oft durch defekte Stellmotoren an den hinteren Bremssätteln.','2014-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (868,'volkswagen-arteon-typ-3h','Infotainmentsystem','Vereinzelt Berichte über Softwareprobleme, Abstürze oder langsame Reaktionen des Discover Media/Pro Systems, insbesondere in den frühen Baujahren vor dem Facelift.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (869,'volkswagen-arteon-typ-3h','Elektronik/Sensoren','Meldungen über Fehlfunktionen von Assistenzsystemen (z.B. Parksensoren, Spurhalteassistent) oder sporadische Fehlermeldungen im Kombiinstrument.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (870,'volkswagen-arteon-typ-3h','DSG-Getriebe (DQ381/DQ500)','Obwohl im Allgemeinen robust, können bei hohen Laufleistungen oder unsachgemäßer Wartung (Ölwechsel) Ruckeln oder Schaltverzögerungen auftreten. Dies ist jedoch kein spezifisches Arteon-Problem, sondern betrifft VW-Modelle mit DSG generell.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (871,'volkswagen-t-roc-a1','Infotainmentsystem','Insbesondere bei frühen Modellen können Softwareprobleme, Abstürze oder langsame Reaktionen des Infotainmentsystems auftreten. Nach dem Facelift wurden die Touch-Bedienelemente für die Klimaanlage kritisiert, da sie während der Fahrt weniger intuitiv zu bedienen sind als physische Knöpfe.','2017-2020 (Softwareprobleme), ab 2021 (Bedienung Touch-Slider)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (872,'volkswagen-t-roc-a1','Verarbeitungsqualität Innenraum','Einige Nutzer bemängeln die Verwendung von Hartplastik im Innenraum, insbesondere an den Türverkleidungen und im unteren Bereich des Armaturenbretts, was dem Premium-Anspruch von VW nicht immer gerecht wird. Dies kann zu Knister- oder Klappergeräuschen führen.','2017-2021 (vor Facelift stärker ausgeprägt)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (873,'volkswagen-t-roc-a1','1.5 TSI Motor (ACT-System)','Bei einigen Fahrzeugen mit dem 1.5 TSI Motor (insbesondere in Verbindung mit dem ACT-System zur Zylinderabschaltung) wurden Ruckeln oder Anfahrschwächen bei niedrigen Drehzahlen berichtet. Dies ist oft auf Software-Optimierungen zurückzuführen und kann durch Updates behoben werden.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (874,'volkswagen-t-cross-c1','Infotainmentsystem','Gelegentliche Berichte über Softwareprobleme, Abstürze oder langsame Reaktionen des Infotainmentsystems, insbesondere bei frühen Baujahren.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (875,'volkswagen-t-cross-c1','Knarzgeräusche im Innenraum','Einige Nutzer berichten über Knarz- oder Klappergeräusche aus dem Armaturenbrett oder den Türverkleidungen, insbesondere bei unebener Fahrbahn.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (876,'volkswagen-t-cross-c1','Bremsen','Vereinzelt wurden überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse, sowie Geräusche beim Bremsen gemeldet.','2019-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (877,'volkswagen-tiguan-i','Steuerkette (TSI-Motoren)','Bei den 1.4 TSI und frühen 2.0 TSI Motoren kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen. Dies kann zu Motorschäden führen.','2007-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (878,'volkswagen-tiguan-i','Turbolader (TSI-Motoren)','Defekte Turbolader, insbesondere bei den 1.4 TSI Motoren, können zu Leistungsverlust und erhöhtem Ölverbrauch führen.','2007-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (879,'volkswagen-tiguan-i','Wasserpumpe','Undichtigkeiten an der Wasserpumpe, oft in Verbindung mit dem Thermostatgehäuse, sind keine Seltenheit und können zu Kühlmittelverlust führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (880,'volkswagen-tiguan-i','DSG-Getriebe (DQ200)','Das 7-Gang-DSG (DQ200) kann bei frühen Modellen Probleme mit der Mechatronik oder dem Kupplungspaket aufweisen, was zu Ruckeln oder Schaltfehlern führt.','2007-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (881,'volkswagen-tiguan-i','Injektoren (Dieselmotoren)','Bei den 2.0 TDI Motoren können die Injektoren ausfallen, was zu unrundem Motorlauf oder Leistungsverlust führt.','2007-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (882,'volkswagen-tiguan-i','Partikelfilter (Dieselmotoren)','Verstopfungen des Dieselpartikelfilters (DPF) können bei Kurzstreckenfahrzeugen auftreten und zu Leistungsverlust und erhöhten Emissionen führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (883,'volkswagen-tiguan-i','Elektronik','Vereinzelt können Fehlermeldungen oder Ausfälle von Komfortelektronik (z.B. Fensterheber, Infotainment) auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (884,'volkswagen-tiguan-ii','DSG-Getriebe (DQ200)','Bei frühen Modellen des Tiguan II mit dem 7-Gang-DSG (DQ200, Trockenkupplung) können Ruckeln, Schaltprobleme oder vorzeitiger Verschleiß der Kupplung auftreten. Betrifft vor allem kleinere Motorisierungen.','2016-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (885,'volkswagen-tiguan-ii','Wasserpumpe','Undichtigkeiten oder Defekte an der Wasserpumpe, insbesondere bei den 1.4 TSI Motoren, können zu Kühlmittelverlust und Überhitzung führen.','2016-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (886,'volkswagen-tiguan-ii','Infotainmentsystem','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des Infotainmentsystems wurden berichtet. Meist durch Software-Updates behebbar.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (887,'volkswagen-tiguan-ii','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder sportlicher Fahrweise.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (888,'volkswagen-touran-i','Steuerkette (1.4 TSI)','Bei den 1.4 TSI Motoren (insbesondere bis ca. 2010) kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen und im schlimmsten Fall zu Motorschäden führen können.','2006-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (889,'volkswagen-touran-i','DSG-Getriebe (DQ200)','Das 7-Gang-DSG-Getriebe (DQ200) kann insbesondere bei frühen Baujahren zu Ruckeln, Schaltproblemen oder Ausfällen der Mechatronik neigen.','2003-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (890,'volkswagen-touran-i','Turbolader (1.4 TSI, 2.0 TDI)','Defekte Turbolader können bei den TSI- und TDI-Motoren auftreten, oft erkennbar an Leistungsverlust, ungewöhnlichen Geräuschen oder blauem Rauch.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (891,'volkswagen-touran-i','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen sind keine Seltenheit, was zu einem Ausfall der Klimafunktion führt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (892,'volkswagen-touran-i','Elektronik','Diverse Elektronikprobleme, wie defekte Fensterheber, Probleme mit der Zentralverriegelung oder Ausfälle von Sensoren, können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (893,'volkswagen-touran-i','Rost','Rost kann an der Heckklappe (insbesondere im Bereich der Kennzeichenbeleuchtung) und an den Türkanten auftreten.','Frühe Baujahre (bis ca. 2007)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (894,'volkswagen-touran-ii','Kupplung (DSG-Getriebe)','Bei einigen Modellen mit DSG-Automatikgetriebe gab es Berichte über vorzeitigen Verschleiß oder Probleme mit der Kupplung.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (895,'volkswagen-touran-ii','Elektronik (Infotainment)','Gelegentliche Software-Probleme oder Aussetzer des Infotainmentsystems, insbesondere bei älteren Modellen vor dem Facelift.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (896,'volkswagen-touran-ii','Partikelfilter (Diesel)','Bei häufigen Kurzstreckenfahrten kann es zu einer Verstopfung des Dieselpartikelfilters kommen.','Alle Diesel-Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (897,'volkswagen-touareg-i','Luftfederung','Defekte Kompressoren, undichte Federbeine oder Ventile können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders bei älteren Modellen und hoher Laufleistung.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (898,'volkswagen-touareg-i','Kardanwelle / Mittellager','Verschleiß des Mittellagers der Kardanwelle kann zu Vibrationen und Geräuschen führen. Ein Austausch ist oft aufwendig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (899,'volkswagen-touareg-i','Getriebe (Automatik)','Probleme mit dem Automatikgetriebe, insbesondere bei den V10 TDI-Modellen, können auftreten. Dazu gehören Schaltrucke, Notlauf oder Totalausfall. Regelmäßige Getriebeölwechsel sind hier entscheidend.','Alle Baujahre, besonders V10 TDI','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (900,'volkswagen-touareg-i','Elektronik','Diverse Elektronikprobleme, wie defekte Steuergeräte, Probleme mit der Zentralverriegelung, Fensterhebern oder dem Infotainmentsystem, sind bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (901,'volkswagen-touareg-i','Bremsanlage','Hoher Verschleiß an Bremsbelägen und -scheiben, insbesondere bei den schwereren Motorisierungen und sportlicher Fahrweise. Auch festkorrodierte Bremssättel können vorkommen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (902,'volkswagen-touareg-ii','Luftfederung','Defekte Kompressoren, undichte Federbeine oder Ventile können zu einem Absinken des Fahrzeugs oder Fehlermeldungen führen. Besonders bei älteren Fahrzeugen oder hoher Laufleistung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (903,'volkswagen-touareg-ii','Automatikgetriebe (8-Gang-Tiptronic)','Ruckeln beim Schalten, verzögerte Gangwechsel oder Notlaufprogramme können auf Probleme mit der Mechatronik oder verschlissene Kupplungspakete hindeuten. Oft durch unzureichende Getriebeölwechselintervalle begünstigt.','Alle Baujahre, insbesondere bei hoher Laufleistung','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (904,'volkswagen-touareg-ii','Panoramadach','Undichtigkeiten, Knarzgeräusche oder Defekte an der Mechanik des Schiebedachs sind bekannt. Verstopfte Abläufe können zu Wassereintritt führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (905,'volkswagen-touareg-ii','Elektronik / Infotainment','Ausfälle des Navigationssystems, des Radios oder anderer elektronischer Komponenten. Gelegentlich auch Fehlermeldungen ohne ersichtlichen Grund.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (906,'volkswagen-touareg-ii','Dieselmotoren (V6 TDI)','Probleme mit der Abgasrückführung (AGR-Ventil), Injektoren oder dem Dieselpartikelfilter (DPF) können auftreten, insbesondere bei Kurzstreckenbetrieb. Auch Steuerkettenprobleme sind vereinzelt bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (907,'volkswagen-touareg-iii','Infotainmentsystem (Innovision Cockpit)','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des Systems wurden berichtet. Updates können Abhilfe schaffen.','2018-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (908,'volkswagen-touareg-iii','Luftfederung','Vereinzelt Berichte über Undichtigkeiten oder Fehlfunktionen der Luftfederung, die zu einem Absinken des Fahrzeugs führen können. Dies ist jedoch nicht weit verbreitet.','2018-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (909,'volkswagen-touareg-iii','Elektronik (allgemein)','Wie bei vielen modernen Fahrzeugen können sporadisch kleinere Elektronikfehler auftreten, die sich in Fehlermeldungen oder dem Ausfall einzelner Funktionen äußern. Oft durch Software-Updates behebbar.','2018-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (910,'volkswagen-caddy-ii','Rost','Rostbildung an Radläufen, Schwellern, Türen und der Heckklappe ist ein häufiges Problem, insbesondere bei älteren Modellen und Fahrzeugen, die im Winterbetrieb eingesetzt wurden.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (911,'volkswagen-caddy-ii','Bremsanlage','Verschleiß an Bremsscheiben und -belägen, sowie festrostende Bremssättel, insbesondere an der Hinterachse, sind typisch. Auch die Bremsleitungen können von Korrosion betroffen sein.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (912,'volkswagen-caddy-ii','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Die Hinterachse kann bei hoher Belastung durchhängen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (913,'volkswagen-caddy-ii','Elektrik','Probleme mit der Elektrik, wie defekte Fensterheber, Zentralverriegelung oder Beleuchtungsausfälle, können auftreten. Auch die Verkabelung im Motorraum kann altersbedingt spröde werden.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (914,'volkswagen-caddy-iii','Kupplung','Bei einigen Modellen, insbesondere mit höheren Laufleistungen, kann es zu Verschleißerscheinungen an der Kupplung kommen.','2003-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (915,'volkswagen-caddy-iii','Turbolader','Bei Dieselmotoren kann es vereinzelt zu Problemen mit dem Turbolader kommen, insbesondere bei mangelnder Wartung oder Kurzstreckenbetrieb.','2003-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (916,'volkswagen-caddy-iii','Rost','An Radläufen, Schwellern und im Bereich der Heckklappe kann es zu Rostbildung kommen, besonders bei Fahrzeugen, die viel im Winterdienst eingesetzt wurden.','2003-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (917,'volkswagen-caddy-iii','Elektronik','Vereinzelt können Probleme mit der Bordelektronik auftreten, z.B. defekte Sensoren oder Probleme mit dem Infotainmentsystem.','2003-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (918,'volkswagen-caddy-iv','Dieselpartikelfilter (DPF)','Bei Fahrzeugen mit hohem Kurzstreckenanteil kann es zu einer vorzeitigen Verstopfung des DPF kommen, was zu Leistungsverlust und Notlauf führt.','Alle Baujahre mit Dieselmotoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (919,'volkswagen-caddy-iv','Wasserpumpe','Undichtigkeiten oder Lagerschäden an der Wasserpumpe können zu Kühlmittelverlust und Überhitzung führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (920,'volkswagen-caddy-iv','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse, kann auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (921,'volkswagen-caddy-iv','Elektronik (Infotainment/Sensoren)','Vereinzelt können Störungen im Infotainmentsystem oder bei Sensoren (z.B. Parksensoren) auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (922,'volkswagen-sharan-i','Rost','Rostbildung an Radläufen, Schwellern, Heckklappe und Unterboden ist ein häufiges Problem, insbesondere bei älteren Modellen vor dem Facelift.','1995-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (923,'volkswagen-sharan-i','Vorderachse','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stabilisatorbuchsen führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','1995-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (924,'volkswagen-sharan-i','Klimaanlage','Defekte Kompressoren, undichte Leitungen oder Probleme mit der Gebläseregelung sind häufig.','1995-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (925,'volkswagen-sharan-i','Elektronik','Probleme mit der Zentralverriegelung, Fensterhebern, Kombiinstrument (Pixelfehler) und der Elektrik der Heckklappe.','1995-2010','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (926,'volkswagen-sharan-i','Dieselmotoren (TDI)','Bei den 1.9 TDI-Motoren können Probleme mit dem Turbolader, dem Luftmassenmesser und den Einspritzdüsen auftreten. Auch die Zahnriemenwechselintervalle müssen unbedingt eingehalten werden.','1995-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (927,'volkswagen-sharan-i','Automatikgetriebe (Tiptronic)','Das 4-Gang-Automatikgetriebe (insbesondere in Verbindung mit den stärkeren Motoren) gilt als anfällig für Verschleiß und Defekte, oft durch mangelnde Wartung (Ölwechsel).','1995-2000 (vor Facelift)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (928,'volkswagen-sharan-ii','DSG-Getriebe (DQ250/DQ500)','Probleme mit Mechatronik, Rupfen beim Anfahren, Schaltrucke, insbesondere bei den frühen Baujahren und hohen Laufleistungen. Ölwechselintervalle sind entscheidend.','2010-2015 (insbesondere frühe Baujahre)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (929,'volkswagen-sharan-ii','Elektronik','Ausfälle von Infotainmentsystemen, Problemen mit der elektrischen Schiebetür (falls vorhanden), Fehlermeldungen von Sensoren.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (930,'volkswagen-sharan-ii','Dieselmotoren (TDI)','Probleme mit AGR-Ventil, Injektoren und Partikelfilter, insbesondere bei Kurzstreckenfahrzeugen. Bei den EA189-Motoren gab es den Abgasskandal.','2010-2015 (EA189), alle Baujahre (AGR/DPF)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (931,'volkswagen-sharan-ii','Fahrwerk','Verschleiß an Querlenkerlagern und Spurstangenköpfen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','Alle Baujahre (insbesondere bei hohen Laufleistungen)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (932,'volkswagen-id.3-1.-generation','Software','Anfängliche Softwareprobleme, darunter Bugs im Infotainment-System, Probleme mit der Konnektivität und der Stabilität der Systeme. Viele dieser Probleme wurden durch Over-the-Air-Updates behoben.','2020-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (933,'volkswagen-id.3-1.-generation','12V-Batterie','Berichte über frühzeitige Entladung oder Defekte der 12V-Starterbatterie, die zu Startproblemen oder Ausfällen von Systemen führen können.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (934,'volkswagen-id.3-1.-generation','Ladeelektronik','Vereinzelt gab es Berichte über Probleme beim Laden, insbesondere an öffentlichen Ladesäulen, oder Fehlermeldungen bezüglich der Ladeelektronik.','2020-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (935,'volkswagen-id.4-1.-generation','Software/Infotainment','Anfängliche Softwareprobleme mit Abstürzen, langsamer Bedienung und Fehlfunktionen des Infotainmentsystems sowie der Online-Dienste. Updates haben die Situation verbessert, aber nicht vollständig behoben.','2020-2022 (teilweise auch spätere Modelle vor größeren Software-Updates)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (936,'volkswagen-id.4-1.-generation','12V-Batterie','Berichte über entladene 12V-Batterien, die zu Startproblemen oder Ausfall von Systemen führen können, insbesondere bei längeren Standzeiten oder Kälte.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (937,'volkswagen-id.4-1.-generation','Ladeleistung','Die beworbene maximale Ladeleistung konnte in der Praxis oft nicht erreicht werden oder wurde nur für kurze Zeit gehalten, was zu längeren Ladezeiten führte. Dies wurde mit Software-Updates und neueren Modelljahren verbessert.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (938,'volkswagen-id.5-1.-generation','Software','Anfängliche Softwareprobleme, die zu Ausfällen von Infotainment-Systemen, Navigationsfehlern oder Problemen mit Assistenzsystemen führen können. Updates werden Over-the-Air oder in der Werkstatt eingespielt.','2022-2023','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (939,'volkswagen-id.5-1.-generation','12V-Batterie','Vereinzelt Berichte über entladene 12V-Batterien, die das Starten des Fahrzeugs verhindern, obwohl die Hochvoltbatterie geladen ist.','2022-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (940,'opel-corsa-a','Rost','Der Corsa A ist stark rostanfällig, insbesondere an Radläufen, Schwellern, Türen, Heckklappe, Tankstutzenbereich und den Federbeinaufnahmen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (941,'opel-corsa-a','Bremsen','Verschleiß an Bremsleitungen und -schläuchen, sowie festrostende Bremssättel hinten sind häufig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (942,'opel-corsa-a','Motor','Ölverlust an Motor und Getriebe, insbesondere an der Ventildeckeldichtung und den Kurbelwellensimmerringen. Bei den Vergasermotoren können Probleme mit dem Vergaser auftreten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (943,'opel-corsa-a','Auspuffanlage','Die Auspuffanlage ist aufgrund der Materialqualität und der exponierten Lage sehr rostanfällig.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (944,'opel-corsa-a','Fahrwerk','Verschleiß an Querlenkerlagern und Spurstangenköpfen ist altersbedingt häufig.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (945,'opel-corsa-b','Rost','Besonders an den hinteren Radläufen, Schwellern, Türeinstiegen und der Heckklappe. Auch der Tankstutzen ist oft betroffen.','Alle Baujahre, insbesondere ältere Modelle und Fahrzeuge ohne ausreichende Pflege.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (946,'opel-corsa-b','Bremsanlage','Verschleiß der Bremsscheiben und -beläge, festgerostete Bremssättel hinten, undichte Bremsleitungen.','Alle Baujahre, alters- und laufleistungsbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (947,'opel-corsa-b','Auspuffanlage','Durchrostung des Endschalldämpfers und der Rohre.','Alle Baujahre, altersbedingt.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (948,'opel-corsa-b','Lenkung','Verschleiß der Spurstangenköpfe und Traggelenke, was zu Spiel in der Lenkung führen kann.','Alle Baujahre, laufleistungsbedingt.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (949,'opel-corsa-b','Elektrik','Probleme mit der Zentralverriegelung, Fensterhebern, Beleuchtung und dem Anlasser.','Alle Baujahre, altersbedingt.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (950,'opel-corsa-b','Motor (speziell 1.0 12V und 1.2 16V)','Probleme mit der Steuerkette (Längung, Rasseln), erhöhtem Ölverbrauch und defekten Zündmodulen.','Ab 1997 (Einführung der Ecotec-Motoren).','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (957,'opel-corsa-c','Lenkung','Probleme mit der elektrischen Servolenkung (EPS), die zu Ausfällen oder schwergängiger Lenkung führen können. Oft ist der Lenkwinkelsensor oder das Steuergerät betroffen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (958,'opel-corsa-c','Bremsen','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere an der Vorderachse. Auch festrostende Bremssättel sind ein bekanntes Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (959,'opel-corsa-c','Auspuffanlage','Rostanfälligkeit der Auspuffanlage, insbesondere des Endschalldämpfers, was zu vorzeitigem Austausch führen kann.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (960,'opel-corsa-c','Zündmodul/Zündspule','Bei Benzinmotoren können Defekte am Zündmodul oder den Zündspulen auftreten, was zu Motorruckeln, Leistungsverlust oder dem Aufleuchten der Motorkontrollleuchte führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (961,'opel-corsa-c','Kurbelwellensensor','Ausfälle des Kurbelwellensensors können zu Startproblemen oder plötzlichem Absterben des Motors während der Fahrt führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (962,'opel-corsa-c','Rost','Rostbildung an den hinteren Radläufen, am Unterboden und an den Türunterkanten ist bei älteren Exemplaren nicht unüblich.','Alle Baujahre, verstärkt bei älteren Fahrzeugen','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (963,'opel-corsa-d','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder einem schwergängigen Lenkgefühl führen können. Oft ist der Lenkwinkelsensor oder das Steuergerät betroffen.','2006-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (964,'opel-corsa-d','Getriebe (Easytronic)','Das automatisierte Schaltgetriebe Easytronic neigt zu Defekten, insbesondere am Aktuator oder der Kupplung, was zu Schaltproblemen oder dem Ausfall des Getriebes führen kann.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (965,'opel-corsa-d','Klimaanlage','Undichtigkeiten im Klimasystem, insbesondere am Kondensator, führen zu Kältemittelverlust und mangelnder Kühlleistung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (966,'opel-corsa-d','Bremsen','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse, sowie festrostende Bremssättel.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (967,'opel-corsa-d','Fahrwerk','Verschleiß an den Querlenkerlagern und Spurstangenköpfen, was sich durch Poltergeräusche bemerkbar macht. Auch gebrochene Fahrwerksfedern sind keine Seltenheit.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (968,'opel-corsa-d','Zündmodul/Zündspulen','Bei Benzinmotoren können Defekte am Zündmodul oder den einzelnen Zündspulen zu Motorruckeln, Leistungsverlust oder dem Aufleuchten der Motorkontrollleuchte führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (969,'opel-corsa-e','Fahrwerk (Achsen, Lenkung)','Bei der Hauptuntersuchung fallen überdurchschnittlich oft Mängel an Achsaufhängungen, Lenkgelenken und Spurstangenköpfen auf. Auch ausgeschlagene Querlenkerlager sind keine Seltenheit.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (970,'opel-corsa-e','Bremsanlage','Erhöhter Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse. Auch die Funktion der Feststellbremse kann beeinträchtigt sein.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (971,'opel-corsa-e','Beleuchtung','Mängel an der Beleuchtungsanlage, insbesondere defekte Leuchtmittel oder fehlerhafte Einstellung der Scheinwerfer, werden häufiger beanstandet.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (972,'opel-corsa-e','Motor (1.0 Ecotec Turbo)','Bei den 1.0 Ecotec Turbo Motoren kann es zu Problemen mit der Steuerkette oder dem Turbolader kommen, was sich durch ungewöhnliche Geräusche oder Leistungsverlust äußert.','2014-2017','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (973,'opel-corsa-e','Getriebe (Easytronic 3.0)','Das automatisierte Schaltgetriebe Easytronic 3.0 kann Ruckeln beim Anfahren oder Schalten zeigen. Auch Ausfälle der Getriebesteuerung sind bekannt.','Alle Baujahre mit Easytronic','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (974,'opel-corsa-f','Infotainmentsystem','Berichte über Softwareprobleme, Abstürze oder langsame Reaktionen des Infotainmentsystems, insbesondere bei frühen Baujahren.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (975,'opel-corsa-f','1.2 PureTech Benzinmotoren (Zahnriemen)','Bei den 1.2 PureTech Motoren kann es zu vorzeitigem Verschleiß des im Öl laufenden Zahnriemens kommen, was zu Problemen mit der Ölpumpe und im schlimmsten Fall zu Motorschäden führen kann. Dies ist ein bekanntes Problem der PSA-Motorenfamilie.','2019-2022','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (976,'opel-corsa-f','Fahrwerk/Geräusche','Einige Nutzer berichten von Poltergeräuschen oder Knistern aus dem Fahrwerksbereich, insbesondere bei unebenen Straßen.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (977,'opel-astra-f','Rost','Starker Rostbefall an Radläufen hinten, Schwellern, Türen, Tankdeckelbereich, Federbeinaufnahmen und am Unterboden. Besonders betroffen sind Modelle vor dem Facelift.','1991-1998','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (978,'opel-astra-f','Bremsleitungen','Korrosion der Bremsleitungen, insbesondere im Bereich des Unterbodens und der Hinterachse, kann zu Undichtigkeiten führen.','1991-1998','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (979,'opel-astra-f','Auspuffanlage','Die Auspuffanlage ist anfällig für Rost und Undichtigkeiten, insbesondere Endschalldämpfer und Verbindungsrohre.','1991-1998','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (980,'opel-astra-f','Zylinderkopfdichtung','Bei den 1.4- und 1.6-Liter-Motoren (C14NZ, C16NZ, X14XE, X16XEL) kann die Zylinderkopfdichtung undicht werden, was zu Ölverlust oder Kühlwasserverlust führt.','1991-1998','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (981,'opel-astra-f','Ölverlust Motor','Neben der Zylinderkopfdichtung können auch Ventildeckeldichtung und Kurbelwellensimmerringe undicht werden.','1991-1998','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (982,'opel-astra-f','Getriebe','Bei hohen Laufleistungen können die Schaltgetriebe (insbesondere F13/F15/F17) Geräusche machen oder schwergängig werden. Auch Ölverlust am Getriebe ist möglich.','1991-1998','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (983,'opel-astra-f','Elektronik','Probleme mit der Motorelektronik (z.B. Leerlaufsteller, Drosselklappenpoti, Lambdasonde) können zu unrundem Motorlauf oder Leistungsverlust führen. Auch defekte Wegfahrsperren sind bekannt.','1991-1998','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (984,'opel-astra-f','Heizungsventil','Das Heizungsventil kann undicht werden, was zu Kühlwasserverlust und feuchten Fußräumen führt.','1991-1998','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (985,'opel-astra-g','Rost','Besonders an den hinteren Radläufen, Schwellern, Türen und der Heckklappe (unter der Zierleiste) kann Rost auftreten. Auch der Tankstutzen ist betroffen.','Alle Baujahre, besonders frühe Modelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (986,'opel-astra-g','Hinterachse','Die Gummilager der Hinterachse verschleißen relativ schnell, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (987,'opel-astra-g','Elektronik','Probleme mit dem Lenkstockschalter (Blinker, Scheibenwischer), dem Display des Bordcomputers (Pixelfehler) und der Wegfahrsperre können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (988,'opel-astra-g','Zündmodul/Zündspule','Bei Benzinmotoren, insbesondere den Ecotec-Motoren, sind Defekte am Zündmodul oder der Zündspule häufig, was zu Motorruckeln oder Aussetzern führt.','Alle Baujahre mit Benzinmotoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (989,'opel-astra-g','Ölverlust/Ölverbrauch','Einige Benzinmotoren neigen zu erhöhtem Ölverbrauch oder Ölverlust an Dichtungen (z.B. Ventildeckeldichtung).','Alle Baujahre mit Benzinmotoren','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (990,'opel-astra-g','Abgasanlage','Der Endschalldämpfer und die Verbindungsrohre sind anfällig für Rost und Undichtigkeiten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (991,'opel-astra-h','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder einem schwergängigen Lenkgefühl führen können. Oft ist der Lenkwinkelsensor oder die Lenksäule selbst betroffen.','2004-2007','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (992,'opel-astra-h','Getriebe','Bei Schaltgetrieben können Lagerschäden auftreten, die sich durch Geräusche oder schwergängige Schaltvorgänge bemerkbar machen. Insbesondere das M32-Getriebe ist anfällig.','2004-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (993,'opel-astra-h','Elektronik','Ausfälle des CIM-Moduls (Column Integration Module) können zu Problemen mit der Lenkradfernbedienung, dem Blinker oder der Hupe führen. Auch defekte Lichtmaschinen sind keine Seltenheit.','2004-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (994,'opel-astra-h','Fahrwerk','Verschleiß an den Querlenkerbuchsen und Koppelstangen der Vorderachse, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt.','2004-2010','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (995,'opel-astra-h','Rost','Rostbildung kann an den hinteren Radläufen, der Heckklappe und den Türunterkanten auftreten, insbesondere bei älteren Modellen oder mangelnder Pflege.','2004-2007','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (996,'opel-astra-j','Fahrwerk (Hinterachse)','Bei frühen Modellen kann es zu Poltergeräuschen von der Hinterachse kommen, oft verursacht durch verschlissene Gummilager oder defekte Stoßdämpfer.','2009-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (997,'opel-astra-j','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse. Auch Festsitzen der Bremssättel ist bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (998,'opel-astra-j','Elektronik','Fehlermeldungen im Bordcomputer, Ausfall von Infotainment-Systemen oder Problemen mit der Zentralverriegelung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (999,'opel-astra-j','Turbolader (1.4 Turbo)','Bei den 1.4 Turbo-Motoren kann es zu Problemen mit dem Turbolader kommen, die sich durch Leistungsverlust oder ungewöhnliche Geräusche äußern.','2009-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1000,'opel-astra-j','Wasserpumpe','Undichtigkeiten oder Ausfall der Wasserpumpe, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre, insbesondere Dieselmotoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1001,'opel-astra-k','Wasserpumpe','Undichtigkeiten an der Wasserpumpe können zu Kühlmittelverlust führen. Betrifft vor allem die 1.4 Turbo-Motoren.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1002,'opel-astra-k','Infotainmentsystem (IntelliLink)','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktion des Systems. Updates können Abhilfe schaffen.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1003,'opel-astra-k','Klimaanlage','Ausfälle der Klimaanlage, oft durch undichte Leitungen oder defekte Kompressoren verursacht.','2016-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1004,'opel-astra-k','Bremsen','Erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit Automatikgetriebe oder sportlicher Fahrweise.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1005,'opel-insignia-b','Infotainmentsystem (Navi 900 IntelliLink)','Gelegentliche Softwareprobleme, Abstürze, langsame Reaktion oder Ausfälle des Touchscreens. Updates können Besserung bringen.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1006,'opel-insignia-b','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit Automatikgetriebe und höherer Motorleistung. Quietschen der Bremsen kann ebenfalls auftreten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1007,'opel-insignia-b','Dieselmotoren (1.6 CDTI, 2.0 CDTI)','Probleme mit der Abgasreinigung (AdBlue-System, NOx-Sensoren) können zu Fehlermeldungen und Notlauf führen. Bei einigen 2.0 CDTI Motoren gab es Berichte über erhöhten Ölverbrauch oder Probleme mit der Steuerkette (selten, aber möglich).','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1008,'opel-insignia-b','Getriebe (Automatik)','Vereinzelt Berichte über ruckeliges Schaltverhalten oder verzögerte Gangwechsel, insbesondere bei den 8-Gang-Automatikgetrieben. Software-Updates können Abhilfe schaffen.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1009,'opel-insignia-b','Fahrwerk (Vorderachse)','Geräusche von der Vorderachse (Poltern, Knarzen) können auf verschlissene Stabilisatorstreben oder Querlenkerbuchsen hindeuten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1010,'opel-mokka-a','Fahrwerk/Achsen','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern, insbesondere an der Vorderachse. Kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1011,'opel-mokka-a','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere bei Fahrzeugen mit Automatikgetriebe oder häufigem Stadtverkehr. Festgehende Bremssättel sind ebenfalls bekannt.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1012,'opel-mokka-a','Elektronik','Probleme mit dem Infotainmentsystem (Ausfälle, Einfrieren), defekte Parksensoren oder Ausfälle der Klimaanlage/Heizung.','2012-2014','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1013,'opel-mokka-a','Motor (1.4 Turbo)','Bekannt für defekte Wasserpumpen und gelegentliche Probleme mit dem Turbolader (Ölverlust, Leistungsverlust).','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1014,'opel-mokka-a','Motor (1.7 CDTI Diesel)','Probleme mit dem AGR-Ventil (Abgasrückführung), was zu Leistungsverlust und Motorkontrollleuchte führen kann. Auch Injektoren können betroffen sein.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1015,'opel-grandland-a','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse. Kann zu frühzeitigem Austausch führen.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1016,'opel-grandland-a','AdBlue-System (Diesel)','Probleme mit dem AdBlue-Tank oder der Einspritzung, die zu Fehlermeldungen und im schlimmsten Fall zu einem Notlaufprogramm führen können.','2017-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1017,'opel-grandland-a','Infotainmentsystem','Gelegentliche Software-Probleme wie Abstürze, langsame Reaktion oder Verbindungsprobleme mit Smartphones.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1018,'opel-crossland-a','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit Automatikgetriebe oder häufigem Stadtverkehr.','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1019,'opel-crossland-a','Fahrwerk (Vorderachse)','Vereinzelt Berichte über ausgeschlagene Spurstangenköpfe oder Traggelenke, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1020,'opel-crossland-a','Infotainmentsystem','Gelegentliche Softwareprobleme, wie Abstürze des Systems oder Schwierigkeiten bei der Smartphone-Konnektivität (Apple CarPlay/Android Auto). Meist durch Software-Updates behebbar.','2017-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1021,'opel-adam-a','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder ungewöhnlichen Geräuschen führen können. Oft ist der Lenkwinkelsensor oder das Lenkgetriebe betroffen.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1022,'opel-adam-a','Bremsen','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Vorderachse. Auch Rost an den Bremsscheiben bei geringer Nutzung ist ein Thema.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1023,'opel-adam-a','Fahrwerk','Verschleiß an den Querlenkern und Stabilisatorlagern, was sich durch Poltergeräusche bemerkbar machen kann. Auch Federbrüche sind vereinzelt aufgetreten.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1024,'opel-adam-a','Motor (1.0 Ecotec Turbo)','Vereinzelt Berichte über erhöhten Ölverbrauch und Probleme mit der Steuerkette oder dem Turbolader bei den Dreizylinder-Motoren.','2014-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1025,'opel-adam-a','Getriebe (Easytronic 3.0)','Das automatisierte Schaltgetriebe kann ruckelig schalten oder zu Ausfällen neigen. Software-Updates können helfen, aber auch mechanische Probleme sind möglich.','Alle mit Easytronic','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1026,'opel-karl-a','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1027,'opel-karl-a','Fahrwerk','Vereinzelt ausgeschlagene Spurstangenköpfe oder Traggelenke, was zu Poltergeräuschen führen kann.','2015-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1028,'opel-karl-a','Elektronik','Probleme mit dem Infotainmentsystem (IntelliLink) oder der Zentralverriegelung sind selten, aber möglich.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1034,'opel-zafira-a','Lenkung','Verschleiß an Spurstangenköpfen und Traggelenken, was zu Spiel und Geräuschen führen kann. Auch die Servopumpe kann undicht werden oder ausfallen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1035,'opel-zafira-a','Bremsen','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder häufigen Kurzstrecken.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1036,'opel-zafira-a','Abgasanlage','Rostbildung am Endschalldämpfer und den Rohren, was zu Undichtigkeiten führen kann.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1037,'opel-zafira-a','Elektronik','Probleme mit dem Steuergerät der Wegfahrsperre, dem Kombiinstrument (Pixelfehler) oder der Zentralverriegelung.','Frühe Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1038,'opel-zafira-a','Rost','Rost an den hinteren Radläufen, Schwellern und der Heckklappe, insbesondere bei älteren Modellen.','Alle Baujahre, verstärkt bei älteren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1039,'opel-zafira-b','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder schwergängiger Lenkung führen können. Oft ist der Lenkwinkelsensor oder die Lenksäule selbst betroffen.','2005-2008','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1040,'opel-zafira-b','Getriebe (Easytronic)','Das automatisierte Schaltgetriebe Easytronic neigt zu Defekten an der Kupplung oder der Steuerung, was zu Ruckeln, Schaltproblemen oder dem Ausfall des Getriebes führen kann.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1041,'opel-zafira-b','Klimaanlage','Undichtigkeiten im Klimasystem, insbesondere am Kondensator, führen zu Kältemittelverlust und Funktionsausfall der Klimaanlage.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1042,'opel-zafira-b','Lichtmaschine','Vorzeitiger Verschleiß der Lichtmaschine, was zu Problemen mit der Batterieladung und dem Ausfall elektrischer Systeme führen kann.','2005-2009','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1043,'opel-zafira-b','Zweimassenschwungrad (Diesel)','Bei Dieselmotoren kann das Zweimassenschwungrad vorzeitig verschleißen, was sich durch Vibrationen, Geräusche beim Starten/Abstellen und Schaltprobleme äußert.','Alle Diesel-Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1044,'opel-zafira-b','Rost','Rostbildung kann an den Türkanten, der Heckklappe und im Bereich der Radläufe auftreten, insbesondere bei älteren Modellen.','Ältere Baujahre, insbesondere vor Facelift','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1051,'opel-zafira-c','AGR-Ventil','Besonders bei Dieselfahrzeugen kann das AGR-Ventil verrußen und zu Leistungsverlust oder Notlauf führen. Dies ist ein häufiges Problem bei Kurzstreckenfahrzeugen.','Alle Baujahre, insbesondere bei Dieselfahrzeugen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1052,'opel-zafira-c','Turbolader','Bei einigen Dieselmotoren, insbesondere dem 2.0 CDTI, können Turboladerschäden auftreten, oft durch mangelnde Ölversorgung oder Überhitzung.','2011-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1053,'opel-zafira-c','Wasserpumpe','Undichtigkeiten oder Lagerschäden an der Wasserpumpe können zu Kühlmittelverlust und Überhitzung führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1054,'opel-zafira-c','FlexRide-Fahrwerk','Bei Fahrzeugen mit adaptivem FlexRide-Fahrwerk können Defekte an den Dämpfern oder Sensoren auftreten, was zu Fehlermeldungen oder beeinträchtigtem Fahrverhalten führt.','Alle Baujahre mit FlexRide','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1055,'opel-zafira-c','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse, ist bekannt. Auch festrostende Bremssättel können vorkommen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1056,'opel-zafira-c','Elektronik','Vereinzelt können Störungen der Bordelektronik, des Infotainmentsystems oder der Parksensoren auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1057,'opel-zafira-life-1-generation','AdBlue-System','Probleme mit dem AdBlue-Tank oder der Einspritzung können zu Fehlermeldungen und im schlimmsten Fall zu einem Notlaufprogramm führen. Dies betrifft insbesondere die Dieselmotoren.','Ab 2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1058,'opel-zafira-life-1-generation','Elektronik','Vereinzelt Berichte über kleinere Elektronikprobleme, wie z.B. Ausfälle des Infotainmentsystems oder Fehlfunktionen von Sensoren.','Ab 2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1059,'opel-zafira-life-1-generation','Bremsen','Bei einigen Fahrzeugen wurde ein erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse, festgestellt.','Ab 2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1060,'opel-meriva-a','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder schwergängiger Lenkung führen können. Oft ist der Lenkwinkelsensor oder die Lenksäule selbst betroffen.','2003-2007','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1061,'opel-meriva-a','Getriebe (Easytronic)','Das automatisierte Schaltgetriebe Easytronic neigt zu Defekten, insbesondere am Aktuator oder der Kupplung, was zu Schaltproblemen oder dem Ausfall des Getriebes führen kann.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1062,'opel-meriva-a','Bremsen','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere an der Hinterachse. Auch festrostende Bremssättel sind ein bekanntes Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1063,'opel-meriva-a','Rost','Rostbildung kann an den Türkanten, der Heckklappe und den Radläufen auftreten, insbesondere bei älteren Modellen.','2003-2006','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1064,'opel-meriva-a','Dieselmotoren (1.7 CDTI)','Probleme mit dem AGR-Ventil, dem Turbolader und den Injektoren, die zu Leistungsverlust und erhöhtem Verbrauch führen können.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1065,'opel-meriva-b','Lenkung','Probleme mit der elektrischen Servolenkung, die zu Ausfällen oder Schwergängigkeit führen kann. Oft ist der Lenkwinkelsensor oder die Lenksäule selbst betroffen.','2010-2013','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1066,'opel-meriva-b','Getriebe (Easytronic)','Das automatisierte Schaltgetriebe Easytronic kann zu Ruckeln, Schaltproblemen oder komplettem Ausfall neigen. Defekte Aktuatoren oder Steuergeräte sind häufig die Ursache.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1067,'opel-meriva-b','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse. Auch festrostende Bremssättel sind ein bekanntes Problem.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1068,'opel-meriva-b','Fahrwerk','Verschleiß an den Querlenkerlagern und Spurstangenköpfen, was sich durch Poltern oder unpräzises Fahrverhalten äußern kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1069,'opel-meriva-b','Elektronik','Vereinzelt Probleme mit der Fahrzeugelektronik, z.B. Ausfälle des Infotainmentsystems, der Klimaanlage oder der Fensterheber.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1070,'ford-fiesta-mk1','Karosserie','Starke Anfälligkeit für Rost, insbesondere an Radläufen, Schwellern, Türeinstiegen, Federbeinaufnahmen, Tankeinfüllstutzen und im Bereich der Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1071,'ford-fiesta-mk1','Bremsanlage','Verschleiß der Bremsleitungen und Bremsschläuche, festrostende Bremssättel hinten und Korrosion an den Bremstrommeln.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1072,'ford-fiesta-mk1','Elektrik','Probleme mit der Verkabelung, insbesondere Korrosion an Steckverbindungen, was zu Ausfällen von Beleuchtung, Scheibenwischern oder Instrumenten führen kann.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1073,'ford-fiesta-mk1','Motor','Ölverlust an Motor und Getriebe, insbesondere an den Simmerringen. Bei den älteren Kent-Motoren können auch Probleme mit der Zylinderkopfdichtung auftreten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1074,'ford-fiesta-mk2','Rost','An Radläufen, Schwellern, Türen, Heckklappe und Fahrwerksteilen.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1075,'ford-fiesta-mk2','Elektrik','Probleme mit der Verkabelung, Lichtern und Schaltern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1076,'ford-fiesta-mk2','Fahrwerk','Verschleiß an Stoßdämpfern, Buchsen und Gelenken.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1077,'ford-fiesta-mk3','Rost','Der Fiesta Mk3 ist stark rostanfällig, insbesondere an den Radläufen, Schwellern, Türunterkanten, der Heckklappe und den Federbeinaufnahmen.','Alle Baujahre (1989-1996)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1078,'ford-fiesta-mk3','Bremsanlage','Verschleiß an Bremsscheiben und -belägen ist häufig. Auch festgerostete Bremssättel, insbesondere hinten, sind ein Problem.','Alle Baujahre (1989-1996)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1079,'ford-fiesta-mk3','Zündanlage','Probleme mit Zündkabeln, Zündkerzen und dem Zündverteiler können zu unrundem Motorlauf oder Startschwierigkeiten führen.','Alle Baujahre (1989-1996)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1080,'ford-fiesta-mk3','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe sind altersbedingt häufig. Auch defekte Thermostate kommen vor.','Alle Baujahre (1989-1996)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1081,'ford-fiesta-mk3','Auspuffanlage','Die Auspuffanlage ist aufgrund von Korrosion oft verschlissen und muss ersetzt werden.','Alle Baujahre (1989-1996)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1082,'ford-fiesta-mk3','Fahrwerk','Verschleiß an Querlenkerbuchsen, Spurstangenköpfen und Stoßdämpfern ist altersbedingt üblich und kann zu Poltergeräuschen und schlechtem Fahrverhalten führen.','Alle Baujahre (1989-1996)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1083,'ford-fiesta-mk4','Rost','Rostbildung an Radläufen, Schwellern, Türen und der Heckklappe ist ein häufiges Problem, insbesondere bei älteren Modellen und Fahrzeugen, die viel Salz ausgesetzt waren.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1084,'ford-fiesta-mk4','Bremsleitungen','Korrosion an den Bremsleitungen, insbesondere im Bereich des Unterbodens, kann zu Undichtigkeiten und Ausfall der Bremsanlage führen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1085,'ford-fiesta-mk4','Zündanlage','Probleme mit Zündkabeln, Zündspule oder Zündkerzen können zu unrundem Motorlauf, Leistungsverlust und erhöhtem Verbrauch führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1086,'ford-fiesta-mk4','Auspuffanlage','Die Auspuffanlage ist anfällig für Rost und kann undicht werden, was zu erhöhten Emissionen und Geräuschentwicklung führt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1087,'ford-fiesta-mk4','Radlager','Verschleiß der Radlager, erkennbar an einem mahlenden oder brummenden Geräusch während der Fahrt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1088,'ford-fiesta-mk5','Rost','Rostbildung an den Türkanten, Heckklappe und Radläufen, insbesondere bei älteren Modellen oder Fahrzeugen, die viel im Winter gefahren wurden.','Alle Baujahre, verstärkt vor Facelift','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1089,'ford-fiesta-mk5','Fahrwerk','Verschleiß an den Querlenkerlagern und Spurstangenköpfen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann. Auch Federbrüche sind bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1090,'ford-fiesta-mk5','Bremsen','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Vorderachse. Festgehende Bremssättel sind ebenfalls ein Thema.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1091,'ford-fiesta-mk5','Elektronik','Probleme mit der Zentralverriegelung, Fensterhebern und gelegentlich der Wegfahrsperre. Auch Ausfälle des Kombiinstruments sind möglich.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1092,'ford-fiesta-mk5','Klimaanlage','Undichtigkeiten im Klimasystem oder Defekte am Klimakompressor, was zu einem Ausfall der Kühlfunktion führt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1093,'ford-fiesta-mk6','Rost','Rostbildung an den Türkanten, Heckklappe und im Bereich der Radläufe, insbesondere bei älteren Modellen und mangelnder Pflege.','Alle Baujahre, verstärkt bei frühen Modellen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1094,'ford-fiesta-mk6','Fahrwerk','Verschleiß an den Querlenkerlagern und Stabilisatorstreben, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann. Auch Federbrüche sind bekannt.','Alle Baujahre, verstärkt bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1095,'ford-fiesta-mk6','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse bei Modellen mit Trommelbremsen, die zum Festrosten neigen können.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1096,'ford-fiesta-mk6','Elektronik','Probleme mit der Zentralverriegelung, Fensterhebern und gelegentlich mit der Wegfahrsperre.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1097,'ford-fiesta-mk6','Klimaanlage','Undichtigkeiten im Klimasystem, die zu einem Verlust des Kältemittels führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1098,'ford-fiesta-mk7','Kupplung','Bei Modellen mit dem 1.0 EcoBoost Motor kann es zu vorzeitigem Verschleiß der Kupplung kommen, insbesondere bei häufigem Stadtverkehr oder sportlicher Fahrweise. Auch das Zweimassenschwungrad kann betroffen sein.','Ab 2012 (1.0 EcoBoost)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1099,'ford-fiesta-mk7','Getriebe (Powershift)','Das optionale Powershift-Doppelkupplungsgetriebe kann Ruckeln, Schaltprobleme oder sogar einen kompletten Ausfall aufweisen. Oft sind die Kupplungspakete oder die Mechatronik betroffen.','Alle Baujahre mit Powershift','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1100,'ford-fiesta-mk7','Wasserpumpe','Undichtigkeiten an der Wasserpumpe sind keine Seltenheit, was zu Kühlmittelverlust und potenzieller Überhitzung führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1101,'ford-fiesta-mk7','Fahrwerk (Vorderachse)','Verschleiß an den Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, insbesondere bei höherer Laufleistung','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1102,'ford-fiesta-mk7','Rost','Rost kann an den Türkanten, der Heckklappe und im Bereich der Radläufe auftreten, insbesondere bei älteren Modellen oder mangelnder Pflege.','Alle Baujahre, verstärkt bei älteren Fahrzeugen','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1103,'ford-focus-mk1','Rost','Korrosion an Radläufen, Schwellern, Türen (besonders Unterkanten) und Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1104,'ford-focus-mk1','Auspuffanlage','Vorzeitiger Verschleiß und Korrosion, insbesondere am Endschalldämpfer.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1105,'ford-focus-mk1','Kupplung','Verschleißerscheinungen und Defekte, besonders bei häufigem Stadtverkehr.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1106,'ford-focus-mk1','Elektrik','Probleme mit Fensterhebern, Zentralverriegelung und Beleuchtung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1107,'ford-focus-mk2','Rost','Rost kann an den Türkanten, am Unterboden, an den Radläufen und unter den Dichtungen auftreten, insbesondere bei älteren Modellen oder Fahrzeugen, die viel Salz ausgesetzt waren.','Alle Baujahre, verstärkt bei frühen Modellen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1108,'ford-focus-mk2','Hinterachse','Verschleiß an den Gummilagern der Mehrlenker-Hinterachse kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Ein Austausch ist aufwendig.','Alle Baujahre, verstärkt bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1109,'ford-focus-mk2','Klimaanlage','Defekte Klimakompressoren oder undichte Leitungen sind keine Seltenheit, was zu einem Ausfall der Klimafunktion führt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1110,'ford-focus-mk2','Elektronik','Probleme mit der Bordelektronik, wie z.B. Ausfälle des Kombiinstruments, defekte Fensterheber oder Probleme mit der Zentralverriegelung, können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1111,'ford-focus-mk2','Dieselmotoren (1.6 TDCi / 2.0 TDCi)','Probleme mit dem Dieselpartikelfilter (DPF), Injektoren und dem Turbolader sind bekannt, insbesondere bei Kurzstreckenfahrzeugen oder mangelnder Wartung. Der 1.6 TDCi kann auch Probleme mit der Ölschlammbildung haben.','Alle Baujahre mit Dieselmotoren','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1112,'ford-focus-mk2','Servolenkung (elektrisch)','Bei Modellen mit elektrischer Servolenkung (EPAS) kann es zu Ausfällen oder einem schwergängigen Lenkgefühl kommen, oft bedingt durch defekte Sensoren oder die Steuereinheit.','Alle Baujahre mit EPAS','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1113,'ford-focus-mk3','Kupplung und Zweimassenschwungrad','Besonders bei den 1.0 EcoBoost Motoren und Dieselmotoren kann es zu vorzeitigem Verschleiß der Kupplung und des Zweimassenschwungrads kommen, was sich durch Ruckeln, Geräusche oder ein hartes Pedal äußert.','2011-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1114,'ford-focus-mk3','Getriebe (Powershift-Automatik)','Das Doppelkupplungsgetriebe Powershift (insbesondere in den USA) ist anfällig für Ruckeln, Schaltprobleme und vorzeitigen Verschleiß der Kupplungen. In Europa weniger verbreitet, aber auch hier können Probleme auftreten.','2011-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1115,'ford-focus-mk3','1.0 EcoBoost Motor (Kühlmittelverlust)','Frühe Baujahre des 1.0 EcoBoost Motors hatten Probleme mit Kühlmittelverlust, oft durch einen defekten Kühlmittelschlauch oder eine undichte Zylinderkopfdichtung, was zu Überhitzung und Motorschäden führen konnte.','2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1116,'ford-focus-mk3','Rost an der Heckklappe','An der Heckklappe, insbesondere im Bereich der Kennzeichenbeleuchtung oder unter der Chromleiste, kann sich Rost bilden.','2011-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1117,'ford-focus-mk3','Fahrwerk (Poltern/Geräusche)','Verschleiß an den Stabilisatorstreben oder Querlenkerbuchsen kann zu Poltergeräuschen an der Vorderachse führen.','2011-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1118,'ford-focus-mk3','Elektronik (SYNC-System)','Das SYNC-Infotainmentsystem kann in frühen Versionen zu Abstürzen, Bluetooth-Problemen oder langsamer Reaktion neigen.','2011-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1119,'ford-focus-mk4','1,0-Liter EcoBoost Motor (Mild-Hybrid)','Berichte über mögliche Probleme mit dem Zahnriemen im Ölbad, der sich auflösen und die Ölpumpe verstopfen kann, was zu Motorschäden führen kann. Betrifft vor allem frühe Baujahre der Mild-Hybrid-Variante.','2018-2020','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1120,'ford-focus-mk4','Infotainment-System (SYNC 3)','Gelegentliche Software-Probleme, Abstürze oder langsame Reaktionen des Systems. Updates können Abhilfe schaffen.','2018-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1121,'ford-focus-mk4','Kupplung (insbesondere bei 1,5-Liter EcoBoost)','Einige Nutzer berichten von vorzeitigem Verschleiß der Kupplung, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder häufigem Stadtverkehr.','2018-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1122,'ford-kuga-mk1','Antriebswellen','Verschleiß der Antriebswellen, insbesondere bei Modellen mit Allradantrieb, kann zu Geräuschen und Vibrationen führen.','2008-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1123,'ford-kuga-mk1','Kupplung/Zweimassenschwungrad','Bei Dieselmotoren kann es zu vorzeitigem Verschleiß der Kupplung und des Zweimassenschwungrads kommen, was sich durch Ruckeln oder Geräusche bemerkbar macht.','2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1124,'ford-kuga-mk1','Partikelfilter (DPF)','Bei Dieselfahrzeugen kann der Partikelfilter bei überwiegendem Kurzstreckenbetrieb verstopfen, was zu Leistungsverlust und Fehlermeldungen führt.','2008-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1125,'ford-kuga-mk1','Fahrwerk (Querlenker, Stabilisatoren)','Verschleiß an den Gummilagern der Querlenker und den Koppelstangen der Stabilisatoren kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','2008-2012','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1126,'ford-kuga-mk2','Kupplung und Zweimassenschwungrad','Besonders bei Dieselfahrzeugen und Modellen mit Anhängerbetrieb kann es zu vorzeitigem Verschleiß der Kupplung und des Zweimassenschwungrads kommen, was sich durch Ruckeln, Geräusche oder schlechte Kraftübertragung äußert.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1127,'ford-kuga-mk2','PowerShift-Automatikgetriebe','Das Doppelkupplungsgetriebe kann anfällig für Probleme sein, insbesondere bei mangelnder Wartung (Ölwechselintervall beachten). Symptome sind Ruckeln, Schaltverzögerungen oder Notlauf.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1128,'ford-kuga-mk2','Dieselpartikelfilter (DPF)','Bei überwiegendem Kurzstreckenbetrieb kann der DPF verstopfen, was zu Leistungsverlust und erhöhten Emissionen führt. Eine Regeneration ist dann oft nicht mehr möglich.','Alle Diesel-Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1129,'ford-kuga-mk2','Rost an der Heckklappe','Vereinzelt kann es zu Rostbildung an der Unterkante der Heckklappe oder im Bereich der Kennzeichenbeleuchtung kommen.','Frühe Baujahre (2012-2014)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1130,'ford-kuga-mk2','Elektronikprobleme','Gelegentlich treten kleinere Elektronikprobleme auf, z.B. mit dem Infotainmentsystem (SYNC), Sensoren oder der Zentralverriegelung.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1131,'ford-kuga-mk3','12V-Batterie','Bei frühen Modellen, insbesondere Plug-in-Hybriden, kann die 12V-Batterie aufgrund von Softwareproblemen oder unzureichender Ladung entladen werden, was zu Startproblemen führt.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1132,'ford-kuga-mk3','Infotainmentsystem (SYNC 3/4)','Gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen des Systems wurden berichtet. Updates können Abhilfe schaffen.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1133,'ford-kuga-mk3','Antriebswelle (Plug-in-Hybrid)','Bei einigen Plug-in-Hybrid-Modellen kann es zu Problemen mit der Antriebswelle kommen, die Geräusche verursachen oder im schlimmsten Fall zum Ausfall führen können.','2020-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1134,'ford-puma-mk1','Rost','Starker Rostbefall an den hinteren Radläufen, Schwellern, Türunterkanten und am Unterboden ist ein häufiges Problem, insbesondere bei Fahrzeugen, die nicht regelmäßig gepflegt wurden.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1135,'ford-puma-mk1','Hinterachse','Die Hinterachse kann durch Rost stark beeinträchtigt sein, was die Fahrsicherheit gefährden kann. Auch die Lager der Hinterachse verschleißen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1136,'ford-puma-mk1','Bremsleitungen','Rost an den Bremsleitungen, insbesondere im Bereich des Unterbodens, ist ein bekanntes Problem und kann zum Ausfall der Bremsanlage führen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1137,'ford-puma-mk1','Motor (Zetec-SE)','Die Zetec-SE-Motoren sind im Allgemeinen robust, können aber bei mangelnder Wartung oder Überhitzung Probleme mit der Zylinderkopfdichtung oder den Ventilschaftdichtungen bekommen. Auch Ölverlust ist möglich.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1138,'ford-puma-mk1','Getriebe','Das manuelle Getriebe kann bei hohen Laufleistungen oder sportlicher Fahrweise verschlissene Synchronringe aufweisen, was sich durch schwergängige oder kratzende Schaltvorgänge bemerkbar macht.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1139,'ford-puma-mk1','Elektronik','Probleme mit der Zentralverriegelung, Fensterhebern oder dem Kombiinstrument (Pixelfehler) können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1140,'ford-puma-mk2','1.0 EcoBoost Motor (Riemen im Ölbad)','Der Zahnriemen im Ölbad kann sich vorzeitig auflösen und die Ölpumpe verstopfen, was zu Motorschäden führen kann. Betrifft vor allem frühe Baujahre und Fahrzeuge mit unregelmäßiger Wartung oder falschem Öl.','2019-2021 (insbesondere bei mangelnder Wartung)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1141,'ford-puma-mk2','1.0 EcoBoost Mild-Hybrid (MHEV) System','Probleme mit dem 48V-Riemenstartergenerator (BSG) oder der 48V-Batterie können zu Ausfällen des Mild-Hybrid-Systems führen, was den Motorstart oder die elektrische Unterstützung beeinträchtigt.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1142,'ford-puma-mk2','Infotainmentsystem (SYNC 3/4)','Gelegentliche Software-Fehler, Abstürze oder langsame Reaktionen des Touchscreens wurden berichtet. Dies kann durch Updates behoben werden.','Alle Baujahre (Software-abhängig)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1143,'ford-mondeo-mk1','Rost','An Radläufen, Schwellern, Türen und Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1144,'ford-mondeo-mk1','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1145,'ford-mondeo-mk1','Elektronik','Probleme mit Zentralverriegelung, Fensterhebern und Bordelektronik.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1146,'ford-mondeo-mk2','Rost','Besonders an den hinteren Radläufen, Schwellern, Türen und der Heckklappe (Kombi) ist Rost ein häufiges Problem. Auch der Unterboden und die Bremsleitungen können betroffen sein.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1147,'ford-mondeo-mk2','Hinterachse','Die Buchsen der Hinterachse verschleißen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führt. Auch die Federaufnahmen können rosten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1148,'ford-mondeo-mk2','Zündanlage (Benziner)','Probleme mit Zündkabeln, Zündspulen und Zündkerzen können zu unrundem Motorlauf und Leistungsverlust führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1149,'ford-mondeo-mk2','Kupplung','Bei Modellen mit hoher Laufleistung kann die Kupplung verschlissen sein, was sich durch Rupfen oder Rutschen bemerkbar macht.','Alle Baujahre, insbesondere bei hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1150,'ford-mondeo-mk2','Bremsanlage','Festgehende Bremssättel, insbesondere hinten, sind ein bekanntes Problem. Auch die Bremsleitungen sind rostanfällig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1151,'ford-mondeo-mk2','Elektronik','Kleinere elektrische Probleme wie defekte Fensterheber, Zentralverriegelung oder Beleuchtung können auftreten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1152,'ford-mondeo-mk3','Rost','An Radläufen, Schwellern, Türen und Heckklappe.','Alle, besonders vor Facelift','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1153,'ford-mondeo-mk3','Elektrik','Defekte Fensterheber, Zentralverriegelung, Klimaanlage, Bordcomputer.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1154,'ford-mondeo-mk3','Fahrwerk','Verschleiß an Querlenkern, Stoßdämpfern und Spurstangenköpfen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1155,'ford-mondeo-mk3','Dieselpartikelfilter (DPF)','Verstopfung des DPF bei Kurzstreckenfahrzeugen.','Modelle mit DPF','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1156,'ford-mondeo-mk4','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen, was zu einem Ausfall der Kühlleistung führt.','2007-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1157,'ford-mondeo-mk4','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stabilisatorlagern, was sich durch Poltern oder unpräzises Fahrverhalten äußert.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1158,'ford-mondeo-mk4','Elektronik','Fehlfunktionen des Convers+-Displays (Pixelfehler, Ausfälle), Probleme mit der Zentralverriegelung oder dem Keyless-Go-System.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1159,'ford-mondeo-mk4','Rost','Rostbildung an der Heckklappe (insbesondere unter der Chromleiste) und an den Türkanten, seltener auch an den Radläufen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1160,'ford-mondeo-mk4','Dieselmotoren (2.0 TDCi, 2.2 TDCi)','Probleme mit dem Dieselpartikelfilter (DPF) bei Kurzstreckenfahrten, Injektoren und dem Zweimassenschwungrad (ZMS).','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1161,'ford-mustang-first-generation','Karosserie (Rost)','Anfällig für Korrosion an Radläufen, Schwellern, Türen, Kofferraumboden und im Bereich der Windschutzscheibe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1162,'ford-mustang-first-generation','Fahrwerk','Verschleiß an Buchsen und Gelenken, insbesondere bei sportlich gefahrenen Fahrzeugen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1163,'ford-mustang-first-generation','Bremsen','Bei älteren Modellen oft Trommelbremsen, die eine geringere Bremsleistung aufweisen. Nachrüstungen auf Scheibenbremsen sind üblich.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1164,'ford-mustang-third-generation','Rost','Rost kann an den Radläufen, Schwellern, dem Unterboden und den Federbeindomen auftreten, insbesondere bei Fahrzeugen aus Regionen mit Streusalzeinsatz.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1165,'ford-mustang-third-generation','Elektrische Probleme','Probleme mit der Elektrik, wie defekte Fensterheber, Zentralverriegelung oder Armaturenbrettbeleuchtung, sind aufgrund des Alters und der Verkabelung häufig.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1166,'ford-mustang-third-generation','Fahrwerk und Lenkung','Verschlissene Buchsen, Stoßdämpfer und Lenkungskomponenten sind altersbedingt üblich und können zu schwammigem Fahrverhalten führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1167,'ford-mustang-third-generation','5.0L V8 Motor (insbesondere HO-Version)','Obwohl robust, können bei mangelnder Wartung Probleme mit der Zylinderkopfdichtung, Ölverlust und verschlissenen Nockenwellen auftreten. Die Kraftstoffzufuhr und Zündung können ebenfalls altersbedingte Schwächen zeigen.','Alle Baujahre mit 5.0L V8','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1168,'ford-mustang-third-generation','Getriebe (manuell und automatisch)','Verschleiß an Synchronringen bei Schaltgetrieben und altersbedingte Undichtigkeiten oder Schaltprobleme bei Automatikgetrieben sind möglich.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1169,'ford-mustang-fourth-generation','Getriebe (manuell)','Probleme mit dem T-5-Schaltgetriebe (bis 1995) und dem T-45-Schaltgetriebe (1996-2000), insbesondere bei starker Beanspruchung. Synchronringe können verschleißen, was zu schwergängigen Schaltvorgängen führt.','1994-2000','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1170,'ford-mustang-fourth-generation','Kopfdichtungen (V6-Motor)','Der 3.8L V6-Motor ist bekannt für undichte Kopfdichtungen, die zu Kühlmittelverlust und Überhitzung führen können.','1994-2004','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1171,'ford-mustang-fourth-generation','Federbeindome (Rost)','Rostbildung an den Federbeindomen, insbesondere in Regionen mit Streusalzeinsatz. Kann die strukturelle Integrität beeinträchtigen.','Alle Baujahre, besonders ältere Modelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1172,'ford-mustang-fourth-generation','Fensterheber','Defekte Fensterhebermotoren oder -mechanismen sind ein häufiges Problem, insbesondere bei den Cabriomodellen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1173,'ford-mustang-fourth-generation','Lackqualität','Die Lackqualität kann bei einigen Modellen zu Blasenbildung oder Ablösung führen, insbesondere an Kunststoffteilen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1174,'ford-mustang-fifth-generation','Vorderachse/Fahrwerk','Verschleiß an Querlenkerbuchsen und Kugelgelenken kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen, insbesondere bei Modellen vor dem Facelift.','2005-2009','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1175,'ford-mustang-fifth-generation','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen können zu einem Ausfall der Klimaanlage führen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1176,'ford-mustang-fifth-generation','Lackqualität','Insbesondere bei frühen Modellen kann die Lackqualität an einigen Stellen zu wünschen übrig lassen, mit Anfälligkeit für Steinschläge und Kratzer.','2005-2007','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1177,'ford-mustang-fifth-generation','Getriebe (manuell)','Bei einigen Modellen, insbesondere dem GT, können Probleme mit dem Schaltgefühl oder Synchronringen auftreten, was zu hakeligen Schaltvorgängen führt.','2005-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1178,'ford-mustang-sixth-generation','Getriebe (manuell)','Probleme mit dem Schaltgefühl, hakelige Gänge, insbesondere beim MT-82 Getriebe in den frühen Baujahren. Kann zu vorzeitigem Verschleiß führen.','2015-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1179,'ford-mustang-sixth-generation','Differential','Bei einigen Fahrzeugen können Geräusche (Heulen, Klopfen) vom Differential auftreten, insbesondere bei Lastwechseln oder Kurvenfahrten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1180,'ford-mustang-sixth-generation','Lackqualität','Berichte über dünnen Lack und Anfälligkeit für Steinschläge und Kratzer, insbesondere an der Front und den Radläufen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1181,'ford-mustang-sixth-generation','Klimaanlage','Ausfälle der Klimaanlage, oft durch undichte Leitungen oder defekte Kompressoren verursacht.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1182,'ford-mustang-mach-e-first-generation','12V-Batterie','Berichte über Entladung der 12V-Batterie, die zu Startproblemen oder Ausfall von Systemen führen kann, insbesondere bei längeren Standzeiten oder nach Software-Updates.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1183,'ford-mustang-mach-e-first-generation','Software / Infotainmentsystem','Gelegentliche Software-Fehler, Abstürze des Infotainmentsystems (SYNC 4A), Probleme mit der Konnektivität oder unzuverlässige Funktion bestimmter Assistenzsysteme.','2020-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1184,'ford-mustang-mach-e-first-generation','Ladeklappe','Probleme mit dem Öffnungs- und Schließmechanismus der Ladeklappe, die klemmen oder nicht richtig verriegeln kann.','2020-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1185,'ford-ecosport-first-generation','Klimaanlage','Probleme mit der Klimaanlage, insbesondere undichte Leitungen oder defekte Kompressoren, können zu einem Ausfall der Kühlfunktion führen.','2014-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1186,'ford-ecosport-first-generation','Fahrwerk / Achsen','Frühe Modelle zeigten erhöhten Verschleiß an den Querlenkern und Stabilisatorlagern, was zu Poltergeräuschen und einer Beeinträchtigung des Fahrverhaltens führen kann.','2014-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1187,'ford-ecosport-first-generation','Infotainmentsystem','Das SYNC-Infotainmentsystem, insbesondere in den frühen Versionen, kann träge reagieren, abstürzen oder Bluetooth-Verbindungsprobleme aufweisen.','2014-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1188,'ford-ecosport-first-generation','Rostschutz','An einigen Stellen, insbesondere an der Heckklappe (im Bereich des Reserveradhalters, falls vorhanden) und an den Türunterkanten, kann sich frühzeitig Rost bilden.','2014-2016','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1189,'ford-ecosport-second-generation','Fahrwerk','Frühe Modelle (bis ca. 2017) zeigten teilweise eine straffe Federung und eine wenig komfortable Abstimmung, was auf schlechten Straßen zu Poltern führen konnte. Spätere Modelle wurden hier verbessert.','2013-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1190,'ford-ecosport-second-generation','Infotainmentsystem','Das SYNC-System der ersten Facelift-Generation (bis ca. 2019) konnte gelegentlich langsam reagieren oder Softwareprobleme aufweisen.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1191,'ford-ecosport-second-generation','Rostschutz','Bei einigen frühen Importmodellen aus Indien wurde von mangelhaftem Rostschutz berichtet, insbesondere an Unterboden und Achsteilen. Bei europäischen Modellen ist dies seltener ein Problem.','2013-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1192,'ford-galaxy-first-generation','Rost','Rostbildung an Karosserie (Radläufe, Schweller, Heckklappe) und tragenden Teilen ist ein häufiges Problem, insbesondere bei älteren Modellen und vor dem Facelift.','Alle Baujahre, verstärkt vor 2000','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1193,'ford-galaxy-first-generation','Vorderachse','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stabilisatorbuchsen führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1194,'ford-galaxy-first-generation','Bremsanlage','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere an der Hinterachse. Festgehende Bremssättel sind ebenfalls bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1195,'ford-galaxy-first-generation','Elektronik','Probleme mit der Fahrzeugelektronik, z.B. defekte Fensterheber, Zentralverriegelung, Klimaanlage oder Kombiinstrument.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1196,'ford-galaxy-first-generation','Dieselmotoren (TDI)','Bei den 1.9 TDI-Motoren (aus VW-Produktion) können Probleme mit dem Turbolader, den Pumpe-Düse-Einheiten und dem Luftmassenmesser auftreten.','Alle Baujahre mit TDI-Motor','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1197,'ford-galaxy-second-generation','Zweimassenschwungrad (ZMS)','Besonders bei Dieselmotoren kann das Zweimassenschwungrad vorzeitig verschleißen, was sich durch Ruckeln beim Anfahren, Vibrationen und Geräusche äußert.','Alle Baujahre, insbesondere bei hoher Laufleistung','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1198,'ford-galaxy-second-generation','DPF (Dieselpartikelfilter)','Bei überwiegendem Kurzstreckenbetrieb kann der Dieselpartikelfilter verstopfen, was zu Leistungsverlust und Notlauf führt.','Alle Dieselmodelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1199,'ford-galaxy-second-generation','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, insbesondere bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1200,'ford-galaxy-second-generation','Elektronik','Vereinzelt können Probleme mit der Bordelektronik auftreten, z.B. Fehlfunktionen des Navigationssystems, der Klimaanlage oder der elektrischen Fensterheber.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1201,'ford-galaxy-second-generation','Rost','Rostbildung kann an der Heckklappe (insbesondere unter der Chromleiste), an den Türkanten und im Bereich der Radläufe auftreten.','Ältere Baujahre, insbesondere vor dem Facelift','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1202,'skoda-fabia-erste-generation','Vorderachse (Querlenkerlager, Spurstangenköpfe)','Verschleiß der Gummilager und Kugelgelenke, führt zu Poltergeräuschen und unpräzisem Fahrverhalten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1203,'skoda-fabia-erste-generation','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse bei Scheibenbremsen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1204,'skoda-fabia-erste-generation','Zündspulen (Benziner)','Ausfälle der Zündspulen, führt zu Motorruckeln und Leistungsverlust.','Vor allem frühe Baujahre bis ca. 2003','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1205,'skoda-fabia-erste-generation','Fensterheber','Defekte Mechanik oder Elektrik der Fensterheber, insbesondere vorne.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1206,'skoda-fabia-erste-generation','Klimaanlage','Undichtigkeiten im System oder Defekte am Klimakompressor.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1207,'skoda-fabia-erste-generation','Turbolader (TDI-Motoren)','Verschleiß oder Verkokung des Turboladers, insbesondere bei mangelnder Wartung oder Kurzstreckenbetrieb.','Alle Baujahre, besonders bei hohen Laufleistungen','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1208,'skoda-fabia-zweite-generation','Steuerkette (1.2 TSI, 1.4 TSI)','Bei den TSI-Motoren, insbesondere den frühen Baujahren, kann es zu Problemen mit der Steuerkette kommen, die sich längt und zu Motorschäden führen kann. Symptome sind Rasseln beim Kaltstart.','2009-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1209,'skoda-fabia-zweite-generation','Wasserpumpe (TSI-Motoren)','Undichtigkeiten an der Wasserpumpe, oft in Verbindung mit dem Steuerkettenproblem, können zu Kühlmittelverlust und Überhitzung führen.','2009-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1210,'skoda-fabia-zweite-generation','DSG-Getriebe (7-Gang DQ200)','Das 7-Gang-DSG-Getriebe (DQ200) kann Probleme mit der Mechatronik oder den Kupplungen aufweisen, was zu Ruckeln, Schaltverzögerungen oder Ausfällen führen kann.','2008-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1211,'skoda-fabia-zweite-generation','Zündspulen (Benziner)','Defekte Zündspulen können zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1212,'skoda-fabia-zweite-generation','Querlenkerlager','Verschleiß der Querlenkerlager an der Vorderachse kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, besonders bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1213,'skoda-fabia-dritte-generation','Steuerkette (1.2 TSI)','Bei den frühen 1.2 TSI Motoren (bis ca. 2015) kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen und im schlimmsten Fall zu Motorschäden führen können. Spätere Modelle und der 1.0 TSI sind davon nicht betroffen.','2014-2015','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1214,'skoda-fabia-dritte-generation','Wasserpumpe (1.2 TSI)','Undichtigkeiten an der Wasserpumpe, insbesondere bei den 1.2 TSI Motoren, können zu Kühlmittelverlust führen.','2014-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1215,'skoda-fabia-dritte-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse, wird gelegentlich berichtet.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1216,'skoda-fabia-dritte-generation','Klimaanlage','Vereinzelt können Probleme mit der Klimaanlage auftreten, wie z.B. undichte Kondensatoren oder Kompressorausfälle.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1217,'skoda-octavia-erste-generation','Rost','Anfällig an Radläufen, Schwellern, Türen und Heckklappe, besonders bei älteren Modellen und schlechter Pflege.','1996-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1218,'skoda-octavia-erste-generation','Fahrwerk','Verschleiß an Stoßdämpfern, Querlenkern und Buchsen, besonders bei hoher Laufleistung.','1996-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1219,'skoda-octavia-erste-generation','Auspuffanlage','Korrosion und Durchrostung, besonders am Endschalldämpfer.','1996-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1220,'skoda-octavia-erste-generation','Klimaanlage','Defekte Kompressoren oder Lecks im System.','1996-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1221,'skoda-octavia-zweite-generation','Steuerkette (1.2 TSI, 1.4 TSI, 1.8 TSI)','Bei den TSI-Motoren kann es zu Problemen mit der Steuerkette kommen, die sich längt und zu unruhigem Motorlauf oder Motorschäden führen kann. Dies äußert sich oft durch Rasseln beim Kaltstart.','2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1222,'skoda-octavia-zweite-generation','DSG-Getriebe (7-Gang DQ200)','Das 7-Gang-DSG-Getriebe (Trockenkupplung) kann Probleme mit der Mechatronik oder den Kupplungen aufweisen, was zu Ruckeln, Schaltverzögerungen oder Ausfällen führen kann.','2008-2013','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1223,'skoda-octavia-zweite-generation','Fensterheber','Defekte an den Fensterhebern, insbesondere an den Seilzügen oder Motoren, sind keine Seltenheit.','2004-2013','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1224,'skoda-octavia-zweite-generation','Turbolader (TSI-Motoren)','Bei einigen TSI-Motoren können Turboladerschäden auftreten, oft verbunden mit erhöhtem Ölverbrauch oder Leistungsverlust.','2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1225,'skoda-octavia-zweite-generation','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen können zu einem Ausfall der Klimaanlage führen.','2004-2013','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1226,'skoda-octavia-zweite-generation','Rost (Heckklappe, Radläufe)','Vereinzelt kann Rost an der Heckklappe (insbesondere im Bereich der Kennzeichenbeleuchtung) und an den Radläufen auftreten, besonders bei älteren Modellen.','2004-2008','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1227,'skoda-octavia-dritte-generation','Wasserpumpe','Undichtigkeiten und Defekte an der Wasserpumpe, insbesondere bei den 1.2 TSI und 1.4 TSI Motoren.','2012-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1228,'skoda-octavia-dritte-generation','Steuerkette','Längung der Steuerkette und daraus resultierende Motorschäden, vor allem bei den frühen 1.2 TSI und 1.4 TSI Motoren. Spätere Modelle mit Zahnriemen sind davon nicht betroffen.','2012-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1229,'skoda-octavia-dritte-generation','DSG-Getriebe (DQ200)','Probleme mit dem Trockenkupplungs-DSG (7-Gang), wie Ruckeln, Schaltverzögerungen oder Ausfälle der Mechatronik.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1230,'skoda-octavia-dritte-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1231,'skoda-octavia-dritte-generation','Elektronik','Vereinzelt Störungen der Infotainmentsysteme, Ausfälle von Sensoren oder Problemen mit der Start-Stopp-Automatik.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1232,'skoda-superb-erste-generation','Vorderachse','Verschleiß an Querlenkern und Spurstangenköpfen, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann. Dies ist eine bekannte Schwachstelle der VW Passat B5 Plattform.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1233,'skoda-superb-erste-generation','Fensterheber','Defekte an den Fensterhebermechanismen, insbesondere an den hinteren Türen, sind häufig. Die Kunststoffteile können brechen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1234,'skoda-superb-erste-generation','Turbolader (bei TDI-Motoren)','Bei den TDI-Motoren kann es zu Problemen mit dem Turbolader kommen, oft durch verstopfte VTG-Verstellung oder Lagerschäden, was zu Leistungsverlust führt.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1235,'skoda-superb-erste-generation','Klimaanlage','Undichtigkeiten im Klimasystem, defekte Kompressoren oder Steuergeräte können zu Ausfällen der Klimaanlage führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1236,'skoda-superb-erste-generation','Elektronik','Sporadische Ausfälle von Komfortelektronik wie Zentralverriegelung, Radio oder Kombiinstrument können auftreten, oft durch Korrosion an Steckverbindungen oder defekte Steuergeräte.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1237,'skoda-superb-zweite-generation','Steuerkette (1.4 TSI, 1.8 TSI, 2.0 TSI)','Probleme mit gelängten Steuerketten, die zu Motorschäden führen können. Äußert sich durch Rasseln beim Kaltstart.','Vor allem Modelle bis ca. 2012/2013','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1238,'skoda-superb-zweite-generation','DSG-Getriebe (DQ200, 7-Gang-Trockenkupplung)','Probleme mit Ruckeln, Schaltverzögerungen oder Ausfällen der Mechatronik. Betrifft vor allem die kleineren Motorisierungen.','Alle Baujahre, besonders frühe Modelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1239,'skoda-superb-zweite-generation','Wasserpumpe (TSI-Motoren)','Undichtigkeiten der Wasserpumpe, was zu Kühlmittelverlust führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1240,'skoda-superb-zweite-generation','Turbolader (TSI-Motoren)','Defekte Turbolader, insbesondere bei den 1.4 TSI und 1.8 TSI Motoren, oft durch mangelnde Ölversorgung oder Materialermüdung.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1241,'skoda-superb-zweite-generation','Injektoren (TDI-Motoren)','Ausfall oder Undichtigkeiten der Injektoren, was zu unrundem Motorlauf oder Leistungsverlust führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1242,'skoda-superb-zweite-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1243,'skoda-superb-zweite-generation','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern und Spurstangenköpfen, was sich durch Poltern oder unpräzises Fahrverhalten äußert.','Alle Baujahre, besonders bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1244,'skoda-superb-dritte-generation','Wasserpumpe','Bei einigen Motoren, insbesondere den 1.8 TSI und 2.0 TSI, kann es zu Undichtigkeiten oder Ausfällen der Wasserpumpe kommen, was zu Kühlmittelverlust und Überhitzung führen kann.','2015-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1245,'skoda-superb-dritte-generation','DSG-Getriebe (DQ200)','Das 7-Gang-Trockenkupplungs-DSG (DQ200) kann bei bestimmten Baujahren und Motorisierungen Ruckeln, Schaltprobleme oder vorzeitigen Verschleiß der Kupplungen aufweisen. Dies betrifft vor allem die kleineren Motorisierungen.','2015-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1246,'skoda-superb-dritte-generation','Infotainmentsystem','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des Infotainmentsystems wurden berichtet. Dies kann durch Updates behoben werden.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1247,'skoda-superb-dritte-generation','Bremsen','Einige Nutzer berichten von überdurchschnittlichem Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit stärkeren Motoren oder häufigem Stadtverkehr.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1248,'skoda-scala-erste-generation','Kupplung','Bei einigen Modellen mit Schaltgetriebe kann es zu Problemen mit der Kupplung kommen, insbesondere bei hoher Laufleistung oder häufigem Stadtverkehr.','2019-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1249,'skoda-scala-erste-generation','Infotainmentsystem','Gelegentliche Software-Probleme und Abstürze des Infotainmentsystems wurden berichtet.','2019-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1250,'skoda-scala-erste-generation','Rost','An Radläufen, Schwellern und im Bereich der Heckklappe kann es bei mangelnder Pflege zu Rostbildung kommen.','2019-2023','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1251,'skoda-kamiq-erste-generation','Bremsen','Vereinzelt Berichte über vorzeitigen Verschleiß der Bremsscheiben und -beläge, insbesondere bei starker Beanspruchung.','2018-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1252,'skoda-kamiq-erste-generation','Infotainmentsystem','Gelegentliche Software-Probleme, wie Abstürze oder verzögerte Reaktionen, besonders bei älteren Software-Versionen.','2018-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1253,'skoda-kamiq-erste-generation','Fahrwerk','Bei einigen Modellen mit Sportfahrwerk (Sportline/Monte Carlo) wurde über Geräuschentwicklung aus dem Fahrwerksbereich berichtet.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1254,'skoda-karoq-erste-generation','Kupplung (DSG-Getriebe)','Bei einigen Modellen mit DSG-Getriebe kann es zu Problemen mit der Kupplung kommen, die zu Ruckeln oder Ausfällen führt.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1255,'skoda-karoq-erste-generation','Elektronik (Infotainment)','Gelegentliche Software-Probleme und Abstürze des Infotainmentsystems.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1256,'skoda-karoq-erste-generation','Partikelfilter (Diesel)','Bei Kurzstreckenbetrieb können Dieselpartikelfilter verstopfen.','2017-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1257,'skoda-kodiaq-erste-generation','Wasserpumpe','Bei einigen 1.5 TSI und 2.0 TSI Motoren kann es zu Undichtigkeiten oder Ausfällen der Wasserpumpe kommen, was zu Kühlmittelverlust und Überhitzung führen kann.','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1258,'skoda-kodiaq-erste-generation','DSG-Getriebe (DQ200)','Insbesondere bei den trockenen 7-Gang-DSG-Getrieben (DQ200) in Verbindung mit kleineren Motoren können Ruckeln, Schaltprobleme oder vorzeitiger Verschleiß der Mechatronik auftreten.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1259,'skoda-kodiaq-erste-generation','Infotainment-System','Berichte über Softwarefehler, Abstürze oder langsame Reaktionen des Infotainment-Systems, insbesondere bei den frühen Modellen.','2017-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1260,'skoda-kodiaq-erste-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse, bei einigen Fahrprofilen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1261,'skoda-citigo-erste-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse. Kann zu Rubbeln oder verminderter Bremsleistung führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1262,'skoda-citigo-erste-generation','Auspuffanlage','Korrosion der Auspuffanlage, insbesondere bei Fahrzeugen, die häufig Kurzstrecken fahren. Kann zu Undichtigkeiten oder Rissen führen.','Ältere Baujahre (ab ca. 5 Jahren)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1263,'skoda-citigo-erste-generation','Fahrwerk (Vorderachse)','Verschleiß an den Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, insbesondere bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1264,'skoda-citigo-erste-generation','Zündspulen (Benziner)','Defekte Zündspulen können zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte führen.','Vereinzelt bei allen Baujahren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1265,'seat-ibiza-erste-generation','Rost','Die Karosserie, insbesondere Radläufe, Schweller, Türen und der Bereich um die Heckklappe, ist anfällig für Rostbildung.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1266,'seat-ibiza-erste-generation','Elektrik','Probleme mit der Fahrzeugelektrik, insbesondere Kabelbrüche, defekte Schalter und Ausfälle von Beleuchtung oder Instrumenten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1267,'seat-ibiza-erste-generation','Bremsanlage','Verschleiß der Bremskomponenten (Scheiben, Beläge) und Korrosion an Bremsleitungen und -sätteln sind häufig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1268,'seat-ibiza-erste-generation','Fahrwerk','Verschleiß an Querlenkerlagern, Stoßdämpfern und Federbrüchen kann auftreten.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1269,'seat-ibiza-erste-generation','Motor (System Porsche)','Obwohl robust, können bei mangelnder Wartung Ölverlust, Probleme mit der Zündung und der Gemischaufbereitung auftreten. Die Vergaser neigen zu Verschleiß.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1270,'seat-ibiza-zweite-generation','Rost','Rostbildung an Radläufen, Schwellern, Heckklappe und Unterboden, insbesondere bei älteren Modellen und vor dem Facelift.','1993-2002','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1271,'seat-ibiza-zweite-generation','Elektronik','Probleme mit der Elektrik, insbesondere Fensterhebern, Zentralverriegelung und Beleuchtung.','1993-2002','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1272,'seat-ibiza-zweite-generation','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','1993-2002','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1273,'seat-ibiza-zweite-generation','Bremsanlage','Festgehende Bremssättel, insbesondere an der Hinterachse, und erhöhter Verschleiß der Bremsbeläge und -scheiben.','1993-2002','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1274,'seat-ibiza-zweite-generation','Kühlsystem','Undichtigkeiten an Schläuchen, Kühler und Wasserpumpe, was zu Kühlmittelverlust und Überhitzung führen kann.','1993-2002','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1275,'seat-ibiza-dritte-generation','Querlenkerlager','Verschleiß der Gummilager an den vorderen Querlenkern führt zu Poltergeräuschen und unpräzisem Fahrverhalten. Besonders betroffen sind die hinteren Lager.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1276,'seat-ibiza-dritte-generation','Fensterheber','Defekte an den elektrischen Fensterhebern, oft durch gebrochene Kunststoffteile oder Seilzüge, führen zum Ausfall der Funktion.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1277,'seat-ibiza-dritte-generation','Zündspulen','Bei den Benzinmotoren, insbesondere den 1.2- und 1.4-Liter-Aggregaten, können Zündspulen ausfallen, was zu Motorruckeln und Leistungsverlust führt.','2002-2005','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1278,'seat-ibiza-dritte-generation','Turbolader (1.9 TDI)','Bei den 1.9 TDI-Motoren kann es zu Problemen mit dem Turbolader kommen, oft durch verkokte Leitschaufeln oder Lagerschäden, was zu Leistungsverlust führt.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1279,'seat-ibiza-dritte-generation','Klimaanlage','Undichtigkeiten im Klimasystem, defekte Kompressoren oder Steuerungen können zum Ausfall der Klimaanlage führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1280,'seat-ibiza-vierte-generation','Steuerkette (1.2 TSI, 1.4 TSI)','Bei den TSI-Motoren, insbesondere den frühen Baujahren, kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen. Dies kann zu Motorschäden führen.','ca. 2008-2012','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1281,'seat-ibiza-vierte-generation','Wasserpumpe (TSI-Motoren)','Undichtigkeiten oder Defekte an der Wasserpumpe sind keine Seltenheit, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre, insbesondere frühe TSI-Motoren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1282,'seat-ibiza-vierte-generation','Zündspulen (Benziner)','Defekte Zündspulen können zu Motorruckeln, Leistungsverlust und Aufleuchten der Motorkontrollleuchte führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1283,'seat-ibiza-vierte-generation','Klimaanlage','Probleme mit dem Klimakompressor oder undichten Leitungen können die Funktion der Klimaanlage beeinträchtigen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1284,'seat-ibiza-vierte-generation','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern oder Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','Alle Baujahre, insbesondere bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1288,'seat-ibiza-fünfte-generation','Infotainmentsystem','Gelegentliche Softwareprobleme, Abstürze oder langsame Reaktionen des Touchscreens, insbesondere bei älteren Softwareständen.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1289,'seat-ibiza-fünfte-generation','Bremsen','Vereinzelt Berichte über frühzeitigen Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit sportlicher Fahrweise.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1290,'seat-ibiza-fünfte-generation','Klimaanlage','Manche Nutzer berichten von unzureichender Kühlleistung oder Geräuschen aus dem Klimasystem.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1291,'seat-leon-erste-generation','Rost','Anfällig für Rostbildung an Radläufen, Schwellern, Türen und Heckklappe.','1999-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1292,'seat-leon-erste-generation','Fahrwerk','Verschleiß an Querlenkerlagern, Spurstangenköpfen und Stoßdämpfern.','1999-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1293,'seat-leon-erste-generation','Kupplung','Kann bei sportlicher Fahrweise oder hoher Laufleistung verschleißen.','1999-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1294,'seat-leon-erste-generation','1.8T Motor','Ölverlust, defekte Zündspulen, Turboladerprobleme.','1999-2006','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1295,'seat-leon-zweite-generation','Steuerkette (TSI-Motoren)','Bei einigen TSI-Motoren kann es zu Problemen mit der Steuerkette kommen, die zu Motorschäden führen können.','2005-2010','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1296,'seat-leon-zweite-generation','Klimaanlage','Ausfälle der Klimaanlage sind keine Seltenheit.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1297,'seat-leon-zweite-generation','Elektrik','Diverse elektrische Probleme, z.B. mit Fensterhebern oder Sensoren.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1298,'seat-leon-zweite-generation','Rost','Rostbildung an Radläufen, Heckklappe und Türen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1299,'seat-leon-dritte-generation','Steuerkette (1.2 TSI, 1.4 TSI)','Bei frühen Baujahren der TSI-Motoren (insbesondere vor 2013/2014) kann es zu Problemen mit der Steuerkette kommen, die sich durch Rasseln bemerkbar machen und im schlimmsten Fall zu Motorschäden führen können.','2012-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1300,'seat-leon-dritte-generation','Wasserpumpe (TSI-Motoren)','Undichtigkeiten oder Defekte an der Wasserpumpe, oft in Verbindung mit dem Thermostatgehäuse, können zu Kühlmittelverlust und Überhitzung führen.','Alle Baujahre, gehäuft bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1301,'seat-leon-dritte-generation','DSG-Getriebe (DQ200 7-Gang-Trockenkupplung)','Bei den 7-Gang-DSG-Getrieben (DQ200) können Probleme mit der Mechatronik oder den Kupplungen auftreten, die sich durch Ruckeln, Schaltverzögerungen oder Ausfälle äußern. Dies betrifft vor allem die schwächeren Motorisierungen.','Alle Baujahre, insbesondere bei hoher Beanspruchung','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1302,'seat-leon-dritte-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse, kann auftreten. Auch festrostende Bremssättel sind bekannt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1303,'seat-leon-dritte-generation','Infotainmentsystem','Softwareprobleme, Abstürze oder eine träge Bedienung des Infotainmentsystems können vorkommen. Nach dem Facelift wurde die Hardware verbessert.','2012-2016 (vor Facelift)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1304,'seat-arona-erste-generation','Kupplung','Bei einigen Modellen mit Schaltgetriebe kann es zu vorzeitigem Verschleiß der Kupplung kommen, insbesondere bei häufigem Stadtverkehr.','2017-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1305,'seat-arona-erste-generation','Infotainmentsystem','Gelegentliche Software-Probleme und Abstürze des Infotainmentsystems, insbesondere bei älteren Versionen vor dem Facelift.','2017-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1306,'seat-arona-erste-generation','Bremsen','Verschleiß der Bremsscheiben und Beläge kann je nach Fahrweise und Beladung schneller auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1307,'seat-ateca-erste-generation','Wasserpumpe','Bei einigen 1.4 TSI Motoren kann es zu Undichtigkeiten oder Ausfällen der Wasserpumpe kommen, was zu Kühlmittelverlust und Überhitzung führen kann.','2016-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1308,'seat-ateca-erste-generation','DSG-Getriebe (7-Gang)','Vereinzelt Berichte über Ruckeln, Schaltprobleme oder ungewöhnliche Geräusche, insbesondere bei den Trockenkupplungs-DSG (DQ200).','2016-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1309,'seat-ateca-erste-generation','Infotainmentsystem','Software-Probleme wie Abstürze, langsame Reaktion oder Ausfälle des Touchscreens wurden berichtet. Oft durch Updates behebbar.','2016-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1310,'seat-ateca-erste-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Vorderachse, bei einigen Fahrprofilen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1311,'cupra-formentor-erste-generation','Software/Infotainment','Berichte über gelegentliche Software-Fehler, Abstürze des Infotainmentsystems oder langsame Reaktionen.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1312,'cupra-formentor-erste-generation','12V-Batterie','Einige Nutzer berichten von frühzeitigen Ausfällen der 12V-Batterie, insbesondere bei Fahrzeugen mit Start-Stopp-Automatik oder häufigen Kurzstreckenfahrten.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1313,'cupra-formentor-erste-generation','Bremsen (Verschleiß)','Bei sportlicher Fahrweise kann der Verschleiß der Bremsbeläge und -scheiben überdurchschnittlich hoch sein.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1314,'toyota-aygo-i','Rost','Anfällig für Korrosion an Radläufen, Schwellern und Türen, besonders bei Fahrzeugen mit hoher Laufleistung oder Einsatz im Winter.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1315,'toyota-aygo-i','Kupplung','Verschleißerscheinungen bei hoher Laufleistung, insbesondere im Stadtverkehr.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1316,'toyota-aygo-i','Klimaanlage','Defekte oder nachlassende Kühlleistung.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1317,'toyota-aygo-ii','Wasserpumpe','Vereinzelt können Undichtigkeiten an der Wasserpumpe auftreten, was zu Kühlmittelverlust führen kann.','2014-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1318,'toyota-aygo-ii','Kupplung','Bei einigen Fahrzeugen, insbesondere bei häufigem Stadtverkehr, kann die Kupplung frühzeitig verschleißen oder Geräusche verursachen.','2014-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1319,'toyota-aygo-ii','Bremsen','Die Bremsanlage, insbesondere die hinteren Trommelbremsen, kann zu Rost neigen, wenn das Fahrzeug selten oder nur auf Kurzstrecken bewegt wird. Dies kann zu ungleichmäßiger Bremswirkung führen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1320,'toyota-aygo-ii','Infotainmentsystem','Das Touchscreen-Infotainmentsystem kann gelegentlich einfrieren oder langsam reagieren. Software-Updates können Abhilfe schaffen.','2014-2016','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1321,'toyota-yaris-i','Rost','An Radläufen, Schwellern und Türunterkanten, besonders bei Fahrzeugen mit geringer Pflege oder aus Regionen mit viel Streusalz.','1999-2005','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1322,'toyota-yaris-i','Kupplung','Verschleißerscheinungen bei hoher Laufleistung oder häufigem Stadtverkehr.','1999-2005','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1323,'toyota-yaris-i','Auspuffanlage','Korrosion und Durchrostung, besonders am Endschalldämpfer.','1999-2005','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1324,'toyota-yaris-ii','Wasserpumpe','Undichtigkeiten oder Lagerschäden können auftreten, was zu Kühlmittelverlust und Überhitzung führen kann.','Alle Baujahre, insbesondere bei höheren Laufleistungen.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1325,'toyota-yaris-ii','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse. Auch Rost an den Bremsscheiben bei wenig genutzten Fahrzeugen.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1326,'toyota-yaris-ii','Auspuffanlage','Rostbildung an der Auspuffanlage, insbesondere am Endschalldämpfer, kann zu vorzeitigem Austausch führen.','Alle Baujahre, besonders bei älteren Fahrzeugen.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1327,'toyota-yaris-ii','Kupplung','Bei Modellen mit dem automatisierten Schaltgetriebe (M-MT) kann es zu Ruckeln, verzögertem Schaltverhalten oder vorzeitigem Verschleiß der Kupplung kommen.','Alle Baujahre mit M-MT Getriebe.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1328,'toyota-yaris-iii','Bremsen','Verschleiß an Bremsbelägen und -scheiben, insbesondere bei häufigem Stadtverkehr.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1329,'toyota-yaris-iii','Fahrwerk','Verschleiß an Stoßdämpfern und Fahrwerkskomponenten, besonders bei Fahrzeugen mit hoher Laufleistung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1330,'toyota-yaris-iii','Kupplung (bei Schaltgetriebe)','Verschleißerscheinungen bei häufigem Anfahren und Kupplungsspiel.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1331,'toyota-yaris-iii','Hybrid-Batterie (bei Hybrid-Modellen)','Langfristige Degradation der Batteriekapazität, obwohl Toyota für die Langlebigkeit seiner Hybrid-Systeme bekannt ist.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1332,'toyota-yaris-iv','Infotainmentsystem','Vereinzelt Berichte über Software-Probleme und langsame Reaktionszeiten.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1333,'toyota-yaris-iv','Hybrid-Batterie','Obwohl generell sehr zuverlässig, sind bei sehr hoher Laufleistung oder extremen Bedingungen Kapazitätsverluste möglich.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1334,'toyota-corolla-ix','Rost','Anfällig für Rostbildung an Radläufen, Schwellern und hinteren Türen, besonders bei Fahrzeugen, die viel im Winterbetrieb eingesetzt wurden.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1335,'toyota-corolla-ix','Kupplung','Bei einigen Modellen kann die Kupplung vorzeitig verschleißen, insbesondere bei häufigem Stadtverkehr.','Unbekannt','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1336,'toyota-corolla-ix','Auspuffanlage','Kann im Laufe der Zeit Korrosion aufweisen und muss eventuell ersetzt werden.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1337,'toyota-corolla-x','Wasserpumpe','Undichtigkeiten und Geräusche können auftreten, insbesondere bei höheren Laufleistungen.','2007-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1338,'toyota-corolla-x','Kupplung','Bei einigen Modellen, insbesondere mit Dieselmotoren, kann die Kupplung frühzeitig verschleißen oder Rupfen zeigen.','2007-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1339,'toyota-corolla-x','Bremsen','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse.','2007-2012','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1340,'toyota-corolla-x','Fahrwerk (Querlenkerbuchsen)','Verschleiß der Gummibuchsen an den Querlenkern kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','2007-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1341,'toyota-corolla-xi','Kupplung (bei Schaltgetriebe)','Vereinzelt Berichte über frühzeitigen Verschleiß oder Probleme mit der Ausrückung.','2013-2016','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1342,'toyota-corolla-xi','Infotainmentsystem','Gelegentliche Software-Probleme, Langsamkeit oder Aussetzer.','2013-2018','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1343,'toyota-corolla-xii','12V-Batterie','Bei Hybridmodellen kann die 12V-Starterbatterie bei längeren Standzeiten oder häufigen Kurzstreckenfahrten entladen sein, was zu Startproblemen führt. Dies ist oft auf die geringe Kapazität und die Ladezyklen im Hybrid-System zurückzuführen.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1344,'toyota-corolla-xii','Infotainmentsystem','Das ursprüngliche Infotainmentsystem wurde von einigen Nutzern als langsam, wenig intuitiv und mit veralteter Grafik kritisiert. Software-Updates können die Performance verbessern, aber die Hardware bleibt limitiert. Das Facelift 2022 brachte ein deutlich verbessertes System.','2019-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1345,'toyota-corolla-xii','Bremsen (Verschleiß)','Bei einigen Fahrern wurde ein erhöhter Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse, festgestellt. Dies kann durch die Rekuperationsfunktion der Hybridmodelle beeinflusst werden, bei der die mechanischen Bremsen seltener und dann stärker beansprucht werden.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1346,'toyota-c-hr-i','Infotainmentsystem','Gelegentliche Software-Probleme, träge Reaktion, Konnektivitätsprobleme mit Smartphones.','2016-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1347,'toyota-c-hr-i','Bremsen (Hybrid)','Verschleiß der Bremsscheiben und -beläge kann bei reinem Stadtverkehr und häufiger Rekuperation schneller auftreten als erwartet.','2016-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1348,'toyota-c-hr-i','Fahrwerk','Geräuschentwicklung aus dem Fahrwerk (z.B. Klappern) kann bei höheren Laufleistungen auftreten, oft durch verschlissene Gelenke.','2016-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1349,'toyota-rav4-i','Rost','An Radläufen, Schwellern und im Bereich der hinteren Türen kann Rost auftreten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1350,'toyota-rav4-i','Fahrwerk','Verschleiß an Querlenkern und Stoßdämpfern ist möglich.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1351,'toyota-rav4-ii','Rost','An Radläufen, Schwellern und Türen, besonders bei Fahrzeugen aus Regionen mit Streusalz.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1352,'toyota-rav4-ii','Fahrwerk','Verschleiß an Stoßdämpfern und Querlenkern.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1353,'toyota-rav4-ii','Klimaanlage','Defekte Kompressoren oder Lecks im System.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1354,'toyota-rav4-iii','Kupplung','Bei Modellen mit Schaltgetriebe kann es zu vorzeitigem Verschleiß der Kupplung kommen, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder häufigem Stadtverkehr.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1355,'toyota-rav4-iii','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und -scheiben, insbesondere an der Hinterachse. Auch Festrosten der Bremssättel ist möglich.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1356,'toyota-rav4-iii','Dieselpartikelfilter (DPF)','Bei den Dieselmotoren kann es zu Problemen mit dem DPF kommen, insbesondere bei überwiegendem Kurzstreckenbetrieb, was zu Verstopfungen und Leistungsverlust führen kann.','Modelle mit Dieselmotor','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1357,'toyota-rav4-iii','Lenkung','Vereinzelt wurden Geräusche oder ein leichtes Spiel in der Lenkung gemeldet, oft verursacht durch die Lenksäule oder das Lenkgetriebe.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1358,'toyota-rav4-iv','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse. Auch festrostende Bremssättel können vorkommen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1359,'toyota-rav4-iv','Fahrwerk (Achsen/Lenkung)','Vereinzelt können ausgeschlagene Spurstangenköpfe oder Traggelenke auftreten, was zu Poltergeräuschen oder unpräzisem Fahrverhalten führt. Auch die Lenkung kann bei einigen Modellen Geräusche machen.','2012-2015','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1360,'toyota-rav4-iv','Dieselmotoren (D-4D)','Bei den Dieselmotoren gab es Berichte über Probleme mit dem AGR-Ventil und dem Dieselpartikelfilter, insbesondere bei Kurzstreckenfahrzeugen. Auch Injektoren können betroffen sein.','Alle Baujahre mit Dieselmotor','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1361,'toyota-rav4-iv','Klimaanlage','Manche Nutzer berichten von einer nachlassenden Kühlleistung oder Geräuschen der Klimaanlage, oft bedingt durch undichte Stellen oder Kompressorprobleme.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1362,'toyota-rav4-v','Infotainmentsystem','Das Infotainmentsystem kann als langsam und nicht immer intuitiv bedienbar wahrgenommen werden. Software-Updates können die Performance verbessern.','2018-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1363,'toyota-rav4-v','Geräuschentwicklung bei höheren Geschwindigkeiten','Einige Nutzer berichten von erhöhter Windgeräuschkulisse bei Autobahngeschwindigkeiten, was auf die Aerodynamik oder Dämmung zurückgeführt wird.','2018-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1364,'toyota-camry-xv10','Rost','Rost kann an den hinteren Radläufen, Schwellern und am Unterboden auftreten, insbesondere bei Fahrzeugen aus Regionen mit Streusalzeinsatz.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1365,'toyota-camry-xv10','Automatikgetriebe','Bei hohen Laufleistungen können die Automatikgetriebe Verschleißerscheinungen zeigen, die sich durch ruckeliges Schalten oder verzögertes Einlegen der Gänge äußern. Regelmäßiger Ölwechsel ist entscheidend.','Alle, insbesondere ab 150.000 km','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1366,'toyota-camry-xv10','Bremsanlage','Die Bremsen können bei intensiver Nutzung zu Fading neigen. Bremsscheiben und -beläge verschleißen bei mangelnder Wartung schnell.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1367,'toyota-camry-xv10','Fahrwerk','Verschleiß an Querlenkerbuchsen und Stoßdämpfern ist altersbedingt möglich, was zu Poltergeräuschen und schlechterem Fahrverhalten führt.','Alle, insbesondere ab 100.000 km','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1368,'toyota-camry-xv20','Auspuffanlage','Korrosion und Durchrostung, insbesondere an Schalldämpfern und Rohren.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1369,'toyota-camry-xv20','Fahrwerk','Verschleiß an Querlenkerbuchsen und Stoßdämpfern, was zu polternden Geräuschen und schlechterem Fahrverhalten führen kann.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1370,'toyota-camry-xv20','Klimaanlage','Undichtigkeiten im System, defekte Kompressoren oder Lüfter.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1371,'toyota-camry-xv30','Fahrwerk','Verschleiß an Querlenkerlagern und Stoßdämpfern, besonders bei Fahrzeugen mit hoher Laufleistung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1372,'toyota-camry-xv30','Auspuffanlage','Korrosion an Endschalldämpfer und Hosenrohr, insbesondere in Regionen mit hoher Salzstreuung im Winter.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1373,'toyota-camry-xv30','Klimaanlage','Defekte Kompressoren oder Undichtigkeiten im System, die zu nachlassender Kühlleistung führen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1374,'toyota-camry-xv40','Wasserpumpe','Bei einigen V6-Modellen (2GR-FE Motor) kann die Wasserpumpe vorzeitig undicht werden, was zu Kühlmittelverlust führt.','2007-2009','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1375,'toyota-camry-xv40','Armaturenbrett','Das Armaturenbrett kann bei starker Sonneneinstrahlung Risse entwickeln oder klebrig werden.','2007-2011','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1376,'toyota-camry-xv40','Automatikgetriebe (5-Gang)','Bei einigen Modellen kann es zu Schaltrucken oder einem verzögerten Gangwechsel kommen, oft bedingt durch Probleme mit dem Ventilgehäuse oder der Getriebesteuerung.','2007-2009','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1377,'toyota-camry-xv40','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Vorderachse, sowie Neigung zu Rubbeln.','2006-2011','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1378,'toyota-camry-xv50','Lenkung','Gelegentliche Probleme mit der elektrischen Servolenkung, die zu Geräuschen oder einem ungleichmäßigen Lenkgefühl führen können.','2011-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1379,'toyota-camry-xv50','Infotainmentsystem','Bei frühen Modellen gab es Berichte über gelegentliche Software-Probleme oder eine träge Reaktion des Touchscreens.','2011-2013','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1380,'toyota-camry-xv50','Bremsen','Verschleiß der Bremsscheiben und -beläge kann bei Vielfahrern oder sportlicher Fahrweise schneller auftreten.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1381,'toyota-camry-xv70','Bremsen','Einige Berichte über erhöhten Verschleiß der Bremsbeläge und -scheiben, insbesondere bei häufigem Stadtverkehr oder sportlicher Fahrweise. Dies kann zu vorzeitigem Austausch führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1382,'toyota-camry-xv70','Infotainmentsystem','Vor dem Facelift (bis Ende 2020) wurde das Infotainmentsystem oft als langsam, wenig intuitiv und grafisch veraltet kritisiert. Nach dem Facelift wurde dies verbessert, aber es kann immer noch zu gelegentlichen Software-Problemen oder Abstürzen kommen.','2019-2020 (stärker), 2021-2024 (gelegentlich)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1383,'toyota-camry-xv70','Geräuschentwicklung','Bei höheren Geschwindigkeiten oder auf schlechten Straßen kann die Geräuschdämmung im Innenraum als nicht optimal empfunden werden, insbesondere Wind- und Abrollgeräusche.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1384,'toyota-prius-xw10','Hybridbatterie','Mit zunehmendem Alter kann die Leistung der Nickel-Metallhydrid-Batterie nachlassen, was zu einem höheren Kraftstoffverbrauch oder im Extremfall zu einem Ausfall führen kann. Dies ist ein typisches Verschleißteil bei älteren Hybridfahrzeugen.','Alle Baujahre, insbesondere Fahrzeuge mit hoher Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1385,'toyota-prius-xw10','Bremsanlage','Aufgrund der Rekuperation werden die mechanischen Bremsen weniger genutzt, was zu Korrosion an den Bremsscheiben und -sätteln führen kann, wenn das Fahrzeug nicht regelmäßig und kräftig abgebremst wird.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1386,'toyota-prius-xw10','Katalysator','Der Katalysator kann bei sehr hohen Laufleistungen oder unsachgemäßer Wartung an Effizienz verlieren oder verstopfen, was zu Problemen bei der Abgasuntersuchung führen kann.','Alle Baujahre, insbesondere ältere Fahrzeuge.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1387,'toyota-prius-xw20','Hybridbatterie','Mit zunehmendem Alter und hoher Laufleistung kann die Leistung der Nickel-Metallhydrid-Batterie nachlassen, was zu einem erhöhten Kraftstoffverbrauch und Fehlermeldungen führen kann. Dies äußert sich oft durch eine reduzierte elektrische Reichweite oder das häufigere Zuschalten des Verbrennungsmotors.','Alle Baujahre, insbesondere Fahrzeuge mit hoher Laufleistung (>150.000 km)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1388,'toyota-prius-xw20','ABS-Aktuator/Bremskraftverstärker','Es kann zu Ausfällen des ABS-Aktuators kommen, was sich durch Warnleuchten im Armaturenbrett (ABS, VSC, Bremswarnleuchte) und ein verändertes Bremsgefühl äußert. Ein defekter Aktuator kann die Bremsleistung beeinträchtigen.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1389,'toyota-prius-xw20','Wasserpumpe (Inverterkühlung)','Die elektrische Wasserpumpe, die für die Kühlung des Inverters zuständig ist, kann undicht werden oder ausfallen. Ein Ausfall kann zur Überhitzung des Inverters und damit zu einem Systemausfall führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1390,'toyota-prius-xw20','Katalysator','Bei einigen Fahrzeugen kann es zu einem vorzeitigen Verschleiß oder einer Verstopfung des Katalysators kommen, was zu einer reduzierten Motorleistung und erhöhten Emissionen führt. Dies kann durch eine leuchtende Motorkontrollleuchte angezeigt werden.','Alle Baujahre, insbesondere bei hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1391,'toyota-prius-xw30','Hybridbatterie','Mit zunehmendem Alter und hoher Laufleistung kann die Leistung der Hybridbatterie nachlassen, was sich in einem höheren Kraftstoffverbrauch und einer geringeren elektrischen Reichweite äußert. Ein Defekt ist selten, aber teuer.','Alle Baujahre, insbesondere Fahrzeuge mit hoher Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1392,'toyota-prius-xw30','Wasserpumpe (Inverterkühlung)','Die elektrische Wasserpumpe, die für die Kühlung des Inverters zuständig ist, kann ausfallen. Dies führt zu einer Überhitzung des Inverters und kann im schlimmsten Fall zu einem Systemausfall führen.','Insbesondere frühe Baujahre (2009-2011).','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1393,'toyota-prius-xw30','Bremsen','Aufgrund des regenerativen Bremssystems werden die mechanischen Bremsen weniger beansprucht, was zu Korrosion an den Bremsscheiben und festsitzenden Bremssätteln führen kann, besonders bei Kurzstreckenfahrzeugen.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1394,'toyota-prius-xw30','Scheinwerfer (Beschlagen)','Einige Besitzer berichten von beschlagenen Scheinwerfern, insbesondere nach dem Waschen oder bei feuchtem Wetter, was auf undichte Dichtungen hindeuten kann.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1395,'toyota-prius-xw50','12V-Batterie','Die kleine 12V-Starterbatterie, die für die Bordelektronik zuständig ist, kann bei seltener Nutzung oder Kälte schnell entladen sein und Startprobleme verursachen. Dies ist ein häufiges Problem bei Hybridfahrzeugen, da sie nicht zum Starten des Verbrennungsmotors verwendet wird und daher weniger robust ausgelegt ist.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1396,'toyota-prius-xw50','Bremsen','Aufgrund der starken Rekuperation werden die Bremsen weniger beansprucht, was zu Korrosion an den Bremsscheiben führen kann, insbesondere bei Fahrzeugen, die viel im Stadtverkehr oder auf Kurzstrecken bewegt werden. Dies kann zu ungleichmäßiger Bremswirkung oder Geräuschen führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1397,'toyota-prius-xw50','Multimediasystem (Toyota Touch 2)','Das Infotainmentsystem kann gelegentlich langsam reagieren, abstürzen oder Probleme mit der Bluetooth-Verbindung aufweisen. Software-Updates können hier Abhilfe schaffen.','Frühe Baujahre (bis ca. 2018)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1398,'toyota-land-cruiser-j40','Rahmen und Karosserie','Starke Rostanfälligkeit, insbesondere an den Rahmenlängsträgern, den Karosserieblechen (Schweller, Radläufe, Türen) und den Befestigungspunkten der Karosserie am Rahmen. Dies ist das größte Problem bei der J40-Serie.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1399,'toyota-land-cruiser-j40','Bremsanlage','Verschleiß der Trommelbremsen (spätere Modelle hatten vorne Scheibenbremsen), festgerostete Bremsleitungen und -zylinder. Die Bremsleistung ist im Vergleich zu modernen Fahrzeugen gering.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1400,'toyota-land-cruiser-j40','Lenkung','Spiel in der Lenkung, verschlissene Lenkgetriebe und Spurstangenköpfe. Die Lenkung ist oft indirekt und erfordert regelmäßige Wartung.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1401,'toyota-land-cruiser-j40','Motor und Getriebe','Obwohl die Motoren als sehr robust gelten, können bei mangelnder Wartung Ölverlust, verschlissene Einspritzpumpen (Diesel) oder Zylinderkopfdichtungen auftreten. Getriebe und Verteilergetriebe können bei hoher Laufleistung Geräusche machen oder undicht werden.','Alle Baujahre, insbesondere bei hoher Laufleistung und schlechter Wartung','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1402,'toyota-land-cruiser-j60','Rost','An Radläufen, Schwellern, Türen, Heckklappe und Unterboden.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1403,'toyota-land-cruiser-j60','Kühlsystem','Undichtigkeiten am Kühler und Schläuchen, Überhitzung bei starker Beanspruchung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1404,'toyota-land-cruiser-j60','Getriebe','Schaltgetriebe können schwergängig werden, Automatikgetriebe können bei hoher Laufleistung Probleme bereiten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1405,'toyota-land-cruiser-j80','Rost','Besonders an Rahmen, Karosserie (Radläufe, Schweller, Heckklappe) und Anbauteilen.','Alle Baujahre, je nach Pflege und Einsatz','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1406,'toyota-land-cruiser-j80','Differentialsperren','Die optionalen elektrischen Differentialsperren können aufgrund von Korrosion oder mangelnder Nutzung klemmen oder ausfallen.','Alle Baujahre mit Sperren','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1407,'toyota-land-cruiser-j80','Lenkgetriebe','Verschleiß und Undichtigkeiten am Lenkgetriebe sind altersbedingt häufig.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1408,'toyota-land-cruiser-j80','Kurbelwellenlager (bei 1HD-T/FT Motoren)','Bei den Dieselmotoren 1HD-T und 1HD-FT können die Kurbelwellenlager bei mangelnder Wartung oder hoher Belastung verschleißen.','Alle Baujahre mit diesen Motoren','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1409,'toyota-land-cruiser-j100','Rahmen','Rostbildung am Leiterrahmen, insbesondere an den Aufnahmepunkten der Karosserie und im Bereich der Hinterachse.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1410,'toyota-land-cruiser-j100','Automatikgetriebe','Bei den V8-Modellen kann es zu Problemen mit dem Automatikgetriebe kommen, insbesondere bei hoher Laufleistung und mangelnder Wartung.','Vor allem Modelle vor dem Facelift 2003','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1411,'toyota-land-cruiser-j100','Kühlsystem','Undichtigkeiten am Kühler und an den Schläuchen, Überhitzung bei starker Beanspruchung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1412,'toyota-land-cruiser-j200','Rost','Insbesondere an Rahmen, Unterboden und Achsteilen kann bei älteren Modellen oder Fahrzeugen aus Regionen mit Streusalzeinsatz Rost auftreten. Dies ist oft auf mangelnde Unterbodenpflege zurückzuführen.','Alle Baujahre, insbesondere ältere Exemplare','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1413,'toyota-land-cruiser-j200','Injektoren (Diesel)','Bei den Dieselmotoren können die Injektoren mit der Zeit verschleißen oder verstopfen, was zu unrundem Motorlauf, Leistungsverlust oder erhöhtem Kraftstoffverbrauch führen kann.','Alle Diesel-Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1414,'toyota-land-cruiser-j200','Luftfederung (falls vorhanden)','Fahrzeuge mit optionaler Luftfederung können im Alter Probleme mit undichten Luftbälgen oder defekten Kompressoren bekommen, was zu einer Absenkung des Fahrzeugs oder Fehlermeldungen führt.','Alle Baujahre mit Luftfederung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1415,'toyota-land-cruiser-j200','Bremsen','Aufgrund des hohen Fahrzeuggewichts und der Leistungsfähigkeit kann es zu erhöhtem Verschleiß an Bremsbelägen und -scheiben kommen, insbesondere bei häufigem Anhängerbetrieb oder sportlicher Fahrweise.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1416,'toyota-hilux-erste-generation','Rost','Besonders anfällig sind Radläufe, Schweller, Ladeboden und der Rahmen. Durch die einfache Konstruktion und den Einsatz im Nutzfahrzeugbereich ist Rost ein häufiges Problem.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1417,'toyota-hilux-erste-generation','Aufhängung','Verschleiß an Blattfedern und Stoßdämpfern, insbesondere bei starker Belastung oder hoher Laufleistung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1418,'toyota-hilux-vierte-generation','Rost','Wie bei vielen japanischen Fahrzeugen dieser Ära ist Rost ein großes Problem, insbesondere an Rahmen, Karosserieblechen, Radläufen und Ladeflächen. Regelmäßige Kontrolle und Rostschutzbehandlung sind essenziell.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1419,'toyota-hilux-vierte-generation','Fahrwerk (Vorderachse)','Bei Modellen mit Einzelradaufhängung vorne können die Torsionsstäbe und Querlenkerbuchsen verschleißen. Bei den selteneren Starrachsmodellen sind die Blattfedern und Stoßdämpfer zu prüfen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1420,'toyota-hilux-vierte-generation','Bremsen','Die Bremsanlage, insbesondere die Trommelbremsen hinten, kann bei mangelnder Wartung zu Problemen führen. Festgehende Bremszylinder oder verschlissene Beläge sind häufig.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1421,'toyota-hilux-fünfte-generation','Rost','Wie bei vielen japanischen Fahrzeugen dieser Ära ist Rost ein großes Thema, insbesondere an Rahmen, Ladefläche, Radläufen und Schwellern. Regelmäßige Kontrolle und Rostschutz sind essenziell.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1422,'toyota-hilux-fünfte-generation','Vorderachsaufhängung','Verschleiß an den Querlenkerbuchsen und Kugelgelenken der vorderen Einzelradaufhängung, besonders bei Fahrzeugen mit hoher Laufleistung oder Offroad-Einsatz.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1423,'toyota-hilux-fünfte-generation','Kupplung','Bei Modellen mit Schaltgetriebe kann die Kupplung bei hoher Beanspruchung (Anhängerbetrieb, schwere Lasten) vorzeitig verschleißen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1424,'toyota-hilux-fünfte-generation','Bremsanlage','Verschleiß der Bremskomponenten (Scheiben, Beläge) ist normal, aber bei älteren Fahrzeugen können auch Bremssättel festgehen oder Bremsleitungen korrodieren.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1425,'toyota-hilux-sechste-generation','Rost','Besonders Rahmen, Ladefläche und Karosseriebleche können bei mangelnder Pflege oder Einsatz in salzhaltigen Regionen stark rosten.','Alle Baujahre','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1426,'toyota-hilux-sechste-generation','Fahrwerk','Verschleiß an Querlenkern, Spurstangenköpfen und Stoßdämpfern, insbesondere bei Fahrzeugen, die häufig im Gelände oder mit hoher Zuladung bewegt wurden.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1427,'toyota-hilux-sechste-generation','Einspritzpumpen (Diesel)','Bei älteren Dieselmotoren können Probleme mit den Einspritzpumpen auftreten, was zu Leistungsverlust oder Startschwierigkeiten führen kann.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1428,'toyota-hilux-sechste-generation','Kupplung','Bei Fahrzeugen mit Schaltgetriebe und hoher Beanspruchung (Anhängerbetrieb, Gelände) kann die Kupplung vorzeitig verschleißen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1429,'toyota-hilux-siebte-generation','Rahmenkorrosion','Insbesondere bei Fahrzeugen, die in Regionen mit viel Salz oder Offroad-Einsatz genutzt wurden, kann es zu starker Korrosion am Leiterrahmen kommen. Dies kann die strukturelle Integrität beeinträchtigen.','Alle Baujahre, insbesondere ältere Modelle und solche aus salzreichen Regionen','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1430,'toyota-hilux-siebte-generation','Injektoren (Dieselmotoren)','Bei den 2.5 D-4D und 3.0 D-4D Dieselmotoren können die Injektoren verschleißen oder verstopfen, was zu unrundem Motorlauf, Leistungsverlust und erhöhtem Kraftstoffverbrauch führt. Ein Austausch ist oft kostspielig.','2005-2010','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1431,'toyota-hilux-siebte-generation','Turbolader (Dieselmotoren)','Einige Berichte über vorzeitigen Verschleiß oder Defekte am Turbolader, insbesondere bei Fahrzeugen mit hoher Laufleistung oder mangelnder Wartung.','Alle Baujahre, insbesondere bei hoher Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1432,'toyota-hilux-siebte-generation','Kupplung (Schaltgetriebe)','Bei Fahrzeugen mit Schaltgetriebe, insbesondere bei häufigem Anhängerbetrieb oder Offroad-Einsatz, kann die Kupplung frühzeitig verschleißen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1433,'toyota-hilux-achte-generation','Dieselpartikelfilter (DPF)','Probleme mit Verstopfung des DPF, insbesondere bei häufigem Kurzstreckenverkehr, was zu Leistungsverlust und Notlauf führen kann. Regelmäßige Regenerationsfahrten sind notwendig.','2015-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1434,'toyota-hilux-achte-generation','Fahrwerk (Blattfedern hinten)','Bei starker Beladung oder intensivem Offroad-Einsatz können die hinteren Blattfedern anfangen zu knarren oder zu quietschen. In seltenen Fällen kann es zu Ermüdungserscheinungen kommen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1435,'toyota-hilux-achte-generation','Infotainmentsystem','Das Infotainmentsystem der frühen Baujahre wurde oft als langsam und wenig intuitiv kritisiert. Software-Updates können Abhilfe schaffen, aber die Hardware bleibt begrenzt. Mit den Facelifts wurde dies deutlich verbessert.','2015-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1436,'toyota-supra-erste-generation-(a40/a50)','Karosserie','Rostbefall an Radläufen, Schwellern, Türunterschweller, hinteren Radhäusern und im Bereich der Windschutzscheibe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1437,'toyota-supra-erste-generation-(a40/a50)','Motor (6-Zylinder)','Verschleiß an Ventilschaftdichtungen, Steuerkette kann Geräusche machen, Kühlung kann bei mangelnder Wartung Probleme bereiten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1438,'toyota-supra-erste-generation-(a40/a50)','Getriebe','Manuelle Getriebe können Synchronringe verschleißen, Automatikgetriebe können Schaltprobleme aufweisen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1439,'toyota-supra-erste-generation-(a40/a50)','Elektrik','Alterungserscheinungen an Kabelbäumen, Korrosion an Steckverbindungen, Ausfall von Instrumentenbeleuchtung oder Anzeigen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1440,'toyota-supra-zweite-generation-(a60)','Rost','Wie bei vielen japanischen Fahrzeugen dieser Ära kann Rost an den Radläufen, Schwellern, dem Unterboden und den Türunterkanten ein Problem darstellen, insbesondere bei Fahrzeugen aus Regionen mit salzhaltigen Straßen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1441,'toyota-supra-zweite-generation-(a60)','Elektronik','Probleme mit der alternden Fahrzeugelektronik, insbesondere bei den digitalen Armaturenbrettern der L-Type-Modelle, können auftreten. Auch elektrische Fensterheber und Zentralverriegelung können Störungen aufweisen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1442,'toyota-supra-zweite-generation-(a60)','Fahrwerk','Verschleiß an den Fahrwerkskomponenten wie Stoßdämpfern, Querlenkerbuchsen und Spurstangenköpfen ist altersbedingt üblich und kann zu Poltergeräuschen oder unpräzisem Fahrverhalten führen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1443,'toyota-supra-dritte-generation-(a70)','Rost','Anfällig für Korrosion an Radläufen, Schwellern, Türen und im Bereich der Heckklappe.','Alle','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1444,'toyota-supra-dritte-generation-(a70)','Kühlsystem (3.0 Turbo)','Neigung zur Überhitzung bei mangelnder Wartung oder defekten Komponenten.','1986-1993 (insbesondere 3.0 Turbo)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1445,'toyota-supra-dritte-generation-(a70)','Ausklappbare Scheinwerfer','Mechanische Probleme mit den Motoren und Gestängen, die die Scheinwerfer bewegen.','Modelle mit ausklappbaren Scheinwerfern (bis ca. 1990)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1446,'toyota-supra-dritte-generation-(a70)','Getriebe','Verschleißerscheinungen, insbesondere bei starker Beanspruchung. Synchronringe können Probleme bereiten.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1447,'toyota-supra-vierte-generation-(a80)','Rost','Anfällig für Rostbildung an Radläufen, Schwellern und im Bereich der Heckklappe.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1448,'toyota-supra-vierte-generation-(a80)','Getriebe (manuell)','Bei starker Beanspruchung oder hohem Drehmoment können Synchronringe verschleißen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1449,'toyota-supra-vierte-generation-(a80)','Turbolader (2JZ-GTE)','Bei stark getunten Motoren oder mangelnder Wartung können die Turbolader überhitzen oder verschleißen.','Alle (besonders bei getunten Fahrzeugen)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1453,'toyota-supra-fünfte-generation-(a90)','Infotainmentsystem','Das Infotainmentsystem, das auf BMW-Technologie basiert, kann gelegentlich Softwarefehler oder Abstürze aufweisen. Dies äußert sich in eingefrorenen Bildschirmen oder nicht reagierenden Eingaben.','2019-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1454,'toyota-supra-fünfte-generation-(a90)','Bremsen','Bei sehr sportlicher Fahrweise kann es zu erhöhtem Verschleiß der Bremsbeläge und -scheiben kommen. Einige Nutzer berichten von Fading bei extremer Beanspruchung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1455,'toyota-supra-fünfte-generation-(a90)','Lackqualität','Einige Berichte deuten auf eine empfindliche Lackierung hin, die anfällig für Steinschläge und Kratzer sein kann, insbesondere an der Frontpartie und den Seitenschwellern.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1456,'toyota-bz4x-erste-generation','Batteriemanagementsystem','Vereinzelt Berichte über Probleme mit dem Batteriemanagementsystem, die zu Leistungseinbußen oder Ladeabbrüchen führen können.','2022-2023','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1457,'toyota-bz4x-erste-generation','Infotainmentsystem','Gelegentliche Software-Fehler und langsame Reaktionszeiten des Infotainmentsystems.','2022-2024','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1458,'hyundai-i10-erste-generation','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Vorderachse. Auch festgerostete Bremssättel sind keine Seltenheit.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1459,'hyundai-i10-erste-generation','Fahrwerk (Achsen und Lenkung)','Verschleiß an den Achsgelenken und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Auch ausgeschlagene Querlenkerlager sind bekannt.','Alle Baujahre, insbesondere bei höherer Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1460,'hyundai-i10-erste-generation','Auspuffanlage','Die Auspuffanlage neigt zu Rost und Undichtigkeiten, insbesondere der Endschalldämpfer.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1461,'hyundai-i10-erste-generation','Beleuchtung','Defekte Glühlampen, insbesondere an den Scheinwerfern, sind häufiger als bei anderen Modellen. Auch Feuchtigkeit in den Scheinwerfern kann vorkommen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1462,'hyundai-i10-zweite-generation','Fahrwerk','Verschleiß an Querlenkerlagern und Stoßdämpfern, insbesondere bei Fahrzeugen mit hoher Laufleistung oder häufigem Stadtverkehr.','2013-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1463,'hyundai-i10-zweite-generation','Kupplung','Bei Schaltgetrieben kann die Kupplung vorzeitig verschleißen, besonders bei häufigem Anfahren im Stadtverkehr.','2013-2018','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1464,'hyundai-i10-zweite-generation','Elektronik','Gelegentliche Probleme mit dem Infotainmentsystem oder der Zentralverriegelung.','2014-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1465,'hyundai-i10-dritte-generation','Kupplung','Bei einigen Modellen mit Schaltgetriebe wurde über frühzeitigen Verschleiß der Kupplung berichtet.','2020-2022','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1466,'hyundai-i10-dritte-generation','Infotainmentsystem','Gelegentliche Software-Probleme und Abstürze des Infotainmentsystems.','2020-2023','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1467,'hyundai-i20-erste-generation','Bremsanlage','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere an der Hinterachse. Festgehende Bremssättel sind ebenfalls bekannt.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1468,'hyundai-i20-erste-generation','Fahrwerk','Verschleiß an den Achsgelenken und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Auch defekte Stoßdämpfer sind keine Seltenheit.','Alle Baujahre, insbesondere bei höheren Laufleistungen','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1469,'hyundai-i20-erste-generation','Beleuchtung','Ausfall von Glühlampen, insbesondere der Abblendlichter, ist häufiger als bei anderen Modellen. Gelegentlich auch Probleme mit Feuchtigkeit in den Scheinwerfern.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1470,'hyundai-i20-erste-generation','Rost','Rostbildung kann an der Auspuffanlage und vereinzelt an den Achsteilen auftreten. Karosserierost ist selten, aber bei unzureichender Pflege an Steinschlagstellen möglich.','Ältere Baujahre, insbesondere bei Fahrzeugen, die viel im Winter gefahren wurden','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1471,'hyundai-i20-zweite-generation','Fahrwerk','Vereinzelt Berichte über frühzeitigen Verschleiß von Fahrwerkskomponenten wie Stoßdämpfern und Querlenkern, insbesondere bei Fahrzeugen mit hoher Laufleistung oder sportlicher Fahrweise.','2014-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1472,'hyundai-i20-zweite-generation','Kupplung','Bei einigen Modellen mit Schaltgetriebe wurde über einen erhöhten Verschleiß der Kupplung berichtet, insbesondere im Stadtverkehr.','2014-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1473,'hyundai-i20-zweite-generation','Elektronik','Gelegentliche Probleme mit der Bordelektronik, z.B. Fehlermeldungen oder Ausfälle von Infotainmentsystemen.','2014-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1474,'hyundai-i20-dritte-generation','Infotainmentsystem','Gelegentliche Software-Probleme, Ruckler oder Abstürze des Systems.','2020-2022','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1475,'hyundai-i20-dritte-generation','Bremsen','Bei einigen Fahrzeugen wurde von erhöhtem Bremsenverschleiß oder Geräuschen berichtet.','2020-2021','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1476,'hyundai-i20-dritte-generation','1.0 T-GDI Motor','Vereinzelt Berichte über erhöhten Ölverbrauch oder unrunden Motorlauf, insbesondere bei frühen Baujahren.','2020-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1477,'hyundai-i30-erste-generation','Fahrwerk','Verschleiß an Querlenkerlagern und Stoßdämpfern, insbesondere bei Fahrzeugen mit hoher Laufleistung oder Anhängerbetrieb.','2007-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1478,'hyundai-i30-erste-generation','Bremsen','Vorzeitiger Verschleiß der Bremsscheiben und Beläge, besonders an der Vorderachse.','2007-2011','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1479,'hyundai-i30-erste-generation','Klimaanlage','Defekte Klimakompressoren oder Undichtigkeiten im System.','2007-2011','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1480,'hyundai-i30-zweite-generation','Lenkung','Geräusche (Knacken, Klappern) aus der Lenkung, oft verursacht durch eine verschlissene Lenksäulenkupplung (Kupplung zwischen Lenkgetriebe und Lenksäule) oder Probleme mit dem Lenkgetriebe selbst. Kann auch ein Gefühl von Spiel in der Lenkung verursachen.','2012-2014','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1481,'hyundai-i30-zweite-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse. Auch Festsitzen der Bremssättel ist möglich, was zu ungleichmäßigem Verschleiß und Geräuschen führt.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1482,'hyundai-i30-zweite-generation','Kupplung (Schaltgetriebe)','Bei einigen Modellen, insbesondere mit stärkeren Motoren, kann es zu vorzeitigem Verschleiß der Kupplung kommen, was sich durch Rutschen oder Rupfen bemerkbar macht.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1483,'hyundai-i30-zweite-generation','Fahrwerk (Vorderachse)','Verschleiß an den Stabilisator-Koppelstangen oder Querlenkerlagern kann zu Poltergeräuschen beim Überfahren von Unebenheiten führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1484,'hyundai-i30-dritte-generation','Bremsen','Überdurchschnittlicher Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere an der Hinterachse. Kann zu frühzeitigem Austausch führen.','Ab 2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1485,'hyundai-i30-dritte-generation','Fahrwerk (Achsen/Lenkung)','Bei der HU können überdurchschnittlich oft Mängel an Achsaufhängungen und Lenkgelenken festgestellt werden. Auch ausgeschlagene Spurstangenköpfe sind möglich.','Ab 2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1486,'hyundai-i30-dritte-generation','Beleuchtung','Mängel an der Beleuchtungsanlage, insbesondere defekte Leuchtmittel oder fehlerhafte Einstellung der Scheinwerfer, werden bei der HU häufiger beanstandet.','Ab 2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1487,'hyundai-i30-dritte-generation','1.4 T-GDI Motor (G4LD)','Einige Berichte über erhöhten Ölverbrauch und in seltenen Fällen Motorschäden durch Probleme mit der Steuerkette oder den Kolbenringen. Betrifft vor allem frühe Baujahre.','2017-2019','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1488,'hyundai-kona-erste-generation','12V-Batterie','Bei einigen Modellen, insbesondere den Elektro-Varianten, kann es zu einer frühzeitigen Entladung oder Defekten der 12V-Batterie kommen, was zu Startproblemen führt.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1489,'hyundai-kona-erste-generation','Infotainmentsystem','Gelegentliche Berichte über Softwarefehler, Abstürze oder langsame Reaktionen des Infotainmentsystems.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1490,'hyundai-kona-erste-generation','Fahrwerk (Vorderachse)','Bei einigen Fahrzeugen können Geräusche von der Vorderachse auftreten, die auf verschlissene Stabilisatorlager oder Koppelstangen hindeuten.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1491,'hyundai-kona-erste-generation','Ladeanschluss (Kona Elektro)','Vereinzelt wurden Probleme mit dem Ladeanschluss bei den Elektro-Modellen gemeldet, die zu Fehlermeldungen oder Unterbrechungen des Ladevorgangs führen können.','2018-2020','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1492,'hyundai-tucson-erste-generation','Rost','Rostbildung kann an der Karosserie, insbesondere an den Radläufen, Schwellern und der Heckklappe, sowie am Unterboden und den Achsteilen auftreten.','Alle Baujahre, besonders ältere Modelle und Fahrzeuge aus Regionen mit Streusalzeinsatz.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1493,'hyundai-tucson-erste-generation','Fahrwerk','Verschleiß an Querlenkerbuchsen, Spurstangenköpfen und Stoßdämpfern, was zu Poltergeräuschen und unpräzisem Fahrverhalten führen kann.','Alle Baujahre, insbesondere bei höherer Laufleistung.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1494,'hyundai-tucson-erste-generation','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, manchmal auch festsitzende Bremssättel.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1495,'hyundai-tucson-erste-generation','Klimaanlage','Probleme mit dem Klimakompressor oder Undichtigkeiten im System, die zu einem Ausfall der Kühlleistung führen.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1496,'hyundai-tucson-erste-generation','Elektronik','Gelegentliche Ausfälle von elektrischen Fensterhebern, Zentralverriegelung oder der Beleuchtung.','Alle Baujahre.','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1497,'hyundai-tucson-zweite-generation','Bremsanlage','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen, insbesondere an der Hinterachse. Festgehende Bremssättel sind ebenfalls bekannt.','2009-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1498,'hyundai-tucson-zweite-generation','Fahrwerk (Vorderachse)','Verschleiß an den Koppelstangen und Querlenkerlagern der Vorderachse kann zu Poltergeräuschen führen.','2009-2013','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1499,'hyundai-tucson-zweite-generation','Lenkung','Bei einigen Modellen kann es zu Geräuschen oder einem Spiel in der Lenkung kommen, oft verursacht durch ein defektes Lenkgetriebe oder die Lenksäule.','2009-2012','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1500,'hyundai-tucson-zweite-generation','Dieselpartikelfilter (DPF)','Bei Fahrzeugen mit Dieselmotor und überwiegendem Kurzstreckenbetrieb kann der DPF verstopfen, was zu Leistungsverlust und Notlauf führt.','2009-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1501,'hyundai-tucson-dritte-generation','Fahrwerk','Vereinzelt Berichte über vorzeitigen Verschleiß von Fahrwerkskomponenten wie Stoßdämpfern oder Querlenkern, insbesondere bei Fahrzeugen mit hoher Laufleistung oder häufigem Anhängerbetrieb.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1502,'hyundai-tucson-dritte-generation','Elektronik','Gelegentliche Fehlermeldungen oder Ausfälle von Infotainment-Systemen oder Assistenzsystemen, insbesondere bei frühen Modellen vor dem Facelift.','2015-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1503,'hyundai-tucson-dritte-generation','Kupplung (bei Schaltgetriebe)','Bei einigen Dieselmodellen wurde über einen erhöhten Verschleiß der Kupplung berichtet, was auf eine möglicherweise zu geringe Dimensionierung für das Drehmoment schließen lässt.','2015-2018 (Diesel)','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1504,'hyundai-santa-fe-erste-generation','Rost','Anfällig für Korrosion an Radläufen, Schwellern, Türen und dem Unterboden, besonders bei Fahrzeugen, die im Winterbetrieb eingesetzt wurden.','2000-2006','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1505,'hyundai-santa-fe-erste-generation','Dieselmotor (CRDi)','Probleme mit der Einspritzpumpe und den Injektoren, insbesondere bei frühen Modellen. Turbolader kann ebenfalls betroffen sein.','2001-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1506,'hyundai-santa-fe-erste-generation','Automatikgetriebe','Kann bei hoher Laufleistung ruckeln oder schalten.','2000-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1507,'hyundai-santa-fe-erste-generation','Fahrwerk','Verschleiß an Querlenkern und Stoßdämpfern.','2000-2006','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1508,'hyundai-santa-fe-zweite-generation','Fahrwerk (Vorderachse)','Verschleiß an Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Auch die Stoßdämpfer können frühzeitig verschleißen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1509,'hyundai-santa-fe-zweite-generation','Dieselmotoren (2.2 CRDi)','Probleme mit dem Dieselpartikelfilter (DPF) bei Kurzstreckenfahrten, was zu Verstopfungen und Leistungsverlust führen kann. Auch Injektoren können undicht werden oder verstopfen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1510,'hyundai-santa-fe-zweite-generation','Rost','Rostbildung kann an der Heckklappe (insbesondere im Bereich der Kennzeichenbeleuchtung), an den Radläufen und am Unterboden auftreten. Auch die Bremsleitungen sind betroffen.','Ältere Baujahre, insbesondere vor Facelift','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1511,'hyundai-santa-fe-zweite-generation','Klimaanlage','Undichtigkeiten im Klimasystem oder Defekte am Klimakompressor können zu einem Ausfall der Kühlfunktion führen.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1512,'hyundai-santa-fe-dritte-generation','Lenkung','Vereinzelt Berichte über Probleme mit der elektrischen Servolenkung, insbesondere bei älteren Modellen.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1513,'hyundai-santa-fe-dritte-generation','Kupplung (bei Schaltgetriebe)','Verschleißerscheinungen an der Kupplung bei hoher Laufleistung oder starker Beanspruchung.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1514,'hyundai-santa-fe-dritte-generation','Dieselpartikelfilter (DPF)','Verstopfung des DPF bei überwiegendem Kurzstreckenverkehr.','Alle (Diesel)','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1515,'hyundai-santa-fe-vierte-generation','Infotainmentsystem','Gelegentliche Berichte über Software-Probleme, Abstürze oder langsame Reaktionen des Infotainmentsystems, insbesondere bei frühen Baujahren vor dem Facelift.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1516,'hyundai-santa-fe-vierte-generation','Bremsen','Einige Nutzer berichten von erhöhtem Verschleiß der Bremsbeläge und -scheiben, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder sportlicher Fahrweise.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1517,'hyundai-santa-fe-vierte-generation','Dieselpartikelfilter (DPF)','Bei überwiegendem Kurzstreckenbetrieb kann es zu Problemen mit der Regeneration des Dieselpartikelfilters kommen, was zu Verstopfungen und Leistungsverlust führen kann.','Alle Dieselmodelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1518,'hyundai-ioniq-5-erste-generation','Ladeanschluss','Vereinzelt Berichte über Probleme mit dem Ladeanschluss, die zu Ladeabbrüchen oder Nicht-Laden führen können.','2021-2023','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1519,'hyundai-ioniq-5-erste-generation','Software','Gelegentliche Fehlermeldungen oder Verzögerungen im Infotainmentsystem und bei den Fahrerassistenzsystemen.','2021-2024','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1520,'hyundai-ioniq-5-erste-generation','Batteriemanagementsystem','Seltene Fälle von Problemen mit dem Batteriemanagementsystem, die zu Leistungsverlust oder Warnleuchten führen können.','2022-2023','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1521,'kia-picanto-ba','Rost','Anfällig für Rostbildung an Radläufen, Schwellern, Türen und der Auspuffanlage.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1522,'kia-picanto-ba','Fahrwerk','Verschleiß an Spurstangenköpfen, Querlenkern und Stoßdämpfern.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1523,'kia-picanto-ba','Lambdasonde','Defekte Lambdasonden führen zu erhöhtem Verbrauch und schlechterer Abgasqualität.','Gesamte Baureihe','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1524,'kia-picanto-ba','Klimaanlage','Ausfälle der Klimaanlage durch Lecks im System oder defekten Kompressor.','Gesamte Baureihe','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1525,'kia-picanto-ta','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Vorderachse. Auch festgerostete Bremssättel können vorkommen.','Alle Baujahre','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1526,'kia-picanto-ta','Fahrwerk (Achsen/Lenkung)','Verschleiß an den Spurstangenköpfen und Traggelenken kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Auch ausgeschlagene Stabilisatorlager sind bekannt.','Ab ca. 80.000 km Laufleistung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1527,'kia-picanto-ta','Beleuchtung','Defekte Glühlampen, insbesondere der Scheinwerfer, treten häufiger auf. Gelegentlich auch Feuchtigkeit in den Rückleuchten.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1528,'kia-picanto-ta','Auspuffanlage','Rostbildung am Endschalldämpfer und den Verbindungsrohren kann zu Undichtigkeiten führen.','Ältere Baujahre, insbesondere bei Kurzstreckenbetrieb','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1529,'kia-picanto-ja','Bremsen','Verschleiß an Bremsscheiben und -belägen, insbesondere bei häufiger Stadtfahrt.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1530,'kia-picanto-ja','Fahrwerk','Geräuschentwicklung an den Stoßdämpfern oder Fahrwerksbuchsen kann auftreten.','2017-2019','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1531,'kia-picanto-ja','Kupplung','Bei Schaltgetrieben kann die Kupplung bei hoher Laufleistung verschleißen.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1532,'kia-rio-dc','Rost','Der Kia Rio DC ist anfällig für Rost, insbesondere an den Radläufen, Schwellern, dem Unterboden und den Türunterkanten. Auch die Heckklappe des Kombis kann betroffen sein.','2000-2005','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1533,'kia-rio-dc','Bremsanlage','Überdurchschnittlicher Verschleiß an Bremsscheiben und -belägen. Auch festgerostete Bremssättel sind keine Seltenheit.','2000-2005','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1534,'kia-rio-dc','Auspuffanlage','Die Auspuffanlage neigt zu vorzeitigem Durchrosten, insbesondere der Endschalldämpfer.','2000-2005','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1535,'kia-rio-dc','Fahrwerk','Verschleiß an den Querlenkerlagern und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen.','2000-2005','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1536,'kia-rio-jb','Rost','An Radläufen, Schwellern, Türen und Heckklappe.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1537,'kia-rio-jb','Fahrwerk','Verschleiß an Stoßdämpfern und Querlenkern.','Alle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1538,'kia-rio-jb','Bremsen','Verschleiß von Bremsscheiben und -belägen.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1539,'kia-rio-ub','Bremsanlage','Überdurchschnittlicher Verschleiß der Bremsscheiben und -beläge, insbesondere an der Hinterachse. Auch festrostende Bremssättel können vorkommen.','2011-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1540,'kia-rio-ub','Fahrwerk','Verschleiß an den Achsgelenken und Spurstangenköpfen kann zu Poltergeräuschen und unpräzisem Fahrverhalten führen. Auch defekte Radlager sind keine Seltenheit.','2011-2017','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1541,'kia-rio-ub','Beleuchtung','Ausfall von Glühlampen, insbesondere der Rückleuchten, ist häufiger als bei anderen Modellen. Auch Feuchtigkeit in den Scheinwerfern kann auftreten.','2011-2017','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1542,'kia-rio-ub','Motor (1.4 CRDi Diesel)','Bei einigen Exemplaren des 1.4 CRDi Diesels gab es Berichte über Probleme mit der Steuerkette oder den Injektoren, was zu unrundem Motorlauf oder Leistungsverlust führen kann.','2011-2014','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1543,'kia-rio-yb','Bremsanlage','Vereinzelt Berichte über erhöhten Verschleiß der Bremsbeläge und Bremsscheiben, insbesondere bei Fahrzeugen mit hohem Stadtanteil.','Alle Baujahre','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1544,'kia-rio-yb','Infotainmentsystem','Gelegentliche Software-Probleme oder langsame Reaktionen des Infotainmentsystems, die meist durch Updates behoben werden können.','Frühe Baujahre (vor Facelift)','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1548,'kia-ceed-ed','Rost','An Radläufen, Schwellern, Türen (Unterkanten) und Heckklappe.','Alle, besonders anfällig vor dem Facelift','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1549,'kia-ceed-ed','Kupplung','Verschleißerscheinungen bei häufigem Stadtverkehr oder sportlicher Fahrweise.','Variabel, je nach Nutzung','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1550,'kia-ceed-ed','Fahrwerk','Verschleiß an Stoßdämpfern und Querlenkern, besonders bei Fahrzeugen mit hoher Laufleistung.','Alle, ab ca. 100.000 km','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1551,'kia-ceed-jd','Kupplung','Bei Modellen mit Schaltgetriebe kann es zu vorzeitigem Verschleiß der Kupplung kommen, insbesondere bei Fahrzeugen mit Anhängerbetrieb oder häufigem Stadtverkehr. Symptome sind Rutschen der Kupplung oder schwergängige Schaltvorgänge.','2012-2015','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1552,'kia-ceed-jd','Bremsen','Die Bremsanlage, insbesondere die Bremsscheiben und -beläge, können einen erhöhten Verschleiß aufweisen. Dies kann sich durch Rubbeln beim Bremsen oder frühzeitigen Austauschbedarf äußern.','Alle','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1553,'kia-ceed-jd','Fahrwerk (Vorderachse)','Vereinzelt wurden ausgeschlagene Spurstangenköpfe oder defekte Stabilisatorlager an der Vorderachse gemeldet, was zu Poltergeräuschen führen kann.','2012-2014','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1554,'kia-ceed-jd','Dieselpartikelfilter (DPF)','Bei Dieselfahrzeugen, die überwiegend im Kurzstreckenverkehr eingesetzt werden, kann es zu Problemen mit dem Dieselpartikelfilter kommen, da die notwendigen Regenerationsfahrten nicht ausreichend stattfinden.','Alle Dieselmodelle','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1555,'kia-ceed-cd','Infotainmentsystem','Gelegentliche Software-Probleme, träge Reaktion.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1556,'kia-ceed-cd','Kupplung (bei Schaltgetriebe)','Verschleißerscheinungen bei hoher Belastung oder früherer Austausch notwendig.','2018-2021','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1557,'kia-ceed-cd','Fahrwerk','Geräuschentwicklung an den Stoßdämpfern oder Fahrwerkskomponenten bei älteren Modellen.','2018-2020','gering');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1558,'kia-sportage-ja','Rost','Starke Rostbildung an Karosserie (Radläufe, Schweller, Heckklappe) und Rahmen, insbesondere bei älteren Modellen und Fahrzeugen, die im Winterbetrieb eingesetzt wurden.','Alle Baujahre, verstärkt bei Modellen vor dem Facelift.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1559,'kia-sportage-ja','Bremsanlage','Verschleiß an Bremsscheiben und -belägen, festgerostete Bremssättel und korrodierte Bremsleitungen.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1560,'kia-sportage-ja','Fahrwerk','Verschleiß an Querlenkerbuchsen, Spurstangenköpfen und Stoßdämpfern. Auch Federbrüche sind möglich.','Alle Baujahre, insbesondere bei hoher Laufleistung oder Offroad-Einsatz.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1561,'kia-sportage-ja','Motor (Benziner)','Probleme mit der Zylinderkopfdichtung, insbesondere bei Überhitzung. Auch Ölverlust und defekte Nockenwellensensoren können auftreten.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1562,'kia-sportage-ja','Motor (Diesel)','Der 2.2 Dieselmotor gilt als anfällig für Zylinderkopfschäden und Probleme mit der Einspritzanlage.','Alle Baujahre mit Dieselmotor.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1563,'kia-sportage-ja','Allradantrieb','Probleme mit der Freilaufnabe an der Vorderachse, die zu einem nicht funktionierenden Allradantrieb führen können.','Alle Baujahre.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1564,'kia-sportage-je','Rost','Korrosion an Radläufen, Schwellern, Achsteilen und Auspuffanlage.','Gesamte Baureihe, besonders anfällig bei Fahrzeugen mit geringer Pflege und im Winterbetrieb.','mittel');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1565,'kia-sportage-je','Turbolader (Diesel)','Defekte am Turbolader, oft durch mangelnde Wartung oder Überhitzung.','Insbesondere bei den Dieselmotoren mit höherer Laufleistung.','hoch');
INSERT INTO schwachstelle_baureihe (id,baureihe_id,bauteil,beschreibung,betroffene_baujahre,schweregrad) VALUES (1566,'kia-sportage-je','Klimaanlage','Ausfall der Klimaanlage, oft durch Lecks im System.','Gesamte Baureihe.','gering');
