INSERT INTO schwachstelle_motor (id,variante_id,bauteil,beschreibung,baujahre,kosten_ca) VALUES (98,'bmw-8er-g15-g14-g16-m850i-xdrive-coupe','Ventilschaftdichtungen','Bei früheren N63-Generationen bekannt, kann auch bei dieser Version zu erhöhtem Ölverbrauch führen. Verbesserungen wurden vorgenommen, aber ein Restrisiko bleibt.','2018-2020','Hoch (mehrere Tausend Euro)');
