INSERT INTO schwachstelle_motor (id,variante_id,bauteil,beschreibung,baujahre,kosten_ca) VALUES (100,'bmw-8er-g15-g14-g16-m8-competition-coupe','Bremsanlage','Extrem hoher Verschleiß von Bremsbelägen und -scheiben bei Rennstreckenbetrieb oder sehr sportlicher Fahrweise. Keramikbremsen sind optional und langlebiger, aber teuer.','Alle','Sehr hoch (mehrere Tausend Euro)');
INSERT INTO schwachstelle_motor (id,variante_id,bauteil,beschreibung,baujahre,kosten_ca) VALUES (101,'bmw-8er-g15-g14-g16-840d-xdrive-coupe','AGR-Kühler','Wie bei vielen modernen Dieselmotoren kann es zu Problemen mit dem AGR-Kühler kommen, die zu Undichtigkeiten oder Verstopfungen führen können.','2018-2020','Mittel (mehrere Hundert bis Tausend Euro)');
INSERT INTO schwachstelle_motor (id,variante_id,bauteil,beschreibung,baujahre,kosten_ca) VALUES (102,'bmw-x1-e84-sDrive18i','Valvetronic-Stellmotor','Kann zu unruhigem Motorlauf oder Leistungsverlust führen.','Alle','500-800 EUR');
