INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (15,'kritische_wartung',769,'b2017248dc6dde7baa6b3c41b17b22152a0c5041f2a7c85b694f5fe4148a084a','partially_verified','autodoc.de Technikangaben zum Audi A3 8P 2.0 FSI','C','https://www.autodoc.de/autoteile/steuerkette-10511/audi/a3/a3-sportback-8pa/18069-2-0-fsi',NULL,'2026-08-25','Der 2.0 FSI (EA113) besitzt tatsaechlich einen Zahnriemen — die Angabe ist also nicht falsch. Fuer das genannte Intervall von 120.000 km fehlt aber eine Hersteller- oder Serviceplan-Quelle (Stufe A). Nach §10 darf ein Eintrag erst dann als HERSTELLERINTERVALL bezeichnet werden, wenn genau das belegt ist; bis dahin bleibt er ein hinterlegter Wartungshinweis.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (4,'rueckruf',11,'6165aea8cdbbaf0e69203dc35415ccf520b6e13745db5859ffb6bb9bc26c1325','unverified','Recherche ohne Treffer: KBA-Rueckrufdatenbank (Bulk-Export HTTP 503, interaktive Suche captcha-gesichert), KBA-Presseachiv, autoservicepraxis.de, bimmertoday.de, autozeitung.de','B',NULL,NULL,'2026-08-27','KEIN Beleg fuer einen Bremskraftverstaerker-Rueckruf des G20/G21 im Maerz 2020. WICHTIG: die bisher hier hinterlegte Quelle (autoservicepraxis.de, Artikel 2514430) belegt eine voellig ANDERE Aktion — veroeffentlicht am 01.10.2013, Nockenwelle/Vakuumpumpe bei N20-Vierzylindern (125i, 320i, 328i, 520i, 528i, X1, X3, Z4), Produktion 06/2012 bis 08/2013, rund 6.800 Fahrzeuge in Deutschland. Andere Fahrzeuggeneration, anderes Bauteil, sieben Jahre frueher. Die frueher vergebene Einstufung ''partially_verified'' beruhte damit auf einer Fehlzitation und wird zurueckgenommen. Der Fakt bleibt sichtbar, traegt aber keine Vertrauensstufe. ''Nicht gefunden'' ist keine Widerlegung — deshalb ''unverified'' und nicht ''rejected''.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (5,'rueckruf',12,'04abe2bf197e625f440ad96470136b3c9cac1007b66e6869bfcf1035d033543d','unverified','Recherche ohne Treffer fuer das behauptete Fehlerbild: KBA-Rueckrufdatenbank (nicht abfragbar), bimmertoday.de, autozeitung.de, auto-motor-und-sport.de','B','https://www.bimmertoday.de/2020/08/14/ruckruf-fur-bmw-3er-z4-x3-m-x4-m-spurstange-kann-brechen/',NULL,'2026-08-27','Im selben Monat existiert ein realer, KBA-ueberwachter Lenkungs-Rueckruf fuer BMW 3er G20/G21, Z4 G29, X3 M F97 und X4 M F98: KBA-Referenz 010009, BMW-Massnahme 0032140300, Spurstange kann im Kerbbereich durch Materialermuedung brechen, Produktion 09/2018 bis 08/2019, 1.304 Fahrzeuge in Deutschland, 20.880 weltweit. Das ist ein ANDERES Fehlerbild als die in der Datenbank behaupteten ''mangelhaften Schweissnaehte an der Lenkung'' und ein anderer Bauzeitraum. Die Zeile wurde deshalb bewusst NICHT in diesen Rueckruf umgeschrieben: gleiches Teilsystem im gleichen Monat begruendet keine Identitaet. Die frueher hier vergebene Einstufung ''partially_verified'' mit dem Quellentext ''keine belastbare Quelle gefunden'' war in sich widerspruechlich und wird auf ''unverified'' korrigiert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (20,'rueckruf',13,'328c445a138d0696114b3be4b2ea64342fe5a8560ceb23fa10985be87914b23c','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','10176 (Herstellercode 0061540500, 0061560500)','2026-08-27','DIE AMTLICHE ENTSPRECHUNG ZUM NHTSA-DATENSATZ AUS DEM RECALL-PILOT. Im Pilot war der Hochvoltspeicher-Rueckruf nur ueber die US-Behoerde NHTSA (20V-601) belegbar, weil der KBA-Export damals durchgehend HTTP 503 lieferte; die Zeile trug deshalb bewusst keine KBA-Nummer. Der amtliche deutsche Datensatz 10176 beschreibt exakt denselben Mangel — Kurzschluss zweier Zellen im Hochvoltspeicher mit erhoehter Brandgefahr — mit Produktionszeitraum 2020, Herstellercodes 0061540500/0061560500, KBA-ueberwacht, und listet das Modell ''3''. Drei trennscharfe Begriffe gemeinsam (Hochvoltspeicher, Kurzschluss, Zellen). Der Bauzeitraum ''2020 (Plug-in-Hybrid)'' bleibt unveraendert: der Klammerzusatz haelt die Eingrenzung auf Plug-in-Hybride maschinenlesbar, die der amtliche Datensatz im Modellfeld nicht ausdruecken kann.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (31,'rueckruf',24,'af292ba9cd3a41387c9be10fcdd3191f8b2e47c208adf98a46571495032cb274','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','8124 (Herstellercode diverse Codes - siehe amtliche Abhilfemassnahme)','2026-08-27','Amtlich: Undichtigkeit am Abgasrueckfuehrungsmodul kann zum Fahrzeugbrand fuehren; der AGR-Kuehler wird geprueft und ggf. ersetzt. Produktion 2010-2022, KBA-ueberwacht, Modellliste enthaelt ''2''. Zwei trennscharfe Begriffe (Abgasrueckfuehrungsmodul, Kuehler). Die bisherige Referenz ''008064'' gehoert amtlich nicht hierher. Bauzeitraum auf die Schnittmenge mit dem F45 (2014-2021) gesetzt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (32,'rueckruf',93,'2c2a2a66de32b6914c8f1fef4b097b588b775d91fc03ba9283e63946c4401129','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','8124 (Herstellercode diverse Codes - siehe amtliche Abhilfemassnahme)','2026-08-27','Derselbe amtliche Rueckruf wie bei #24 — die Aktion 8124 umfasst zwoelf BMW-Baureihen, die Modellliste enthaelt ''1''. Das ist KEINE Dublette: zwei verschiedene VIRA-Baureihen sind von derselben herstellerweiten Aktion betroffen, und genau so bildet die Datenbank das ab (ein Rueckruf je Baureihe). Bauzeitraum auf die Schnittmenge mit dem F20/F21 gesetzt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (33,'rueckruf',114,'a35d78c5df008b734f258e33677bd0ee99be7968b3374982bfec3663d625358e','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','10589','2026-08-27','Amtlich: bei fehlender Netzabdeckung funktioniert der automatische Notruf wegen eines Softwarefehlers nicht; die Software des Kommunikationsmoduls wird aktualisiert. Produktion 2016-2020. Die vollstaendige amtliche Modellliste nennt B-KLASSE ausdruecklich (im gekuerzten Report war sie abgeschnitten — deshalb einzeln nachgeprueft). Zwei trennscharfe Begriffe (Kommunikationsmoduls, Softwarefehlers). Der bisherige VIRA-Bauzeitraum 2020-2021 ragte ueber das amtliche Fenster hinaus und wird auf die Schnittmenge mit dem W247 (ab 2019) korrigiert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (19,'rueckruf',121,'68159422fb858f86e5eff773c8e7ca01e3e12330fc05aec1ef9ee27e423540fd','unverified','Recherche ohne Treffer fuer das behauptete Fehlerbild: KBA-Rueckrufdatenbank (nicht abfragbar), Stiftung Warentest (test.de), autoservicepraxis.de, mbpassion.de','B',NULL,NULL,'2026-08-27','Kein Beleg fuer einen Rueckruf wegen fehlerhafter BEFESTIGUNG des Airbag-Steuergeraets an der C-Klasse W205. Belegt sind zwei ANDERE Airbag-Aktionen: (1) KBA-Referenz 6918, veroeffentlicht 21.03.2017, fehlerhafte CODIERUNG von Steuergeraeten, C-Klasse und weitere Baureihen der Baujahre 2003 bis 2016 — anderes Fehlerbild, weit groesserer Zuschnitt; (2) Sitzbelegungserkennung, veroeffentlicht 10.07.2015, Produktion 02.08.2013 bis 22.04.2014, eine nicht ordnungsgemaess montierte Steuereinheit der Sitzheizung stoert die Insassenerkennung — anderes Bauteil, anderer Zeitraum. Keine der beiden traegt die DB-Aussage; keine Umschreibung. Die frueher hier vergebene Einstufung ''partially_verified'' mit dem Quellentext ''keine belastbare Quelle gefunden'' war in sich widerspruechlich und wird auf ''unverified'' korrigiert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (28,'rueckruf',122,'37a1d2f4efac3806d4d68bc7da654506e7e8ac84d4a0e09198d2abecd3114890','unverified','Recherche ohne Treffer: autoservicepraxis.de, auto-motor-und-sport.de, mbpassion.de, rueckrufe.net','B',NULL,NULL,'2026-08-27','Kein Beleg fuer einen Rueckruf wegen Undichtigkeit im Bereich des Turboladers an der C-Klasse W205 (Mai 2018). Belegt sind fuer die Baureihe 205 andere Aktionen, unter anderem Kabelbaumschaeden im Lenkungssteuergeraet (Baureihen 205/253/293, Produktion Dezember 2019 bis Mai 2020, Mercedes-Code 5491022, rund 10.122 Fahrzeuge in Deutschland) — anderes Bauteil, anderer Zeitraum. Keine Widerlegung, nur kein Beleg.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (29,'rueckruf',123,'7d968625930d3240eac09d74c1c02d195d9f183b0747a75c3bab6724536d1ee5','partially_verified','autoservicepraxis.de und mbpassion.de zur Mercedes-Rueckrufaktion eCall-/Kommunikationsmodul','B','https://www.autoservicepraxis.de/rueckrufe/artikel/mercedes-benz-ecall-arbeitet-nicht-richtig-2513085',NULL,'2026-08-27','Das Rueckrufthema ist real und die C-Klasse (Baureihe 205) ist ausdruecklich betroffen: veroeffentlicht am 21.01.2019, Software des Kommunikationsmoduls fuer das eCall-Notrufsystem, Produktionszeitraum Maerz 2017 bis September 2018. Automatischer und manueller Notruf koennen ausfallen, wenn Mercedes-me-Dienste vor der Auslieferung im werksseitigen Transportmodus aktiviert wurden; Abhilfe ist ein Software-Update, das ueber die Mobilfunkverbindung eingespielt wird. Der Zuschnitt der DB-Zeile passt NICHT: sie datiert die Aktion auf Juli 2020 und nennt die Baujahre 2019-2020, also ausserhalb des belegten Produktionsfensters. Deshalb nur ''partially_verified'' — Thema belegt, Zeitraum nicht. Datum und Baujahre wurden bewusst NICHT umgeschrieben: es ist offen, ob die Zeile eine andere, spaetere eCall-Aktion meint (belegt ist zusaetzlich eine Aktion zur Dachbedieneinheit mit demselben Symptom). Fuer das Testfahrzeug (Baujahr 2016) ist die Zeile ohnehin nicht einschlaegig.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (34,'rueckruf',144,'3d373b8f3f8296beb8aeeeb247d09f50b4a47582371a3772f8dcc6edb08db1d3','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','7465','2026-08-27','Amtlich: Ausfall der elektrischen Lenkunterstuetzung, Abhilfe Erneuerung der elektrischen Servolenkung. Produktion 2016-2017, Modelle S-KLASSE und E-KLASSE. Zwei trennscharfe Begriffe. Der VIRA-Bauzeitraum 2017-2018 lag teilweise ausserhalb und wird auf das amtliche Fenster korrigiert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (35,'rueckruf',150,'d57aefda2f2f59e3779f3a53c1b476be957128ea00c364282507afa5e1ab4406','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','11075','2026-08-27','Amtlich: eingeschraenkte Funktion des Notrufsystems, Abhilfe Software-Update inklusive korrekter Konfiguration des Kommunikationsmoduls. Produktion 2020-2021, Modell S-KLASSE. Drei trennscharfe Begriffe. Die VIRA-Zeile trug dieselbe erfundene Referenz ''011603'' wie #114 — ein deutlicher Hinweis darauf, wie die Nummern entstanden sind.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (36,'rueckruf',196,'5d09b4edc8257ff21f08d2502830bba1b38af219ad14c92dee6fc3eba933702d','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','10589','2026-08-27','Derselbe amtliche eCall-Rueckruf wie #114; die Modellliste nennt CLA ausdruecklich. Bauzeitraum passt bereits, nur Datum und Referenz waren falsch.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (37,'rueckruf',221,'88b0b762c6e42fb6d1873302bd1d187ee5c84ad1ae70720f99cccacc0b028e0c','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','13692','2026-08-27','Amtlich: ''Lenkungssoftware'', Abhilfe Aktualisierung der Software der elektrischen Lenkung. Produktion 2017-2024, Modellliste enthaelt EQA. Zwei trennscharfe Begriffe. Bauzeitraum auf die Schnittmenge mit dem H243 erweitert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (38,'rueckruf',264,'d0a5fb410845cb098c76bdced853df144453659dfa6a50151d9c61eb0d677c21','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','6565','2026-08-27','Amtlich: fehlerhafte Programmierung des Airbag-Zentralsensors beeintraechtigt die Insassenschutzeinrichtungen; der Zentralsensor wird durch einen mit korrekter Software ersetzt. Produktion 2008-2012, Modelle ''7, 5''. Das deckt sich mit der VIRA-Aussage (Airbag-Steuergeraet, Fehlfunktion der Airbags) im Mechanismus — Programmierung/Software — und nicht nur im Bauteil. Bauzeitraum auf das amtliche Fenster verengt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (25,'rueckruf',282,'3e2f71c89313d855e6dc701e7ea56ca3f60fc71030bd684f8bd6ba3748b1a868','unverified','Recherche ohne Treffer: KBA-Rueckrufdatenbank (nicht abfragbar), rueden.de-Uebersicht Audi-Rueckrufe, autozeitung.de, auto-motor-und-sport.de, carwiki.de','B',NULL,NULL,'2026-08-27','Kein amtlicher oder herstellerseitiger Beleg fuer einen Rueckruf des A3 8P wegen Federbruchs im Bremspedal mit Ausfall der Bremsleuchten (September 2010). Die Zeile traegt keine KBA-Referenz und bleibt inhaltlich unveraendert. Keine Widerlegung, nur kein Beleg.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (26,'rueckruf',283,'5c29167d4a44021b76622dd2bf3a112e9c4c877809b343687d410715a735e7b6','unverified','Recherche ohne Treffer fuer das behauptete Fehlerbild: rueden.de-Uebersicht Audi-Rueckrufe (EA189), auto-motor-und-sport.de, autozeitung.de','B',NULL,NULL,'2026-08-27','Fuer den A3 8P ist der grosse, amtlich angeordnete Motorsteuergeraete-Rueckruf der EA189-Diesel belegt (1.6 und 2.0 TDI, Baujahre 2008 bis 2015, Herstellercode 23Q7). Er betrifft jedoch unzulaessige Abschalteinrichtungen im Abgasskandal, wurde ab 2015/2016 durchgefuehrt und hat als Fehlerbild NICHT ''unrunder Motorlauf oder Leistungsverlust''. Die DB-Zeile wird deshalb nicht in den EA189-Rueckruf umgeschrieben. UNABHAENGIG davon wurde ein Applicability-Fehler behoben: die Zeile grenzt sich im Text ausdruecklich auf den 2.0 TDI ein, wurde aber fuer das Testfahrzeug 2.0 FSI (Benziner) als moeglicherweise zutreffend angezeigt, weil der Antriebs-Abgleich in app/recall_filter.py nur einen Klammerzusatz auswertet und die Kuerzel ''TDI''/''TFSI'' nicht aufloest. Der ergaenzte Klammerzusatz macht die Einschraenkung maschinenlesbar.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (27,'rueckruf',284,'179b62e53f9524cfc9d2851be00250dcace594460d5829595a44530b7afce166','unverified','Recherche ohne Treffer: rueden.de-Uebersicht Audi-Rueckrufe, carwiki.de, gebrauchtwagenberater.de','B',NULL,NULL,'2026-08-27','Kein Beleg fuer einen Rueckruf des A3 8P wegen Risses im Ladeluftkuehler des 1.4 TFSI (Mai 2012). Wie bei Zeile 283 wurde nur die Applicability geschaerft: der Klammerzusatz ''(1.4 TFSI Benzin)'' verhindert, dass die Zeile bei Dieselfahrzeugen des 8P erscheint. Bekannte Grenze: eine Eingrenzung auf genau den 1.4-l-Motor ist mit der vorhandenen Semantik nicht moeglich.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (21,'rueckruf',543,'5b6ca5d4c8e9707b77a74489e85bb0b7ec13e56508eb4f83f27093b4ac4a3dd6','unverified','Recherche ohne Treffer: KBA-Presseachiv Abgasthematik, rueckrufe.net-Archiv Opel Insignia, auto-motor-und-sport.de, kfz-betrieb.vogel.de, heise autos','B',NULL,NULL,'2026-08-27','Kein amtlicher oder herstellerseitiger Beleg fuer einen Rueckruf des Insignia B wegen eines Softwarefehlers der elektrischen Servolenkung im Maerz 2018. Das durchsuchte Rueckruf-Archiv fuehrt fuer den Insignia in diesem Zeitraum andere Aktionen (Turbolader-Oelzulaufleitung 08/2018, Airbag-Fehlfunktion 04/2017), aber keine zur Servolenkung. Keine Widerlegung, nur kein Beleg.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (22,'rueckruf',544,'c782fb503ac842062b17a048673b7d4555f4b86ae0a4bef82b0a3ce27c67d3f5','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','10743 (Herstellercode E212103163 (21-C-097) O2D (alt: E212103161 (21-C-077)))','2026-08-27','BESTAETIGT DIE PILOT-KORREKTUR AMTLICH. Der Recall-Pilot hatte diese Zeile anhand eines Fachmediums von 2018-08/2017-2018 auf 2021-06/2021 korrigiert, konnte die KBA-Nummer aber nicht belegen und liess das Feld leer. Der amtliche Datensatz 10743 bestaetigt jetzt Bauzeitraum und Fehlerbild und liefert zusaetzlich den Herstellercode — inklusive des im Pilot notierten Vorgaengercodes E212103161 (21-C-077). Vier trennscharfe Begriffe. Nur das Datum wird noch um einen Monat auf die amtliche Veroeffentlichung korrigiert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (23,'rueckruf',545,'eec5c73b7f89c262c94daf3bed5312b078c5b30d0adf86d25b1609b45348f5e1','unverified','Recherche ohne Treffer: heise autos, rueckrufe.net-Archiv Opel Insignia, kfz-betrieb.vogel.de, auto-motor-und-sport.de','B','https://www.heise.de/news/Rueckruf-Opel-Insignia-Rost-an-der-hinteren-Spurstange-6360360.html',NULL,'2026-08-27','Kein Beleg fuer einen Rueckruf wegen Bruchs der hinteren Federbeine am Insignia B. Belegt ist eine ANDERE Fahrwerksaktion an der Hinterachse: Rost an der hinteren Spurstange, KBA-Referenz 011476, Opel-Code E202004350 (20-P-143) OYZ, rund 572.000 Fahrzeuge weltweit — anderes Bauteil, und nach Quellenlage der Insignia A. Keine Umschreibung, keine Uebernahme der fremden Referenz.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (7,'rueckruf',546,'15400cca645edd5eab55ecd37511736befce903a202f8bbf84a8db22d455a943','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','11422 (Herstellercode E222115640 (22-C-013) O7A)','2026-08-27','SCHLIESST DEN OFFENEN PUNKT AUS DEM SAFETY-CHECK. Diese Referenz war im Pilot auf ''partially_verified'' zurueckgestuft und die Nummer entfernt worden, weil sich trotz gezielter Suche keine KBA-Primaerquelle finden liess — nur uebereinstimmende Anwaltskanzlei-Seiten. Der jetzt erreichbare amtliche Export bestaetigt jede damals berichtete Angabe: Referenz 11422, Herstellercode E222115640 (22-C-013) O7A, veroeffentlicht 2022-02-17, Produktion 2013-2018, KBA-ueberwacht, und im Feld ''Moegliche Eingrenzung der betroffenen Modelle'' woertlich ''1,3 l und 1,6 l Dieselmotor Euro 6 mit AGR + NSK (LNT)''. Der im Pilot gesetzte Bauzeitraum ''2017-2018 (1,6 l Diesel Euro 6)'' bleibt deshalb unveraendert — er ist die Schnittmenge des amtlichen Fensters mit dem Insignia B und die amtliche Motoreingrenzung, maschinenlesbar gehalten.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (24,'rueckruf',547,'e93b5f7701a2a6c661d67869612c037a5827f552d74855c66340b23b022b806e','unverified','Recherche ohne Treffer: rueckrufe.net-Archiv Opel Insignia, kfz-betrieb.vogel.de, auto-motor-und-sport.de','B',NULL,NULL,'2026-08-27','Kein Beleg fuer einen Rueckruf wegen Kurzschlusses im Heizsystem der Vordersitze am Insignia B. Belegt ist eine andere Kurzschlussaktion: Wassereintritt in das Schaltrelais der Heckklappensteuerung, 3.548 Fahrzeuge der Modelljahre 2009 bis 2012 — Insignia A, anderes Bauteil, anderer Zeitraum. Keine Umschreibung.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (39,'rueckruf',676,'614e3ee83076f33e73972e63d2a656868060c19a1cacacc45fba1d089dd28ff7','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','4191','2026-08-27','Amtlich: wegen eines Steuergeraetefehlers loesen die Seiten-Airbags nicht korrekt aus; Abhilfe ist die Parametrierung der Airbagsteuergeraete. Produktion 2013, Modell CITIGO. Mechanismus (Steuergeraet/Parametrierung) und Wirkung (Airbags loesen nicht korrekt aus) decken sich mit der VIRA-Aussage. Bauzeitraum auf das amtliche Jahr verengt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (40,'rueckruf',739,'f043a0e213823906f8dc3f016200fa61159fa6e0d83855426e829536714141b7','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','2811','2026-08-27','Amtlich: bei leichtem Abbremsen auf glatter oder holpriger Fahrbahn kann sich der Bremsweg verlaengern; das ABS-Steuergeraet erhaelt eine neue Software. Produktion 2009-2010, Modell PRIUS, Veroeffentlichung 2010-02-17. Das ist der bekannte Prius-Bremsenrueckruf. Der VIRA-Bauzeitraum 2003-2009 war viel zu weit und wird auf die Schnittmenge mit dem amtlichen Fenster verengt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (41,'rueckruf',779,'18a15fd884822079601b47bde202ce8977d481bfa4075a9101769fff9a282f1f','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','9873','2026-08-27','Amtlich: Eintritt von Schmutz und Feuchtigkeit kann im ABS-Modul einen Kurzschluss ausloesen, in der Folge droht Brand; Abhilfe ist der Einbau eines Relais-Kits. Produktion 2005-2009, Modell SANTA FE. Drei trennscharfe Begriffe. Das VIRA-Datum lag zehn Jahre daneben.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (30,'rueckruf',808,'d6f73ecef82e3852f25dae600ff98e97177be6b8ef04cd388c00a09633e9c78b','verified','KBA-Rueckrufdatenbank, amtlicher Gesamtexport (7.816 Rueckrufe), abgerufen 2026-08-27','A','https://www.kba-online.de/rrdb/buerger/api/rueckruf/export?format=csv&type=cars','12223 (Herstellercode KBT)','2026-08-27','Bereits im Insignia-Nachtrag Feld fuer Feld aus derselben amtlichen Quelle uebernommen und dort verifiziert. Der Gesamtabgleich bestaetigt ihn als einzigen EXACT_OFFICIAL_MATCH des ganzen Bestands: als einzige der 570 VIRA-Referenzen ist 12223 amtlich gueltig fuer ihr Fahrzeug UND beschreibt denselben Mangel. Hier steht er nur der Vollstaendigkeit halber; inhaltlich aendert sich nichts.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (1,'schwachstelle_baureihe',14,'1a3282912f8d8ebe0c7e83d587113a58f3665e6fb5d745f41085ffb341143441','verified','AUTO BILD TUEV-Check BMW 3er/4er; gebrauchtwagenberater.de (G20/G21)','B','https://www.autobild.de/artikel/bmw-3er-4er-im-tuev-check-2026--28158815.html',NULL,'2026-08-25','Software-/Infotainment-Schwaeche der fruehen G20 bestaetigt: iDrive 7 gilt bis Modelljahr 2022 als fehleranfaellig, erst das LCI mit iDrive 8 als stabil. Der DB-Baujahresbereich 2019-2020 liegt vollstaendig innerhalb des belegten Zeitfensters, und die DB-Formulierung (''vereinzelt'', ''meist durch Updates behoben'') geht nicht ueber die Quelle hinaus.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (2,'schwachstelle_baureihe',15,'5cf8beee767053e4df82aa439f0db18e5b33dcd586401db9ce6495003d3f328b','rejected','AUTO BILD TUEV-Check BMW 3er/4er (TUEV-Report-Auswertung)','B','https://www.autobild.de/artikel/bmw-3er-4er-im-tuev-check-2026--28158815.html',NULL,'2026-08-25','WIDERSPRUCH: Die DB behauptet ueberdurchschnittlichen Bremsenverschleiss als Baureihen-Schwachstelle. Die TUEV-Auswertung stellt fuer den G20 das Gegenteil fest — Bremsscheiben aller drei Generationen zeigen relativ wenig Verschleiss, die Fussbremsfunktion ist beanstandungsfrei, Bremsleitungen und -schlaeuche sind unauffaellig. Bleibt als Hinweis erhalten, aber ohne Vertrauensstufe; eine Datenkorrektur waere Sache der Cleanup-Migration.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (3,'schwachstelle_baureihe',16,'cd02650707180d64bf4f9aa1687a715febbe4747f01b97c448ebd59897f697b3','partially_verified','AUTO BILD TUEV-Check BMW 3er/4er; gebrauchtwagenberater.de (G20/G21)','B','https://www.autobild.de/artikel/bmw-3er-4er-im-tuev-check-2026--28158815.html',NULL,'2026-08-25','Klapper-/Knarzgeraeusche sind fuer den G20 belegt — aber am FAHRWERK (auffaellig ab ca. 80.000 km, 400-900 EUR), nicht im Innenraum. Fuer Armaturenbrett und Tuerverkleidungen liess sich keine Quelle finden. Thema plausibel, Bauteil-zuordnung der DB nicht belegt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (16,'schwachstelle_baureihe',233,'b854d3f3f1ea437fa98b9b7ded074b5987168dc69aa17854e0cf33f71a40ce8c','partially_verified','att24.de (9G-Tronic 725.0); gebrauchtwagenberater.de W205; kfz-dietrich.com','C','https://gebrauchtwagenberater.de/mercedes-c-klasse-w205-s205-probleme/',NULL,'2026-08-25','Fuer die 9G-TRONIC (725.0) sind Schaltrucke in fruehen Exemplaren gut belegt, besonders im Stadtverkehr zwischen 20 und 40 km/h, ebenso die Empfehlung eines Getriebeoelwechsels alle 60.000 km trotz ''Lifetime''-Angabe — das deckt die DB-Aussage inklusive ''insbesondere bei mangelnder Wartung''. Die DB nennt zusaetzlich die 7G-TRONIC PLUS, fuer die keine entsprechende Quelle gefunden wurde. Deshalb nur teilweise verifiziert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (17,'schwachstelle_baureihe',234,'6954d8612770357c5fafc61361b3b554eb03d99cc0aeda709e83fc0d482f3b6d','verified','gebrauchtwagenberater.de W205; kfz-dietrich.com (XENTRY-Diagnose W205); autodoc.de','C','https://gebrauchtwagenberater.de/mercedes-c-klasse-w205-s205-probleme/',NULL,'2026-08-25','Von drei unabhaengigen Fachquellen uebereinstimmend beschrieben: COMAND kann einfrieren bzw. Software-/Anzeigefehler zeigen, meist durch Software-Update dauerhaft behebbar. Die DB-Aussage (''gelegentliche Software-Probleme, Abstuerze oder Aussetzer des Displays'', Schweregrad gering) entspricht dem genau und behauptet nicht mehr.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (18,'schwachstelle_baureihe',235,'70f8cb3f1d6dc589b3bde32eb8f8dbaf99c13de0cc76788521c46135ec4d839c','partially_verified','gebrauchtwagenberater.de W205; autodoc.de Technikblog W205','C','https://gebrauchtwagenberater.de/mercedes-c-klasse-w205-s205-probleme/',NULL,'2026-08-25','Kuehlmittelverlust am W205 ist belegt — als Ursache nennen die Quellen jedoch undichte WASSERPUMPEN ab etwa 80.000-120.000 km, waehrend die DB Kuehler und Schlaeuche nennt. Fehlerbild bestaetigt, Bauteilzuordnung nicht.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (8,'schwachstelle_baureihe',543,'865becdcaf6b535c3015c0e2ad65d0b037793e3dc8aa2855a4cc3f7c536ef3fc','partially_verified','KBA (Druckminderer/ZMS-Aktion) via carwiki.de; autozeitung.de Kaufberatung A3 8P','B','https://carwiki.de/audi-a3-probleme',NULL,'2026-08-25','Vorzeitiger ZMS-Verschleiss am A3 8P ist belegt, die dokumentierte KBA-Aktion zu einem falsch ausgelegten Druckminderer betrifft jedoch die Baujahre 2003-2005. Die DB spannt den Bereich auf ''Alle Baujahre'' auf und geht damit ueber die Quellenlage hinaus. Fuer den 2.0 FSI mit 150 PS ist die Einordnung ''leistungsstaerkere Benziner'' zudem grenzwertig.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (9,'schwachstelle_baureihe',544,'aaef4cda2d01ad42c3360b5ed998a1e69d6db82678dc42a95a71077e4e63ac81','partially_verified','carwiki.de (A3-Motorenuebersicht EA111); autodoc.de Technikblog A3','B','https://carwiki.de/audi-a3-probleme',NULL,'2026-08-25','Die Steuerkettenproblematik ist belegt — aber fuer die EA111-Benziner (1.2 TSI, 1.4 TSI, 1.6 FSI, 1.8 TFSI) der Baujahre 2007-2013. Die DB nennt stattdessen ''1.4 TFSI, 1.8 TFSI, 2.0 TFSI'': der 2.0 TFSI (EA113) gehoert nicht zu dieser Familie, der betroffene 1.6 FSI fehlt. Motorliste teilweise falsch, Kernaussage richtig.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (10,'schwachstelle_baureihe',545,'ec81d4eefe81799037bb87228dc08805a4ce7de1b1387b0ba12f1814ad8a9544','verified','gebrauchtwagenberater.de (A3 8P); autozeitung.de Kaufberatung; autodoc.de','C','https://gebrauchtwagenberater.de/audi-a3-8p-schwachstellen-kaufberatung/',NULL,'2026-08-25','Von drei unabhaengigen Fachquellen uebereinstimmend beschrieben: Anfahr-schwaechen und unwillige Gangwechsel am DSG/S tronic, mit ausdruecklichem Hinweis auf den turnusmaessigen Getriebeoelwechsel laut Serviceplan. Das deckt die DB-Aussage (Mechatronik/Kupplungen, Schaltprobleme, Ruckeln, ''insbesondere bei mangelnder Wartung'') vollstaendig ab, ohne dass die DB darueber hinausgeht.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (11,'schwachstelle_baureihe',547,'612dfe45cc54b96da48a87011362f79cb96caaa41ed7065c24324f13c37a2a36','partially_verified','AUTO BILD TUEV-Check Audi A3; autozeitung.de Kaufberatung A3 8P','B','https://www.autobild.de/artikel/audi-a3-im-tuev-check-2026--28123347.html',NULL,'2026-08-25','Keine der ausgewerteten Quellen nennt Fensterheber als typische A3-8P-Schwaeche; die TUEV-Auswertung stellt den A3 insgesamt unter den Maengeldurchschnitt und hebt stattdessen Fahrwerk (gebrochene Federn, undichte Stossdaempfer) und Bremsanlage hervor. Kein Widerspruch, aber auch kein Beleg.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (12,'schwachstelle_baureihe',548,'32bc93db6744fb3929b5869c69c9d029f2f99673c8b7ee38babfa7ce2c622981','partially_verified','AUTO BILD TUEV-Check Audi A3; autoscout24.de Kaufberatung A3 8P','B','https://www.autobild.de/artikel/audi-a3-im-tuev-check-2026--28123347.html',NULL,'2026-08-25','Rost an Heckklappe/Kotfluegeln wird in den ausgewerteten Quellen nicht als typische Schwaeche des A3 8P gefuehrt. Die DB-Formulierung ist bereits vorsichtig (''vereinzelt''), bleibt aber unbelegt.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (6,'schwachstelle_baureihe',1007,'8c78983c25b8fedc6b7d209b38258a7c16853244a184b6d9a7c65fda284be395','partially_verified','KBA-Rueckrufanordnung Opel Diesel (Astra/Corsa/Insignia)','A','https://www.kba.de/DE/Presse/Archiv/Abgasthematik/opel_inhalt.html','011422','2026-08-25','Die Abgas-/NOx-Thematik bei Opel-Dieselmotoren ist amtlich belegt (KBA-Rueckrufanordnung, Referenz 011422, Herstellercode E222115640 / 22-C-013). Die DB-Zeile mischt jedoch mehrere Aussagen in einem Satz: AdBlue-System, NOx-Sensoren, erhoehter Oelverbrauch UND Steuerkette. Belegt ist davon nur der Abgas-/Softwareteil; fuer Oelverbrauch und Steuerkette am 2.0 CDTI wurde keine Quelle gefunden. Deshalb nur teilweise verifiziert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (13,'schwachstelle_motor',1289,'cab1ee3fda6d03650d8e47d21f00c9ab487d03911a227422afe369d5167e0f22','partially_verified','autodoc.de Teilekatalog (Steuerkette Audi A3 8P 2.0 FSI 150 PS); EOS-Forum und MOTOR-TALK Reparaturberichte zu AXW/BLR','C','https://www.autodoc.de/autoteile/steuerkette-10511/audi/a3/a3-sportback-8pa/18069-2-0-fsi',NULL,'2026-08-25','Fehlerbild bestaetigt: Kettenlaengung und Verschleiss am Nockenwellenversteller, Rasseln beim Start bzw. bis ca. 2.000/min, typischerweise ab rund 150.000 km; die Motorcodes AXW und BLR werden dabei ausdruecklich genannt. Es fehlt allerdings eine Quelle der Stufe A oder B (Hersteller, ADAC, TUEV) zur Haeufigkeit — ein Teilekatalog belegt die Existenz des Bauteils, nicht die Ausfallrate. Deshalb bewusst nur teilweise verifiziert.');
INSERT INTO fakt_verifikation (id,fakt_art,fakt_id,fingerprint,status,quelle,quelle_stufe,url,referenz,geprueft_am,notiz) VALUES (14,'schwachstelle_motor',1290,'41962b338bd6fd6ffeb9eb31d8ee8e4e437150f79a59a7860596695d01ad7131','partially_verified','keine belastbare Einzelquelle fuer diese Motorisierung gefunden','C',NULL,NULL,'2026-08-25','Verkokung an Einlassventilen/Einspritzung ist bei Direkteinspritzern allgemein bekannt, es liess sich jedoch keine Quelle finden, die das speziell fuer den 2.0 FSI (AXW/BLR) belegt. Bleibt als Pruefhinweis erhalten, ohne Vertrauensstufe.');
